42: impl HeldAttack {
43:     fn observed(
44:         mut self,
45:         mouse: &ButtonInput<MouseButton>,
46:         button: MouseButton,
47:         elapsed: AnimationElapsed,
48:     ) -> AnimationValueResult<Self> {
49:         if mouse.pressed(MouseButton::Right) && mouse.just_pressed(button) {
50:             self.armed = true;
51:             self.elapsed = AnimationElapsed::ZERO;
52:         }
53:         if self.armed && mouse.pressed(button) {
