83:                 MeleePreparationInput::Preferred
84:             } else {
85:                 MeleePreparationInput::Alternate
86:             };
87:         let preparation = if offhand.armed && observation.mouse.pressed(MouseButton::Middle) {
88:             MeleePreparation::held(&offhand, MeleePreparationInput::Offhand, config)?
89:         } else if main.armed && observation.mouse.pressed(MouseButton::Left) {
90:             MeleePreparation::held(&main, MeleePreparationInput::Alternate, config)?
91:         } else {
92:             let selected = if observation.left_trigger {
93:                 controller_preparation
94:             } else {
95:                 MeleePreparationInput::Preferred
96:             };
97:             MeleePreparation {
98:                 from: selected,
99:                 to: selected,
100:                 progress: UnitInterval::ONE,
101:                 selected,
102:             }
103:         };
104:         Ok(PreparedAttackInput {
105:             main,
106:             offhand,
107:             main_released,
108:             offhand_released,
109:             requested: main_released
110:                 || offhand_released
111:                 || observation.controller_attack
112:                 || observation.forced_attack,
113:             alternate: mouse_alternate
114:                 || (observation.controller_attack
115:                     && observation.left_trigger_value < config.aim_trigger_threshold),
116:             hand: if offhand_released {
117:                 AttackHand::Offhand
118:             } else {
119:                 AttackHand::Main
120:             },
121:             preparation,
122:         })
