1: //! Bounded comparison of terrain sources at unchanged production building IDs.
2: use adventuresim_building_generator::{compile_ground_entrances, generate};
3: use adventuresim_tactical_core::{
4:     city_layout::grounding::{GeographicSurface, SupportElevation},
5:     prelude::*,
6:     scene_input::GeneratedBuildingRecipes,
7: };
8: use bevy::math::{Vec2, Vec3Swizzles};
9: use clap::Parser;
10: use serde::Deserialize;
11: use serde_json::{Value, json};
12: use std::path::PathBuf;
13: #[path = "compare_city_terrain/capture.rs"]
14: mod capture;
15: #[path = "compare_city_terrain/capture_export.rs"]
16: mod capture_export;
17: #[path = "compare_city_terrain/contacts.rs"]
18: mod contacts;
19: #[path = "compare_city_terrain/gardens.rs"]
20: mod gardens;
21: use capture::{PreparedTerrainCapture, TerrainPreparationPurpose};
22: 
23: #[derive(Parser)]
24: struct Request {
25:     #[arg(long)]
26:     scene_input: PathBuf,
27:     #[arg(long)]
28:     terrain_stages: PathBuf,
29:     #[arg(long)]
30:     output: PathBuf,
31:     /// Save fine terrain prepared with complete production scene context.
32:     #[arg(long)]
33:     prepared_terrain_output: Option<PathBuf>,
34:     /// Save exact physical triangles for bounded footprint/collision inspection.
35:     #[arg(long)]
36:     physical_surface_output: Option<PathBuf>,
37:     /// Materialize production colliders and probe exact bearing vertices.
38:     #[arg(long)]
39:     collision_probes: bool,
40:     /// Restrict expensive triangle comparisons to these exact identities.
41:     #[arg(long, value_delimiter = ',')]
42:     building_id: Vec<u64>,
43: }
44: 
45: #[derive(Deserialize)]
46: struct TerrainStages {
47:     input_digest: String,
48:     source_digest: adventuresim_world_schema::source_package::SourcePackageDigest,
49:     ungraded_vista: adventuresim_tactical_core::scene_input::VistaSample,
50: }
51: 
52: fn main() -> Result<(), Box<dyn std::error::Error>> {
53:     let request = Request::parse();
54:     let input = TacticalSceneInput::load(&request.scene_input)?;
55:     let stages: TerrainStages = serde_json::from_slice(&std::fs::read(&request.terrain_stages)?)?;
56:     if input.digest()? != stages.input_digest
57:         || input.source != SceneSource::ImportedPackage(stages.source_digest.clone())
58:     {
59:         return Err("stage provenance differs from the frozen production input".into());
60:     }
61:     let lod = stages
62:         .ungraded_vista
63:         .lods
64:         .iter()
65:         .find(|lod| lod.level == adventuresim_tactical_core::scene_input::VistaLevelIndex::new(0))
66:         .ok_or("near source vista is absent")?;
67:     let vista = GeographicSurface::from_vista_lod(lod).ok_or("invalid near vista")?;
68:     let raw = SceneTerrain::from_heightmap(
69:         usize::from(input.playable.width),
70:         usize::from(input.playable.depth),
71:         input.playable.spacing_metres,
72:         input.playable.heights_metres.clone(),
73:     )
74:     .ok_or("invalid production playable grid")?;
75:     let raw_surface = raw
76:         .sampled_geographic_surface()
77:         .ok_or("raw terrain is not sampled")?;
78:     let graded = input.generate_unfurnished(GeneratedBuildingRecipes::default())?;
79:     let graded_surface = graded
80:         .terrain
81:         .physical_geographic_surface()
82:         .ok_or("production terrain lacks physical support")?;
83: 
84:     let natural = input.prepare_geographic_terrain(&mut GeneratedBuildingRecipes::default())?;
85:     let natural_surface = natural
86:         .terrain
87:         .sampled_geographic_surface()
88:         .ok_or("complete-context terrain is not sampled")?;
89:     if let Some(path) = &request.physical_surface_output {
90:         std::fs::write(
91:             path,
92:             serde_json::to_vec(&graded_surface.triangles().collect::<Vec<_>>())?,
93:         )?;
94:     }
95:     let sources = [
96:         StageSource {
97:             role: TerrainStageRole::UngradedNearVista,
98:             surface: &vista,
99:         },
100:         StageSource {
101:             role: TerrainStageRole::RawPlayable,
102:             surface: &raw_surface,
103:         },
104:         StageSource {
105:             role: TerrainStageRole::PreparedFinePlayable,
106:             surface: &natural_surface,
107:         },
108:         StageSource {
109:             role: TerrainStageRole::BoundedSupport,
110:             surface: &graded_surface,
111:         },
112:     ];
113:     let enclosures = contacts::measure_enclosures(&input, &graded.terrain)?;
114:     let contacts = request
115:         .collision_probes
116:         .then(|| contacts::CornerSupportProbe::new(&graded.terrain))
117:         .transpose()?;
118:     let buildings = request.selected_building_reports(&input, &sources, contacts.as_ref())?;
119:     let presented =
120:         GeographicSurface::from_presented_scene(&natural.terrain, &stages.ungraded_vista)
121:             .ok_or("complete source presentation is invalid")?;
122:     let garden_measurements = gardens::measure(&input, &presented, &graded.terrain)?;
123:     let report: Value = json!({"input_digest":stages.input_digest,"source_digest":stages.source_digest,
124:         "seed":input.seed,"absolute_minute":input.absolute_minute,"schema":input.schema_version,
125:         "generation":input.generation_version,"vista_spacing_metres":lod.spacing_metres,

126:         "raw_playable_spacing_metres":raw.grid_scale(),
127:         "prepared_playable_spacing_metres":natural.terrain.grid_scale(),
128:         "current_production_repairs":graded.repairs,"geographic_preparation_repairs":natural.repairs,
129:         "scope":"Complete production context prepares geographic terrain before grading. Input, source identity, buildings, property reservations, gardens, streets and yards are retained. The physical surface is reconstructed by production generate_unfurnished. These measurements do not certify complete access, collision or renderer acceptance. Comparison coverage is explicit; partial footprints are not accepted.",
130:         "buildings":buildings,"gardens":garden_measurements,"enclosures":enclosures});
131:     std::fs::write(request.output, serde_json::to_vec_pretty(&report)?)?;
132:     if let Some(path) = request.prepared_terrain_output {
133:         let capture = PreparedTerrainCapture {
134:             purpose: TerrainPreparationPurpose::CompleteSceneContext,
135:             input_digest: input.digest()?,
136:             source_digest: stages.source_digest,
137:             terrain: natural.terrain,
138:         };
139:         capture.write_with_metadata(&path, &input, &stages.ungraded_vista)?;
140:     }
141:     Ok(())
142: }
