144: fn inspect_building(
145:     input: &TacticalSceneInput,
146:     placement: &adventuresim_tactical_core::scene_input::TacticalBuildingPlacement,
147:     sources: &[StageSource<'_>; 4],
148:     contacts: Option<&contacts::CornerSupportProbe>,
149: ) -> Result<Value, Box<dyn std::error::Error>> {
150:     let plan = generate(&placement.program)?;
151:     let collision = adventuresim_building_generator::compile_building_collision(&plan)?;
152:     let footprint = collision
153:         .ground_floor_footprint()?
154:         .ok_or("missing actual floor contact")?;
155:     let origin = collision.bounds.centre()?.metres().xz();
156:     let project = |p: Vec2| {
157:         placement.centre_metres.metres() + placement.orientation.local_to_world(p - origin)
158:     };
159:     let projection =
160:         adventuresim_tactical_core::scene_coordinates::ArchitecturalPlanProjection::from_placement(
161:             placement,
162:             collision.bounds,
163:         )?;
164:     let scene_outline =
165:         adventuresim_tactical_core::scene_coordinates::ScenePlanPolygon::from_architectural(
166:             footprint.polygon(),
167:             projection,
168:         )?;
169:     let outline: Vec<_> = scene_outline
170:         .vertices()
171:         .iter()
172:         .map(|point| point.metres())
173:         .collect();
174:     let thresholds: Vec<_> = compile_ground_entrances(&plan)?.into_iter().map(|entry| {
175:             let position = adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(project(entry.threshold_metres.metres()))?;
176:             Ok(json!({"entrance": entry.id, "support":entry.support, "position_metres":position,
177:                 "elevations":sources.iter().map(|source| (source.role.output_name(), source.surface.elevation_at(position)
178:                     .map(SupportElevation::metres))).collect::<std::collections::BTreeMap<_,_>>()}))
179:         }).collect::<Result<Vec<_>, adventuresim_building_generator::spatial_geometry::GeometryError>>()?;
180:     let ranges: Vec<_> = sources
181:         .iter()
182:         .map(|source| {
183:             let range = source.surface.height_range_in_outline(&scene_outline);
184:             json!({"source":source.role.output_name(),"minimum":range.map(|r|(r.minimum.point.metres(),r.minimum.elevation.metres())),
185:                 "maximum":range.map(|r|(r.maximum.point.metres(),r.maximum.elevation.metres()))})
186:         })
187:         .collect();
188:     let comparisons: Vec<_> = [
189:         StageComparison {
190:             first: TerrainStageRole::UngradedNearVista,
191:             second: TerrainStageRole::RawPlayable,
192:         },
193:         StageComparison {
194:             first: TerrainStageRole::UngradedNearVista,
195:             second: TerrainStageRole::PreparedFinePlayable,
196:         },
197:         StageComparison {
198:             first: TerrainStageRole::RawPlayable,
199:             second: TerrainStageRole::PreparedFinePlayable,
200:         },
201:         StageComparison {
202:             first: TerrainStageRole::PreparedFinePlayable,
203:             second: TerrainStageRole::BoundedSupport,
204:         },
205:     ]
206:     .into_iter()
207:     .map(|comparison| {
208:         let first = comparison.first.source(sources);
209:         let second = comparison.second.source(sources);
210:         json!({"first":comparison.first.output_name(), "second":comparison.second.output_name(),
211:             "complete_triangle_overlay":first.compare_in_outline(second, &scene_outline)})
212:     })
213:     .collect();
214:     let floor = placement.base_elevation_metres;
215:     let corner_support = contacts
216:         .map(|probe| probe.measure(&scene_outline, floor))
217:         .transpose()?;
218:     Ok(json!({"building_id":placement.id,
219:             "property_id":input.properties.as_ref().and_then(|catalog|catalog.homes.iter()
220:                 .find(|home|home.building_id==placement.id.0).map(|home|&home.id)),
221:             "placement":placement,"actual_bearing_outline_metres":outline,
222:             "ranges":ranges,"comparisons":comparisons,"thresholds":thresholds,
223:             "corner_support":corner_support}))
224: }
