1: //! Collision contact and height queries are different observations at cut edges.
2: use super::*;
3: use adventuresim_tactical_core::avian3d;
4: use adventuresim_tactical_core::city_layout::CompoundGradingPolicy;
5: use bevy::math::{Quat, Vec3};
6: 
7: use adventuresim_tactical_core::city_layout::grounding::SupportElevation;
8: use adventuresim_tactical_core::scene_coordinates::{ScenePlanPoint, ScenePlanPolygon};
9: 
10: #[derive(Debug, thiserror::Error)]
11: pub(super) enum CornerProbeError {
12:     #[error(transparent)]
13:     Geometry(#[from] adventuresim_building_generator::spatial_geometry::GeometryError),
14:     #[error("no physical support collider at {point:?}")]
15:     MissingSupport { point: ScenePlanPoint },
16:     #[error("unsupported collider pair at {point:?}")]
17:     UnsupportedShapeCast { point: ScenePlanPoint },
18: }
19: 
20: const RAY_START_CONTACT_BOUNDS: f32 = 2.0;
21: const RAY_RANGE_CONTACT_BOUNDS: f32 = 3.0;
22: 
23: pub(super) struct CornerSupportProbe<'a> {
24:     terrain: &'a SceneTerrain,
25:     colliders: Vec<Collider>,
26:     contact_bound_metres: f32,
27: }
28: 
29: impl<'a> CornerSupportProbe<'a> {
30:     pub(super) fn new(
31:         terrain: &'a SceneTerrain,
32:     ) -> Result<Self, adventuresim_tactical_core::city_layout::grounding::SupportColliderError>
33:     {
34:         Ok(Self {
35:             terrain,
36:             colliders: terrain.colliders()?,
37:             contact_bound_metres: CompoundGradingPolicy::bounded_settlement()
38:                 .limits
39:                 .contact_tolerance_metres(),
40:         })
41:     }
42: 
43:     pub(super) fn measure(
44:         &self,
45:         outline: &ScenePlanPolygon,
46:         floor: SupportElevation,
47:     ) -> Result<Value, CornerProbeError> {
48:         let floor = floor.metres();
49:         let probes = outline.vertices().iter().map(|scene_point| {
50:             let point = scene_point.metres();
51:             let bearing = Vec3::new(point.x, floor, point.y);
52:             let start = bearing + Vec3::Y * (self.contact_bound_metres * RAY_START_CONTACT_BOUNDS);
53:             let max_ray = self.contact_bound_metres * RAY_RANGE_CONTACT_BOUNDS;
54:             let hit = self.colliders.iter().filter_map(|shape|
55:                 shape.cast_ray(Vec3::ZERO, Quat::IDENTITY, start, -Vec3::Y, max_ray, false))
56:                 .min_by(|a, b| a.0.total_cmp(&b.0));
57:             let nearest = self.colliders.iter().map(|shape|
58:                 shape.project_point(Vec3::ZERO, Quat::IDENTITY, bearing, false).0)
59:                 .min_by(|a, b| a.distance_squared(bearing).total_cmp(&b.distance_squared(bearing)))
60:                 .ok_or(CornerProbeError::MissingSupport { point:*scene_point })?;
61:             let cylinder = Collider::cylinder(adventuresim_core::combat::HUMANOID_COLLISION_RADIUS_METRES, 1.9);
62:             let bottom = -cylinder.aabb(Vec3::ZERO, Rotation::default()).min.y;
63:             let pose = avian3d::parry::math::Pose::from_translation(start + Vec3::Y * bottom);
64:             let cylinder_hits = self.colliders.iter().map(|shape|
65:                 avian3d::parry::query::cast_shapes(&pose, -Vec3::Y, cylinder.shape_scaled().as_ref(),
66:                     &avian3d::parry::math::Pose::IDENTITY, Vec3::ZERO, shape.shape_scaled().as_ref(),
67:                     avian3d::parry::query::ShapeCastOptions::with_max_time_of_impact(max_ray))
68:                     .map_err(|_| CornerProbeError::UnsupportedShapeCast { point:*scene_point }))
69:                 .collect::<Result<Vec<_>,_>>()?;
70:             let cylinder_hit = cylinder_hits.into_iter().flatten().min_by(|a,b| a.time_of_impact.total_cmp(&b.time_of_impact));
71:             let below = self.terrain.surface_below(adventuresim_tactical_core::city_layout::grounding::SupportQuery::try_from(bearing + Vec3::Y * self.contact_bound_metres)?);
72:             Ok(json!({"bearing_metres":bearing,"ray_support_height_metres":hit.map(|hit| start.y - hit.0),
73:                 "ray_support_within_bound":hit.is_some_and(|hit| (start.y-hit.0-floor).abs()<=self.contact_bound_metres),
74:                 "cylinder_support_hit":cylinder_hit.map(|hit| json!({"foot_elevation_metres":start.y-hit.time_of_impact,"time_of_impact":hit.time_of_impact,"normal":hit.normal2})),
75:                 "nearest_solid_metres":nearest,"nearest_solid_distance_metres":nearest.distance(bearing),
76:                 "nearest_point_query_within_bound":nearest.distance(bearing)<=self.contact_bound_metres,
77:                 "height_query_below_floor_metres":below.map(|sample| sample.elevation.metres()),
78:                 "all_support_elevations_metres":self.terrain.support_elevations_at(*scene_point).iter().map(|h|h.metres()).collect::<Vec<_>>()}))
79:         }).collect::<Result<Vec<_>,CornerProbeError>>()?;
80:         Ok(
81:             json!({"colliders_materialized":self.colliders.len(),"contact_bound_metres":self.contact_bound_metres,
82:             "scope":"Exact bearing vertices, no point perturbation. Nearest-point, exact rays, production-radius cylinder casts and unbound height queries are distinct observations. Cylinder corner tests include adjacent soil and do not prove occupied access. Full footprint support and soil intrusion require the separate triangle-intersection experiment.","probes":probes}),
83:         )
84:     }
85: }
86: 
87: pub(super) fn measure_enclosures(
88:     input: &TacticalSceneInput,
89:     terrain: &SceneTerrain,
90: ) -> Result<Vec<Value>, adventuresim_tactical_core::scene_input::SceneInputError> {
91:     let mut enclosures = Vec::new();
92:     for compound in &input.compounds {
93:         let boundary = GeneratedBoundary::project(compound, terrain)?;
94:         let _collider = boundary.scene().fixed_support().collider()?;
95:         enclosures.push(json!({"property_id":compound.id,"member_building_ids":[compound.front_building_id,compound.rear_building_id],
96:             "gate_elevation_metres":boundary.elevation_metres().metres(),"cells":boundary.scene().fixed_support().cells().len(),
97:             "triangles":boundary.scene().fixed_support().cells().len()*8,
98:             "minimum_masonry_base_metres":boundary.scene().fixed_support().cells().iter().flat_map(|c|c.positions()[3..].iter())
99:                 .map(|p|p.metres().y+boundary.elevation_metres().metres()).fold(f32::INFINITY,f32::min)}));
100:     }
101:     Ok(enclosures)
102: }

