22: 
23: impl HeightExtrema {
24:     fn observe(&mut self, control: GeographicHeightControl) {
25:         self.vertices += 1;
26:         if self
27:             .low
28:             .is_none_or(|low| control.elevation.metres() < low.elevation.metres())
29:         {
30:             self.low = Some(control);
31:         }
32:         if self
33:             .high
34:             .is_none_or(|high| control.elevation.metres() > high.elevation.metres())
