41: pub(super) fn terrain_extrema(terrain: &SceneTerrain, corners: [ScenePlanPoint; 4]) -> Value {
42:     // Native clipping uses a complete nonempty scene-plane polygon.
43:     let corners = corners.map(ScenePlanPoint::metres);
44:     let half = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
45:     let [first, rest @ ..] = corners;
46:     let minimum = rest.into_iter().fold(first, Vec2::min);
47:     let maximum = rest.into_iter().fold(first, Vec2::max);
48:     let grid_min = ((minimum + half) / terrain.grid_scale())
49:         .floor()
50:         .max(Vec2::ZERO);
51:     let grid_max = ((maximum + half) / terrain.grid_scale())
52:         .ceil()
53:         .min(Vec2::new(
54:             (terrain.grid_width() - 1) as f32,
55:             (terrain.grid_depth() - 1) as f32,
56:         ));
57:     let mut result = HeightExtrema::default();
58:     for z in grid_min.y as usize..grid_max.y as usize {
59:         for x in grid_min.x as usize..grid_max.x as usize {
60:             let a = Vec2::new(x as f32, z as f32) * terrain.grid_scale() - half;
61:             let b = a + Vec2::X * terrain.grid_scale();
62:             let c = a + Vec2::ONE * terrain.grid_scale();
63:             let d = a + Vec2::Y * terrain.grid_scale();
64:             // SceneTerrain and Avian subdivide across b--d, not a--c.
65:             for triangle in [[a, b, d], [b, c, d]] {
66:                 for point in clip(triangle.to_vec(), &corners) {
67:                     let Some(point) = ScenePlanPoint::from_metres(point) else {
68:                         continue;
69:                     };
70:                     let Some(elevation) = terrain.height_at(point) else {
71:                         continue;
72:                     };
73:                     result.observe(GeographicHeightControl { point, elevation });
74:                 }
75:             }
76:         }
77:     }
78:     json!({
79:         "complete_playable_coverage":corners.iter().all(|p| p.abs().cmple(half).all()),
80:         "intersection_vertices":result.vertices,
81:         "minimum_metres":result.low.map(|sample|sample.elevation),
82:         "minimum_location":result.low.map(|sample|sample.point),
83:         "maximum_metres":result.high.map(|sample|sample.elevation),
84:         "maximum_location":result.high.map(|sample|sample.point),
85:         "method":"Linear terrain-triangle extrema at clipped intersection vertices, including interior terrain vertices; outside-playable coverage is not certified.",
86:     })
87: }
