89: pub(super) fn clip(mut polygon: Vec<Vec2>, corners: &[Vec2]) -> Vec<Vec2> {
90:     for index in 0..corners.len() {
91:         let a = corners[index];
92:         let edge = corners[(index + 1) % corners.len()] - a;
93:         let input = std::mem::take(&mut polygon);
94:         let Some(mut previous) = input.last().copied() else {
95:             break;
96:         };
97:         let mut previous_side = edge.perp_dot(previous - a);
98:         for point in input {
99:             let side = edge.perp_dot(point - a);
100:             if (side >= 0.0) != (previous_side >= 0.0) {
101:                 polygon.push(previous.lerp(point, previous_side / (previous_side - side)));
102:             }
103:             if side >= 0.0 {
104:                 polygon.push(point);
105:             }
106:             previous = point;
107:             previous_side = side;
108:         }
109:     }
110:     polygon
111: }
