27:         (0.0, street_height),
28:         (route.half_width_metres(), street_height),
29:         (gate_distance - route.half_width_metres(), gate_height),
30:         (platform_end, gate_height),
31:         (court_begin, court_height),
32:         (length, court_height),
33:     ];
