97:         let report = inspect(&compound, floor, court, height, 0.65)
98:             .unwrap()
99:             .unwrap();
100:         assert_eq!(report["candidates"][0]["passes_endpoint_grade"], false);
101:         assert!(report["candidates"][0]["shortfall_m"].as_f64().unwrap() > 2.0);
102:         assert_eq!(report["candidates"][1]["passes_endpoint_grade"], true);
103:         assert!(
104:             report["candidates"][1]["difference_from_front_floor_m"]
105:                 .as_f64()
106:                 .unwrap()
107:                 > 2.1
108:         );
109:         let passage = &report["independent_gate_to_court_profile"];
110:         assert_eq!(passage["passes_endpoint_grade"], true);
111:         assert!(passage["grade"].as_f64().unwrap() < 0.22);
112:         assert!(passage["gate_to_court_effective_run_m"].as_f64().unwrap() > 16.8);
113:         let mut reversed = compound.clone();
114:         reversed.access.reverse();
115:         assert_eq!(
116:             report,
117:             inspect(&reversed, floor, court, height, 0.65)
118:                 .unwrap()
119:                 .unwrap()
120:         );
121:     }
122: }

1: //! Bounded construction comparison; this does not publish runtime foundations.
2: use adventuresim_tactical_core::city_layout::grounding::{
3:     CompoundSupportLevels, CompoundSupportPlan, CourtStairLimits, CourtTreatment, MemberSupport,
4:     SupportElevation, SupportLimits,
5: };
6: use adventuresim_tactical_core::city_layout::{CityCompound, CityPlotBounds};
7: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
8: use bevy::math::{Vec3, Vec3Swizzles};
9: use serde_json::{Value, json};
10: #[path = "solutions/quantities.rs"]
11: mod quantities;
12: 
13: const COMPARISON_CONTACT_TOLERANCE_METRES: f32 = 0.001;
14: const PROVISIONAL_COMPARISON_CUT_FILL_METRES: f32 = 6.0;
15: const COMPARISON_MAXIMUM_RISER_METRES: f32 = 0.19;
16: const COMPARISON_MINIMUM_GOING_METRES: f32 = 0.25;
17: const COMPARISON_STAIR_CLEAR_WIDTH_METRES: f32 = 1.0;
18: const COMPARISON_LANDING_RUN_METRES: f32 = 0.5;
19: 
20: const COMPARISON_STAIRS: CourtStairLimits = CourtStairLimits::new(
21:     positive_comparison_length(COMPARISON_MAXIMUM_RISER_METRES),
22:     positive_comparison_length(COMPARISON_MINIMUM_GOING_METRES),
23:     positive_comparison_length(COMPARISON_STAIR_CLEAR_WIDTH_METRES),
24:     positive_comparison_length(COMPARISON_LANDING_RUN_METRES),
25:     positive_comparison_length(COMPARISON_LANDING_RUN_METRES),
26: );
27: 
28: pub(super) struct ComparisonMember {
29:     pub bearing: CityPlotBounds,
30:     pub threshold: ScenePlanPoint,
31: }
32: pub(super) struct ComparisonMembers {
33:     pub front: ComparisonMember,
34:     pub rear: ComparisonMember,
35: }
36: pub(super) struct ProposedCompoundLevels {
37:     pub front: SupportElevation,
38:     pub court: SupportElevation,
39:     pub rear: SupportElevation,
40: }
41: 
42: #[derive(Debug, thiserror::Error)]
43: pub(super) enum ComparisonInputError {
44:     #[error("comparison requires three finite front/court/rear elevations")]
45:     InvalidProposedLevels,
46: }
47: 
48: impl ProposedCompoundLevels {
49:     /// Adapt the diagnostic producer's front/court/rear JSON array explicitly.
50:     pub fn from_capture(value: &Value) -> Result<Self, ComparisonInputError> {
51:         Self::decode_capture(value).ok_or(ComparisonInputError::InvalidProposedLevels)
52:     }
53:     fn decode_capture(value: &Value) -> Option<Self> {
54:         let values: &[Value; 3] = value.as_array()?.as_slice().try_into().ok()?;
55:         let elevation = |value: &Value| SupportElevation::from_metres(value.as_f64()? as f32);
56:         Some(Self {
57:             front: elevation(&values[0])?,
58:             court: elevation(&values[1])?,
59:             rear: elevation(&values[2])?,
60:         })
61:     }
62: }
63: 
64: pub(super) fn stair_limits() -> CourtStairLimits {
65:     COMPARISON_STAIRS
66: }
67: 
68: pub(super) fn compare(
69:     property: &CityCompound,
70:     members: ComparisonMembers,
71:     proposed: ProposedCompoundLevels,
72:     geographic: &[[Vec3; 3]],
73:     height: impl Fn(ScenePlanPoint) -> Option<SupportElevation>,
74:     maximum_grade: f32,
75: ) -> Option<Value> {
76:     let gate = ScenePlanPoint::from_metres(property.boundary.gate.centre_metres)?;
77:     let mut gate_routes = property
78:         .access
79:         .iter()
80:         .filter(|r| r.contains_centreline(gate));
81:     let route = gate_routes
82:         .next()
83:         .filter(|_| gate_routes.next().is_none())?;
84:     let levels = CompoundSupportLevels {
85:         front: MemberSupport {
86:             building_id: property.front_building_id,
87:             contact: members.front.bearing,
88:             court_threshold_metres: members.front.threshold,
89:             elevation: proposed.front,
90:         },
91:         rear: MemberSupport {
92:             building_id: property.rear_building_id,
93:             contact: members.rear.bearing,
94:             court_threshold_metres: members.rear.threshold,
95:             elevation: proposed.rear,
96:         },
97:         court: proposed.court,
98:         gate: height(gate)?,
99:         street: height(route.start())?,
100:     };

101:     let limits = SupportLimits::new(
102:         adventuresim_tactical_core::city_layout::grounding::SupportGrade::from_ratio(
103:             maximum_grade,
104:         )?,
105:         adventuresim_building_generator::spatial_geometry::PositiveLength::from_metres(
106:             PROVISIONAL_COMPARISON_CUT_FILL_METRES,
107:         )
108:         .ok()?,
109:         adventuresim_building_generator::spatial_geometry::PositiveLength::from_metres(
110:             COMPARISON_CONTACT_TOLERANCE_METRES,
111:         )
112:         .ok()?,
113:     );
114:     let stairs = stair_limits();
115:     let thickness = property
116:         .boundary
117:         .walls
118:         .iter()
119:         .map(|w| w.thickness_metres)
120:         .max_by(f32::total_cmp)?;
121:     let candidates=[CourtTreatment::Level,CourtTreatment::Terraced(stairs)].map(|treatment| {
122:         match CompoundSupportPlan::compile(property,levels,limits,treatment) {
123:             Ok(plan)=>{
124:                 let mesh = match plan.mesh() {
125:                     Ok(mesh) => mesh,
126:                     Err(error) => return json!({"treatment":treatment,"support_rejection":error}),
127:                 };
128:                 match quantities::measure(&plan,geographic,&height,thickness) { Ok(quantities)=>json!({"treatment":treatment,
129:                 "member_support":plan.member_support(),"court_elevation":plan.court_elevation(),
130:                 "gate_elevation":plan.gate_elevation(),"stair_flights":plan.stair_flights().collect::<Vec<_>>(),
131:                 "mesh_maximum_grade":mesh.maximum_grade(),
132:                 "quantities":quantities,"mesh":mesh,
133:             }), Err(error)=>json!({"treatment":treatment,"property_id":property.id,"quantity_rejection":error}) }},
134:             Err(error)=>json!({"treatment":treatment,"support_rejection":error}),
135:         }
136:     });
137:     Some(
138:         json!({"property_id":property.id,"member_building_ids":[property.front_building_id,property.rear_building_id],
139:             "chosen_level_inputs":levels,"comparison_limits":limits,"candidates":candidates,
140:             "geographic_triangles":geographic,
141:             "access_scope":"Pedestrian support surfaces. Cart/service traversal, neighbouring boundary geometry, drainage and retaining-wall structural capacity are not accepted by this comparison.",
142:             "verification_scope":"Bounded construction decision experiment. Six-metre cut/fill and stair dimensions are explicit provisional modelling assumptions, not calibrated runtime limits or historical measurements. No production terrain is changed, no required positive fixture is accepted, and no retaining-wall collision capacity is asserted.",
143:         }),
144:     )
145: }
146: 
147: const fn positive_comparison_length(
148:     value: f32,
149: ) -> adventuresim_building_generator::spatial_geometry::PositiveLength {
150:     match adventuresim_building_generator::spatial_geometry::PositiveLength::from_metres(value) {
151:         Ok(length) => length,
152:         Err(_) => panic!("authored comparison lengths must be positive"),
153:     }
154: }
155: 
156: #[cfg(test)]
157: mod input_tests {
158:     use super::*;
159:     #[test]
160:     fn proposed_levels_reject_malformed_or_unrepresentable_capture_values() {
161:         assert!(ProposedCompoundLevels::from_capture(&json!([1, 2])).is_err());
162:         assert!(ProposedCompoundLevels::from_capture(&json!([1, 2, 3, 4])).is_err());
163:         assert!(ProposedCompoundLevels::from_capture(&json!([1, 2, 1e100])).is_err());
164:         let levels = ProposedCompoundLevels::from_capture(&json!([-1, 2, 3])).unwrap();
165:         assert_eq!(levels.front.metres(), -1.0);
166:         assert_eq!(levels.court.metres(), 2.0);
167:         assert_eq!(levels.rear.metres(), 3.0);
168:     }
169: }

1: //! Diagnostic source sampling; vista observations never become tactical support.
2: use super::{Inspection, TerrainStages};
3: use adventuresim_tactical_core::{
4:     city_layout::grounding::SupportElevation,
5:     scene::SceneTerrain,
6:     scene_coordinates::ScenePlanPoint,
