14: }
15: 
16: impl<'a> InspectionSource<'a> {
17:     pub(super) fn new(terrain: &'a SceneTerrain, vista: &'a VistaSample) -> Self {
18:         Self { terrain, vista }
19:     }
20: 
21:     pub(super) fn height_at(&self, point: ScenePlanPoint) -> Option<SupportElevation> {
22:         self.terrain.height_at(point).or_else(|| {
23:             self.vista.lods.iter().enumerate().find_map(|(index, lod)| {
24:                 vista_triangle_height(lod, self.vista.lods.get(index + 1), self.terrain, point)
25:             })
26:         })
27:     }
