1: //! Distance between convex plan-space contacts, including point/edge contacts.
2: use bevy::math::Vec2;
3: 
4: pub(super) fn between(a: &[Vec2], b: &[Vec2]) -> Option<f32> {
5:     if a.is_empty() || b.is_empty() {
6:         return None;
7:     }
8:     if a.iter().any(|p| contains(b, *p)) || b.iter().any(|p| contains(a, *p)) {
9:         return Some(0.0);
10:     }
11:     let mut minimum = f32::INFINITY;
12:     for (&start, &end) in a.iter().zip(a.iter().cycle().skip(1)).take(a.len()) {
13:         for (&other_start, &other_end) in b.iter().zip(b.iter().cycle().skip(1)).take(b.len()) {
14:             if crosses(start, end, other_start, other_end) {
15:                 return Some(0.0);
16:             }
17:             for distance in [
18:                 to_segment(start, other_start, other_end),
19:                 to_segment(end, other_start, other_end),
20:                 to_segment(other_start, start, end),
21:                 to_segment(other_end, start, end),
22:             ] {
23:                 minimum = minimum.min(distance);
24:             }
25:         }
26:     }
27:     Some(minimum)
28: }
29: 
30: fn to_segment(point: Vec2, start: Vec2, end: Vec2) -> f32 {
31:     let edge = end - start;
32:     if edge.length_squared() == 0.0 {
33:         return point.distance(start);
34:     }
35:     let fraction = ((point - start).dot(edge) / edge.length_squared()).clamp(0.0, 1.0);
36:     point.distance(start + edge * fraction)
37: }
38: 
39: fn crosses(a: Vec2, b: Vec2, c: Vec2, d: Vec2) -> bool {
40:     let r = b - a;
41:     let s = d - c;
42:     let denominator = r.perp_dot(s);
43:     if denominator == 0.0 {
44:         return false;
45:     }
46:     let t = (c - a).perp_dot(s) / denominator;
47:     let u = (c - a).perp_dot(r) / denominator;
48:     (0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u)
49: }
50: 
51: fn contains(polygon: &[Vec2], point: Vec2) -> bool {
52:     if polygon.len() < 3 {
53:         return false;
54:     }
55:     let mut positive = false;
56:     let mut negative = false;
57:     for (&start, &end) in polygon
58:         .iter()
59:         .zip(polygon.iter().cycle().skip(1))
60:         .take(polygon.len())
61:     {
62:         let side = (end - start).perp_dot(point - start);
63:         positive |= side > 0.0;
64:         negative |= side < 0.0;
65:     }
66:     !(positive && negative)
67: }
