1: //! Materialize a deterministic tactical scene at a geographic coordinate.
2: 
3: use std::path::PathBuf;
4: 
5: use adventuresim_tactical_core::prelude::TACTICAL_SCENE_GENERATION_VERSION;
6: use adventuresim_tactical_server_dispatcher::scene_input::{
7:     build_imported_scene, materialize_scene_input,
8: };
9: use adventuresim_terrain::{TerrainPack, TerrainPurpose};
10: use adventuresim_world_schema::coordinates::{LatitudeE7, LongitudeE7};
11: use clap::Parser;
12: 
13: #[derive(Debug, Parser)]
14: #[command(about = "Sample the final real-world terrain pack into a tactical scene document")]
15: struct Args {
16:     /// Latitude in signed WGS84 decimal degrees.
17:     #[arg(long, allow_hyphen_values = true)]
18:     latitude: f64,
19: 
20:     /// Longitude in signed WGS84 decimal degrees.
21:     #[arg(long, allow_hyphen_values = true)]
22:     longitude: f64,
23: 
24:     /// Absolute world minute used for deterministic weather and celestial state.
25:     #[arg(long, default_value_t = 340_320)]
26:     absolute_minute: u64,
27: 
28:     /// Stable semantic name included in the scene document.
29:     #[arg(long, default_value = "real-world-coordinate")]
30:     scene_key: String,
31: 
32:     /// Final terrain manifest produced by build-strategic-map.
33:     #[arg(long, default_value = "target/strategic-map/terrain-routing-v3.json")]
34:     terrain_manifest: PathBuf,
35: 
36:     /// Final compressed terrain pack paired with terrain-manifest.
37:     #[arg(long, default_value = "target/strategic-map/terrain-routing-v3.pack")]
38:     terrain_pack: PathBuf,
39:     /// Directory for immutable coordinate-derived scene documents.
40:     #[arg(long, default_value = "target/tactical-real-world-scenes")]
41:     output_dir: PathBuf,
42: }
43: 
44: fn main() -> Result<(), String> {
45:     let args = Args::parse();
46:     let latitude_e7 = LatitudeE7::from_degrees(args.latitude)
47:         .ok_or("latitude must be finite and within -90..=90")?
48:         .get();
49:     let longitude_e7 = LongitudeE7::from_degrees(args.longitude)
50:         .ok_or("longitude must be finite and within -180..=180")?
51:         .get();
52:     let terrain = TerrainPack::load(&args.terrain_manifest, &args.terrain_pack)
53:         .map_err(|error| format!("failed to load final terrain pack: {error}"))?;
54:     if terrain.purpose() != TerrainPurpose::Final {
55:         return Err("real-world scenes require the final terrain pack".into());
56:     }
57:     let mission_id = format!(
58:         "capture:v{}:{}:{latitude_e7}:{longitude_e7}:{}:{}:{}",
59:         TACTICAL_SCENE_GENERATION_VERSION,
60:         terrain.digest(),
61:         args.absolute_minute,
62:         args.absolute_minute,
63:         args.scene_key
64:     );
65:     let input = build_imported_scene(
66:         &terrain,
67:         &mission_id,
68:         &args.scene_key,
69:         latitude_e7,
70:         longitude_e7,
71:         adventuresim_world_schema::calendar::StrategicMinute::new(args.absolute_minute),
72:         adventuresim_world_schema::calendar::StrategicMinute::new(args.absolute_minute),
73:         None,
74:     )?;
75:     let path = materialize_scene_input(&args.output_dir, &mission_id, &input)?;
76:     println!(
77:         "TACTICAL_REAL_WORLD_SCENE={}",
78:         path.canonicalize().unwrap_or(path).display()
79:     );
80:     println!("TERRAIN_PACKAGE_SHA256={}", terrain.digest());
81:     println!("COORDINATES={:.7},{:.7}", args.latitude, args.longitude);
82:     Ok(())
83: }
