1: //! Measure a composed surface and verify unowned source vertices independently.
2: use super::*;
3: use std::path::Path;
4: 
5: pub(super) struct Composition {
6:     pub accepted: bool,
7:     pub report: Value,
8: }
9: 
10: impl Composition {
11:     pub fn compile(
12:         selected: SelectedCityGrounding,
13:         geographic: &GeographicSurface,
14:         policy: CompoundGradingPolicy,
15:         output: Option<&Path>,
16:         placements_output: Option<&Path>,
17:         projection_output: Option<&Path>,
18:     ) -> Result<Self, Box<dyn std::error::Error>> {
19:         let started = Instant::now();
20:         let grounded = match selected.compile() {
21:             Ok(grounded) => grounded,
22:             Err(error) => {
23:                 return Ok(Self {
24:                     accepted: false,
25:                     report: json!({"composition_rejection": error}),
26:                 });
27:             }
28:         };
29:         let compilation_seconds = started.elapsed().as_secs_f64();
30:         let projection_check = projection::check(&grounded, geographic, projection_output)?;
31:         let surface = grounded.terrain();
32:         let plans = grounded.support_surfaces();
33:         let plan_bytes = serde_json::to_vec(plans)?.len();
34:         if let Some(path) = placements_output {
35:             placements::write(path, grounded.layout())?;
36:         }
37:         let encoded = serde_json::to_vec(&surface)?;
38:         let started = Instant::now();
39:         let mut checksum = 0.0_f64;
40:         let mut query_count = 0;
41:         let mut unchanged_samples = 0;
42:         for triangle in geographic.triangles() {
43:             for point in triangle {
44:                 let query = Vec2::new(point.x, point.z);
45:                 let Some(hit) = surface.highest_surface_at(
46:                     adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::from_metres(
47:                         query,
48:                     )
49:                     .ok_or("nonfinite support query")?,
50:                 ) else {
51:                     return Ok(Self {
52:                         accepted: false,
53:                         report: json!({
54:                             "source_query_missing": {"location_m":point,"constraint":"source_coverage"}
55:                         }),
56:                     });
57:                 };
58:                 let height = hit.elevation.metres();
59:                 checksum += f64::from(height);
60:                 query_count += 1;
61:                 let scene_query =
62:                     adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(query)?;
63:                 if plans.iter().all(|plan| !plan.contains(scene_query)) {
64:                     let error = (height - point.y).abs();
65:                     let permitted = policy.limits.contact_tolerance_metres();
66:                     if error > permitted {
67:                         return Ok(Self {
68:                             accepted: false,
69:                             report: json!({"unowned_source_change":{
70:                                 "location_m":query,"expected_m":point.y,"observed_m":height,
71:                                 "measured_error_m":error,"permitted_m":permitted,"shortfall_m":error-permitted
72:                             }}),
73:                         });
74:                     }
75:                     unchanged_samples += 1;
76:                 }
77:             }
78:         }
79:         let query_seconds = started.elapsed().as_secs_f64();
80:         if let Some(path) = output {
81:             std::fs::write(path, &encoded)?;
82:         }
83:         Ok(Self {
84:             accepted: true,
85:             report: json!({
86:                 "plans": plans.iter().map(|plan| json!({
87:                     "property_id":plan.property_id(),"members":plan.member_building_ids(),
88:                     "regions":plan.support_regions(),"maximum_grade":plan.mesh().maximum_grade()
89:                 })).collect::<Vec<_>>(),
90:                 "composition":{
91:                     "seconds":compilation_seconds,"surface_json_bytes":encoded.len(),
92:                     "support_plan_json_bytes":plan_bytes,
93:                     "compact_round_trip":projection_check,
94:                     "seated_playable_buildings":grounded.layout().playable.len(),
95:                     "seated_distant_buildings":grounded.layout().distant.len(),
96:                     "foundation_owners":surface.foundations().len(),
97:                     "foundation_solid_triangles":surface.foundations().iter().map(|f| f.solid_triangles().len()).sum::<usize>(),
98:                     "source_triangles_after_clipping":surface.natural_triangles().len(),
99:                     "query_seconds":query_seconds,"queries":query_count,
100:                     "unchanged_unowned_vertex_queries":unchanged_samples,"query_height_checksum":checksum
101:                 }
102:             }),
103:         })
104:     }
105: }

