284: fn scarp_lod(
285:     origin_metres: [f64; 2],
286:     tangent: [f64; 2],
287:     playable_half_extent: f64,
288: ) -> Option<TerrainLandformLod> {
289:     if origin_metres
290:         .into_iter()
291:         .all(|coordinate| coordinate.abs() <= playable_half_extent)
292:     {
293:         return Some(TerrainLandformLod::Detail);
294:     }
295:     let length = (tangent[0] * tangent[0] + tangent[1] * tangent[1]).sqrt();
296:     let unit = [tangent[0] / length, tangent[1] / length];
297:     let half_length = f64::from(SCARP_DEFAULT_HALF_LENGTH_CM) / 100.0;
298:     let half_width = f64::from(SCARP_DEFAULT_HALF_WIDTH_CM) / 100.0;
299:     let extent = [
300:         unit[0].abs() * half_length + unit[1].abs() * half_width,
301:         unit[1].abs() * half_length + unit[0].abs() * half_width,
302:     ];
303:     origin_metres
304:         .into_iter()
305:         .zip(extent)
306:         .all(|(coordinate, footprint_extent)| {
307:             coordinate.abs() <= playable_half_extent + footprint_extent
308:         })
309:         .then_some(TerrainLandformLod::Fringe)
310: }
