312: pub fn materialize_scene_input(
313:     directory: &Path,
314:     mission_id: &str,
315:     input: &TacticalSceneInput,
316: ) -> Result<PathBuf, String> {
317:     fs::create_dir_all(directory).map_err(|error| error.to_string())?;
318:     let key = Sha256::digest(mission_id.as_bytes())
319:         .iter()
320:         .take(12)
321:         .map(|byte| format!("{byte:02x}"))
322:         .collect::<String>();
323:     let path = directory.join(format!("scene-{key}.json"));
324:     let bytes = serde_json::to_vec(input).map_err(|error| error.to_string())?;
325:     if let Ok(existing) = fs::read(&path) {
326:         if existing == bytes {
327:             return Ok(path);
328:         }
329:         return Err("existing scene input does not match the deterministic request".into());
330:     }
331:     let temporary = directory.join(format!("scene-{key}.tmp"));
332:     fs::write(&temporary, bytes).map_err(|error| error.to_string())?;
333:     fs::rename(&temporary, &path).map_err(|error| error.to_string())?;
334:     Ok(path)
335: }
336: 
337: fn sample_grid(
338:     pack: &TerrainPack,
339:     request: GridSampleRequest,
340: ) -> Result<TerrainSampleGrid, String> {
341:     let GridDimensions { width, depth } = request.dimensions;
342:     let center_x = f64::from(width - 1) * 0.5;
343:     let center_z = f64::from(depth - 1) * 0.5;
344:     let mut heights = Vec::with_capacity(usize::from(width) * usize::from(depth));
345:     let mut environment = Vec::with_capacity(heights.capacity());
346:     let origin = NativeTerrainCoordinate::from(request.center);
347:     for z in 0..depth {
348:         for x in 0..width {
349:             let east = (f64::from(x) - center_x) * f64::from(request.spacing_metres);
350:             let north = (f64::from(z) - center_z) * f64::from(request.spacing_metres);
351:             let point = origin.at_offset(east, north);
352:             let cell = pack
353:                 .cell(point.latitude_degrees, point.longitude_degrees)
354:                 .map_err(|error| error.to_string())?
355:                 .ok_or("requested scene window leaves the final terrain pack")?;
356:             let mut elevation = f32::from(cell.elevation_m);
357:             if matches!(request.elevation_sampling, ElevationSampling::PreservePeaks) {
358:                 let radius = f64::from(request.spacing_metres) * PEAK_SAMPLE_RADIUS_FACTOR;
359:                 for (sample_east, sample_north) in [
360:                     (-radius, -radius),

361:                     (0.0, -radius),
362:                     (radius, -radius),
363:                     (-radius, 0.0),
364:                     (radius, 0.0),
365:                     (-radius, radius),
366:                     (0.0, radius),
367:                     (radius, radius),
368:                 ] {
369:                     let sample = point.at_offset(sample_east, sample_north);
370:                     if let Some(neighbor) = pack
371:                         .cell(sample.latitude_degrees, sample.longitude_degrees)
372:                         .map_err(|error| error.to_string())?
373:                     {
374:                         elevation = elevation.max(f32::from(neighbor.elevation_m));
375:                     }
376:                 }
377:             } else {
378:                 let detail = deterministic_detail(request.seed, x, z)
379:                     * f32::from(cell.hilly_fraction_percent)
380:                     / f32::from(PERCENT_PER_WHOLE)
381:                     * HILLY_DETAIL_AMPLITUDE_METRES;
382:                 elevation += detail;
383:             }
384:             heights.push(elevation - f32::from(request.center_elevation_metres.get()));
385:             environment.push(environment_sample(cell));
386:         }
387:     }
388:     Ok(TerrainSampleGrid {
389:         width,
390:         depth,
391:         spacing_metres: request.spacing_metres,
392:         heights_metres: heights,
393:         environment,
394:     })
395: }
396: 
397: fn deterministic_seed(mission_id: &str) -> Seed {
398:     Seed::derive(mission_id.as_bytes(), StreamId::new("scene.mission"), &[])
