877:             Proj::from_proj_string("+proj=longlat +datum=WGS84 +ellps=WGS84 +no_defs").unwrap();
878:         let projected = Proj::from_proj_string("+proj=lcc +lat_0=52 +lon_0=10 +lat_1=35 +lat_2=65 +x_0=4000000 +y_0=2800000 +ellps=GRS80 +units=m +no_defs").unwrap();
879:         let mut position = (longitude.to_radians(), latitude.to_radians(), 0.0);
880:         transform(&geographic, &projected, &mut position).unwrap();
881:         let (x, y) = (position.0.round() as i32, position.1.round() as i32);
882:         TerrainFeature::MappedGeology(MappedGeologicWindow {
883:             id: "egdi-window:fault-test".into(),
884:             unit: GeologicUnitId::new("fault-test").unwrap(),
885:             lithology: SurfaceLithology::Sedimentary(SedimentaryRock::Sandstone),
886:             bounds_metres: [x - 1_000, y - 1_000, x + 1_000, y + 1_000],
887:         })
888:     }
