890:     fn constant_final_pack() -> (TerrainPack, PathBuf) {
891:         let nonce = SystemTime::now()
892:             .duration_since(SystemTime::UNIX_EPOCH)
893:             .expect("clock after epoch")
894:             .as_nanos();
895:         let directory = std::env::temp_dir().join(format!(
896:             "adventuresim-tactical-scene-pack-{}-{nonce}",
897:             std::process::id()
898:         ));
899:         fs::create_dir_all(&directory).expect("create terrain fixture directory");
900:         let manifest_path = directory.join("terrain.manifest.json");
901:         let pack_path = directory.join("terrain.pack");
902:         let mut pack_bytes = Vec::new();
903:         let mut entries = Vec::new();
904:         let tile_width = 1_800_u16;
905:         let tile_height = 3_600_u16;
906:         for chunk_y in 0..tile_height.div_ceil(CHUNK_SIDE) {
907:             for chunk_x in 0..tile_width.div_ceil(CHUNK_SIDE) {
908:                 let width = CHUNK_SIDE.min(tile_width - chunk_x * CHUNK_SIDE);
909:                 let height = CHUNK_SIDE.min(tile_height - chunk_y * CHUNK_SIDE);
910:                 let cell = [65, 1, 3, 0b1111, 77];
911:                 let decoded = cell.repeat(usize::from(width) * usize::from(height));
912:                 let mut encoder = DeflateEncoder::new(Vec::new(), Compression::fast());
913:                 encoder.write_all(&decoded).expect("encode fixture chunk");
914:                 let compressed = encoder.finish().expect("finish fixture chunk");
915:                 let offset = pack_bytes.len() as u64;
916:                 pack_bytes.extend_from_slice(&compressed);
917:                 entries.push(Entry {
918:                     south: 50,
919:                     west: 10,
920:                     tile_width,
921:                     tile_height,
922:                     chunk_x,
923:                     chunk_y,
924:                     width,
925:                     height,
926:                     offset,
927:                     length: compressed.len() as u32,
928:                     decoded_sha256: format!("{:x}", Sha256::digest(&decoded)),
929:                 });
930:             }
931:         }
932:         fs::write(&pack_path, &pack_bytes).expect("write terrain fixture pack");
933:         let mut manifest = Manifest {
934:             schema: adventuresim_terrain::SCHEMA,
935:             purpose: TerrainPurpose::Final,
936:             bounds: [10.0, 50.0, 11.0, 51.0],
937:             source_resolution_m: 30,
938:             content_sha256: format!("{:x}", Sha256::digest(&pack_bytes)),
939:             road_geometry_sha256: "1".repeat(64),
940:             wetland_source_sha256: "2".repeat(64),
941:             wetland_cells: 1,
942:             cultivation_grid_crs: "EPSG:3035".into(),
943:             cultivation_grid_resolution_m: 1_000,
944:             cultivation_rules_version: 1,
945:             cultivation_source_sha256: "3".repeat(64),
946:             cultivated_square_count: 1,
947:             cultivated_native_cells: 1,
948:             terrain_features: vec![
949:                 TerrainFeature::MappedFault(MappedFault {
950:                     id: "DE:pack-fixture".into(),
951:                     local_name: Some("pack fixture".into()),
952:                     classification: None,
953:                     mapped_active: false,
954:                     mapped_capable: false,
955:                     trace: vec![
956:                         TravelGeometryPoint::new(10.49, 50.5001).unwrap(),
957:                         TravelGeometryPoint::new(10.51, 50.5001).unwrap(),
958:                     ],
959:                 }),
960:                 mapped_sandstone_window(10.5, 50.5),
961:             ],
962:             entries,
963:             package_sha256: "0".repeat(64),
964:         };
965:         manifest.package_sha256 = format!(
966:             "{:x}",
967:             Sha256::digest(serde_json::to_vec(&manifest).expect("serialize unsigned manifest"))
968:         );
969:         fs::write(
970:             &manifest_path,
971:             serde_json::to_vec(&manifest).expect("serialize terrain manifest"),
972:         )
973:         .expect("write terrain fixture manifest");
974:         let pack =
975:             TerrainPack::load(&manifest_path, &pack_path).expect("load final terrain fixture");
976:         (pack, directory)
977:     }
978: }

