1: //! Exact settlement business and operator bindings for occupied scenes.
2: use super::*;
3: 
4: pub(super) fn bind_establishments(
5:     settlement: Option<&SettlementSceneProfile>,
6:     layout: &adventuresim_tactical_core::city_layout::CitySceneLayout,
7: ) -> Result<Vec<SceneEstablishment>, String> {
8:     let Some(settlement) = settlement else {
9:         return Ok(Vec::new());
10:     };
11:     let mut operators = BTreeMap::new();
12:     for operator in &settlement.operators {
13:         if operator.business_id.settlement_id != settlement.id {
14:             return Err("business operator crosses the requested settlement boundary".into());
15:         }
16:         if operators
17:             .insert(operator.business_id.key, operator)
18:             .is_some()
19:         {
20:             return Err("business operator identity is duplicated".into());
21:         }
22:     }
23:     let mut establishments = Vec::with_capacity(layout.businesses.len());
24:     for site in &layout.businesses {
25:         let operator = operators
26:             .remove(&site.key)
27:             .ok_or("placed business is missing its resident operator")?;
28:         let operator_name = operator.operator_name.clone();
29:         establishments.push(SceneEstablishment {
30:             building_id: site.building_id,
31:             business_id: operator.business_id.clone(),
32:             operator_character_id: operator.operator_character_id,
33:             operator_name: operator_name.clone(),
34:             shop_name: ShopName::for_operator(&operator_name, site.key.usage),
35:         });
36:     }
37:     if !operators.is_empty() {
38:         return Err("business operator has no placed establishment".into());
39:     }
40:     establishments.sort_by_key(|establishment| establishment.building_id);
41:     Ok(establishments)
42: }

