1: //! Select procedural landforms from mapped lithology and unmodified source
2: //! relief. The selected process is a plausible realization, not a mapped event.
3: //!
4: //! Rebuild world data and terrain packs to supply containment-verified EGDI
5: //! windows. Coverage is deliberately limited to mapped polygons around import
6: //! anchors; absent coverage leaves the heightfield intact. Fault traces retain
7: //! priority. Roads, water, cultivation, settlements and the central traversal
8: //! corridor exclude additional landforms before any geometry is generated.
9: 
10: use super::*;
11: use adventuresim_building_generator::spatial_geometry::PositiveLength;
12: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
13: use adventuresim_world_schema::{
14:     IgneousRock, SedimentaryRock, SurfaceLithology, UnconsolidatedDeposit,
15: };
16: use proj4rs::{proj::Proj, transform::transform};
17: 
18: const MIN_SOURCE_GRADE: f32 = 0.20;
19: const MAX_SOURCE_GRADE: f32 = 0.65;
20: const MIN_SOURCE_RELIEF_METRES: f32 = 4.0;
21: const MAX_RELIEF_METRES: f32 = 8.0;
22: const HALF_LENGTH_CM: u16 = 1_200;
23: const HALF_WIDTH_CM: u16 = 1_000;
24: const COLLAR_CM: u16 = 250;
25: const CORRIDOR_HALF_WIDTH_METRES: f32 = 7.0;
26: const PROTECTED_COVER_BPS: u16 = 1_000;
27: const GEOLOGIC_PROJECTION_MARGIN_METRES: f64 = 2.0;
28: const CANDIDATE_STRIDE: usize = 8;
29: 
30: struct MappedLandformProfile {
31:     kind: TerrainLandformKind,
32:     lithology: SurfaceLithology,
33: }
34: 
35: pub(super) fn select(
36:     features: &[TerrainFeature],
37:     center: Wgs84CoordinateE7,
38:     grid: &TerrainSampleGrid,
39:     seed: fabelgeist_determinism::Seed,
40: ) -> Option<TerrainLandformRecipe> {
41:     let geographic =
42:         Proj::from_proj_string("+proj=longlat +datum=WGS84 +ellps=WGS84 +no_defs").ok()?;
43:     let projected = Proj::from_proj_string("+proj=lcc +lat_0=52 +lon_0=10 +lat_1=35 +lat_2=65 +x_0=4000000 +y_0=2800000 +ellps=GRS80 +units=m +no_defs").ok()?;
44:     let terrain = SceneTerrain::from_heightmap(
45:         usize::from(grid.width),
46:         usize::from(grid.depth),
47:         grid.spacing_metres,
48:         grid.heights_metres.clone(),
49:     )?;
50:     for z in
51:         (CANDIDATE_STRIDE..usize::from(grid.depth) - CANDIDATE_STRIDE).step_by(CANDIDATE_STRIDE)
52:     {
53:         for x in
54:             (CANDIDATE_STRIDE..usize::from(grid.width) - CANDIDATE_STRIDE).step_by(CANDIDATE_STRIDE)
55:         {
56:             let point = ScenePlanPoint::from_metres(
57:                 Vec2::new(
58:                     x as f32 - (f32::from(grid.width) - 1.0) * 0.5,
59:                     z as f32 - (f32::from(grid.depth) - 1.0) * 0.5,
60:                 ) * grid.spacing_metres,
61:             )?;
62:             let offset =
63:                 PositiveLength::from_metres(grid.spacing_metres * CANDIDATE_STRIDE as f32).ok()?;
64:             let gradient = source_gradient(&terrain, point, offset)?;
65:             let grade = gradient.length();
66:             if !(MIN_SOURCE_GRADE..=MAX_SOURCE_GRADE).contains(&grade) {
67:                 continue;
68:             }
69:             let downhill = -gradient.normalize();
70:             let tangent = Vec2::new(downhill.y, -downhill.x);
71:             let relief = (grade * f32::from(HALF_WIDTH_CM) * 2.0 / 100.0).min(MAX_RELIEF_METRES);
72:             if relief < MIN_SOURCE_RELIEF_METRES {
73:                 continue;
74:             }
75:             let tangent_permyriad = [
76:                 (tangent.x * 10000.0).round() as i16,
77:                 (tangent.y * 10000.0).round() as i16,
78:             ];
79:             let Some(MappedLandformProfile { kind, lithology }) = mapped_profile(
80:                 features,
81:                 center,
82:                 point,
83:                 f64::from(HALF_LENGTH_CM.max(HALF_WIDTH_CM)) / 100.0,
84:                 &geographic,
85:                 &projected,
86:             ) else {
87:                 continue;
88:             };
89:             let recipe = TerrainLandformRecipe::from_quantized(
90:                 adventuresim_tactical_core::volumetric_terrain::QuantizedLandformRecipe {
91:                     kind,
92:                     surface: TerrainSurfaceRecipe::new(
93:                         lithology,
94:                         TerrainSurfaceSource::Mapped,
95:                         seed,
96:                         tangent_permyriad,
97:                     )
98:                     .ok()?,
99:                     seed,
100:                     origin_cm: [
101:                         (point.metres().x * 100.0).round() as i32,
102:                         (point.metres().y * 100.0).round() as i32,
103:                     ],
104:                     tangent_permyriad,
105:                     relief_cm: (relief * 100.0).round() as u16,
106:                     half_length_cm: HALF_LENGTH_CM,
107:                     half_width_cm: HALF_WIDTH_CM,
108:                     collar_cm: COLLAR_CM,
109:                     lod: TerrainLandformLod::Detail,
110:                 },
111:             )
112:             .ok()?;
113:             if !safe_footprint(grid, &terrain, recipe) {
114:                 continue;
115:             }
116:             return Some(recipe);
117:         }
118:     }
119:     None
120: }

