255: 
256: fn mapped_lithology(
257:     features: &[TerrainFeature],
258:     center: Wgs84CoordinateE7,
259:     point: ScenePlanPoint,
260:     footprint_radius_metres: f64,
261:     geographic: &Proj,
262:     projected: &Proj,
263: ) -> Option<SurfaceLithology> {
264:     // The whole bounding square, not only the mission coordinate, must
265:     // lie inside one containment-verified source window. Margin absorbs
266:     // rounding and local east/north versus map-projection curvature.
267:     let radius = footprint_radius_metres + GEOLOGIC_PROJECTION_MARGIN_METRES;
268:     // Proj4 consumes native longitude/latitude derived from this scene footprint.
269:     let point = point.metres();
270:     let corners = [-radius, 0.0, radius]
271:         .into_iter()
272:         .flat_map(|dx| [-radius, 0.0, radius].map(|dz| (dx, dz)))
273:         .map(|(dx, dz)| {
274:             let longitude_scale =
275:                 METRES_PER_LATITUDE_DEGREE * center.latitude().degrees().to_radians().cos();
276:             let mut position = (
277:                 (center.longitude().degrees() + (f64::from(point.x) + dx) / longitude_scale)
278:                     .to_radians(),
279:                 (center.latitude().degrees()
280:                     + (f64::from(point.y) + dz) / METRES_PER_LATITUDE_DEGREE)
281:                     .to_radians(),
282:                 0.0,
283:             );
284:             transform(geographic, projected, &mut position).ok()?;
285:             Some([position.0, position.1])
286:         })
287:         .collect::<Option<Vec<_>>>()?;
288:     let window = features
289:         .iter()
290:         .filter_map(|feature| match feature {
291:             TerrainFeature::MappedGeology(window) => Some(window),
292:             _ => None,
293:         })
294:         .find(|window| corners.iter().all(|&corner| window.contains(corner)))?;
295:     Some(window.lithology)
296: }
