150: /// Native centred finite difference in scene east/north metres; output is grade.
151: fn source_gradient(
152:     terrain: &SceneTerrain,
153:     point: ScenePlanPoint,
154:     offset: PositiveLength,
155: ) -> Option<Vec2> {
156:     let offset = offset.metres();
157:     let east = terrain.height_at(ScenePlanPoint::from_metres(
158:         point.metres() + Vec2::X * offset,
159:     )?)?;
160:     let west = terrain.height_at(ScenePlanPoint::from_metres(
161:         point.metres() - Vec2::X * offset,
162:     )?)?;
163:     let north = terrain.height_at(ScenePlanPoint::from_metres(
164:         point.metres() + Vec2::Y * offset,
165:     )?)?;
166:     let south = terrain.height_at(ScenePlanPoint::from_metres(
167:         point.metres() - Vec2::Y * offset,
168:     )?)?;
169:     // Metres become native coefficients only for this finite difference.
170:     Some(
171:         Vec2::new(
172:             east.metres() - west.metres(),
173:             north.metres() - south.metres(),
174:         ) / (offset * 2.0),
175:     )
176: }
