178: fn kind_for_lithology(lithology: SurfaceLithology) -> Option<TerrainLandformKind> {
179:     match lithology {
180:         SurfaceLithology::Sedimentary(SedimentaryRock::Sandstone) => {
181:             Some(TerrainLandformKind::SandstoneAlcove)
182:         }
183:         SurfaceLithology::Sedimentary(SedimentaryRock::Limestone | SedimentaryRock::Dolostone) => {
184:             Some(TerrainLandformKind::CarbonateDissolution)
185:         }
186:         SurfaceLithology::Igneous(IgneousRock::Granite | IgneousRock::Granitoid) => {
187:             Some(TerrainLandformKind::GraniteJointRockfall)
188:         }
189:         SurfaceLithology::Igneous(IgneousRock::Basalt) => {
190:             Some(TerrainLandformKind::BasaltCoolingColumns)
191:         }
192:         SurfaceLithology::Unconsolidated(UnconsolidatedDeposit::Clay) => {
193:             Some(TerrainLandformKind::CohesiveSlumpHeadscarp)
194:         }
195:         _ => None,
196:     }
197: }
