199: fn safe_footprint(
200:     grid: &TerrainSampleGrid,
201:     terrain: &SceneTerrain,
202:     recipe: TerrainLandformRecipe,
203: ) -> bool {
204:     let origin = Vec2::new(recipe.origin_cm()[0] as f32, recipe.origin_cm()[1] as f32) / 100.0;
205:     let radius = f32::from(recipe.half_length_cm().max(recipe.half_width_cm())) / 100.0 + 2.0;
206:     let half = Vec2::new(terrain.width(), terrain.depth()) * 0.5;
207:     if origin.x.abs() + radius >= half.x
208:         || origin.y.abs() + radius >= half.y
209:         || origin.y.abs() - radius <= CORRIDOR_HALF_WIDTH_METRES
210:     {
211:         return false;
212:     }
213:     for (index, sample) in grid.environment.iter().enumerate() {
214:         let point = (Vec2::new(
215:             (index % usize::from(grid.width)) as f32,
216:             (index / usize::from(grid.width)) as f32,
217:         ) - Vec2::new(
218:             (f32::from(grid.width) - 1.0) * 0.5,
219:             (f32::from(grid.depth) - 1.0) * 0.5,
220:         )) * grid.spacing_metres;
221:         if (point - origin).abs().max_element() <= radius
222:             && (sample.water_bps > 0
223:                 || sample.crossing_bps > 0
224:                 || sample.wetland_bps >= PROTECTED_COVER_BPS
225:                 || sample.cultivation_bps > 0
226:                 || matches!(
227:                     sample.surface,
228:                     TacticalSurface::Road | TacticalSurface::Water | TacticalSurface::Wetland
229:                 ))
230:         {
231:             return false;
232:         }
233:     }
234:     true
235: }
