1: //! Native report quantities retain f64 precision through sums and reductions.
2: //!
3: //! Roles distinguish clocks and units even when they share numeric storage.
4: //! Native f32 observations are promoted once; sums and means never narrow back
5: //! into gameplay quantities. Scalar projection belongs to the report serializer
6: //! or to the named arithmetic operations below.
7: 
8: use std::{marker::PhantomData, time::Duration};
9: 
10: use adventuresim_core::{
11:     elapsed::AnimationElapsed, linear_speed::NonnegativeSpeed, unit_interval::UnitInterval,
12: };
13: use adventuresim_tactical_server::iteration::TacticalElapsed;
14: use serde::Serialize;
15: 
16: pub(super) type MeasurementResult<T> = Result<T, MeasurementError>;
17: 
18: #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd, Serialize)]
19: #[serde(transparent)]
20: pub(super) struct Measurement<Role> {
21:     value: f64,
22:     #[serde(skip)]
23:     role: PhantomData<Role>,
24: }
25: 
26: #[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
27: pub(crate) enum MeasurementError {
28:     #[error("native report {quantity:?} must be finite")]
29:     NonFinite { quantity: ReportQuantity },
30:     #[error("native report {quantity:?} arithmetic overflowed")]
31:     Overflow { quantity: ReportQuantity },
32: }
33: 
34: pub(super) trait ReportUnit: Copy + Default + PartialOrd {
35:     const QUANTITY: ReportQuantity;
36: }
37: 
38: macro_rules! report_quantities {
39:     ($($role:ident),+ $(,)?) => {
40:         #[derive(Clone, Copy, Debug, PartialEq, Eq)]
41:         pub(crate) enum ReportQuantity {
42:             $($role),+
43:         }
44: 
45:         $(
46:             #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd)]
47:             pub(super) struct $role;
48: 
49:             impl ReportUnit for $role {
50:                 const QUANTITY: ReportQuantity = ReportQuantity::$role;
51:             }
52:         )+
53:     };
54: }
55: 
56: report_quantities! {
57:     TacticalSeconds,
58:     AutoresolveSeconds,
59:     ContactMetres,
60:     CenterSeparationMetres,
61:     WeaponReachMetres,
62:     MovementMetres,
63:     MovementSpeed,
64:     ContactJoules,
65:     HealthDamage,
66:     BloodLossFraction,
67:     WoundFlowFractionPerSecond,
68:     Fatigue,
69:     AcuteTrauma,
70:     Imbalance,
71:     PainIncapacitation,
72:     IncapacitationPerformance,
73:     AttackPowerMultiplier,
74:     WinRate,
75:     WinRateDifference,
76:     WallSeconds,
77:     WallMilliseconds,
78:     DuelsPerWallSecond,
79:     TacticalSecondsPerWallSecond,
80: }
