82: impl<Role: ReportUnit> Measurement<Role> {
83:     pub(super) const ZERO: Self = Self {
84:         value: 0.0,
85:         role: PhantomData,
86:     };
87: 
88:     /// Admission at a native observation or authored report-limit boundary.
89:     pub(super) fn from_native(value: f32) -> MeasurementResult<Self> {
90:         Self::from_f64(f64::from(value))
91:     }
92: 
93:     pub(super) fn checked_add(&mut self, sample: Self) -> MeasurementResult<()> {
94:         *self = Self::from_arithmetic(self.value + sample.value)?;
95:         Ok(())
96:     }
97: 
98:     /// Divide after the original ordered sum. An unobserved mean keeps its
99:     /// existing zero representation; contact extrema use Option separately.
100:     pub(super) fn mean(self, samples: u64) -> MeasurementResult<Self> {
101:         if samples == 0 {
102:             return Ok(self);
103:         }
104:         Self::from_arithmetic(self.value / samples as f64)
105:     }
106: 
107:     pub(super) fn min(self, other: Self) -> Self {
108:         Self {
109:             value: self.value.min(other.value),
110:             role: PhantomData,

111:         }
112:     }
113: 
114:     pub(super) fn max(self, other: Self) -> Self {
115:         Self {
116:             value: self.value.max(other.value),
117:             role: PhantomData,
118:         }
119:     }
120: 
121:     fn from_f64(value: f64) -> MeasurementResult<Self> {
122:         if !value.is_finite() {
123:             return Err(MeasurementError::NonFinite {
124:                 quantity: Role::QUANTITY,
125:             });
126:         }
127:         Ok(Self {
128:             value,
129:             role: PhantomData,
130:         })
131:     }
132: 
133:     fn from_arithmetic(value: f64) -> MeasurementResult<Self> {
134:         Self::from_f64(value).map_err(|_| MeasurementError::Overflow {
135:             quantity: Role::QUANTITY,
136:         })
137:     }
138: }
