285: fn record_autoresolve_timeline(
286:     causal: &mut AutoresolveCausalSummary,
287:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
288:     john_id: u64,
289: ) -> IterationResult<()> {
290:     let scheduled_contact_ticks = outcome
291:         .timeline
292:         .iter()
293:         .filter(|event| event.kind == MeleeTimelineKind::AttackStarted)
294:         .filter_map(|event| Some((event.attack_id?, event.attack_contact_tick?)))
295:         .collect::<BTreeMap<_, _>>();
296:     for event in &outcome.timeline {
297:         let Some(id) = event.combatant_id else {
298:             continue;
299:         };
300:         let combatant = if id == john_id {
301:             &mut causal.john
302:         } else {
303:             &mut causal.opponent
304:         };
305:         if event.kind == MeleeTimelineKind::Contact
306:             && event.attack_id.and_then(|attack_id| {
307:                 scheduled_contact_ticks
308:                     .get(&attack_id)
309:                     .map(|scheduled| event.tick < *scheduled)
310:             }) == Some(true)
311:         {
312:             combatant.premature_contact_events += 1;
313:         }
314:         causal::record_timeline_event(combatant, event)?;
315:     }
316:     if let Some(first) = outcome
317:         .timeline
318:         .iter()
319:         .find(|event| event.kind == MeleeTimelineKind::Contact)
320:     {
321:         causal.john_first_contacts += u64::from(first.combatant_id == Some(john_id));
322:         causal.opponent_first_contacts += u64::from(first.combatant_id != Some(john_id));
323:     }
324:     Ok(())
325: }

