132: fn record_autoresolve_outcome(
133:     batch: &mut AutoresolveBatch,
134:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
135:     john: &MeleeIterationBuild,
136:     opponent: &MeleeIterationBuild,
137: ) -> IterationResult<()> {
138:     match outcome.resolution {
139:         BattleResolution::AlliesVictory => batch.john_wins += 1,
140:         BattleResolution::EnemiesVictory => batch.opponent_wins += 1,
141:         BattleResolution::MutualIncapacitation => batch.mutual_incapacitations += 1,
142:         BattleResolution::Timeout => batch.timeouts += 1,
143:     }
144:     batch.causal.total_rounds += outcome.rounds as u64;
145:     batch.causal.john_yields += u64::from(outcome.allies[0].yielded);
146:     batch.causal.opponent_yields += u64::from(outcome.enemies[0].yielded);
147:     batch.causal.john.record_final(&outcome.allies[0])?;
148:     batch.causal.opponent.record_final(&outcome.enemies[0])?;
149:     record_final_totals(&mut batch.causal, outcome)?;
150:     record_autoresolve_log(
151:         &mut batch.causal,
152:         outcome,
153:         john.combatant.id,
154:         john.combatant.equipment.melee_weapon_id,
155:         opponent.combatant.equipment.melee_weapon_id,
156:     )?;
157:     record_autoresolve_timeline(&mut batch.causal, outcome, john.combatant.id)?;
158:     Ok(())
159: }
