161: fn record_final_totals(
162:     causal: &mut AutoresolveCausalSummary,
163:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
164: ) -> MeasurementResult<()> {
165:     for combatant in outcome.allies.iter().chain(&outcome.enemies) {
166:         causal.final_blood_loss_fraction.checked_add(
167:             Measurement::<BloodLossFraction>::from_native(combatant.blood_loss_fraction)?,
168:         )?;
169:         causal.final_wound_count += combatant.wound_count as u64;
170:         causal.final_open_wound_count += combatant.open_wound_count as u64;
171:         causal.final_internal_wound_count += combatant.internal_wound_count as u64;
172:         causal
173:             .final_wound_flow_fraction_per_second
174:             .checked_add(Measurement::<WoundFlowFractionPerSecond>::from_native(
175:                 combatant.wound_flow_fraction_per_second,
176:             )?)?;
177:         causal
178:             .final_fatigue
179:             .checked_add(Measurement::<Fatigue>::from_native(combatant.fatigue)?)?;
180:         causal
181:             .final_acute_trauma
182:             .checked_add(Measurement::<AcuteTrauma>::from_native(
183:                 combatant.acute_trauma,
184:             )?)?;
185:         causal
186:             .final_imbalance
187:             .checked_add(Measurement::<Imbalance>::from_native(combatant.imbalance)?)?;
188:     }
189:     Ok(())
190: }
191: 
192: fn record_autoresolve_log(
193:     causal: &mut AutoresolveCausalSummary,
194:     outcome: &adventuresim_core::autoresolve::BattleOutcome,
195:     john_id: u64,
196:     john_weapon_id: Option<u64>,
197:     opponent_weapon_id: Option<u64>,
198: ) -> IterationResult<()> {
199:     for entry in &outcome.log {
200:         if entry.attack_kind != BattleAttackKind::Melee {
201:             continue;
202:         }
203:         causal.melee_attacks += 1;
204:         let john_attacks = entry.attacker_id == john_id;
205:         causal.john_attacks += u64::from(john_attacks);
206:         causal.opponent_attacks += u64::from(!john_attacks);
207:         causal.hits += u64::from(matches!(
208:             entry.outcome,
209:             BattleAttackOutcome::HitHealth | BattleAttackOutcome::HitArmor
210:         ));
211:         causal.blocks_or_parries += u64::from(entry.outcome == BattleAttackOutcome::Blocked);
212:         causal.block_attempts += u64::from(entry.defender_response == MeleeResponseChoice::Block);
213:         causal.parry_attempts += u64::from(entry.defender_response == MeleeResponseChoice::Parry);
214:         causal.misses += u64::from(entry.outcome == BattleAttackOutcome::Missed);
215:         record_autoresolve_dodge(causal, entry);
216:         record_autoresolve_implement(causal, entry, john_id, john_weapon_id, opponent_weapon_id);
217:         record_autoresolve_armor(causal, entry);
218:         causal.total_contact_energy_joules.checked_add(
219:             Measurement::<ContactJoules>::from_native(entry.contact_stress)?,
220:         )?;

