253: fn maintain_guard_stance(
254:     mut guarded: Query<(&TacticalCombatState, &mut SkeletonState), With<RaisedGuardAi>>,
255: ) {
256:     for (state, mut skeleton) in &mut guarded {
257:         let guard = if state.is_incapacitated() {
258:             WeaponGuardState::Lowered
259:         } else {
260:             WeaponGuardState::Raised
261:         };
262:         set_weapon_guard(&mut skeleton, guard);
263:     }
264: }
