266: fn aim_at_nearest_opponent(
267:     candidates: Query<
268:         (
269:             Entity,
270:             &Transform,
271:             &TacticalCombatSide,
272:             &TacticalCombatState,
273:         ),
274:         With<Player>,
275:     >,
276:     mut aiming: Query<
277:         (
278:             Entity,
279:             &Transform,
280:             &TacticalCombatSide,
281:             &TacticalCombatState,
282:             &mut CharacterLook,
283:         ),
284:         With<AimAtNearestOpponentAi>,
285:     >,
286: ) {
287:     for (entity, transform, side, state, mut look) in &mut aiming {
288:         if state.is_incapacitated() {
289:             continue;
290:         }
291:         let nearest = candidates
292:             .iter()
293:             .filter(|(candidate, _, candidate_side, candidate_state)| {
294:                 *candidate != entity
295:                     && **candidate_side != *side
296:                     && !candidate_state.is_incapacitated()
297:             })
298:             .min_by(|(a, a_transform, _, _), (b, b_transform, _, _)| {
299:                 compare_target(transform, a_transform, *a, b_transform, *b)
300:             });
301:         let Some((_, target_transform, _, _)) = nearest else {
302:             continue;
303:         };
304:         let offset = target_transform.translation.xz() - transform.translation.xz();
305:         if offset.length_squared() > 0.0 {
306:             look.yaw = (-offset.x).atan2(-offset.y);
307:         }
308:     }
309: }
