10: pub(super) fn drive_ranged_pursuit(
11:     cmd: &mut Commands,
12:     pursuit: RangedPursuit,
13:     input: &mut AuthoritativeMovementIntent,
14:     controller: &mut OffensiveCombatAi,
15:     facts: &OffensiveFacts,
16:     config: &AiOffenseConfig,
17: ) -> ElapsedResult<()> {
18:     let standoff = (facts.weapon_reach * config.ranged_reach_fraction)
19:         .clamp(
20:             config.ranged_standoff_min_metres,
21:             config.ranged_standoff_max_metres,
22:         )
23:         .min(facts.weapon_reach);
24:     if pursuit.distance > facts.weapon_reach
25:         || pursuit.distance > standoff + config.ranged_standoff_slop_metres
26:     {
27:         input.0 = Some(Vec2::Y);
28:     } else if pursuit.distance + config.ranged_standoff_slop_metres < standoff {
29:         input.0 = Some(-Vec2::Y);
30:     } else {
31:         input.0 = None;
32:         let windup = CombatDuration::from_elapsed(config.windup_seconds)?;
33:         let timer = Timer::new(config.windup_seconds.native_duration()?, TimerMode::Once);
34:         cmd.trigger(RangedAttackStartedIntent {
35:             attacker: pursuit.entity,
36:             target: Some(pursuit.target),
37:             animation_windup: windup,
38:             minimum_windup: windup,
39:         });
40:         controller.phase = OffensiveCombatPhase::RangedWindup(timer);
41:     }
42:     Ok(())
43: }

