79:     let metal_weapon = striking_material.is_some_and(|material| material.is_metal());
80:     let sound = match result {
81:         AttackResult::ToAttacker {
82:             physical_contact: false,
83:             ..
84:         } => ImpactSound::None,
85:         AttackResult::ToAttacker { .. } if metal_weapon => ImpactSound::Metal,
86:         AttackResult::ToAttacker { .. } => ImpactSound::NonMetalWeapon,
87:         AttackResult::ToDefender {
88:             armor_impact: Some(impact),
89:             ..
90:         } if metal_weapon
91:             && impact
92:                 .surface
93:                 .material
