98:         AttackResult::ToDefender { .. } if striking_material.is_some() && !metal_weapon => {
99:             ImpactSound::NonMetalWeapon
100:         }
101:         AttackResult::ToDefender { cut_damage, .. } if cut_damage > 0.0 => ImpactSound::CutFlesh,
102:         AttackResult::ToDefender { .. } => ImpactSound::BluntFlesh,
103:     };
104:     ImpactEffects {
105:         metal_sparks: metal_weapon
