109:                     armor_impact: Some(impact),
110:                     ..
111:                 } if impact.surface.material.is_some_and(|material| material.is_metal())
112:             ),
113:         blood: matches!(result, AttackResult::ToDefender { cut_damage, .. } if cut_damage > 0.0),
114:         sound,
