257:     pub(crate) fn transform_attack_for_offhand_defense(
258:         &mut self,
259:         effectiveness: f32,
260:     ) -> Option<TransformedMeleeAttack> {
261:         let active = self.active.as_mut()?;
262:         let attack_key = self.windup.as_ref()?.attack_key;
263:         // Keeping the sword committed while the off hand intercepts costs
264:         // trunk rotation and grip support. A complete buckler interception
265:         // retains sixty percent of the already-worked strike; weaker contacts
266:         // disturb it proportionally less.
267:         let retained = 1.0 - 0.4 * effectiveness.clamp(0.0, 1.0);
268:         active.power_multiplier *= retained;
269:         Some(TransformedMeleeAttack {
270:             attack_key,
271:             retained_power: active.power_multiplier,
272:         })
273:     }
