290:     pub(crate) fn permits(&self, target: Entity, body_part: BodyPart, now: CombatInstant) -> bool {
291:         self.windup.as_ref().is_some_and(|windup| {
292:             windup.target.is_none_or(|observed| observed == target)
293:                 && windup
294:                     .body_part
295:                     .is_none_or(|observed| observed == body_part)
296:                 && now >= windup.ready_at
297:                 && now <= windup.expires_at
298:                 && now >= self.cooldown_until
299:         })
300:     }
301: 
302:     pub(super) fn reciprocal_attack_opportunity(
303:         &self,
304:         incoming_attacker: Entity,
305:         incoming_started_at: CombatInstant,
306:         now: CombatInstant,
307:         reflex_window: CombatDuration,
308:     ) -> Option<ReciprocalAttackOpportunity> {
309:         let active = self.active.as_ref()?;
310:         let windup = self.windup.as_ref()?;
311:         if active.target != Some(incoming_attacker) || active.started_at <= incoming_started_at {
312:             return None;
313:         }
314:         let delay = active.started_at.elapsed_since(incoming_started_at);
315:         let window = reflex_window.as_secs_f32();
316:         (delay.as_secs_f32() <= window).then(|| {
317:             let decision_sample = fabelgeist_determinism::Seed::derive(
318:                 &windup.attack_key.to_le_bytes(),
319:                 fabelgeist_determinism::StreamId::new("combat.reciprocal-attack"),
320:                 &[&active.started_at.native_nanos().to_le_bytes()],
321:             )
322:             .rng()
323:             .inclusive_unit_f32();
324:             ReciprocalAttackOpportunity {
325:                 input_reflex: (1.0 - delay.as_secs_f32() / window).clamp(0.0, 1.0),
326:                 precision: active.reported_precision,
327:                 own_contact_after_incoming_seconds: ContactTimingOffset::from(
328:                     windup.ready_at.elapsed_since(now),
329:                 ),
330:                 own_windup_seconds: AnimationElapsed::from(
331:                     windup.ready_at.elapsed_since(active.started_at),
332:                 ),
333:                 decision_sample,
334:                 consecutive_intercepts: self.consecutive_intercepts,
335:             }
336:         })
337:     }
338:     fn authorize(
339:         &mut self,
340:         target: Entity,
341:         body_part: BodyPart,
342:         now: CombatInstant,
343:         cooldown: CombatDuration,
344:     ) -> Option<f32> {
345:         let authorized = self.windup.as_ref().and_then(|windup| {
346:             (windup.target.is_none_or(|observed| observed == target)
347:                 && windup
348:                     .body_part
349:                     .is_none_or(|observed| observed == body_part)
350:                 && now >= windup.ready_at
351:                 && now <= windup.expires_at
352:                 && now >= self.cooldown_until)
353:                 .then(|| {
354:                     let active = self
355:                         .active
356:                         .as_ref()
357:                         .expect("an observed windup has active attack metadata");
358:                     active.power_multiplier
359:                 })
360:         });

361:         if authorized.is_some() {
362:             self.windup = None;
363:             self.active = None;
364:             self.cooldown_until = now + cooldown;
365:         }
366:         authorized
367:     }
368: }
