506: ) -> bool {
507:     let offset = target_position - origin;
508:     let distance = offset.length();
509:     let Ok(direction) = Dir3::new(offset) else {
510:         return false;
511:     };
512:     let excluded: Vec<_> = scene_items.iter().chain([attacker]).collect();
