31: impl PlannedMeleeLunge {
32:     fn admit(
33:         request: MeleeLungeRequest<'_>,
34:         config: &TacticalCombatConfig,
35:     ) -> AnimationValueResult<Self> {
36:         let reach = melee_interaction_range(
37:             request.attacker_dimensions.arm_reach_metres,
38:             request.weapon_reach_metres,
39:         );
