47:             ));
48:         let closure = (melee_surface_measure(
49:             request.attacker_position,
50:             request.target_transform.translation,
51:         ) - reach)
52:             .max(0.0);
53:         let movement = planned_melee_lunge(request, config);
54:         let lunge = match movement {
55:             Some(movement) if movement.quickstep => MeleeLunge::Quickstep {
56:                 distance_metres: movement.distance_metres,
57:             },
58:             Some(movement) => MeleeLunge::Forward {
59:                 distance_metres: movement.distance_metres,
60:             },
61:             None => MeleeLunge::None,
62:         };
63:         let arrival = melee_lunge_arrival(
64:             lunge,
65:             config.movement.speeds_metres_per_second.run,
66:             conservative_forward_lunge_acceleration(&config.movement.motor)?,
67:             config.movement.maneuvers.quickstep_duration_seconds,
68:         )?;
69:         let movement = match arrival {
70:             MeleeLungeArrival::CannotArrive => None,
71:             _ => movement,
72:         };
73:         Ok(Self {
74:             arrival,
75:             movement,
76:             reach,
77:             closure,
78:             maximum_travel,
79:         })
