129:     else {
130:         return Ok(None);
131:     };
132:     let dimensions = dimensions
133:         .get(request.attacker)
134:         .copied()
135:         .unwrap_or_default();
136:     Ok(Some(PlannedMeleeLunge::admit(
137:         MeleeLungeRequest {
138:             attacker_position: attacker_transform.translation,
139:             attacker_collider,
140:             attacker_dimensions: dimensions,
141:             target_transform,
