153: pub(super) fn planned_melee_lunge(
154:     request: MeleeLungeRequest<'_>,
155:     _config: &TacticalCombatConfig,
156: ) -> Option<MeleeLungeMovement> {
157:     let direction = (request.target_transform.translation - request.attacker_position)
158:         .xz()
159:         .normalize_or_zero();
160:     if direction == Vec2::ZERO {
161:         return None;
162:     }
163:     let arm_reach = request.attacker_dimensions.arm_reach_metres;
164:     let maximum_travel = request
165:         .quickstep_distance_metres
166:         .min(melee_collision_clearance(
167:             request.attacker_position,
168:             request.attacker_collider,
169:             request.target_transform,
170:             request.target_collider,
171:         ));
172:     let (distance_metres, quickstep) = match melee_lunge(
173:         melee_surface_measure(
174:             request.attacker_position,
175:             request.target_transform.translation,
176:         ),
177:         arm_reach,
178:         request.weapon_reach_metres,
179:         maximum_travel,
180:     ) {
181:         MeleeLunge::None => return None,
182:         MeleeLunge::Forward { distance_metres } => (distance_metres, false),
183:         MeleeLunge::Quickstep { distance_metres } => (distance_metres, true),
184:     };
185:     Some(MeleeLungeMovement {
186:         origin: request.attacker_position,
187:         direction,
188:         distance_metres,
189:         quickstep,
190:     })
191: }
192: 
193: pub(crate) fn melee_surface_measure(attacker_position: Vec3, target_position: Vec3) -> f32 {
194:     (attacker_position.xz().distance(target_position.xz())
195:         - adventuresim_core::combat::HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES)
196:         .max(0.0)
197: }
198: 
199: pub(crate) fn melee_collision_clearance(
200:     attacker_position: Vec3,
201:     attacker_collider: &Collider,
202:     target_transform: &Transform,
203:     target_collider: &Collider,
204: ) -> f32 {
205:     let a = attacker_collider.aabb(attacker_position, Rotation::default());
206:     let b = target_collider.aabb(
207:         target_transform.translation,
208:         Rotation(target_transform.rotation),
209:     );
210:     let ar = ((a.max - a.min) * 0.5).xz().max_element();
211:     let br = ((b.max - b.min) * 0.5).xz().max_element();
212:     (attacker_position
213:         .xz()
214:         .distance(target_transform.translation.xz())
215:         - ar
216:         - br)
217:         .max(0.0)
218: }
219: 
220: pub(crate) fn melee_target_reachable(request: MeleeLungeRequest<'_>) -> bool {

221:     let maximum_travel = request
222:         .quickstep_distance_metres
223:         .min(melee_collision_clearance(
224:             request.attacker_position,
225:             request.attacker_collider,
226:             request.target_transform,
227:             request.target_collider,
228:         ));
229:     melee_surface_measure(
230:         request.attacker_position,
231:         request.target_transform.translation,
232:     ) <= melee_interaction_range(
233:         request.attacker_dimensions.arm_reach_metres,
234:         request.weapon_reach_metres,
235:     ) + maximum_travel
236:         + 1.0e-5
237: }
238: 
239: pub(crate) fn melee_target_lunge_arrival(
240:     request: MeleeLungeRequest<'_>,
241:     config: &TacticalCombatConfig,
242: ) -> AnimationValueResult<Option<MeleeLungeArrival>> {
243:     if !melee_target_reachable(request) {
244:         return Ok(None);
245:     }
246:     Ok(Some(PlannedMeleeLunge::admit(request, config)?.arrival))
247: }
