255: pub(super) fn resolve_melee_attack(
256:     event: On<MeleeAttackIntent>,
257:     mut cmd: Commands,
258:     viewer: TacticalPlayerViewer,
259:     spatial: SpatialQuery,
260:     q_character: Query<(&CharacterLook, &Transform)>,
261:     q_dimensions: Query<&CharacterDimensions>,
262:     q_sides: Query<&TacticalCombatSide>,
263:     mut q_states: Query<&mut TacticalCombatState>,
264:     mut q_skeletons: Query<&mut SkeletonState>,
265:     mut q_authorities: Query<&mut MeleeAttackAuthority>,
266:     q_pending: Query<&PendingDefenderResponse>,
267:     q_scene_items: Query<Entity, With<TacticalSceneItem>>,
268:     time: Res<Time<()>>,
269:     config: Res<TacticalCombatConfig>,
270: ) {
271:     let attack_style = event.strike_family.melee_style();
272:     let entity = event.attacker;
273:     let hand = event.hand;
274:     let Ok(authority) = q_authorities.get(entity) else {
275:         info!(attacker = ?entity, reason = "missing_authority", "melee_completion_rejected");
276:         return;
277:     };
278:     let attack_key = authority.attack_key();
279: 
280:     let Ok(attacker_view) = viewer.get_for_attack(entity, hand).inspect_err(|err| {
281:         info!(attack_key = attack_key.map(MeleeAttackKey::encoded), attacker = ?entity, reason = %err, "melee_completion_rejected");
282:     }) else {
283:         return;
284:     };
285:     let Ok(defender_view) = viewer.get(event.target).inspect_err(|err| {
286:         info!(attack_key = attack_key.map(MeleeAttackKey::encoded), attacker = ?entity, target = ?event.target, reason = %err, "melee_completion_rejected");
287:     }) else {
288:         return;
289:     };
290: 
291:     let Ok([attacker_character, defender_character]) = q_character
292:         .get_many([entity, event.target])
293:         .inspect_err(|err| {
294:             info!(attack_key = attack_key.map(MeleeAttackKey::encoded), attacker = ?entity, target = ?event.target, reason = %err, "melee_completion_rejected");
295:         })
296:     else {
297:         return;
298:     };
299:     let (attacker_look, attacker_transform) = attacker_character;
300:     let (defender_look, defender_transform) = defender_character;
301: 
302:     let weapon_reach = attacker_view.weapon_reach();
303:     let Ok(attacker_dimensions) = q_dimensions.get(entity) else {
304:         info!(attack_key = attack_key.map(MeleeAttackKey::encoded), attacker = ?entity, reason = "missing_attacker_dimensions", "melee_completion_rejected");
305:         return;
306:     };
307:     let now = CombatInstant::from_elapsed(&time);
308:     let reach = melee_interaction_range(attacker_dimensions.arm_reach_metres, weapon_reach);
309:     let center_separation = attacker_transform
310:         .translation
311:         .xz()
312:         .distance(defender_transform.translation.xz());
313:     let surface_distance = (center_separation
314:         - adventuresim_core::combat::HUMANOID_MELEE_MINIMUM_CENTER_SEPARATION_METRES)
315:         .max(0.0);
316:     let contact_at_time = contact_at_completion(
317:         &attacker_view,
318:         authority,
319:         surface_distance,
320:         reach,
321:         attack_style,
322:         config.ai.ordinary.offense.melee_measure_reach_fraction,
323:     );
324:     let facts = completion_intent_facts(
325:         &event,
326:         &attacker_view,
327:         authority,
328:         attacker_look,
329:         attacker_transform,
330:         defender_look,
331:         defender_transform,
332:         attacker_dimensions,
333:         weapon_reach,
334:         surface_distance,
335:         now,
336:         &q_sides,
337:         &q_states,
338:         &config,
339:     );
340:     let contact_sample = event.contact_sample;
341:     let defense_alignment_sample = event.defense_alignment_sample;
342:     let Some(completion) = MeleeCompletion::prepare(
343:         facts,
344:         authority,
345:         &spatial,
346:         &q_scene_items,
347:         &config,
348:         attack_key,
349:         surface_distance,
350:         reach,
351:     ) else {
352:         return;
353:     };
354:     let (a2, a1) = completion.attack.attacker_yaw().sin_cos();
355:     let (d2, d1) = completion.attack.target_yaw().sin_cos();
356:     let flanking = flanking_from_dir((a1, a2), (d1, d2));
357:     let Some(attacker_side) = attacker_view.weapon_holding_side() else {
358:         info!(attack_key = attack_key.map(MeleeAttackKey::encoded), attacker = ?completion.attack.attacker(), target = ?completion.attack.target(), body_part = ?completion.attack.body_part, outcome = "failed", reason = "missing_striking_side", "melee_attack_resolved");
359:         return;
360:     };

