56: fn queue_equipment_action(
57:     request: On<FromClient<EquipmentActionRequest>>,
58:     mut pending: ResMut<PendingEquipmentActions>,
59: ) {
60:     let Some(controlled) = request.client_id.entity() else {
61:         warn!(
62:             client_id = ?request.client_id,
63:             actor = ?request.actor,
64:             sequence = request.sequence.encoded(),
65:             "Rejected tactical equipment action from a client without a controlled entity"
66:         );
67:         return;
68:     };
69:     if request.actor != controlled {
70:         warn!(
71:             ?controlled,
72:             requested_actor = ?request.actor,
73:             sequence = request.sequence.encoded(),
74:             action = ?request.action,
75:             "Rejected tactical equipment action for an uncontrolled actor"
76:         );
77:         return;
78:     }
79:     if !can_enqueue(&pending.0, controlled) {
80:         warn!(
81:             actor = ?controlled,
82:             sequence = request.sequence.encoded(),
83:             action = ?request.action,
84:             max_pending = MAX_PENDING_PER_ACTOR,
85:             "Rejected tactical equipment action because the actor queue is full"
86:         );
87:         return;
88:     }
89:     pending.0.push_back((controlled, **request));
90: }
91: 
92: fn can_enqueue(queue: &VecDeque<(Entity, EquipmentActionRequest)>, actor: Entity) -> bool {
93:     queue.iter().filter(|(queued, _)| *queued == actor).count() < MAX_PENDING_PER_ACTOR
94: }
