96: fn process_equipment_actions(
97:     mut commands: Commands,
98:     mut pending: ResMut<PendingEquipmentActions>,
99:     mut sequences: ResMut<LastEquipmentSequence>,
100:     players: Query<(&Transform, &CharacterLook), With<Player>>,
101:     mut action_states: Query<&mut EquipmentActionState>,
102:     items: Query<ItemView<'_>>,
103:     mut environment: EquipmentEnvironment,
104: ) {
105:     // Exactly one action is validated and committed per frame. Deferred ECS
106:     // mutations are therefore applied before another queued action can read
107:     // the actor's topology.
108:     let Some((controlled, request)) = pending.0.pop_front() else {
109:         return;
110:     };
111:     if request.actor != controlled {
112:         warn!(
113:             ?controlled,
114:             requested_actor = ?request.actor,
115:             sequence = request.sequence.encoded(),
116:             action = ?request.action,
117:             "Rejected queued tactical equipment action for an uncontrolled actor"
118:         );
119:         return;
120:     }

121:     if players.get(controlled).is_err() {
122:         warn!(
123:             actor = ?controlled,
124:             sequence = request.sequence.encoded(),
125:             action = ?request.action,
126:             "Rejected tactical equipment action because the controlled player is unavailable"
127:         );
128:         return;
129:     }
130:     let Ok(mut state) = action_states.get_mut(controlled) else {
131:         warn!(
132:             actor = ?controlled,
133:             sequence = request.sequence.encoded(),
134:             action = ?request.action,
135:             "Rejected tactical equipment action because authoritative action state is unavailable"
136:         );
137:         return;
138:     };
139:     let last = sequences.0.get(&controlled).copied();
140:     if !request.sequence.is_admissible_after(last) {
141:         warn!(
142:             actor = ?controlled,
143:             sequence = request.sequence.encoded(),
144:             last_sequence = ?last.map(EquipmentSequence::encoded),
145:             action = ?request.action,
146:             "Rejected stale or replayed tactical equipment action"
147:         );
148:         return;
149:     }
150:     if request.expected_revision != state.revision {
151:         warn!(
152:             actor = ?controlled,
153:             sequence = request.sequence.encoded(),
154:             expected_revision = request.expected_revision.encoded(),
155:             authoritative_revision = state.revision.encoded(),
156:             action = ?request.action,
157:             "Rejected tactical equipment action with a stale revision"
158:         );
159:         return;
160:     }
161:     let authoritative_hand_item = hand_item(controlled, request.hand, &items);
162:     if authoritative_hand_item != request.expected_hand_item {
163:         warn!(
164:             actor = ?controlled,
165:             sequence = request.sequence.encoded(),
166:             hand = ?request.hand,
167:             expected_hand_item = ?request.expected_hand_item,
168:             ?authoritative_hand_item,
169:             action = ?request.action,
170:             "Rejected tactical equipment action because the held item changed"
171:         );
172:         return;
173:     }
174: 
175:     let accepted = match request.action {
176:         EquipmentAction::Slot {
177:             location,
178:             depth,
179:             expected_destination,
180:         } => {
181:             let authoritative_destination = ordered_at_location(controlled, location, &items)
182:                 .get(depth as usize)
