186:                     actor = ?controlled,
187:                     sequence = request.sequence.encoded(),
188:                     ?location,
189:                     depth,
190:                     ?expected_destination,
191:                     ?authoritative_destination,
192:                     "Rejected tactical equipment slot action because the destination changed"
193:                 );
194:                 false
