297:             || vertical_alignment < MIN_VERTICAL_ALIGNMENT
298:         {
299:             warn!(
300:                 building_id = door.building_id.0,
301:                 opening_id = door.opening_id.0,
302:                 hinge_separation_metres = hinge_separation,
303:                 vertical_alignment,
304:                 position = ?position.0,
