265: fn hand_item(actor: Entity, hand: EquipmentHand, items: &Query<ItemView<'_>>) -> Option<Entity> {
266:     items
267:         .iter()
268:         .find_map(|(entity, _, owner, _, slot, _, scene, _)| {
269:             (!scene
270:                 && owner.is_some_and(|owner| owner.0 == actor)
271:                 && slot.is_some_and(|slot| *slot == hand.slot()))
