276: fn ordered_at_location(
277:     actor: Entity,
278:     location: EquipmentLocation,
279:     items: &Query<ItemView<'_>>,
280: ) -> Vec<ReachableTarget> {
281:     let mut found: Vec<_> = items
282:         .iter()
283:         .filter(|(_, _, owner, _, _, _, scene, _)| {
284:             !scene && owner.is_some_and(|owner| owner.0 == actor)
285:         })
286:         .filter_map(|(entity, properties, _, topology, _, _, _, _)| {
287:             topology
288:                 .root_order(location, &properties.id)
289:                 .map(|key| (key, entity))
290:         })
291:         .collect();
292:     found.sort_by_key(|(key, _)| *key);
293:     let mut reachable = Vec::new();
294:     let mut visited = HashSet::new();
295:     for (_, entity) in found {
296:         append_reachable(entity, location, items, &mut visited, &mut reachable);
297:     }
298:     reachable
299: }
300: 
301: #[derive(Clone, Debug, PartialEq, Eq)]
302: enum ReachableTarget {
303:     Occupied(Entity),
304:     EmptyAttachment {
305:         parent: Entity,
306:         attachment_point_id: String,
307:         channel: EquipmentChannel,
308:         capacity_index: u16,
309:     },
310: }
311: 
312: impl ReachableTarget {
313:     fn expected_entity(&self) -> Entity {
314:         match self {
315:             Self::Occupied(entity) => *entity,
316:             Self::EmptyAttachment { parent, .. } => *parent,
317:         }
318:     }
319: }
320: 
321: fn append_reachable(
322:     entity: Entity,
323:     location: EquipmentLocation,
324:     items: &Query<ItemView<'_>>,
325:     visited: &mut HashSet<Entity>,
326:     output: &mut Vec<ReachableTarget>,
327: ) {
328:     if !visited.insert(entity) {
329:         return;
330:     }
331:     let Ok((_, properties, _, _, _, _, _, _)) = items.get(entity) else {
332:         output.push(ReachableTarget::Occupied(entity));
333:         return;
334:     };
335:     let Some(equipment) = item_catalog::definition(&properties.id)
336:         .and_then(|definition| definition.equipment.as_ref())
337:     else {
338:         output.push(ReachableTarget::Occupied(entity));
339:         return;
340:     };
341:     let mut points: Vec<_> = equipment.attachment_points.iter().collect();
342:     points.sort_by_key(|point| (point.order, point.id.as_str()));
343:     for point in points
344:         .into_iter()
345:         .filter(|point| point.locations.is_empty() || point.locations.contains(&location))
346:     {
347:         for capacity_index in 0..point.capacity {
348:             let child = items
349:                 .iter()
350:                 .find_map(|(child, _, _, topology, _, _, _, _)| {
351:                     topology.occupancies.iter().any(|occupancy| {
352:                     matches!(
353:                         &occupancy.anchor,
354:                         TacticalEquipmentAnchor::ItemAttachment { parent, attachment_point_id }
355:                             if *parent == entity
356:                                 && attachment_point_id == &point.id
357:                                 && occupancy.capacity_index == capacity_index
358:                     )
359:                 }).then_some(child)
360:                 });

