407: fn placement_topology(item_id: &str, location: EquipmentLocation) -> Option<EquipmentTopology> {
408:     let definition = item_catalog::definition(item_id)?;
409:     let equipment = definition.equipment.as_ref()?;
410:     let placement = equipment.placements.iter().find(|placement| {
411:         placement.parents.is_empty()
412:             && placement
413:                 .occupancy
414:                 .iter()
415:                 .any(|requirement| requirement.location == location)
416:     })?;
417:     if !root_placement_allowed(item_id, placement) {
418:         return None;
419:     }
420:     Some(EquipmentTopology {
421:         placement_id: Some(placement.id.clone()),
422:         occupancies: placement
423:             .occupancy
424:             .iter()
425:             .enumerate()
426:             .map(|(index, requirement)| EquipmentTopologyOccupancy {
427:                 occupancy_id: format!("tactical:{item_id}:{}:{index}", placement.id),
428:                 anchor: TacticalEquipmentAnchor::CharacterLocation(requirement.location),
429:                 channel: requirement.channel,
430:                 order: requirement.order,
431:                 requirement_index: index as u16,
432:                 capacity_index: 0,
433:             })
434:             .collect(),
435:     })
436: }
