438: fn root_placement_allowed(item_id: &str, placement: &item_catalog::EquipmentPlacement) -> bool {
439:     if item_catalog::weapon_carry(item_id) != Some(item_catalog::WeaponCarry::HandOnly) {
440:         return true;
441:     }
442:     placement.parents.is_empty()
443:         && placement.occupancy.len() == 1
444:         && matches!(
445:             placement.occupancy[0].location,
446:             EquipmentLocation::LeftHand | EquipmentLocation::RightHand
447:         )
448:         && placement.occupancy[0].channel == EquipmentChannel::Held
449:         && placement.occupancy[0].order == 0
450: }
451: 
452: fn parent_placement_allowed(item_id: &str) -> bool {
453:     item_catalog::weapon_carry(item_id) != Some(item_catalog::WeaponCarry::HandOnly)
454: }
