287: /// requires a [`LoadFromPath`](bevy::asset::LoadFromPath) to resolve any
288: /// `Handle<T>` fields found while deserializing. None of the allowlisted
289: /// components in [`on_debug_dump_world_request`] hold asset handles, so this
290: /// should never actually be called.
291: #[cfg(feature = "debug")]
292: struct NoAssetHandlesInDump;
293: 
294: #[cfg(feature = "debug")]
295: impl bevy::asset::LoadFromPath for NoAssetHandlesInDump {
296:     fn load_from_path_erased(
297:         &mut self,
298:         _type_id: std::any::TypeId,
299:         _path: bevy::asset::AssetPath<'static>,
300:     ) -> bevy::asset::UntypedHandle {
301:         unimplemented!("world dumps do not contain asset handles")
302:     }
