166: pub(crate) struct TerminalCombatSnapshot {
167:     pub required_enemies: u32,
168:     pub loaded_enemies: u32,
169:     pub incapacitated_enemies: u32,
170:     pub loaded_party: u32,
171:     pub incapacitated_party: u32,
