1086: pub(crate) fn on_player_input(
1087:     input: On<FromClient<PlayerInputRequest>>,
1088:     viewer: TacticalPlayerViewer,
1089:     mut commands: Commands,
1090:     mut players: PlayerInputStateQuery<'_, '_>,
1091:     combat_config: Res<TacticalCombatConfig>,
1092: ) {
1093:     let Some(validated) = validate_player_input(**input) else {
1094:         return;
1095:     };
1096:     let Some(entity) = input.client_id.entity() else {
1097:         return;
1098:     };
1099:     let Ok((
1100:         mut accumulated_input,
1101:         mut look,
1102:         combat_state,
1103:         mut skeleton,
1104:         mut movement_intent,
1105:         input_tick,
1106:         mut posture_intent,
1107:         mut quickstep_push,
1108:         mut pace,
1109:         mut velocity,
1110:         mut transform,
1111:         mut physics_rotation,
1112:         startup_input_observed,
1113:     )) = players.get_mut(entity)
1114:     else {
1115:         return;
1116:     };
1117:     if let Some(mut newest) = input_tick
1118:         && !newest.accept(input.simulation_tick)
1119:     {
1120:         return;
1121:     }
1122:     let jump_requested =
1123:         sequence_is_newer(validated.jump.sequence, posture_intent.last_jump_sequence);
1124:     if jump_requested && let Some(direction) = validated.jump.quickstep {
1125:         info!(
1126:             target: "quickstep_trace",
1127:             ?entity,
1128:             simulation_tick = input.simulation_tick.encoded(),
1129:             sequence = validated.jump.sequence,
1130:             ?direction,
1131:             requested_guard = ?validated.weapon_guard,
1132:             server_guard = ?skeleton.weapon_guard(),
1133:             server_body = ?skeleton.body(),
1134:             server_action = ?skeleton.action_kind(),
1135:             push_active = quickstep_push.active,
1136:             "[quickstep][server-input] received new edge"
1137:         );
1138:     }
1139:     if jump_requested {
1140:         // Consume the edge even when the current body state cannot jump. The
1141:         // client repeats this sequence indefinitely, so retaining it through
1142:         // incapacitation or an airborne interval would create a stale jump
1143:         // as soon as the player became grounded again.
1144:         posture_intent.last_jump_sequence = validated.jump.sequence;
1145:     }
1146:     if combat_state.is_incapacitated() {
1147:         if jump_requested && validated.jump.quickstep.is_some() {
1148:             warn!(
1149:                 target: "quickstep_trace",
1150:                 ?entity,
1151:                 simulation_tick = input.simulation_tick.encoded(),
1152:                 sequence = validated.jump.sequence,
1153:                 "[quickstep][server-input] rejected: incapacitated"
1154:             );
1155:         }
1156:         accumulated_input.last_movement = None;
1157:         movement_intent.0 = None;
1158:         accumulated_input.jumped = None;
1159:         accumulated_input.crouched = false;
1160:         posture_intent.facing = CameraFacingIntent::Free;
1161:         quickstep_push.cancel();
1162:         skeleton.set_jump_anticipation(JumpAnticipation::Inactive);
1163:         set_weapon_guard(
1164:             &mut skeleton,
1165:             authoritative_weapon_guard(validated.weapon_guard, true),
1166:         );
1167:         return;
1168:     }
1169:     if !startup_input_observed {
1170:         info!("[startup] first server input received for {entity:?}");
1171:         commands.entity(entity).insert(StartupInputObserved);
1172:     }
1173:     trace!(
1174:         "DEBUG on_player_input entity={entity:?} input.look={:?} validated.yaw={}",
1175:         input.look,
1176:         validated.yaw.radians()
1177:     );
1178:     validated.write_look(&mut look);
1179:     accumulated_input.last_movement = validated.movement;
1180:     if sequence_is_newer(
1181:         validated.posture.sequence,
1182:         posture_intent.last_command_sequence,
1183:     ) {
1184:         posture_intent.last_command_sequence = validated.posture.sequence;
1185:         if let Some(action) = validated.posture.action
1186:             && let Some(launch) = apply_posture_action(
1187:                 action,
1188:                 &mut skeleton,
1189:                 &mut accumulated_input,
1190:                 validated.pace,
1191:                 &combat_config,
1192:             )
1193:         {
1194:             if launch.trajectory == DiveTrajectory::Airborne {
1195:                 // Airborne dive travel and authored direction both capture
1196:                 // this accepted camera frame before transition facing locks.
1197:                 let launch_rotation = dive_launch_root_rotation(Quat::from_rotation_y(look.yaw));
1198:                 transform.rotation = launch_rotation;
1199:                 physics_rotation.0 = launch_rotation;
1200:             }

1201:             // A slide inherits an already-committed sprint heading and exact
1202:             // velocity. Rewriting its root to camera yaw would twist the whole
1203:             // body on the first frame, independently of its inverted animation.
1204:             apply_dive_launch_velocity(
1205:                 &mut velocity,
