1564: /// Rehydrates Ahoy's disposable fixed-loop input from the latest accepted
1565: /// complete request before movement runs. Ahoy may clear its accumulator after
1566: /// every fixed loop without turning a missing network packet into a stop.
1567: pub(crate) fn restore_authoritative_movement_intent(
1568:     mut players: MovementIntentQuery<'_, '_>,
1569:     combat_config: Res<TacticalCombatConfig>,
1570: ) {
1571:     for (
1572:         movement_intent,
1573:         skeleton,
1574:         posture,
1575:         quickstep_push,
1576:         controller,
1577:         transform,
1578:         mut accumulated_input,
1579:     ) in &mut players
1580:     {
1581:         accumulated_input.last_movement = movement_intent.0;
1582:         if quickstep_push.active {
1583:             // The supported force phase commits to its accepted direction.
1584:             accumulated_input.last_movement = Some(skeleton.action_direction());
1585:         }
1586:         if skeleton.body().is_downed()
1587:             && let (Some(controller), Some(transform), Some(movement)) =
1588:                 (controller, transform, accumulated_input.last_movement)
1589:         {
1590:             accumulated_input.last_movement = Some(downed_tank_controller_input(
1591:                 movement,
1592:                 skeleton.body(),
1593:                 transform.rotation,
1594:                 controller.orientation,
1595:                 combat_config.movement.prone_lateral_speed_scale,
1596:             ));
1597:         }
1598:         if skeleton.body() == BodyState::Prone && posture.facing == CameraFacingIntent::Aim {
1599:             accumulated_input.last_movement = None;
1600:         }
1601:         accumulated_input.crouched =
1602:             skeleton.body().is_downed() || skeleton.is_posture_transitioning();
1603:         let roll_motion = skeleton.downed_lateral_motion();
1604:         if roll_motion.is_moving() {
1605:             accumulated_input.last_movement = match (controller, transform) {
1606:                 (Some(controller), Some(transform)) => Some(body_relative_controller_input(
1607:                     Vec3::new(-roll_motion.fraction(), 0.0, 0.0),
1608:                     transform.rotation,
1609:                     controller.orientation,
1610:                 )),
1611:                 _ => Some(Vec2::X * roll_motion.fraction()),
1612:             };
1613:         } else if skeleton.is_posture_transitioning() {
1614:             accumulated_input.last_movement = None;
1615:         }
1616:     }
1617: }
