1901:     requested: CharacterId,
1902:     supplied: Option<ReconnectToken>,
1903:     existing: &mut DisconnectedPlayer,
1904: ) -> bool {
1905:     if !reconnect_matches(requested, supplied, existing) {
1906:         return false;
1907:     }
1908:     // Immediate mutation serializes duplicate ordered events even though the
1909:     // component moves below are deferred until the command queue is applied.
1910:     existing.claimed = true;
