1957: pub(crate) fn expire_disconnected_players(
1958:     time: Res<Time>,
1959:     mut commands: Commands,
1960:     mut disconnected: Query<(Entity, &mut DisconnectedPlayer)>,
1961:     items: Query<(Entity, &ItemOf)>,
1962:     mut pending_actions: ResMut<PendingEquipmentActions>,
1963:     mut action_sequences: ResMut<LastEquipmentSequence>,
1964:     conn: Res<SpacetimeDb>,
1965: ) {
1966:     for (entity, mut grace) in &mut disconnected {
1967:         // A successful reconnect synchronously owns this root. Its deferred
1968:         // moves must complete before any expiry teardown can touch it.
1969:         if grace.claimed {
1970:             continue;
1971:         }
1972:         grace.remaining_secs -= time.delta_secs();
1973:         if grace.remaining_secs > 0.0 {
1974:             continue;
1975:         }
1976:         if let Err(error) = conn.reducers().leave_mission(grace.character_id.0) {
1977:             warn!(
1978:                 character_id = grace.character_id.0,
1979:                 ?error,
1980:                 "Failed to expire disconnected mission member"
1981:             );
1982:             continue;
1983:         }
1984:         for (item, owner) in &items {
1985:             if owner.0 == entity {
1986:                 commands.entity(item).despawn();
1987:             }
1988:         }
1989:         purge_equipment_lifecycle(entity, &mut pending_actions, &mut action_sequences);
1990:         commands.entity(entity).despawn();
1991:     }
1992: }
