1994: /// Fires whenever `Player` lands on any entity - via the normal
1995: /// SpacetimeDB-driven [`spawn_connected_player`], a loaded world dump
1996: /// (`load_world_dump`), or a dump-to-live-client merge
1997: /// (`bind_dumped_character_on_join`). Adds everything a character always
1998: /// needs that is never part of its actual data: mid-action authority/
1999: /// cooldown state (correctly starts neutral regardless of source), the
2000: /// physics/controller bundle (colliders aren't reflectable - see
2001: /// `avian3d::Collider`), and the replication marker. This is what lets both
2002: /// SpacetimeDB rows and world dumps carry only "core" reflectable character
2003: /// data (`Player`, `CharacterId`, `Skills`, `Limbs`, `TacticalAttributes`, `Stats`,
2004: /// `TacticalCombatState`, `TacticalCombatSide`, `Transform`) instead of a
2005: /// full component-for-component bundle.
2006: pub(crate) fn on_player_added(
2007:     event: On<Add, Player>,
2008:     mut commands: Commands,
2009:     query: Query<(&Player, &CharacterId)>,
2010: ) -> Result {
2011:     let (player, character_id) = query.get(event.entity)?;
2012:     commands.entity(event.entity).insert_if_new((
2013:         Name::new(format!("Character#{} {}", character_id.0, player.name)),
2014:         Replicated,
2015:         BestiaryCategories::default(),
2016:         MeleeAttackAuthority::default(),
2017:         RangedAttackAuthority::default(),
2018:         player_collider(),
2019:         CollisionMargin(0.01),
2020:         tactical_character_controller(),
2021:         CharacterLook::default(),
2022:         AuthoritativeMovementIntent::default(),
2023:         AuthoritativeInputTick::default(),
2024:         CharacterMotionSnapshot::default(),
2025:         QuickstepPush::default(),
2026:         DoorPassageExemptions::default(),
2027:     ));
2028:     Ok(())
2029: }
2030: 
2031: /// Marks every scene-written inventory item as [`Replicated`]. `Replicated`
2032: /// is deliberately outside the dump's core-data allowlist (a replication-
2033: /// transport concern, not character/level data - see
2034: /// `dump_request_excludes_reflected_components_outside_the_core_allowlist`),
2035: /// so a dump-loaded item never carries it - without this, such an item
2036: /// exists server-side but never replicates to any client. Called by the two
2037: /// scene-writing paths (`load_world_dump`, [`bind_dumped_character_on_join`])
2038: /// right where they add the other things a dump deliberately
2039: /// omits (see `insert_fresh_combatant_extras`); the live SpacetimeDB spawn
2040: /// path inserts `Replicated` explicitly at spawn like everything else it

2041: /// spawns.
2042: #[cfg(feature = "debug")]
2043: pub(crate) fn mark_loaded_items_replicated<'a>(
2044:     world: &mut World,
2045:     loaded: impl Iterator<Item = &'a Entity>,
2046: ) {
2047:     for &entity in loaded {
2048:         let Ok(mut entity_mut) = world.get_entity_mut(entity) else {
2049:             continue;
2050:         };
2051:         if entity_mut.contains::<ItemOf>() {
2052:             entity_mut.insert(Replicated);
2053:         }
2054:     }
2055: }
2056: 
2057: /// Standalone-mode-only: turns a [`LoadingPlayer`] into a real character by
2058: /// finding an existing entity with a matching [`CharacterId`] (the world
2059: /// dump's placeholder for that character) and transplanting its reflected
2060: /// components directly onto the joining client's connection entity, in one
2061: /// atomic operation - no other system observes a half-merged entity.
2062: ///
2063: /// Reuses the same `DynamicSceneBuilder`/`EntityHashMap` trick as
2064: /// `load_world_dump`, just pre-seeding the map with `template -> client`
2065: /// instead of letting it allocate a fresh entity.
2066: #[cfg(feature = "debug")]
2067: pub(crate) fn bind_dumped_character_on_join(world: &mut World) {
2068:     let loading: Vec<(Entity, CharacterId)> = world
2069:         .query::<(Entity, &LoadingPlayer)>()
2070:         .iter(world)
2071:         .map(|(entity, loading)| (entity, loading.requested_character))
2072:         .collect();
2073:     if loading.is_empty() {
2074:         return;
2075:     }
2076:     let mut templates: Vec<(Entity, CharacterId)> = world
2077:         .query_filtered::<(Entity, &CharacterId), Without<LoadingPlayer>>()
2078:         .iter(world)
2079:         .map(|(entity, id)| (entity, *id))
2080:         .collect();
2081: 
2082:     for (client_entity, character_id) in loading {
2083:         let Some(index) = templates.iter().position(|(_, id)| *id == character_id) else {
2084:             warn!(
2085:                 character_id = character_id.0,
2086:                 "No dumped character found for joining client; join stays pending"
2087:             );
2088:             continue;
2089:         };
2090:         let (template_entity, _) = templates.swap_remove(index);
2091: 
2092:         // Inventory items are separate entities linked via `ItemOf`, not
2093:         // part of the character entity itself - they must be extracted
2094:         // alongside it or they're silently left behind.
2095:         let item_entities: Vec<Entity> = world
2096:             .query::<(Entity, &ItemOf)>()
2097:             .iter(world)
2098:             .filter_map(|(entity, item_of)| (item_of.0 == template_entity).then_some(entity))
2099:             .collect();
2100: 
2101:         let registry = world.resource::<AppTypeRegistry>().0.clone();
2102:         let scene = {
2103:             let registry = registry.read();
2104:             bevy::world_serialization::DynamicWorldBuilder::from_world(world, &registry)
2105:                 .extract_entities(core::iter::once(template_entity).chain(item_entities))
2106:                 .build()
2107:         };
2108:         let mut entity_map = bevy::ecs::entity::EntityHashMap::default();
2109:         entity_map.insert(template_entity, client_entity);
2110:         match scene.write_to_world(world, &mut entity_map) {
2111:             Ok(()) => {
2112:                 world.despawn(template_entity);
2113:                 world.entity_mut(client_entity).remove::<LoadingPlayer>();
2114:                 // `write_to_world` inserted `Player` directly (not via
2115:                 // `Commands`), which still triggers `on_player_added`
2116:                 // synchronously, but that observer's own `Commands` calls
2117:                 // need an explicit flush to actually land before anything
2118:                 // else in this same exclusive system reads the entity.
2119:                 world.flush();
2120:                 // `on_player_added`'s generic bundle (fired by the `Player`
2121:                 // insert just above) adds most "always fresh, never
2122:                 // dump-captured" extras, but not these two - unlike
2123:                 // `spawn_connected_player`'s normal-join path, which inserts
2124:                 // them explicitly. Their absence doesn't fail loudly: it
2125:                 // just makes `on_player_input`'s query silently never match
2126:                 // this entity, so the joined client's ordinary per-frame
2127:                 // input (movement, look, everything) is dropped forever -
2128:                 // confirmed live, traced through many layers of downstream
2129:                 // symptoms (wrong facing, bots never reacting) before
2130:                 // finding this root cause.
2131:                 world.entity_mut(client_entity).insert((
2132:                     AuthoritativePostureIntent::default(),
2133:                     MovementPace::default(),
2134:                 ));
2135:                 mark_loaded_items_replicated(world, entity_map.values());
2136:                 info!(
2137:                     character_id = character_id.0,
2138:                     "Bound joining client to dumped character"
2139:                 );
2140:             }
2141:             Err(error) => error!(
2142:                 ?error,
2143:                 character_id = character_id.0,
2144:                 "Failed to bind dumped character to joining client"
2145:             ),
2146:         }
2147:     }
2148: }
