 1: use crate::scene_spawn::SceneSpawnResult;
 2: use adventuresim_building_generator::spatial_geometry::Position;
 3: use adventuresim_tactical_core::{
 4:     prelude::*,
 5:     scene_coordinates::{Scene, ScenePlanPoint},
 6: };
 7: use adventuresim_tactical_netcode::bevy_replicon::prelude::Replicated;
 8: use bevy::prelude::*;
 9: 
10: struct AdmittedObstacle {
11:     kind: SceneObstacle,
12:     collider: Collider,
13:     position: Position<Scene>,
14:     rotation: Quat,
15: }
16: 
17: impl AdmittedObstacle {
18:     fn from_generated(
19:         obstacle: GeneratedObstacle,
20:         terrain: &SceneTerrain,
21:         obstacle_spacing: f32,
22:     ) -> SceneSpawnResult<Self> {
23:         let (grid_x, grid_z, kind, collider, height_offset) = match obstacle {
24:             GeneratedObstacle::Tree { x, z } => (
25:                 x,
26:                 z,
27:                 SceneObstacle::Tree,
28:                 Collider::cylinder(TREE_TRUNK_RADIUS_METRES, TREE_TRUNK_HEIGHT_METRES),
29:                 TREE_TRUNK_HEIGHT_METRES * 0.5,
30:             ),
31:             GeneratedObstacle::Rock { x, z, recipe } => (
32:                 x,
33:                 z,
34:                 SceneObstacle::Rock(recipe),
35:                 Collider::sphere(recipe.collision_radius_metres()),
36:                 recipe.collision_radius_metres(),
37:             ),
38:         };
39:         // Decode the serialized grid ordinals into scene-local metres here;
40:         // preserve multiply-then-subtract rounding at this recipe boundary.
41:         let x = f32::from(grid_x) * obstacle_spacing - terrain.width() * 0.5;
42:         let z = f32::from(grid_z) * obstacle_spacing - terrain.depth() * 0.5;
43:         let point = ScenePlanPoint::try_from(Vec2::new(x, z))?;
44:         let elevation = terrain.required_height_at(point)?;
45:         let position = Position::from_metres(Vec3::new(x, elevation.metres() + height_offset, z))?;
46:         let yaw = match kind {
47:             SceneObstacle::Rock(recipe) => {
48:                 (recipe.seed.to_u64() >> 40) as f32 / ((1_u32 << 24) - 1) as f32
49:                     * core::f32::consts::TAU
50:             }
51:             SceneObstacle::Tree => 0.0,
52:         };
53:         Ok(Self {
54:             kind,
55:             collider,
56:             position,
57:             rotation: Quat::from_rotation_y(yaw),
58:         })
59:     }
60: }
61: 
62: pub(crate) fn spawn(
63:     commands: &mut Commands,
64:     obstacles: Vec<GeneratedObstacle>,
65:     terrain: &SceneTerrain,
66:     obstacle_spacing: f32,
67: ) -> SceneSpawnResult<()> {
68:     let admitted = obstacles
69:         .into_iter()
70:         .map(|obstacle| AdmittedObstacle::from_generated(obstacle, terrain, obstacle_spacing))
71:         .collect::<SceneSpawnResult<Vec<_>>>()?;
72:     for obstacle in admitted {
73:         let label = match obstacle.kind {
74:             SceneObstacle::Tree => "tree trunk",
75:             SceneObstacle::Rock(_) => "rock",
76:         };
77:         commands.spawn((
78:             Replicated,
79:             Name::new(format!("Tactical scene {label}")),
80:             obstacle.kind,
81:             RigidBody::Static,
82:             CollisionLayers::new(TACTICAL_TERRAIN_LAYER, LayerMask::ALL),
83:             obstacle.collider,
84:             Transform::from_translation(obstacle.position.metres())
85:                 .with_rotation(obstacle.rotation),
86:         ));
87:     }
88:     Ok(())
89: }

  1: //! Admit the complete applicable connected-player batch before any entity commands.
  2: 
  3: use super::{LoadingPlayer, player_collider, spawn_connected_player};
  4: use crate::{
  5:     Args,
  6:     bot::CombatantBehaviorPackages,
  7:     scene_spawn::{SceneSpawnError, SceneSpawnResult},
  8: };
  9: use adventuresim_building_generator::spatial_geometry::{Position, SignedLength};
 10: use adventuresim_stdb_client::*;
 11: use adventuresim_tactical_core::{
 12:     prelude::*,
 13:     scene_coordinates::{Scene, ScenePlanPoint},
 14: };
 15: use bevy::prelude::*;
 16: 
 17: pub(super) struct PreparedPlayerSpawns(Vec<AdmittedPlayer>);
 18: 
 19: pub(super) struct AdmittedPlayer {
 20:     pub(super) player: ConnectedPlayer,
 21:     pub(super) recipient: SpawnRecipient,
 22:     pub(super) position: Position<Scene>,
 23:     pub(super) collider: Collider,
 24: }
 25: 
 26: pub(super) enum SpawnRecipient {
 27:     Loading(Entity),
 28:     Enemy(CombatantBehaviorPackages),
 29: }
 30: 
 31: impl PreparedPlayerSpawns {
 32:     pub(super) fn prepare(
 33:         players: Vec<ConnectedPlayer>,
 34:         loading: &Query<(Entity, &LoadingPlayer)>,
 35:         terrain: &SceneTerrain,
 36:         args: &Args,
 37:         combat: &TacticalCombatConfig,
 38:     ) -> SceneSpawnResult<Self> {
 39:         let mut admitted = Vec::with_capacity(players.len());
 40:         for player in players {
 41:             let recipient = if player.mission_side == TacticalMissionSide::Enemy {
 42:                 let packages = if let Some(fixture) = args.enemy_fixture.as_ref() {
 43:                     let enemy = fixture.enemy_named(&player.character.name).ok_or(
 44:                         SceneSpawnError::MissingEnemyFixture {
 45:                             character: CharacterId(player.character.id),
 46:                         },
 47:                     )?;
 48:                     CombatantBehaviorPackages::from_fixture(enemy.behavior, combat)
 49:                 } else if args.enemy_combat_scale_bps > 0 {
 50:                     CombatantBehaviorPackages::standard_combat(combat)
 51:                 } else {
 52:                     CombatantBehaviorPackages::passive()
 53:                 };
 54:                 SpawnRecipient::Enemy(packages)
 55:             } else {
 56:                 let Some((entity, _)) = loading
 57:                     .iter()
 58:                     .find(|(_, id)| id.requested_character.0 == player.character.id)
 59:                 else {
 60:                     warn!(
 61:                         "Got new ConnectedPlayer from stdb, but there is no LoadingPlayer for it: {}#{}",
 62:                         player.character.name, player.character.id
 63:                     );
 64:                     continue;
 65:                 };
 66:                 SpawnRecipient::Loading(entity)
 67:             };
 68:             let collider = player_collider();
 69:             let mut random = fabelgeist_determinism::StreamId::new("tactical.player-spawn")
 70:                 .rng(player.character.id.into(), &[]);
 71:             let point = ScenePlanPoint::try_from(Vec2::new(
 72:                 random.range_f32(-5.0, 5.0),
 73:                 random.range_f32(-5.0, 5.0),
 74:             ))?;
 75:             let elevation = terrain.required_height_at(point)?;
 76:             let offset = player_spawn_offset(&collider)?;
 77:             let position = Position::from_metres(Vec3::new(
 78:                 point.metres().x,
 79:                 elevation.metres() + offset.metres(),
 80:                 point.metres().y,
 81:             ))?;
 82:             admitted.push(AdmittedPlayer {
 83:                 player,
 84:                 recipient,
 85:                 position,
 86:                 collider,
 87:             });
 88:         }
 89:         Ok(Self(admitted))
 90:     }
 91: 
 92:     pub(super) fn project(
 93:         self,
 94:         args: &Args,
 95:         commands: &mut Commands,
 96:         combat: &TacticalCombatConfig,
 97:     ) {
 98:         for admitted in self.0 {
 99:             spawn_connected_player(admitted, args.enemy_combat_scale_bps, commands, combat);
100:         }
101:     }
102: }
103: 
104: fn player_spawn_offset(collider: &Collider) -> SceneSpawnResult<SignedLength> {
105:     Ok(SignedLength::from_metres(
106:         -collider.aabb(default(), Rotation::default()).min.y,
107:     )?)
108: }

