24: pub(crate) fn authoritative_terrain<'a>(
25:     terrains: &'a Query<&SceneTerrain>,
26: ) -> SceneSpawnResult<Option<&'a SceneTerrain>> {
27:     let mut terrains = terrains.iter();
28:     let first = terrains.next();
29:     if terrains.next().is_some() {
30:         return Err(SceneSpawnError::AmbiguousTerrain);
31:     }
32:     Ok(first)
33: }

