 45: /// Everything `main` needs loaded and validated before it builds the app.
 46: pub(crate) struct StartupInputs {
 47:     pub(crate) scene: TacticalSceneInput,
 48:     pub(crate) combat: TacticalCombatConfig,
 49: }
 50: 
 51: impl StartupInputs {
 52:     /// Loads both inputs, falling back to the committed defaults, and installs
 53:     /// the combat runtime snapshot the simulation reads from. The error already
 54:     /// names which input was rejected.
 55:     pub(crate) fn load(scene: Option<&Path>, combat: Option<&Path>) -> Result<Self, String> {
 56:         let scene_path = scene.map_or_else(default_scene_input_path, Path::to_path_buf);
 57:         let scene = TacticalSceneInput::load(&scene_path)
 58:             .map_err(|error| format!("tactical scene input: {error}"))?;
 59:         let combat_path = combat.map_or_else(default_combat_config_path, Path::to_path_buf);
 60:         let combat = load_combat_config(&combat_path)
 61:             .map_err(|error| format!("tactical combat config: {error}"))?;
 62:         combat
 63:             .install_runtime_snapshot()
 64:             .expect("loaded tactical combat config was validated");
 65:         let digest = combat
 66:             .digest()
 67:             .expect("loaded tactical combat config was validated");
 68:         eprintln!(
 69:             "[startup] tactical combat config path={} digest={digest}",
 70:             combat_path.display()
 71:         );
 72:         Ok(Self { scene, combat })
 73:     }
 74: }
