 5: pub(super) fn colliders(
 6:     terrain: &SceneTerrain,
 7:     recipe: Option<&TerrainLandformRecipe>,
 8:     prepared: Option<&SceneTerrainPatch>,
 9: ) -> Result<Vec<Collider>> {
10:     if let Some(patch) = prepared {
11:         return Ok(patch.colliders_with_terrain(terrain)?);
12:     }
13:     let Some(recipe) = recipe else {
14:         return Ok(terrain.colliders()?);
15:     };
16:     let patch = terrain_landform_patch(terrain, *recipe)?;
17:     Ok(patch.colliders_with_terrain(terrain)?)
18: }
