 36: impl WindowGrabber<'_, '_> {
 37:     pub(crate) fn try_toggle_from_inside(&mut self, actor: Entity, window_entity: Entity) -> bool {
 38:         let Ok(actor_transform) = self.characters.get(actor) else {
 39:             return false;
 40:         };
 41:         let Ok((window, mut controller)) = self.windows.get_mut(window_entity) else {
 42:             return false;
 43:         };
 44:         if !can_grab_window_from_inside(
 45:             actor_transform.translation,
 46:             window.opening_centre_metres.metres(),
 47:             window.tangent.vector(),
 48:             window.outward.vector(),
 49:             window.size_metres.metres().x * 0.5,
 50:         ) {
 51:             return false;
 52:         }
 53:         controller.open = !controller.open;
 54:         debug!(
 55:             actor = ?actor,
 56:             window = ?window_entity,
 57:             building_id = window.building_id.0,
 58:             opening_id = window.opening_id.0,
 59:             open = controller.open,
 60:             "Toggled interior window catch"
 61:         );
 62:         true
 63:     }
