 12: use tiff::decoder::{Decoder, DecodingResult};
 13: 
 14: mod features;
 15: pub use features::Features;
 16: 
 17: pub fn build(
 18:     elevation_dir: &Path,
 19:     forest_dir: &Path,
 20:     bounds: [f64; 4],
 21:     manifest_path: &Path,
 22:     pack_path: &Path,
 23:     features: &Features,
 24:     purpose: TerrainPurpose,
 25: ) -> crate::Result<Manifest> {
 26:     let [west, south, east, north] = bounds;
 27:     if !bounds.into_iter().all(f64::is_finite) || west >= east || south >= north {
 28:         return Err(crate::Error::Validation(
 29:             "invalid terrain build bounds".into(),
 30:         ));
 31:     }
 32:     let source_bounds = [
 33:         west.floor() as i16,
 34:         south.floor() as i16,
 35:         east.ceil() as i16,
 36:         north.ceil() as i16,
 37:     ];
 38:     let (mut entries, mut pack) = (Vec::new(), Vec::new());
 39:     let mut cultivated_native_cells = 0_u64;
 40:     for south in source_bounds[1]..source_bounds[3] {
 41:         for west in source_bounds[0]..source_bounds[2] {
 42:             let path = elevation_path(elevation_dir, south, west)?;
 43:             let (width, height, elevations, synthetic_water) = if path.is_file() {
 44:                 let mut decoder = Decoder::new(BufReader::new(File::open(&path)?))
 45:                     .map_err(|error| crate::Error::Validation(error.to_string()))?;
 46:                 let (width, height) = decoder
 47:                     .dimensions()
 48:                     .map_err(|error| crate::Error::Validation(error.to_string()))?;
 49:                 if ![1_800, 2_400, 3_600].contains(&width) || height != 3_600 {
 50:                     return Err(crate::Error::Validation(format!(
 51:                         "{} is not a native GLO-30 tile",
 52:                         path.display()
 53:                     )));
 54:                 }
 55:                 let DecodingResult::F32(elevations) = decoder
 56:                     .read_image()
 57:                     .map_err(|error| crate::Error::Validation(error.to_string()))?
 58:                 else {
 59:                     return Err(crate::Error::Validation(format!(
 60:                         "{} is not Float32",
 61:                         path.display()
 62:                     )));
 63:                 };
 64:                 if elevations.len() != width as usize * height as usize {
 65:                     return Err(crate::Error::Validation(format!(
 66:                         "{} is truncated",
 67:                         path.display()
 68:                     )));
 69:                 }
 70:                 (width, height, Some(elevations), false)
 71:             } else if is_known_offshore_gap(south, west) {
 72:                 // The initialized request intentionally omits five all-water
 73:                 // North Sea cells. Preserve the native latitude-band geometry
 74:                 // and mark them impassable without inventing terrain heights.
 75:                 (2_400, 3_600, None, true)
 76:             } else {
 77:                 return Err(crate::Error::Validation(format!(
 78:                     "missing {}",
 79:                     path.display()
