452: fn polygon_bounds(polygon: &[Vec<[f64; 2]>]) -> Option<[f64; 4]> {
453:     let mut points = polygon.iter().flatten();
454:     let first = *points.next()?;
455:     let mut bounds = [first[0], first[1], first[0], first[1]];
456:     for point in points {
457:         bounds[0] = bounds[0].min(point[0]);
458:         bounds[1] = bounds[1].min(point[1]);
459:         bounds[2] = bounds[2].max(point[0]);
460:         bounds[3] = bounds[3].max(point[1]);
461:     }
462:     Some(bounds)
463: }
