156: pub(crate) fn subdivide<const N: usize>(points: &[[f64; N]], maximum_chord: f64) -> Vec<[f64; N]> {
157:     let mut result = vec![points[0]];
158:     for pair in points.windows(2) {
159:         let [a, b] = [pair[0], pair[1]];
160:         let length = (0..N).map(|i| (b[i] - a[i]).powi(2)).sum::<f64>().sqrt();
161:         let count = (length / maximum_chord).ceil().max(1.0) as usize;
162:         for i in 1..=count {
163:             let t = i as f64 / count as f64;
164:             result.push(std::array::from_fn(|axis| {
165:                 a[axis] + (b[axis] - a[axis]) * t
166:             }));
167:         }
168:     }
169:     result
170: }

