 25: fn point_segment_distance(p: PlanarPoint, a: PlanarPoint, b: PlanarPoint) -> f64 {
 26:     let delta = [b[0] - a[0], b[1] - a[1]];
 27:     let denominator = delta[0] * delta[0] + delta[1] * delta[1];
 28:     let t = if denominator == 0.0 {
 29:         0.0
 30:     } else {
 31:         ((p[0] - a[0]) * delta[0] + (p[1] - a[1]) * delta[1]) / denominator
 32:     }
 33:     .clamp(0.0, 1.0);
 34:     (p[0] - a[0] - delta[0] * t).hypot(p[1] - a[1] - delta[1] * t)
 35: }
 36: 
 37: fn refine(
 38:     evaluate: &impl Fn(f64) -> PlanarPoint,
 39:     quality: CurveQuality,
 40:     samples: &mut Vec<PlanarPoint>,
 41:     span: [f64; 2],
 42:     ends: [PlanarPoint; 2],
 43:     depth: usize,
 44: ) {
 45:     let [t0, t1] = span;
 46:     let [p0, p1] = ends;
 47:     let midpoint_t = (t0 + t1) / 2.0;
 48:     let midpoint = evaluate(midpoint_t);
 49:     let chord = (p1[0] - p0[0]).hypot(p1[1] - p0[1]);
 50:     let deviation = [
 51:         evaluate(t0 * 0.75 + t1 * 0.25),
 52:         midpoint,
 53:         evaluate(t0 * 0.25 + t1 * 0.75),
 54:     ]
 55:     .into_iter()
 56:     .map(|p| point_segment_distance(p, p0, p1))
 57:     .fold(0.0, f64::max);
 58:     if depth < 8 && (chord > quality.max_chord || deviation > quality.max_deviation) {
 59:         refine(
 60:             evaluate,
 61:             quality,
 62:             samples,
 63:             [t0, midpoint_t],
 64:             [p0, midpoint],
 65:             depth + 1,
 66:         );
 67:         refine(
 68:             evaluate,
 69:             quality,
 70:             samples,
 71:             [midpoint_t, t1],
 72:             [midpoint, p1],
 73:             depth + 1,
 74:         );
 75:     } else {
 76:         samples.push(p1);
 77:     }
 78: }
