 85:     quality.minimum_segments = detail.samples(quality.minimum_segments, 2);
 86:     quality.max_chord = detail.error(quality.max_chord);
 87:     quality.max_deviation = detail.error(quality.max_deviation);
 88:     let mut samples = vec![evaluate(0.0)];
 89:     for i in 0..quality.minimum_segments {
 90:         let t0 = i as f64 / quality.minimum_segments as f64;
 91:         let t1 = (i + 1) as f64 / quality.minimum_segments as f64;
 92:         let p0 = *samples.last().unwrap();
 93:         refine(
 94:             &evaluate,
 95:             quality,
 96:             &mut samples,
 97:             [t0, t1],
 98:             [p0, evaluate(t1)],
 99:             0,
100:         );

