133:         self.faces
134:             .iter()
135:             .map(|&[a, b, c]| {
136:                 dot(
137:                     self.positions[a],
138:                     cross(self.positions[b], self.positions[c]),
139:                 ) / 6.0
140:             })
141:             .sum()
142:     }
