160:         let base = self.positions.len();
161:         let surface_base = self.surfaces.iter().copied().max().unwrap_or(0);
162:         self.positions.extend(other.positions);
163:         self.faces
164:             .extend(other.faces.into_iter().map(|face| face.map(|i| i + base)));
165:         self.surfaces
166:             .extend(other.surfaces.into_iter().map(|surface| {
167:                 if surface == 0 {
168:                     0
169:                 } else {
170:                     surface + surface_base
171:                 }
172:             }));
