176: pub(crate) fn add(a: Point, b: Point) -> Point {
177:     std::array::from_fn(|i| a[i] + b[i])
178: }
179: pub(crate) fn sub(a: Point, b: Point) -> Point {
180:     std::array::from_fn(|i| a[i] - b[i])
181: }
182: pub(crate) fn mul(a: Point, scalar: f64) -> Point {
183:     a.map(|v| v * scalar)
184: }
185: pub(crate) fn dot(a: Point, b: Point) -> f64 {
186:     (0..3).map(|i| a[i] * b[i]).sum()
187: }
188: pub(crate) fn cross(a: Point, b: Point) -> Point {
189:     [
190:         a[1] * b[2] - a[2] * b[1],
191:         a[2] * b[0] - a[0] * b[2],
192:         a[0] * b[1] - a[1] * b[0],
193:     ]
194: }
195: pub(crate) fn magnitude(a: Point) -> f64 {
196:     dot(a, a).sqrt()
197: }
198: pub(crate) fn normalize(a: Point) -> Point {
199:     let n = magnitude(a);
200:     if n == 0.0 { [0.0; 3] } else { mul(a, 1.0 / n) }
201: }
202: pub(crate) fn lerp(a: Point, b: Point, t: f64) -> Point {
203:     add(a, mul(sub(b, a), t))
204: }
