206: pub(crate) fn rotate(mut point: Point, degrees: Point) -> Point {
207:     for (axis, angle) in degrees.iter().enumerate() {
208:         let (s, c) = angle.to_radians().sin_cos();
209:         let a = (axis + 1) % 3;
210:         let b = (axis + 2) % 3;
211:         let x = point[a] * c - point[b] * s;
212:         let y = point[a] * s + point[b] * c;
213:         point[a] = x;
214:         point[b] = y;
215:     }
216:     point
217: }
218: 
219: pub(crate) fn inverse_rotate(mut point: Point, degrees: Point) -> Point {
220:     for axis in (0..3).rev() {
221:         let (s, c) = (-degrees[axis]).to_radians().sin_cos();
222:         let a = (axis + 1) % 3;
223:         let b = (axis + 2) % 3;
224:         let x = point[a] * c - point[b] * s;
225:         let y = point[a] * s + point[b] * c;
226:         point[a] = x;
227:         point[b] = y;
228:     }
229:     point
230: }

