  2: use super::PlanarPoint;
  3: use std::collections::{BTreeMap, BTreeSet};
  4: 
  5: // Keep equivalent diagonals in stable input order across libm implementations.
  6: pub(super) const TRIANGLE_QUALITY_TIE_TOLERANCE: f64 = 1e-12;
  7: pub(super) const TRIANGLE_QUALITY_RELATIVE_IMPROVEMENT: f64 = 1e-8;
  8: 
  9: #[derive(Clone, Debug)]
 10: pub(crate) struct Region {
 11:     pub(crate) points: Vec<PlanarPoint>,
 12:     pub(crate) triangles: Vec<[usize; 3]>,
 13:     pub(crate) boundary: Vec<usize>,
 14: }
 15: 
 16: fn area2(a: PlanarPoint, b: PlanarPoint, c: PlanarPoint) -> f64 {
 17:     (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
 18: }
 19: fn distance2(a: PlanarPoint, b: PlanarPoint) -> f64 {
 20:     (a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2)
 21: }
 22: pub(super) fn edge(a: usize, b: usize) -> (usize, usize) {
 23:     (a.min(b), a.max(b))
 24: }
 25: pub(crate) fn signed_area(points: &[PlanarPoint]) -> f64 {
 26:     (0..points.len())
 27:         .map(|i| {
 28:             let a = points[i];
 29:             let b = points[(i + 1) % points.len()];
 30:             a[0] * b[1] - b[0] * a[1]
 31:         })
 32:         .sum::<f64>()
 33:         / 2.0
 34: }
 35: pub(super) fn shape(points: &[PlanarPoint], [a, b, c]: [usize; 3]) -> f64 {
 36:     let [a, b, c] = [points[a], points[b], points[c]];
 37:     area2(a, b, c).abs() / distance2(a, b).max(distance2(b, c)).max(distance2(c, a))
 38: }
 39: fn contains(p: PlanarPoint, a: PlanarPoint, b: PlanarPoint, c: PlanarPoint) -> bool {
 40:     let signs = [area2(p, a, b), area2(p, b, c), area2(p, c, a)];
 41:     !(signs.iter().any(|&v| v < 0.0) && signs.iter().any(|&v| v > 0.0))
 42: }
 43: 
 44: impl Region {
 45:     pub(crate) fn triangulate(
 46:         input: &[PlanarPoint],
 47:         preserve_boundary: bool,
 48:     ) -> Result<Self, String> {
 49:         let OutlineTolerance {
 50:             minimum_distance,
 51:             minimum_area,
 52:         } = checked_outline(input)?;
 53:         let mut points: Vec<_> = input
 54:             .iter()
 55:             .enumerate()
 56:             .filter(|&(i, p)| i == 0 || distance2(*p, input[i - 1]).sqrt() > minimum_distance)
 57:             .map(|(_, p)| *p)
 58:             .collect();
 59:         if points.len() > 1
 60:             && distance2(points[0], *points.last().unwrap()).sqrt() <= minimum_distance
 61:         {
 62:             points.pop();
 63:         }
 64:         if !preserve_boundary {
 65:             points = remove_collinear(points, minimum_area);
 66:         }
 67:         if signed_area(&points) < 0.0 {
 68:             points.reverse();
 69:         }
 70:         let mut remaining: Vec<_> = (0..points.len()).collect();
 71:         let mut triangles = Vec::new();
 72:         while remaining.len() > 3 {
 73:             let mut selected = None;
 74:             let mut best = -1.0;
 75:             for i in 0..remaining.len() {
 76:                 let [a, b, c] = [
 77:                     remaining[(i + remaining.len() - 1) % remaining.len()],
 78:                     remaining[i],
 79:                     remaining[(i + 1) % remaining.len()],
 80:                 ];
 81:                 if area2(points[a], points[b], points[c]) <= minimum_area {
 82:                     continue;
 83:                 }
 84:                 if remaining.iter().any(|&p| {
 85:                     p != a
 86:                         && p != b
 87:                         && p != c
 88:                         && contains(points[p], points[a], points[b], points[c])
 89:                 }) {
 90:                     continue;
 91:                 }
 92:                 let quality = shape(&points, [a, b, c]);
 93:                 if quality > best + TRIANGLE_QUALITY_TIE_TOLERANCE {
 94:                     selected = Some(i);
 95:                     best = quality;
 96:                 }
 97:             }
 98:             let Some(i) = selected else {
 99:                 return Err("outline must be simple and nondegenerate".into());
100:             };
101:             triangles.push([
102:                 remaining[(i + remaining.len() - 1) % remaining.len()],
103:                 remaining[i],
104:                 remaining[(i + 1) % remaining.len()],
105:             ]);
106:             remaining.remove(i);
107:         }
108:         if remaining.len() != 3 {
109:             return Err("outline collapsed during triangulation".into());
110:         }

111:         if area2(
112:             points[remaining[0]],
113:             points[remaining[1]],
114:             points[remaining[2]],
115:         ) <= minimum_area
116:         {
117:             return Err("outline has a degenerate final triangle".into());
118:         }
119:         triangles.push([remaining[0], remaining[1], remaining[2]]);
120:         let boundary = (0..points.len()).collect();
121:         let mut region = Self {
122:             points,
123:             triangles,
124:             boundary,
125:         };
126:         region.improve();
127:         Ok(region)
128:     }
129: 
130:     fn improve(&mut self) {
131:         self.improve_where(|_, _, _| true);
132:     }
133: 
134:     pub(super) fn improve_where(
135:         &mut self,
136:         allowed: impl Fn(&[PlanarPoint], [[usize; 3]; 2], [[usize; 3]; 2]) -> bool,
137:     ) {
138:         for _ in 0..16 {
139:             let mut edges: BTreeMap<_, Vec<_>> = BTreeMap::new();
140:             for (index, face) in self.triangles.iter().enumerate() {
141:                 for i in 0..3 {
142:                     let a = face[i];
143:                     let b = face[(i + 1) % 3];
144:                     edges
145:                         .entry(edge(a, b))
146:                         .or_default()
147:                         .push((index, a, b, face[(i + 2) % 3]));
148:                 }
149:             }
150:             let mut touched = BTreeSet::new();
151:             let mut changed = false;
152:             for entries in edges.values() {
153:                 let [x, y] = entries.as_slice() else {
154:                     continue;
155:                 };
156:                 if touched.contains(&x.0) || touched.contains(&y.0) {
157:                     continue;
158:                 }
159:                 let candidates = [[x.3, x.1, y.3], [x.3, y.3, x.2]];
160:                 if candidates.iter().any(|&[a, b, c]| {
161:                     area2(self.points[a], self.points[b], self.points[c]) <= 1e-16
162:                 }) {
163:                     continue;
164:                 }
165:                 let before = shape(&self.points, self.triangles[x.0])
166:                     .min(shape(&self.points, self.triangles[y.0]));
167:                 let after =
168:                     shape(&self.points, candidates[0]).min(shape(&self.points, candidates[1]));
169:                 if after <= before * (1.0 + TRIANGLE_QUALITY_RELATIVE_IMPROVEMENT) {
170:                     continue;
171:                 }
172:                 if !allowed(
173:                     &self.points,
174:                     [self.triangles[x.0], self.triangles[y.0]],
175:                     candidates,
176:                 ) {
177:                     continue;
178:                 }
179:                 self.triangles[x.0] = candidates[0];
180:                 self.triangles[y.0] = candidates[1];
181:                 touched.extend([x.0, y.0]);
182:                 changed = true;
183:             }
184:             if !changed {
185:                 break;
186:             }
187:         }
188:     }
189: 
190:     pub(crate) fn refine(mut self, max_edge: f64) -> Self {
191:         let mut longest = 0.0_f64;
192:         for f in &self.triangles {
193:             for i in 0..3 {
194:                 longest =
195:                     longest.max(distance2(self.points[f[i]], self.points[f[(i + 1) % 3]]).sqrt());
196:             }
197:         }
198:         let rounds = (longest / max_edge).log2().ceil().max(0.0) as usize + 1;
199:         for _ in 0..rounds {
200:             let mut mids = BTreeMap::new();
201:             for f in &self.triangles {
202:                 for i in 0..3 {
203:                     let a = f[i];
204:                     let b = f[(i + 1) % 3];
205:                     let key = edge(a, b);
206:                     if mids.contains_key(&key)
207:                         || distance2(self.points[a], self.points[b]) <= max_edge * max_edge
208:                     {
209:                         continue;
210:                     }
211:                     mids.insert(key, self.points.len());
212:                     self.points.push(std::array::from_fn(|axis| {
213:                         (self.points[a][axis] + self.points[b][axis]) / 2.0
214:                     }));
215:                 }
216:             }
217:             if mids.is_empty() {
218:                 break;
219:             }
220:             self.split_edges(&mids);

221:             self.improve();
222:         }
223:         self.improve();
224:         self
225:     }
226: }
