228: struct OutlineTolerance {
229:     minimum_distance: f64,
230:     minimum_area: f64,
231: }
232: fn checked_outline(input: &[PlanarPoint]) -> Result<OutlineTolerance, String> {
233:     if input.len() < 3 || input.iter().flatten().any(|v| !v.is_finite()) {
234:         return Err("outline needs at least three finite points".into());
235:     }
236:     let extent = (0..2)
237:         .map(|axis| {
238:             input
239:                 .iter()
240:                 .map(|p| p[axis])
241:                 .fold(f64::NEG_INFINITY, f64::max)
242:                 - input.iter().map(|p| p[axis]).fold(f64::INFINITY, f64::min)
243:         })
244:         .fold(0.0, f64::max);
245:     if extent == 0.0 {
246:         return Err("outline has no extent".into());
247:     }
248:     let minimum_distance = extent * 1e-9;
249:     let minimum_area = extent * extent * 1e-12;
250:     for i in 0..input.len() {
251:         let next = (i + 1) % input.len();
252:         for j in i + 1..input.len() {
253:             let other = (j + 1) % input.len();
254:             if j == next || other == i {
255:                 continue;
256:             }
257:             let [a, b, c, d] = [input[i], input[next], input[j], input[other]];
258:             let orientation = |a, b, c| {
259:                 let area = area2(a, b, c);
260:                 if area.abs() <= minimum_area {
261:                     0_i8
262:                 } else if area < 0.0 {
263:                     -1
264:                 } else {
265:                     1
266:                 }
267:             };
268:             let on_segment = |p: PlanarPoint, a: PlanarPoint, b: PlanarPoint| {
269:                 (0..2).all(|axis| {
270:                     p[axis] >= a[axis].min(b[axis]) - minimum_distance
271:                         && p[axis] <= a[axis].max(b[axis]) + minimum_distance
272:                 })
273:             };
274:             let [ac, ad, ca, cb] = [
275:                 orientation(a, b, c),
276:                 orientation(a, b, d),
277:                 orientation(c, d, a),
278:                 orientation(c, d, b),
279:             ];
280:             if ac * ad < 0 && ca * cb < 0
281:                 || ac == 0 && on_segment(c, a, b)
282:                 || ad == 0 && on_segment(d, a, b)
283:                 || ca == 0 && on_segment(a, c, d)
284:                 || cb == 0 && on_segment(b, c, d)
285:             {
286:                 return Err("outline edges intersect or touch".into());
287:             }
288:         }
289:     }
290: 
291:     Ok(OutlineTolerance {
292:         minimum_distance,
293:         minimum_area,
294:     })
295: }
