323:     pub(crate) fn rounded_plate(
324:         outline: &[PlanarPoint],
325:         thickness: f64,
326:         bevel_fraction: f64,
327:     ) -> Result<Self, String> {
328:         let region = Region::triangulate(outline, false)?;
329:         let center_y = (region
330:             .points
331:             .iter()
332:             .map(|p| p[1])
333:             .fold(f64::INFINITY, f64::min)
334:             + region
335:                 .points
336:                 .iter()
337:                 .map(|p| p[1])
338:                 .fold(f64::NEG_INFINITY, f64::max))
339:             / 2.0;
340:         let vertex = |i: usize, side: f64, inset: bool| {
341:             let scale = if inset { 1.0 - bevel_fraction } else { 1.0 };
342:             [
343:                 region.points[i][0] * scale,
344:                 center_y + (region.points[i][1] - center_y) * scale,
345:                 side * thickness * if inset { 0.5 } else { 0.28 },
346:             ]
347:         };
348:         let mut solid = Self::default();
349:         for side in [-1.0, 1.0] {
350:             for &[a, b, c] in &region.triangles {
351:                 let [a, b, c] = [
352:                     vertex(a, side, true),
353:                     vertex(b, side, true),
354:                     vertex(c, side, true),
355:                 ];
356:                 if side < 0.0 {
357:                     solid.triangle(c, b, a, 0);
358:                 } else {
359:                     solid.triangle(a, b, c, 0);
360:                 }
361:             }
362:             for i in 0..region.points.len() {
363:                 let j = (i + 1) % region.points.len();
364:                 let [a, b, c, d] = [
365:                     vertex(i, side, false),
366:                     vertex(j, side, false),
367:                     vertex(j, side, true),
368:                     vertex(i, side, true),
369:                 ];
370:                 if side > 0.0 {
371:                     solid.quad(a, b, c, d, 1);
372:                 } else {
373:                     solid.quad(a, d, c, b, 2);
374:                 }
375:             }
376:         }
377:         for i in 0..region.points.len() {
378:             let j = (i + 1) % region.points.len();
379:             solid.quad(
380:                 vertex(i, -1.0, false),
381:                 vertex(j, -1.0, false),
382:                 vertex(j, 1.0, false),
383:                 vertex(i, 1.0, false),
384:                 3,
385:             );
386:         }
387:         Ok(solid.positive())
388:     }
