177:                 continue;
178:             }
179:             self.split_edges(&mids);
180:             self.improve_refinement_cells(&classify, &height, maximum_deviation, maximum_edge);
181:         }
182:         Err("plate surface exceeds its bounded refinement budget".into())
183:     }
184: 
185:     /// Improve interior fans without undoing a completed error or edge split.
186:     fn improve_refinement_cells<K: Eq>(
187:         &mut self,
188:         classify: &impl Fn(PlanarPoint) -> K,
189:         height: &impl Fn(PlanarPoint) -> f64,
190:         maximum_deviation: f64,
191:         maximum_edge: f64,
192:     ) {
193:         self.improve_where(|points, before, after| {
194:             let center = |face: [usize; 3]| {
195:                 std::array::from_fn(|axis| face.iter().map(|&i| points[i][axis]).sum::<f64>() / 3.0)
196:             };
197:             if classify(center(before[0])) != classify(center(before[1])) {
198:                 return false;
199:             }
200:             let limits = |faces: [[usize; 3]; 2]| {
201:                 let (mut longest, mut deviation) = (0.0_f64, 0.0_f64);
202:                 let mut within_edge = true;
203:                 for face in faces {
204:                     let p = face.map(|i| points[i]);
205:                     deviation = deviation.max(surface_deviation(p, height));
206:                     for i in 0..3 {
207:                         let [a, b] = [p[i], p[(i + 1) % 3]];
208:                         longest = longest.max((a[0] - b[0]).hypot(a[1] - b[1]));
209:                         within_edge &= within_surface_edge(a, b, maximum_edge);
210:                     }
211:                 }
212:                 (longest, deviation, within_edge)
213:             };
214:             let (old_edge, old_deviation, old_within_edge) = limits(before);
215:             let (new_edge, new_deviation, new_within_edge) = limits(after);
216:             new_edge <= old_edge.max(maximum_edge)
217:                 && (!old_within_edge || new_within_edge)
218:                 && new_deviation <= old_deviation.max(maximum_deviation / 2.0)
219:         });
220:     }

1: //! Conforming subdivision shared by planar regions and sampled relief surfaces.
