6: const MAX_SURFACE_REFINEMENT_ROUNDS: usize = 12;
7: const SURFACE_EDGE_ROUNDING_ULPS: f64 = 64.0;
8: 
9: /// Keep rounding at an exact edge limit on the refining side on every target.
10: /// The margin tightens the bound and includes subtraction at the point scale.
11: pub(super) fn within_surface_edge(a: PlanarPoint, b: PlanarPoint, maximum_edge: f64) -> bool {
12:     let scale = a
13:         .into_iter()
14:         .chain(b)
15:         .map(f64::abs)
16:         .fold(maximum_edge, f64::max);
17:     let rounding = SURFACE_EDGE_ROUNDING_ULPS * f64::EPSILON * scale;
18:     (a[0] - b[0]).hypot(a[1] - b[1]) + rounding <= maximum_edge
19: }
