21: impl Region {
22:     /// Repair incidental sub-resolution diagonals without moving authored
23:     /// boundaries or crossing a structural surface partition.
24:     pub(crate) fn improve_surface_cells<K: Eq>(
25:         &mut self,
26:         classify: impl Fn(PlanarPoint) -> K,
27:         height: impl Fn(PlanarPoint) -> f64,
28:         maximum_deviation: f64,
29:         maximum_edge: f64,
30:     ) {
31:         self.collapse_interior_sampling(&classify, &height, maximum_deviation, maximum_edge);
32:         self.improve_where(|points, before, after| {
33:             let centroid = |face: [usize; 3]| {
34:                 std::array::from_fn(|axis| face.iter().map(|&i| points[i][axis]).sum::<f64>() / 3.0)
35:             };
36:             if classify(centroid(before[0])) != classify(centroid(before[1])) {
37:                 return false;
38:             }
39:             let subresolution = before.iter().any(|&face| {
40:                 let [a, b, c] = face.map(|i| points[i]);
41:                 let longest = [(a, b), (b, c), (c, a)]
42:                     .into_iter()
43:                     .map(|(p, q)| (p[0] - q[0]).hypot(p[1] - q[1]))
44:                     .fold(0.0, f64::max);
45:                 shape(points, face) * longest < crate::recipe::MIN_MANUFACTURED_METRES
46:             });
47:             subresolution
48:                 && after.into_iter().all(|face| {
49:                     let p = face.map(|i| points[i]);
50:                     (0..3).all(|i| {
51:                         let next = (i + 1) % 3;
52:                         within_surface_edge(p[i], p[next], maximum_edge)
53:                     }) && surface_deviation(p, &height) <= maximum_deviation / 2.0
54:                 })
55:         });
56:         self.collapse_interior_sampling(&classify, &height, maximum_deviation, maximum_edge);
57:         self.remove_interior_fans(&classify, &height, maximum_deviation, maximum_edge);
58:     }
