60:     pub(crate) fn split_edges(&mut self, mids: &BTreeMap<(usize, usize), usize>) {
61:         let mut next = Vec::new();
62:         for &f in &self.triangles {
63:             let m: Vec<_> = (0..3)
64:                 .map(|i| mids.get(&edge(f[i], f[(i + 1) % 3])).copied())
65:                 .collect();
66:             match m.iter().flatten().count() {
67:                 0 => next.push(f),
68:                 3 => {
69:                     let [a, b, c] = [m[0].unwrap(), m[1].unwrap(), m[2].unwrap()];
70:                     next.extend([[f[0], a, c], [a, f[1], b], [c, b, f[2]], [a, b, c]]);
71:                 }
72:                 1 => {
73:                     let i = m.iter().position(Option::is_some).unwrap();
74:                     let [a, b, c] = [f[i], f[(i + 1) % 3], f[(i + 2) % 3]];
75:                     let mid = m[i].unwrap();
76:                     next.extend([[a, mid, c], [mid, b, c]]);
77:                 }
78:                 _ => {
79:                     let i = m.iter().position(Option::is_none).unwrap();
80:                     let [a, b, c] = [f[i], f[(i + 1) % 3], f[(i + 2) % 3]];
81:                     let bc = m[(i + 1) % 3].unwrap();
82:                     let ca = m[(i + 2) % 3].unwrap();
83:                     next.push([c, ca, bc]);
84:                     let options = [[[a, b, bc], [a, bc, ca]], [[a, b, ca], [b, bc, ca]]];
85:                     let quality = |option: [[usize; 3]; 2]| {
86:                         shape(&self.points, option[0]).min(shape(&self.points, option[1]))
87:                     };
88:                     next.extend(
89:                         if quality(options[1])
90:                             > quality(options[0]) + TRIANGLE_QUALITY_TIE_TOLERANCE
91:                         {
92:                             options[1]
93:                         } else {
94:                             options[0]
95:                         },
96:                     );
97:                 }
98:             }
99:         }
100:         self.boundary = (0..self.boundary.len())
101:             .flat_map(|i| {
102:                 let a = self.boundary[i];
103:                 let mut points = vec![a];
104:                 if let Some(&mid) = mids.get(&edge(a, self.boundary[(i + 1) % self.boundary.len()]))
105:                 {
106:                     points.push(mid);
107:                 }
108:                 points
109:             })
110:             .collect();

301:             };
302:             let taper = (1.0 + (sweep.tip_scale - 1.0) * t)
303:                 * (1.0 + sweep.terminal_swell * ((t - 0.72) / 0.28).max(0.0).powi(2));
304:             let [u, v] = outline[side].map(|value| value * taper * scales[row]);
305:             add(
306:                 add(points[row], mul(normal, u * twist.cos() - v * twist.sin())),
307:                 mul(binormal, u * twist.sin() + v * twist.cos()),
308:             )
309:         };
310:         let mut solid = Self::default();
311:         for row in 0..n - 1 {
312:             for side in 0..outline.len() {
313:                 let next = (side + 1) % outline.len();
314:                 let group = match sweep.section {
315:                     Section::Round | Section::Oval => 1,
316:                     Section::DShape => {
317:                         if side == outline.len() - 1 {
318:                             2
319:                         } else {
320:                             1
321:                         }
322:                     }
323:                     _ => side as u32 + 1,
324:                 };
325:                 let corners = [
326:                     vertex(row, side),
327:                     vertex(row, next),
328:                     vertex(row + 1, next),
329:                     vertex(row + 1, side),
330:                 ];
331:                 if sweep.twist == 0.0 {
332:                     solid.quad(corners[0], corners[1], corners[2], corners[3], group);
333:                 } else {
334:                     // A fixed diagonal of a twisted face adds a handedness-
335:                     // dependent material wedge. Its bilinear center treats
336:                     // both diagonals equally and preserves mirrored volumes.
337:                     let center = mul(corners.into_iter().fold([0.0; 3], add), 0.25);
338:                     for side in 0..4 {
339:                         solid.triangle(corners[side], corners[(side + 1) % 4], center, group);
340:                     }
341:                 }
342:             }
343:         }
344:         if !closed {
345:             for (row, reverse) in [(0, true), (n - 1, false)] {
346:                 for side in 0..outline.len() {
347:                     let a = vertex(row, side);
348:                     let b = vertex(row, (side + 1) % outline.len());
349:                     if reverse {
350:                         solid.triangle(points[row], b, a, 0);
351:                     } else {
352:                         solid.triangle(points[row], a, b, 0);
353:                     }
354:                 }
355:             }
356:         }
357:         Ok(solid.positive())
358:     }
359: }

