53: pub(crate) fn tube_segments(radius: f64, requested: usize, detail: Detail) -> usize {
54:     let chord = if 0.006 >= radius * 2.0 {
55:         3.0
56:     } else {
57:         (PI / (0.006 / (radius * 2.0)).asin()).ceil()
58:     };
59:     let sagitta = if 0.0003 >= radius {
60:         3.0
61:     } else {
62:         (PI / (1.0 - 0.0003 / radius).acos()).ceil()
63:     };
64:     detail
65:         .radial(radius, requested)
66:         .max((chord / detail.error(1.0)).ceil() as usize)
67:         .max((sagitta / detail.error(1.0).sqrt()).ceil() as usize)
68: }
