86:                 let cut_x = width * CORNER_CUT_FRACTION;
87:                 let cut_y = depth * CORNER_CUT_FRACTION;
88:                 vec![
89:                     [-x + cut_x, -y],
90:                     [x - cut_x, -y],
91:                     [x, -y + cut_y],
92:                     [x, y - cut_y],
93:                     [x - cut_x, y],
94:                     [-x + cut_x, y],
95:                     [-x, y - cut_y],
96:                     [-x, -y + cut_y],
97:                 ]
98:             }
99:             Self::Round | Self::Oval => {
100:                 let count = tube_segments(width.max(depth) / 2.0, requested, detail);

101:                 (0..count)
102:                     .map(|i| {
103:                         let angle = i as f64 / count as f64 * TAU;
104:                         [angle.cos() * width / 2.0, angle.sin() * depth / 2.0]
105:                     })
106:                     .collect()
107:             }
108:             Self::Diamond => vec![
109:                 [width / 2.0, 0.0],
110:                 [0.0, depth / 2.0],
111:                 [-width / 2.0, 0.0],
112:                 [0.0, -depth / 2.0],
113:             ],
114:             Self::DShape => {
115:                 let count = tube_segments(width.max(depth) / 2.0, requested, detail).max(8);
116:                 let mut points = vec![[-width / 2.0, -depth / 2.0]];
117:                 points.extend((0..=count).map(|i| {
118:                     let angle = -PI / 2.0 + i as f64 / count as f64 * PI;
119:                     [angle.cos() * width / 2.0, angle.sin() * depth / 2.0]
120:                 }));
121:                 points.push([-width / 2.0, depth / 2.0]);
122:                 points
123:             }
124:             Self::Triangular => vec![
125:                 [0.0, depth * 0.58],
126:                 [-width / 2.0, -depth * 0.42],
127:                 [width / 2.0, -depth * 0.42],
128:             ],
129:             Self::Flat => vec![
130:                 [-width / 2.0, -depth / 2.0],
131:                 [width / 2.0, -depth / 2.0],
132:                 [width / 2.0, depth / 2.0],
133:                 [-width / 2.0, depth / 2.0],
134:             ],
135:         }
