139: fn rotate_around(vector: Point, axis: Point, angle: f64) -> Point {
140:     add(
141:         add(
142:             mul(vector, angle.cos()),
143:             mul(cross(axis, vector), angle.sin()),
144:         ),
145:         mul(axis, dot(axis, vector) * (1.0 - angle.cos())),
146:     )
147: }
