149: fn segment_distance(a: Point, b: Point, c: Point, d: Point) -> f64 {
150:     let u = sub(b, a);
151:     let v = sub(d, c);
152:     let w = sub(a, c);
153:     let aa = dot(u, u);
154:     let bb = dot(u, v);
155:     let cc = dot(v, v);
156:     let dd = dot(u, w);
157:     let ee = dot(v, w);
158:     let denominator = aa * cc - bb * bb;
159:     let mut s = if denominator > aa * cc * 1e-14 {
160:         ((bb * ee - cc * dd) / denominator).clamp(0.0, 1.0)
161:     } else {
162:         0.0
163:     };
164:     let mut t = if cc > 0.0 { (bb * s + ee) / cc } else { 0.0 };
165:     if t < 0.0 {
166:         t = 0.0;
167:         s = if aa > 0.0 {
168:             (-dd / aa).clamp(0.0, 1.0)
169:         } else {
170:             0.0
171:         };
172:     }
173:     if t > 1.0 {
174:         t = 1.0;
175:         s = if aa > 0.0 {
176:             ((bb - dd) / aa).clamp(0.0, 1.0)
177:         } else {
178:             0.0
179:         };
180:     }
181:     magnitude(sub(add(w, mul(u, s)), mul(v, t)))
182: }
