184: pub(crate) fn bend_scales(points: &[Point], radius: f64, closed: bool) -> Vec<f64> {
185:     let n = points.len();
186:     let count = if closed { n - 1 } else { n };
187:     let mut scales = vec![1.0_f64; n];
188:     let mut arc = vec![0.0];
189:     for i in 1..n {
190:         arc.push(arc[i - 1] + magnitude(sub(points[i], points[i - 1])));
191:     }
192:     for i in 0..count {
193:         if !closed && (i == 0 || i == count - 1) {
194:             continue;
195:         }
196:         let incoming = sub(points[i], points[(i + count - 1) % count]);
197:         let outgoing = sub(points[(i + 1) % count], points[i]);
198:         let a = magnitude(incoming);
199:         let b = magnitude(outgoing);
200:         let cosine = (dot(incoming, outgoing) / (a * b)).clamp(-1.0, 1.0);

201:         let tangent_half = ((1.0 - cosine) / (1.0 + cosine).max(1e-12)).sqrt();
202:         if tangent_half > 1e-8 {
203:             scales[i] = (0.3 * a.min(b) / (radius * tangent_half)).min(1.0);
204:         }
205:     }
206:     for i in 0..n - 1 {
207:         for j in i + 2..n - 1 {
208:             let forward = arc[j] - arc[i + 1];
209:             let separated = if closed {
210:                 forward.min(arc[n - 1] - arc[j + 1] + arc[i])
211:             } else {
212:                 forward
213:             };
214:             if separated <= radius * 4.0 {
215:                 continue;
216:             }
217:             let scale = (segment_distance(points[i], points[i + 1], points[j], points[j + 1])
218:                 * 0.3
219:                 / radius)
220:                 .min(1.0);
221:             for vertex in [i, i + 1, j, j + 1] {
222:                 scales[vertex] = scales[vertex].min(scale);
223:             }
224:         }
225:     }
226:     let limits = scales.clone();
227:     for i in 0..count {
228:         for j in 0..count {
229:             let forward = (arc[i] - arc[j]).abs();
230:             let distance = if closed {
231:                 forward.min(arc[n - 1] - forward)
232:             } else {
233:                 forward
234:             };
235:             scales[i] = scales[i].min(limits[j] + distance / (radius * 3.0));
236:         }
237:     }
238:     if closed {
239:         scales[n - 1] = scales[0].min(scales[n - 1]);
240:         scales[0] = scales[n - 1];
241:     }
242:     scales
243: }
