11: impl SampledPath {
12:     pub(super) fn new(
13:         input: &[Point],
14:         sweep: &Sweep,
15:         section_vertices: usize,
16:         detail: Detail,
17:         closed: bool,
18:     ) -> Result<Self, String> {
