22:             sweep
23:                 .ring_scales
24:                 .clone()
25:                 .unwrap_or_else(|| vec![1.0; input.len()])
26:         };
27:         if room.len() != input.len() {
28:             return Err("section scales must match member stations".into());
29:         }
30:         let chord = detail.error(0.025).min(
31:             sweep.width.min(sweep.depth)
32:                 * sweep.tip_scale.min(1.0)
33:                 * (PI / section_vertices as f64).sin()
34:                 * 32.0,
35:         );
36:         // Axial distance alone cannot resolve a rotating section: a short
37:         // straight member may contain several complete turns. Bound the
38:         // movement of its furthest corner as well as the rotation per ring.
39:         let radius = sweep.width.hypot(sweep.depth) / 2.0
40:             * sweep.tip_scale.max(1.0)
41:             * (1.0 + sweep.terminal_swell.max(0.0))
42:             * room.iter().copied().fold(1.0, f64::max);
