44:             (detail.error(TWIST_CORNER_TRAVEL_METRES) / radius).min(MAXIMUM_RING_TWIST_RADIANS);
45:         let twist_stations = sweep.twist.to_radians().abs() / (input.len() - 1) as f64 / ring_twist;
46:         let segment_count = |length: f64| (length / chord).max(twist_stations).ceil().max(1.0);
47:         let stations = input
48:             .windows(2)
49:             .map(|p| segment_count(magnitude(sub(p[1], p[0]))))
50:             .sum::<f64>()
51:             + 1.0;
52:         let faces_per_cell = if sweep.twist == 0.0 { 2.0 } else { 4.0 };
53:         construction_budget(stations * section_vertices as f64 * faces_per_cell)?;
54:         let mut points = Vec::new();
55:         let mut scales = Vec::new();
56:         let mut progress = Vec::new();
57:         for i in 0..input.len() - 1 {
58:             let count = segment_count(magnitude(sub(input[i + 1], input[i]))) as usize;
59:             for step in 0..count {
60:                 let t = step as f64 / count as f64;
61:                 points.push(lerp(input[i], input[i + 1], t));
62:                 scales.push(room[i] * (1.0 - t) + room[i + 1] * t);
63:                 progress.push((i as f64 + t) / (input.len() - 1) as f64);
64:             }
65:         }
66:         points.push(*input.last().unwrap());
67:         scales.push(*room.last().unwrap());
68:         progress.push(1.0);
69: 
70:         Ok(Self {
71:             points,
72:             scales,
73:             progress,
74:         })
75:     }
76: }
77: pub(super) struct TransportFrames {
78:     pub(super) tangents: Vec<Point>,
79:     pub(super) normals: Vec<Point>,
80: }
81: impl TransportFrames {
82:     pub(super) fn along(points: &[Point], closed: bool) -> Result<Self, String> {
83:         let n = points.len();
84:         let tangents: Vec<_> = (0..n)
85:             .map(|row| {
86:                 normalize(sub(
87:                     points[if row == n - 1 {
88:                         if closed { 1 } else { row }
89:                     } else {
90:                         row + 1
91:                     }],
92:                     points[if row == 0 {
93:                         if closed { n - 2 } else { 0 }
94:                     } else {
95:                         row - 1
96:                     }],
97:                 ))
98:             })
99:             .collect();
100:         let mut frames = Vec::new();

101:         for row in 0..n {
102:             let tangent = tangents[row];
103:             if row == 0 {
104:                 let reference = if tangent[2].abs() < 0.8 {
105:                     [0.0, 0.0, 1.0]
106:                 } else {
107:                     [0.0, 1.0, 0.0]
108:                 };
109:                 frames.push(normalize(cross(reference, tangent)));
110:             } else {
111:                 let axis = cross(tangents[row - 1], tangent);
112:                 let sine = magnitude(axis);
113:                 let cosine = dot(tangents[row - 1], tangent);
114:                 if cosine < -0.99 {
115:                     return Err("member centerline reverses direction".into());
116:                 }
117:                 frames.push(if sine < 1e-8 {
118:                     frames[row - 1]
119:                 } else {
120:                     normalize(rotate_around(
121:                         frames[row - 1],
122:                         mul(axis, 1.0 / sine),
123:                         sine.atan2(cosine),
124:                     ))
125:                 });
126:             }
127:         }
128:         if closed {
129:             let angle = dot(cross(frames[n - 1], frames[0]), tangents[0])
130:                 .atan2(dot(frames[n - 1], frames[0]));
131:             for row in 0..n {
132:                 frames[row] = rotate_around(
133:                     frames[row],
134:                     tangents[row],
135:                     angle * row as f64 / (n - 1) as f64,
136:                 );
137:             }
138:             frames[n - 1] = frames[0];
139:         }
140: 
141:         Ok(Self {
142:             tangents,
143:             normals: frames,
144:         })
145:     }
146: }

