1: //! Linear radiance in a latitude-longitude studio light map, shared with armor baking.
2: 
3: use glam::Vec3;
4: use std::{f32::consts::PI, sync::LazyLock};
5: use tiny_skia::Pixmap;
6: 
7: const MAP_WIDTH: usize = 128;
8: const MAP_HEIGHT: usize = 64;
9: const EXPOSURE: f32 = 1.4;
10: const REFLECTION_SAMPLES: usize = 12;
11: 
12: static ENVIRONMENT: LazyLock<Vec<Vec3>> = LazyLock::new(|| {
13:     (0..MAP_WIDTH * MAP_HEIGHT)
14:         .map(|index| {
15:             let longitude = ((index % MAP_WIDTH) as f32 + 0.5) / MAP_WIDTH as f32;
16:             let latitude = ((index / MAP_WIDTH) as f32 + 0.5) / MAP_HEIGHT as f32;
17:             let theta = latitude * PI;
18:             let phi = longitude * 2.0 * PI;
19:             let direction = Vec3::new(
20:                 theta.sin() * phi.cos(),
21:                 theta.cos(),
22:                 theta.sin() * phi.sin(),
23:             );
24:             let sky = Vec3::new(0.16, 0.19, 0.25);
25:             let floor = Vec3::new(0.035, 0.028, 0.022);
26:             let surround = floor.lerp(sky, direction.y * 0.5 + 0.5);
27:             let key = direction
28:                 .dot(Vec3::new(-0.4, 0.4, 0.8).normalize())
29:                 .max(0.0)
30:                 .powi(12);
31:             let rim = direction
32:                 .dot(Vec3::new(0.85, 0.25, -0.45).normalize())
33:                 .max(0.0)
34:                 .powi(48);
35:             surround
36:                 + Vec3::new(1.0, 0.92, 0.78) * key * 3.0
37:                 + Vec3::new(0.65, 0.8, 1.0) * rim * 2.0
38:         })
39:         .collect()
40: });
41: 
42: fn sample(direction: Vec3) -> Vec3 {
43:     let u = direction.z.atan2(direction.x).rem_euclid(2.0 * PI) / (2.0 * PI);
44:     let v = direction.y.clamp(-1.0, 1.0).acos() / PI;
45:     let x = (u * MAP_WIDTH as f32) as usize % MAP_WIDTH;
46:     let y = ((v * MAP_HEIGHT as f32) as usize).min(MAP_HEIGHT - 1);
47:     ENVIRONMENT[y * MAP_WIDTH + x]
48: }
49: 
50: fn filtered(direction: Vec3, spread: f32) -> Vec3 {
51:     let tangent = direction.any_orthonormal_vector();
52:     let bitangent = direction.cross(tangent);
53:     let mut color = sample(direction);
54:     for index in 0..REFLECTION_SAMPLES {
55:         let angle = index as f32 * 2.399_963_1;
56:         let radius = ((index as f32 + 0.5) / REFLECTION_SAMPLES as f32).sqrt() * spread;
57:         color += sample(
58:             (direction + radius * (angle.cos() * tangent + angle.sin() * bitangent)).normalize(),
59:         );
60:     }
61:     color / (REFLECTION_SAMPLES + 1) as f32
62: }
63: 
64: pub(super) fn shade(normal: Vec3, view: Vec3, albedo: Vec3, metallic: f32, roughness: f32) -> Vec3 {
65:     let normal = if normal.dot(view) < 0.0 {
66:         -normal
67:     } else {
68:         normal
69:     };
70:     let reflection = 2.0 * normal.dot(view) * normal - view;
71:     let fresnel = albedo.lerp(Vec3::splat(0.04), 1.0 - metallic);
72:     let fresnel = fresnel + (Vec3::ONE - fresnel) * (1.0 - normal.dot(view).max(0.0)).powi(5);
73:     let diffuse = filtered(normal, 1.5) * albedo * (1.0 - metallic);
74:     let specular = filtered(reflection.normalize(), roughness * roughness * 2.0) * fresnel;
75:     (diffuse + specular) * EXPOSURE
76: }
77: 
78: pub(super) fn srgb(linear: f32) -> u8 {
79:     // Reinhard highlight compression followed by the display transfer function.
80:     let value = linear.max(0.0) / (1.0 + linear.max(0.0));
81:     let encoded = if value <= 0.003_130_8 {
82:         value * 12.92
83:     } else {
84:         1.055 * value.powf(1.0 / 2.4) - 0.055
85:     };
86:     (encoded * 255.0).round() as u8
87: }
88: 
89: /// Export the same linear studio radiance as RGBE for offline armor rendering.
90: pub fn environment_hdr() -> Vec<u8> {
91:     let mut output =
92:         format!("#?RADIANCE\nFORMAT=32-bit_rle_rgbe\n\n-Y {MAP_HEIGHT} +X {MAP_WIDTH}\n")
93:             .into_bytes();
94:     for color in ENVIRONMENT.iter() {
95:         let exponent = color.max_element().log2().floor() as i32 + 1;
96:         let scale = 256.0 / 2.0_f32.powi(exponent);
97:         output.extend([
98:             (color.x * scale) as u8,
99:             (color.y * scale) as u8,
100:             (color.z * scale) as u8,
101:             (exponent + 128) as u8,
102:         ]);
103:     }
104:     output
105: }
106: 
107: pub(super) fn encode_png(size: u16, rgba: Vec<u8>) -> Result<Vec<u8>, super::IconError> {
108:     let dimensions = tiny_skia::IntSize::from_wh(u32::from(size), u32::from(size))
109:         .ok_or(super::IconError::InvalidSpec)?;
110:     Pixmap::from_vec(rgba, dimensions)
111:         .ok_or(super::IconError::Rasterization)?
112:         .encode_png()
113:         .map_err(|error| super::IconError::Png(error.to_string()))
114: }

101:     side: usize,
102:     flat: [usize; 2],
103:     ring: F,
104:     broad: Point,
105:     tolerance: f64,
106: }
107: impl<F: Fn(f64) -> Vec<Point>> NormalCheck<F> {
108:     fn compare(&self, normal: Point, param: [f64; 2]) -> Result<(), String> {
109:         let Self {
110:             interval,
111:             side,
112:             flat,
113:             ring,
114:             broad,
115:             tolerance,
116:         } = self;
117:         let [y, u] = param;
118:         let h = (interval[1] - interval[0]) * 0.0001;
119:         let at = ring(y);
120:         let before = ring(y - h);
121:         let after = ring(y + h);
122:         let sampled_normal = |indices: [usize; 2]| {
123:             let sample = |r: &[Point]| add(mul(r[indices[0]], 1.0 - u), mul(r[indices[1]], u));
124:             unit(cross(
125:                 sub(at[indices[1]], at[indices[0]]),
126:                 sub(sample(&after), sample(&before)),
127:             ))
128:         };
129:         let reference = sampled_normal(*flat)?;
130:         let next = (side + 1) % at.len();
131:         let analytic = if at[*side] == at[next] {
132:             reference
133:         } else {
134:             sampled_normal([*side, next])?
135:         };
136:         let base_error = angle(*broad, reference);
137:         // A retained transition fan follows the nonflat analytic surface.
138:         // Completely omitted strips call this with normal=broad, which also
139:         // bounds their full normal departure without flattening retained fans.
140:         if angle(normal, analytic) > base_error + tolerance {
141:             return Err(format!(
142:                 "fuller tail cannot be simplified within the normal-error budget: interval {interval:?}, side {side}, at {param:?}, analytic-to-flat {}, mesh-to-analytic {}, base {}, tolerance {}",
143:                 angle(analytic, reference),
144:                 angle(normal, analytic),
145:                 base_error,
146:                 tolerance
147:             ));
148:         }
149:         Ok(())
150:     }
151: }
152: fn unit(v: Point) -> Result<Point, String> {
153:     let length = magnitude(v);
154:     if !length.is_finite() || length == 0.0 {
155:         return Err("unresolved blade surface normal".into());
156:     }
157:     Ok(mul(v, 1.0 / length))
158: }
159: fn angle(a: Point, b: Point) -> f64 {
160:     dot(a, b).clamp(-1.0, 1.0).acos()
161: }

1: //! One transverse section and closed loft authority for authored blades.
2: use super::*;
3: use std::f64::consts::TAU;
4: 
5: #[derive(Clone, Copy)]
6: pub(super) enum BladeSampling {
7:     Section,
8:     Loft(usize),
9: }
10: pub(super) fn blade(
11:     p: BladeProfile<'_>,
12:     sampling: BladeSampling,
13:     detail: Detail,
14: ) -> Result<Solid, String> {
15:     p.validate().map_err(|e| e.to_string())?;
16:     let point = p.point_curve()?;
17:     let minimum_envelope = blade_reduction::envelope_floor(&p, detail)?;
18:     let ring = |y, minimum_envelope| {
19:         let [w, d] = p.dimensions(y, point.as_ref());
20:         let center = p.center(y, w);
21:         section(&p, y, w, d, detail, minimum_envelope)
22:             .into_iter()
23:             .map(|[x, z]| [center + x, y, z])
24:             .collect::<Vec<_>>()
25:     };
26:     let mut stations = if p.fuller.is_some() || p.point.is_some() {
27:         feature_stations(&p, |y| ring(y, 0.0), detail)?
28:     } else {
29:         let mut stations = baseline_stations(p.length, |y| ring(y, 0.0), sampling, detail)?;
30:         if p.ricasso > 0.0 {
31:             stations.push(p.ricasso);
32:         }
33:         stations.sort_by(f64::total_cmp);
34:         stations.dedup();
35:         stations
36:     };
37:     if let Some(fuller) = p.fuller {
38:         groove_transitions::refine(&mut stations, fuller, minimum_envelope, &ring, detail)?;
39:     }
40:     let rings: Vec<_> = stations
41:         .iter()
42:         .copied()
43:         .map(|y| ring(y, minimum_envelope))
44:         .collect();
45:     construction_budget((rings.len() * rings[0].len() * 2) as f64)?;
46:     let smooth = if matches!(sampling, BladeSampling::Section) {
47:         0
48:     } else {
49:         1
50:     };
51:     let mut solid = Solid::default();
52:     for rows in rings.windows(2) {
53:         for side in 0..rows[0].len() {
54:             let next = (side + 1) % rows[0].len();
55:             let quad = [rows[0][side], rows[0][next], rows[1][next], rows[1][side]];
56:             face(
57:                 &mut solid,
58:                 quad,
59:                 if p.section == BladeCrossSection::Recessed {
60:                     side as u32 + 1
61:                 } else {
62:                     smooth
63:                 },
64:             )?;
65:         }
66:     }
67:     cap_rings(
68:         &mut solid,
69:         &rings,
70:         p.section == BladeCrossSection::Recessed || matches!(sampling, BladeSampling::Section),
71:     )?;
72:     Ok(solid.positive())
73: }
74: fn cap_rings(
75:     solid: &mut Solid,
76:     rings: &[Vec<Point>],
77:     retain_collinear: bool,
78: ) -> Result<(), String> {
79:     for (ring, reverse) in [
80:         (rings.first().unwrap(), true),
81:         (rings.last().unwrap(), false),
82:     ] {
83:         let mut outline: Vec<_> = ring.iter().map(|p| [p[0], p[2]]).collect();
84:         outline.dedup();
85:         if outline.len() > 1 && outline.first() == outline.last() {
86:             outline.pop();
87:         }
88:         if outline.len() == 1 {
89:             continue;
90:         }
91:         let cap = Region::triangulate(&outline, retain_collinear)?;
92:         for [a, b, c] in cap.triangles {
93:             let point = |i: usize| [cap.points[i][0], ring[0][1], cap.points[i][1]];
94:             if reverse {
95:                 solid.triangle(point(a), point(b), point(c), 0);
96:             } else {
97:                 solid.triangle(point(a), point(c), point(b), 0);
98:             }
99:         }
100:     }

1: //! Error bounds for replacing unresolvable groove tails by broad-face fans.
2: use super::*;
3: 
4: pub(super) const BLADE_SURFACE_ERROR: f64 = 0.00004;
5: const GROOVE_ADDITIONAL_NORMAL_ERROR: f64 = 0.02;
6: 
7: pub(super) fn envelope_floor(p: &BladeProfile<'_>, detail: Detail) -> Result<f64, String> {
8:     let Some(f) = p.fuller else {
9:         return Ok(0.0);
10:     };
11:     let minimum = f
12:         .grooves
13:         .iter()
14:         .map(|g| {
15:             let strip_width = g.mouth_width.get()
16:                 * g.floor_width_ratio
17:                     .get()
18:                     .min((1.0 - g.floor_width_ratio.get()) / 2.0);
19:             FLOAT32_STRIP_SEPARATION / strip_width
20:         })
21:         .fold(0.0, f64::max);
22:     if minimum >= 1.0
23:         || f.grooves
24:             .iter()
25:             .any(|g| g.depth.get() * minimum.powi(2) > detail.error(BLADE_SURFACE_ERROR) / 2.0)
26:     {
27:         return Err("fuller strips cannot be resolved within the surface-error budget".into());
28:     }
29:     Ok(minimum)
30: }
31: pub(super) fn flat_indices(f: &FullerParameters, side: usize) -> Option<[usize; 2]> {
32:     let front_end = 2 + 4 * f.grooves.iter().filter(|g| g.on_face(true)).count();
33:     let back_start = front_end + 2;
34:     let back_end = back_start + 1 + 4 * f.grooves.iter().filter(|g| g.on_face(false)).count();
35:     [[1, front_end], [back_start, back_end]]
36:         .into_iter()
37:         .find(|[a, b]| side >= *a && side < *b)
38: }
39: 
40: // The broad face has the same body curvature and point-thickness approximation.
41: // Bound additional error from removing the recess separately from that existing
42: // chord error, and check both longitudinal and transverse analytic derivatives.
43: pub(super) fn check(
44:     interval: [f64; 2],
45:     side: usize,
46:     flat: [usize; 2],
47:     quad: &[Point; 4],
48:     ring: impl Fn(f64) -> Vec<Point>,
49:     detail: Detail,
50: ) -> Result<(), String> {
51:     let [a, b] = interval;
52:     let left = ring(a);
53:     let right = ring(b);
54:     let broad = unit(cross(
55:         sub(left[flat[1]], left[flat[0]]),
56:         sub(right[flat[0]], left[flat[0]]),
57:     ))?;
58:     let mut vertices: Vec<_> = quad
59:         .iter()
60:         .copied()
61:         .zip([[a, 0.0], [a, 1.0], [b, 1.0], [b, 0.0]])
62:         .collect();
63:     vertices.dedup_by(|a, b| a.0 == b.0);
64:     if vertices.first().map(|v| v.0) == vertices.last().map(|v| v.0) {
65:         vertices.pop();
66:     }
67:     let check = NormalCheck {
68:         interval,
69:         side,
70:         flat,
71:         ring,
72:         broad,
73:         tolerance: detail.error(GROOVE_ADDITIONAL_NORMAL_ERROR),
74:     };
75:     for i in 1..vertices.len().saturating_sub(1) {
76:         let tri = [vertices[0], vertices[i], vertices[i + 1]];
77:         let normal = unit(cross(sub(tri[1].0, tri[0].0), sub(tri[2].0, tri[0].0)))?;
78:         for weights in [
79:             [1.0 / 3.0; 3],
80:             [0.6, 0.2, 0.2],
81:             [0.2, 0.6, 0.2],
82:             [0.2, 0.2, 0.6],
83:         ] {
84:             let param: [f64; 2] =
85:                 std::array::from_fn(|axis| (0..3).map(|j| tri[j].1[axis] * weights[j]).sum());
86:             check.compare(normal, param)?;
87:         }
88:     }
89:     // Even a strip omitted completely has a bounded analytic slope toward the
90:     // broad face. This covers the region after the final triangular fan.
91:     if vertices.len() < 3 {
92:         for t in [0.25, 0.5, 0.75] {
93:             check.compare(broad, [a + (b - a) * t, 0.5])?;
94:         }
95:     }
96:     Ok(())
97: }
