99: struct NormalCheck<F> {
100:     interval: [f64; 2],

201:                 construction_budget(((ys.len() + 1) * profile.len() * 2) as f64)?;
202:                 ys.push(if y <= step * (1.0 + 1e-8) {
203:                     0.0
204:                 } else {
205:                     y - step
206:                 });
207:             }
208:             ys.reverse();
209:             ys
210:         }
211:     })
