214: pub(super) fn face(solid: &mut Solid, quad: [Point; 4], surface: u32) -> Result<(), String> {
215:     let mut vertices = quad.to_vec();
216:     vertices.dedup();
217:     if vertices.first() == vertices.last() {
218:         vertices.pop();
219:     }
220:     if vertices.len() < 3 {
221:         return Ok(());
222:     }
223:     if vertices.iter().flatten().any(|x| !x.is_finite()) {
224:         return Err("blade section contains a nonfinite vertex".into());
225:     }
226:     for i in 1..vertices.len() - 1 {
227:         solid.triangle(vertices[0], vertices[i], vertices[i + 1], surface);
228:     }
229:     Ok(())
230: }
231: 
232: fn section(
233:     p: &BladeProfile<'_>,
234:     y: f64,
235:     w: f64,
236:     d: f64,
237:     detail: Detail,
238:     minimum_envelope: f64,
239: ) -> Vec<PlanarPoint> {
240:     match p.section {
241:         BladeCrossSection::Diamond => vec![[-w, 0.0], [0.0, d], [w, 0.0], [0.0, -d]],
242:         BladeCrossSection::Fullered => vec![
243:             [-w, 0.0],
244:             [-w * 0.72, d],
245:             [-w * 0.28, d * 0.32],
246:             [0.0, d * 0.22],
247:             [w * 0.28, d * 0.32],
248:             [w * 0.72, d],
249:             [w, 0.0],
250:             [0.0, -d],
251:         ],
252:         BladeCrossSection::Hexagonal => vec![
253:             [-w, 0.0],
254:             [-w * 0.72, d],
255:             [w * 0.72, d],
256:             [w, 0.0],
257:             [w * 0.72, -d],
258:             [-w * 0.72, -d],
259:         ],
260:         BladeCrossSection::Lenticular => {
261:             // Curved faces remain real geometry rather than a diamond alias.
262:             let n = detail.samples(24, 12).div_ceil(4) * 4;
263:             (0..n)
264:                 .map(|i| {
265:                     let a = TAU * i as f64 / n as f64;
266:                     [-w * a.cos(), d * a.sin()]
267:                 })
268:                 .collect()
269:         }
270:         BladeCrossSection::Recessed => {
271:             super::groove_sections::section(p.fuller.unwrap(), y, w, d, minimum_envelope)
272:         }
273:     }
274: }

101:     Ok(())
102: }
