104: // Refine the complete section together. Unrelated uniform rows inside the
105: // vanishing groove tail can create features below float32 resolution.
106: fn feature_stations(
107:     p: &BladeProfile<'_>,
108:     ring: impl Fn(f64) -> Vec<Point>,
109:     detail: Detail,
110: ) -> Result<Vec<f64>, String> {
111:     let mut features = vec![0.0, p.length];
112:     if p.ricasso > 0.0 {
113:         features.push(p.ricasso);
114:     }
115:     if let Some(start) = p.point_start() {
116:         features.push(start);
117:     }
118:     if let Some(f) = p.fuller {
119:         for g in &f.grooves {
120:             features.extend([
121:                 g.start.get(),
122:                 g.start.get() + g.entry_length.get(),
123:                 g.end.get() - g.exit_length.get(),
124:                 g.end.get(),
125:             ]);
126:         }
127:     }
128:     features.sort_by(f64::total_cmp);
129:     features.dedup();
130:     let mut stations = vec![0.0];
131:     for pair in features.windows(2) {
132:         refine_sections(pair[0], pair[1], &ring, detail, 0, &mut stations)?;
133:     }
134:     Ok(stations)
135: }
136: pub(super) fn refine_sections(
137:     a: f64,
138:     b: f64,
139:     ring: &impl Fn(f64) -> Vec<Point>,
140:     detail: Detail,
141:     depth: usize,
142:     out: &mut Vec<f64>,
143: ) -> Result<(), String> {
144:     let (left, right) = (ring(a), ring(b));
145:     let mut deviation = 0.0_f64;
146:     for t in [0.25, 0.5, 0.75] {
147:         let sampled = ring(a + (b - a) * t);
148:         for i in 0..left.len() {
149:             let line = sub(right[i], left[i]);
150:             let length2 = dot(line, line);
151:             let u = if length2 > 0.0 {
152:                 (dot(sub(sampled[i], left[i]), line) / length2).clamp(0.0, 1.0)
153:             } else {
154:                 0.0
155:             };
156:             deviation = deviation.max(magnitude(sub(sampled[i], add(left[i], mul(line, u)))));
157:         }
158:     }
159:     if (b - a) > detail.error(0.015)
160:         || deviation > detail.error(blade_reduction::BLADE_SURFACE_ERROR) / 2.0
161:     {
162:         if depth >= f64::MANTISSA_DIGITS as usize {
163:             return Err("blade sampling exceeds its surface-error budget".into());
164:         }
165:         let mid = (a + b) / 2.0;
166:         refine_sections(a, mid, ring, detail, depth + 1, out)?;
167:         refine_sections(mid, b, ring, detail, depth + 1, out)?;
168:     } else {
169:         construction_budget(((out.len() + 1) * left.len() * 2) as f64)?;
170:         out.push(b);
171:     }
172:     Ok(())
173: }
174: 
175: fn baseline_stations(
176:     length: f64,
177:     ring: impl Fn(f64) -> Vec<Point>,
178:     sampling: BladeSampling,
179:     detail: Detail,
180: ) -> Result<Vec<f64>, String> {
181:     Ok(match sampling {
182:         BladeSampling::Loft(n) => (0..=n)
183:             .map(|i| length * i as f64 / n as f64)
184:             .collect::<Vec<_>>(),
185:         BladeSampling::Section => {
186:             let mut ys = vec![length];
187:             loop {
188:                 let y = *ys.last().unwrap();
189:                 if y <= 0.0 {
190:                     break;
191:                 }
192:                 let profile = ring(y);
193:                 let edge = (0..profile.len())
194:                     .map(|i| magnitude(sub(profile[i], profile[(i + 1) % profile.len()])))
195:                     .filter(|&d| d > 0.0)
196:                     .fold(f64::INFINITY, f64::min);
197:                 let step = detail.error(0.03).min(edge * 40.0);
198:                 if !step.is_finite() || step <= 0.0 {
199:                     return Err("blade section has no area".into());
200:                 }

201:     let length = p.length.get();
202:     let width = p.width.get();
203:     let root = p.root.map_or(0.035, Metres::get);
204:     let curvature = p.curvature.map_or(0.1, Metres::get);
205:     let belly = p.belly_position.map_or(0.42, Ratio::get);
206:     let point = p.point_length.map_or(0.24, Ratio::get);
207:     let root_length = p.root_length.map_or(0.08, Metres::get);
208:     let boundary = |side: f64| {
209:         adaptive_curve(
210:             |t| {
211:                 let phase = if t < belly {
212:                     t / belly
213:                 } else {
214:                     (1.0 - t) / (1.0 - belly)
215:                 };
216:                 let swelling = (PI * phase / 2.0).sin().powi(2);
217:                 let tip = ((1.0 - t) / point).clamp(0.0, 1.0);
218:                 let proportion = if side > 0.0 {
219:                     0.75 + p.edge_curvature.map_or(0.24, Ratio::get) * 0.2
220:                 } else {
221:                     0.25 + p.spine_curvature.map_or(0.2, Ratio::get) * 0.2
222:                 };
223:                 let breadth = (root / 2.0 * (1.0 - swelling) + width * swelling * proportion) * tip;
224:                 [curvature * t * t + side * breadth, length * t]
225:             },
226:             CurveQuality {
227:                 minimum_segments: 18,
228:                 max_chord: length / 28.0,
229:                 max_deviation: width / 220.0,
230:             },
231:             detail,
232:         )
233:     };
234:     let mut outline = vec![[root / 2.0, -root_length]];
235:     outline.extend(boundary(1.0));
236:     let mut spine = boundary(-1.0);
237:     spine.pop();
238:     outline.extend(spine.into_iter().rev());
239:     outline.push([-root / 2.0, -root_length]);
240:     outline
241: }

1: //! Forged blade, axe and spear surface profiles.
2: use super::*;
