9: pub(super) fn axe(p: &AxeParameters, detail: Detail) -> Result<Solid, String> {
10:     let width = p.width.get();
11:     let height = p.height.get();
12:     let thickness = p.thickness.get();
13:     let side = p.side.map_or(1.0, Direction::sign);
14:     let root = p.root_width.map_or((width * 0.18).min(0.055), Metres::get);
15:     let flare = p.flare.map_or(0.0, Ratio::get);
16:     let curvature = p.curvature.map_or(0.12, Ratio::get);
17:     let beard = p.beard.map_or(0.35, Ratio::get);
18:     let upper = p.upper_shoulder.map_or(0.38, Ratio::get);
19:     let lower = p.lower_shoulder.map_or(0.26, Ratio::get);
20:     let mut outline = vec![
21:         [-root * side, height * upper],
22:         [
23:             width * 0.3 * side,
24:             height * (upper - p.upper_cusp.map_or(0.0, Ratio::get)),
25:         ],
26:         [
27:             width * (0.68 + flare * 0.12) * side,
28:             height * (0.48 + p.toe.map_or(0.0, Ratio::get)),
29:         ],
30:     ];
31:     outline.extend(adaptive_curve(
32:         |t| {
33:             [
34:                 width * (0.82 + flare * (t - 0.5) + curvature * (PI * t).sin()) * side,
35:                 height * (0.42 - t * 0.9),
36:             ]
37:         },
38:         CurveQuality {
39:             minimum_segments: 8,
40:             max_chord: width.max(height) / 18.0,
41:             max_deviation: width / 220.0,
42:         },
43:         detail,
44:     ));
45:     outline.extend([
46:         [
47:             width * beard * side,
48:             -height
49:                 * (0.34
50:                     + p.beard_drop.map_or(beard * 0.45, Ratio::get)
51:                     + p.heel.map_or(0.0, Ratio::get)),
52:         ],
53:         [
54:             width * 0.18 * side,
55:             -height * (lower - p.lower_cusp.map_or(0.0, Ratio::get)),
56:         ],
57:         [-root * side, -height * lower],
58:     ]);
59:     if p.shoulder_construction == Some(AxeShoulderConstruction::Straight) {
60:         outline.remove(outline.len() - 2);
61:         outline.remove(1);
62:     }
63:     if side < 0.0 {
64:         outline.reverse();
65:     }
66:     let thickness_root = p.root_width.map_or(width * 0.18, Metres::get);
67:     Solid::shaped_plate(
68:         &outline,
69:         |x, y| {
70:             let t = ((0.42 - y / height) / 0.9).clamp(0.0, 1.0);
71:             let edge = width * (0.82 + flare * (t - 0.5) + curvature * (PI * t).sin());
72:             let remaining =
73:                 1.0 - ((side * x + thickness_root) / (edge + thickness_root)).clamp(0.0, 1.0);
74:             0.0006 + (thickness - 0.0006) * remaining
75:         },
76:         detail,
77:     )
78: }
