88: pub(super) fn diamond_blade(p: &DiamondBladeParameters, detail: Detail) -> Solid {
89:     let length = p.length.get();
90:     let width = p.width.get();
91:     let thickness = p.thickness.get();
92:     let taper = p.taper.map_or(0.92, Ratio::get);
93:     let samples = detail.samples(14, 4);
94:     let ring = |t: f64| {
95:         let w = width * 0.5 * (1.0 - t * taper);
96:         let d = thickness * 0.5 * (1.0 - t * 0.7);
97:         [
98:             [-w, t * length, 0.0],
99:             [0.0, t * length, d],
100:             [w, t * length, 0.0],

101:             [0.0, t * length, -d],
102:         ]
103:     };
104:     let mut solid = Solid::default();
105:     for i in 0..samples {
106:         let a = ring(i as f64 / samples as f64);
107:         let b = ring((i + 1) as f64 / samples as f64);
108:         for side in 0..4 {
109:             let next = (side + 1) % 4;
110:             solid.quad(a[side], a[next], b[next], b[side], 0);
111:         }
112:     }
113:     // Both finite section ends close the solid; the old preview omitted these.
114:     for (t, reverse) in [(0.0, true), (1.0, false)] {
115:         let ring = ring(t);
116:         for side in 0..4 {
117:             let a = ring[side];
118:             let b = ring[(side + 1) % 4];
119:             if reverse {
120:                 solid.triangle([0.0, t * length, 0.0], b, a, 0);
121:             } else {
122:                 solid.triangle([0.0, t * length, 0.0], a, b, 0);
123:             }
124:         }
125:     }
126:     solid.positive()
127: }
