129: pub(super) fn fork(p: &ForkParameters, detail: Detail) -> Result<Solid, String> {
130:     let length = p.length.get();
131:     let width = p.width.get();
132:     let half = width / 2.0;
133:     let root = p.base_width.get() / 2.0;
134:     let tine = p.working_tine_width().get();
135:     let taper = p.tine_taper.map_or(0.55, Ratio::get);
136:     let shoulder = p.shoulder_blend.map_or(0.2, Ratio::get);
137:     let crotch = p.crotch.map_or(0.34, Ratio::get);
138:     let round = p.crotch_round.map_or(0.05, Ratio::get);
139:     Solid::prism(
140:         &[
141:             [-root, 0.0],
142:             [-half, length * shoulder],
143:             [-half, length],
144:             [-half + tine * taper, length * 0.94],
145:             [-tine * 0.45, length * (crotch + round)],
146:             [0.0, length * crotch],
147:             [tine * 0.45, length * (crotch + round)],
148:             [half - tine * taper, length * 0.94],
149:             [half, length],
150:             [half, length * shoulder],
151:             [root, 0.0],
152:         ],
153:         p.thickness.get(),
154:         detail,
155:     )
156: }
