158: pub(super) fn partisan(p: &PartisanParameters, detail: Detail) -> Result<Solid, String> {
159:     let length = p.length.get();
160:     let width = p.width.get();
161:     let lug = p.lug_width.get() / 2.0;
162:     let belly = p.belly_position.map_or(0.32, Ratio::get);
163:     let root = p.root_width.map_or(width * 0.18, Metres::get);
164:     let drop = p.lug_drop.map_or(0.08, Ratio::get);
165:     let sweep = p.lug_sweep.map_or(0.055, Ratio::get);
166:     let acuteness = p.acuteness.map_or(1.0, Ratio::get);
167:     let shoulder = length * belly.clamp(0.18, 0.48);
168:     let point = shoulder + (length - shoulder) * (1.0 - 1.0 / (1.0 + acuteness));
169:     Solid::prism(
170:         &[
171:             [0.0, length],
172:             [-width * 0.34, point],
173:             [-width / 2.0, shoulder],
174:             [-width * 0.34, length * 0.12],
175:             [-lug, length * drop],
176:             [-lug * 0.72, 0.0],
177:             [-root / 2.0, length * sweep],
178:             [root / 2.0, length * sweep],
179:             [lug * 0.72, 0.0],
180:             [lug, length * drop],
181:             [width * 0.34, length * 0.12],
182:             [width / 2.0, shoulder],
183:             [width * 0.34, point],
184:         ],
185:         p.thickness.get(),
186:         detail,
187:     )
188: }
