1: //! Closed asymmetric wedge sections, with capped or continuously pointed ends.
2: use super::*;
3: 
4: pub(super) fn blade(p: &BladeParameters, detail: Detail) -> Result<Solid, String> {
5:     p.validate_form().map_err(|e| e.to_string())?;
6:     let point = p.point_curve()?;
7:     let ring = |y| section(p, y, point.as_ref());
8:     let mut boundaries = vec![0.0];
9:     if let Some(start) = p.point_start() {
10:         boundaries.push(start);
11:     }
12:     boundaries.push(p.length.get());
13:     let mut stations = vec![0.0];
14:     for pair in boundaries.windows(2) {
15:         blade_sections::refine_sections(pair[0], pair[1], &ring, detail, 0, &mut stations)?;
16:     }
17:     let rings: Vec<_> = stations.into_iter().map(ring).collect();
18:     let mut solid = Solid::default();
19:     for pair in rings.windows(2) {
20:         for side in 0..pair[0].len() {
21:             let next = (side + 1) % pair[0].len();
22:             blade_sections::face(
23:                 &mut solid,
24:                 [pair[0][side], pair[0][next], pair[1][next], pair[1][side]],
25:                 side as u32 + 1,
26:             )?;
27:         }
28:     }
29:     cap(&mut solid, &rings[0], true)?;
30:     if point.is_none() {
31:         cap(&mut solid, rings.last().unwrap(), false)?;
32:     }
33:     Ok(solid.positive())
34: }
35: 
36: fn section(p: &BladeParameters, y: f64, point: Option<&PointCurve>) -> Vec<Point> {
37:     let [w, thickness, edge] = p.section_dimensions(y, point);
38:     let single = p.single_edge.map_or(0.0, Ratio::get);
39:     let center = p.curvature.map_or(0.0, Metres::get) * (y / p.length.get()).powi(2);
40:     if p.section == Some(ForgedBladeSection::Triangular) {
41:         // Full transverse height is authored; the centroid stays on the axis.
42:         return vec![
43:             [center - w, y, -thickness / 3.0],
44:             [center, y, 2.0 * thickness / 3.0],
45:             [center + w, y, -thickness / 3.0],
46:         ];
47:     }
48:     if p.section == Some(ForgedBladeSection::Diamond) {
49:         return vec![
50:             [center - w, y, 0.0],
51:             [center, y, thickness / 2.0],
52:             [center + w, y, 0.0],
53:             [center, y, -thickness / 2.0],
54:         ];
55:     }
56:     let left = center - w * (1.0 - single);
57:     let right = center + w * (1.0 + single);
58:     let ridge = left + w * (1.0 - single);
59:     // An extreme single-edge section has its full-thickness spine on one side.
60:     // Omit the collinear edge-floor landmarks there before constructing faces.
61:     let mut ring = Vec::with_capacity(6);
62:     if single != 1.0 {
63:         ring.push([left, y, -edge / 2.0]);
64:     }
65:     ring.push([ridge, y, -thickness / 2.0]);
66:     if single != -1.0 {
67:         ring.push([right, y, -edge / 2.0]);
68:         ring.push([right, y, edge / 2.0]);
69:     }
70:     ring.push([ridge, y, thickness / 2.0]);
71:     if single != 1.0 {
72:         ring.push([left, y, edge / 2.0]);
73:     }
74:     ring.reverse();
75:     ring
76: }
77: 
78: fn cap(solid: &mut Solid, ring: &[Point], reverse: bool) -> Result<(), String> {
79:     let outline: Vec<_> = ring.iter().map(|p| [p[0], p[2]]).collect();
80:     let cap = Region::triangulate(&outline, true)?;
81:     for [a, b, c] in cap.triangles {
82:         let vertex = |i: usize| [cap.points[i][0], ring[0][1], cap.points[i][1]];
83:         if reverse {
84:             solid.triangle(vertex(a), vertex(b), vertex(c), 0);
85:         } else {
86:             solid.triangle(vertex(a), vertex(c), vertex(b), 0);
87:         }
88:     }
89:     Ok(())
90: }

1: //! Sorted groove landmarks follow the actual recessed face, including inactive lanes.
2: use super::*;
3: struct GrooveCut {
4:     center: f64,
5:     mouth: f64,
6:     floor: f64,
7:     depth: f64,
8: }
9: impl GrooveCut {
10:     fn at(&self, x: f64) -> f64 {
11:         let distance = (x - self.center).abs();
12:         if distance >= self.mouth {
13:             0.0
14:         } else if distance <= self.floor {
15:             self.depth
16:         } else {
17:             self.depth * (self.mouth - distance) / (self.mouth - self.floor)
18:         }
19:     }
20: }
21: pub(super) fn section(
22:     f: &FullerParameters,
23:     y: f64,
24:     w: f64,
25:     d: f64,
26:     minimum_envelope: f64,
27: ) -> Vec<PlanarPoint> {
28:     let flat = w * (1.0 - f.bevel_width_ratio.get());
29:     let mut result = vec![[-w, 0.0]];
30:     for front in [true, false] {
31:         let sign = if front { 1.0 } else { -1.0 };
32:         let cuts: Vec<_> = f
33:             .grooves
34:             .iter()
35:             .filter(|g| g.on_face(front))
36:             .map(|g| {
37:                 let q = g.envelope(y);
38:                 let q = if q < minimum_envelope { 0.0 } else { q };
39:                 let mouth = g.mouth_width.get() * q / 2.0;
40:                 GrooveCut {
41:                     center: flat * g.lateral_position.get(),
42:                     mouth,
43:                     floor: mouth * g.floor_width_ratio.get(),
44:                     depth: g.depth.get() * q * q,
45:                 }
46:             })
47:             .collect();
48:         let mut face = vec![[-flat, sign * d]];
49:         for (index, c) in cuts.iter().enumerate() {
50:             for (x, depth) in [
51:                 (c.center - c.mouth, 0.0),
52:                 (c.center - c.floor, c.depth),
53:                 (c.center + c.floor, c.depth),
54:                 (c.center + c.mouth, 0.0),
55:             ] {
56:                 let cut = depth
57:                     + cuts
58:                         .iter()
59:                         .enumerate()
60:                         .filter(|(i, _)| *i != index)
61:                         .map(|(_, other)| other.at(x))
62:                         .sum::<f64>();
63:                 face.push([x, sign * (d - cut)]);
64:             }
65:         }
66:         face.push([flat, sign * d]);
67:         face.sort_by(|a, b| a[0].total_cmp(&b[0]));
68:         if !front {
69:             face.reverse();
70:         }
71:         result.extend(face);
72:         result.push([if front { w } else { -w }, 0.0]);
73:     }
74:     result.pop();
75:     result
76: }

1: //! Canonical controlling hand frame selection.
2: use super::*;
3: use std::collections::BTreeMap;
4: pub(super) fn grip_point(recipe: &Recipe, frames: &BTreeMap<String, Point>) -> Point {
5:     if let Some(&grip) = frames.get(SHIELD_GRIP_FRAME) {
6:         return grip;
7:     }
8:     if let (Some(clearance), Some(&base), Some(&top)) = (
9:         recipe.grip_clearance,
10:         frames.get(GRIP_BASE_FRAME),
11:         frames.get(GRIP_TOP_FRAME),
12:     ) {
13:         return add(top, mul(normalize(sub(base, top)), clearance.get()));
14:     }
15:     if let Some(grip) = recipe
16:         .components
17:         .iter()
18:         .rev()
19:         .find(|c| c.role == Some(crate::ComponentRole::Grip))
20:         .and_then(|c| c.id.as_ref())
21:         .and_then(|id| frames.get(&format!("{id}.center")))
22:     {
23:         return *grip;
24:     }
25:     if let Some(&grip) = frames.get(GRIP_CENTER_FRAME) {
26:         return grip;
27:     }
28:     if let (Some(&bottom), Some(&top)) =
29:         (frames.get(SHAFT_BOTTOM_FRAME), frames.get(SHAFT_TOP_FRAME))
30:     {
31:         let length = magnitude(sub(top, bottom));
32:         return lerp(bottom, top, (length * 0.2).clamp(0.18, 0.45) / length);
33:     }
34:     [0.0; 3]
35: }

1: //! Resolve reduced groove fans at their actual float32 envelope cutoffs.
2: use super::*;
3: 
4: pub(super) fn refine(
5:     stations: &mut Vec<f64>,
6:     fuller: &FullerParameters,
7:     minimum_envelope: f64,
8:     ring: &impl Fn(f64, f64) -> Vec<Point>,
9:     detail: Detail,
10: ) -> Result<(), String> {
11:     let mut cutoffs: Vec<_> = fuller
12:         .grooves
13:         .iter()
14:         .flat_map(|g| {
15:             [GrooveEnd::Entry, GrooveEnd::Exit].map(|end| end.cutoff(g, minimum_envelope))
16:         })
17:         .collect();
18:     cutoffs.sort_by(f64::total_cmp);
19:     cutoffs.dedup();
20:     // Every unsuccessful pass must insert at least one previously absent cutoff.
21:     for _ in 0..=cutoffs.len() {
22:         let mut next = vec![stations[0]];
23:         let mut changed = false;
24:         for pair in stations.windows(2) {
25:             if let Err(error) =
26:                 check_interval([pair[0], pair[1]], fuller, minimum_envelope, ring, detail)
27:             {
28:                 let inside: Vec<_> = cutoffs
29:                     .iter()
30:                     .copied()
31:                     .filter(|&y| y > pair[0] && y < pair[1])
32:                     .collect();
33:                 if inside.is_empty() {
34:                     return Err(error);
35:                 }
36:                 next.extend(inside);
37:                 changed = true;
38:             }
39:             next.push(pair[1]);
40:         }
41:         if !changed {
42:             return Ok(());
43:         }
44:         construction_budget((next.len() * ring(0.0, minimum_envelope).len() * 2) as f64)?;
45:         *stations = next;
46:     }
47:     Err("groove transition exceeds its bounded cutoff refinement".into())
48: }
49: 
50: fn check_interval(
51:     [a, b]: [f64; 2],
52:     fuller: &FullerParameters,
53:     minimum_envelope: f64,
54:     ring: &impl Fn(f64, f64) -> Vec<Point>,
55:     detail: Detail,
56: ) -> Result<(), String> {
57:     let [left, right] = [ring(a, minimum_envelope), ring(b, minimum_envelope)];
58:     let [raw_left, raw_right] = [ring(a, 0.0), ring(b, 0.0)];
59:     for side in 0..left.len() {
60:         let next = (side + 1) % left.len();
61:         let quad = [left[side], left[next], right[next], right[side]];
62:         if quad
63:             != [
64:                 raw_left[side],
65:                 raw_left[next],
66:                 raw_right[next],
67:                 raw_right[side],
68:             ]
69:             && let Some(flat) = blade_reduction::flat_indices(fuller, side)
70:         {
71:             blade_reduction::check([a, b], side, flat, &quad, |y| ring(y, 0.0), detail)?;
72:         }
73:     }
74:     Ok(())
75: }
76: 
77: enum GrooveEnd {
78:     Entry,
79:     Exit,
80: }
81: 
82: impl GrooveEnd {
83:     fn cutoff(self, groove: &FullerGroove, minimum_envelope: f64) -> f64 {
84:         let [mut lo, mut hi] = match self {
85:             Self::Entry => [
86:                 groove.start.get(),
87:                 groove.start.get() + groove.entry_length.get(),
88:             ],
89:             Self::Exit => [
90:                 groove.end.get() - groove.exit_length.get(),
91:                 groove.end.get(),
92:             ],
93:         };
94:         for _ in 0..f64::MANTISSA_DIGITS {
95:             let mid = (lo + hi) / 2.0;
96:             let retained = groove.envelope(mid) >= minimum_envelope;
97:             if retained == matches!(self, Self::Entry) {
98:                 hi = mid;
99:             } else {
100:                 lo = mid;
101:             }
102:         }
103:         // Keep the bracket endpoint on the representable side of the cutoff.
104:         match self {
105:             Self::Entry => hi,
106:             Self::Exit => lo,
107:         }
108:     }
109: }

