129:     fn lower_dimensions(&self, a: f64, b: f64) -> [f64; 2] {
130:         if self.p.point_start().is_some_and(|start| a >= start) {
131:             return self.p.dimensions(b, self.point);
132:         }
133:         let ta = ((a - self.p.ricasso) / (self.p.length - self.p.ricasso)).clamp(0.0, 1.0);
134:         let tb = ((b - self.p.ricasso) / (self.p.length - self.p.ricasso)).clamp(0.0, 1.0);
135:         let sa = (PI * ta).sin();
136:         let sb = (PI * tb).sin();
137:         let sine_min = sa.min(sb);
138:         let sine_max = if ta <= 0.5 && tb >= 0.5 {
139:             1.0
140:         } else {
141:             sa.max(sb)
142:         };
143:         let plan = match self.p.plan {
144:             BladePlan::Straight => 1.0,
145:             BladePlan::Leaf => 0.78 + 0.22 * sine_min,
146:             BladePlan::Cleaver => 0.9 + 0.24 * sine_min,
147:         };
148:         let belly = 1.0
149:             + self.p.belly
150:                 * if self.p.belly >= 0.0 {
151:                     sine_min
152:                 } else {
153:                     sine_max
154:                 };
155:         [
156:             self.p.width / 2.0 * plan * (0.025 + 0.975 * (1.0 - tb).powf(self.p.taper)) * belly,
157:             self.p.body(b)[1],
158:         ]
159:     }
160:     fn tip_interval(&self, a: f64, b: f64) -> bool {
161:         let Some(point) = self.point else {
162:             return false;
163:         };
164:         let Some(start) = self.p.point_start() else {
165:             return false;
166:         };
167:         if b != self.p.length || a < start {
168:             return false;
169:         }
170:         let delta = b - a;
171:         let mut envelopes = Vec::new();
172:         for g in &self.f.grooves {
173:             if g.end.get() <= a {
174:                 envelopes.push(0.0);
175:             } else if g.end.get() == b && a >= b - g.exit_length.get() {
176:                 // S(u)<=10u^3; division by the point's linear width bound
177:                 // leaves positive powers of delta for both mouth and depth.
178:                 envelopes.push(10.0 * (delta / g.exit_length.get()).powi(3));
179:             } else {
180:                 return false;
181:             }
182:         }
183:         let width = point.minimum_width_slope() * delta;
184:         let depth = self.p.body(b)[1] * width / self.p.body(start)[0];
185:         self.inside(&envelopes, width, depth)
186:     }
187:     fn interval(&mut self, a: f64, b: f64, level: usize) -> Result<(), RecipeError> {
188:         if self.remaining == 0 {
189:             return Err(RecipeError::Budget);
190:         }
191:         self.remaining -= 1;
192:         if self.tip_interval(a, b) {
193:             return Ok(());
194:         }
195:         let envelopes: Vec<_> = self
196:             .f
197:             .grooves
198:             .iter()
199:             .map(|g| {
200:                 let peak = ((g.start.get() + g.entry_length.get() + g.end.get()
201:                     - g.exit_length.get())
202:                     / 2.0)
203:                     .clamp(a, b);
204:                 g.envelope(peak)
205:             })
206:             .collect();
207:         let [w, d] = self.lower_dimensions(a, b);
208:         if self.inside(&envelopes, w, d) {
209:             return Ok(());
210:         }
211:         let mid = (a + b) / 2.0;
212:         let envelopes: Vec<_> = self.f.grooves.iter().map(|g| g.envelope(mid)).collect();
213:         let [w, d] = self.p.dimensions(mid, self.point);
214:         if !self.inside(&envelopes, w, d) {
215:             return Err(RecipeError::Proportion);
216:         }
217:         if level >= MAX_CLEARANCE_DEPTH {
218:             return Err(RecipeError::Budget);
219:         }
220:         self.interval(a, mid, level + 1)?;
221:         self.interval(mid, b, level + 1)
222:     }
223: }

