57:         } else if distance <= self.floor {
58:             self.depth
59:         } else {
60:             self.depth * (self.mouth - distance) / (self.mouth - self.floor)
61:         }
62:     }
63:     fn corners(&self) -> [f64; 4] {
64:         [
65:             self.center - self.mouth,
66:             self.center - self.floor,
67:             self.center + self.floor,
68:             self.center + self.mouth,
69:         ]
70:     }
71: }
