55: impl BladeProfile<'_> {
56:     fn progress(&self, y: f64) -> f64 {
57:         ((y - self.ricasso) / (self.length - self.ricasso)).clamp(0.0, 1.0)
58:     }
59:     pub(crate) fn body(&self, y: f64) -> [f64; 2] {
60:         let t = self.progress(y);
61:         let sine = (PI * t).sin();
62:         let plan = match self.plan {
