1: //! Continuous outline and terminal section of an asymmetric forged blade.
2: use super::*;
3: use std::f64::consts::PI;
4: 
5: /// Full thickness at the cutting edge before an authored point begins.
6: pub(crate) const BLADE_EDGE_THICKNESS: f64 = 0.0006;
7: /// Fraction of root thickness removed by the body taper at its distal end.
8: const DISTAL_THICKNESS_REDUCTION: f64 = 0.65;
9: 
10: impl BladeParameters {
11:     pub(crate) fn heel_center(&self) -> [f64; 3] {
12:         [
13:             self.single_edge.map_or(0.0, Ratio::get) * self.width.get() / 2.0,
14:             0.0,
15:             0.0,
16:         ]
17:     }
18:     pub(crate) fn body_half_width(&self, y: f64) -> f64 {
19:         let t = (y / self.length.get()).clamp(0.0, 1.0);
20:         let tip = self.tip_width.map_or(0.025, Ratio::get);
21:         self.width.get() / 2.0
22:             * (tip + (1.0 - tip) * (1.0 - t).powf(self.taper.map_or(1.25, Ratio::get)))
23:             * (1.0 + self.belly.map_or(0.0, Ratio::get) * (PI * t).sin())
24:     }
25: 
26:     pub(crate) fn point_start(&self) -> Option<f64> {
27:         self.point
28:             .as_ref()
29:             .map(|p| p.start.get() * self.length.get())
30:     }
31: 
32:     pub(crate) fn point_curve(&self) -> Result<Option<PointCurve>, String> {
33:         let Some(point) = &self.point else {
34:             return Ok(None);
35:         };
36:         let y = self.point_start().unwrap();
37:         let t = point.start.get();
38:         let tip = self.tip_width.map_or(0.025, Ratio::get);
39:         let taper = self.taper.map_or(1.25, Ratio::get);
40:         let belly = self.belly.map_or(0.0, Ratio::get);
41:         let (sin, cos) = (PI * t).sin_cos();
42:         let slope = self.width.get() / (2.0 * self.length.get())
43:             * (-(1.0 - tip) * taper * (1.0 - t).powf(taper - 1.0) * (1.0 + belly * sin)
44:                 + (tip + (1.0 - tip) * (1.0 - t).powf(taper)) * belly * PI * cos);
45:         PointCurve::new(
46:             y,
47:             self.length.get(),
48:             self.body_half_width(y),
49:             slope,
50:             point.roundness.get(),
51:         )
52:         .map(Some)
53:     }
54: 
55:     /// Half-width, full ridge thickness, and full edge thickness. The same
56:     /// envelope closes every transverse landmark at the exact authored tip.
57:     pub(crate) fn section_dimensions(&self, y: f64, point: Option<&PointCurve>) -> [f64; 3] {
58:         let t = (y / self.length.get()).clamp(0.0, 1.0);
59:         let mut width = self.body_half_width(y);
60:         let mut envelope = 1.0;
61:         if let (Some(start), Some(point)) = (self.point_start(), point)
62:             && y >= start
63:         {
64:             width = point.width_at(y);
65:             let q = width / self.body_half_width(start);
66:             envelope = q * (2.0 - q);
67:         }
68:         if matches!(
69:             self.section,
70:             Some(ForgedBladeSection::Diamond | ForgedBladeSection::Triangular)
71:         ) {
72:             return [
73:                 width,
74:                 2.0 * width * self.thickness.get() / self.width.get(),
75:                 0.0,
76:             ];
77:         }
78:         [
79:             width,
80:             self.thickness.get() * (1.0 - DISTAL_THICKNESS_REDUCTION * t) * envelope,
81:             BLADE_EDGE_THICKNESS * envelope,
82:         ]
83:     }
84: 
85:     pub(crate) fn validate_form(&self) -> Result<(), RecipeError> {
86:         let tip = self.tip_width.map_or(0.025, Ratio::get);
87:         let section_valid = if matches!(
88:             self.section,
89:             Some(ForgedBladeSection::Diamond | ForgedBladeSection::Triangular)
90:         ) {
91:             self.single_edge.map_or(0.0, Ratio::get) == 0.0
92:         } else {
93:             self.thickness.get() * (1.0 - DISTAL_THICKNESS_REDUCTION) >= BLADE_EDGE_THICKNESS
94:         };
95:         let valid = self.taper.map_or(1.25, Ratio::get) > 0.0
96:             && section_valid
97:             && (-1.0..=1.0).contains(&self.single_edge.map_or(0.0, Ratio::get))
98:             && (0.0..=1.0).contains(&tip)
99:             && (tip > 0.0 || self.point.is_some())
100:             && self.belly.map_or(0.0, Ratio::get) > -1.0;
101:         if !valid
102:             || self.point.as_ref().is_some_and(|p| {
103:                 !(p.start.get() > 0.0
104:                     && p.start.get() < 1.0
105:                     && (0.0..=1.0).contains(&p.roundness.get()))
106:             })
107:         {
108:             return Err(RecipeError::Proportion);
109:         }
110:         self.point_curve().map_err(|_| RecipeError::Proportion)?;
111:         Ok(())
112:     }
113: }

1: //! Input bounds for dimensioned forged blanks.
2: use super::*;
3: 
4: const MAX_PLATE_SPANS: usize = 64;
5: const MAX_PLATE_THICKNESS_STATIONS: usize = 16;
6: 
7: pub(super) fn validate(p: &ContouredPlateParameters) -> Checked {
8:     positive(p.width.get())?;
9:     positive(p.length.get())?;
10:     require(
11:         (3..=MAX_PLATE_SPANS).contains(&p.boundary.len()),
12:         RecipeError::Budget,
13:     )?;
14:     let check_point = |point: [Ratio; 2]| {
15:         require(
16:             (-1.0..=1.0).contains(&point[0].get()) && (0.0..=1.0).contains(&point[1].get()),
17:             RecipeError::Profile,
18:         )
19:     };
20:     check_point(p.start)?;
21:     for span in &p.boundary {
22:         check_point(span.end())?;
23:         if let PlateBoundarySpan::Cubic { controls, .. } = span {
24:             for &point in controls {
25:                 check_point(point)?;
26:             }
27:         }
28:     }
29:     require(
30:         p.boundary.last().unwrap().end() == p.start,
31:         RecipeError::Profile,
32:     )?;
33:     for endpoint in [0.0, 1.0] {
34:         require(
35:             std::iter::once(p.start)
36:                 .chain(p.boundary.iter().map(PlateBoundarySpan::end))
37:                 .any(|point| point[1].get() == endpoint),
38:             RecipeError::Profile,
39:         )?;
40:     }
41:     match &p.surface {
42:         PlateSurface::Ridge { stations } => ridge(p, stations),
43:         PlateSurface::Profile { stations } => profile(p, stations),
44:     }
45: }
46: 
47: fn positions(values: impl Iterator<Item = f64>) -> Checked {
48:     let values: Vec<_> = values.collect();
49:     require(
50:         (2..=MAX_PLATE_THICKNESS_STATIONS).contains(&values.len()),
51:         RecipeError::Budget,
52:     )?;
53:     require(
54:         values.first() == Some(&0.0) && values.last() == Some(&1.0),
55:         RecipeError::Profile,
56:     )?;
57:     require(values.windows(2).all(|p| p[0] < p[1]), RecipeError::Profile)
58: }
59: 
60: fn ridge(p: &ContouredPlateParameters, stations: &[PlateThicknessStation]) -> Checked {
61:     positions(stations.iter().map(|s| s.at.get()))?;
62:     for station in stations {
63:         require(
64:             (0.0..=1.0).contains(&station.at.get()),
65:             RecipeError::Profile,
66:         )?;
67:         nonnegative(station.flat_half_width.get())?;
68:         nonnegative(station.hollow_depth())?;
69:         require(
70:             station.hollow_depth() <= (station.ridge.get() - station.edge.get()) / 4.0,
71:             RecipeError::Profile,
72:         )?;
73:         let terminal = station.at.get() == 0.0 || station.at.get() == 1.0;
74:         if terminal && station.edge.get() == 0.0 && station.ridge.get() == 0.0 {
75:             require(
76:                 station.ridge_half_width.get() == 0.0 && station.flat_half_width.get() == 0.0,
77:                 RecipeError::Profile,
78:             )?;
79:             let points = std::iter::once(p.start).chain(
80:                 p.boundary
81:                     .iter()
82:                     .take(p.boundary.len() - 1)
83:                     .map(PlateBoundarySpan::end),
84:             );
85:             require(
86:                 points.filter(|point| point[1] == station.at).count() == 1,
87:                 RecipeError::Profile,
88:             )?;
89:         } else {
90:             positive(station.ridge_half_width.get())?;
91:             require(
92:                 station.ridge_half_width.get() - station.flat_half_width.get()
93:                     >= MIN_MANUFACTURED_METRES,
94:                 RecipeError::Profile,
95:             )?;
96:             positive(station.edge.get())?;
97:             positive(station.ridge.get())?;
98:             require(
99:                 station.ridge.get() >= station.edge.get(),
100:                 RecipeError::Profile,

101:             )?;
102:         }
103:     }
104:     Ok(())
105: }
106: 
107: const MAX_SECTION_LANDMARKS: usize = 32;
108: 
109: fn profile(p: &ContouredPlateParameters, stations: &[PlateSectionStation]) -> Checked {
110:     positions(stations.iter().map(|s| s.at.get()))?;
111:     let count = stations[0].profile.len();
112:     require(
113:         (2..=MAX_SECTION_LANDMARKS).contains(&count),
114:         RecipeError::Budget,
115:     )?;
116:     for station in stations {
117:         require(station.profile.len() == count, RecipeError::Profile)?;
118:         require(
119:             station.profile[0].across.get() == -1.0
120:                 && station.profile[count - 1].across.get() == 1.0,
121:             RecipeError::Profile,
122:         )?;
123:         for pair in station.profile.windows(2) {
124:             require(
125:                 (pair[1].across.get() - pair[0].across.get()) * p.width.get()
126:                     >= MIN_MANUFACTURED_METRES,
127:                 RecipeError::Profile,
128:             )?;
129:         }
130:         for point in &station.profile {
131:             nonnegative(point.thickness.get())?;
132:         }
133:     }
134:     Ok(())
135: }

1: //! Dimension and sampling bounds for archery constructions.
2: use super::*;
3: pub(super) fn archery_bow(p: &ArcheryBowParameters) -> Checked {
4:     positive(p.length.get())?;
5:     positive(p.grip_length.get())?;
6:     positive(p.limb_width.get())?;
7:     positive(p.limb_depth.get())?;
8:     bounded(p.grip_width.get())?;
9:     bounded(p.grip_depth.get())?;
10:     {
11:         let n = &p.tip_scale;
12:         require(n.get().abs() <= 128.0, RecipeError::Dimension)?;
13:     }
14:     bounded(p.reflex.get())?;
15:     bounded(p.recurve.get())?;
16:     {
17:         let n = &p.upper_ratio;
18:         require(n.get().abs() <= 128.0, RecipeError::Dimension)?;
19:     }
20:     bounded(p.brace_height.get())?;
21:     positive(p.string_radius.get())?;
22:     bounded(p.loop_radius.get())?;
23:     bounded(p.loop_gap.get())?;
24:     if let Some(n) = &p.backing_thickness {
25:         bounded(n.get())?;
26:     }
27:     if let Some(n) = &p.horn_thickness {
28:         bounded(n.get())?;
29:     }
30:     if let Some(n) = &p.samples {
31:         require(n.0 <= MAX_SAMPLING_REQUEST, RecipeError::Budget)?;
32:     }
33:     if let Some(n) = &p.radial_segments {
34:         require(n.0 <= MAX_SAMPLING_REQUEST, RecipeError::Budget)?;
35:     }
36: 
37:     Ok(())
38: }
39: pub(super) fn arrow(p: &ArrowParameters) -> Checked {
40:     positive(p.length.get())?;
41:     positive(p.shaft_radius.get())?;
42:     positive(p.head_length.get())?;
43:     positive(p.head_width.get())?;
44:     positive(p.head_thickness.get())?;
45:     positive(p.fletching_length.get())?;
46:     bounded(p.fletching_height.get())?;
47:     require(
48:         p.fletching_count.0 <= MAX_SAMPLING_REQUEST,
49:         RecipeError::Budget,
