1: //! Bounds for interpolated visible grip dimensions and their material inset.
2: use super::*;
3: 
4: pub(super) fn check(p: &ProfileBodyParameters) -> Checked {
5:     positive(p.length.get())?;
6:     if let Some(count) = p.radial_segments {
7:         require(
8:             (MIN_PROFILE_RADIAL_SEGMENTS..=MAX_SAMPLING_REQUEST).contains(&count.0),
9:             RecipeError::Budget,
10:         )?;
11:     }
12:     require(
13:         (2..=MAX_BODY_PROFILE_STATIONS).contains(&p.profile.len()),
14:         RecipeError::Budget,
15:     )?;
16:     require(
17:         p.profile[0].at.get() == 0.0 && p.profile.last().unwrap().at.get() == 1.0,
18:         RecipeError::Profile,
19:     )?;
20:     require(
21:         p.profile.windows(2).all(|s| s[1].at.get() > s[0].at.get()),
22:         RecipeError::Profile,
23:     )?;
24:     for s in &p.profile {
25:         positive(s.width.get())?;
26:         positive(s.depth.get())?;
27:     }
28:     let rib_depth = p.ribs.as_ref().map_or(0.0, |r| r.depth.get());
29:     if let Some(ribs) = &p.ribs {
30:         require(
31:             (1..=MAX_PROFILE_RIBS).contains(&ribs.count.0),
32:             RecipeError::Budget,
33:         )?;
34:         positive(rib_depth)?;
35:         clearance(rib_depth <= p.length.get() / ribs.count.0 as f64 / 4.0)?;
36:         for station in &p.profile {
37:             clearance(2.0 * rib_depth < station.width.get().min(station.depth.get()))?;
38:         }
39:     }
40:     if let Some(cover) = &p.cover {
41:         positive(cover.thickness.get())?;
42:         if let Some(cap) = cover.end_cap {
43:             positive(cap.get())?;
44:             clearance(cap.get() < p.length.get())?;
45:         }
46:         // Monotone interpolation has no interior extrema beyond its endpoints.
47:         // This conservative interval bound also keeps the ellipse inset below
48:         // its smallest radius of curvature throughout every profile interval.
49:         for pair in p.profile.windows(2) {
50:             let small = pair
51:                 .iter()
52:                 .flat_map(|s| [s.width.get(), s.depth.get()])
53:                 .fold(f64::INFINITY, f64::min)
54:                 / 2.0
55:                 - rib_depth;
56:             let large = pair
57:                 .iter()
58:                 .flat_map(|s| [s.width.get(), s.depth.get()])
59:                 .fold(0.0, f64::max)
60:                 / 2.0;
61:             clearance(cover.thickness.get() < small * small / large)?;
62:         }
63:     }
64:     Ok(())
65: }
66: 
67: pub(super) fn grip(p: &ProfileBodyParameters) -> Checked {
68:     check(p)?;
69:     require(
70:         p.profile.iter().all(|s| {
71:             s.width.get() <= MAX_SWORD_GRIP_WIDTH && s.depth.get() <= MAX_SWORD_GRIP_THICKNESS
72:         }),
73:         RecipeError::Grip,
74:     )
75: }

1: //! Bounded, internally consistent paths and authored guard meshes.
2: use super::*;
3: pub(super) fn check(shape: &Shape) -> Checked {
4:     match shape {
5:         Shape::Tube(p) => tube(p)?,
6:         Shape::GuardAssembly(p) => guard(p)?,
7:         Shape::Pommel(p) => {
8:             if let Some(ornaments) = &p.ornaments {
9:                 for ornament in ornaments {
10:                     positive(ornament.scale.get())?;
11:                     require(
12:                         p.sockets
13:                             .as_ref()
14:                             .is_some_and(|s| s.contains_key(&ornament.socket)),
15:                         RecipeError::Attachment,
16:                     )?;
17:                     if let OrnamentGeometry::Authored {
18:                         positions, indices, ..
19:                     } = &ornament.geometry
20:                     {
21:                         require(
22:                             !positions.is_empty()
23:                                 && positions.len() % 3 == 0
24:                                 && indices.len() % 3 == 0
25:                                 && indices.len() <= MAX_AUTHORED_STATIONS * 3
26:                                 && indices.iter().all(|&i| (i as usize) < positions.len() / 3),
27:                             RecipeError::Profile,
28:                         )?;
29:                         for p in positions {
30:                             bounded(p.get())?;
31:                         }
32:                     }
33:                 }
34:             }
35:         }
36:         _ => {}
37:     }
38:     Ok(())
39: }
40: 
41: fn tube(p: &TubeParameters) -> Checked {
42:     require(
43:         (2..=MAX_AUTHORED_STATIONS).contains(&p.points.len()),
44:         RecipeError::Budget,
45:     )?;
46:     for point in &p.points {
47:         for value in point {
48:             bounded(value.get())?;
49:         }
50:     }
51:     proportion(p.points.windows(2).all(|p| p[0] != p[1]))?;
52:     let points = p
53:         .points
54:         .iter()
55:         .map(|p| [p[0].get(), p[1].get(), 0.0])
56:         .collect::<Vec<_>>();
57:     crate::construction::validate_simple_path(&points)
