1: //! Positive-length fittings and explicit annular profile steps.
2: use super::*;
3: const MAX_TERMINAL_PROFILE_STATIONS: usize = 32;
4: pub(super) fn check(p: &GuardParameters) -> Checked {
5:     let selected = p.terminal == Some(GuardTerminal::Profile)
6:         || p.left_terminal == Some(GuardLeftTerminal::Profile)
7:         || p.right_terminal == Some(GuardRightTerminal::Profile);
8:     proportion(selected == p.terminal_profile.is_some())?;
9:     let Some(profile) = &p.terminal_profile else {
10:         return Ok(());
11:     };
12:     let stations = &profile.stations;
13:     require(
14:         (2..=MAX_TERMINAL_PROFILE_STATIONS).contains(&stations.len()),
15:         RecipeError::Budget,
16:     )?;
17:     require(
18:         stations[0][0].get() == 0.0 && stations.last().unwrap()[0].get() > 0.0,
19:         RecipeError::Profile,
20:     )?;
21:     for (i, station) in stations.iter().enumerate() {
22:         nonnegative(station[0].get())?;
23:         if i == stations.len() - 1 {
24:             nonnegative(station[1].get())?;
25:         } else {
26:             positive(station[1].get())?;
27:         }
28:     }
29:     for pair in stations.windows(2) {
30:         require(
31:             pair[1][0].get() >= pair[0][0].get() && pair[0] != pair[1],
32:             RecipeError::Profile,
33:         )?;
34:     }
35:     for triple in stations.windows(3) {
36:         require(
37:             triple[2][0].get() > triple[0][0].get(),
38:             RecipeError::Profile,
39:         )?;
40:     }
41:     Ok(())
42: }

