852: fn point_order(left: &[Point], right: &[Point]) -> std::cmp::Ordering {
853:     left.first()
854:         .and_then(|p| {
855:             right.first().map(|q| {
856:                 p.0[0]
857:                     .total_cmp(&q.0[0])
858:                     .then_with(|| p.0[1].total_cmp(&q.0[1]))
859:             })
860:         })
861:         .unwrap_or_else(|| left.len().cmp(&right.len()))
862: }
