709: fn clip_polyline(points: &[Point], bounds: [f64; 4]) -> Vec<Vec<Point>> {
710:     let mut output = Vec::new();
711:     let mut current = Vec::new();
712:     for pair in points.windows(2) {
713:         if let Some((start, end)) = clip_segment(&pair[0], &pair[1], bounds) {
714:             if current.last() != Some(&start) {
715:                 if current.len() >= 2 {
716:                     output.push(std::mem::take(&mut current));
717:                 }
718:                 current.push(start);
719:             }
720:             current.push(end);
721:         } else if current.len() >= 2 {
722:             output.push(std::mem::take(&mut current));
723:         }
724:     }
725:     if current.len() >= 2 {
726:         output.push(current);
727:     }
728:     output
729: }
