731: fn clip_segment(
732:     start: &Point,
733:     end: &Point,
734:     [west, south, east, north]: [f64; 4],
735: ) -> Option<(Point, Point)> {
736:     let [x0, y0] = start.0;
737:     let [x1, y1] = end.0;
738:     if ![x0, y0, x1, y1].into_iter().all(f64::is_finite) {
739:         return None;
740:     }
741:     let dx = x1 - x0;
742:     let dy = y1 - y0;
743:     let mut low: f64 = 0.0;
744:     let mut high: f64 = 1.0;
745:     for (p, q) in [
746:         (-dx, x0 - west),
747:         (dx, east - x0),
748:         (-dy, y0 - south),
749:         (dy, north - y0),
750:     ] {
751:         if p == 0.0 {
752:             if q < 0.0 {
753:                 return None;
754:             }
755:         } else {
756:             let t = q / p;
757:             if p < 0.0 {
758:                 low = low.max(t);
759:             } else {
760:                 high = high.min(t);
761:             }
762:         }
763:         if low > high {
764:             return None;
765:         }
766:     }
767:     Some((
768:         Point([x0 + low * dx, y0 + low * dy]),
769:         Point([x0 + high * dx, y0 + high * dy]),
770:     ))
771: }
