657: fn coordinates(wkt: &str) -> Vec<Point> {
658:     wkt.split(['(', ')', ','])
659:         .filter_map(|part| {
660:             let mut values = part
661:                 .split_whitespace()
662:                 .filter_map(|v| v.parse::<f64>().ok());
