208: fn graph(edges: &[TravelEdgeImport]) -> HashMap<u64, Vec<(u64, u64)>> {
209:     let mut g = HashMap::new();
210:     for e in edges {
211:         g.entry(e.from_node_id)
212:             .or_insert_with(Vec::new)
213:             .push((e.to_node_id, u64::from(e.length_m)));
214:         g.entry(e.to_node_id)
215:             .or_insert_with(Vec::new)
216:             .push((e.from_node_id, u64::from(e.length_m)));
217:     }
218:     g
219: }
220: fn shortest_within(g: &HashMap<u64, Vec<(u64, u64)>>, start: u64, goal: u64, limit: u64) -> bool {
221:     let mut q = BinaryHeap::new();
222:     let mut best = HashMap::new();
223:     q.push((Reverse(0_u64), start));
224:     while let Some((Reverse(d), n)) = q.pop() {
225:         if d > limit {
226:             continue;
227:         }
228:         if n == goal {
229:             return true;
230:         }
231:         if best.get(&n).is_some_and(|v| *v <= d) {
232:             continue;
233:         }
234:         best.insert(n, d);
235:         for &(m, w) in g.get(&n).into_iter().flatten() {
236:             if let Some(nd) = d.checked_add(w).filter(|v| *v <= limit) {
237:                 q.push((Reverse(nd), m));
238:             }
239:         }
240:     }
241:     false
242: }
243: fn connected_settlement_count(world: &CompiledWorld) -> usize {
