248:         .collect::<HashSet<_>>();
249:     world
250:         .settlements
251:         .iter()
252:         .filter(|s| incident.contains(&s.source_node_id))
253:         .count()
254: }
255: fn stable_id(from: u64, to: u64, existing: &HashSet<u64>, accepted: &[TravelEdgeImport]) -> u64 {
256:     for salt in 0_u32.. {
257:         let mut h = Sha256::new();
258:         h.update(b"adventuresim-inferred-road-v9");
259:         h.update(from.to_le_bytes());
260:         h.update(to.to_le_bytes());
261:         h.update(salt.to_le_bytes());
262:         let raw = u64::from_le_bytes(h.finalize()[..8].try_into().unwrap()) | (1_u64 << 63);
263:         if !existing.contains(&raw) && accepted.iter().all(|e| e.id != raw) {
264:             return raw;
265:         }
266:     }
267:     unreachable!()
268: }
269: fn haversine_m(a: (f64, f64), b: (f64, f64)) -> u32 {
270:     let dlat = (b.0 - a.0).to_radians();
271:     let dlon = (b.1 - a.1).to_radians();
272:     let h = (dlat / 2.0).sin().powi(2)
273:         + a.0.to_radians().cos() * b.0.to_radians().cos() * (dlon / 2.0).sin().powi(2);
274:     (6_371_000.0 * 2.0 * h.sqrt().asin()).round() as u32
275: }
