142: /// Single canonical economy projection used by import and database
143: /// finalization. `documented_town` is direct Viabundus evidence; route count is
144: /// taken from the finalized graph.
145: pub fn infer_settlement_economy(
146:     population_level: i32,
147:     population: u32,
148:     routes: u16,
149:     documented_town: bool,
150:     industries: &InferredIndustryProfile,
151: ) -> Result<SettlementEconomyProfile, String> {
152:     let industrial = industries
153:         .outputs()
154:         .iter()
155:         .map(|e| match e {
156:             IndustryEvidence::Derived(v) => match v.scale() {
157:                 ProductionScale::Marginal => 12,
158:                 ProductionScale::Local => 28,
159:                 ProductionScale::Regional => 48,
160:             },
161:             IndustryEvidence::Fallback(_) => 5,
162:         })
163:         .sum::<u16>()
164:         .min(260);
165:     let population_points = ((population.max(1) as f64).log10() * 95.0) as u16;
166:     let score = (u16::try_from(population_level.max(1)).unwrap_or(1) * 85)
167:         .saturating_add(population_points)
168:         .saturating_add(industrial)
169:         .saturating_add(routes.min(8) * 18)
170:         .saturating_add(u16::from(documented_town) * 55)
171:         .min(1_000);
172:     let tier = match score {
173:         0..=249 => ProsperityTier::Subsistence,
174:         250..=419 => ProsperityTier::Modest,
175:         420..=599 => ProsperityTier::Comfortable,
176:         600..=779 => ProsperityTier::Prosperous,
177:         _ => ProsperityTier::Wealthy,
178:     };
179:     let services = infer_services(population_level, population, score, industries);
180:     let stock = infer_stock(population_level, score, industries, &services);
181:     let mut specializations = stock
182:         .values()
183:         .filter(|value| value.abundance >= 4)
184:         .map(|value| (value.category, value.abundance))
185:         .collect::<Vec<_>>();
186:     specializations.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
187:     specializations.truncate(SettlementEconomyProfile::MAX_SPECIALIZATIONS);
188:     specializations.sort_by_key(|(category, _)| *category);
189:     let profile = SettlementEconomyProfile {
190:         rules_version: CURRENT_INFERENCE_RULES_VERSION,
191:         prosperity_score: score,
192:         prosperity_tier: tier,
193:         services: services.into_iter().collect(),
194:         specializations: specializations
195:             .into_iter()
196:             .map(|(category, _)| category)
197:             .collect(),
198:         stock: stock.into_values().collect(),
199:     };
200:     profile.validate()?;

201:     Ok(profile)
202: }
203: 
204: fn forest_or_peat(e: &IndustryEvidence) -> bool {
205:     matches!(
206:         e,
207:         IndustryEvidence::Derived(DerivedIndustry::Forestry(_) | DerivedIndustry::PeatCutting(_))
208:     )
209: }
210: 
211: fn infer_services(
212:     population_level: i32,
213:     population: u32,
214:     score: u16,
215:     industries: &InferredIndustryProfile,
216: ) -> std::collections::BTreeSet<SettlementService> {
217:     use std::collections::BTreeSet;
218:     let mut services = BTreeSet::from([SettlementService::Inn]);
219:     if population_level <= 1 && population < 250 {
220:         services.insert(SettlementService::GeneralStore);
221:     } else {
222:         services.extend([
223:             SettlementService::GeneralStore,
224:             SettlementService::Market,
225:             SettlementService::Temple,
226:         ]);
227:         if population_level <= 2 || score < 470 {
228:             services.insert(SettlementService::GeneralBlacksmith);
229:         } else {
230:             services.extend([SettlementService::Weaponsmith, SettlementService::Armorer]);
231:         }
232:         if population_level >= 3 || score >= 500 {
233:             services.insert(SettlementService::Tailor);
234:         }
235:         if population_level >= 3 || industries.outputs().iter().any(forest_or_peat) {
236:             services.insert(SettlementService::Herbalist);
237:         }
238:         if population_level >= 4 {
239:             services.insert(SettlementService::Bookstore);
240:         }
241:     }
242:     services
243: }
244: 
245: fn infer_stock(
246:     population_level: i32,
247:     score: u16,
248:     industries: &InferredIndustryProfile,
249:     services: &std::collections::BTreeSet<SettlementService>,
250: ) -> std::collections::BTreeMap<StockCategory, SettlementStock> {
251:     use std::collections::BTreeMap;
252:     let mut stock = BTreeMap::<StockCategory, SettlementStock>::new();
253:     let mut add = |category, abundance, provenance| {
254:         stock
255:             .entry(category)
256:             .and_modify(|v| v.abundance = v.abundance.max(abundance))
257:             .or_insert(SettlementStock {
258:                 category,
259:                 abundance,
260:                 provenance,
261:             });
262:     };
263:     for evidence in industries.outputs() {
264:         let IndustryEvidence::Derived(industry) = evidence else {
265:             continue;
266:         };
267:         let abundance = match industry.scale() {
268:             ProductionScale::Marginal => 2,
269:             ProductionScale::Local => 4,
270:             ProductionScale::Regional => 5,
271:         };
272:         let category = industry_stock_category(industry);
273:         add(
274:             category,
275:             abundance,
276:             ProfileFactProvenance::DerivedFromCanonicalEvidence,
277:         );
278:     }
279:     let gap = ProfileFactProvenance::DeterministicGapFill;
280:     add(
281:         StockCategory::GeneralGoods,
282:         if population_level <= 1 { 3 } else { 2 },
283:         gap,
284:     );
285:     if population_level <= 1 {
286:         add(StockCategory::Grain, 1, gap);
287:         add(StockCategory::Meat, 1, gap);
288:     }
289:     if industries.outputs().iter().any(|e|matches!(e,IndustryEvidence::Derived(DerivedIndustry::Agriculture(v)) if matches!(v.commodity,AgriculturalCommodity::Dairy|AgriculturalCommodity::Hides))){add(StockCategory::Meat,3,ProfileFactProvenance::DerivedFromCanonicalEvidence);}
290:     if services.contains(&SettlementService::GeneralBlacksmith)
291:         || services.contains(&SettlementService::Weaponsmith)
292:     {
293:         add(
294:             StockCategory::Metalwares,
295:             if score >= 600 { 4 } else { 2 },
296:             gap,
297:         );
298:     }
299:     if services.contains(&SettlementService::GeneralBlacksmith) {
300:         add(StockCategory::Weapons, 1, gap);

301:         add(StockCategory::Armor, 1, gap);
302:     }
303:     if services.contains(&SettlementService::Weaponsmith) {
304:         add(
305:             StockCategory::Weapons,
306:             if score >= 700 { 4 } else { 2 },
307:             gap,
308:         );
309:     }
310:     if services.contains(&SettlementService::Armorer) {
311:         add(StockCategory::Armor, if score >= 700 { 4 } else { 2 }, gap);
312:     }
313:     if services.contains(&SettlementService::Herbalist) {
314:         add(
315:             StockCategory::Herbs,
316:             2 + u8::from(industries.outputs().iter().any(forest_or_peat)),
317:             gap,
318:         );
319:     }
320:     if services.contains(&SettlementService::Bookstore) {
321:         add(
322:             StockCategory::Books,
323:             if population_level >= 5 { 4 } else { 2 },
324:             gap,
325:         );
326:     }
327:     stock
328: }
329: 
330: fn industry_stock_category(industry: &DerivedIndustry) -> StockCategory {
331:     match industry {
332:         DerivedIndustry::Agriculture(v) => match v.commodity {
333:             AgriculturalCommodity::Grain => StockCategory::Grain,
334:             AgriculturalCommodity::Flax | AgriculturalCommodity::Wool => StockCategory::Cloth,
335:             AgriculturalCommodity::Dairy => StockCategory::Dairy,
336:             AgriculturalCommodity::Hides => StockCategory::Hides,
337:         },
338:         DerivedIndustry::Fishing(_) => StockCategory::Fish,
339:         DerivedIndustry::Quarrying(_) => StockCategory::Stone,
340:         DerivedIndustry::Mining(_) => StockCategory::Fuel,
341:         DerivedIndustry::Pottery(_) => StockCategory::Pottery,
342:         DerivedIndustry::PeatCutting(_) | DerivedIndustry::CharcoalBurning(_) => {
343:             StockCategory::Fuel
344:         }
345:         DerivedIndustry::Forestry(v) => match v.commodity {
346:             ForestCommodity::Fuelwood => StockCategory::Fuel,
347:             _ => StockCategory::Timber,
348:         },
349:         DerivedIndustry::Saltmaking(_) => StockCategory::Salt,
350:         DerivedIndustry::Construction(v) => match v.commodity {
351:             ConstructionCommodity::Timber => StockCategory::Timber,
352:             ConstructionCommodity::Brick | ConstructionCommodity::RoofTile => {
353:                 StockCategory::Pottery
354:             }
355:             _ => StockCategory::Stone,
356:         },
357:     }
358: }

