245: /// O(L*n) best-counterpart choices from one immutable party snapshot.
246: pub fn party_common_oral_choices(
247:     speakers: &[(u64, OralLanguageHours)],
248: ) -> Vec<(u64, OralLanguage, f32)> {
249:     let capped: Vec<_> = speakers
250:         .iter()
251:         .map(|(id, hours)| (*id, *hours, ORAL_FLUENCY_HOURS))
252:         .collect();
253:     party_common_oral_choices_capped(&capped)
254: }
255: 
256: pub fn party_common_oral_choices_capped(
257:     speakers: &[(u64, OralLanguageHours, f32)],
258: ) -> Vec<(u64, OralLanguage, f32)> {
259:     let mut top = [[(0_u64, -1.0_f32); 2]; 8];
260:     for (id, hours, cap) in speakers {
261:         for language in OralLanguage::ALL {
262:             let candidate = (*id, hours.effective(language).min((*cap).max(0.0)));
263:             let values = &mut top[language.index()];
264:             if candidate.1 > values[0].1
265:                 || (candidate.1 == values[0].1 && candidate.0 < values[0].0)
266:             {
267:                 values[1] = values[0];
268:                 values[0] = candidate;
269:             } else if candidate.1 > values[1].1
270:                 || (candidate.1 == values[1].1 && candidate.0 < values[1].0)
271:             {
272:                 values[1] = candidate;
273:             }
274:         }
275:     }
276:     speakers
277:         .iter()
278:         .map(|(id, own, cap)| {
279:             OralLanguage::ALL
280:                 .into_iter()
281:                 .map(|language| {
282:                     let values = top[language.index()];
283:                     let other = if values[0].0 != *id {
284:                         values[0].1
285:                     } else {
286:                         values[1].1
287:                     };
288:                     let coefficient = if other < 0.0 {
289:                         0.0
290:                     } else {
291:                         (own.effective(language).min((*cap).max(0.0)).min(other)
292:                             / ORAL_FLUENCY_HOURS)
293:                             .clamp(0.0, 1.0)
294:                     };
295:                     (language, coefficient)
296:                 })
297:                 .max_by(|a, b| {
298:                     a.1.total_cmp(&b.1)
299:                         .then_with(|| b.0.index().cmp(&a.0.index()))
300:                 })
301:                 .map(|(language, coefficient)| (*id, language, coefficient))
302:                 .unwrap()
303:         })
304:         .collect()
305: }
