542:         twenty_year_mean: PalmerDroughtSeverityIndex,
543:         drought_summers: u8,
544:         wet_summers: u8,
545:     ) -> Option<Self> {
546:         if drought_summers > Self::WINDOW_YEARS
547:             || wet_summers > Self::WINDOW_YEARS
548:             || drought_summers + wet_summers > Self::WINDOW_YEARS
549:         {
550:             return None;
551:         }
552:         let mut drought_remaining = i32::from(drought_summers);
553:         let mut wet_remaining = i32::from(wet_summers);
554:         let mut normal_remaining = i32::from(Self::WINDOW_YEARS - drought_summers - wet_summers);
555:         let current = i32::from(current_summer.milli_units());
556:         if current <= -2_000 {
557:             if drought_remaining == 0 {
558:                 return None;
559:             }
560:             drought_remaining -= 1;
561:         } else if current >= 2_000 {
562:             if wet_remaining == 0 {
563:                 return None;
564:             }
565:             wet_remaining -= 1;
566:         } else {
567:             if normal_remaining == 0 {
568:                 return None;
569:             }
570:             normal_remaining -= 1;
571:         }
572:         let minimum_sum = current + drought_remaining * i32::from(PalmerDroughtSeverityIndex::MIN)
573:             - normal_remaining * 1_999
574:             + wet_remaining * 2_000;
575:         let maximum_sum = current - drought_remaining * 2_000
576:             + normal_remaining * 1_999
577:             + wet_remaining * i32::from(PalmerDroughtSeverityIndex::MAX);
578:         let minimum_mean = (f64::from(minimum_sum) / f64::from(Self::WINDOW_YEARS)).round() as i16;
579:         let maximum_mean = (f64::from(maximum_sum) / f64::from(Self::WINDOW_YEARS)).round() as i16;
580:         if !(minimum_mean..=maximum_mean).contains(&twenty_year_mean.milli_units()) {

581:             return None;
582:         }
583:         Some(Self {
584:             current_summer,
585:             twenty_year_mean,
