1445: /// Cross-field invariants shared by offline validation and the strategic import
1446: /// boundary. Evidence-specific enums make invalid category pairings
1447: /// unrepresentable; this predicate validates the surrounding source context.
1448: pub fn historical_vegetation_matches_context(
1449:     historical: HistoricalVegetation,
1450:     land_use: LandUseProfile,
1451:     potential: &PotentialVegetation,
1452:     soil: SoilProfile,
1453:     hydrology: SettlementHydrology,
1454: ) -> bool {
1455:     match historical {
1456:         HistoricalVegetation::Direct(value) => {
1457:             let crop = land_use.cropland().basis_points();
1458:             let grazing = land_use.grazing().basis_points();
1459:             let built = land_use.built_up().basis_points();
1460:             // Stable tie order is built, cropland, pasture.
1461:             if built >= crop && built >= grazing {
1462:                 matches!(value.cover, DirectHistoricalVegetationCover::BuiltSettlement(v) if v.built_fraction == land_use.built_up() && built >= 1_000)
1463:             } else if crop >= grazing {
1464:                 matches!(value.cover, DirectHistoricalVegetationCover::Cropland(v) if v.cultivated_fraction == land_use.cropland() && crop >= 3_500)
1465:             } else {
1466:                 matches!(value.cover, DirectHistoricalVegetationCover::Pasture(v) if v.grazing_fraction == land_use.grazing() && grazing >= 3_500)
1467:             }
1468:         }
1469:         HistoricalVegetation::Derived(value) => match value.cover {
1470:             DerivedHistoricalVegetationCover::Wetland(wetland) => {
1471:                 wetland_context_is_convergent(potential, soil, hydrology)
1472:                     && wetland.water_regime == soil.properties.water_regime
1473:             }
1474:             DerivedHistoricalVegetationCover::TransitionalWater => {
1475:                 matches!(hydrology.marine, Some(MarineWaterAccess::Tidal(_)))
1476:             }
1477:             _ => true,
1478:         },
1479:         HistoricalVegetation::Fallback(_) => true,
1480:     }

