2247: pub struct IndustryInferenceContext<'a> {
2248:     pub elevation: ElevationMeters,
2249:     pub drought: DroughtProfile,
2250:     pub land_use: LandUseProfile,
2251:     pub historical_vegetation: HistoricalVegetation,
