2259: /// Single canonical rules-v6 implementation. Compilation and both import
2260: /// boundaries compare the complete result, including order and scales.
2261: pub fn infer_industries(
2262:     c: IndustryInferenceContext<'_>,
2263: ) -> Result<InferredIndustryProfile, String> {
2264:     let mut out = Vec::new();
2265:     let add = |out: &mut Vec<_>, value| out.push(IndustryEvidence::Derived(value));
2266:     let crop = c.land_use.cropland().basis_points();
2267:     let grazing = c.land_use.grazing().basis_points();
2268:     let built = c.land_use.built_up().basis_points();
2269:     let wet = matches!(
2270:         c.soil.properties.water_regime,
2271:         SoilWaterRegime::LongSeasonWet | SoilWaterRegime::PermanentlyWet
2272:     );
2273:     let mean = match c.drought {
2274:         DroughtProfile::Reconstructed(v) | DroughtProfile::Inferred(v) => {
2275:             v.twenty_year_mean().milli_units()
2276:         }
2277:     };
2278:     let dry = mean <= -2_000 || c.soil.properties.water_regime == SoilWaterRegime::UsuallyDry;
2279:     let fertile = !matches!(
2280:         c.soil.fertility,
2281:         SoilFertility::VeryLow | SoilFertility::Low
2282:     );
2283:     if crop >= 1_500
2284:         && fertile
2285:         && !dry
2286:         && c.soil.properties.agricultural_limitation != AgriculturalLimitation::Flooded
2287:     {
2288:         add(
2289:             &mut out,
2290:             DerivedIndustry::Agriculture(AgricultureIndustry {
2291:                 commodity: AgriculturalCommodity::Grain,
2292:                 scale: canonical_industry_scale(
2293:                     crop.saturating_add(industry_pop_score(c.population_estimate)),
2294:                     c.max_scale,
2295:                 ),
2296:             }),
2297:         );
2298:         if crop >= 3_000
2299:             && matches!(
2300:                 c.soil.fertility,
2301:                 SoilFertility::High | SoilFertility::VeryHigh
2302:             )
2303:             && !wet
2304:             && c.elevation.get() <= 300
2305:         {
2306:             add(
2307:                 &mut out,
2308:                 DerivedIndustry::Agriculture(AgricultureIndustry {
2309:                     commodity: AgriculturalCommodity::Flax,
2310:                     scale: canonical_industry_scale(

2311:                         crop.saturating_add(industry_pop_score(c.population_estimate))
2312:                             .saturating_sub(500),
2313:                         c.max_scale,
2314:                     ),
2315:                 }),
2316:             );
2317:         }
2318:     }
2319:     if grazing >= 1_500 {
2320:         let scale = canonical_industry_scale(
2321:             grazing.saturating_add(industry_pop_score(c.population_estimate)),
2322:             c.max_scale,
2323:         );
2324:         for commodity in [
2325:             AgriculturalCommodity::Wool,
2326:             AgriculturalCommodity::Dairy,
2327:             AgriculturalCommodity::Hides,
2328:         ] {
2329:             add(
2330:                 &mut out,
2331:                 DerivedIndustry::Agriculture(AgricultureIndustry { commodity, scale }),
2332:             );
2333:         }
2334:     }
2335:     let mut freshwater = false;
2336:     if let Some(flowing) = c.hydrology.flowing {
2337:         let river = match flowing {
2338:             FlowingWaterAccess::River(v) => v,
2339:             FlowingWaterAccess::RiverAndCanal(v) => v.river,
2340:         };
2341:         if river.distance.get() <= 5_000 {
2342:             add(
2343:                 &mut out,
2344:                 DerivedIndustry::Fishing(FishingIndustry {
