2385:         Some(MarineWaterAccess::OpenCoast(d)) if d.get() <= 10_000 => add(
2386:             &mut out,
2387:             DerivedIndustry::Fishing(FishingIndustry {
2388:                 commodity: FishCommodity::Marine,
2389:                 scale: canonical_industry_scale(
