27: fn validate_inferred_geometry(
28:     edge: &adventuresim_world_schema::TravelEdgeImport,
29:     node_coordinates: &HashMap<u64, (f64, f64)>,
30: ) -> Result<()> {
31:     if edge.geometry.len() < 2 || edge.geometry.len() > MAX_EDGE_GEOMETRY_POINTS {
32:         return Err(Error::Validation(format!(
33:             "inferred edge {} has invalid geometry size",
34:             edge.id
35:         )));
36:     }
37:     let [west, south, east, north] = PLAYABLE_BOUNDS;
38:     if edge.geometry.iter().any(|point| {
39:         let (lat, lon) = (point.latitude(), point.longitude());
40:         lon < west || lon > east || lat < south || lat > north
41:     }) || edge.geometry.windows(2).any(|pair| pair[0] == pair[1])
42:     {
43:         return Err(Error::Validation(format!(
44:             "inferred edge {} has out-of-bounds or duplicate geometry points",
45:             edge.id
46:         )));
47:     }
48:     let endpoint_matches =
49:         |point: adventuresim_world_schema::TravelGeometryPoint, node_id: u64| -> bool {
50:             let Some(&(lat, lon)) = node_coordinates.get(&node_id) else {
51:                 return false;
52:             };
53:             let Ok(expected) = adventuresim_world_schema::TravelGeometryPoint::new(lon, lat) else {
54:                 return false;
55:             };
56:             point.longitude_e7.abs_diff(expected.longitude_e7) <= 1
57:                 && point.latitude_e7.abs_diff(expected.latitude_e7) <= 1
58:         };
59:     if !endpoint_matches(edge.geometry[0], edge.from_node_id)
60:         || !endpoint_matches(*edge.geometry.last().unwrap(), edge.to_node_id)
61:     {
62:         return Err(Error::Validation(format!(
63:             "inferred edge {} geometry endpoints do not match its nodes",
64:             edge.id
65:         )));
66:     }
67:     let length = edge
68:         .geometry
69:         .windows(2)
70:         .map(|pair| geodesic_segment_m(pair[0], pair[1]) as u64)
71:         .sum::<u64>();
72:     if length.abs_diff(u64::from(edge.length_m)) > 2 {
73:         return Err(Error::Validation(format!(
74:             "inferred edge {} geometry length does not reconcile",
75:             edge.id
76:         )));
77:     }
78:     Ok(())
79: }
