14: pub(crate) fn validate(features: &[TerrainFeature], report: &WorldBuildReport) -> Result<()> {
15:     let [west, south, east, north] = PLAYABLE_BOUNDS;
16:     let point_count = features
17:         .iter()
18:         .map(|feature| feature.geometry().len())
19:         .sum::<usize>();
20:     let invalid_geometry = features.iter().any(|feature| {
21:         if let TerrainFeature::MappedGeology(window) = feature {
22:             return !window.is_valid();
23:         }
24:         feature.id().is_empty()
25:             || feature.id().len() > 256
26:             || feature.geometry().len() < 2
27:             || feature.geometry().len() > MAX_FAULT_LINE_POINTS
28:             || feature.geometry().windows(2).any(|pair| pair[0] == pair[1])
29:             || feature.geometry().iter().any(|point| {
30:                 point.longitude() < west
31:                     || point.longitude() > east
32:                     || point.latitude() < south
33:                     || point.latitude() > north
34:             })
35:     });
36:     if features
37:         .iter()
38:         .filter(|f| matches!(f, TerrainFeature::MappedGeology(_)))
39:         .count()
40:         > adventuresim_world_schema::MAX_GEOLOGIC_WINDOWS
41:         || features
42:             .iter()
43:             .filter(|f| matches!(f, TerrainFeature::MappedFault(_)))
44:             .count()
45:             != report.fault_traces_imported
46:         || point_count != report.fault_geometry_points
47:         || point_count > MAX_FAULT_GEOMETRY_POINTS
48:         || features.windows(2).any(|pair| pair[0].id() >= pair[1].id())
49:         || invalid_geometry
50:     {
51:         return Err(Error::Validation(
52:             "fault geometry is unbounded, non-canonical, or inconsistent with the build report"
53:                 .into(),
54:         ));
55:     }
56:     Ok(())
57: }

