78: pub(crate) fn validate_semantics(world: &CompiledWorld) -> Result<()> {
79:     let contexts = route_contexts(world);
80:     for s in &world.settlements {
81:         let context = contexts
82:             .get(&s.source_node_id)
83:             .copied()
84:             .unwrap_or_else(SettlementRouteContext::isolated);
85:         let max_scale = match context.accessibility {
86:             RouteAccessibility::Connected => Scale::Regional,
87:             RouteAccessibility::Difficult => Scale::Local,
88:             RouteAccessibility::Isolated => Scale::Marginal,
89:         };
90:         if !adventuresim_world_schema::industry_profile_is_canonical(
91:             &s.industries,
92:             inference_context(s, max_scale),
93:         ) {
94:             return Err(Error::Validation(format!(
