103: fn route_contexts(world: &CompiledWorld) -> HashMap<u64, SettlementRouteContext> {
104:     let mut grouped: HashMap<u64, Vec<&adventuresim_world_schema::TravelEdgeImport>> =
105:         HashMap::new();
106:     for edge in &world.edges {
107:         grouped.entry(edge.from_node_id).or_default().push(edge);
108:         grouped.entry(edge.to_node_id).or_default().push(edge);
109:     }
110:     grouped
111:         .into_iter()
112:         .map(|(node, edges)| {
113:             let route_count = u16::try_from(edges.len()).unwrap_or(u16::MAX);
114:             let best = edges
115:                 .iter()
116:                 .map(|e| e.terrain.class)
117:                 .min()
118:                 .unwrap_or(RouteTerrainClass::Mountainous);
119:             let worst = edges
120:                 .iter()
121:                 .map(|e| e.terrain.class)
122:                 .max()
123:                 .unwrap_or(RouteTerrainClass::Mountainous);
124:             let max_slope = edges
125:                 .iter()
126:                 .map(|e| e.terrain.max_slope.get())
127:                 .max()
128:                 .unwrap_or(0);
129:             let roughness = edges
130:                 .iter()
131:                 .map(|e| e.terrain.roughness.get())
132:                 .max()
133:                 .unwrap_or(0);
134:             let relief = edges
135:                 .iter()
136:                 .map(|e| e.terrain.relief.get())
137:                 .max()
138:                 .unwrap_or(0);
139:             let accessibility =
140:                 if route_count >= 2 && best <= RouteTerrainClass::Rolling && max_slope <= 250 {
141:                     RouteAccessibility::Connected
142:                 } else if route_count > 0 {
143:                     RouteAccessibility::Difficult
144:                 } else {
145:                     RouteAccessibility::Isolated
146:                 };
147:             (
148:                 node,
149:                 SettlementRouteContext {
150:                     route_count,
151:                     accessibility,
152:                     best_terrain: best,
153:                     worst_terrain: worst,
154:                     max_slope_permille: max_slope,
155:                     max_roughness_m: roughness,
156:                     max_relief_m: relief,
157:                 },
158:             )
159:         })
160:         .collect()
161: }
