310:                 "repertoire {} form {} is incompatible with family, culture, or register",
311:                 repertoire.id, frequency.form_id
312:             ));
313:         }
314:         families_with_forms.insert(frequency.family_id.as_str());
315:         let total = form_totals.entry(frequency.family_id.as_str()).or_default();
316:         *total = total
317:             .checked_add(frequency.frequency)
318:             .ok_or_else(|| format!("form frequencies overflow for {}", frequency.family_id))?;
319:     }
320:     for family_id in eligible_families.iter().copied() {
321:         if !families_with_forms.contains(family_id) {
322:             return Err(format!(
323:                 "repertoire {} family {} has no everyday form",
324:                 repertoire.id, family_id
325:             ));
326:         }
327:     }
328:     Ok(())
329: }
