377: fn validate_observations<'a>(
378:     observations: &'a [NameObservationDefinition],
379:     sources: &BTreeSet<&'a str>,
380: ) -> Result<BTreeSet<&'a str>, String> {
381:     let mut observation_ids = BTreeSet::new();
382:     for record in observations {
383:         validate_id("observation", &record.id)?;
384:         if !observation_ids.insert(record.id.as_str()) {
385:             return Err(format!("duplicate observation ID {}", record.id));
386:         }
387:         if !sources.contains(record.source_id.as_str())
388:             || record.locator.trim().is_empty()
389:             || record.derivation.trim().is_empty()
390:             || record.recorded_spelling.trim().is_empty()
391:         {
392:             return Err(format!(
393:                 "observation {} is incomplete or dangling",
394:                 record.id
395:             ));
396:         }
397:     }
398:     Ok(observation_ids)
399: }
