 90: fn validate_entry(
 91:     derivation: &NameDerivationDefinition,
 92:     repertoire_ids: &BTreeSet<&str>,
 93:     observation_ids: &BTreeSet<&str>,
 94:     families: &FamilyIndex<'_>,
 95:     forms: &FormIndex<'_>,
 96:     surnames: &SurnameIndex<'_>,
 97:     targets: &BTreeMap<TargetKey, u64>,
 98:     derivation_ids: &mut BTreeSet<String>,
 99:     covered_targets: &mut BTreeSet<TargetKey>,
100: ) -> Result<(), String> {

101:     super::validate_id("derivation", &derivation.id)?;
102:     if !derivation_ids.insert(derivation.id.clone()) {
103:         return Err(format!("duplicate derivation ID {}", derivation.id));
104:     }
105:     if derivation.operation.trim().is_empty()
106:         || derivation.rationale.trim().is_empty()
107:         || derivation.observation_ids.is_empty()
108:         || derivation.frequency == 0
109:     {
110:         return Err(format!("derivation {} is incomplete", derivation.id));
111:     }
112:     if !repertoire_ids.contains(derivation.repertoire_id.as_str()) {
113:         return Err(format!(
114:             "derivation {} references unknown repertoire {}",
115:             derivation.id, derivation.repertoire_id
116:         ));
117:     }
118:     validate_target_links(derivation, families, forms, surnames)?;
119:     let target = (
120:         derivation.repertoire_id.clone(),
121:         derivation.family_id.clone(),
122:         derivation.form_id.clone(),
123:         derivation.surname_id.clone(),
124:     );
125:     if targets.get(&target) != Some(&derivation.frequency) {
126:         return Err(format!(
127:             "derivation {} frequency {} disagrees with its repertoire target",
128:             derivation.id, derivation.frequency
129:         ));
130:     }
131:     if !covered_targets.insert(target) {
132:         return Err(format!("duplicate derivation target in {}", derivation.id));
133:     }
134:     validate_observation_links(derivation, observation_ids)
135: }
