137: fn validate_target_links(
138:     derivation: &NameDerivationDefinition,
139:     families: &FamilyIndex<'_>,
140:     forms: &FormIndex<'_>,
141:     surnames: &SurnameIndex<'_>,
142: ) -> Result<(), String> {
143:     let target_count = derivation.family_id.is_some() as u8
144:         + derivation.form_id.is_some() as u8
145:         + derivation.surname_id.is_some() as u8;
146:     let valid_shape = (derivation.family_id.is_some()
147:         && derivation.form_id.is_none()
148:         && derivation.surname_id.is_none())
149:         || (derivation.family_id.is_some()
150:             && derivation.form_id.is_some()
151:             && derivation.surname_id.is_none())
152:         || (derivation.family_id.is_none()
153:             && derivation.form_id.is_none()
154:             && derivation.surname_id.is_some());
155:     if target_count == 0 || !valid_shape {
156:         return Err(format!(
157:             "derivation {} has an invalid target",
158:             derivation.id
159:         ));
160:     }
161:     if let Some(family_id) = &derivation.family_id
162:         && !families.contains_key(family_id.as_str())
163:     {
164:         return Err(format!(
165:             "derivation {} references unknown family {}",
166:             derivation.id, family_id
167:         ));
168:     }
169:     if let Some(form_id) = &derivation.form_id {
170:         let form = forms.get(form_id.as_str()).ok_or_else(|| {
171:             format!(
172:                 "derivation {} references unknown form {}",
173:                 derivation.id, form_id
174:             )
175:         })?;
176:         if !form
177:             .family_ids
178:             .iter()
179:             .any(|family_id| Some(family_id) == derivation.family_id.as_ref())
180:         {
181:             return Err(format!(
182:                 "derivation {} targets a form outside its family",
183:                 derivation.id
184:             ));
185:         }
186:     }
187:     if let Some(surname_id) = &derivation.surname_id
188:         && !surnames.contains_key(surname_id.as_str())
189:     {
190:         return Err(format!(
191:             "derivation {} references unknown surname {}",
192:             derivation.id, surname_id
193:         ));
194:     }
195:     Ok(())
196: }
