198: fn validate_observation_links(
199:     derivation: &NameDerivationDefinition,
200:     observation_ids: &BTreeSet<&str>,

201: ) -> Result<(), String> {
202:     let mut references = BTreeSet::new();
203:     for observation_id in &derivation.observation_ids {
204:         if !references.insert(observation_id.as_str())
205:             || !observation_ids.contains(observation_id.as_str())
206:         {
207:             return Err(format!(
208:                 "derivation {} has a duplicate or dangling observation ID {}",
209:                 derivation.id, observation_id
210:             ));
211:         }
212:     }
213:     Ok(())
214: }

