 9: pub struct PartFrame {
10:     pub origin: [f32; 3],
11:     pub axes: [[f32; 3]; 3],
12:     pub half_extents: [f32; 3],
13: }
14: 
15: impl PartFrame {
16:     pub fn point(&self, local: [f32; 3]) -> [f32; 3] {
17:         std::array::from_fn(|axis| {
18:             self.origin[axis] + (0..3).map(|i| self.axes[i][axis] * local[i]).sum::<f32>()
19:         })
20:     }
21: 
22:     pub fn validate(&self) -> Result<(), GenerateError> {
23:         let finite = self
24:             .origin
25:             .iter()
26:             .chain(self.axes.iter().flatten())
27:             .chain(self.half_extents.iter())
28:             .all(|v| v.is_finite());
29:         let orthogonal = (0..3).all(|i| {
30:             (0..3).all(|j| {
31:                 (dot(self.axes[i], self.axes[j]) - if i == j { 1.0 } else { 0.0 }).abs() < 0.001
32:             })
33:         });
34:         if !finite || !orthogonal || self.half_extents.iter().any(|v| *v <= 0.0) {
35:             return Err(GenerateError::InvalidSurface);
36:         }
37:         Ok(())
38:     }
39: }
