 11: /// How a piece is built.
 12: #[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
 13: #[serde(rename_all = "snake_case")]
 14: pub enum Construction {
 15:     /// One plate shaped to the wearer.
 16:     #[default]
 17:     Solid,
 18:     /// Narrow lames laced into rows, each row hung from the row above by
 19:     /// lacing that runs down over the upper row's face.
 20:     Lamellar(Tiling),
 21:     /// Scales laced to their neighbours through their top holes, each row
 22:     /// covering the lacing of the row below.
 23:     Scale(Tiling),
 24: }
