 26: impl Construction {
 27:     pub fn name(&self) -> &'static str {
 28:         match self {
 29:             Self::Solid => "Solid",
 30:             Self::Lamellar(_) => "Lamellar",
 31:             Self::Scale(_) => "Scale",
 32:         }
 33:     }
 34: 
 35:     /// The small plates, unless the piece is solid.
 36:     pub fn tiling(&self) -> Option<&Tiling> {
 37:         match self {
 38:             Self::Solid => None,
 39:             Self::Lamellar(tiling) | Self::Scale(tiling) => Some(tiling),
 40:         }
 41:     }
 42: 
 43:     pub fn tiling_mut(&mut self) -> Option<&mut Tiling> {
 44:         match self {
 45:             Self::Solid => None,
 46:             Self::Lamellar(tiling) | Self::Scale(tiling) => Some(tiling),
 47:         }
 48:     }
 49: 
 50:     pub fn validate(&self) -> Result<(), ConstructionError> {
 51:         self.tiling().map_or(Ok(()), Tiling::validate)
 52:     }
 53: 
 54:     /// `trim` as it runs on this construction. On small plates the band
 55:     /// follows each plate's rim, so it keeps to a share of the plate and the
 56:     /// plate's face still shows.
 57:     pub fn trim_on(&self, trim: &Trim) -> Trim {
 58:         match self.tiling() {
 59:             Some(tiling) => trim.narrowed(tiling.plate.widest_trim()),
 60:             None => trim.clone(),
 61:         }
 62:     }
 63: }
