178: 
179:     pub(crate) fn png(width: u32, height: u32, rgb: impl Fn(u32, u32) -> [u8; 3]) -> Vec<u8> {
180:         let rgb = &rgb;
181:         let pixels = (0..height)
182:             .flat_map(|y| (0..width).flat_map(move |x| rgb(x, y)))
183:             .collect::<Vec<_>>();
184:         let mut bytes = Vec::new();
185:         image::codecs::png::PngEncoder::new(&mut bytes)
186:             .write_image(&pixels, width, height, image::ExtendedColorType::Rgb8)
187:             .unwrap();
188:         bytes
189:     }
190: 
191:     /// A groove down the middle of the image.
192:     pub(crate) fn groove_png() -> Vec<u8> {
193:         png(8, 8, |x, _| {
194:             if (3..5).contains(&x) {
195:                 [0; 3]
196:             } else {
197:                 [255; 3]
198:             }
199:         })
200:     }

201:     }
202: 
203:     /// The widest trim band along the plate's rim.
204:     pub fn widest_trim(&self) -> f32 {
205:         (self.width.min(self.height) * Self::TRIM_SHARE).max(Trim::MIN_WIDTH)
206:     }
207: 
208:     /// The widest hole the plate keeps clear of its edges and its other
209:     /// holes, the rows of holes included.
210:     pub fn max_hole_radius(&self) -> f32 {
211:         let across = self.width.min(self.height) / Self::HOLE_CLEARANCE_RADII;
212:         let between_rows = if self.hole_pairs > 1 {
213:             // Centres two and a half radii apart leave half a hole of metal.
214:             self.hole_row_pitch() * 2.0 / Self::HOLE_CLEARANCE_RADII
215:         } else {
216:             f32::INFINITY
217:         };
218:         across.min(between_rows).min(*Self::HOLE_RADIUS.end())
219:     }
220: 
221:     /// The distance between the centres of successive rows of holes.
222:     fn hole_row_pitch(&self) -> f32 {
223:         self.height * Self::HOLE_ROW_SPAN / Self::MAX_HOLE_PAIRS as f32
224:     }
225: 
226:     /// The centre of every lacing hole, a pair per row from the top, each
227:     /// pair left then right. None when the plate has no holes.
228:     pub fn holes(&self) -> Vec<[f32; 2]> {
229:         if self.hole_radius <= 0.0 {
230:             return Vec::new();
231:         }
232:         let x = self.width * Self::HOLE_INSET;
233:         let pitch = self.hole_row_pitch();
234:         (0..self.hole_pairs)
235:             .flat_map(|pair| {
236:                 let y = self.height * 0.5
237:                     - self.hole_radius * Self::FIRST_HOLE_RADII
238:                     - pair as f32 * pitch;
239:                 [[-x, y], [x, y]]
240:             })
241:             .collect()
242:     }
243: }
