 28: /// Crossings one ring may weld; a ring meeting more fails.
 29: const RING_CAPACITY: u32 = 2048;
 30: 
 31: /// Set when a ring crosses fewer than three skin edges.
 32: pub const STATUS_EMPTY_CONTOUR: u32 = 16;
 33: 
 34: /// One realization of the body the bracer is displaced from.
 35: pub struct BracerBody<'a> {
 36:     pub positions: &'a Buffer,
 37:     pub normals: &'a Buffer,
 38: }
 39: 
 40: struct BracerMesh {
 41:     positions: Buffer,
 42:     normals: VertexNormals,
 43: }
 44: 
 45: /// What every realization's mesh shares.
 46: struct Layout {
 47:     design: Buffer,
 48:     surface: DeviceSurface,
 49:     samples: Buffer,
 50:     status: Buffer,
 51:     around: u32,
 52:     indices: Buffer,
 53:     triangle_count: u32,
 54: }
 55: 
 56: /// A mesh's positions and normals, read back.
 57: type MeshSurface = (Vec<[f32; 3]>, Vec<[f32; 3]>);
 58: 
 59: impl Layout {
 60:     fn sample_count(&self) -> u32 {
 61:         self.around * (ALONG + 1)
 62:     }
 63: 
 64:     fn vertex_count(&self) -> u32 {
 65:         self.sample_count() * 2
 66:     }
