  1: //! Plate charts evaluated on the device.
  2: //!
  3: //! A chart is a grid of rows along the plate and columns across it. The host
  4: //! decides the columns -- evenly spaced, or aligned to a flute pattern's
  5: //! crests and lands -- and the connectivity; a kernel built from a shape's
  6: //! two WGSL functions evaluates every vertex:
  7: //!
  8: //! ```wgsl
  9: //! fn chart_point(u: f32, v: f32) -> vec3<f32>   // local position
 10: //! fn chart_offset(u: f32, axial: f32) -> f32    // height along the extrusion
 11: //! ```
 12: //!
 13: //! Both may read the shape's `design` floats, the shell's `params.value*`,
 14: //! and `fit`, the part frame. A shape also defines `chart_origin()`, the
 15: //! local origin of its extrusion; [`AUTHORED_ORIGIN`] is the usual one. The
 16: //! kernel adds the flute relief, places the point through the frame, and
 17: //! writes the shell's extrusion geometry.
 18: 
 19: use fabelgeist_gpu::prelude::BufferUpload;
 20: use std::sync::Arc;
 21: 
 22: use fabelgeist_compute::{Kernel, KernelBatch};
 23: use fabelgeist_gpu::prelude::{Buffer, PassParameters};
 24: 
 25: use super::part::{Extrusion, GridShape, PartBuild, SHELL_WORDS, ShellSpec};
 26: use super::{ArmorGpu, device_error};
 27: use crate::{BoundaryNormals, GenerateError, PlateFluting};
 28: 
 29: mod chart_wgsl;
 30: 
 31: use chart_wgsl::source;
 32: pub(crate) use chart_wgsl::{AUTHORED_ORIGIN, FLUTING};
 33: 
 34: /// Columns across an unfluted chart.
 35: pub(crate) const AROUND: usize = 40;
 36: /// Latitude rings closing a capped chart's tip, the tip vertex excluded.
 37: const TIP_RINGS: usize = 8;
 38: 
 39: #[derive(Clone, Copy, Debug, PartialEq)]
 40: pub(crate) enum ChartBoundary {
 41:     Open,
 42:     Cyclic,
 43:     /// Closed by a rounded tip whose length follows the fitted frame:
 44:     /// `per_half_height` of its half height, plus `fixed`.
 45:     CappedByFrame {
 46:         per_half_height: f32,
 47:         fixed: f32,
 48:     },
 49:     /// The last row welded to one apex vertex.
 50:     Apex,
 51:     /// Closed around, with the last row welded to one apex vertex: a disc.
 52:     CyclicApex,
 53: }
 54: 
 55: /// Boundary codes the chart kernel reads.
 56: const BOUNDARY_ROWS_ONLY: u32 = 0;
 57: const BOUNDARY_CAPPED: u32 = 2;
 58: const BOUNDARY_APEX: u32 = 3;
 59: 
 60: impl ChartBoundary {
 61:     fn code(self) -> u32 {
 62:         match self {
 63:             Self::Open | Self::Cyclic => BOUNDARY_ROWS_ONLY,
 64:             Self::CappedByFrame { .. } => BOUNDARY_CAPPED,
 65:             Self::Apex | Self::CyclicApex => BOUNDARY_APEX,
 66:         }
 67:     }
 68: }
 69: 
 70: /// One plate chart, as the host describes it.
 71: #[derive(Clone, Debug)]
 72: pub(crate) struct PlateChart {
 73:     pub rows: usize,
 74:     pub boundary: ChartBoundary,
 75:     pub thickness: f32,
 76:     pub extrusion: Extrusion,
 77:     /// Extrusion origin and axis (or direction) in the chart's local frame.
 78:     /// A capped chart's origin height is taken from its own first row.
 79:     pub origin: [f32; 3],
 80:     pub axis: [f32; 3],
 81:     pub fluting: Option<PlateFluting>,
 82:     pub span: [f32; 2],
 83:     /// Shape constants that differ between the shells of one part.
 84:     pub values: [f32; 4],
 85:     /// Reflected across its local x before the part frame places it.
 86:     pub mirrored: bool,
 87:     /// Which of the part's frames places this chart.
 88:     pub frame: usize,
 89:     /// Columns across the chart when it is not fluted.
 90:     pub around: usize,
 91: }
 92: 
 93: impl PlateChart {
 94:     fn columns(&self) -> Vec<f32> {
 95:         let around = self.around;
 96:         let mut columns = self.fluting.map_or_else(
 97:             || (0..=around).map(|i| i as f32 / around as f32).collect(),
