106:     fn cyclic(&self) -> bool {
107:         matches!(
108:             self.boundary,
109:             ChartBoundary::Cyclic | ChartBoundary::CyclicApex
110:         )
111:     }
112: 
113:     fn last_row(&self) -> usize {
114:         if matches!(
115:             self.boundary,
116:             ChartBoundary::Apex | ChartBoundary::CyclicApex
117:         ) {
118:             self.rows - 1
119:         } else {
120:             self.rows
