122:     }
123: 
124:     /// Carrier connectivity: two triangles per grid cell, closed around a
125:     /// cyclic chart, and the boundary's cap.
126:     fn indices(&self, stride: usize) -> Vec<u32> {
127:         let cyclic = self.cyclic();
128:         let last_row = self.last_row();
129:         let segments = if cyclic { stride } else { stride - 1 };
130:         let mut indices = Vec::new();
131:         for row in 0..last_row {
132:             for col in 0..segments {
133:                 let next = (col + 1) % stride;
134:                 let [a, b, c, d] = [
135:                     row * stride + col,
136:                     row * stride + next,
137:                     (row + 1) * stride + col,
138:                     (row + 1) * stride + next,
139:                 ]
140:                 .map(|i| i as u32);
141:                 indices.extend([a, b, d, a, d, c]);
142:             }
143:         }
144:         let grid = (last_row + 1) * stride;
145:         match self.boundary {
146:             ChartBoundary::Apex | ChartBoundary::CyclicApex => {
147:                 let tip = grid as u32;
148:                 let start = grid - stride;
149:                 for col in 0..segments {
150:                     let a = (start + col) as u32;
151:                     let b = (start + (col + 1) % stride) as u32;
152:                     indices.extend([a, b, tip]);
153:                 }
154:             }
155:             ChartBoundary::CappedByFrame { .. } => {
156:                 let mut previous: Vec<u32> = (0..stride as u32).collect();
157:                 let mut next_index = grid as u32;
158:                 for _ in 1..TIP_RINGS {
159:                     let next: Vec<u32> = (0..stride as u32).map(|c| next_index + c).collect();
160:                     next_index += stride as u32;
161:                     for col in 0..stride - 1 {
162:                         let [a, b, c, d] =
163:                             [previous[col], previous[col + 1], next[col], next[col + 1]];
164:                         indices.extend([a, d, b, a, c, d]);
165:                     }
166:                     previous = next;
167:                 }
168:                 let tip = next_index;
169:                 for col in 0..stride - 1 {
170:                     indices.extend([tip, previous[col + 1], previous[col]]);
171:                 }
172:             }
173:             ChartBoundary::Open | ChartBoundary::Cyclic => {}
174:         }
175:         indices
176:     }
177: 
178:     fn extra_vertices(&self, stride: usize) -> usize {
179:         match self.boundary {
180:             ChartBoundary::Apex | ChartBoundary::CyclicApex => 1,
181:             ChartBoundary::CappedByFrame { .. } => (TIP_RINGS - 1) * stride + 1,
182:             ChartBoundary::Open | ChartBoundary::Cyclic => 0,
183:         }
184:     }
