 37: /// ankle toward the toe. It thickens radially about the sole's long axis.
 38: const SABATON_LAME: &str = r#"
 39: fn chart_origin() -> vec3<f32> {
 40:     return vec3<f32>(0.0, sole(), 0.0);
 41: }
 42: 
 43: fn chart_offset(u: f32, axial: f32) -> f32 {
 44:     let low = params.value0;
 45:     let high = params.value1;
 46:     return design[GAUGE] * 2.0 * (axial - low) / (high - low);
 47: }
