 49: fn foot_width(t: f32) -> f32 {
 50:     if (t < 0.55) {
 51:         return lerp(0.63, 1.0, smoothstep_unclamped(t / 0.55));
 52:     }
 53:     return lerp(1.0, design[TOE_WIDTH], smoothstep_unclamped((t - 0.55) / 0.45));
 54: }
 55: 
 56: fn chart_point(u: f32, v: f32) -> vec3<f32> {
 57:     let width = fit.half_extents.x;
 58:     let height = fit.half_extents.y;
 59:     let length = fit.half_extents.z;
 60:     let t = lerp(params.value0, params.value1, v);
 61:     let theta = (0.5 - u) * PI;
 62:     let arch = height * design[INSTEP_HEIGHT] * lerp(1.75, 1.1, smoothstep_unclamped(t));
 63:     return vec3<f32>(
 64:         (width * foot_width(t) + design[CLEARANCE]) * sin(theta),
 65:         -height + design[GAUGE] + arch * cos(theta),
