104: const ROWS: u32 = {BOOT_ROWS}u;
105: 
106: fn boot_point(coord: vec4<f32>, v: f32) -> vec3<f32> {{
107:     let width = fit.half_extents.x;
108:     let height = fit.half_extents.y;
109:     let length = fit.half_extents.z;
110:     let gauge = design[GAUGE];
111:     let clearance = design[CLEARANCE];
112:     let ankle_z = -length * 0.45;
113:     let ankle_width = width * 0.69 + clearance;
114:     let ankle_depth = length * 0.35 + clearance;
115:     let upper_height = height * 1.65 + clearance + gauge;
116:     let shaft_height = design[SHAFT_HEIGHT];
117:     let total_height = upper_height + shaft_height;
118:     let sine = coord.x;
119:     let cosine = coord.y;
120:     let toe_factor = lerp(0.72, design[TOE_WIDTH], (cosine + 1.0) * 0.5);
121:     let outer_x = (width * toe_factor + clearance) * coord.z;
122:     let outer_z = (length + clearance) * coord.w;
123:     let inner_x = ankle_width * sine;
124:     let inner_z = ankle_z + ankle_depth * cosine;
125:     let rise = total_height * v;
126:     let transition = smoothstep_unclamped(min(rise / upper_height, 1.0));
127:     let shaft = max((rise - upper_height) / shaft_height, 0.0);
128:     let flare = lerp(1.0, design[SHAFT_FLARE], smoothstep_unclamped(shaft));
129:     return vec3<f32>(
130:         lerp(outer_x, inner_x * flare, transition),
131:         -height - gauge + rise,
132:         lerp(outer_z, ankle_z + (inner_z - ankle_z) * flare, transition),
133:     );
134: }}
