136: fn shell_vertex(index: u32, coord: vec4<f32>) -> ShellVertex {{
137:     if (index == COLUMNS * (ROWS + 1u)) {{
138:         // The sole centre: the mean of the perimeter row, summed in order.
139:         var sum = vec3<f32>(0.0);
140:         for (var column = 0u; column < COLUMNS; column = column + 1u) {{
141:             sum = sum + boot_point(coords[column], 0.0);
142:         }}
143:         return ShellVertex(sum / f32(COLUMNS), 0.0);
144:     }}
145:     let row = index / COLUMNS;
146:     return ShellVertex(boot_point(coord, f32(row) / f32(ROWS)), 0.0);
147: }}
