125: /// Rows up a buffe's face, or up each of its courses.
126: const BUFFE_ROWS: usize = 32;
127: /// Columns across a buffe's face.
128: const BUFFE_COLUMNS: usize = 40;
129: /// The pierced face's design chart, in millimetres: its half width and height.
130: const BUFFE_CHART_HALF_WIDTH_MM: f64 = 160.0;
131: const BUFFE_CHART_HEIGHT_MM: f64 = 100.0;
132: 
133: /// A removable face defense under the peak: one face, or overlapping
134: /// courses, its breaths pierced through the face or its top course. A
135: /// vertex's coordinates are across the face, up it and its course, which the
136: /// design alone decides.
137: fn buffe(b: &BuffeDesign, gauge: f32) -> Result<Vec<CoordShell>, GenerateError> {
138:     let breaths = b.breaths.filter(|breaths| breaths.count_per_row > 0);
139:     let courses = b.courses.map_or(1, |courses| courses.plate_count);
140:     (0..courses)
141:         .map(|course| {
142:             let top = course + 1 == courses;
143:             let surface = match breaths.filter(|_| top) {
144:                 Some(breaths) => {
145:                     // The top course's chart reaches down to its lapped lower edge.
146:                     let height = b.courses.map_or(BUFFE_CHART_HEIGHT_MM, |courses| {
147:                         let low = [
148:                             0.0,
149:                             courses.lower_boundary.unit(),
150:                             courses.upper_boundary.unit(),
151:                         ][usize::from(course)];
152:                         BUFFE_CHART_HEIGHT_MM * f64::from(1.0 - low) + f64::from(courses.overlap.0)
153:                     });
154:                     pierced_buffe(&breaths, height, f32::from(course))?
155:                 }
156:                 None => buffe_grid(f32::from(course)),
157:             };
158:             Ok(surface.shell(gauge, CoordExtrusion::Normal))
159:         })
160:         .collect()
161: }
