208: /// The toe cap as a half dome: latitude rings over a half turn of columns,
209: /// closed by a fan to its tip.
210: fn toe_cap(gauge: f32) -> CoordShell {
211:     let stride = AROUND + 1;
212:     let mut coords = Vec::with_capacity(TOE_RINGS * stride + 1);
213:     for row in 0..TOE_RINGS {
214:         let latitude = row as f32 / TOE_RINGS as f32 * PI * 0.5;
215:         for column in 0..=AROUND {
216:             let theta = (0.5 - column as f32 / AROUND as f32) * PI;
217:             coords.push([theta.sin(), theta.cos(), latitude.cos(), latitude.sin()]);
218:         }
219:     }
220:     let mut indices = Vec::new();
221:     for row in 0..TOE_RINGS - 1 {
222:         for column in 0..AROUND {
223:             let a = (row * stride + column) as u32;
224:             let b = a + 1;
225:             let c = a + stride as u32;
226:             let e = c + 1;
227:             indices.extend_from_slice(&[a, b, e, a, e, c]);
228:         }
229:     }
230:     let tip = coords.len() as u32;
231:     coords.push([0.0; 4]);
232:     for column in 0..AROUND {
233:         let a = ((TOE_RINGS - 1) * stride + column) as u32;
234:         indices.extend_from_slice(&[a, a + 1, tip]);
235:     }
236:     CoordShell {
237:         coords,
238:         indices,
239:         boundary_normals: BoundaryNormals::Smooth,
240:         thickness: gauge,
241:         extrusion: CoordExtrusion::Normal,
242:         values: [0.0; 4],
243:         mirrored: false,
244:         frame: 0,
245:         passes: 1,
246:         hinge: None,
247:     }
248: }
