226: /// A plain face or course: rows up it, columns across it.
227: fn buffe_grid(course: f32) -> CoordSurface {
228:     let mut surface = CoordSurface::default();
229:     let mut previous: Vec<u32> = Vec::new();
230:     for row in 0..=BUFFE_ROWS {
231:         let v = row as f32 / BUFFE_ROWS as f32;
232:         let ring = (0..=BUFFE_COLUMNS)
233:             .map(|column| {
234:                 let u = column as f32 / BUFFE_COLUMNS as f32;
235:                 surface.vertex(VertexKind::Buffe, [u, v, course])
236:             })
237:             .collect::<Vec<_>>();
238:         if !previous.is_empty() {
239:             surface.connect(&ring, &previous, false);
240:         }
241:         previous = ring;
242:     }
243:     surface
244: }
