246: /// A face or top course with its breaths cut through, triangulated in the
247: /// design chart `height` millimetres tall.
248: fn pierced_buffe(
249:     breaths: &VisorBreaths,
250:     height: f64,
251:     course: f32,
252: ) -> Result<CoordSurface, GenerateError> {
253:     let outer = [
254:         [-BUFFE_CHART_HALF_WIDTH_MM, 0.0],
255:         [BUFFE_CHART_HALF_WIDTH_MM, 0.0],
256:         [BUFFE_CHART_HALF_WIDTH_MM, height],
257:         [-BUFFE_CHART_HALF_WIDTH_MM, height],
258:     ];
259:     let half_columns = BUFFE_COLUMNS as i32;
260:     let interior = (1..BUFFE_ROWS).flat_map(|row| {
261:         (-half_columns + 1..half_columns).map(move |column| {
262:             [
263:                 f64::from(column) * BUFFE_CHART_HALF_WIDTH_MM / f64::from(half_columns),
264:                 row as f64 * height / BUFFE_ROWS as f64,
265:             ]
266:         })
267:     });
268:     let holes = breaths.openings(BUFFE_CHART_HEIGHT_MM, ArmorDetail::BakeSource);
269:     let domain = PiercedDomain::new(&outer, &holes, interior, ArmorDetail::BakeSource)?;
270:     let mut surface = CoordSurface::default();
271:     for p in &domain.points {
272:         surface.vertex(
273:             VertexKind::Buffe,
274:             [
275:                 ((p[0] / BUFFE_CHART_HALF_WIDTH_MM + 1.0) * 0.5) as f32,
276:                 (1.0 - p[1] / height) as f32,
277:                 course,
278:             ],
279:         );
280:     }
281:     surface.indices = domain.indices;
282:     Ok(surface)
283: }
