122:     /// The crown of a styled helmet; a fluted or crested crown is fanned
123:     /// from the temples. Returns the rim.
124:     pub fn styled_dome(&mut self, style: &HelmetCrown, crest: f32) -> Vec<u32> {
125:         let first_index = self.indices.len();
126:         if style.fluting.is_none() && crest <= 0.0 {
127:             return self.full_dome();
128:         }
129:         let rim = self.fan_dome(style.fluting.as_ref(), crest > 0.0);
130:         for face in self.indices[first_index..].as_chunks_mut::<3>().0 {
131:             face.swap(1, 2);
132:         }
133:         rim
134:     }
