136:     fn fan_dome(&mut self, pattern: Option<&PlateFluting>, crest: bool) -> Vec<u32> {
137:         let columns = pattern.map_or_else(
138:             || {
139:                 (0..=FAN_COLUMNS)
140:                     .map(|i| i as f32 / FAN_COLUMNS as f32)
141:                     .collect()
142:             },
143:             |p| p.columns(FAN_COLUMNS),
144:         );
145:         let rim = (0..AROUND)
146:             .map(|i| {
147:                 let angle = i as f32 / AROUND as f32 * 2.0 * PI;
148:                 self.vertex(VertexKind::FanRim, [angle, 0.0, 0.0])
149:             })
150:             .collect::<Vec<_>>();
151:         let first = rim[AROUND / 4];
152:         let mut rings: Vec<Vec<u32>> = Vec::new();
153:         for (latitude, rim_row) in latitudes(crest) {
154:             let front = (AROUND + AROUND / 4 - rim_row) % AROUND;
155:             let mut ring = Vec::with_capacity(columns.len());
156:             for (column, u) in columns.iter().enumerate() {
157:                 // The first and last columns are the rim itself, whose flute
158:                 // relief is zero: flutes never reach a chart's edges.
159:                 let id = if column == 0 {
160:                     rim[front]
161:                 } else if column + 1 == columns.len() {
162:                     rim[(AROUND + AROUND / 2 - front) % AROUND]
163:                 } else {
164:                     match latitude {
165:                         Latitude::Regular(value) => {
166:                             self.vertex(VertexKind::FanPoint, [value, *u, 0.0])
167:                         }
168:                         Latitude::Crest { side, base } => {
169:                             self.vertex(VertexKind::FanCrest, [side, f32::from(u8::from(base)), *u])
170:                         }
171:                     }
172:                 };
173:                 ring.push(id);
174:             }
175:             if let Some(previous) = rings.last() {
176:                 for i in 0..ring.len() - 1 {
177:                     for triangle in [
178:                         [previous[i], ring[i], ring[i + 1]],
179:                         [previous[i], ring[i + 1], previous[i + 1]],
180:                     ] {
181:                         if triangle[0] != triangle[1]
182:                             && triangle[1] != triangle[2]
183:                             && triangle[2] != triangle[0]
184:                         {
185:                             self.indices.extend(triangle);
186:                         }
187:                     }
188:                 }
189:             } else {
190:                 for pair in ring.windows(2) {
191:                     self.indices.extend([first, pair[0], pair[1]]);
192:                 }
193:             }
194:             rings.push(ring);
195:         }
196:         let last = rim[AROUND * 3 / 4];
197:         for pair in rings.last().expect("crown rings").windows(2) {
198:             self.indices.extend([pair[0], last, pair[1]]);
199:         }
200:         rim
201:     }
