15: /// The heaviest eight joints of `skins`, each weighted by its share,
16: /// renormalised. With no weight at all, the first skin.
17: pub(crate) fn blend(first: SkinShare, remaining: &[SkinShare]) -> RigInfluences<8> {
18:     let mut merged = Vec::<Influence>::with_capacity((1 + remaining.len()) * 8);
19:     for SkinShare { skin, share } in std::iter::once(&first).chain(remaining) {
20:         for (joint, weight) in skin.joints.iter().zip(&skin.weights) {
21:             let weight = weight * share;
22:             if weight <= 0.0 {
23:                 continue;
24:             }
25:             match merged
26:                 .iter_mut()
27:                 .find(|influence| influence.joint == *joint)
28:             {
29:                 Some(influence) => influence.weight += weight,
30:                 None => merged.push(Influence {
31:                     joint: *joint,
32:                     weight,
33:                 }),
34:             }
35:         }
36:     }
37:     merged.sort_by(|x, y| y.weight.total_cmp(&x.weight).then(x.joint.cmp(&y.joint)));
38:     merged.truncate(8);
39:     let total = merged.iter().map(|influence| influence.weight).sum::<f32>();
40:     if total <= 0.0 {
41:         return first.skin;
42:     }
43:     let mut joints = [RigJointOrdinal::from(0usize); 8];
44:     let mut weights = [0.0f32; 8];
45:     for (slot, influence) in merged.into_iter().enumerate() {
46:         joints[slot] = influence.joint;
47:         weights[slot] = influence.weight / total;
48:     }
49:     RigInfluences { joints, weights }
50: }
