210: /// Each edge of the closed polygon `ring`.
211: fn edges(ring: &[[f32; 2]]) -> impl Iterator<Item = ([f32; 2], [f32; 2])> + '_ {
212:     (0..ring.len()).map(|i| (ring[i], ring[(i + 1) % ring.len()]))
213: }
214: 
215: /// A lacing hole as a polygon, counterclockwise.
216: fn circle([x, y]: [f32; 2], radius: f32) -> Vec<[f32; 2]> {
217:     (0..HOLE_SIDES)
218:         .map(|i| {
219:             let t = i as f32 * std::f32::consts::TAU / HOLE_SIDES as f32;
220:             [x + radius * t.cos(), y + radius * t.sin()]
221:         })
222:         .collect()
223: }
224: 
225: /// Whether `point` lies inside the closed polygon `ring`.
226: fn inside(ring: &[[f32; 2]], [x, y]: [f32; 2]) -> bool {
227:     let mut inside = false;
228:     for ([ax, ay], [bx, by]) in edges(ring) {
229:         if (ay > y) != (by > y) && x < ax + (y - ay) * (bx - ax) / (by - ay) {
230:             inside = !inside;
231:         }
232:     }
233:     inside
234: }
