11: use super::surface::{GridPoint, GridSurface};
12: 
13: /// Lattice cells across a plate, and along it.
14: const CELLS: [usize; 2] = [4, 8];
15: /// How far past its outline the lattice reaches, as a share of the plate, so
16: /// that cord leaving a hole or turning under a foot lands on it.
17: const MARGIN: f32 = 0.15;
18: 
19: /// A plate's coordinates on its grid.
20: #[derive(Clone, Debug)]
21: pub(super) struct TileMap {
22:     /// The lattice's corner and cell size in the plate's coordinates.
23:     corner: [f32; 2],
24:     cell: [f32; 2],
25:     /// Nodes row by row from the bottom, `CELLS[0] + 1` across.
26:     nodes: Vec<GridPoint>,
27: }
28: 
29: impl TileMap {
30:     /// Walk a `width` by `height` plate out from `center`. `None` where the
31:     /// surface has no frame to step in.
32:     pub(super) fn walk(
33:         surface: &GridSurface,
34:         center: GridPoint,
35:         width: f32,
36:         height: f32,
37:     ) -> Option<Self> {
38:         let size = [width, height].map(|size| size * (1.0 + 2.0 * MARGIN));
39:         let cell = [size[0] / CELLS[0] as f32, size[1] / CELLS[1] as f32];
40:         let step_from = |at: GridPoint, across: f32, up: f32| {
41:             let step = surface.frame(at).step(across, up)?;
42:             Some(GridPoint {
43:                 row: at.row + step.row,
44:                 column: at.column + step.column,
45:             })
46:         };
47:         // Up and down the plate's centre line, then across from each node.
48:         let half = [CELLS[0] / 2, CELLS[1] / 2];
49:         let mut spine = vec![center; CELLS[1] + 1];
50:         for k in 1..=half[1] {
51:             spine[half[1] + k] = step_from(spine[half[1] + k - 1], 0.0, cell[1])?;
52:             spine[half[1] - k] = step_from(spine[half[1] - k + 1], 0.0, -cell[1])?;
53:         }
54:         let mut nodes = Vec::with_capacity((CELLS[0] + 1) * (CELLS[1] + 1));
55:         for middle in spine {
56:             let mut row = vec![middle; CELLS[0] + 1];
57:             for k in 1..=half[0] {
58:                 row[half[0] + k] = step_from(row[half[0] + k - 1], cell[0], 0.0)?;
59:                 row[half[0] - k] = step_from(row[half[0] - k + 1], -cell[0], 0.0)?;
60:             }
61:             nodes.extend(row);
62:         }
63:         Some(Self {
64:             corner: [-size[0] * 0.5, -size[1] * 0.5],
65:             cell,
66:             nodes,
67:         })
68:     }
69: 
70:     /// The grid point at `x` across and `y` up the plate from its centre,
71:     /// continued linearly past the lattice.
72:     pub(super) fn at(&self, x: f32, y: f32) -> GridPoint {
73:         let locate = |value: f32, axis: usize| {
74:             let t = (value - self.corner[axis]) / self.cell[axis];
75:             let cell = (t.floor() as i64).clamp(0, CELLS[axis] as i64 - 1) as usize;
76:             (cell, t - cell as f32)
77:         };
78:         let ((i, s), (j, t)) = (locate(x, 0), locate(y, 1));
79:         let node = |i: usize, j: usize| self.nodes[j * (CELLS[0] + 1) + i];
80:         let lerp = |a: GridPoint, b: GridPoint, t: f32| GridPoint {
81:             row: a.row + (b.row - a.row) * t,
82:             column: a.column + (b.column - a.column) * t,
83:         };
84:         lerp(
85:             lerp(node(i, j), node(i + 1, j), s),
86:             lerp(node(i, j + 1), node(i + 1, j + 1), s),
87:             t,
88:         )
89:     }
90: }
