156: /// Each vertex's welded point, and the welded points.
157: fn weld(positions: &[[f32; 3]]) -> (Vec<u32>, Vec<[f32; 3]>) {
158:     let mut ids = HashMap::new();
159:     let mut points = Vec::new();
160:     let welded = positions
161:         .iter()
