219: /// Join directed edges into polylines of welded points. A closed chain
220: /// repeats its first point last; open chains start where no edge arrives.
221: fn chains(edges: &[(u32, u32)]) -> Vec<Vec<u32>> {
222:     let mut outgoing = BTreeMap::<u32, Vec<usize>>::new();
223:     let arriving = edges.iter().map(|(_, end)| *end).collect::<BTreeSet<_>>();
224:     for (index, (start, _)) in edges.iter().enumerate() {
225:         outgoing.entry(*start).or_default().push(index);
226:     }
227:     let mut used = vec![false; edges.len()];
228:     let open_starts = (0..edges.len()).filter(|e| !arriving.contains(&edges[*e].0));
229:     let mut chains = Vec::new();
230:     for first in open_starts.chain(0..edges.len()).collect::<Vec<_>>() {
231:         if used[first] {
232:             continue;
233:         }
234:         let mut chain = vec![edges[first].0];
235:         let mut at = first;
236:         loop {
237:             used[at] = true;
238:             let end = edges[at].1;
239:             chain.push(end);
240:             if end == chain[0] {
241:                 break;
242:             }
243:             match outgoing
244:                 .get(&end)
245:                 .and_then(|next| next.iter().find(|e| !used[**e]))
246:             {
247:                 Some(next) => at = *next,
248:                 None => break,
249:             }
250:         }
251:         chains.push(chain);
252:     }
253:     chains
254: }
