23:             (0..CELLS).flat_map(move |i| {
24:                 let [a, b, c, d] = [
25:                     j * row + i,
26:                     j * row + i + 1,
27:                     (j + 1) * row + i + 1,
28:                     (j + 1) * row + i,
29:                 ];
