83: /// Distance from a point on the plate at `x` to its outline.
84: fn inset(p: [f32; 3], x: f32) -> f32 {
85:     let (u, v) = (p[0] - x, p[1]);
86:     u.min(SIDE - u).min(v).min(SIDE - v)
