 20: /// Primitives per leaf below which splitting stops paying for itself.
 21: const MAX_LEAF_SIZE: usize = 4;
 22: /// Candidate split planes tried per axis.
 23: const BIN_COUNT: usize = 12;
 24: 
 25: #[derive(Clone, Copy, Debug)]
 26: pub struct Node {
 27:     pub bounds: Aabb,
 28:     /// Left child for an internal node; first primitive for a leaf.
 29:     pub left_first: u32,
 30:     /// Zero marks an internal node.
 31:     pub count: u32,
 32: }
