143:     /// The cheapest binned split, or `None` when leaving the node whole is
144:     /// cheaper than any of them.
145:     fn find_split(&self, first: usize, count: usize, bounds: &[Aabb]) -> Option<(usize, f32)> {
146:         let slice = &self.indices[first..first + count];
147: 
148:         // Bin over the *centroid* bounds, not the node bounds: binning over
149:         // the latter wastes bins on the margin that large primitives add.
150:         let centroid_bounds = slice.iter().fold(Aabb::EMPTY, |acc, &i| {
151:             acc.extend(bounds[i as usize].center())
152:         });
153:         let extent = centroid_bounds.extent();
154: 
155:         let leaf_cost = count as f32;
156:         let mut best: Option<(usize, f32, f32)> = None;
157: 
158:         for axis in 0..3 {
159:             let size = extent.axis(axis);
160:             if size <= 0.0 {

161:                 continue;
162:             }
163:             let scale = BIN_COUNT as f32 / size;
164:             let origin = centroid_bounds.min.axis(axis);
165: 
166:             let mut bin_bounds = [Aabb::EMPTY; BIN_COUNT];
167:             let mut bin_counts = [0u32; BIN_COUNT];
168:             for &index in slice {
169:                 let primitive = bounds[index as usize];
170:                 let bin = (((primitive.center().axis(axis) - origin) * scale) as usize)
171:                     .min(BIN_COUNT - 1);
172:                 bin_bounds[bin] = bin_bounds[bin].union(primitive);
173:                 bin_counts[bin] += 1;
174:             }
175: 
176:             // Sweep from both ends so each of the BIN_COUNT - 1 planes knows
177:             // the bounds and the population on either side of it.
178:             let mut left_area = [0.0f32; BIN_COUNT - 1];
179:             let mut right_area = [0.0f32; BIN_COUNT - 1];
180:             let mut left_count = [0u32; BIN_COUNT - 1];
181:             let mut right_count = [0u32; BIN_COUNT - 1];
182: 
183:             let mut accumulated = Aabb::EMPTY;
184:             let mut population = 0u32;
185:             for i in 0..BIN_COUNT - 1 {
186:                 accumulated = accumulated.union(bin_bounds[i]);
187:                 population += bin_counts[i];
188:                 left_area[i] = accumulated.surface_area();
189:                 left_count[i] = population;
190:             }
191: 
192:             accumulated = Aabb::EMPTY;
193:             population = 0;
194:             for i in (0..BIN_COUNT - 1).rev() {
195:                 accumulated = accumulated.union(bin_bounds[i + 1]);
196:                 population += bin_counts[i + 1];
197:                 right_area[i] = accumulated.surface_area();
198:                 right_count[i] = population;
199:             }
200: 
201:             for i in 0..BIN_COUNT - 1 {
202:                 if left_count[i] == 0 || right_count[i] == 0 {
203:                     continue;
204:                 }
205:                 let cost =
206:                     left_count[i] as f32 * left_area[i] + right_count[i] as f32 * right_area[i];
207:                 let position = origin + (i + 1) as f32 / scale;
208:                 if best.is_none_or(|(_, _, best_cost)| cost < best_cost) {
209:                     best = Some((axis, position, cost));
210:                 }
211:             }
212:         }
213: 
214:         // The parent's own area normalises the split cost into the same units
215:         // as `leaf_cost`.
216:         let parent_area = slice
217:             .iter()
218:             .fold(Aabb::EMPTY, |acc, &i| acc.union(bounds[i as usize]))
219:             .surface_area();
220:         let (axis, position, cost) = best?;
221:         if parent_area > 0.0 && cost / parent_area >= leaf_cost {
222:             return None;
223:         }
224:         Some((axis, position))
225:     }
