227:     /// Recompute every node's bounds against new primitive bounds, keeping the
228:     /// topology. Cheap enough to run every frame on a deforming mesh, and the
229:     /// tree degrades gracefully as long as the deformation is not wild.
230:     pub fn refit(&mut self, bounds: &[Aabb]) {
231:         for index in (0..self.nodes.len()).rev() {
232:             let node = self.nodes[index];
233:             self.nodes[index].bounds = if node.is_leaf() {
234:                 let first = node.left_first as usize;
235:                 self.indices[first..first + node.count as usize]
236:                     .iter()
237:                     .fold(Aabb::EMPTY, |acc, &i| acc.union(bounds[i as usize]))
238:             } else {
239:                 let left = node.left_first as usize;
240:                 self.nodes[left].bounds.union(self.nodes[left + 1].bounds)
241:             };
242:         }
243:     }
244: 
245:     /// Call `visit` with every primitive in a leaf whose *node* box overlaps
246:     /// `query`.
247:     ///
248:     /// A leaf holds several primitives and its box is their union, so this
249:     /// over-reports: some of what it hands back does not overlap at all. That
250:     /// is the normal contract for a hierarchy -- it narrows the search, and
251:     /// the caller runs the exact test, which for a triangle or a particle is
252:     /// not a box test anyway. Use [`Bvh::query_aabb`] when the box test *is*
253:     /// the exact test.
254:     pub fn candidates_aabb(&self, query: &Aabb, visit: impl FnMut(u32)) {
255:         self.walk(|node| node.bounds.overlaps(query), visit);
256:     }
257: 
258:     /// Call `visit` with every primitive whose own box overlaps `query`.
259:     ///
260:     /// `bounds` must be the array the tree was built from.
261:     pub fn query_aabb(&self, bounds: &[Aabb], query: &Aabb, mut visit: impl FnMut(u32)) {
262:         self.candidates_aabb(query, |index| {
263:             if bounds[index as usize].overlaps(query) {
264:                 visit(index);
265:             }
266:         });
267:     }
