269:     /// Call `visit` with every primitive in a leaf whose node box is within
270:     /// `radius` of `point`. Over-reports, for the same reason as
271:     /// [`Bvh::candidates_aabb`].
272:     pub fn candidates_point(&self, point: Vec3, radius: f32, visit: impl FnMut(u32)) {
273:         let radius_squared = radius * radius;
274:         self.walk(
275:             |node| node.bounds.distance_squared(point) <= radius_squared,
276:             visit,
277:         );
278:     }
279: 
280:     /// Call `visit` with every primitive whose own box is within `radius` of
281:     /// `point`.
282:     pub fn query_point(
283:         &self,
284:         bounds: &[Aabb],
285:         point: Vec3,
286:         radius: f32,
287:         mut visit: impl FnMut(u32),
288:     ) {
289:         let radius_squared = radius * radius;
290:         self.candidates_point(point, radius, |index| {
291:             if bounds[index as usize].distance_squared(point) <= radius_squared {
292:                 visit(index);
293:             }
294:         });
295:     }
