327:     /// Nearest ray hit. `hit` returns the distance at which the ray meets
328:     /// primitive `i`, if it does at all within the current limit.
329:     pub fn raycast(
330:         &self,
331:         ray: &Ray,
332:         max_distance: f32,
333:         mut hit: impl FnMut(u32, f32) -> Option<f32>,
334:     ) -> Option<(u32, f32)> {
335:         let mut best: Option<(u32, f32)> = None;
336:         let limit = std::cell::Cell::new(max_distance);
337: 
338:         self.walk(
339:             |node| ray.hits(&node.bounds, limit.get()).is_some(),
340:             |index| {
341:                 if let Some(distance) = hit(index, limit.get())
342:                     && distance < limit.get()
343:                 {
344:                     limit.set(distance);
345:                     best = Some((index, distance));
346:                 }
347:             },
348:         );
349: 
350:         best
351:     }
352: 
353:     /// Depth-first walk with an explicit stack.
354:     ///
355:     /// `descend` decides whether a node is worth entering; `leaf` is called
356:     /// per primitive. `descend` is re-asked on every node, so a caller that
357:     /// tightens a shared limit inside `leaf` -- as `closest` and `raycast` do
358:     /// -- prunes the rest of the walk with it.
359:     fn walk(&self, mut descend: impl FnMut(&Node) -> bool, mut leaf: impl FnMut(u32)) {
360:         if self.nodes.is_empty() {
361:             return;
362:         }
363:         // 64 is well past the depth a SAH build reaches for any realistic
364:         // primitive count; it is a stack, not a bound on the tree.
365:         let mut stack: Vec<u32> = Vec::with_capacity(64);
366:         stack.push(0);
367: 
368:         while let Some(index) = stack.pop() {
369:             let node = &self.nodes[index as usize];
370:             if !descend(node) {
371:                 continue;
372:             }
373:             if node.is_leaf() {
374:                 let first = node.left_first as usize;
375:                 for &primitive in &self.indices[first..first + node.count as usize] {
376:                     leaf(primitive);
377:                 }
378:             } else {
379:                 stack.push(node.left_first);
380:                 stack.push(node.left_first + 1);
381:             }
382:         }
383:     }
384: }
