 40:     #[inline]
 41:     pub fn transform_vec(&self, v: [f64; 3]) -> [f64; 3] {
 42:         [
 43:             self.0[0] * v[0] + self.0[1] * v[1] + self.0[2] * v[2],
 44:             self.0[3] * v[0] + self.0[4] * v[1] + self.0[5] * v[2],
 45:             self.0[6] * v[0] + self.0[7] * v[1] + self.0[8] * v[2],
 46:         ]
 47:     }
 48: 
 49:     #[inline]
 50:     pub fn transform_vec32(&self, v: [f32; 3]) -> [f32; 3] {
 51:         let v64 = [v[0] as f64, v[1] as f64, v[2] as f64];
 52:         let out = self.transform_vec(v64);
 53:         [out[0] as f32, out[1] as f32, out[2] as f32]
 54:     }
 55: 
 56:     pub fn invert(&self) -> Option<Self> {
 57:         crate::space::invert_3x3(&self.0).map(Self)
 58:     }
 59: }
 60: 
 61: // Bradford cone response matrix
 62: const M_BRADFORD: Matrix3x3 = Matrix3x3([
 63:     0.8951, 0.2664, -0.1614, -0.7502, 1.7135, 0.0367, 0.0389, -0.0685, 1.0296,
 64: ]);
 65: 
 66: // Inverse of Bradford matrix
 67: const M_BRADFORD_INV: Matrix3x3 = Matrix3x3([
 68:     0.9869929055,
 69:     -0.1470542564,
 70:     0.1599626517,
 71:     0.4323052697,
 72:     0.5183602715,
 73:     0.0492912282,
 74:     -0.0085286646,
 75:     0.0400428217,
 76:     0.9684866958,
 77: ]);
 78: 
 79: /// Computes a 3x3 chromatic adaptation matrix between source and destination white points
 80: /// using the Bradford transform method.
 81: pub fn bradford_adaptation(src: WhitePoint, dst: WhitePoint) -> Matrix3x3 {
 82:     if src == dst {
 83:         return Matrix3x3::IDENTITY;
 84:     }
 85: 
 86:     let src_xyz = src.xyz();
 87:     let dst_xyz = dst.xyz();
 88: 
 89:     let src_cone = M_BRADFORD.transform_vec(src_xyz);
 90:     let dst_cone = M_BRADFORD.transform_vec(dst_xyz);
 91: 
 92:     let scale = Matrix3x3([
 93:         dst_cone[0] / src_cone[0],
 94:         0.0,
 95:         0.0,
 96:         0.0,
 97:         dst_cone[1] / src_cone[1],
 98:         0.0,
 99:         0.0,
100:         0.0,
101:         dst_cone[2] / src_cone[2],
102:     ]);
103: 
104:     M_BRADFORD_INV.mul(&scale).mul(&M_BRADFORD)
105: }
