107: /// A precomputed color transformation between two color spaces.
108: #[derive(Debug, Clone, Copy, PartialEq)]
109: pub struct ColorTransform {
110:     pub matrix: Matrix3x3,
111:     pub src_transfer: TransferFunction,
112:     pub dst_transfer: TransferFunction,
113: }
114: 
115: impl ColorTransform {
116:     /// Creates a transformation between two arbitrary primaries/white-points.
117:     pub fn new(src_primaries: &ColorPrimaries, dst_primaries: &ColorPrimaries) -> Self {
118:         let src_to_xyz = Matrix3x3(src_primaries.to_xyz_matrix());
119:         let dst_from_xyz = Matrix3x3(dst_primaries.from_xyz_matrix());
120:         let adapt = bradford_adaptation(src_primaries.white, dst_primaries.white);
121: 
122:         let matrix = dst_from_xyz.mul(&adapt).mul(&src_to_xyz);
123: 
124:         Self {
125:             matrix,
126:             src_transfer: TransferFunction::Linear,
127:             dst_transfer: TransferFunction::Linear,
128:         }
129:     }
130: 
131:     /// Creates a color transformation between two standard `ColorSpace` definitions,
132:     /// including transfer curves.
133:     pub fn between_spaces(src: ColorSpace, dst: ColorSpace) -> Self {
134:         let src_prim = src.primaries();
135:         let dst_prim = dst.primaries();
136:         let mut transform = Self::new(&src_prim, &dst_prim);
137:         transform.src_transfer = src.transfer_function();
138:         transform.dst_transfer = dst.transfer_function();
139:         transform
140:     }
141: 
142:     /// Applies the complete transformation (transfer decode -> matrix -> transfer encode)
143:     /// to an RGB triplet.
144:     #[inline]
145:     pub fn convert(&self, rgb: [f32; 3]) -> [f32; 3] {
146:         let linear_src = self.src_transfer.to_linear_rgb(rgb);
147:         let linear_dst = self.matrix.transform_vec32(linear_src);
148:         self.dst_transfer.from_linear_rgb(linear_dst)
149:     }
150: }
151: 
152: /// High-level function to convert an RGB color from source color space to destination color space.
153: #[inline]
154: pub fn convert_color(rgb: [f32; 3], src: ColorSpace, dst: ColorSpace) -> [f32; 3] {
155:     if src == dst {
156:         return rgb;
157:     }
158:     let transform = ColorTransform::between_spaces(src, dst);
159:     transform.convert(rgb)
160: }

