165: 
166: /// Converts image pixel buffers between formats on CPU.
167: pub fn convert_pixels(
168:     src: &[u8],
169:     src_format: PixelFormat,
170:     dst: &mut [u8],
171:     dst_format: PixelFormat,
172:     width: usize,
173:     height: usize,
174: ) -> Result<(), ConversionError> {
175:     let num_pixels = width * height;
176: 
177:     // Fast path: identical format
178:     if src_format == dst_format {
179:         let len = src.len().min(dst.len());
180:         dst[..len].copy_from_slice(&src[..len]);
181:         return Ok(());
182:     }
183: 
184:     // YUV decoding paths
185:     if src_format == PixelFormat::Nv12
186:         && (dst_format == PixelFormat::Rgba8Unorm || dst_format == PixelFormat::Rgba8UnormSrgb)
187:     {
188:         let y_len = num_pixels;
189:         let uv_len = num_pixels / 2;
190:         if src.len() < y_len + uv_len {
191:             return Err(ConversionError::SourceBufferTooSmall {
192:                 expected: y_len + uv_len,
193:                 actual: src.len(),
194:             });
195:         }
196:         if dst.len() < num_pixels * 4 {
197:             return Err(ConversionError::DestinationBufferTooSmall {
198:                 expected: num_pixels * 4,
199:                 actual: dst.len(),
200:             });
201:         }
202:         let (y_plane, uv_plane) = src.split_at(y_len);
203:         yuv::nv12_to_rgba8(
204:             y_plane,
205:             uv_plane,
206:             width,
207:             height,
208:             YuvStandard::Bt709,
209:             YuvRange::Full,
210:             dst,
211:         );
212:         return Ok(());
213:     }
214: 
215:     if src_format == PixelFormat::I420
216:         && (dst_format == PixelFormat::Rgba8Unorm || dst_format == PixelFormat::Rgba8UnormSrgb)
217:     {
218:         let y_len = num_pixels;
219:         let chroma_len = num_pixels / 4;
220:         let expected = y_len + chroma_len * 2;
221:         if src.len() < expected {
222:             return Err(ConversionError::SourceBufferTooSmall {
223:                 expected,
224:                 actual: src.len(),
225:             });
226:         }
227:         if dst.len() < num_pixels * 4 {
228:             return Err(ConversionError::DestinationBufferTooSmall {
229:                 expected: num_pixels * 4,
230:                 actual: dst.len(),
231:             });
232:         }
233:         let y_plane = &src[..y_len];
234:         let u_plane = &src[y_len..y_len + chroma_len];
235:         let v_plane = &src[y_len + chroma_len..expected];
236:         yuv::i420_to_rgba8(
237:             y_plane,
238:             u_plane,
239:             v_plane,
240:             width,
241:             height,
242:             YuvStandard::Bt709,
243:             YuvRange::Full,
244:             dst,
245:         );
246:         return Ok(());
247:     }
248: 
249:     // RGBA8 / BGRA8 conversions
250:     match (src_format, dst_format) {
251:         (PixelFormat::Bgra8Unorm, PixelFormat::Rgba8Unorm)
252:         | (PixelFormat::Bgra8UnormSrgb, PixelFormat::Rgba8UnormSrgb)
253:         | (PixelFormat::Rgba8Unorm, PixelFormat::Bgra8Unorm)
254:         | (PixelFormat::Rgba8UnormSrgb, PixelFormat::Bgra8UnormSrgb) => {
255:             let expected = num_pixels * 4;
256:             check_buffer_lengths(src, dst, expected, expected)?;
257:             for (s, d) in src
258:                 .as_chunks::<4>()
259:                 .0
260:                 .iter()
261:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
262:             {
263:                 d[0] = s[2];
264:                 d[1] = s[1];
265:                 d[2] = s[0];
266:                 d[3] = s[3];
267:             }
268:             Ok(())
269:         }
270:         (PixelFormat::Rgba8Unorm, PixelFormat::Rgba8UnormSrgb) => {
271:             let expected = num_pixels * 4;
272:             check_buffer_lengths(src, dst, expected, expected)?;
273:             for (s, d) in src
274:                 .as_chunks::<4>()
275:                 .0
276:                 .iter()
277:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
278:             {
279:                 d[0] = crate::transfer::linear_to_srgb_u8(s[0] as f32 / 255.0);
280:                 d[1] = crate::transfer::linear_to_srgb_u8(s[1] as f32 / 255.0);
281:                 d[2] = crate::transfer::linear_to_srgb_u8(s[2] as f32 / 255.0);
282:                 d[3] = s[3];
283:             }
284:             Ok(())
285:         }
286:         (PixelFormat::Bgra8Unorm, PixelFormat::Rgba8UnormSrgb) => {
287:             let expected = num_pixels * 4;
288:             check_buffer_lengths(src, dst, expected, expected)?;
289:             for (s, d) in src
290:                 .as_chunks::<4>()
291:                 .0
292:                 .iter()
293:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
294:             {
295:                 d[0] = crate::transfer::linear_to_srgb_u8(s[2] as f32 / 255.0);
296:                 d[1] = crate::transfer::linear_to_srgb_u8(s[1] as f32 / 255.0);
297:                 d[2] = crate::transfer::linear_to_srgb_u8(s[0] as f32 / 255.0);
298:                 d[3] = s[3];
299:             }
300:             Ok(())
301:         }
302:         (PixelFormat::Rgba8UnormSrgb, PixelFormat::Rgba8Unorm) => {
303:             let expected = num_pixels * 4;
304:             check_buffer_lengths(src, dst, expected, expected)?;
305:             for (s, d) in src
306:                 .as_chunks::<4>()
307:                 .0
308:                 .iter()
309:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
310:             {
311:                 d[0] = (crate::transfer::srgb_to_linear(s[0] as f32 / 255.0).clamp(0.0, 1.0)
312:                     * 255.0)
313:                     .round() as u8;
314:                 d[1] = (crate::transfer::srgb_to_linear(s[1] as f32 / 255.0).clamp(0.0, 1.0)
315:                     * 255.0)
316:                     .round() as u8;
317:                 d[2] = (crate::transfer::srgb_to_linear(s[2] as f32 / 255.0).clamp(0.0, 1.0)
318:                     * 255.0)
319:                     .round() as u8;
320:                 d[3] = s[3];

321:             }
322:             Ok(())
323:         }
324:         (PixelFormat::R8Unorm, PixelFormat::Rgba8Unorm) => {
325:             let expected_src = num_pixels;
326:             let expected_dst = num_pixels * 4;
327:             if src.len() < expected_src {
328:                 return Err(ConversionError::SourceBufferTooSmall {
329:                     expected: expected_src,
330:                     actual: src.len(),
331:                 });
332:             }
333:             if dst.len() < expected_dst {
334:                 return Err(ConversionError::DestinationBufferTooSmall {
335:                     expected: expected_dst,
336:                     actual: dst.len(),
337:                 });
338:             }
339:             for (s, d) in src[..expected_src]
340:                 .iter()
341:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
342:             {
343:                 d[0] = *s;
344:                 d[1] = *s;
345:                 d[2] = *s;
346:                 d[3] = 255;
347:             }
348:             Ok(())
349:         }
350:         (PixelFormat::R8Unorm, PixelFormat::Rgba8UnormSrgb) => {
351:             let expected_src = num_pixels;
352:             let expected_dst = num_pixels * 4;
353:             if src.len() < expected_src {
354:                 return Err(ConversionError::SourceBufferTooSmall {
355:                     expected: expected_src,
356:                     actual: src.len(),
357:                 });
358:             }
359:             if dst.len() < expected_dst {
360:                 return Err(ConversionError::DestinationBufferTooSmall {
361:                     expected: expected_dst,
362:                     actual: dst.len(),
363:                 });
364:             }
365:             for (s, d) in src[..expected_src]
366:                 .iter()
367:                 .zip(dst.as_chunks_mut::<4>().0.iter_mut())
368:             {
369:                 let gray = crate::transfer::linear_to_srgb_u8(*s as f32 / 255.0);
370:                 d[0] = gray;
371:                 d[1] = gray;
372:                 d[2] = gray;
373:                 d[3] = 255;
374:             }
375:             Ok(())
376:         }
377:         (PixelFormat::Rgba8Unorm, PixelFormat::Nv12) => {
378:             let expected_rgba = num_pixels * 4;
379:             let expected_y = num_pixels;
380:             let expected_uv = num_pixels / 2;
381:             if src.len() < expected_rgba {
382:                 return Err(ConversionError::SourceBufferTooSmall {
383:                     expected: expected_rgba,
384:                     actual: src.len(),
385:                 });
386:             }
387:             if dst.len() < expected_y + expected_uv {
388:                 return Err(ConversionError::DestinationBufferTooSmall {
389:                     expected: expected_y + expected_uv,
390:                     actual: dst.len(),
391:                 });
392:             }
393:             let (y_dst, uv_dst) = dst.split_at_mut(expected_y);
394:             yuv::rgba8_to_nv12(
395:                 src,
396:                 width,
397:                 height,
398:                 YuvStandard::Bt709,
399:                 YuvRange::Full,
400:                 y_dst,
401:                 uv_dst,
402:             );
403:             Ok(())
404:         }
405:         _ => Err(ConversionError::UnsupportedFormatConversion {
406:             src: src_format,
407:             dst: dst_format,
408:         }),
409:     }
410: }
411: 
412: fn check_buffer_lengths(
413:     src: &[u8],
414:     dst: &[u8],
415:     expected_src: usize,
416:     expected_dst: usize,
417: ) -> Result<(), ConversionError> {
418:     if src.len() < expected_src {
419:         return Err(ConversionError::SourceBufferTooSmall {
420:             expected: expected_src,
421:             actual: src.len(),
422:         });
423:     }
424:     if dst.len() < expected_dst {
425:         return Err(ConversionError::DestinationBufferTooSmall {
426:             expected: expected_dst,
427:             actual: dst.len(),
428:         });
429:     }
430:     Ok(())
431: }
