437:     #[test]
438:     fn test_srgb_to_display_p3() {
439:         // Red in sRGB is inside Display P3, so its colorimetric transformation
440:         // should yield high red with minor adjustments in P3.
441:         let srgb_red = [1.0, 0.0, 0.0];
442:         let p3_color = convert_color(srgb_red, ColorSpace::Srgb, ColorSpace::DisplayP3);
443:         // In Display P3, sRGB red has approx [0.92, 0.20, 0.14] coordinates
444:         assert!(p3_color[0] > 0.85 && p3_color[0] < 0.98);
445:         assert!(p3_color[1] > 0.10 && p3_color[1] < 0.30);
446:         assert!(p3_color[2] > 0.05 && p3_color[2] < 0.25);
447:     }
