  6: /// CIE 1931 xy chromaticity coordinates.
  7: #[derive(Debug, Clone, Copy, PartialEq)]
  8: #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
  9: pub struct Chromaticity {
 10:     pub x: f64,
 11:     pub y: f64,
 12: }
 13: 
 14: impl Chromaticity {
 15:     pub const fn new(x: f64, y: f64) -> Self {
 16:         Self { x, y }
 17:     }
 18: 
 19:     /// Converts chromaticity to XYZ tristimulus values given luminance Y (typically 1.0).
 20:     pub fn to_xyz(&self, y_lum: f64) -> [f64; 3] {
 21:         if self.y.abs() < 1e-12 {
 22:             [0.0, 0.0, 0.0]
 23:         } else {
 24:             let x = (self.x / self.y) * y_lum;
 25:             let z = ((1.0 - self.x - self.y) / self.y) * y_lum;
 26:             [x, y_lum, z]
 27:         }
 28:     }
 29: }
