 31: /// Standard CIE Illuminants / White Points.
 32: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
 33: #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
 34: pub enum WhitePoint {
 35:     /// CIE Standard Illuminant D65 (daylight, ~6504 K). Standard for sRGB, BT.709, Display P3, BT.2020.
 36:     #[default]
 37:     D65,
 38:     /// CIE Standard Illuminant D50 (horizon daylight, ~5003 K). Standard for printing, ICC profiles, Adobe Photoshop.
 39:     D50,
 40:     /// CIE Illuminant D60 (~6000 K). Standard for ACES.
 41:     D60,
 42:     /// DCI-P3 theatrical white point (~6300 K).
 43:     Dci,
 44:     /// CIE Standard Illuminant A (incandescent tungsten, ~2856 K).
 45:     A,
 46:     /// CIE Standard Illuminant C (average daylight, ~6774 K).
 47:     C,
 48:     /// Equal-energy radiator illuminant E (x = 1/3, y = 1/3).
 49:     E,
 50: }
 51: 
 52: impl WhitePoint {
 53:     /// CIE 1931 (x, y) coordinates for this white point.
 54:     pub const fn chromaticity(&self) -> Chromaticity {
 55:         match self {
 56:             Self::D65 => Chromaticity::new(0.3127, 0.3290),
 57:             Self::D50 => Chromaticity::new(0.34567, 0.35850),
 58:             Self::D60 => Chromaticity::new(0.32168, 0.33767),
 59:             Self::Dci => Chromaticity::new(0.314, 0.351),
 60:             Self::A => Chromaticity::new(0.44757, 0.40745),
 61:             Self::C => Chromaticity::new(0.31006, 0.31616),
 62:             Self::E => Chromaticity::new(1.0 / 3.0, 1.0 / 3.0),
 63:         }
 64:     }
 65: 
 66:     /// Normalized CIE XYZ tristimulus coordinates where Y = 1.0.
 67:     pub fn xyz(&self) -> [f64; 3] {
 68:         self.chromaticity().to_xyz(1.0)
 69:     }
 70: }
