233: #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
234: pub enum ColorSpace {
235:     /// sRGB with IEC 61966-2-1 transfer curve and BT.709 primaries.
236:     #[default]
237:     Srgb,
238:     /// Linear sRGB (BT.709 primaries, linear light).
239:     LinearSrgb,
240:     /// Display P3 (DCI-P3 primaries, D65 white point, sRGB transfer curve).
241:     DisplayP3,
242:     /// Linear Display P3 (DCI-P3 primaries, D65 white point, linear light).
243:     LinearDisplayP3,
244:     /// ITU-R BT.709 (HDTV color space).
245:     Bt709,
246:     /// ITU-R BT.2020 (UHDTV wide-gamut color space with BT.2020 transfer curve).
247:     Bt2020,
248:     /// Linear ITU-R BT.2020 (BT.2020 primaries, linear light).
249:     LinearBt2020,
