260: impl ColorSpace {
261:     /// Chromaticity primaries and white point for this color space.
262:     pub const fn primaries(&self) -> ColorPrimaries {
263:         match self {
264:             Self::Srgb | Self::LinearSrgb | Self::Bt709 => ColorPrimaries::BT709,
265:             Self::DisplayP3 | Self::LinearDisplayP3 => ColorPrimaries::DISPLAY_P3,
266:             Self::Bt2020 | Self::LinearBt2020 => ColorPrimaries::BT2020,
267:             Self::DciP3 => ColorPrimaries::DCI_P3,
268:             Self::AdobeRgb => ColorPrimaries::ADOBE_RGB,
269:             Self::AcesCg => ColorPrimaries::ACES_CG,
270:             Self::Aces2065_1 => ColorPrimaries::ACES_2065_1,
271:         }
272:     }
273: 
274:     /// Reference white point for this color space.
275:     pub const fn white_point(&self) -> WhitePoint {
276:         self.primaries().white
277:     }
278: 
279:     /// Non-linear transfer function (EOTF) for this color space.
280:     pub const fn transfer_function(&self) -> TransferFunction {
281:         match self {
282:             Self::Srgb | Self::DisplayP3 => TransferFunction::Srgb,
283:             Self::LinearSrgb
284:             | Self::LinearDisplayP3
285:             | Self::LinearBt2020
286:             | Self::AcesCg
287:             | Self::Aces2065_1 => TransferFunction::Linear,
288:             Self::Bt709 | Self::Bt2020 => TransferFunction::Bt709,
289:             Self::DciP3 => TransferFunction::Dci,
290:             Self::AdobeRgb => TransferFunction::Gamma22,
291:         }
292:     }
293: 
294:     /// Converts this color space to its linear light variant.
295:     pub const fn to_linear_space(&self) -> Self {
296:         match self {
297:             Self::Srgb | Self::LinearSrgb | Self::Bt709 => Self::LinearSrgb,
298:             Self::DisplayP3 | Self::LinearDisplayP3 => Self::LinearDisplayP3,
299:             Self::Bt2020 | Self::LinearBt2020 => Self::LinearBt2020,
300:             _ => *self,
301:         }
302:     }
303: 
304:     /// Converts this color space to its gamma / encoded variant.
305:     pub const fn to_gamma_space(&self) -> Self {
306:         match self {
307:             Self::LinearSrgb | Self::Srgb => Self::Srgb,
308:             Self::LinearDisplayP3 | Self::DisplayP3 => Self::DisplayP3,
309:             Self::LinearBt2020 | Self::Bt2020 => Self::Bt2020,
310:             _ => *self,
311:         }
312:     }
313: }
