  4: /// Transfer function characteristics (EOTF / OETF) describing how linear light
  5: /// is encoded into non-linear digital signal values and vice versa.
  6: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
  7: #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
  8: pub enum TransferFunction {
  9:     /// Linear light (identity mapping).
 10:     #[default]
 11:     Linear,
 12:     /// IEC 61966-2-1 standard sRGB transfer curve.
 13:     Srgb,
 14:     /// ITU-R BT.709 transfer curve.
 15:     Bt709,
 16:     /// Perceptual Quantizer (SMPTE ST 2084 / HDR10).
 17:     Pq,
 18:     /// Hybrid Log-Gamma (ITU-R BT.2100 / ARIB STD-B67).
 19:     Hlg,
 20:     /// Pure power-law gamma 2.2.
 21:     Gamma22,
 22:     /// Pure power-law gamma 2.8.
 23:     Gamma28,
 24:     /// DCI-P3 theatrical gamma 2.6.
 25:     Dci,
 26: }
 27: 
 28: impl TransferFunction {
 29:     /// Converts a non-linear encoded value in `[0.0, 1.0]` to linear light.
 30:     #[inline]
 31:     pub fn to_linear(&self, encoded: f32) -> f32 {
 32:         match self {
 33:             Self::Linear => encoded,
 34:             Self::Srgb => srgb_to_linear(encoded),
 35:             Self::Bt709 => bt709_to_linear(encoded),
 36:             Self::Pq => pq_to_linear(encoded),
 37:             Self::Hlg => hlg_to_linear(encoded),
 38:             Self::Gamma22 => {
 39:                 if encoded <= 0.0 {
 40:                     0.0
 41:                 } else {
 42:                     encoded.powf(2.2)
 43:                 }
 44:             }
 45:             Self::Gamma28 => {
 46:                 if encoded <= 0.0 {
 47:                     0.0
 48:                 } else {
 49:                     encoded.powf(2.8)
 50:                 }
 51:             }
 52:             Self::Dci => {
 53:                 if encoded <= 0.0 {
 54:                     0.0
 55:                 } else {
 56:                     encoded.powf(2.6)
 57:                 }
 58:             }
 59:         }
 60:     }
 61: 
 62:     /// Converts a linear light value in `[0.0, 1.0]` (or higher for HDR) to encoded signal.
 63:     #[inline]
 64:     pub fn from_linear(&self, linear: f32) -> f32 {
 65:         match self {
 66:             Self::Linear => linear,
 67:             Self::Srgb => linear_to_srgb(linear),
 68:             Self::Bt709 => linear_to_bt709(linear),
 69:             Self::Pq => linear_to_pq(linear),
 70:             Self::Hlg => linear_to_hlg(linear),
 71:             Self::Gamma22 => {
 72:                 if linear <= 0.0 {
 73:                     0.0
 74:                 } else {
 75:                     linear.powf(1.0 / 2.2)
 76:                 }
 77:             }
 78:             Self::Gamma28 => {
 79:                 if linear <= 0.0 {
 80:                     0.0
 81:                 } else {
 82:                     linear.powf(1.0 / 2.8)
 83:                 }
 84:             }
 85:             Self::Dci => {
 86:                 if linear <= 0.0 {
 87:                     0.0
 88:                 } else {
 89:                     linear.powf(1.0 / 2.6)
 90:                 }
 91:             }
 92:         }
 93:     }
 94: 
 95:     /// Converts an RGB triplet from encoded to linear space.
 96:     #[inline]
 97:     pub fn to_linear_rgb(&self, rgb: [f32; 3]) -> [f32; 3] {
 98:         [
 99:             self.to_linear(rgb[0]),
100:             self.to_linear(rgb[1]),
101:             self.to_linear(rgb[2]),
102:         ]
103:     }
104: 
105:     /// Converts an RGB triplet from linear to encoded space.
106:     #[inline]
107:     pub fn from_linear_rgb(&self, rgb: [f32; 3]) -> [f32; 3] {
108:         [
109:             self.from_linear(rgb[0]),
110:             self.from_linear(rgb[1]),
111:             self.from_linear(rgb[2]),
112:         ]
113:     }
114: }
