117: // Standalone Transfer Functions
118: // -----------------------------------------------------------------------------
119: 
120: /// Converts an sRGB encoded value in `[0.0, 1.0]` to linear light.
121: #[inline]
122: pub fn srgb_to_linear(encoded: f32) -> f32 {
123:     if encoded <= 0.04045 {
124:         encoded / 12.92
125:     } else {
126:         ((encoded + 0.055) / 1.055).powf(2.4)
127:     }
128: }
129: 
130: /// Converts a linear light value in `[0.0, 1.0]` to sRGB encoded value.
131: #[inline]
132: pub fn linear_to_srgb(linear: f32) -> f32 {
133:     if linear <= 0.0031308 {
134:         linear * 12.92
135:     } else {
136:         1.055 * linear.powf(1.0 / 2.4) - 0.055
137:     }
138: }
139: 
140: /// Fast conversion from linear light `[0.0, 1.0]` to sRGB 8-bit integer `[0, 255]`.

141: #[inline]
142: pub fn linear_to_srgb_u8(linear: f32) -> u8 {
143:     let srgb = linear_to_srgb(linear);
144:     (srgb.clamp(0.0, 1.0) * 255.0).round() as u8
145: }
146: 
147: /// Converts a BT.709 encoded value in `[0.0, 1.0]` to linear light.
148: #[inline]
149: pub fn bt709_to_linear(encoded: f32) -> f32 {
150:     if encoded < 0.081 {
151:         encoded / 4.5
152:     } else {
153:         ((encoded + 0.099) / 1.099).powf(1.0 / 0.45)
154:     }
155: }
156: 
157: /// Converts a linear light value in `[0.0, 1.0]` to BT.709 encoded value.
158: #[inline]
159: pub fn linear_to_bt709(linear: f32) -> f32 {
160:     if linear < 0.018 {
161:         4.5 * linear
162:     } else {
163:         1.099 * linear.powf(0.45) - 0.099
164:     }
165: }
166: 
167: // SMPTE ST 2084 (Perceptual Quantizer / PQ) constants
168: const PQ_M1: f32 = 2610.0 / 16384.0;
169: const PQ_M2: f32 = (2523.0 / 4096.0) * 128.0;
170: const PQ_C1: f32 = 3424.0 / 4096.0;
171: const PQ_C2: f32 = (2413.0 / 4096.0) * 32.0;
172: const PQ_C3: f32 = (2392.0 / 4096.0) * 32.0;
173: 
174: /// Converts a PQ (SMPTE ST 2084) encoded value to normalized linear light [0.0, 1.0]
175: /// where 1.0 represents 10,000 cd/m² (nits).
176: #[inline]
177: pub fn pq_to_linear(encoded: f32) -> f32 {
178:     if encoded <= 0.0 {
179:         return 0.0;
180:     }
181:     let vp = encoded.clamp(0.0, 1.0).powf(1.0 / PQ_M2);
182:     let num = (vp - PQ_C1).max(0.0);
183:     let den = PQ_C2 - PQ_C3 * vp;
184:     if den <= 0.0 {
185:         1.0
186:     } else {
187:         (num / den).powf(1.0 / PQ_M1)
188:     }
189: }
190: 
191: /// Converts normalized linear light [0.0, 1.0] (where 1.0 is 10,000 nits)
192: /// to a PQ (SMPTE ST 2084) encoded value in [0.0, 1.0].
193: #[inline]
194: pub fn linear_to_pq(linear: f32) -> f32 {
195:     if linear <= 0.0 {
196:         return 0.0;
197:     }
198:     let yp = linear.clamp(0.0, 1.0).powf(PQ_M1);
199:     let num = PQ_C1 + PQ_C2 * yp;
200:     let den = 1.0 + PQ_C3 * yp;
201:     (num / den).powf(PQ_M2)
202: }
203: 
204: // ARIB STD-B67 / BT.2100 (HLG) constants
205: const HLG_A: f32 = 0.17883277;
206: const HLG_B: f32 = 0.28466892; // 1.0 - 4.0 * HLG_A
207: const HLG_C: f32 = 0.559_910_7; // 0.5 - HLG_A * (4.0 * HLG_A).ln()
208: 
209: /// Converts an HLG (ITU-R BT.2100) encoded value in [0.0, 1.0] to normalized linear scene light.
210: #[inline]
211: pub fn hlg_to_linear(encoded: f32) -> f32 {
212:     let e = encoded.clamp(0.0, 1.0);
213:     if e <= 0.5 {
214:         (e * e) / 3.0
215:     } else {
216:         (((e - HLG_C) / HLG_A).exp() + HLG_B) / 12.0
217:     }
218: }
219: 
220: /// Converts normalized linear scene light in [0.0, 1.0] to an HLG encoded value in [0.0, 1.0].
221: #[inline]
222: pub fn linear_to_hlg(linear: f32) -> f32 {
223:     let l = linear.max(0.0);
224:     if l <= (1.0 / 12.0) {
225:         (3.0 * l).sqrt()
226:     } else {
227:         HLG_A * (12.0 * l - HLG_B).ln() + HLG_C
228:     }
229: }
