184: // The float nearest a double-float.
185: fn df_round(a: vec2<f32>) -> f32 {
186:     return host_add(a.x, a.y);
187: }
188: 
189: // `2^n` for the exponents of normal floats.
190: fn df_power_of_two(n: i32) -> f32 {
191:     return bitcast<f32>(u32(n + 127) << 23u);
192: }
193: "#;
194: 
195: /// Sine, cosine, arcsine, logarithm, exponential and power.
196: const FUNCTIONS: &str = r#"
197: // `x` less its nearest multiple k of a quarter turn, and k. Each part of the
198: // quarter turn times k is exact as a double-float.
199: fn df_quarter_turns(x: f32) -> vec3<f32> {
200:     let k = round(host_mul(x, DF_TWO_OVER_PI));
201:     var r = df_add(vec2<f32>(x, 0.0), df_two_product(DF_QUARTER_TURN_0, -k));
202:     r = df_add(r, df_two_product(DF_QUARTER_TURN_1, -k));
203:     r = df_add(r, df_two_product(DF_QUARTER_TURN_2, -k));
204:     r = df_add(r, df_two_product(DF_QUARTER_TURN_3, -k));
205:     return vec3<f32>(r, k);
206: }
207: 
208: // sin (`odd`) or cos of `x`, unrounded.
209: fn df_sin_or_cos(x: f32, odd: bool) -> vec2<f32> {
210:     let reduced = df_quarter_turns(x);
211:     let r = reduced.xy;
212:     let quadrant = i32(reduced.z) & 3;
213:     // An odd quadrant swaps sine and cosine.
214:     let sine = odd != ((quadrant & 1) == 1);
215:     let z = df_mul(r, r);
216:     var value = df_cosine_series(z);
217:     if (sine) {
218:         value = df_mul(r, df_sine_series(z));
219:     }
220:     // Sine is negative in quadrants 2 and 3, cosine in 1 and 2.
221:     let negative = select(quadrant == 1 || quadrant == 2, quadrant >= 2, odd);
222:     return select(value, -value, negative);
223: }
224: 
225: fn host_sin(x: f32) -> f32 {
226:     // Keeps the sign of a zero.
227:     if (x == 0.0) {
228:         return x;
229:     }
230:     return df_round(df_sin_or_cos(x, true));
231: }
232: 
233: fn host_cos(x: f32) -> f32 {
234:     return df_round(df_sin_or_cos(x, false));
235: }
236: 
237: // (sin x, cos x).
238: fn host_sin_cos(x: f32) -> vec2<f32> {
239:     return vec2<f32>(host_sin(x), host_cos(x));
240: }
241: 
242: // asin of x in [-1, 1]: one Newton step from the device's estimate, its
243: // residual sin(estimate) - x taken in double-float.
244: fn host_asin(x: f32) -> f32 {
245:     if (abs(x) == 1.0) {
246:         return select(-DF_QUARTER_TURN_0, DF_QUARTER_TURN_0, x > 0.0);
247:     }
248:     let estimate = asin(x);
249:     let c = host_cos(estimate);
250:     if (!(c > 0.0) || !(abs(x) < 1.0)) {
251:         return estimate;
252:     }
253:     let residual = df_add_f32(df_sin_or_cos(estimate, true), -x);
254:     let correction = host_div(df_round(residual), c);
255:     return df_round(df_two_sum(estimate, -correction));
256: }
257: 
258: // The natural logarithm of a positive normal float.
259: fn df_log(x: f32) -> vec2<f32> {
260:     // x = m 2^n with m within a factor sqrt 2 of one.
261:     let bits = bitcast<u32>(x);
262:     var n = i32((bits >> 23u) & 0xffu) - 127;
263:     var m = bitcast<f32>((bits & 0x007fffffu) | 0x3f800000u);
264:     if (m > 1.41421356f) {
265:         m = m * 0.5;
266:         n = n + 1;
267:     }
268:     // log m = 2 atanh t, t = (m - 1) / (m + 1).
269:     let t = df_div(vec2<f32>(host_sub(m, 1.0), 0.0), df_two_sum(m, 1.0));
270:     let log_m = df_mul(t, df_atanh_series(df_mul(t, t)));
271:     // n ln 2, its first two parts exact as double-floats.
272:     let e = f32(n);
273:     let log_2n = df_add(df_two_product(DF_LN_2_0, e), df_two_product(DF_LN_2_1, e));
274:     return df_add(df_add_f32(log_2n, host_mul(DF_LN_2_2, e)), log_m);
275: }
276: 
277: // Beyond these, e to the power over- or underflows a float.
278: const DF_EXP_UNDERFLOW: f32 = -104.0f;
279: const DF_EXP_OVERFLOW: f32 = 89.0f;
280: 
281: // e to a double-float power, rounded once.
282: fn df_exp_rounded(y: vec2<f32>) -> f32 {
283:     if (y.x < DF_EXP_UNDERFLOW) {
284:         return 0.0;
285:     }
286:     if (y.x > DF_EXP_OVERFLOW) {
287:         return bitcast<f32>(0x7f800000u | host_zero());
288:     }
289:     // y = k ln 2 + r, |r| <= ln 2 / 2.
290:     let k = round(host_mul(y.x, DF_LOG2_E));
291:     var r = df_add(y, df_two_product(DF_LN_2_0, -k));
292:     r = df_add(r, df_two_product(DF_LN_2_1, -k));
293:     r = df_add_f32(r, host_mul(DF_LN_2_2, -k));
294:     let scaled = df_round(df_exp_series(r));
295:     // 2^k in two factors, neither of which overflows.
296:     let half = i32(k) / 2;
297:     return host_mul(host_mul(scaled, df_power_of_two(half)), df_power_of_two(i32(k) - half));
298: }
299: 
300: // The natural logarithm of a positive normal float; log 0 is -infinity,
301: // and a negative argument NaN.
302: fn host_log(x: f32) -> f32 {
303:     if (x == 0.0) {
304:         return -bitcast<f32>(0x7f800000u | host_zero());
305:     }
306:     if (!(x > 0.0) || !(x <= HOST_FLOAT_MAX)) {
307:         return log(x);
308:     }
309:     return df_round(df_log(x));
310: }
311: 
312: fn host_exp(x: f32) -> f32 {
313:     // NaN, tested on its bits: a compiler may take `x != x` to be false.
314:     if ((bitcast<u32>(x) & 0x7fffffffu) > 0x7f800000u) {
315:         return x;
316:     }
317:     return df_exp_rounded(vec2<f32>(x, 0.0));
318: }
319: 
320: // `base` to the `exponent`, for a positive normal base. Any exponent of
321: // zero and a base of one give one; a base of zero -- or any other
322: // non-positive base -- gives zero, as the host's `powf` does for zero to a
323: // positive exponent.
324: fn host_pow(base: f32, exponent: f32) -> f32 {
325:     if (exponent == 0.0 || base == 1.0) {
326:         return 1.0;
327:     }
328:     if (!(base > 0.0)) {
329:         return 0.0;
330:     }
331:     return df_exp_rounded(df_mul_f32(df_log(base), exponent));
332: }
