 12: impl Words {
 13:     fn next(&mut self) -> u64 {
 14:         self.0 ^= self.0 << 13;
 15:         self.0 ^= self.0 >> 7;
 16:         self.0 ^= self.0 << 17;
 17:         self.0
 18:     }
 19: 
 20:     /// Uniform in `[low, high)`.
 21:     fn uniform(&mut self, low: f32, high: f32) -> f32 {
 22:         let unit = (self.next() >> 40) as f32 / (1u64 << 24) as f32;
 23:         low + (high - low) * unit
 24:     }
 25: 
 26:     /// A normal float of either sign whose exponent lies in `exponents`,
 27:     /// every significand equally likely.
 28:     fn normal(&mut self, exponents: std::ops::RangeInclusive<i32>) -> f32 {
 29:         let word = self.next();
 30:         let span = (exponents.end() - exponents.start() + 1) as u64;
 31:         let exponent = exponents.start() + ((word >> 32) % span) as i32;
 32:         let bits = ((word & 1) << 31) as u32
 33:             | ((exponent + 127) as u32) << 23
 34:             | (word >> 8) as u32 & 0x007f_ffff;
 35:         f32::from_bits(bits)
 36:     }
 37: }
