 40: /// input -- on the device, returning each input's results in order.
 41: async fn run(inputs: &[[f32; 4]], expressions: &[&str]) -> Result<Vec<f32>> {
 42:     let context = WgpuContext::new().await?;
 43:     let stores: String = expressions
 44:         .iter()
 45:         .enumerate()
 46:         .map(|(k, expression)| {
 47:             format!(
 48:                 "    outputs[i * {}u + {k}u] = {expression};\n",
 49:                 expressions.len()
 50:             )
 51:         })
 52:         .collect();
 53:     let source = format!(
 54:         r#"
 55: @group(0) @binding(0) var<storage, read> inputs: array<vec4<f32>>;
 56: @group(0) @binding(1) var<storage, read_write> outputs: array<f32>;
 57: struct Params {{ count: u32, zero: u32, pad0: u32, pad1: u32 }};
 58: @group(0) @binding(2) var<uniform> params: Params;
 59: {PARAMS_ZERO_HOOK}
 60: {library}
 61: @compute @workgroup_size(64)
 62: fn main(@builtin(global_invocation_id) id: vec3<u32>) {{
 63:     let i = id.x;
 64:     if (i >= params.count) {{
 65:         return;
 66:     }}
 67:     let a = inputs[i].x;
 68:     let b = inputs[i].y;
 69:     let c = inputs[i].z;
 70:     let d = inputs[i].w;
