 98: /// How many results differ from `expected` in any bit, per expression.
 99: fn mismatches(
100:     inputs: &[[f32; 4]],
101:     device: &[f32],
102:     expected: impl Fn([f32; 4]) -> Vec<f32>,
103: ) -> Vec<usize> {
104:     let mut counts = Vec::new();
105:     for (input, results) in inputs
106:         .iter()
107:         .zip(device.chunks(device.len() / inputs.len()))
108:     {
109:         let expected = expected(*input);
110:         counts.resize(expected.len(), 0);
111:         for (k, (got, want)) in results.iter().zip(expected).enumerate() {
112:             // NaNs of any payload agree.
113:             counts[k] +=
114:                 usize::from(got.to_bits() != want.to_bits() && !(got.is_nan() && want.is_nan()));
115:         }
116:     }
117:     counts
118: }
