162: impl FastPath {
163:     /// Build a fast path for this kernel, or `None` if its shape does not
164:     /// suit one.
165:     pub(super) fn new(
166:         context: &WgpuContext,
167:         module: &wgpu::ShaderModule,
168:         entry_point: &str,
169:         reflection: &fabelgeist_gpu::data::gpu::shader::ReflectionData,
170:     ) -> Result<Option<Self>> {
171:         // One bind group only. Everything the solver writes uses group 0, and
172:         // supporting more would mean a dynamic offset per group.
173:         if reflection.bind_groups.len() != 1 {
174:             return Ok(None);
175:         }
176:         let group = &reflection.bind_groups[0];
177:         if group.index != 0 {
178:             return Ok(None);
179:         }
180:         // Textures and samplers would each need their own cache key and their
181:         // own lifetime handling; nothing on the solver path uses them.
182:         if !group.texture_bindings.is_empty() || !group.sampler_bindings.is_empty() {
183:             return Ok(None);
184:         }
185: 
186:         let mut entries: Vec<wgpu::BindGroupLayoutEntry> = group
187:             .buffer_bindings
188:             .iter()
189:             .map(|binding| wgpu::BindGroupLayoutEntry {
190:                 binding: binding.binding,
191:                 visibility: wgpu::ShaderStages::COMPUTE,
192:                 ty: wgpu::BindingType::Buffer {
193:                     ty: binding.ty,
194:                     has_dynamic_offset: false,
195:                     min_binding_size: None,
196:                 },
197:                 count: None,
198:             })
199:             .collect();
200: 
201:         let uniform_size = group.uniform_buffer_size as u64;
202:         if uniform_size as usize > MAX_UNIFORM_BYTES {
203:             return Ok(None);
204:         }
205:         let uniform_binding = group.uniform_binding.filter(|_| uniform_size > 0);
206:         if let Some(binding) = uniform_binding {
207:             entries.push(wgpu::BindGroupLayoutEntry {
208:                 binding,
209:                 visibility: wgpu::ShaderStages::COMPUTE,
210:                 ty: wgpu::BindingType::Buffer {
211:                     ty: wgpu::BufferBindingType::Uniform,
212:                     // The whole point: one buffer, one bind group, and the
213:                     // per-dispatch values selected by offset.
214:                     has_dynamic_offset: true,
215:                     min_binding_size: std::num::NonZeroU64::new(uniform_size),
216:                 },
217:                 count: None,
218:             });
219:         }
220:         entries.sort_by_key(|entry| entry.binding);
221: 
222:         let compiled = CompiledLayout::new(context, &entries, module, entry_point)?;
223: 
224:         let alignment = context.device.limits().min_uniform_buffer_offset_alignment as u64;
225:         let stride = uniform_size.div_ceil(alignment.max(1)) * alignment.max(1);
226: 
227:         Ok(Some(Self {
228:             pipeline: compiled.pipeline,
229:             layout: compiled.layout,
230:             buffers: group.buffer_bindings.clone(),
231:             uniform_binding,
232:             uniform_members: group.uniform_members.clone(),
233:             uniform_size,
234:             stride,
235:         }))
236:     }
237: 
238:     /// Resolve the bind group and write this dispatch's uniform values.
239:     pub(super) fn prepare(
240:         &self,
241:         context: &WgpuContext,
242:         parameters: &PassParameters,
243:         uniforms: &mut UniformArena,
244:     ) -> Result<Prepared> {
245:         let slot = (self.uniform_binding.is_some() && self.uniform_size > 0)
246:             .then(|| uniforms.allocate(context, self.stride));
247:         // Built fresh every dispatch. See the note at the top of this file:
248:         // reusing one costs wgpu the barrier between dependent passes.
249:         let mut entries: Vec<wgpu::BindGroupEntry> = Vec::with_capacity(self.buffers.len() + 1);
250:         let mut bound: Vec<(u32, Buffer)> = Vec::with_capacity(self.buffers.len());
251:         for binding in &self.buffers {
252:             let Some(PassParameter::Buffer(buffer)) = parameters.get(&binding.name) else {
253:                 return Err(anyhow!(
254:                     "Kernel: parameter `{}` (binding {}) is missing or is not a buffer",
255:                     binding.name,
256:                     binding.binding
257:                 ));
258:             };
259:             bound.push((binding.binding, buffer.clone()));
260:         }
261: 
262:         for (binding, buffer) in &bound {
263:             entries.push(wgpu::BindGroupEntry {
264:                 binding: *binding,
265:                 resource: if u64::from(buffer.size) < buffer.buffer.size() {
266:                     wgpu::BindingResource::Buffer(wgpu::BufferBinding {
267:                         buffer: &buffer.buffer,
268:                         offset: 0,
269:                         size: std::num::NonZeroU64::new(u64::from(buffer.size)),
270:                     })
271:                 } else {
272:                     buffer.buffer.as_entire_binding()
273:                 },
274:             });
275:         }
276:         if let (Some(binding), Some((chunk, _))) = (self.uniform_binding, &slot) {
277:             entries.push(wgpu::BindGroupEntry {
278:                 binding,
279:                 resource: wgpu::BindingResource::Buffer(wgpu::BufferBinding {
280:                     buffer: chunk,
281:                     offset: 0,
282:                     size: std::num::NonZeroU64::new(self.uniform_size),
283:                 }),
284:             });
285:         }
286:         entries.sort_by_key(|entry| entry.binding);
287: 
288:         let bind_group = context
289:             .device
290:             .create_bind_group(&wgpu::BindGroupDescriptor {

291:                 label: Some("Kernel Bind Group"),
292:                 layout: &self.layout,
293:                 entries: &entries,
294:             });
295: 
296:         let dynamic_offset = match &slot {
297:             None => None,
298:             Some((chunk, offset)) => {
299:                 let offset = *offset;
300:                 // A uniform block is a handful of words, so it is packed on
301:                 // the stack rather than allocated per dispatch.
302:                 let mut data = [0u8; MAX_UNIFORM_BYTES];
303:                 let size = self.uniform_size as usize;
304:                 let data = &mut data[..size];
305:                 data.fill(0);
306:                 write_uniform(&self.uniform_members, parameters, data)?;
307:                 context.queue.write_buffer(chunk, offset, data);
308:                 Some(offset as u32)
309:             }
310:         };
311: 
312:         Ok(Prepared {
313:             pipeline: self.pipeline.clone(),
314:             bind_group,
315:             dynamic_offset,
316:         })
317:     }
318: }
319: 
320: /// Pack the uniform block from named parameters, by reflected offsets.
321: ///
322: /// Covers the scalar, vector and matrix kinds a solver passes. Anything else
323: /// is reported rather than silently skipped -- a uniform quietly left at zero
324: /// is a wrong simulation, not an error, and those are the expensive ones.
325: fn write_uniform(
326:     members: &[UniformMember],
327:     parameters: &PassParameters,
328:     out: &mut [u8],
329: ) -> Result<()> {
330:     for member in members {
331:         let Some(value) = parameters.get(&member.name) else {
332:             return Err(anyhow!(
333:                 "Kernel: uniform `{}` was not supplied",
334:                 member.name
335:             ));
336:         };
337:         let offset = member.offset as usize;
338: 
339:         let mut put = |values: &[f32]| {
340:             let end = offset + values.len() * 4;
341:             if end <= out.len() {
342:                 for (index, value) in values.iter().enumerate() {
343:                     out[offset + index * 4..offset + index * 4 + 4]
344:                         .copy_from_slice(&value.to_le_bytes());
345:                 }
346:             }
347:         };
348: 
349:         match value {
350:             PassParameter::Number(n) => put(&[*n as f32]),
351:             PassParameter::Unsigned(u) => {
352:                 if offset + 4 <= out.len() {
353:                     out[offset..offset + 4].copy_from_slice(&u.to_le_bytes());
354:                 }
355:             }
356:             PassParameter::Vec2(v) => put(&[v.x, v.y]),
357:             PassParameter::Vec3(v) => put(&[v.x, v.y, v.z]),
358:             PassParameter::Vec4(v) => put(&[v.x, v.y, v.z, v.w]),
359:             PassParameter::Mat4(m) => {
360:                 let mut values = Vec::with_capacity(16);
361:                 for column in 0..4 {
362:                     for row in 0..4 {
363:                         values.push(m.columns[column][row]);
364:                     }
365:                 }
366:                 put(&values);
367:             }
368:             other => {
369:                 return Err(anyhow!(
370:                     "Kernel: uniform `{}` is a {:?}, which the cached dispatch path does not pack; \
371:                      use ComputePass::record for this kernel",
372:                     member.name,
373:                     std::mem::discriminant(other)
374:                 ));
375:             }
376:         }
377:     }
378:     Ok(())
379: }

  1: //! A raw compute kernel, and a batch that records many of them into one submit.
  2: //!
  3: //! The other primitives in this module each impose a shape: `Map` is one input
  4: //! to one output, `Reduce` folds, `Stencil` walks a neighbourhood. A solver
  5: //! does not fit any of them -- an XPBD constraint projection reads positions,
  6: //! inverse masses, rest lengths and a constraint list, and writes back into
  7: //! positions and Lagrange multipliers, all in one pass. So this is the escape
  8: //! hatch: hand it WGSL with named storage buffers and it binds them by name,
  9: //! using the same reflection [`ComputePipeline`] already does for every other
 10: //! primitive.
 11: //!
 12: //! The second half matters more than the first. Every other primitive here
 13: //! calls [`ComputePass::dispatch`], which finishes an encoder and submits it. A
 14: //! cloth step is hundreds of dispatches (substeps x constraint colours), and
 15: //! hundreds of submits per frame is a lost frame. [`KernelBatch`] records into
 16: //! a single encoder and submits once.
 17: 
 18: mod fast;
 19: 
 20: use crate::prelude::*;
 21: use std::collections::HashMap;
 22: use std::sync::{Arc, RwLock};
 23: 
 24: // Validation scopes on one device must not interleave during compilation.
 25: static COMPILING: std::sync::Mutex<()> = std::sync::Mutex::new(());
 26: 
 27: /// The most workgroups one dispatch dimension may hold.
 28: pub const MAX_GROUPS: u32 = 65_535;
 29: 
 30: /// The flat item index of an invocation dispatched by
 31: /// [`KernelBatch::dispatch_folded`], given its `global_invocation_id`, its
 32: /// `num_workgroups` and the kernel's workgroup width.
 33: pub const FOLDED_INDEX_WGSL: &str = r#"
 34: fn folded_index(id: vec3<u32>, groups: vec3<u32>, width: u32) -> u32 {
 35:     return id.y * groups.x * width + id.x;
 36: }
 37: "#;
 38: 
 39: /// A compiled compute kernel: the pipeline plus the workgroup size declared in
 40: /// its own source, so that a dispatch can be sized in *items* rather than in
 41: /// workgroups.
 42: pub struct Kernel {
 43:     pub pipeline: ComputePipeline,
 44:     pub workgroup_size: [u32; 3],
 45:     pub entry_point: String,
 46:     /// The cached dispatch path, when this kernel's shape allows one.
 47:     ///
 48:     /// Without it every dispatch builds a uniform buffer and a bind group,
 49:     /// which a solver making hundreds of dispatches a frame cannot afford --
 50:     /// in CPU time or, run at speed, in allocations. See [`fast`].
 51:     fast: Option<fast::FastPath>,
 52: }
 53: 
 54: impl std::fmt::Debug for Kernel {
 55:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 56:         f.debug_struct("Kernel")
 57:             .field("entry_point", &self.entry_point)
 58:             .field("workgroup_size", &self.workgroup_size)
 59:             .field("cached", &self.fast.is_some())
 60:             .finish()
 61:     }
 62: }
 63: 
 64: impl PartialEq for Kernel {
 65:     fn eq(&self, other: &Self) -> bool {
 66:         self.pipeline.shader.code == other.pipeline.shader.code
 67:     }
 68: }
 69: 
 70: impl Kernel {
 71:     /// Compile WGSL into a kernel. The source is ordinary WGSL with explicit
 72:     /// `@group(0) @binding(n)` declarations; the binding *names* are what a
 73:     /// dispatch matches its parameters against.
 74:     pub fn new(context: &WgpuContext, code: impl Into<String>) -> Result<Self> {
 75:         // Shader and pipeline creation read back validation error scopes,
 76:         // which interleave badly when two threads compile at once.
 77:         let _compiling = COMPILING
 78:             .lock()
 79:             .unwrap_or_else(|poisoned| poisoned.into_inner());
 80:         let code = code.into();
 81: 
 82:         let module =
 83:             fabelgeist_gpu::data::gpu::shader::parse_naga(&code, wgpu::naga::ShaderStage::Compute)?;
 84:         let entry = module
 85:             .entry_points
 86:             .iter()
 87:             .find(|ep| ep.stage == wgpu::naga::ShaderStage::Compute)
 88:             .ok_or_else(|| anyhow!("Kernel: no compute entry point"))?;
 89:         let workgroup_size = entry.workgroup_size;
 90:         let entry_point = entry.name.clone();
 91: 
 92:         if workgroup_size.contains(&0) {
 93:             return Err(anyhow!(
 94:                 "Kernel `{entry_point}`: workgroup size {workgroup_size:?} has a zero dimension"
 95:             ));
 96:         }
 97: 
 98:         let shader = ComputeShader::new(context, code.clone())?;
 99:         let mut pipeline = ComputePipeline::prepare(context, shader)?;
100: 
101:         let fast = match pipeline
102:             .shader
103:             .module
104:             .as_ref()
105:             .zip(pipeline.reflection.as_ref())
106:         {
107:             Some((module, reflection)) => {
108:                 fast::FastPath::new(context, module, &entry_point, reflection)?
109:             }
110:             None => None,
111:         };
112: 
113:         // The batched layout owns its pipeline. Compile the static layout only
114:         // for kernels requiring it, or when a caller uses a one-off dispatch.
115:         if fast.is_none() {
116:             pipeline.compile(context)?;
117:         }
118: 
119:         Ok(Self {
120:             pipeline,
121:             workgroup_size,
122:             entry_point,
123:             fast,
124:         })
125:     }
126: 
127:     /// Whether this kernel dispatches through the cached path.
128:     pub fn is_cached(&self) -> bool {
129:         self.fast.is_some()
130:     }
131: 
132:     /// Workgroup count that covers `items` invocations along x.
133:     pub fn groups_for(&self, items: u32) -> [u32; 3] {
134:         [items.div_ceil(self.workgroup_size[0]), 1, 1]
135:     }
136: 
137:     /// Workgroup count that covers `items` invocations, folded into y past
138:     /// the 65535 groups one dimension may hold. The kernel recovers its item
139:     /// with [`FOLDED_INDEX_WGSL`]'s `folded_index`, and must bounds-check it:
140:     /// the last row of groups overshoots.
141:     pub fn groups_folded(&self, items: u32) -> [u32; 3] {
142:         let groups = items.div_ceil(self.workgroup_size[0]);
143:         let x = groups.clamp(1, MAX_GROUPS);
144:         [x, groups.div_ceil(x), 1]
145:     }

146: 
147:     /// Run this kernel on its own -- one encoder, one submit. Convenient for a
148:     /// one-off; use a [`KernelBatch`] for anything in a loop.
149:     pub fn run(
150:         &self,
151:         context: &WgpuContext,
152:         parameters: PassParameters,
153:         groups: [u32; 3],
154:     ) -> Result<()> {
155:         let pipeline = {
156:             let _compiling = COMPILING
157:                 .lock()
158:                 .unwrap_or_else(|poisoned| poisoned.into_inner());
159:             let mut pipeline = self.pipeline.clone();
160:             pipeline.compile(context)?;
161:             pipeline
162:         };
163:         ComputePass::dispatch(
164:             context, pipeline, parameters, groups[0], groups[1], groups[2],
165:         )
166:     }
167: }
168: 
169: /// Compiles each distinct kernel source once and hands out clones after that.
170: ///
171: /// Kernels here are generated -- a constraint kernel is a template with the
172: /// fabric model pasted into it -- so the same source comes back around every
173: /// frame and for every solver instance. Compiling it once per source rather
174: /// than once per call is the difference between a stutter and a steady frame.
175: #[derive(Clone, Debug, Default)]
176: pub struct KernelCache {
177:     kernels: Arc<RwLock<HashMap<String, Arc<Kernel>>>>,
178: }
179: 
180: impl KernelCache {
181:     pub fn new() -> Self {
182:         Self::default()
183:     }
184: 
185:     pub fn get(&self, context: &WgpuContext, code: &str) -> Result<Arc<Kernel>> {
186:         if let Some(kernel) = self.kernels.read().unwrap().get(code) {
187:             return Ok(kernel.clone());
188:         }
189: 
190:         // Compiled outside the write lock: a shader compile is slow, and
191:         // holding the lock across it would serialise every other kernel's
192:         // first use behind this one.
193:         let kernel = Arc::new(Kernel::new(context, code)?);
194: 
195:         let mut kernels = self.kernels.write().unwrap();
196:         // A racing caller may have inserted the same source in the meantime;
197:         // keep theirs, so that every holder of this source shares one pipeline.
198:         Ok(kernels.entry(code.to_string()).or_insert(kernel).clone())
199:     }
200: 
201:     pub fn len(&self) -> usize {
202:         self.kernels.read().unwrap().len()
203:     }
204: 
205:     pub fn is_empty(&self) -> bool {
206:         self.len() == 0
207:     }
208: }
209: 
210: /// A command encoder that many kernel dispatches record into before a single
211: /// submit.
212: ///
213: /// Dispatches recorded into one encoder run in order and wgpu inserts the
214: /// barriers between them, so a solver can read what the previous dispatch
215: /// wrote without any explicit synchronisation.
216: pub struct KernelBatch<'a> {
217:     context: &'a WgpuContext,
218:     encoder: wgpu::CommandEncoder,
219:     dispatches: usize,
220:     uniforms: fast::UniformArena,
221:     /// Run once the batch is submitted, in order.
222:     after_submit: Vec<Box<dyn FnOnce() + Send + 'a>>,
223: }
224: 
225: impl<'a> KernelBatch<'a> {
226:     pub fn new(context: &'a WgpuContext) -> Self {
227:         Self::labelled(context, "KernelBatch")
228:     }
229: 
230:     pub fn labelled(context: &'a WgpuContext, label: &str) -> Self {
231:         let encoder = context
232:             .device
233:             .create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some(label) });
234:         Self {
235:             context,
236:             encoder,
237:             dispatches: 0,
238:             uniforms: fast::UniformArena::default(),
239:             after_submit: Vec::new(),
240:         }
241:     }
242: 
243:     /// The context the batch records for -- for a pass that has to upload a
244:     /// changed parameter before its dispatches run.
245:     pub fn context(&self) -> &'a WgpuContext {
246:         self.context
247:     }
248: 
249:     /// Record one dispatch of `kernel` over an explicit workgroup grid.
250:     pub fn dispatch(
251:         &mut self,
252:         kernel: &Kernel,
253:         parameters: &PassParameters,
254:         groups: [u32; 3],
255:     ) -> Result<&mut Self> {
256:         // A zero-sized grid is a no-op, not an error: an empty constraint
257:         // colour or an empty contact list is a perfectly ordinary frame.
258:         if groups.contains(&0) {
259:             return Ok(self);
260:         }
261: 
262:         match &kernel.fast {
263:             Some(fast) => {
264:                 let prepared = fast.prepare(self.context, parameters, &mut self.uniforms)?;
265:                 let mut pass = self
266:                     .encoder
267:                     .begin_compute_pass(&wgpu::ComputePassDescriptor {
268:                         label: Some("Kernel Pass"),
269:                         timestamp_writes: None,
270:                     });
271:                 pass.set_pipeline(&prepared.pipeline);
272:                 match prepared.dynamic_offset {
273:                     Some(offset) => pass.set_bind_group(0, &prepared.bind_group, &[offset]),
274:                     None => pass.set_bind_group(0, &prepared.bind_group, &[]),
275:                 }
276:                 pass.dispatch_workgroups(groups[0], groups[1], groups[2]);
277:             }
278:             None => ComputePass::record(
279:                 self.context,
280:                 &kernel.pipeline,
281:                 parameters,
282:                 &mut self.encoder,
283:                 groups[0],
284:                 groups[1],
285:                 groups[2],
286:             )?,
287:         }
288: 
289:         self.dispatches += 1;
290:         Ok(self)

291:     }
292: 
293:     /// Record one dispatch covering `items` invocations however many there
294:     /// are, folded as [`Kernel::groups_folded`] describes.
295:     pub fn dispatch_folded(
296:         &mut self,
297:         kernel: &Kernel,
298:         parameters: &PassParameters,
299:         items: u32,
300:     ) -> Result<&mut Self> {
301:         if items == 0 {
302:             return Ok(self);
303:         }
304:         self.dispatch(kernel, parameters, kernel.groups_folded(items))
305:     }
306: 
307:     /// Record one dispatch sized to cover `items` invocations along x.
308:     pub fn dispatch_items(
309:         &mut self,
310:         kernel: &Kernel,
311:         parameters: &PassParameters,
312:         items: u32,
313:     ) -> Result<&mut Self> {
314:         self.dispatch(kernel, parameters, kernel.groups_for(items))
315:     }
316: 
317:     /// Copy between buffers inside the batch, so that the copy is ordered
318:     /// against the dispatches around it.
319:     pub fn copy_buffer(&mut self, source: &Buffer, destination: &Buffer, bytes: u64) -> Result<()> {
320:         if bytes > u64::from(source.size) || bytes > u64::from(destination.size) {
321:             return Err(anyhow!(
322:                 "KernelBatch::copy_buffer: {bytes} bytes does not fit {} -> {}",
323:                 u64::from(source.size),
324:                 u64::from(destination.size)
325:             ));
326:         }
327:         self.encoder
328:             .copy_buffer_to_buffer(&source.buffer, 0, &destination.buffer, 0, bytes);
329:         Ok(())
330:     }
331: 
332:     /// Zero a buffer inside the batch.
333:     pub fn clear_buffer(&mut self, buffer: &Buffer) {
334:         self.encoder.clear_buffer(&buffer.buffer, 0, None);
335:     }
336: 
337:     /// The raw encoder, for anything this wrapper does not cover.
338:     pub fn encoder(&mut self) -> &mut wgpu::CommandEncoder {
339:         &mut self.encoder
340:     }
341: 
342:     pub fn dispatch_count(&self) -> usize {
343:         self.dispatches
344:     }
345: 
346:     /// Run `work` once the batch has been submitted -- for what has to
347:     /// follow the submission rather than be recorded in it, like asking for a
348:     /// staging buffer to be mapped. Dropped unrun if the batch never is.
349:     pub fn after_submit(&mut self, work: impl FnOnce() + Send + 'a) {
350:         self.after_submit.push(Box::new(work));
351:     }
352: 
353:     /// Finish the encoder and submit. Returns the submission index, which the
354:     /// caller can wait on if it needs the results back on the host.
355:     pub fn submit(self) -> wgpu::SubmissionIndex {
356:         let index = self.context.queue.submit(Some(self.encoder.finish()));
357:         for work in self.after_submit {
358:             work();
359:         }
360:         index
361:     }
362: }
363: 
364: // There is no unit test here for the barrier between dependent dispatches,
365: // and not for want of trying: a synthetic chain -- one kernel repeated, or two
366: // alternating on one buffer -- keeps working even with the bind group cached,
367: // which is the mistake that breaks the real thing. The case that does catch it
368: // is `fabelgeist_bvh::gpu::tests::refit_tracks_moved_primitives`, where three
369: // different kernels take turns on one buffer through atomics. That test is the
370: // guard; see the note at the top of `fast.rs` for what it guards against.
371: 
372: #[cfg(test)]
373: mod context_tests {
374:     use super::*;
375:     use anyhow::Result;
376:     use fabelgeist_gpu::globals::WgpuContext;
377: 
378:     /// A kernel compiles through a *borrowed* context too -- one built from
379:     /// someone else's device rather than owning it.
380:     ///
381:     /// Lives here rather than beside `WgpuContext`, because the kernel is
382:     /// this crate's and `fabelgeist-gpu` cannot depend on it.
383:     #[tokio::test]
384:     async fn a_borrowed_context_compiles_a_kernel() -> Result<()> {
385:         let owned = WgpuContext::new().await?;
386:         let borrowed = WgpuContext::from_parts(
387:             owned.instance.clone(),
388:             owned.adapter.clone(),
389:             owned.device.clone(),
390:             owned.queue.clone(),
391:         );
392: 
393:         let kernel = Kernel::new(
394:             &borrowed,
395:             r#"
396: @group(0) @binding(0) var<storage, read_write> values: array<f32>;
397: @compute @workgroup_size(64)
398: fn main(@builtin(global_invocation_id) id: vec3<u32>) {
399:     if (id.x < arrayLength(&values)) { values[id.x] = values[id.x] * 2.0; }
400: }
401: "#,
402:         )?;
403:         assert_eq!(kernel.workgroup_size, [64, 1, 1]);
404:         Ok(())
405:     }
406: }

