  1: //! Many results back to the host for the price of one.
  2: //!
  3: //! [`Buffer::read`] copies its buffer to a staging buffer, submits, and
  4: //! waits for the queue: one round trip per buffer. A pipeline that ends with a
  5: //! dozen small results -- positions, normals, indices, a few status words --
  6: //! pays that wait a dozen times. A [`Readback`] records every copy into the
  7: //! batch that produced the results, lays them end to end in one staging
  8: //! buffer, and maps it once after the batch is submitted.
  9: //!
 10: //! Waiting at all is the other cost. [`Readback::record_pending`] asks for the
 11: //! mapping as the batch is submitted and returns a [`PendingReadback`], which
 12: //! hands the results over once the GPU has got there -- a frame later, say --
 13: //! and until then says so rather than waiting: a simulation stepped on the
 14: //! GPU can be read every frame without the CPU ever stalling on it.
 15: 
 16: use std::sync::{Arc, Mutex, MutexGuard};
 17: 
 18: use fabelgeist_gpu::prelude::{Buffer, BufferByteLength, BufferByteOffset, WgpuContext};
 19: 
 20: use crate::KernelBatch;
 21: 
 22: type Result<T> = std::result::Result<T, ReadbackError>;
 23: 
 24: /// A buffer's admitted location in the shared staging allocation.
 25: #[derive(Clone, Copy, Debug)]
 26: struct StagedRange {
 27:     offset: BufferByteOffset,
 28:     length: BufferByteLength,
 29: }
 30: 
 31: /// Results staged for one mapping.
 32: #[derive(Debug)]
 33: pub struct Readback {
 34:     staging: wgpu::Buffer,
 35:     ranges: Vec<StagedRange>,
 36: }
 37: 
 38: /// Results on their way back: see [`Readback::record_pending`].
 39: #[derive(Debug)]
 40: pub struct PendingReadback {
 41:     staging: Arc<wgpu::Buffer>,
 42:     ranges: Vec<StagedRange>,
 43:     state: Arc<Mutex<ReadbackState>>,
 44: }
 45: 
 46: /// Failures of recording or retrieving a batch of GPU results.
 47: #[derive(Debug, thiserror::Error)]
 48: pub enum ReadbackError {
 49:     #[error("readback staging extent exceeds the addressable buffer size")]
 50:     ExtentOverflow,
 51:     #[error("readback mapping callback was dropped")]
 52:     ChannelClosed,
 53:     #[error("readback mapping failed")]
 54:     Mapping(#[source] wgpu::BufferAsyncError),
 55:     #[error("readback device polling failed")]
 56:     Poll(#[source] wgpu::PollError),
 57:     #[error("readback results have already been taken")]
 58:     AlreadyRead,
 59: }
 60: 
 61: #[derive(Debug)]
 62: enum ReadbackState {
 63:     Pending,
 64:     Ready,
 65:     Failed(wgpu::BufferAsyncError),
 66:     Taken,
 67: }
 68: 
 69: impl StagedRange {
 70:     /// Convert byte addresses only when slicing the mapped native bytes.
 71:     fn bytes(self, data: &[u8]) -> Vec<u8> {
 72:         let start = u64::from(self.offset) as usize;
 73:         let length = u64::from(self.length) as usize;
 74:         data[start..start + length].to_vec()
 75:     }
 76: }
 77: 
 78: impl Readback {
 79:     /// Record each source's typed extent in an aligned staging allocation.
 80:     /// Overflow is rejected before a GPU allocation or copy is recorded.
 81:     pub fn record(
 82:         context: &WgpuContext,
 83:         batch: &mut KernelBatch,
 84:         buffers: &[&Buffer],
 85:     ) -> Result<Self> {
 86:         let mut ranges = Vec::with_capacity(buffers.len());
 87:         let mut end = BufferByteOffset::START;
 88:         for buffer in buffers {
 89:             ranges.push(StagedRange {
 90:                 offset: end,
 91:                 length: buffer.size,
 92:             });
 93:             // wgpu's copy alignment is a byte-layout boundary. Preserve the
 94:             // original padding and ordering while checking the total extent.
 95:             let padded = u64::from(buffer.size)
 96:                 .div_ceil(wgpu::COPY_BUFFER_ALIGNMENT)
 97:                 .checked_mul(wgpu::COPY_BUFFER_ALIGNMENT)
 98:                 .ok_or(ReadbackError::ExtentOverflow)?;
 99:             end = end
100:                 .checked_after(BufferByteLength::from(padded))
101:                 .ok_or(ReadbackError::ExtentOverflow)?;
102:         }
103:         let staging = context.device.create_buffer(&wgpu::BufferDescriptor {
104:             label: Some("Readback"),
105:             size: u64::from(end).max(wgpu::COPY_BUFFER_ALIGNMENT),
106:             usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
107:             mapped_at_creation: false,
108:         });
109:         for (buffer, range) in buffers.iter().zip(&ranges) {
110:             batch.encoder().copy_buffer_to_buffer(
111:                 &buffer.buffer,
112:                 0,
113:                 &staging,
114:                 u64::from(range.offset),
115:                 u64::from(range.length),
116:             );
117:         }
118:         Ok(Self { staging, ranges })
119:     }
120: 
121:     /// Record copies and request mapping when the producing batch is submitted.
122:     pub fn record_pending(
123:         context: &WgpuContext,
124:         batch: &mut KernelBatch,
125:         buffers: &[&Buffer],
126:     ) -> Result<PendingReadback> {
127:         let Self { staging, ranges } = Self::record(context, batch, buffers)?;
128:         let state = Arc::new(Mutex::new(ReadbackState::Pending));
129:         let staging = Arc::new(staging);
130:         let (mapped, shared) = (staging.clone(), state.clone());
131:         batch.after_submit(move || {
132:             mapped
133:                 .slice(..)
134:                 .map_async(wgpu::MapMode::Read, move |result| {
135:                     *lock_state(&shared) = match result {
136:                         Ok(()) => ReadbackState::Ready,
137:                         Err(error) => ReadbackState::Failed(error),
138:                     };
139:                 });
140:         });
141:         Ok(PendingReadback {
142:             staging,
143:             ranges,
144:             state,
145:         })
146:     }
147: 
148:     /// Map once and return each source's bytes in the recorded order.
149:     pub async fn read(self, context: &WgpuContext) -> Result<Vec<Vec<u8>>> {
150:         let slice = self.staging.slice(..);

151:         let (sender, receiver) = futures_channel::oneshot::channel();
152:         slice.map_async(wgpu::MapMode::Read, move |result| {
153:             let _ = sender.send(result);
154:         });
155:         #[cfg(not(target_arch = "wasm32"))]
156:         context
157:             .device
158:             .poll(wgpu::PollType::wait_indefinitely())
159:             .map_err(ReadbackError::Poll)?;
160:         #[cfg(target_arch = "wasm32")]
161:         let _ = context;
162:         receiver
163:             .await
164:             .map_err(|_| ReadbackError::ChannelClosed)?
165:             .map_err(ReadbackError::Mapping)?;
166:         let data = slice.get_mapped_range();
167:         let results = self.ranges.iter().map(|range| range.bytes(&data)).collect();
168:         drop(data);
169:         self.staging.unmap();
170:         Ok(results)
171:     }
172: }
173: 
174: impl PendingReadback {
175:     /// Take completed results once, returning `None` while mapping is pending.
176:     pub fn try_read(&self, context: &WgpuContext) -> Result<Option<Vec<Vec<u8>>>> {
177:         poll(context)?;
178:         let mut state = lock_state(&self.state);
179:         match &*state {
180:             ReadbackState::Pending => return Ok(None),
181:             ReadbackState::Failed(error) => return Err(ReadbackError::Mapping(error.clone())),
182:             ReadbackState::Taken => return Err(ReadbackError::AlreadyRead),
183:             ReadbackState::Ready => {}
184:         }
185:         let slice = self.staging.slice(..);
186:         let data = slice.get_mapped_range();
187:         let results = self.ranges.iter().map(|range| range.bytes(&data)).collect();
188:         drop(data);
189:         self.staging.unmap();
190:         *state = ReadbackState::Taken;
191:         Ok(Some(results))
192:     }
193: 
194:     /// Observe readiness without taking the mapped results.
195:     pub fn is_ready(&self, context: &WgpuContext) -> Result<bool> {
196:         poll(context)?;
197:         match &*lock_state(&self.state) {
198:             ReadbackState::Ready => Ok(true),
199:             ReadbackState::Failed(error) => Err(ReadbackError::Mapping(error.clone())),
200:             ReadbackState::Pending | ReadbackState::Taken => Ok(false),
201:         }
202:     }
203: }
204: 
205: fn poll(context: &WgpuContext) -> Result<()> {
206:     #[cfg(not(target_arch = "wasm32"))]
207:     context
208:         .device
209:         .poll(wgpu::PollType::Poll)
210:         .map_err(ReadbackError::Poll)?;
211:     #[cfg(target_arch = "wasm32")]
212:     let _ = context;
213:     Ok(())
214: }
215: 
216: fn lock_state(state: &Mutex<ReadbackState>) -> MutexGuard<'_, ReadbackState> {
217:     // The callback replaces one complete enum value. A poisoned lock cannot
218:     // expose a partially updated record, so retain the recorded GPU outcome.
219:     match state.lock() {
220:         Ok(state) => state,
221:         Err(poisoned) => poisoned.into_inner(),
222:     }
223: }
