  1: //! Least-significant-digit radix sort of `u32` keys, carrying a `u32` payload.
  2: //!
  3: //! Two things upstream need it. A linear BVH sorts primitives by Morton code;
  4: //! a spatial hash sorts particles by cell index. Both want the sort recorded
  5: //! into the frame's own [`KernelBatch`], never read back to the host, so this
  6: //! is written as passes over GPU buffers with no synchronisation points.
  7: //!
  8: //! Eight bits per pass, so a full 32-bit key takes four passes and a 30-bit
  9: //! Morton code takes four as well (`bits` rounds up to a whole digit). Each
 10: //! pass is three dispatches:
 11: //!
 12: //! 1. **histogram** -- one workgroup per tile counts its 256 digits into
 13: //!    shared memory and writes the counts to `histogram[digit][tile]`.
 14: //! 2. **scan** -- an exclusive [`PrefixSum`] over the whole histogram turns
 15: //!    those counts into the global offset each `(digit, tile)` pair writes
 16: //!    at. Digit-major is what makes one flat scan enough: everything before
 17: //!    `(d, t)` in the array is every smaller digit from every tile, then
 18: //!    digit `d` from the earlier tiles -- exactly what lands before it in the
 19: //!    output. (A single workgroup used to do this, each thread walking one
 20: //!    digit's row; past a few hundred thousand keys that serial walk was most
 21: //!    of the sort.)
 22: //! 3. **scatter** -- each element's destination is its tile's base for that
 23: //!    digit, plus its rank among the same-digit elements earlier in the tile.
 24: //!
 25: //! The rank in step 3 is computed by counting matching digits over the tile in
 26: //! shared memory: `TILE` reads per element, all 256 threads in parallel. A
 27: //! subgroup ballot would make it a couple of instructions instead, but ballots
 28: //! are an optional wgpu feature and this is nowhere near the bottleneck for
 29: //! the tens of thousands of elements a cloth solve sorts.
 30: 
 31: use crate::prelude::*;
 32: use std::sync::Arc;
 33: 
 34: /// Elements per tile, and threads per workgroup. One element per thread.
 35: const TILE: u32 = 256;
 36: /// Digits per pass. Tied to `TILE` only because the scan pass gives each of
 37: /// its 256 threads one digit row.
 38: const RADIX: u32 = 256;
 39: /// Bits consumed per pass.
 40: const BITS_PER_PASS: u32 = 8;
 41: 
 42: fn histogram_code() -> String {
 43:     format!(
 44:         r#"
 45: @group(0) @binding(0) var<storage, read> keys: array<u32>;
 46: @group(0) @binding(1) var<storage, read_write> histogram: array<u32>;
 47: 
 48: struct Params {{
 49:     count: u32,
 50:     shift: u32,
 51:     tiles: u32,
 52:     pad: u32,
 53: }};
 54: @group(0) @binding(2) var<uniform> params: Params;
 55: 
 56: var<workgroup> local_histogram: array<atomic<u32>, {RADIX}u>;
 57: 
 58: @compute @workgroup_size({TILE}u)
 59: fn main(
 60:     @builtin(global_invocation_id) global_id: vec3<u32>,
 61:     @builtin(local_invocation_id) local_id: vec3<u32>,
 62:     @builtin(workgroup_id) group_id: vec3<u32>,
 63: ) {{
 64:     atomicStore(&local_histogram[local_id.x], 0u);
 65:     workgroupBarrier();
 66: 
 67:     let index = global_id.x;
 68:     if (index < params.count) {{
 69:         let digit = (keys[index] >> params.shift) & {mask}u;
 70:         atomicAdd(&local_histogram[digit], 1u);
 71:     }}
 72:     workgroupBarrier();
 73: 
 74:     // Digit-major: every tile's count for one digit is contiguous, which is
 75:     // what lets the scan pass hand one whole row to one thread.
 76:     histogram[local_id.x * params.tiles + group_id.x] =
 77:         atomicLoad(&local_histogram[local_id.x]);
 78: }}
 79: "#,
 80:         mask = RADIX - 1
 81:     )
 82: }
 83: 
 84: fn scatter_code() -> String {
 85:     format!(
 86:         r#"
 87: @group(0) @binding(0) var<storage, read> keys_in: array<u32>;
 88: @group(0) @binding(1) var<storage, read> values_in: array<u32>;
 89: @group(0) @binding(2) var<storage, read_write> keys_out: array<u32>;
 90: @group(0) @binding(3) var<storage, read_write> values_out: array<u32>;
 91: @group(0) @binding(4) var<storage, read> histogram: array<u32>;
 92: 
 93: struct Params {{
 94:     count: u32,
 95:     shift: u32,
 96:     tiles: u32,
 97:     pad: u32,
 98: }};
 99: @group(0) @binding(5) var<uniform> params: Params;
100: 
101: var<workgroup> tile_digits: array<u32, {TILE}u>;
102: 
103: @compute @workgroup_size({TILE}u)
104: fn main(
105:     @builtin(global_invocation_id) global_id: vec3<u32>,
106:     @builtin(local_invocation_id) local_id: vec3<u32>,
107:     @builtin(workgroup_id) group_id: vec3<u32>,
108: ) {{
109:     let index = global_id.x;
110:     let in_range = index < params.count;
111: 
112:     // Out-of-range lanes park on a digit no live lane can hold. They sit past
113:     // the end of the tile, so a live lane would never count them anyway; this
114:     // just keeps the shared array from carrying a digit that means something.
115:     var digit = {RADIX}u;
116:     var key = 0u;
117:     if (in_range) {{
118:         key = keys_in[index];
119:         digit = (key >> params.shift) & {mask}u;
120:     }}
121:     tile_digits[local_id.x] = digit;
122:     workgroupBarrier();
123: 
124:     if (in_range) {{
125:         // Rank among the same-digit elements earlier in this tile. Counting
126:         // rather than scanning keeps the sort stable, which is what makes the
127:         // whole least-significant-digit scheme work.
128:         var rank = 0u;
129:         for (var i = 0u; i < local_id.x; i = i + 1u) {{
130:             if (tile_digits[i] == digit) {{
131:                 rank = rank + 1u;
132:             }}
133:         }}
134:         let destination = histogram[digit * params.tiles + group_id.x] + rank;
135:         keys_out[destination] = key;
136:         values_out[destination] = values_in[index];
137:     }}
138: }}
139: "#,
140:         mask = RADIX - 1
141:     )
142: }
143: 
144: /// Scratch buffers a sort needs: one ping-pong pair, the histogram, and the
145: /// histogram scan's own scratch.
146: ///
147: /// Allocated for a capacity and reused, so that a per-frame sort does not
148: /// allocate. Grow it with [`SortScratch::ensure`].
149: #[derive(Clone, Debug)]
150: pub struct SortScratch {
151:     pub keys: Buffer,
152:     pub values: Buffer,
153:     pub histogram: Buffer,
154:     scan: PrefixSumScratch,
155:     capacity: u32,

156: }
157: 
158: impl SortScratch {
159:     pub fn new(context: &WgpuContext, capacity: u32) -> Result<Self> {
160:         let capacity = capacity.max(1);
161:         let tiles = capacity.div_ceil(TILE);
162:         let storage = BufferDefinition::storage();
163:         Ok(Self {
164:             keys: Buffer::new(
165:                 context,
166:                 ((capacity as u64) * 4).into(),
167:                 storage.clone().with_label("sort keys".into()),
168:             )?,
169:             values: Buffer::new(
170:                 context,
171:                 ((capacity as u64) * 4).into(),
172:                 storage.clone().with_label("sort values".into()),
173:             )?,
174:             histogram: Buffer::new(
175:                 context,
176:                 ((RADIX as u64) * (tiles as u64) * 4).into(),
177:                 storage.with_label("sort histogram".into()),
178:             )?,
179:             scan: PrefixSumScratch::new(context, ScanElementCount::from_elements(RADIX * tiles))?,
180:             capacity,
181:         })
182:     }
183: 
184:     pub fn capacity(&self) -> u32 {
185:         self.capacity
186:     }
187: 
188:     /// Reallocate if `capacity` no longer fits. Returns whether it grew.
189:     pub fn ensure(&mut self, context: &WgpuContext, capacity: u32) -> Result<bool> {
190:         if capacity <= self.capacity {
191:             return Ok(false);
192:         }
193:         *self = Self::new(context, capacity)?;
194:         Ok(true)
195:     }
196: }
197: 
198: /// The compiled passes.
199: #[derive(Clone, Debug)]
200: pub struct RadixSort {
201:     histogram: Arc<Kernel>,
202:     scan: PrefixSum,
203:     scatter: Arc<Kernel>,
204: }
205: 
206: impl RadixSort {
207:     pub fn new(context: &WgpuContext) -> Result<Self> {
208:         Self::with_cache(context, &KernelCache::new())
209:     }
210: 
211:     pub fn with_cache(context: &WgpuContext, cache: &KernelCache) -> Result<Self> {
212:         Ok(Self {
213:             histogram: cache.get(context, &histogram_code())?,
214:             scan: PrefixSum::with_cache(context, cache)?,
215:             scatter: cache.get(context, &scatter_code())?,
216:         })
217:     }
218: 
219:     /// Number of passes a key of `bits` significant bits needs.
220:     pub fn passes_for(bits: u32) -> u32 {
221:         bits.clamp(1, 32).div_ceil(BITS_PER_PASS)
222:     }
223: 
224:     /// Record a sort of `keys`/`values` in place, ascending by key.
225:     ///
226:     /// `bits` is how many low bits of the key actually vary -- 30 for a Morton
227:     /// code, 32 for an arbitrary hash. Passing fewer is purely a saving; it
228:     /// never changes the result as long as the higher bits really are zero.
229:     ///
230:     /// Every pass ping-pongs into `scratch`, so an odd pass count would leave
231:     /// the result there. Rather than make the caller track that, an odd count
232:     /// gets one extra copy back at the end.
233:     pub fn record(
234:         &self,
235:         batch: &mut KernelBatch,
236:         keys: &Buffer,
237:         values: &Buffer,
238:         scratch: &mut SortScratch,
239:         count: u32,
240:         bits: u32,
241:     ) -> Result<()> {
242:         if count <= 1 {
243:             return Ok(());
244:         }
245:         if scratch.capacity < count {
246:             return Err(anyhow!(
247:                 "RadixSort: scratch holds {} elements, asked to sort {count}",
248:                 scratch.capacity
249:             ));
250:         }
251:         let needed = (count as u64) * 4;
252:         if u64::from(keys.size) < needed || u64::from(values.size) < needed {
253:             return Err(anyhow!(
254:                 "RadixSort: {count} elements need {needed} bytes; keys hold {}, values hold {}",
255:                 u64::from(keys.size),
256:                 u64::from(values.size)
257:             ));
258:         }
259: 
260:         let tiles = count.div_ceil(TILE);
261:         let passes = Self::passes_for(bits);
262: 
263:         let mut source_keys = keys.clone();
264:         let mut source_values = values.clone();
265:         let mut target_keys = scratch.keys.clone();
266:         let mut target_values = scratch.values.clone();
267: 
268:         for pass in 0..passes {
269:             let shift = pass * BITS_PER_PASS;
270: 
271:             let mut parameters = PassParameters::new();
272:             parameters.insert("count", count);
273:             parameters.insert("shift", shift);
274:             parameters.insert("tiles", tiles);
275:             parameters.insert("pad", 0u32);
276:             parameters.insert("histogram", scratch.histogram.clone());
277: 
278:             let mut histogram_parameters = parameters.clone();
279:             histogram_parameters.insert("keys", source_keys.clone());
280:             batch.dispatch(&self.histogram, &histogram_parameters, [tiles, 1, 1])?;
281: 
282:             self.scan.record(
283:                 batch,
284:                 &scratch.histogram,
285:                 &scratch.scan,
286:                 ScanElementCount::from_elements(RADIX * tiles),
287:             )?;
288: 
289:             let mut scatter_parameters = parameters;
290:             scatter_parameters.insert("keys_in", source_keys.clone());
291:             scatter_parameters.insert("values_in", source_values.clone());
292:             scatter_parameters.insert("keys_out", target_keys.clone());
293:             scatter_parameters.insert("values_out", target_values.clone());
294:             batch.dispatch(&self.scatter, &scatter_parameters, [tiles, 1, 1])?;
295: 
296:             std::mem::swap(&mut source_keys, &mut target_keys);
297:             std::mem::swap(&mut source_values, &mut target_values);
298:         }
299: 
300:         if passes % 2 == 1 {
301:             batch.copy_buffer(&source_keys, keys, needed)?;
302:             batch.copy_buffer(&source_values, values, needed)?;
303:         }
304: 
305:         Ok(())

  1: //! Animation takes, as FBX stores them.
  2: //!
  3: //! FBX addresses animation through connections rather than containment:
  4: //!
  5: //! ```text
  6: //! AnimationStack ("Take 001")
  7: //!   └── AnimationLayer
  8: //!         └── AnimationCurveNode ──OP:"Lcl Rotation"──> Model
  9: //!               ├── AnimationCurve ──OP:"d|X"
 10: //!               ├── AnimationCurve ──OP:"d|Y"
 11: //!               └── AnimationCurve ──OP:"d|Z"
 12: //! ```
 13: //!
 14: //! Times come back in seconds. Values come back exactly as the file stores
 15: //! them — rotations in degrees, in the target node's own rotation order, before
 16: //! any pre/post-rotation — because composing those is a rig question, not a
 17: //! container question.
 18: 
 19: use crate::{FbxObjectName, FbxQualifiedName, Prop, Scene};
 20: use anyhow::{Context, Result};
 21: 
 22: /// FBX stores times as integer ticks of this many per second.
 23: const TICKS_PER_SECOND: f64 = 46_186_158_000.0;
 24: 
 25: /// Declared or inferred FBX take duration in source seconds, retaining f64 precision.
 26: #[derive(derive_more::Debug, Clone, Copy, PartialEq)]
 27: #[debug("{_0:?}")]
 28: pub struct FbxAnimationDuration(f64);
 29: 
 30: /// One animated scalar channel.
 31: #[derive(Debug, Clone, Default)]
 32: pub struct Curve {
 33:     /// Key times in seconds, ascending.
 34:     pub times: Vec<f64>,
 35:     pub values: Vec<f64>,
 36: }
 37: 
 38: /// One of a node's transform properties, as three channels plus the static
 39: /// values to use where a channel has no curve.
 40: #[derive(Debug, Clone, Default)]
 41: pub struct TransformChannel {
 42:     pub x: Curve,
 43:     pub y: Curve,
 44:     pub z: Curve,
 45:     /// The curve node's own `d|X`, `d|Y`, `d|Z` values.
 46:     pub default: [f64; 3],
 47: }
 48: 
 49: /// Everything one take animates on one node.
 50: #[derive(Debug, Clone)]
 51: pub struct NodeAnimation {
 52:     /// Object id of the animated `Model`.
 53:     pub node: i64,
 54:     /// The model's name, namespace intact.
 55:     pub name: FbxQualifiedName,
 56:     pub translation: Option<TransformChannel>,
 57:     /// Euler angles in degrees, in the node's own rotation order.
 58:     pub rotation: Option<TransformChannel>,
 59:     pub scale: Option<TransformChannel>,
 60: }
