 62: /// One `AnimationStack` — what other tools call a take or a clip.
 63: #[derive(Debug, Clone)]
 64: pub struct Take {
 65:     pub name: FbxObjectName,
 66:     /// Seconds, from the stack's declared local time span when it has one and
 67:     /// from the keys otherwise.
