 72: /// Rejection at the source-file seconds boundary.
 73: #[derive(Debug, Clone, Copy, PartialEq, Eq, derive_more::Display, derive_more::Error)]
 74: pub enum InvalidFbxAnimationDuration {
 75:     #[display("FBX take duration must be finite")]
 76:     NonFinite,
 77:     #[display("FBX take duration must be nonnegative")]
 78:     Negative,
 79: }
 80: 
 81: impl FbxAnimationDuration {
 82:     pub fn from_seconds(seconds: f64) -> std::result::Result<Self, InvalidFbxAnimationDuration> {
 83:         if !seconds.is_finite() {
 84:             return Err(InvalidFbxAnimationDuration::NonFinite);
 85:         }
 86:         if seconds < 0.0 {
 87:             return Err(InvalidFbxAnimationDuration::Negative);
 88:         }
 89:         Ok(Self(seconds))
 90:     }
 91:     pub fn seconds(self) -> f64 {
 92:         self.0
 93:     }
 94: }
