 96: impl Curve {
 97:     pub fn is_empty(&self) -> bool {
 98:         self.times.is_empty()
 99:     }
100: 
101:     /// Samples the curve, holding the end values outside the keyed range.
102:     ///
103:     /// FBX keys carry cubic tangents that this ignores: sampling linearly at
104:     /// the file's own key times reproduces every key exactly, which is what an
105:     /// importer that re-keys on import needs.
106:     pub fn sample(&self, time: f64) -> Option<f64> {
107:         if self.times.is_empty() {
108:             return None;
109:         }
110:         let last = self.times.len() - 1;
111:         if time <= self.times[0] {
112:             return Some(self.values[0]);
113:         }
114:         if time >= self.times[last] {
115:             return Some(self.values[last]);
116:         }
117:         let upper = self.times.partition_point(|t| *t < time).min(last);
118:         let lower = upper.saturating_sub(1);
119:         let span = self.times[upper] - self.times[lower];
120:         if span <= 0.0 {
121:             return Some(self.values[lower]);
122:         }
123:         let factor = (time - self.times[lower]) / span;
124:         Some(self.values[lower] + (self.values[upper] - self.values[lower]) * factor)
125:     }
126: }
127: 
128: impl TransformChannel {
129:     pub fn is_empty(&self) -> bool {
130:         self.x.is_empty() && self.y.is_empty() && self.z.is_empty()
131:     }
132: 
133:     /// The value at a time, falling back per axis to the static default.
134:     pub fn sample(&self, time: f64) -> [f64; 3] {
135:         [
136:             self.x.sample(time).unwrap_or(self.default[0]),
137:             self.y.sample(time).unwrap_or(self.default[1]),
138:             self.z.sample(time).unwrap_or(self.default[2]),
139:         ]
140:     }
141: 
142:     /// Every key time in the channel, sorted and deduplicated.
143:     pub fn key_times(&self, into: &mut Vec<f64>) {
144:         into.extend_from_slice(&self.x.times);
145:         into.extend_from_slice(&self.y.times);
146:         into.extend_from_slice(&self.z.times);
147:     }
148: }
149: 
150: impl NodeAnimation {

151:     pub fn key_times(&self, into: &mut Vec<f64>) {
152:         for channel in [&self.translation, &self.rotation, &self.scale]
153:             .into_iter()
154:             .flatten()
155:         {
156:             channel.key_times(into);
157:         }
158:     }
159: }
160: 
161: impl Take {
162:     /// Every distinct key time in the take, sorted.
163:     pub fn key_times(&self) -> Vec<f64> {
164:         let mut times = Vec::new();
165:         for node in &self.nodes {
166:             node.key_times(&mut times);
167:         }
168:         times.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
169:         times.dedup_by(|a, b| (*a - *b).abs() <= 1.0e-9);
170:         if times.is_empty() {
171:             times.push(0.0);
172:         }
173:         times
174:     }
175: }
