177: impl Scene {
178:     /// Every animation take in the file.
179:     ///
180:     /// Takes with no animated node are dropped: FBX exporters routinely emit an
181:     /// empty stack alongside the real one.
182:     pub fn takes(&self) -> Result<Vec<Take>> {
183:         // Curve nodes point at the model they drive, but the link is recorded
184:         // on the model's side, so the reverse map is built once rather than
185:         // rediscovered per curve node.
186:         let mut targets: std::collections::HashMap<i64, (i64, String)> =
187:             std::collections::HashMap::new();
188:         for model in self.objects.iter().filter(|object| object.is_node()) {
189:             for (child, property) in self.children_with_property(model.id) {
190:                 if let Some(property @ ("Lcl Translation" | "Lcl Rotation" | "Lcl Scaling")) =
191:                     property
192:                 {
193:                     targets.insert(child.id, (model.id, property.to_string()));
194:                 }
195:             }
196:         }
197: 
198:         self.objects
199:             .iter()
200:             .filter(|object| object.kind == "AnimationStack")
201:             .filter_map(|stack| {
202:                 let mut nodes: Vec<NodeAnimation> = Vec::new();
203: 
204:                 // Layers are blended by FBX; importers that do not blend take
205:                 // the base layer, which is the first one connected.
206:                 if let Some(layer) = self
207:                     .children(stack.id)
208:                     .find(|object| object.kind == "AnimationLayer")
209:                 {
210:                     self.collect_layer(layer.id, &targets, &mut nodes);
211:                 }
212:                 if nodes.is_empty() {
213:                     return None;
214:                 }
215: 
216:                 let duration = self.stack_duration(stack).unwrap_or_else(|| {
217:                     let mut times = Vec::new();
218:                     for node in &nodes {
219:                         node.key_times(&mut times);
220:                     }
221:                     times.into_iter().fold(0.0, f64::max)
222:                 });
223: 
224:                 Some(
225:                     FbxAnimationDuration::from_seconds(duration)
226:                         .with_context(|| format!("Invalid duration for FBX take {}", stack.name))
227:                         .map(|duration| Take {
228:                             name: stack.name.clone(),
229:                             duration,
230:                             nodes,
231:                         }),
232:                 )
233:             })
234:             .collect()
235:     }
236: 
237:     /// The stack's declared time span, when the exporter wrote one.
238:     fn stack_duration(&self, stack: &crate::Object) -> Option<f64> {
239:         let start = stack.node.property70("LocalStart")?;
240:         let stop = stack.node.property70("LocalStop")?;
241:         let start = start.props.get(4).and_then(Prop::as_i64)?;
242:         let stop = stop.props.get(4).and_then(Prop::as_i64)?;
243:         let span = ticks_to_seconds(stop) - ticks_to_seconds(start);
244:         (span > 0.0).then_some(span)
245:     }
246: 
247:     /// Walks a layer's curve nodes and attributes each to the model and
248:     /// property it drives.
249:     fn collect_layer(
250:         &self,
251:         layer: i64,
252:         targets: &std::collections::HashMap<i64, (i64, String)>,
253:         nodes: &mut Vec<NodeAnimation>,
254:     ) {
255:         for curve_node in self
256:             .children(layer)
257:             .filter(|object| object.kind == "AnimationCurveNode")
258:         {
259:             let Some((model, property)) = targets.get(&curve_node.id) else {
260:                 continue;
261:             };
262:             let (model, property) = (*model, property.as_str());
263:             let channel = self.transform_channel(curve_node.id);
264:             if channel.is_empty() {
265:                 continue;
266:             }
267: 
268:             let entry = match nodes.iter_mut().find(|entry| entry.node == model) {
269:                 Some(entry) => entry,
270:                 None => {
271:                     let name = self
272:                         .get(model)
273:                         .map(|object| object.qualified.clone())
274:                         .unwrap_or_default();
275:                     nodes.push(NodeAnimation {
276:                         node: model,
277:                         name,
278:                         translation: None,
279:                         rotation: None,
280:                         scale: None,
281:                     });
282:                     nodes.last_mut().expect("just pushed")
283:                 }
284:             };
285: 
286:             match property {
287:                 "Lcl Translation" => entry.translation = Some(channel),
288:                 "Lcl Rotation" => entry.rotation = Some(channel),
289:                 "Lcl Scaling" => entry.scale = Some(channel),
290:                 _ => {}

291:             }
292:         }
293:     }
294: 
295:     /// A curve node's three axis curves plus its static defaults.
296:     fn transform_channel(&self, curve_node: i64) -> TransformChannel {
297:         let mut channel = TransformChannel::default();
298: 
299:         if let Some(object) = self.get(curve_node) {
300:             for (index, name) in ["d|X", "d|Y", "d|Z"].into_iter().enumerate() {
301:                 if let Some(value) = object
302:                     .node
303:                     .property70(name)
304:                     .and_then(|property| property.props.get(4))
305:                     .and_then(Prop::as_f64)
306:                 {
307:                     channel.default[index] = value;
308:                 }
309:             }
310:         }
311: 
312:         for (curve, property) in self.children_with_property(curve_node) {
313:             if curve.kind != "AnimationCurve" {
314:                 continue;
315:             }
316:             let Some(times) = curve
317:                 .node
318:                 .child("KeyTime")
319:                 .and_then(|node| node.i64_array())
320:             else {
321:                 continue;
322:             };
323:             let Some(values) = curve
324:                 .node
325:                 .child("KeyValueFloat")
326:                 .and_then(|node| node.props.first().and_then(Prop::as_f64_array))
327:             else {
328:                 continue;
329:             };
330:             let count = times.len().min(values.len());
331:             let curve = Curve {
332:                 times: times[..count]
333:                     .iter()
334:                     .map(|t| ticks_to_seconds(*t))
335:                     .collect(),
336:                 values: values[..count].to_vec(),
337:             };
338:             match property {
339:                 Some("d|X") => channel.x = curve,
340:                 Some("d|Y") => channel.y = curve,
341:                 Some("d|Z") => channel.z = curve,
342:                 _ => {}
343:             }
344:         }
345: 
346:         channel
347:     }
348: }
349: 
350: fn ticks_to_seconds(ticks: i64) -> f64 {
351:     ticks as f64 / TICKS_PER_SECOND
352: }
