  5: // These fields are native serialized FBX fixture metadata, before admission.
  6: fn compressed(payload: &[u8]) -> Vec<u8> {
  7:     let mut encoder = ZlibEncoder::new(Vec::new(), Compression::default());
  8:     encoder.write_all(payload).unwrap();
  9:     encoder.finish().unwrap()
 10: }
 11: 
 12: fn file(tag: u8, count: u32, encoding: u32, raw: &[u8]) -> Vec<u8> {
 13:     let mut property = vec![tag];
 14:     for value in [count, encoding, raw.len() as u32] {
 15:         property.extend(value.to_le_bytes());
 16:     }
 17:     property.extend(raw);
 18:     let mut bytes = b"Kaydara FBX Binary  \0\x1a\0".to_vec();
 19:     bytes.extend(7400u32.to_le_bytes());
 20:     let end = (27 + 13 + 4 + property.len() + 13) as u32;
 21:     for value in [end, 1, property.len() as u32] {
 22:         bytes.extend(value.to_le_bytes());
 23:     }
 24:     bytes.push(4);
 25:     bytes.extend(b"Root");
 26:     bytes.extend(property);
 27:     bytes.resize(bytes.len() + 13, 0);
 28:     bytes
 29: }
