 31: fn value(prop: &Prop) -> String {
 32:     match prop {
 33:         Prop::ArrF32(values) => format!(
 34:             "f32bits:{:?}",
 35:             values.iter().map(|v| v.to_bits()).collect::<Vec<_>>()
 36:         ),
 37:         Prop::ArrF64(values) => format!(
 38:             "f64bits:{:?}",
 39:             values.iter().map(|v| v.to_bits()).collect::<Vec<_>>()
 40:         ),
 41:         Prop::ArrI32(values) => format!("i32:{values:?}"),
 42:         Prop::ArrI64(values) => format!("i64:{values:?}"),
 43:         Prop::ArrBool(values) => format!("bool-bytes:{values:?}"),
 44:         other => format!("other:{other:?}"),
 45:     }
 46: }
 47: 
 48: fn snapshot(bytes: &[u8]) -> String {
 49:     match parse(bytes) {
 50:         Ok(nodes) => nodes
 51:             .iter()
 52:             .map(|node| {
 53:                 format!(
 54:                     "name={:?};children={};props={:?}",
 55:                     node.name,
 56:                     node.children.len(),
 57:                     node.props.iter().map(value).collect::<Vec<_>>()
 58:                 )
 59:             })
 60:             .collect::<Vec<_>>()
 61:             .join("|"),
 62:         Err(error) => format!("error:{error:#}"),
 63:     }
 64: }
 65: 
 66: fn observe() -> String {
 67:     let mut f32s = (-0.0f32).to_bits().to_le_bytes().to_vec();
 68:     f32s.extend(0x7fc0_1234u32.to_le_bytes());
 69:     let mut f64s = (-0.0f64).to_bits().to_le_bytes().to_vec();
 70:     f64s.extend(0x7ff8_0000_0000_4321u64.to_le_bytes());
 71:     let mut i32s = (-17i32).to_le_bytes().to_vec();
 72:     i32s.extend(i32::MAX.to_le_bytes());
 73:     let mut i64s = i64::MIN.to_le_bytes().to_vec();
 74:     i64s.extend(99i64.to_le_bytes());
 75:     let kinds = [
 76:         (b'f', f32s),
 77:         (b'd', f64s),
 78:         (b'i', i32s),
 79:         (b'l', i64s),
 80:         (b'b', vec![0, 127]),
 81:     ];
 82:     let mut out = String::new();
 83:     for (tag, payload) in kinds {
 84:         for encoding in [0, 1, 7, u32::MAX] {
 85:             let mut extra = payload.clone();
 86:             extra.extend([0x33; 9]);
 87:             for (label, count, decoded) in [
 88:                 ("normal", 2, payload.as_slice()),
 89:                 ("empty", 0, [].as_slice()),
 90:                 ("short", 2, [0x7f].as_slice()),
 91:                 ("extra", 2, extra.as_slice()),
 92:             ] {
 93:                 let raw = if encoding == 0 {
 94:                     decoded.to_vec()
 95:                 } else {
 96:                     compressed(decoded)
 97:                 };
 98:                 out.push_str(&format!(
 99:                     "{}-{encoding}-{label}:{}\n",
100:                     char::from(tag),
101:                     snapshot(&file(tag, count, encoding, &raw))
102:                 ));
103:             }
104:             if encoding != 0 {
105:                 out.push_str(&format!(
106:                     "{}-{encoding}-corrupt:{}\n",
107:                     char::from(tag),
108:                     snapshot(&file(tag, 2, encoding, &[0xff, 0xff]))
109:                 ));
110:             }
111:         }
112:     }
113:     out
114: }
