 22: pub use animation::{
 23:     Curve, FbxAnimationDuration, InvalidFbxAnimationDuration, NodeAnimation, Take, TransformChannel,
 24: };
 25: pub use array_encoding::UnsupportedFbxArrayEncoding;
 26: pub use object_name::{FbxObjectName, FbxQualifiedName};
 27: 
 28: pub mod animation;
 29: mod array_encoding;
 30: mod object_name;
 31: 
 32: /// One node record of the FBX tree.
 33: #[derive(Debug, Clone)]
 34: pub struct Node {
 35:     pub name: String,
 36:     pub props: Vec<Prop>,
 37:     pub children: Vec<Node>,
 38: }
 39: 
 40: struct Reader<'a> {
 41:     data: &'a [u8],
 42:     pos: usize,
 43:     version: u32,
 44: }
 45: 
 46: /// An entry of the `Objects` block.
 47: #[derive(Debug)]
 48: pub struct Object {
 49:     pub id: i64,
 50:     /// Object name with the `\0\x01Class` suffix and any `namespace:` prefix removed.
 51:     pub name: FbxObjectName,
 52:     /// Object name with its namespace intact, e.g. `mixamorig:Hips`.
 53:     ///
 54:     /// Rig profiles are usually written against the namespaced name, so an
 55:     /// importer wants this one even though momentum matches on the stripped one.
 56:     pub qualified: FbxQualifiedName,
 57:     /// The sub-class token, e.g. `LimbNode`, `Mesh`, `Cluster`, `BlendShapeChannel`.
 58:     pub class: String,
 59:     /// The record name, e.g. `Model`, `Geometry`, `Deformer`.
 60:     pub kind: String,
 61:     pub node: Node,
 62: }
 63: 
 64: /// One entry of the connection list.
 65: #[derive(Debug, Clone)]
 66: pub struct Link {
 67:     /// The object being connected in.
 68:     pub from: i64,
 69:     /// The property it connects to, for object-property (`OP`) links.
 70:     ///
 71:     /// Animation is addressed entirely through these: a curve node connects to
 72:     /// a model's `Lcl Rotation`, and a curve connects to that node's `d|X`.
 73:     pub property: Option<String>,
 74: }
 75: 
 76: /// The object table plus the connection graph of an FBX file.
 77: pub struct Scene {
 78:     pub objects: Vec<Object>,
 79:     /// The file's top-level records, kept for `GlobalSettings` and friends.
 80:     pub roots: Vec<Node>,
 81:     by_id: HashMap<i64, usize>,
 82:     /// Incoming links per object id, in file order (id 0 is the scene root).
 83:     links: HashMap<i64, Vec<Link>>,
 84: }
