 86: /// A typed FBX property value.
 87: #[derive(Debug, Clone)]
 88: pub enum Prop {
 89:     I16(i16),
 90:     Bool(bool),
 91:     I32(i32),
 92:     I64(i64),
 93:     F32(f32),
 94:     F64(f64),
 95:     ArrF32(Vec<f32>),
 96:     ArrF64(Vec<f64>),
 97:     ArrI32(Vec<i32>),
 98:     ArrI64(Vec<i64>),
 99:     ArrBool(Vec<u8>),
100:     /// FBX strings are not UTF-8 in general; object names embed a `\0\x01` separator.
101:     Str(Vec<u8>),
102:     Raw(Vec<u8>),
103: }
