105: impl Prop {
106:     pub fn as_i64(&self) -> Option<i64> {
107:         match self {
108:             Prop::I16(v) => Some(*v as i64),
109:             Prop::I32(v) => Some(*v as i64),
110:             Prop::I64(v) => Some(*v),
111:             Prop::Bool(v) => Some(*v as i64),
112:             _ => None,
113:         }
114:     }
115: 
116:     pub fn as_f64(&self) -> Option<f64> {
117:         match self {
118:             Prop::F32(v) => Some(*v as f64),
119:             Prop::F64(v) => Some(*v),
120:             Prop::I16(v) => Some(*v as f64),
121:             Prop::I32(v) => Some(*v as f64),
122:             Prop::I64(v) => Some(*v as f64),
123:             _ => None,
124:         }
125:     }
126: 
127:     pub fn as_str(&self) -> Option<&[u8]> {
128:         match self {
129:             Prop::Str(v) | Prop::Raw(v) => Some(v),
130:             _ => None,
131:         }
132:     }
133: 
134:     /// Numeric array widened to `f64`, whatever the on-disk element type.
135:     pub fn as_f64_array(&self) -> Option<Vec<f64>> {
136:         match self {
137:             Prop::ArrF32(v) => Some(v.iter().map(|x| *x as f64).collect()),
138:             Prop::ArrF64(v) => Some(v.clone()),
139:             Prop::ArrI32(v) => Some(v.iter().map(|x| *x as f64).collect()),
140:             Prop::ArrI64(v) => Some(v.iter().map(|x| *x as f64).collect()),
141:             _ => None,
142:         }
143:     }
144: 
145:     /// Integer array widened to `i64`, whatever the on-disk element type.
146:     pub fn as_i64_array(&self) -> Option<Vec<i64>> {
147:         match self {
148:             Prop::ArrI32(v) => Some(v.iter().map(|x| *x as i64).collect()),
149:             Prop::ArrI64(v) => Some(v.clone()),
150:             Prop::ArrBool(v) => Some(v.iter().map(|x| *x as i64).collect()),
151:             _ => None,
152:         }
153:     }
154: }
