169:     /// First property as a numeric array, widened to `f64`.
170:     pub fn f64_array(&self) -> Option<Vec<f64>> {
171:         self.props.first()?.as_f64_array()
172:     }
173: 
174:     /// First property as an integer array, widened to `i64`.
175:     pub fn i64_array(&self) -> Option<Vec<i64>> {
176:         self.props.first()?.as_i64_array()
177:     }
178: 
179:     pub fn str_prop(&self, index: usize) -> Option<&[u8]> {
180:         self.props.get(index)?.as_str()
181:     }
182: 
183:     /// Look up an entry of this node's `Properties70` block by name.
184:     ///
185:     /// Mirrors OpenFBX `resolveProperty`: a `P` record whose first property is

186:     /// the requested name; values start at index 4.
187:     pub fn property70(&self, name: &str) -> Option<&Node> {
188:         let props = self.child("Properties70")?;
189:         props.children.iter().find(|p| {
190:             p.props
191:                 .first()
192:                 .and_then(|v| v.as_str())
193:                 .is_some_and(|v| v == name.as_bytes())
194:         })
195:     }
196: 
197:     /// A three-component `Properties70` value such as `Lcl Translation`.
198:     pub fn property70_vec3(&self, name: &str, default: [f64; 3]) -> [f64; 3] {
199:         let Some(p) = self.property70(name) else {
200:             return default;
201:         };
202:         let mut out = default;
203:         for (i, slot) in out.iter_mut().enumerate() {
204:             match p.props.get(4 + i).and_then(Prop::as_f64) {
205:                 Some(v) => *slot = v,
206:                 None => return default,
207:             }
208:         }
209:         out
210:     }
211: 
212:     /// A scalar integer `Properties70` value such as `RotationOrder`.
213:     pub fn property70_i64(&self, name: &str, default: i64) -> i64 {
214:         self.property70(name)
215:             .and_then(|p| p.props.get(4))
216:             .and_then(Prop::as_i64)
217:             .unwrap_or(default)
218:     }
219: }
