221: impl<'a> Reader<'a> {
222:     fn take(&mut self, len: usize) -> Result<&'a [u8]> {
223:         let end = self
224:             .pos
225:             .checked_add(len)
226:             .ok_or_else(|| anyhow!("FBX read overflow"))?;
227:         if end > self.data.len() {
228:             bail!(
229:                 "truncated FBX file: wanted {len} bytes at offset {}",
230:                 self.pos
231:             );
232:         }
233:         let slice = &self.data[self.pos..end];
234:         self.pos = end;
235:         Ok(slice)
236:     }
237: 
238:     fn u8(&mut self) -> Result<u8> {
239:         Ok(self.take(1)?[0])
240:     }
241: 
242:     fn u32(&mut self) -> Result<u32> {
243:         Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
244:     }
245: 
246:     fn u64(&mut self) -> Result<u64> {
247:         Ok(u64::from_le_bytes(self.take(8)?.try_into().unwrap()))
248:     }
249: 
250:     /// Node headers went 32-bit -> 64-bit in FBX 7500.
251:     fn header_word(&mut self) -> Result<u64> {
252:         if self.version >= 7500 {
253:             self.u64()
254:         } else {
255:             Ok(self.u32()? as u64)
256:         }
257:     }
258: 
259:     fn header_size(&self) -> usize {
260:         // 3 header words + the 1-byte name length.
261:         if self.version >= 7500 { 25 } else { 13 }
262:     }
263: }
