281: impl Scene {
282:     pub fn from_roots(roots: Vec<Node>) -> Result<Self> {
283:         let mut objects = Vec::new();
284:         let mut by_id = HashMap::new();
285:         let mut links: HashMap<i64, Vec<Link>> = HashMap::new();
286: 
287:         for root in &roots {
288:             if root.name != "Objects" {
289:                 continue;
290:             }
291:             for node in &root.children {
292:                 let Some(id) = node.props.first().and_then(Prop::as_i64) else {
293:                     continue;
294:                 };
295:                 let qualified = node
296:                     .str_prop(1)
297:                     .map(FbxQualifiedName::from)
298:                     .unwrap_or_default();
299:                 let name = FbxObjectName::from(&qualified);
300:                 let class = node
301:                     .str_prop(2)
302:                     .map(|c| String::from_utf8_lossy(c).into_owned())
303:                     .unwrap_or_default();
304:                 by_id.insert(id, objects.len());
305:                 objects.push(Object {
306:                     id,
307:                     name,
308:                     qualified,
309:                     class,
310:                     kind: node.name.clone(),
311:                     node: node.clone(),
312:                 });
313:             }
314:         }
315: 
316:         for root in &roots {
317:             if root.name != "Connections" {
318:                 continue;
319:             }
320:             for c in &root.children {
321:                 // C: [type, from, to, (property name)]
322:                 let (Some(from), Some(to)) = (
323:                     c.props.get(1).and_then(Prop::as_i64),
324:                     c.props.get(2).and_then(Prop::as_i64),
325:                 ) else {
326:                     continue;
327:                 };
328:                 if from == 0 {
329:                     continue;
330:                 }
331:                 let property = c
332:                     .props
333:                     .get(3)
334:                     .and_then(Prop::as_str)
335:                     .map(|name| String::from_utf8_lossy(name).into_owned());
336:                 links.entry(to).or_default().push(Link { from, property });
337:             }
338:         }
339: 
340:         Ok(Self {
341:             objects,
342:             roots,
343:             by_id,
344:             links,
345:         })
346:     }
347: 
348:     pub fn parse(data: &[u8]) -> Result<Self> {
349:         Self::from_roots(parse(data)?)
350:     }
351: 
352:     pub fn get(&self, id: i64) -> Option<&Object> {
353:         self.by_id.get(&id).map(|i| &self.objects[*i])
354:     }
355: 
356:     /// A top-level record such as `GlobalSettings` or `Definitions`.
357:     pub fn root(&self, name: &str) -> Option<&Node> {
358:         self.roots.iter().find(|root| root.name == name)
359:     }
360: 
361:     /// Objects connected as children of `id`, in file order. This is OpenFBX's
362:     /// `resolveObjectLink` ordering, which fixes the joint order of the rig.
363:     pub fn children(&self, id: i64) -> impl Iterator<Item = &Object> {
364:         self.incoming(id).filter_map(|link| self.get(link.from))
365:     }
366: 
367:     /// As [`Scene::children`], keeping the property each link targets.
368:     pub fn children_with_property(&self, id: i64) -> impl Iterator<Item = (&Object, Option<&str>)> {
369:         self.incoming(id).filter_map(|link| {
370:             self.get(link.from)

371:                 .map(|object| (object, link.property.as_deref()))
372:         })
373:     }
374: 
375:     fn incoming(&self, id: i64) -> impl Iterator<Item = &Link> {
376:         self.links.get(&id).map(Vec::as_slice).unwrap_or(&[]).iter()
377:     }
378: 
379:     /// The first child of `id` whose record name and class match.
380:     pub fn child_of_kind(&self, id: i64, kind: &str, class: &str) -> Option<&Object> {
381:         self.children(id)
382:             .find(|o| o.kind == kind && o.class == class)
383:     }
384: 
385:     pub fn objects_of_kind<'a>(
386:         &'a self,
387:         kind: &'a str,
388:         class: &'a str,
389:     ) -> impl Iterator<Item = &'a Object> {
390:         self.objects
391:             .iter()
392:             .filter(move |o| o.kind == kind && o.class == class)
393:     }
394: }
