396: /// Parses the top-level node list of a binary FBX file.
397: pub fn parse(data: &[u8]) -> Result<Vec<Node>> {
398:     const MAGIC: &[u8] = b"Kaydara FBX Binary  \x00";
399:     if data.len() < 27 || &data[..MAGIC.len()] != MAGIC {
400:         // ASCII FBX is a different format sharing the extension. Saying so is
401:         // more use than "not a binary FBX file", because the fix is a re-export.
402:         if data.starts_with(b"; FBX") || data.starts_with(b"\xef\xbb\xbf; FBX") {
403:             bail!("this is an ASCII FBX file; re-export it as binary FBX");
404:         }
405:         bail!("not a binary FBX file");
406:     }
407:     let version = u32::from_le_bytes(data[23..27].try_into().unwrap());
408:     let mut reader = Reader {
409:         data,
410:         pos: 27,
411:         version,
412:     };
413: 
414:     let mut roots = Vec::new();
415:     while reader.pos + reader.header_size() <= data.len() {
416:         match read_node(&mut reader)? {
417:             Some(node) => roots.push(node),
418:             None => break,
419:         }
420:     }
421:     Ok(roots)
422: }
423: 
424: fn decode_array<T: Copy>(
425:     raw: &[u8],
426:     count: usize,
427:     encoding: FbxArrayEncoding,
428:     parse: impl Fn(&[u8]) -> T,
429:     width: usize,
430: ) -> Result<Vec<T>> {
431:     let bytes = match encoding {
432:         FbxArrayEncoding::Uncompressed => raw.to_vec(),
433:         FbxArrayEncoding::Zlib => {
434:             let mut out = Vec::with_capacity(count * width);
435:             ZlibDecoder::new(raw)
436:                 .read_to_end(&mut out)
437:                 .context("inflating FBX array property")?;
438:             out
439:         }
440:     };
441:     if bytes.len() < count * width {
442:         bail!(
443:             "FBX array property is short: {} bytes for {count} x {width}",
444:             bytes.len()
445:         );
446:     }
447:     Ok((0..count)
448:         .map(|i| parse(&bytes[i * width..(i + 1) * width]))
449:         .collect())
450: }
451: 
452: fn read_props(reader: &mut Reader<'_>, count: usize) -> Result<Vec<Prop>> {
453:     let mut props = Vec::with_capacity(count);
454:     for _ in 0..count {
455:         let kind = reader.u8()?;
456:         let prop = match kind {
457:             b'Y' => Prop::I16(i16::from_le_bytes(reader.take(2)?.try_into().unwrap())),
458:             b'C' => Prop::Bool(reader.u8()? != 0),
459:             b'I' => Prop::I32(i32::from_le_bytes(reader.take(4)?.try_into().unwrap())),
460:             b'F' => Prop::F32(f32::from_le_bytes(reader.take(4)?.try_into().unwrap())),
461:             b'D' => Prop::F64(f64::from_le_bytes(reader.take(8)?.try_into().unwrap())),
462:             b'L' => Prop::I64(i64::from_le_bytes(reader.take(8)?.try_into().unwrap())),
463:             b'f' | b'd' | b'l' | b'i' | b'b' => {
464:                 let count = reader.u32()? as usize;
465:                 // FBX array metadata stores encoding as a little-endian u32.
466:                 // Admit only supported encodings before decoding the payload.
467:                 let encoding = FbxArrayEncoding::try_from(reader.u32()?)?;
468:                 let compressed_len = reader.u32()? as usize;
469:                 let raw = reader.take(compressed_len)?;
470:                 match kind {
471:                     b'f' => Prop::ArrF32(decode_array(
472:                         raw,
473:                         count,
474:                         encoding,
475:                         |b| f32::from_le_bytes(b.try_into().unwrap()),
476:                         4,
477:                     )?),
478:                     b'd' => Prop::ArrF64(decode_array(
479:                         raw,
480:                         count,
481:                         encoding,
482:                         |b| f64::from_le_bytes(b.try_into().unwrap()),
483:                         8,
484:                     )?),
485:                     b'i' => Prop::ArrI32(decode_array(
486:                         raw,
487:                         count,
488:                         encoding,
489:                         |b| i32::from_le_bytes(b.try_into().unwrap()),
490:                         4,
491:                     )?),
492:                     b'l' => Prop::ArrI64(decode_array(
493:                         raw,
494:                         count,
495:                         encoding,
496:                         |b| i64::from_le_bytes(b.try_into().unwrap()),
497:                         8,
498:                     )?),
499:                     _ => Prop::ArrBool(decode_array(raw, count, encoding, |b| b[0], 1)?),
500:                 }
501:             }
502:             b'S' => {
503:                 let len = reader.u32()? as usize;
504:                 Prop::Str(reader.take(len)?.to_vec())
505:             }
506:             b'R' => {
507:                 let len = reader.u32()? as usize;
508:                 Prop::Raw(reader.take(len)?.to_vec())
509:             }
510:             other => bail!("unknown FBX property type {:?}", other as char),
511:         };
512:         props.push(prop);
513:     }
514:     Ok(props)
515: }
516: 
517: /// Reads one node record. Returns `None` for the null record that terminates a list.
518: fn read_node(reader: &mut Reader<'_>) -> Result<Option<Node>> {
519:     let end_offset = reader.header_word()? as usize;
520:     let num_props = reader.header_word()? as usize;
521:     let _prop_list_len = reader.header_word()?;
522:     let name_len = reader.u8()? as usize;
523:     let name = String::from_utf8_lossy(reader.take(name_len)?).into_owned();
524: 
525:     if end_offset == 0 {
526:         return Ok(None);
527:     }
528: 
529:     let props = read_props(reader, num_props)?;
530: 
531:     let mut children = Vec::new();
532:     let sentinel = reader.header_size();
533:     while reader.pos + sentinel <= end_offset {
534:         match read_node(reader)? {
535:             Some(child) => children.push(child),
536:             None => break,
537:         }
538:     }
539:     reader.pos = end_offset;
540: 
541:     Ok(Some(Node {
542:         name,
543:         props,
544:         children,
545:     }))
546: }
