 19: /// An insertion-ordered map -- YAML and the pattern JSON both care about key
 20: /// order, and `HashMap` would scramble it.
 21: #[derive(Debug, Clone, Default, PartialEq)]
 22: pub struct OrderedMap {
 23:     entries: Vec<(String, Value)>,
 24: }
 25: 
 26: impl OrderedMap {
 27:     pub fn new() -> Self {
 28:         Self::default()
 29:     }
 30: 
 31:     pub fn get(&self, key: &str) -> Option<&Value> {
 32:         self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
 33:     }
 34: 
 35:     pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
 36:         self.entries
 37:             .iter_mut()
 38:             .find(|(k, _)| k == key)
 39:             .map(|(_, v)| v)
 40:     }
 41: 
 42:     pub fn insert(&mut self, key: impl Into<String>, value: Value) {
 43:         let key = key.into();
 44:         match self.get_mut(&key) {
 45:             Some(slot) => *slot = value,
 46:             None => self.entries.push((key, value)),
 47:         }
 48:     }
 49: 
 50:     pub fn keys(&self) -> impl Iterator<Item = &str> {
 51:         self.entries.iter().map(|(k, _)| k.as_str())
 52:     }
 53: 
 54:     pub fn iter(&self) -> impl Iterator<Item = (&str, &Value)> {
 55:         self.entries.iter().map(|(k, v)| (k.as_str(), v))
 56:     }
 57: 
 58:     pub fn len(&self) -> usize {
 59:         self.entries.len()
 60:     }
 61: 
 62:     pub fn is_empty(&self) -> bool {
 63:         self.entries.is_empty()
 64:     }
 65: }
