 67: #[derive(Debug, Clone, PartialEq)]
 68: pub enum Value {
 69:     Null,
 70:     Bool(bool),
 71:     Int(i64),
 72:     Float(f64),
 73:     Str(String),
 74:     List(Vec<Value>),
 75:     Map(OrderedMap),
 76: }
 77: 
 78: impl Value {
 79:     pub fn as_f64(&self) -> Option<f64> {
 80:         match self {
 81:             Value::Float(f) => Some(*f),
 82:             Value::Int(i) => Some(*i as f64),
 83:             Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
 84:             _ => None,
 85:         }
 86:     }
 87: 
 88:     pub fn as_i64(&self) -> Option<i64> {
 89:         match self {
 90:             Value::Int(i) => Some(*i),
 91:             Value::Float(f) => Some(*f as i64),
 92:             _ => None,
 93:         }
 94:     }
 95: 
 96:     pub fn as_bool(&self) -> Option<bool> {
 97:         match self {
 98:             Value::Bool(b) => Some(*b),
 99:             _ => None,
100:         }
101:     }
102: 
103:     pub fn as_str(&self) -> Option<&str> {
104:         match self {
105:             Value::Str(s) => Some(s.as_str()),
106:             _ => None,
107:         }
108:     }
109: 
110:     pub fn as_map(&self) -> Option<&OrderedMap> {
111:         match self {
112:             Value::Map(m) => Some(m),
113:             _ => None,
114:         }
115:     }
116: 
117:     pub fn is_null(&self) -> bool {
118:         matches!(self, Value::Null)
119:     }
120: }
121: 
122: fn from_yaml(v: &serde_yaml::Value) -> Value {
123:     match v {
124:         serde_yaml::Value::Null => Value::Null,
125:         serde_yaml::Value::Bool(b) => Value::Bool(*b),
126:         serde_yaml::Value::Number(n) => {
127:             if let Some(i) = n.as_i64() {
128:                 Value::Int(i)
129:             } else {
130:                 Value::Float(n.as_f64().unwrap_or(f64::NAN))
131:             }
132:         }
133:         serde_yaml::Value::String(s) => Value::Str(s.clone()),
134:         serde_yaml::Value::Sequence(s) => Value::List(s.iter().map(from_yaml).collect()),
135:         serde_yaml::Value::Mapping(m) => {
136:             let mut out = OrderedMap::new();
137:             for (k, v) in m {
138:                 let key = match k {
139:                     serde_yaml::Value::String(s) => s.clone(),
140:                     other => format!("{other:?}"),
141:                 };
142:                 out.insert(key, from_yaml(v));
143:             }
144:             Value::Map(out)
145:         }
146:         serde_yaml::Value::Tagged(t) => from_yaml(&t.value),
147:     }
148: }
