115:     async fn get_file(&self, name: &str, create: bool) -> Result<Box<dyn FileEntry>> {
116:         let path = self.path.join(name);
117:         if create && !path.exists() {
118:             std::fs::File::create(&path).map_err(|e| anyhow!("Create failed: {}", e))?;
119:         }
120:         Ok(Box::new(NativeFile { path }))
121:     }
122:     async fn get_directory(&self, name: &str, create: bool) -> Result<Box<dyn DirectoryEntry>> {
123:         let path = self.path.join(name);
124:         if create && !path.exists() {
125:             std::fs::create_dir_all(&path).map_err(|e| anyhow!("CreateDir failed: {}", e))?;
126:         }
127:         Ok(Box::new(NativeDirectory { path }))
128:     }
129:     async fn delete_entry(&self, name: &str) -> Result<()> {
130:         let path = self.path.join(name);
131:         if path.is_file() {
132:             std::fs::remove_file(path).map_err(|e| anyhow!("Delete file failed: {}", e))
133:         } else {
134:             std::fs::remove_dir_all(path).map_err(|e| anyhow!("Delete dir failed: {}", e))
135:         }
136:     }
137:     fn as_any(&self) -> &dyn std::any::Any {
138:         self
139:     }
140: }
