171:     }
172:     fn path(&self) -> String {
173:         self.handle.0.name()
174:     }
175:     async fn read(&self) -> Result<Vec<u8>> {
176:         use wasm_bindgen_futures::JsFuture;
177:         let file_promise = self.handle.0.get_file();
178:         let file_value = JsFuture::from(file_promise)
179:             .await
180:             .map_err(|e| anyhow!("GetFile failed: {:?}", e))?;
181:         let file = web_sys::File::from(file_value);
182:         let array_buffer_promise = file.array_buffer();
183:         let array_buffer_value = JsFuture::from(array_buffer_promise)
184:             .await
185:             .map_err(|e| anyhow!("ArrayBuffer failed: {:?}", e))?;
186:         let array_buffer = js_sys::ArrayBuffer::from(array_buffer_value);
187:         Ok(js_sys::Uint8Array::new(&array_buffer).to_vec())
188:     }
189:     async fn write(&self, data: &[u8]) -> Result<()> {
190:         use wasm_bindgen_futures::JsFuture;
191:         let writable_promise = self.handle.0.create_writable();
192:         let writable_value = JsFuture::from(writable_promise)
193:             .await
194:             .map_err(|e| anyhow!("CreateWritable failed: {:?}", e))?;
195:         let writable = web_sys::FileSystemWritableFileStream::from(writable_value);
196: 
197:         let uint8_array = js_sys::Uint8Array::from(data);
198:         JsFuture::from(
199:             writable
200:                 .write_with_buffer_source(&uint8_array)
201:                 .map_err(|e| anyhow!("Write failed: {:?}", e))?,
202:         )
203:         .await
204:         .map_err(|e| anyhow!("Write await failed: {:?}", e))?;
205:         JsFuture::from(writable.close())
206:             .await
207:             .map_err(|e| anyhow!("Close failed: {:?}", e))?;
208:         Ok(())
209:     }
210: }
