221: impl DirectoryEntry for WebDirectory {
222:     fn name(&self) -> String {
223:         self.handle.0.name()
224:     }
225:     fn path(&self) -> String {
226:         self.handle.0.name()
227:     }
228:     async fn list_entries(&self) -> Result<Vec<Entry>> {
229:         use wasm_bindgen::JsCast;
230:         use wasm_bindgen_futures::JsFuture;
231: 
232:         let mut entries = Vec::new();
233:         let iterator = self.handle.0.values();
234:         loop {
235:             let next_promise = iterator
236:                 .next()
237:                 .map_err(|e| anyhow!("Next failed: {:?}", e))?;
238:             let next_value = JsFuture::from(next_promise)
239:                 .await
240:                 .map_err(|e| anyhow!("Next await failed: {:?}", e))?;
241:             let next_obj = js_sys::Object::from(next_value);
242:             let done = js_sys::Reflect::get(&next_obj, &"done".into())
243:                 .unwrap()
244:                 .as_bool()
245:                 .unwrap_or(true);
246:             if done {
247:                 break;
248:             }
249: 
250:             let value = js_sys::Reflect::get(&next_obj, &"value".into()).unwrap();
251:             let handle = web_sys::FileSystemHandle::from(value);
252: 
253:             let kind = js_sys::Reflect::get(&handle, &"kind".into())
254:                 .unwrap()
255:                 .as_string()
256:                 .unwrap_or_default();
257: 
258:             if kind == "file" {
259:                 entries.push(Entry::File(Box::new(WebFile {
260:                     handle: SendFileHandle(handle.dyn_into().unwrap()),
261:                 })));
262:             } else {
263:                 entries.push(Entry::Directory(Box::new(WebDirectory {
264:                     handle: SendDirectoryHandle(handle.dyn_into().unwrap()),
265:                 })));
266:             }
267:         }
268:         Ok(entries)
269:     }
270:     async fn get_file(&self, name: &str, create: bool) -> Result<Box<dyn FileEntry>> {
271:         use wasm_bindgen_futures::JsFuture;
272:         let options = js_sys::Object::new();
273:         js_sys::Reflect::set(&options, &"create".into(), &create.into()).ok();
274: 
275:         let promise = extGetFileHandle(&self.handle.0, name, &options.unchecked_into())
276:             .map_err(|e| anyhow!("extGetFileHandle failed: {:?}", e))?;
277:         let value = JsFuture::from(promise)
278:             .await
279:             .map_err(|e| anyhow!("GetFileHandle failed: {:?}", e))?;
280:         Ok(Box::new(WebFile {
281:             handle: SendFileHandle(value.into()),
282:         }))
283:     }
284:     async fn get_directory(&self, name: &str, create: bool) -> Result<Box<dyn DirectoryEntry>> {
285:         use wasm_bindgen_futures::JsFuture;
286:         let options = js_sys::Object::new();
287:         js_sys::Reflect::set(&options, &"create".into(), &create.into()).ok();
288: 
289:         let promise = extGetDirectoryHandle(&self.handle.0, name, &options.unchecked_into())
290:             .map_err(|e| anyhow!("extGetDirectoryHandle failed: {:?}", e))?;
291:         let value = JsFuture::from(promise)
292:             .await
293:             .map_err(|e| anyhow!("GetDirectoryHandle failed: {:?}", e))?;
294:         Ok(Box::new(WebDirectory {
295:             handle: SendDirectoryHandle(value.into()),
296:         }))
297:     }
298:     async fn delete_entry(&self, name: &str) -> Result<()> {
299:         use wasm_bindgen_futures::JsFuture;
300:         let promise = self.handle.0.remove_entry(name);
301:         JsFuture::from(promise)
302:             .await
303:             .map_err(|e| anyhow!("RemoveEntry failed: {:?}", e))?;
304:         Ok(())
305:     }
306:     fn as_any(&self) -> &dyn std::any::Any {
307:         self
308:     }
309: }
