320:     #[wasm_bindgen(js_name = showOpenFilePicker)]

161:     pub fn from_value(v: Value) -> Self {
162:         Self {
163:             root: Rc::new(RefCell::new(v)),
164:             path: Vec::new(),
165:         }
166:     }
167: 
168:     /// Load the `design:` section of a YAML file.
169:     pub fn load(path: impl AsRef<Path>) -> Result<Self> {
170:         let path = path.as_ref();
171:         let text = std::fs::read_to_string(path)
172:             .with_context(|| format!("reading design file {}", path.display()))?;
173:         Self::from_yaml_str(&text)
174:             .with_context(|| format!("reading design file {}", path.display()))
175:     }
176: 
177:     /// The same, from YAML already in memory -- what a front-end that keeps the
178:     /// design in a text buffer (or bundles it through [`crate::assets`]) needs.
179:     pub fn from_yaml_str(text: &str) -> Result<Self> {
180:         let yaml: serde_yaml::Value = serde_yaml::from_str(text).context("parsing the design")?;
181:         let design = yaml
182:             .get("design")
183:             .ok_or_else(|| anyhow!("missing top-level 'design' key"))?;
184:         Ok(Self::from_value(from_yaml(design)))
185:     }
186: 
187:     /// A handle to a sub-tree. The tree itself is shared, not copied.
188:     pub fn sub(&self, key: &str) -> Design {
189:         let mut path = self.path.clone();
190:         path.extend(key.split('.').map(|s| s.to_string()));
191:         Design {
192:             root: Rc::clone(&self.root),
193:             path,
194:         }
195:     }
196: 
197:     fn resolve(&self, extra: &[&str]) -> Option<Value> {
198:         let root = self.root.borrow();
199:         let mut cur: &Value = &root;
200:         for key in self
201:             .path
202:             .iter()
203:             .map(|s| s.as_str())
204:             .chain(extra.iter().copied())
205:         {
206:             cur = cur.as_map()?.get(key)?;
207:         }
208:         Some(cur.clone())
209:     }
210: 
211:     fn split(key: &str) -> Vec<&str> {
212:         key.split('.').collect()
213:     }
214: 
215:     /// Raw node at `key` (dot-separated), without unwrapping `v`.
216:     pub fn node(&self, key: &str) -> Option<Value> {
217:         self.resolve(&Self::split(key))
218:     }
219: 
220:     pub fn contains(&self, key: &str) -> bool {
221:         self.node(key).is_some()
222:     }
223: 
224:     fn value_of(&self, key: &str) -> Value {
225:         let mut parts = Self::split(key);
226:         parts.push("v");
227:         self.resolve(&parts).unwrap_or_else(|| {
228:             panic!(
229:                 "Design::ERROR::missing parameter '{}' under {:?}",
230:                 key, self.path
231:             )
232:         })
233:     }
234: 
235:     /// Float parameter value (`design[..][key]['v']`).
236:     pub fn f(&self, key: &str) -> f64 {
237:         self.value_of(key)
238:             .as_f64()
239:             .unwrap_or_else(|| panic!("Design::ERROR::parameter '{key}' is not a number"))
240:     }
241: 
242:     /// Integer parameter value.
243:     pub fn i(&self, key: &str) -> i64 {
244:         self.value_of(key)
245:             .as_i64()
246:             .unwrap_or_else(|| panic!("Design::ERROR::parameter '{key}' is not an integer"))
247:     }
248: 
249:     /// Boolean parameter value.
250:     pub fn b(&self, key: &str) -> bool {
251:         self.value_of(key)
252:             .as_bool()
253:             .unwrap_or_else(|| panic!("Design::ERROR::parameter '{key}' is not a bool"))
254:     }
255: 
256:     /// String parameter value, `None` for a YAML `null` (a `select_null` type).
257:     pub fn s(&self, key: &str) -> Option<String> {
258:         match self.value_of(key) {
259:             Value::Str(s) => Some(s),
260:             Value::Null => None,
261:             other => panic!("Design::ERROR::parameter '{key}' is not a string: {other:?}"),
262:         }
263:     }
264: 
265:     /// Write a value into the tree, creating intermediate maps as needed.
266:     ///
267:     /// Used by the sleeve code, which injects the cuff width before building a
268:     /// cuff component -- the same in-place dictionary update the reference does.
269:     pub fn set_v(&self, key: &str, value: Value) {
270:         let mut root = self.root.borrow_mut();
271:         let mut cur: &mut Value = &mut root;
272:         let keys: Vec<String> = self
273:             .path
274:             .iter()
275:             .cloned()
276:             .chain(Self::split(key).iter().map(|s| s.to_string()))
277:             .chain(std::iter::once("v".to_string()))
278:             .collect();
279: 
280:         for (i, k) in keys.iter().enumerate() {
281:             if !matches!(cur, Value::Map(_)) {
282:                 *cur = Value::Map(OrderedMap::new());
283:             }
284:             let Value::Map(map) = cur else { unreachable!() };
285:             if map.get(k).is_none() {
286:                 map.insert(k.clone(), Value::Map(OrderedMap::new()));
287:             }
288:             let slot = map.get_mut(k).unwrap();
289:             if i == keys.len() - 1 {
290:                 *slot = value;
291:                 return;
292:             }
293:             cur = slot;
294:         }
295:     }
296: 
297:     /// Shorthand for `set_v(key, Value::Float(value))`.
298:     pub fn set_f(&self, key: &str, value: f64) {
299:         self.set_v(key, Value::Float(value));
300:     }
301: 
302:     /// A detached copy of the *whole* tree, rooted at the same path.
303:     ///
304:     /// Stands in for the reference's `deepcopy(design)`, which several garment
305:     /// programs use before recalculating derived parameters in place.
306:     pub fn deep_copy(&self) -> Design {
307:         Design {
308:             root: Rc::new(RefCell::new(self.root.borrow().clone())),
309:             path: self.path.clone(),
310:         }
311:     }
312: 
313:     /// Copy a value from one key to another within this tree.
314:     pub fn copy_v(&self, from: &str, to: &str) {
315:         let value = self.value_of(from);
316:         self.set_v(to, value);
317:     }
318: 
319:     /// Every parameter in the tree, in declaration order, with the schema the
320:     /// YAML declares next to it (`type` and `range`).

321:     ///
322:     /// This is what the reference's configurator GUI reads to build its
323:     /// controls, and what any other front-end needs for the same job: the
324:     /// design files are self-describing, so nothing here hard-codes a garment.
325:     pub fn params(&self) -> Vec<ParamSpec> {
326:         let mut out = Vec::new();
327:         if let Some(root) = self.resolve(&[]) {
328:             collect_params(&root, &mut Vec::new(), &mut out);
329:         }
330:         out
331:     }
332: 
333:     /// Serialise the tree back to the `design:` YAML the reference reads.
334:     pub fn to_yaml(&self) -> String {
335:         let root = self.resolve(&[]).unwrap_or(Value::Null);
336:         let mut out = String::from("design:\n");
337:         write_yaml(&root, 1, &mut out);
338:         out
339:     }
340: }
341: 
342: /// What kind of control a parameter wants, as declared by its `type:` key.
343: #[derive(Debug, Clone, PartialEq)]
344: pub enum ParamKind {
345:     /// `type: float`, bounded by `range`.
346:     Float { min: f64, max: f64 },
347:     /// `type: int`, bounded by `range`.
348:     Int { min: i64, max: i64 },
349:     /// `type: bool`.
350:     Bool,
351:     /// `type: select` / `select_null`. A `None` option is the YAML `null` that
352:     /// `select_null` allows, which the garment programs read as "absent".
353:     Select { options: Vec<Option<String>> },
354: }
355: 
356: /// One leaf of the design tree.
357: #[derive(Debug, Clone, PartialEq)]
358: pub struct ParamSpec {
359:     /// Dot-separated path, ready for [`Design::f`] and friends.
360:     pub path: String,
361:     /// The leaf's own key.
362:     pub name: String,
363:     /// The groups above it, outermost first.
364:     pub group: Vec<String>,
365:     pub kind: ParamKind,
366:     /// The current value (the leaf's `v`).
367:     pub value: Value,
368: }
369: 
370: /// A map is a parameter when it declares a `type`; anything else is a group.
371: fn collect_params(node: &Value, path: &mut Vec<String>, out: &mut Vec<ParamSpec>) {
372:     let Some(map) = node.as_map() else { return };
373: 
374:     for (key, child) in map.iter() {
375:         let Some(child_map) = child.as_map() else {
376:             continue;
377:         };
378:         path.push(key.to_string());
379: 
380:         match child_map.get("type").and_then(Value::as_str) {
381:             Some(kind) => {
382:                 if let Some(kind) = param_kind(kind, child_map.get("range")) {
383:                     out.push(ParamSpec {
384:                         path: path.join("."),
385:                         name: key.to_string(),
386:                         group: path[..path.len() - 1].to_vec(),
387:                         kind,
388:                         value: child_map.get("v").cloned().unwrap_or(Value::Null),
389:                     });
390:                 }
391:             }
392:             None => collect_params(child, path, out),
393:         }
394: 
395:         path.pop();
396:     }
397: }
398: 
399: fn param_kind(kind: &str, range: Option<&Value>) -> Option<ParamKind> {
400:     let items = match range {
401:         Some(Value::List(items)) => items.as_slice(),
402:         _ => &[],
403:     };
404: 
405:     match kind {
406:         "float" => Some(ParamKind::Float {
407:             min: items.first().and_then(Value::as_f64).unwrap_or(0.0),
408:             max: items.get(1).and_then(Value::as_f64).unwrap_or(1.0),
409:         }),
410:         "int" => Some(ParamKind::Int {
411:             min: items.first().and_then(Value::as_i64).unwrap_or(0),
412:             max: items.get(1).and_then(Value::as_i64).unwrap_or(1),
413:         }),
414:         "bool" => Some(ParamKind::Bool),
415:         "select" | "select_null" => Some(ParamKind::Select {
416:             options: items
417:                 .iter()
418:                 .map(|v| v.as_str().map(str::to_string))
419:                 .collect(),
420:         }),
421:         // The reference has a couple of unused types (e.g. `select_range`);
422:         // skip rather than guess at a control for them.
423:         _ => None,
424:     }
425: }
426: 
427: /// Emit a value as YAML. Only the shapes a design tree holds are covered.
428: fn write_yaml(value: &Value, depth: usize, out: &mut String) {
429:     let pad = "  ".repeat(depth);
430:     match value {
431:         Value::Map(map) => {
432:             for (key, child) in map.iter() {
433:                 match child {
434:                     Value::Map(inner) if !inner.is_empty() => {
435:                         out.push_str(&format!("{pad}{key}:\n"));
436:                         write_yaml(child, depth + 1, out);
437:                     }
438:                     Value::List(items) if !items.is_empty() => {
439:                         out.push_str(&format!("{pad}{key}:\n"));
440:                         for item in items {
441:                             out.push_str(&format!("{pad}- {}\n", scalar_yaml(item)));
442:                         }
443:                     }
444:                     other => out.push_str(&format!("{pad}{key}: {}\n", scalar_yaml(other))),
445:                 }
446:             }
447:         }
448:         other => out.push_str(&format!("{pad}{}\n", scalar_yaml(other))),
449:     }
450: }
451: 
452: fn scalar_yaml(value: &Value) -> String {
453:     match value {
454:         Value::Null => "null".to_string(),
455:         Value::Bool(b) => b.to_string(),
456:         Value::Int(i) => i.to_string(),
457:         Value::Float(f) => {
458:             let text = f.to_string();
459:             if text.contains('.') || text.contains('e') || text.contains("inf") || text == "NaN" {
460:                 text
461:             } else {
462:                 format!("{text}.0")
463:             }
464:         }
465:         Value::Str(s) => format!("{s:?}"),
466:         // Empty containers -- the only ones that reach here.
467:         Value::List(_) => "[]".to_string(),
468:         Value::Map(_) => "{}".to_string(),
469:     }
470: }
