472: /// Body measurements with the derived quantities GarmentCode adds.
473: ///
474: /// Ports `BodyParametrizationBase` plus `assets.bodies.body_params.BodyParameters`.
475: #[derive(Debug, Clone, Default)]
476: pub struct Body {
477:     params: HashMap<String, f64>,
478:     order: Vec<String>,
479: }
480:

481: impl Body {
482:     pub fn load(path: impl AsRef<Path>) -> Result<Self> {
483:         let path = path.as_ref();
484:         let text = std::fs::read_to_string(path)
485:             .with_context(|| format!("reading body file {}", path.display()))?;
486:         Self::from_yaml_str(&text).with_context(|| format!("reading body file {}", path.display()))
487:     }
488: 
489:     /// The same, from YAML already in memory.
490:     pub fn from_yaml_str(text: &str) -> Result<Self> {
491:         let yaml: serde_yaml::Value =
492:             serde_yaml::from_str(text).context("parsing the body measurements")?;
493:         let body = yaml
494:             .get("body")
495:             .ok_or_else(|| anyhow!("missing top-level 'body' key"))?;
496:         let map = body
497:             .as_mapping()
498:             .ok_or_else(|| anyhow!("'body' is not a mapping"))?;
499: 
500:         let mut out = Body::default();
501:         for (k, v) in map {
502:             let key = k
503:                 .as_str()
504:                 .ok_or_else(|| anyhow!("body key is not a string"))?
505:                 .to_string();
506:             let val = v
507:                 .as_f64()
508:                 .ok_or_else(|| anyhow!("body value for '{key}' is not a number"))?;
509:             out.set_raw(key, val);
510:         }
511:         out.eval_dependencies();
512:         Ok(out)
513:     }
514: 
515:     fn set_raw(&mut self, key: String, value: f64) {
516:         if !self.params.contains_key(&key) {
517:             self.order.push(key.clone());
518:         }
519:         self.params.insert(key, value);
520:     }
521: 
522:     pub fn set(&mut self, key: &str, value: f64) {
523:         self.set_raw(key.to_string(), value);
524:         self.eval_dependencies();
525:     }
526: 
527:     /// Set one measurement without re-deriving the rest.
528:     ///
529:     /// For building a body up from nothing -- a measurer filling in all
530:     /// twenty-six -- where [`set`](Self::set) would try to derive from a body
531:     /// that is still half empty. Call [`eval_dependencies`](Self::eval_dependencies)
532:     /// once the last one is in.
533:     pub fn insert(&mut self, key: &str, value: f64) {
534:         self.set_raw(key.to_string(), value);
535:     }
536: 
537:     pub fn contains(&self, key: &str) -> bool {
538:         self.params.contains_key(key)
539:     }
540: 
541:     /// Every measurement this body carries, in the order it was given them.
542:     pub fn names(&self) -> impl Iterator<Item = &str> {
543:         self.order.iter().map(String::as_str)
544:     }
545: 
546:     /// Measurement lookup -- panics on a missing key, like the reference's
547:     /// `body[key]` would raise `KeyError`.
548:     pub fn get(&self, key: &str) -> f64 {
549:         *self
550:             .params
551:             .get(key)
552:             .unwrap_or_else(|| panic!("Body::ERROR::unknown measurement '{key}'"))
553:     }
554: 
555:     /// `BodyParameters.eval_dependencies` -- the derived measurements the
556:     /// garment programs read (all prefixed with an underscore).
557:     pub fn eval_dependencies(&mut self) {
558:         let height = self.get("height");
559:         let head_l = self.get("head_l");
560:         let waist_line = self.get("waist_line");
561:         let hips_line = self.get("hips_line");
562: 
563:         let waist_level = height - head_l - waist_line;
564:         self.set_raw("_waist_level".into(), waist_level);
565:         self.set_raw("_leg_length".into(), waist_level - hips_line);
566: 
567:         let shoulder_w = self.get("shoulder_w");
568:         // The sleeve line sits a little closer to the neck than the true
569:         // shoulder width.
570:         self.set_raw("_base_sleeve_balance".into(), shoulder_w - 2.0);
571: 
572:         let bust_line = self.get("bust_line");
573:         let bust = if self.contains("vert_bust_line") {
574:             (1.0 - 1.0 / 3.0) * self.get("vert_bust_line") + (1.0 / 3.0) * bust_line
575:         } else {
576:             bust_line
577:         };
578:         self.set_raw("_bust_line".into(), bust);
579: 
580:         let hip_incl = self.get("hip_inclination");
581:         self.set_raw("_hip_inclination".into(), hip_incl / 2.0);
582: 
583:         let shoulder_incl = self.get("shoulder_incl");
584:         self.set_raw("_shoulder_incl".into(), shoulder_incl);
585: 
586:         let armscye = self.get("armscye_depth");
587:         self.set_raw("_armscye_depth".into(), armscye + 2.5);
588:     }
589: 
590:     /// Serialise back to the `body:` YAML the reference writes alongside a
591:     /// pattern.
592:     pub fn to_yaml(&self) -> String {
593:         let mut keys: Vec<&String> = self.params.keys().collect();
594:         keys.sort();
595:         let mut out = String::from("body:\n");
596:         for k in keys {
597:             out.push_str(&format!("  {}: {}\n", k, self.params[k]));
598:         }
599:         out
600:     }
601: 
602:     pub fn save(&self, dir: impl AsRef<Path>) -> Result<()> {
603:         let file = dir.as_ref().join("body_measurements.yaml");
604:         std::fs::write(&file, self.to_yaml())
605:             .with_context(|| format!("writing {}", file.display()))?;
606:         Ok(())
607:     }
608: }
