164:     /// The torso's ring at a height, and its girth.
165:     fn level(&self, y: f32) -> Option<Level> {
166:         let rings = self.cut(y);
167:         let ring = section::ring_at(&rings, Axes::Horizontal, self.axis)?;
168:         let outline = hull(&flatten(ring, Axes::Horizontal));
169:         Some(Level {
170:             y,
171:             girth: perimeter(&outline),
172:             hull: outline,
173:             ring: ring.clone(),
174:         })
175:     }
176: 
177:     /// Scan a range of heights and keep the level that best answers `better`.
178:     fn scan(&self, from: f32, to: f32, better: fn(f32, f32) -> bool) -> Option<Level> {
179:         let (from, to) = (from.min(to), from.max(to));
180:         let mut best: Option<Level> = None;
181:         let mut y = from;
182:         while y <= to {
183:             if let Some(level) = self.level(y)
184:                 && level.girth > 0.0
185:                 && best.as_ref().is_none_or(|b| better(level.girth, b.girth))
186:             {
187:                 best = Some(level);
188:             }
189:             y += self.step;
190:         }
191:         best
192:     }
193: 
194:     /// How many rings a horizontal cut makes, ignoring specks.
195:     ///
196:     /// A cut can catch a sliver of surface where it grazes tangentially --
197:     /// the top of a shoulder, the outside of a heel -- and counting those as
198:     /// limbs would put the armpit at the wrong height. A ring smaller than a
199:     /// fiftieth of the body's height around is one of those.
200:     fn ring_count(&self, y: f32) -> usize {
201:         let floor = self.height() / 50.0;
202:         self.cut(y)
203:             .iter()
204:             .filter(|ring| perimeter(&hull(&flatten(ring, Axes::Horizontal))) > floor)
205:             .count()
206:     }
207: 
208:     /// Scan down from `from` for the highest cut at which the arms have come
209:     /// away from the torso -- three rings rather than one.
210:     fn split_below(&self, from: f32, to: f32) -> Option<f32> {
211:         let mut y = from;
212:         while y > to {
213:             if self.ring_count(y) >= 3 {
214:                 return Some(y);
215:             }
216:             y -= self.step;
217:         }
218:         None
219:     }
