221:     fn body(&self) -> Result<Body> {
222:         let height = self.height();
223:         let hip_joint = (self.marks.hips[0][1] + self.marks.hips[1][1]) / 2.0;
224:         let shoulder_joint = (self.marks.shoulders[0][1] + self.marks.shoulders[1][1]) / 2.0;
225: 
226:         // --- the levels, from the bottom up.
227: 
228:         // Below the crotch there are two legs, above it one torso. The scan
229:         // starts at the hip joints, which are always above the crotch, and the
230:         // first cut that finds two rings has passed it.
231:         let crotch_y = self
232:             .split_two_legs(hip_joint)
233:             .unwrap_or(self.floor + height * 0.46);
234: 
235:         // The waist is the narrowest place between the ribs and the hips. The
236:         // range is generous: from the hip joints themselves up to a fifth of
237:         // the body above them, which covers a long torso and a short one.
238:         let waist = self
239:             .scan(
240:                 hip_joint + height * 0.01,
241:                 hip_joint + height * 0.18,
242:                 |a, b| a < b,
243:             )
244:             .ok_or_else(|| anyhow::anyhow!("no waist: the torso has no closed section"))?;
245: 
246:         // The hips are the widest place between the crotch and the waist.
247:         let hips = self
248:             .scan(crotch_y + height * 0.01, waist.y - height * 0.02, |a, b| {
249:                 a > b
250:             })
251:             .ok_or_else(|| anyhow::anyhow!("no hipline between the crotch and the waist"))?;
252: 
253:         // Below the armpit the arms are their own rings; above it they have
254:         // merged into the shoulders.
255:         let armpit_y = self
256:             .split_below(shoulder_joint, waist.y)
257:             .unwrap_or(shoulder_joint - height * 0.07);
258: 
259:         let bust = self
260:             .scan(waist.y + height * 0.02, armpit_y - height * 0.01, |a, b| {
261:                 a > b
262:             })
263:             .ok_or_else(|| anyhow::anyhow!("no bustline between the waist and the armpit"))?;
264:         let underbust = self.underbust(&bust, &waist);
265: 
266:         let neck = self.neck_base(shoulder_joint)?;
267: 
268:         // --- the sagittal profile, for the tape measurements down the body.
269: 
270:         // The profile is hulled over a band a little taller than the tape
271:         // that will run down it. A hull closes across the top and the bottom
272:         // of whatever it is given, and those chords lie across the body rather
273:         // than down it; cutting the band flush with the tape leaves them at
274:         // its ends, and the depth of the body gets added to a length measured
275:         // down it. Keeping them outside the tape's own range is what stops
276:         // that, and it costs nothing -- a tape does not stop abruptly either.
277:         let margin = height * 0.04;
278:         let profile = self.profile(self.axis[0], waist.y - margin, self.top);
279:         let nape = self.nape(&profile, neck.y);
280:         let head_l = distance3(nape, self.crown());
281: 
282:         let waist_line = self.tape(&profile, waist.y, neck.y, Side::Back);
283:         let bust_points = self.peak_separation(&bust.ring, Side::Front);
284:         let bum_points = self.peak_separation(&hips.ring, Side::Back);
285: 
286:         // The line over the bust is taken in the plane through a bust point,
287:         // not down the middle: that is where a tape measure would run.
288:         let bust_plane = if bust_points > 1.0 {
289:             self.axis[0] + bust_points / 2.0
290:         } else {
291:             self.axis[0]
292:         };
293:         let bust_profile = self.profile(bust_plane, waist.y - margin, neck.y + margin);
294:         let waist_over_bust_line = self.tape(&bust_profile, waist.y, neck.y, Side::Front);
295:         let bust_line = self.tape(&bust_profile, bust.y, neck.y, Side::Front);
296: 
297:         // --- the limbs.
298: 
299:         let arm_length = distance3(self.marks.shoulders[0], self.marks.elbows[0])
300:             + distance3(self.marks.elbows[0], self.marks.wrists[0]);
301:         let arm_pose_angle = self.arm_pose();
302:         // The thigh is measured below the crotch. Above it the two legs are
303:         // one pelvis, and the widest cut along the bone would be the hips --
304:         // which is how a thigh comes out a metre around.
305:         let hip_to_knee = self.marks.hips[0][1] - self.marks.knees[0][1];
306:         let below_crotch = if hip_to_knee > 1.0 {
307:             ((self.marks.hips[0][1] - crotch_y + height * 0.01) / hip_to_knee).clamp(0.05, 0.5)
308:         } else {
309:             0.10
310:         };
311:         let leg_circ = self.limb_girth(
312:             self.marks.hips[0],
313:             self.marks.knees[0],
314:             below_crotch,
315:             (below_crotch + 0.45).min(0.75),
316:             |a, b| a > b,
317:         );
318:         let wrist = self.limb_girth(
319:             self.marks.elbows[0],
320:             self.marks.wrists[0],

161:                 continue;
162:             }
163:             let want = segments[a][a_edge].max(segments[b][b_edge]);
164:             if segments[a][a_edge] != want || segments[b][b_edge] != want {
165:                 segments[a][a_edge] = want;
166:                 segments[b][b_edge] = want;
167:                 settled = false;
168:             }
