172:     segments
173: }
174: 
175: /// Sample one panel's outline into a polygon, and remember where each pattern
176: /// edge starts.
177: ///
178: /// The returned outline has one point per sample, and `edge_starts[i]` is the
179: /// index at which pattern edge `i` begins -- which is what lets a stitch
180: /// declared between two *pattern* edges become a seam between two *outline*
181: /// edges. Every pattern edge becomes a run of outline edges, so the two
182: /// numberings have to be translated between rather than assumed equal.
183: fn sample_outline(
184:     panel: &fabelgeist_garment_code::pattern::spec::PanelSpec,
185:     segments: &[usize],
186: ) -> (Vec<Vec2>, Vec<usize>) {
187:     let mut outline = Vec::new();
188:     let mut edge_starts = Vec::with_capacity(panel.edges.len());
189: 
190:     for (index, edge) in panel.edges.iter().enumerate() {
191:         edge_starts.push(outline.len());
192:         let curve =
193:             fabelgeist_garment_code::pattern::core::edge_as_curve(&panel.vertices, edge, false);
194:         let segments = segments.get(index).copied().unwrap_or(1).max(1);
195:         // The end point is the next edge's start, so it is left for that edge
196:         // to add -- and the last edge's end is outline[0], closing the loop.
197:         for step in 0..segments {
198:             let t = step as f64 / segments as f64;
199:             let point = curve.point(t);
200:             outline.push(Vec2::new(point[0] as f32, point[1] as f32));
201:         }
202:     }
203: 
204:     (outline, edge_starts)
205: }
206: 
207: /// The outline edges a pattern edge covers, as a range.
208: fn outline_edges(edge_starts: &[usize], total: usize, edge: usize) -> std::ops::Range<usize> {
209:     let start = edge_starts[edge];
210:     let end = if edge + 1 < edge_starts.len() {
211:         edge_starts[edge + 1]
212:     } else {
213:         total
214:     };
215:     start..end
216: }
217: 
218: /// Everything a fit needs, derived from a pattern.
219: pub struct GarmentBuild {
220:     pub mesh: GarmentMesh,
221:     /// Panels that produced no geometry -- degenerate outlines from a pattern
222:     /// that did not close.
223:     pub skipped: Vec<String>,
224: }
225: 
226: /// Convert a pattern into a meshed garment.
227: pub fn build_garment(
228:     spec: &PatternSpec,
229:     settings: &FitSettings,
230:     fabric: &Fabric,
231: ) -> anyhow::Result<GarmentBuild> {
232:     let mut panels = Vec::new();
233:     let mut panel_index = std::collections::HashMap::new();
234:     let mut edge_maps = Vec::new();
235:     let mut skipped = Vec::new();
236: 
237:     let segments = stitched_segments(spec);
238:     for (index, (name, spec_panel)) in spec.panels.iter().enumerate() {
239:         let (outline, edge_starts) = sample_outline(spec_panel, &segments[index]);
240:         if outline.len() < 3 {
241:             skipped.push(name.clone());
242:             continue;
243:         }
244: 
245:         let outline: Vec<Vec2> = outline.into_iter().map(|p| p * CM_TO_M).collect();
246:         let placement = Placement {
247:             translation: Vec3::new(
248:                 spec_panel.translation[0] as f32 * CM_TO_M,
249:                 spec_panel.translation[1] as f32 * CM_TO_M,
250:                 spec_panel.translation[2] as f32 * CM_TO_M,
251:             ),
252:             rotation: Vec3::new(
253:                 spec_panel.rotation[0] as f32,
254:                 spec_panel.rotation[1] as f32,
255:                 spec_panel.rotation[2] as f32,
256:             ),
257:         };
258: 
259:         panel_index.insert(name.clone(), panels.len());
260:         edge_maps.push((edge_starts, outline.len()));
261:         panels.push(Panel::new(name.clone(), outline).placed(placement));
262:     }
263: 
264:     if panels.is_empty() {
265:         anyhow::bail!("the pattern has no usable panels");
266:     }
267: 
268:     // A stitch joins two pattern edges. Each of those covers a run of outline
269:     // edges, so one stitch becomes several seams -- paired up along the run so
270:     // that the fabric is sewn all the way along rather than only at the ends.
271:     let mut seams = Vec::new();
272:     for stitch in &spec.stitches {
273:         let (Some(&a_panel), Some(&b_panel)) = (
274:             panel_index.get(&stitch.sides[0].panel),
275:             panel_index.get(&stitch.sides[1].panel),
276:         ) else {
277:             continue;
278:         };
279: 
280:         let (a_starts, a_total) = &edge_maps[a_panel];
281:         let (b_starts, b_total) = &edge_maps[b_panel];
282:         if stitch.sides[0].edge >= a_starts.len() || stitch.sides[1].edge >= b_starts.len() {
283:             continue;
284:         }
285: 
286:         let a_range = outline_edges(a_starts, *a_total, stitch.sides[0].edge);
287:         let b_range = outline_edges(b_starts, *b_total, stitch.sides[1].edge);
288: 
289:         // Which way round the two runs meet is decided geometrically, by
290:         // trying both and keeping the shorter total. A pattern format's own
291:         // convention is easy to get backwards, and getting it backwards
292:         // produces a garment with a twist in it that still looks plausible
293:         // until you turn it round.
294:         let reversed = should_reverse(&panels, a_panel, &a_range, b_panel, &b_range);
295: 
296:         let steps = a_range.len().max(b_range.len());
297:         for step in 0..steps {
298:             let t = if steps > 1 {
299:                 step as f32 / (steps - 1) as f32
300:             } else {
301:                 0.0
302:             };
303:             let a_edge = a_range.start + pick(t, a_range.len());
304:             let b_step = if reversed { 1.0 - t } else { t };
305:             let b_edge = b_range.start + pick(b_step, b_range.len());
306:             seams.push(
307:                 Seam::new(
308:                     SeamSide {
309:                         panel: a_panel,
310:                         edge: a_edge,
311:                     },
312:                     SeamSide {
313:                         panel: b_panel,
314:                         edge: b_edge,
315:                     },
316:                 )
317:                 .reversed(reversed),
318:             );
319:         }
320:     }

321:             0.80,
322:             1.00,
323:             |a, b| a < b,
324:         );
325: 
326:         // --- the shoulders.
327: 
328:         let shoulder_w = distance3(self.marks.shoulders[0], self.marks.shoulders[1]);
329:         let neck_w = back_width(&neck.hull);
330:         let shoulder_incl = self.shoulder_inclination(neck_w, shoulder_w, armpit_y);
331:         let shoulder_top = self.shoulder_top(shoulder_w, armpit_y);
332: 
333:         let mut body = Body::default();
334:         let mut set = |name: &str, value: f32| body.insert(name, value as f64);
335: 
336:         set("height", height);
337:         set("head_l", head_l);
338: 
339:         set("bust", bust.girth);
340:         set("underbust", underbust.girth);
341:         set("waist", waist.girth);
342:         set("hips", hips.girth);
343:         set("leg_circ", leg_circ);
344:         set("wrist", wrist);
345: 
346:         set("back_width", back_width(&bust.hull));
347:         set("waist_back_width", back_width(&waist.hull));
348:         set("hip_back_width", back_width(&hips.hull));
349:         set("neck_w", neck_w);
350: 
351:         set("shoulder_w", shoulder_w);
352:         set("shoulder_incl", shoulder_incl);
353:         set("armscye_depth", shoulder_top - armpit_y);
354:         set("arm_length", arm_length);
355:         set("arm_pose_angle", arm_pose_angle);
356: 
357:         set("bust_points", bust_points);
358:         set("bum_points", bum_points);
359:         set("waist_line", waist_line);
360:         set("waist_over_bust_line", waist_over_bust_line);
361:         set("bust_line", bust_line);
362:         set("vert_bust_line", nape[1] - bust.y);
363:         set("hips_line", waist.y - hips.y);
364:         set("crotch_hip_diff", hips.y - crotch_y);
365:         set("hip_inclination", self.hip_inclination(&waist, &hips));
