371:     /// The girth right below the bust.
372:     ///
373:     /// Not an extremum of the body the way the other levels are: from the
374:     /// waist upwards a body gets steadily wider, so the narrowest cut below
375:     /// the bust is the waist itself. What marks the underbust is the *dip*
376:     /// under a bust that overhangs -- so the scan runs down from the bust and
377:     /// stops at the first cut that is narrower than the one below it.
378:     ///
379:     /// A body with no such dip has no underbust to find, and the fallback is
380:     /// stated rather than measured: two fifths of the way from the waist up to
381:     /// the bust, which is where it sits on the bodies GarmentCode ships.
382:     fn underbust(&self, bust: &Level, waist: &Level) -> Level {
383:         let mut y = bust.y - self.step;
384:         let mut last = bust.girth;
385:         while y > waist.y + self.step {
386:             let Some(level) = self.level(y) else { break };
387:             if level.girth > last {
388:                 return level;
389:             }
390:             last = level.girth;
391:             y -= self.step;
392:         }
393: 
394:         let fallback = waist.y + (bust.y - waist.y) * 0.4;
395:         self.level(fallback).unwrap_or(Level {
396:             y: waist.y,
397:             girth: waist.girth,
398:             hull: waist.hull.clone(),
399:             ring: waist.ring.clone(),
400:         })
401:     }
402: 
403:     /// Scan down from the hip joints for the crotch: the highest cut at which
404:     /// the legs are two rings rather than one pelvis.
405:     fn split_two_legs(&self, from: f32) -> Option<f32> {
406:         let mut y = from;
407:         let bottom = self.floor + self.height() * 0.30;
408:         while y > bottom {
409:             if self.ring_count(y) >= 2 {
410:                 return Some(y);
411:             }
412:             y -= self.step;
413:         }
414:         None
415:     }
416: 
417:     /// The base of the neck: where the neck column meets the shoulders.
418:     ///
419:     /// Found in two passes, because neither alone gets it. Rising from the
420:     /// shoulders the body narrows steeply through the trapezius and then
421:     /// hardly at all up the neck, so the first pass finds the narrowest cut --
422:     /// which is unambiguously *on* the neck, but partway up it. The second
423:     /// comes back down to the lowest cut still within a sixth of that width,
424:     /// which is where the neck stops being a column and starts being a
425:     /// shoulder. Stopping at the first cut under some fraction of the
426:     /// shoulders would land wherever on the slope that fraction happened to
427:     /// fall.
428:     fn neck_base(&self, shoulder_joint: f32) -> Result<Level> {
429:         let ceiling = self.marks.neck[1] + self.height() * 0.06;
430:         let mut narrowest: Option<Level> = None;
431:         let mut y = shoulder_joint;
432:         while y < ceiling {
433:             if self.ring_count(y) == 1
434:                 && let Some(level) = self.level(y)
435:                 && narrowest
436:                     .as_ref()
437:                     .is_none_or(|best| span(&level.hull, 0) < span(&best.hull, 0))
438:             {
439:                 narrowest = Some(level);
440:             }
441:             y += self.step;
442:         }
443:         let narrowest = narrowest.ok_or_else(|| {
444:             anyhow::anyhow!("no neck found above the shoulders; is the mesh y-up and standing?")
445:         })?;
446: 
447:         let column = span(&narrowest.hull, 0) * 7.0 / 6.0;
448:         let mut y = narrowest.y;
449:         let mut base = None;
450:         while y > shoulder_joint {
451:             let next = y - self.step;
452:             match self.level(next) {
453:                 Some(level) if self.ring_count(next) == 1 && span(&level.hull, 0) <= column => {
454:                     base = Some(level);
455:                     y = next;
456:                 }
457:                 _ => break,
458:             }
459:         }
460:         Ok(base.unwrap_or(narrowest))
461:     }
