463:     /// The highest point of the body -- the top of the head.
464:     fn crown(&self) -> [f32; 3] {
465:         let mut crown = self.mesh.vertices[0];
466:         for vertex in self.mesh.vertices {
467:             if vertex[1] > crown[1] {
468:                 crown = *vertex;
469:             }
470:         }
471:         crown
472:     }
473: 
474:     /// The body's outline seen from the side, cut down the plane `x` and kept
475:     /// between two heights, as a convex hull in `(z, y)`.
476:     ///
477:     /// The band matters. A hull of the whole side of a body runs from the back
478:     /// of the head straight to the back of the calves, and a tape measured
479:     /// along it would miss every shape in between. Hulling only the stretch a
480:     /// measurement covers is what makes the result a tape over that stretch --

481:     /// without waiting on a readback from the solver.
482:     pub fn placed_positions(&self) -> Vec<Vec3> {
483:         self.pose.place(&self.base_positions, &self.pivots)
484:     }
485: 
486:     /// Put the garment somewhere else, at rest.
487:     ///
488:     /// No rebuild: a pose is rigid, so every rest length, bending weight and
489:     /// mass the constraints were built with still holds, and only the
490:     /// positions move. Velocities go back to zero with them -- this is a
491:     /// placement, not a shove -- and the frame count restarts, because a
492:     /// garment that has been moved is no longer the drape that was running.
493:     pub fn set_pose(&mut self, pose: GarmentPose) -> anyhow::Result<()> {
494:         let positions = pose.place(&self.base_positions, &self.pivots);
495:         self.cloth
496:             .particles
497:             .write_positions(&self.context, &positions)?;
498:         self.pose = pose;
499:         self.frames = 0;
500:         Ok(())
501:     }
502: 
503:     /// Lift every garment particle that sits inside the body out to its
504:     /// surface, once, before the first step.
505:     ///
506:     /// A garment's initial layout puts panels straight through the body, and a
507:     /// substep cannot fix that: it looks only as far as the collision shell,
508:     /// and from inside a torso there is no triangle in that range.
509:     ///
510:     /// This runs on the **host**, against `fabelgeist-bvh`'s own tree, and that is
511:     /// deliberate. The GPU version of the same idea has to be told how far to
512:     /// look, and the honest answer for "somewhere inside a body" is about a
513:     /// quarter of a metre -- which turns every particle's query into a box
514:     /// that matches a large fraction of the body's triangles. Thousands of
515:     /// particles against thousands of triangles in one dispatch runs for
516:     /// seconds, and a compute dispatch that runs for seconds is what Windows'
517:     /// display watchdog exists to kill: it resets the GPU, which takes the
518:     /// device, the compositor and the window with it.
519:     ///
520:     /// On the host the same query is exact rather than radius-limited, prunes
521:     /// properly, costs a few milliseconds for a whole garment, and cannot
522:     /// stall a display driver. It happens once, so nothing is lost by it.
523:     pub async fn clear_body(&mut self, settings: &FitSettings) -> anyhow::Result<()> {
524:         let Some(body) = &self.body else {
525:             return Ok(());
526:         };
527: 
528:         let offset = settings.body_offset_cm * CM_TO_M + self.cloth.fabric.particle_radius();
529:         let mut positions = self.cloth.read_positions(&self.context).await?;
530: 
531:         // Generous, but a *distance* bound rather than a box: the tree prunes
532:         // on it, so a particle already outside the body stops almost at once.
533:         let reach = 0.5f32;
534:         let mut lifted = 0usize;
535: 
536:         for position in &mut positions {
537:             let Some((triangle, closest, distance)) = body.closest_point(*position, reach) else {
538:                 continue;
539:             };
540:             let (a, b, c) = body.triangle(triangle);
541:             let normal = (b - a).cross(c - a);
542:             let length = normal.length();
543:             if length < 1e-12 {
544:                 continue;
545:             }
546:             let normal = normal / length;
547: 
548:             // Which side of the surface the particle is on. The face normal
549:             // decides, because the direction to the closest point says nothing
550:             // once the particle is on the surface.
551:             let outward = (*position - closest).dot(normal);
552:             if outward < 0.0 {
553:                 *position = closest + normal * offset;
554:                 lifted += 1;
555:             } else if distance < offset {
556:                 let direction = if distance > 1e-6 {
557:                     (*position - closest) / distance
558:                 } else {
559:                     normal
560:                 };
561:                 *position = closest + direction * offset;
562:                 lifted += 1;
563:             }
564:         }
565: 
566:         if lifted > 0 {
567:             self.cloth
568:                 .particles
569:                 .write_positions(&self.context, &positions)?;
570:         }
571:         Ok(())
572:     }
573: 
574:     /// Step the fit.
575:     ///
576:     /// Interleaved: one submission per substep. The solver is running on the
577:     /// application's own device, alongside the compositor presenting the
578:     /// window it is drawn in, and a whole step submitted at once occupies the
579:     /// GPU long enough that the compositor cannot get a swapchain image.
580:     ///
581:     /// Asynchronous because the host-side contact projection between substeps
582:     /// reads positions back from the GPU.
583:     pub async fn step(&mut self, delta: f32) -> anyhow::Result<()> {
584:         self.cloth
585:             .step_interleaved(&self.context, &self.solver, &mut self.collisions, delta)
586:             .await?;
587:         self.frames += 1;
588:         Ok(())
589:     }
590: 
591:     /// Step, then wait for the GPU to finish it.
592:     ///
593:     /// What an interactive loop must call. A step is tens of milliseconds of
594:     /// GPU work and nothing throttles submission, so a loop that steps on a
595:     /// timer submits faster than the device drains and the queue grows without
596:     /// bound -- for a minute or so, until the driver loses the device and
597:     /// takes the window with it. Waiting also hands the compositor sharing
598:     /// this device a clear gap between steps.
599:     #[cfg_attr(not(test), allow(dead_code))]
600:     pub async fn step_and_wait(&mut self, delta: f32) -> anyhow::Result<()> {
601:         self.step(delta).await?;
602:         self.context.submitted_work_done().await;
603:         Ok(())
604:     }
605: 
606:     /// The garment's current positions on the host.
607:     #[cfg_attr(not(test), allow(dead_code))]
608:     /// What a caller needs to read the positions back *without* holding a
609:     /// lock on the fit.
610:     ///
611:     /// Both are cheap handles. The read is asynchronous, and holding a
612:     /// blocking lock across it would stall every other handler on the thread.
613:     pub fn readback_handles(&self) -> (WgpuContext, fabelgeist_gpu::prelude::Buffer) {
614:         (self.context.clone(), self.cloth.particles.positions.clone())
615:     }
616: 
617:     #[cfg_attr(not(test), allow(dead_code))]
618:     pub async fn positions(&self) -> anyhow::Result<Vec<[f32; 3]>> {
619:         Ok(self
620:             .cloth
621:             .read_positions(&self.context)
622:             .await?
623:             .into_iter()
624:             .map(|p| [p.x, p.y, p.z])
625:             .collect())
626:     }
