628:     /// Put the garment back where it was placed, at rest.
629:     ///
630:     /// `set_pose` writes every particle from the pattern's own positions, so
631:     /// it subsumes `Cloth::reset` -- and unlike it, keeps the garment where
632:     /// it was put. Reset undoes the simulation, not the positioning.
633:     pub async fn reset(&mut self, settings: &FitSettings) -> anyhow::Result<()> {
634:         let pose = self.pose.clone();
635:         self.set_pose(pose)?;
636:         self.clear_body(settings).await
637:     }
638: }
