757: /// The extent of a polygon along one of its axes.
758: fn span(polygon: &[[f32; 2]], axis: usize) -> f32 {
759:     let mut low = f32::INFINITY;
760:     let mut high = f32::NEG_INFINITY;
761:     for point in polygon {
762:         low = low.min(point[axis]);
763:         high = high.max(point[axis]);
764:     }
765:     if high > low { high - low } else { 0.0 }
766: }
767: 
768: fn distance3(a: [f32; 3], b: [f32; 3]) -> f32 {
769:     ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2) + (b[2] - a[2]).powi(2)).sqrt()
770: }
771: 
772: /// Trim a `(z, y)` segment to the part of it between two heights.
773: fn clip_to_band(a: [f32; 2], b: [f32; 2], low: f32, high: f32) -> Option<([f32; 2], [f32; 2])> {
774:     let (mut a, mut b) = (a, b);
775:     if a[1] > b[1] {
776:         std::mem::swap(&mut a, &mut b);
777:     }
778:     if b[1] <= low || a[1] >= high {
779:         return None;
780:     }
781:     let at = |y: f32| {
782:         let t = (y - a[1]) / (b[1] - a[1]);
783:         [a[0] + (b[0] - a[0]) * t, y]
784:     };
785:     let start = if a[1] < low { at(low) } else { a };
786:     let end = if b[1] > high { at(high) } else { b };
787:     Some((start, end))
788: }
