641: ///
642: /// The solver is all storage buffers and compute, and a device created with
643: /// the WebGL2 baseline limits allows neither -- every buffer comes back
644: /// invalid and the first write panics inside wgpu's validation, far from
645: /// anything that names the cause. Checking up front turns that into a line of
646: /// text in the tab.
647: fn check_device(context: &WgpuContext) -> anyhow::Result<()> {
648:     // The widest kernel here binds seven storage buffers (mesh collision:
649:     // positions, previous, mesh positions, mesh triangles, and three for the
650:     // hierarchy) plus a uniform.
651:     const STORAGE_BUFFERS: u32 = 8;
652:     const WORKGROUP_SIZE: u32 = 256;
653: 
654:     let limits = context.device.limits();
655:     if limits.max_storage_buffers_per_shader_stage < STORAGE_BUFFERS {
656:         anyhow::bail!(
657:             "this GPU device allows {} storage buffers per stage and the solver needs {STORAGE_BUFFERS};              it was probably created with the WebGL2 baseline limits",
658:             limits.max_storage_buffers_per_shader_stage
659:         );
660:     }
661:     if limits.max_compute_invocations_per_workgroup < WORKGROUP_SIZE {
662:         anyhow::bail!(
663:             "this GPU device allows {} compute invocations per workgroup and the solver needs {WORKGROUP_SIZE}",
664:             limits.max_compute_invocations_per_workgroup
665:         );
666:     }
667:     Ok(())
668: }
