670: /// Scale and centre a body mesh so that it stands the given height, in metres,
671: /// with its feet at the origin.
672: ///
673: /// The body model and the pattern come from different worlds and agree on
674: /// nothing -- not the unit, not where the origin is. The pattern's own body
675: /// measurements give a height in centimetres, and matching the model to it is
676: /// what puts the garment on the body rather than beside it.
677: pub fn normalize_body(vertices: &[[f32; 3]], target_height_m: f32) -> Vec<Vec3> {
678:     if vertices.is_empty() {
679:         return Vec::new();
680:     }
681: 
682:     let mut lowest = [f32::INFINITY; 3];
683:     let mut highest = [f32::NEG_INFINITY; 3];
684:     for vertex in vertices {
685:         for axis in 0..3 {
686:             lowest[axis] = lowest[axis].min(vertex[axis]);
687:             highest[axis] = highest[axis].max(vertex[axis]);
688:         }
689:     }
690: 
691:     let height = highest[1] - lowest[1];
692:     let scale = if height > 1e-6 {
693:         target_height_m / height
694:     } else {
695:         1.0
696:     };
697:     let center_x = (lowest[0] + highest[0]) * 0.5;
698:     let center_z = (lowest[2] + highest[2]) * 0.5;
699: 
700:     vertices
701:         .iter()
702:         .map(|vertex| {
703:             Vec3::new(
704:                 (vertex[0] - center_x) * scale,
705:                 (vertex[1] - lowest[1]) * scale,
706:                 (vertex[2] - center_z) * scale,
707:             )
708:         })
709:         .collect()
710: }
