  1: //! Slicing a closed mesh with a plane.
  2: //!
  3: //! Every measurement in this module is a plane section of the body: a girth is
  4: //! the section's perimeter, a back width is part of it, a level is found by
  5: //! scanning sections up the body until one is narrowest or widest.
  6: //!
  7: //! The sections are returned as **loops**, not as a bag of segments, and that
  8: //! is what makes the rest of the module possible. A horizontal cut across the
  9: //! chest of a body standing with its arms away from it produces three loops --
 10: //! the torso and one for each arm -- and a measurement wants exactly one of
 11: //! them. The same fact is used the other way round to find levels: the armpit
 12: //! is the highest cut at which the arms are still their own loops, and the
 13: //! crotch is the highest cut at which the legs are.
 14: 
 15: use std::collections::HashMap;
 16: 
 17: /// A triangle mesh being measured. Nothing is copied; the measurements read
 18: /// the caller's arrays directly.
 19: #[derive(Clone, Copy)]
 20: pub struct BodyMesh<'a> {
 21:     pub vertices: &'a [[f32; 3]],
 22:     pub faces: &'a [[u32; 3]],
 23: }
 24: 
 25: /// Where a point lands when a section is flattened.
 26: ///
 27: /// Sections are cut on three kinds of plane and each has its own natural pair
 28: /// of axes, so the loops are kept in 3D and projected on demand rather than
 29: /// being flattened once into a basis that only one caller wants.
 30: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
 31: pub enum Axes {
 32:     /// A horizontal cut, seen from above: `(x, z)`.
 33:     Horizontal,
 34:     /// A cut down the middle of the body, seen from the side: `(z, y)`.
 35:     Sagittal,
 36: }
 37: 
 38: /// Points are matched to a tenth of a millimetre when loops are assembled.
 39: ///
 40: /// Two triangles sharing an edge each compute the crossing on that edge from
 41: /// the same two vertices, but from opposite ends, so the two answers differ in
 42: /// the last bits. Rounding to a grid is what lets them be recognised as one
 43: /// point; a tenth of a millimetre is far below any feature of a body and far
 44: /// above that error.
 45: const GRID: f32 = 10.0;
 46: 
 47: fn key(point: [f32; 3]) -> [i32; 3] {
 48:     [
 49:         (point[0] * GRID).round() as i32,
 50:         (point[1] * GRID).round() as i32,
 51:         (point[2] * GRID).round() as i32,
 52:     ]
 53: }
 54: 
 55: /// One closed ring of the surface, in the order it goes round.
 56: pub type Ring = Vec<[f32; 3]>;
 57: 
 58: /// Cut the mesh with the plane through `origin` with the given `normal`, and
 59: /// return the rings the cut makes.
 60: ///
 61: /// A vertex exactly on the plane is treated as being just above it. Deciding
 62: /// it either way is arbitrary; deciding it *consistently* is not, because a
 63: /// triangle whose vertices disagree about which side they are on produces a
 64: /// segment out of nothing and breaks the ring it lands in.
 65: pub fn cross_section(mesh: BodyMesh<'_>, origin: [f32; 3], normal: [f32; 3]) -> Vec<Ring> {
 66:     let side = |vertex: [f32; 3]| {
 67:         let distance = (vertex[0] - origin[0]) * normal[0]
 68:             + (vertex[1] - origin[1]) * normal[1]
 69:             + (vertex[2] - origin[2]) * normal[2];
 70:         if distance == 0.0 {
 71:             f32::MIN_POSITIVE
 72:         } else {
 73:             distance
 74:         }
 75:     };
 76: 
 77:     let mut segments: Vec<([f32; 3], [f32; 3])> = Vec::new();
 78:     for face in mesh.faces {
 79:         let points = [
 80:             mesh.vertices[face[0] as usize],
 81:             mesh.vertices[face[1] as usize],
 82:             mesh.vertices[face[2] as usize],
 83:         ];
 84:         let distances = [side(points[0]), side(points[1]), side(points[2])];
 85:         if distances.iter().all(|d| *d > 0.0) || distances.iter().all(|d| *d < 0.0) {
 86:             continue;
 87:         }
 88: 
 89:         let mut crossings = Vec::with_capacity(2);
 90:         for edge in 0..3 {
 91:             let next = (edge + 1) % 3;
 92:             let (from, to) = (distances[edge], distances[next]);
 93:             if (from > 0.0) == (to > 0.0) {
 94:                 continue;
 95:             }
 96:             let t = from / (from - to);
 97:             let (a, b) = (points[edge], points[next]);
 98:             crossings.push([
 99:                 a[0] + (b[0] - a[0]) * t,
100:                 a[1] + (b[1] - a[1]) * t,
101:                 a[2] + (b[2] - a[2]) * t,
102:             ]);
103:         }
104:         if let [a, b] = crossings[..]
105:             && key(a) != key(b)
106:         {
107:             segments.push((a, b));
108:         }
109:     }
110: 
111:     assemble(segments)
112: }
113: 
114: /// Chain the segments into closed rings.
115: ///
116: /// A segment that cannot be continued ends its ring; the result is kept
117: /// anyway, because a body mesh with a hole in it should still measure rather
118: /// than silently drop the piece the hole is in.
119: fn assemble(segments: Vec<([f32; 3], [f32; 3])>) -> Vec<Ring> {
120:     let mut at: HashMap<[i32; 3], Vec<usize>> = HashMap::new();
121:     for (index, (a, b)) in segments.iter().enumerate() {
122:         at.entry(key(*a)).or_default().push(index);
123:         at.entry(key(*b)).or_default().push(index);
124:     }
125: 
126:     let mut used = vec![false; segments.len()];
127:     let mut rings = Vec::new();
128: 
129:     for start in 0..segments.len() {
130:         if used[start] {
131:             continue;
132:         }
133:         used[start] = true;
134:         let (first, mut head) = segments[start];
135:         let mut ring = vec![first, head];
136: 
137:         loop {
138:             let candidates = at.get(&key(head));
139:             let next = candidates.and_then(|list| {
140:                 list.iter()
141:                     .copied()
142:                     .find(|index| !used[*index] && matches(segments[*index], head))
143:             });
144:             let Some(index) = next else { break };
145:             used[index] = true;
146:             let (a, b) = segments[index];
147:             head = if key(a) == key(head) { b } else { a };
148:             if key(head) == key(ring[0]) {
149:                 break;
150:             }
151:             ring.push(head);
152:         }
153: 
154:         if ring.len() >= 3 {
155:             rings.push(ring);
156:         }
157:     }
158: 
159:     rings
160: }
161: 
162: fn matches(segment: ([f32; 3], [f32; 3]), point: [f32; 3]) -> bool {
163:     key(segment.0) == key(point) || key(segment.1) == key(point)
164: }
165: 
166: /// Flatten a ring onto a pair of axes.
167: pub fn flatten(ring: &[[f32; 3]], axes: Axes) -> Vec<[f32; 2]> {
168:     ring.iter()
169:         .map(|point| match axes {
170:             Axes::Horizontal => [point[0], point[2]],
171:             Axes::Sagittal => [point[2], point[1]],
172:         })
173:         .collect()
174: }
