181: pub fn flatten_on_plane(ring: &[[f32; 3]], normal: [f32; 3]) -> Vec<[f32; 2]> {
182:     let helper = if normal[0].abs() < 0.9 {
183:         [1.0, 0.0, 0.0]
184:     } else {
185:         [0.0, 1.0, 0.0]
186:     };
187:     let dot = helper[0] * normal[0] + helper[1] * normal[1] + helper[2] * normal[2];
188:     let mut u = [
189:         helper[0] - normal[0] * dot,
190:         helper[1] - normal[1] * dot,
191:         helper[2] - normal[2] * dot,
192:     ];
193:     let length = (u[0] * u[0] + u[1] * u[1] + u[2] * u[2]).sqrt();
194:     u = [u[0] / length, u[1] / length, u[2] / length];
195:     let v = [
196:         u[1] * normal[2] - u[2] * normal[1],
197:         u[2] * normal[0] - u[0] * normal[2],
198:         u[0] * normal[1] - u[1] * normal[0],
199:     ];
200: 
201:     ring.iter()
202:         .map(|point| {
203:             [
204:                 point[0] * u[0] + point[1] * u[1] + point[2] * u[2],
205:                 point[0] * v[0] + point[1] * v[1] + point[2] * v[2],
206:             ]
207:         })
208:         .collect()
209: }
210: 
211: /// The convex hull of a flattened ring, anticlockwise, by Andrew's monotone
212: /// chain.
213: ///
214: /// Girths are hulls rather than the ring itself because that is what a tape
215: /// measure does: it bridges a hollow -- the small of the back, the dip beside
216: /// a hip -- instead of following it in and out again.
217: pub fn hull(points: &[[f32; 2]]) -> Vec<[f32; 2]> {
218:     let mut sorted = points.to_vec();
219:     sorted.sort_by(|a, b| a[0].total_cmp(&b[0]).then(a[1].total_cmp(&b[1])));
220:     sorted.dedup_by(|a, b| a[0] == b[0] && a[1] == b[1]);
221:     if sorted.len() < 3 {
222:         return sorted;
223:     }
224: 
225:     let turn = |o: [f32; 2], a: [f32; 2], b: [f32; 2]| {
226:         (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
227:     };
228: 
229:     let mut chain: Vec<[f32; 2]> = Vec::with_capacity(sorted.len() * 2);
230:     for pass in 0..2 {
231:         let start = chain.len();
232:         let ordered: Box<dyn Iterator<Item = &[f32; 2]>> = if pass == 0 {
233:             Box::new(sorted.iter())
234:         } else {
235:             Box::new(sorted.iter().rev())
236:         };
237:         for point in ordered {
238:             while chain.len() >= start + 2
239:                 && turn(chain[chain.len() - 2], chain[chain.len() - 1], *point) <= 0.0
240:             {
241:                 chain.pop();
242:             }
243:             chain.push(*point);
244:         }
245:         chain.pop();
246:     }
247:     chain
248: }
249: 
250: pub fn perimeter(polygon: &[[f32; 2]]) -> f32 {
251:     if polygon.len() < 3 {
252:         return 0.0;
253:     }
254:     let mut total = 0.0;
255:     for index in 0..polygon.len() {
256:         let a = polygon[index];
257:         let b = polygon[(index + 1) % polygon.len()];
258:         total += ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
259:     }
260:     total
261: }
262: 
263: pub fn centroid(points: &[[f32; 2]]) -> [f32; 2] {
264:     let count = points.len().max(1) as f32;
265:     let sum = points
266:         .iter()
267:         .fold([0.0f32, 0.0], |acc, p| [acc[0] + p[0], acc[1] + p[1]]);
268:     [sum[0] / count, sum[1] / count]
269: }
270: 
271: /// Whether a flattened ring encloses a point, by the crossing-number rule.
272: pub fn encloses(polygon: &[[f32; 2]], point: [f32; 2]) -> bool {
273:     let mut inside = false;
274:     for index in 0..polygon.len() {
275:         let a = polygon[index];
276:         let b = polygon[(index + 1) % polygon.len()];
277:         if (a[1] > point[1]) != (b[1] > point[1]) {
278:             let crossing = a[0] + (point[1] - a[1]) / (b[1] - a[1]) * (b[0] - a[0]);
279:             if crossing > point[0] {
280:                 inside = !inside;
281:             }
282:         }
283:     }
284:     inside
285: }
286: 
287: /// The ring of a section that a point is in, or the one nearest it.
288: ///
289: /// "Nearest" is the fallback rather than the rule: a cut through the chest
290: /// gives the torso and both arms, and the torso is the one that encloses the
291: /// spine. Only when nothing encloses the reference -- a cut just past the top
292: /// of the head, say -- does the closest ring win.
293: pub fn ring_at(rings: &[Ring], axes: Axes, reference: [f32; 2]) -> Option<&Ring> {
294:     let mut nearest: Option<(f32, &Ring)> = None;
295:     for ring in rings {
296:         let flat = flatten(ring, axes);
297:         if encloses(&flat, reference) {
298:             return Some(ring);
299:         }
300:         let middle = centroid(&flat);
301:         let distance = (middle[0] - reference[0]).powi(2) + (middle[1] - reference[1]).powi(2);
302:         if nearest.is_none_or(|(best, _)| distance < best) {
303:             nearest = Some((distance, ring));
304:         }
305:     }
306:     nearest.map(|(_, ring)| ring)
307: }
308: 
309: /// The length of the hull's back half: from the point furthest to one side of
310: /// the body to the point furthest to the other, going round the back.
311: ///
312: /// This is GarmentCode's "section" family of measurements -- `back_width`,
313: /// `waist_back_width`, `hip_back_width`, `neck_w`. The two side points are its
314: /// balance lines: the vertical lines down the sides of the body.
315: pub fn back_width(hull: &[[f32; 2]]) -> f32 {
316:     if hull.len() < 3 {
317:         return 0.0;
318:     }
319:     let index_of = |pick: fn(f32, f32) -> bool| {
320:         let mut best = 0;
321:         for index in 1..hull.len() {
322:             if pick(hull[index][0], hull[best][0]) {
323:                 best = index;
324:             }
325:         }
326:         best
327:     };
328:     let left = index_of(|a, b| a > b);
329:     let right = index_of(|a, b| a < b);
330: 
331:     // Both ways round from one side point to the other; the back is the way
332:     // whose points sit behind the section's middle.
333:     let walk = |from: usize, to: usize| {
334:         let mut length = 0.0;
335:         let mut depth = 0.0;
336:         let mut count = 0.0f32;
337:         let mut index = from;
338:         while index != to {
339:             let next = (index + 1) % hull.len();
340:             let (a, b) = (hull[index], hull[next]);
341:             length += ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
342:             depth += b[1];
343:             count += 1.0;
344:             index = next;
345:         }
346:         (length, depth / count.max(1.0))
347:     };
348: 
349:     let (forward, forward_depth) = walk(left, right);
350:     let (backward, backward_depth) = walk(right, left);
351:     if forward_depth < backward_depth {
352:         forward
353:     } else {
354:         backward
355:     }
