44: 
45:     /// The same, with control over whether the validation error scope is read
46:     /// back. Draining the queue to read it is only safe on a device nothing
47:     /// else is submitting to -- see `WgpuContext::blocking_validation`.
48:     pub fn get_or_create_pipeline_validated(
49:         &self,
50:         device: &wgpu::Device,
51:         entry_point: &str,
52:         // The web never blocks to read the scope back.
53:         #[cfg_attr(target_arch = "wasm32", allow(unused_variables))] blocking_validation: bool,
54:     ) -> anyhow::Result<Arc<wgpu::ComputePipeline>> {
55:         #[cfg(target_arch = "wasm32")]
