57:         use std::collections::hash_map::DefaultHasher;
58:         use std::hash::{Hash, Hasher};
59: 
60:         // Cache key based on entry point (shader code is part of shader struct but not strictly hashed here, assuming one pipeline per shadernode usually)
61:         // Ideally we should hash the shader code or module ID too if it changes.
62:         // For now lets hash the entry point.
63:         let mut s = DefaultHasher::new();
64:         entry_point.hash(&mut s);
65:         let cache_key = s.finish();
66: 
67:         let mut cache = self
68:             .pipeline_cache
69:             .lock()
70:             .map_err(|_| anyhow::anyhow!("Failed to lock pipeline cache"))?;
71:         if let Some(p) = cache.get(&cache_key) {
72:             return Ok(p.clone());
73:         }
74: 
75:         // Reset validation error
76:         if let Ok(mut guard) = self.validation_error.lock() {
77:             *guard = None;
78:         }
79: 
80:         // Create Pipeline
81:         #[cfg(not(target_arch = "wasm32"))]
82:         let error_scope =
83:             blocking_validation.then(|| device.push_error_scope(wgpu::ErrorFilter::Validation));
84: 
85:         let module = self
86:             .shader
87:             .module
88:             .as_ref()
89:             .ok_or_else(|| anyhow::anyhow!("ComputePipeline: Shader Module missing"))?;
90: 
91:         let layouts: Vec<_> = self.bind_group_layouts.iter().map(|l| l.as_ref()).collect();
92:         let sparse_layouts: Vec<Option<&wgpu::BindGroupLayout>> =
93:             layouts.iter().map(|&l| Some(l)).collect();
94: 
95:         let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
96:             label: Some("ComputePipeline Layout"),
97:             bind_group_layouts: &sparse_layouts,
98:             immediate_size: 0,
99:         });
