101:         let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
102:             label: Some("ComputePipeline"),
103:             layout: Some(&pipeline_layout),
104:             module,
105:             entry_point: Some(entry_point),
106:             compilation_options: wgpu::PipelineCompilationOptions::default(),
107:             cache: None,
108:         });
109: 
110:         // POP ERROR SCOPE
111:         #[cfg(not(target_arch = "wasm32"))]
112:         if let Some(error_scope) = error_scope {
113:             let _ = device.poll(wgpu::PollType::wait_indefinitely());
114:             if let Some(e) = pollster::block_on(error_scope.pop())
115:                 && let Ok(mut guard) = self.validation_error.lock()
116:             {
117:                 *guard = Some(e.to_string());
118:             }
119:         }
