126:     pub fn validate_interface(&self) -> anyhow::Result<()> {
127:         let naga_res = parse_naga(&self.shader.code, wgpu::naga::ShaderStage::Compute)
128:             .map_err(|e| anyhow::anyhow!("Compute Shader Parse Error: {}", e))?;
129: 
130:         if !naga_res
131:             .entry_points
132:             .iter()
133:             .any(|ep| ep.stage == wgpu::naga::ShaderStage::Compute)
134:         {
135:             return Err(anyhow::anyhow!("Compute Shader missing entry point"));
136:         }
137: 
138:         Ok(())
139:     }
