142: impl ComputePipeline {
143:     pub fn new(context: &WgpuContext, shader: ComputeShader) -> Result<Self> {
144:         let mut pipeline = Self::prepare(context, shader)?;
145:         pipeline.compile(context)?;
146:         Ok(pipeline)
147:     }
148: 
149:     /// Reflect bindings without compiling a GPU pipeline. A caller choosing a
150:     /// different uniform layout can share the shader and its interface, then
151:     /// compile only the dispatch layout it actually uses.
152:     pub fn prepare(context: &WgpuContext, shader: ComputeShader) -> Result<Self> {
153:         let interface = reflection::ReflectedInterface::new(context, &shader.code)?;
154:         Ok(Self {
155:             shader,
156:             bind_group_layouts: interface.layouts,
157:             reflection: Some(interface.reflection),
158:             ..Default::default()
159:         })
160:     }
161: 
162:     /// Compile this definition's static uniform layout on first use. Clones
163:     /// share the entry-point cache, including definitions used by raw kernels.
164:     pub fn compile(&mut self, context: &WgpuContext) -> Result<()> {
165:         if self.pipeline.is_some() {
166:             return Ok(());
167:         }
168:         let reflection = self
169:             .reflection
170:             .as_ref()
171:             .ok_or_else(|| anyhow!("ComputePipeline: Reflection missing"))?;
172:         let pipeline = self.get_or_create_pipeline_validated(
173:             &context.device,
174:             &reflection.vertex_entry_point,
175:             context.blocking_validation,
176:         )?;
177:         let validation = self
178:             .validation_error
179:             .lock()
180:             .map_err(|_| anyhow!("Failed to lock pipeline validation state"))?;
181:         if let Some(error) = validation.as_ref() {
182:             return Err(anyhow!("ComputePipeline Creation Error: {error}"));
183:         }
184:         self.pipeline = Some(pipeline);
185:         Ok(())
186:     }
187: }

