43: impl PingPong {
44:     fn src(&self) -> Buffer {
45:         if self.flipped {
46:             self.scratch.clone()
47:         } else {
48:             self.own.clone()
49:         }
50:     }
51: 
52:     fn dst(&self) -> Buffer {
53:         if self.flipped {
54:             self.own.clone()
55:         } else {
56:             self.scratch.clone()
57:         }
58:     }
59: 
60:     fn swap(&mut self) {
61:         self.flipped = !self.flipped;
