368: /// The head's mesh on the GPU, for measuring how much hair covers it.
369: struct HeadMesh {
370:     vertices: u32,
371:     points: Buffer,
372:     normals: Buffer,
373:     adjacency_start: Buffer,
374:     adjacency: Buffer,
375: }
376: 
377: pub struct GpuGroomer {
378:     context: WgpuContext,
379:     kernels: Kernels,
380:     scan: PrefixSum,
381:     scan_scratch: PrefixSumScratch,
382:     sort: RadixSort,
383:     sort_scratch: SortScratch,
384:     grid: GpuHashGrid,
385:     scratch: Scratches,
386:     head_mesh: Option<HeadMesh>,
387:     atlas: Option<(u32, [u32; 2], Arc<CardAtlas>)>,
388: }
389: 
390: impl GpuGroomer {
391:     pub fn new(context: WgpuContext) -> Result<Self> {
392:         let cache = KernelCache::new();
393:         let kernels = Kernels::new(&context, &cache)?;
394:         let scan = PrefixSum::with_cache(&context, &cache)?;
395:         let scan_scratch = PrefixSumScratch::new(&context, ScanElementCount::from_elements(1024))?;
396:         let sort = RadixSort::with_cache(&context, &cache)?;
397:         let sort_scratch = SortScratch::new(&context, 1024)?;
398:         let grid = GpuHashGrid::new(&context, HashKernels::new(&context, &cache)?, 1024)?;
399:         Ok(Self {
400:             context,
401:             kernels,
402:             scan,
403:             scan_scratch,
404:             sort,
405:             sort_scratch,
406:             grid,
407:             scratch: Scratches::default(),
408:             head_mesh: None,
409:             atlas: None,
410:         })
411:     }
412: 
413:     pub fn context(&self) -> &WgpuContext {
414:         &self.context
415:     }
416: 
417:     /// The head the hair is drawn on, to measure how much hair covers each
418:     /// of its vertices ([`GpuLods::cover`]): its points, normals, and which
419:     /// vertices neighbour which.
420:     pub fn set_head_mesh(&mut self, surface: &Surface) -> Result<()> {
421:         let n = surface.positions.len();
422:         let mut neighbors: Vec<Vec<u32>> = vec![Vec::new(); n];
423:         for t in &surface.triangles {
424:             for &a in t {
425:                 for &b in t {
426:                     if a != b && !neighbors[a as usize].contains(&b) {
427:                         neighbors[a as usize].push(b);
428:                     }
429:                 }
430:             }
431:         }
432:         let mut start = Vec::with_capacity(n + 1);
433:         let mut adjacency = Vec::new();
434:         for list in &neighbors {
435:             start.push(adjacency.len() as u32);
436:             adjacency.extend_from_slice(list);
437:         }
438:         start.push(adjacency.len() as u32);
439:         let four = |v: &[Vec3]| {
440:             v.iter()
441:                 .map(|p| [p.x, p.y, p.z, 0.0])
442:                 .collect::<Vec<[f32; 4]>>()
443:         };
444:         self.head_mesh = Some(HeadMesh {
445:             vertices: n as u32,
446:             points: upload(
447:                 &self.context,
448:                 &four(&surface.positions),
449:                 "hair head points".into(),
450:             )?,
451:             normals: upload(
452:                 &self.context,
453:                 &four(&surface.normals),
454:                 "hair head normals".into(),
455:             )?,
456:             adjacency_start: upload(&self.context, &start, "hair head adjacency start".into())?,
457:             adjacency: upload(&self.context, &adjacency, "hair head adjacency".into())?,
458:         });
459:         Ok(())
460:     }
461: 
462:     /// Strands already grown -- a DiffLocks sample, say -- onto the GPU, to
463:     /// be prepared for drawing like a groom grown there.
464:     pub fn upload(&self, strands: &Strands, head: Option<&Head>) -> Result<GpuGroom> {
465:         let n = strands.len();
466:         let positions: Vec<[f32; 4]> = strands
467:             .positions
468:             .iter()
469:             .map(|p| [p.x, p.y, p.z, 0.0])
470:             .collect();
471:         let attributes: Vec<StrandGpu> = (0..n)
472:             .map(|s| {
473:                 let a = strands.attachment(s);
474:                 StrandGpu {
475:                     normal: a.normal.to_array(),
476:                     id: (a.id).word(),
477:                     uv: a.uv,
478:                     group: (a.group).gpu_word(),
479:                     radius: a.radius,
480:                 }
481:             })
482:             .collect();
483:         let roots: Vec<[f32; 4]> = (0..n)
484:             .map(|s| {
485:                 let r = strands.root(s);
486:                 [r.x, r.y, r.z, 1.0]
487:             })
488:             .collect();
489:         let [lo, hi] = strands.bounds();
490:         let (mut root_lo, mut root_hi) =
491:             (Vec3::splat(f32::INFINITY), Vec3::splat(f32::NEG_INFINITY));
492:         for s in 0..n {
493:             root_lo = root_lo.min(strands.root(s));
494:             root_hi = root_hi.max(strands.root(s));
495:         }
496:         Ok(GpuGroom {
497:             strands: n as u32,
498:             points: strands.points as u32,
499:             positions: upload(&self.context, &positions, "hair positions".into())?,
500:             attributes: upload(&self.context, &attributes, "hair strands".into())?,
501:             roots: upload(&self.context, &roots, "hair roots".into())?,
502:             bounds: Some([lo, hi]),
503:             root_bounds: [root_lo, root_hi],
504:             head: head.cloned(),
505:             guides: None,
506:         })
507:     }
508: 
509:     /// Wait for everything submitted to finish.
510:     pub fn finish(&self) {
511:         let _ = self
512:             .context
513:             .device
514:             .poll(wgpu::PollType::wait_indefinitely());
515:     }
516: 
517:     /// One word of `buffer`, `at` words in, read back.
518:     fn read_word(&mut self, batch: KernelBatch, buffer: &Buffer, at: u32) -> Result<u32> {
519:         Ok(self.read_words(batch, &[(buffer.clone(), at)])?[0])
520:     }
521: 
522:     /// Words of buffers (each `at` words in), read back after `batch` in
523:     /// one wait.
524:     fn read_words(&mut self, batch: KernelBatch, words: &[(Buffer, u32)]) -> Result<Vec<u32>> {
525:         let mut batch = batch;
526:         let out = self.scratch.word.fit(
527:             &self.context,
528:             ((words.len() as u64 * 4).max(16)).into(),
529:             "hair readback words".into(),
530:         )?;
531:         for (k, (buffer, at)) in words.iter().enumerate() {
532:             batch.encoder().copy_buffer_to_buffer(
533:                 &buffer.buffer,
534:                 *at as u64 * 4,
535:                 &out.buffer,
536:                 k as u64 * 4,
537:                 4,
538:             );
539:         }
540:         batch.submit();

541:         let values: Vec<u32> = pollster::block_on(out.read(&self.context))?;
542:         if values.len() < words.len() {
543:             return Err(HairGpuError::ShortReadback {
544:                 expected: (words.len() * std::mem::size_of::<u32>()).into(),
545:                 actual: (values.len() * std::mem::size_of::<u32>()).into(),
546:             });
547:         }
548:         Ok(values[..words.len()].to_vec())
549:     }
550: 
551:     fn ensure_scan(&mut self, count: u32) -> Result<()> {
552:         self.scan_scratch
553:             .ensure(&self.context, ScanElementCount::from_elements(count))?;
554:         Ok(())
555:     }
556: }
