558: impl GpuGroom {
559:     /// The strands back on the host.
560:     pub fn read(&self, context: &WgpuContext) -> Result<Strands> {
561:         read_strands(
562:             context,
563:             &self.positions,
564:             &self.attributes,
565:             self.strands,
566:             self.points,
567:         )
568:     }
569: }
570: 
571: /// `count` strands of `points` points back on the host.
572: fn read_strands(
573:     context: &WgpuContext,
574:     positions: &Buffer,
575:     attributes: &Buffer,
576:     count: u32,
577:     points: u32,
578: ) -> Result<Strands> {
579:     let positions: Vec<[f32; 4]> = pollster::block_on(positions.read(context))?;
580:     let attributes: Vec<StrandGpu> = pollster::block_on(attributes.read(context))?;
581:     let points = points as usize;
582:     let mut strands = Strands::with_capacity(points, count as usize);
583:     let mut strand = vec![Vec3::default(); points];
584:     for s in 0..count as usize {
585:         for (j, p) in strand.iter_mut().enumerate() {
586:             let q = positions[s * points + j];
587:             *p = Vec3::new(q[0], q[1], q[2]);
588:         }
589:         let a = attributes[s];
590:         strands.push(
591:             &strand,
592:             Attachment {
593:                 uv: a.uv,
594:                 normal: Vec3::from_array(a.normal),
595:                 id: StrandId::from_word(a.id),
596:                 group: PartingGroup::from_gpu_word(a.group),
597:                 radius: a.radius,
598:             },
599:         );
600:     }
601:     Ok(strands)
602: }
