604: /// A device of its own, for grooming and drawing without a window.
605: pub fn headless_context() -> Result<WgpuContext> {
606:     pollster::block_on(async {
607:         let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
608:             backends: wgpu::Backends::all(),
609:             ..wgpu::InstanceDescriptor::new_without_display_handle()
610:         });
611:         let adapter = instance
612:             .request_adapter(&wgpu::RequestAdapterOptions {
613:                 power_preference: wgpu::PowerPreference::HighPerformance,
614:                 compatible_surface: None,
615:                 force_fallback_adapter: false,
616:             })
617:             .await
618:             .map_err(HairGpuError::Adapter)?;
619:         let limits = required_limits(&adapter);
620:         let (device, queue) = adapter
621:             .request_device(&wgpu::DeviceDescriptor {
622:                 label: Some("hair"),
623:                 required_features: wgpu::Features::empty(),
624:                 required_limits: limits,
625:                 memory_hints: wgpu::MemoryHints::Performance,
626:                 experimental_features: wgpu::ExperimentalFeatures::default(),
627:                 trace: Default::default(),
628:             })
629:             .await?;
630:         Ok(WgpuContext::from_parts(
631:             Arc::new(instance),
632:             Arc::new(adapter),
633:             Arc::new(device),
634:             Arc::new(queue),
635:         ))
636:     })
637: }
