645:         max_buffer_size: adapter_limits.max_buffer_size,
646:         max_storage_buffer_binding_size: adapter_limits.max_storage_buffer_binding_size,
647:         max_storage_buffers_per_shader_stage: adapter_limits.max_storage_buffers_per_shader_stage,
648:         ..Default::default()
649:     }
650: }
