874:                 crate::collider::keep_clear(&head, &mut host, 0.0012, 4);
875:                 for (j, h) in host.iter().enumerate() {
876:                     let p = levels[1][slot * n + j];
877:                     let off = (Vec3::new(p[0], p[1], p[2]) - *h).length();
878:                     assert!(
879:                         off < 2e-4,
880:                         "{name}: strand {slot} point {j} is {off} off the host's"
881:                     );
882:                 }
883:             }
884:         }
885:     }
