977:     /// Grown on the GPU, a hairdo's guides are the host's: the same roots,
978:     /// combed the same way, draped and wrapped the same way.
979:     #[test]
980:     fn guides_grow_on_the_gpu_as_on_the_host() {
981:         use crate::ops::Context;
982:         let Ok(context) = headless_context() else {
983:             eprintln!("no GPU: skipped");
984:             return;
985:         };
986:         let mut groomer = GpuGroomer::new(context).expect("kernels");
987:         for preset in [
988:             Preset::Long,
989:             Preset::Bob,
990:             Preset::Afro,
991:             Preset::Ringlets,
992:             Preset::Ponytail,
993:             Preset::Bun,
994:             Preset::Braid,
995:             Preset::Mohawk,
996:             Preset::Buzz,
997:             Preset::Bangs,
998:             Preset::Balding,
999:             Preset::SideSwept,
1000:             Preset::Dreadlocks,
1001:         ] {
1002:             let mut look = Look::new(preset);
1003:             look.strands = StrandCount::from_count(5_000);
1004:             look.wind = AccelerationVector::from_components([1.5, 0.0, 0.5]);
1005:             let head = look.head(&Head::mannequin());
1006:             let scalp = head.scalp(0.006);
1007:             let groom = look.groom(&head);
1008:             let points = groom.points.max(2);
1009:             // The host's guides, straight to the groom's points, and the
1010:             // operations before interpolation run over them.
1011:             let mut host = look.hairdo.guides(
1012:                 &head,
1013:                 &scalp,
1014:                 points,
1015:                 look.variation.ratio(),
1016:                 look.seed.word() as u64,
1017:             );
1018:             let at = groom
1019:                 .ops
1020:                 .iter()
1021:                 .position(|op| matches!(op, crate::ops::Op::Interpolate(_)))
1022:                 .expect("interpolates");
1023:             let host_context = Context {
1024:                 scalp: &scalp,
1025:                 collider: &head,
1026:             };
1027:             for op in &groom.ops[..at] {
1028:                 op.apply(&mut host, &host_context);
1029:             }
1030:             let uploaded = groomer.upload_scalp(&scalp).expect("scalp");
1031:             let grown = groomer.grow_look(&look, &head, &uploaded).expect("grown");
1032:             let gpu = grown
1033:                 .guides
1034:                 .as_ref()
1035:                 .expect("guides")
1036:                 .read(groomer.context())
1037:                 .expect("read back");
1038:             let name = preset.name();
1039:             assert!(!gpu.has_non_finite(), "{name}");
1040:             assert!(
1041:                 gpu.len().abs_diff(host.len()) <= 2,
1042:                 "{name}: {} guides against {}",
1043:                 gpu.len(),
1044:                 host.len()
1045:             );
1046:             // Each guide against the host's rooted at the same place.
1047:             let mut off = Vec::new();
1048:             for g in 0..gpu.len() {
1049:                 let root = gpu.root(g);
1050:                 let Some(h) = (0..host.len()).find(|&h| (host.root(h) - root).length() < 1e-3)
1051:                 else {
1052:                     continue;
1053:                 };
1054:                 let mean = gpu
1055:                     .strand(g)
1056:                     .iter()
1057:                     .zip(host.strand(h))
1058:                     .map(|(a, b)| (*a - *b).length())
1059:                     .sum::<f32>()
1060:                     / points as f32;
1061:                 off.push(mean);
1062:             }
1063:             assert!(
1064:                 off.len() * 100 >= gpu.len() * 97,
1065:                 "{name}: {} of {} guides rooted as on the host",
1066:                 off.len(),
1067:                 gpu.len()
1068:             );
1069:             off.sort_by(f32::total_cmp);
1070:             let median = off[off.len() / 2];
1071:             let high = off[off.len() * 9 / 10];
1072:             // The same numbers drawn and the same steps taken: only the
1073:             // floating point differs. Along a metre of braid that shifts a
1074:             // strand a millimetre or two, and now and then a step lands on
1075:             // the other side of a threshold (lying on the head or not) and
1076:             // the strand goes its own way from there -- a guide in a hundred.
1077:             let worst = *off.last().expect("matched above");
1078:             let astray = off.iter().filter(|&&o| o > 2e-3).count();
1079:             assert!(median < 1e-4, "{name}: guides {median} m off the host's");
1080:             assert!(

1081:                 high < 1e-3,
1082:                 "{name}: a tenth of the guides {high} m off the host's"
1083:             );
1084:             assert!(astray * 50 <= off.len(), "{name}: {astray} guides astray");
1085:             assert!(worst < 5e-2, "{name}: a guide {worst} m off the host's");
1086:         }
1087:     }
