1202:     /// At rest, hair lying on hair stays as it lies: strands meeting each
1203:     /// other answer motion, not where the groom put them.
1204:     #[test]
1205:     fn strands_meeting_leave_a_groom_at_rest() {
1206:         use crate::sim::{Rigid, SimSettings};
1207:         let Ok(context) = headless_context() else {
1208:             eprintln!("no GPU: skipped");
1209:             return;
1210:         };
1211:         let mut groomer = GpuGroomer::new(context).expect("kernels");
1212:         groomer
1213:             .set_head_mesh(&Head::mannequin().mesh(0.008))
1214:             .expect("head");
1215:         let mut look = Look::new(Preset::Long);
1216:         look.strands = StrandCount::from_count(20_000);
1217:         let head = look.head(&Head::mannequin());
1218:         let scalp = groomer.cut_scalp(&head, 0.006).expect("scalp");
1219:         let grown = groomer.grow_look(&look, &head, &scalp).expect("grown");
1220:         let lods = groomer
1221:             .lods(&grown, head.cranium.center, &crate::LodSettings::default())
1222:             .expect("levels");
1223:         let run = |groomer: &mut GpuGroomer, settings: SimSettings| {
1224:             let mut sim = groomer.simulate(&lods, Some(&head), settings).expect("sim");
1225:             for _ in 0..60 {
1226:                 sim.step(groomer, 1.0 / 60.0, Rigid::default())
1227:                     .expect("step");
1228:             }
1229:             sim.read_positions(groomer).expect("read")
1230:         };
1231:         let settings = SimSettings::default();
1232:         let meeting = run(&mut groomer, settings);
1233:         let alone = run(&mut groomer, settings.alone());
1234:         // How far each is from the groom: the solver alone settles a
1235:         // little under gravity; meeting must not puff the hair out.
1236:         let rest = groomer
1237:             .simulate(&lods, Some(&head), settings)
1238:             .expect("sim")
1239:             .read_rest(&groomer)
1240:             .expect("read");
1241:         let from_rest = |now: &[[f32; 4]]| {
1242:             now.iter()
1243:                 .zip(&rest)
1244:                 .map(|(a, b)| (Vec3::new(a[0], a[1], a[2]) - Vec3::new(b[0], b[1], b[2])).length())
1245:                 .sum::<f32>()
1246:                 / now.len() as f32
1247:         };
1248:         let (meeting, alone) = (from_rest(&meeting), from_rest(&alone));
1249:         assert!(
1250:             meeting < alone + 1e-3,
1251:             "meeting moved a groom at rest {meeting} m from its groom, alone {alone} m"
1252:         );
1253:     }
