1255:     /// Two strands swung into each other across their paths stop where
1256:     /// they meet, the one above still above; without the strands'
1257:     /// collisions they pass through.
1258:     #[test]
1259:     fn a_strand_does_not_pass_through_another() {
1260:         use crate::strands::{Attachment, Strands};

1261:         let Ok(context) = headless_context() else {
1262:             eprintln!("no GPU: skipped");
1263:             return;
1264:         };
1265:         let mut groomer = GpuGroomer::new(context).expect("kernels");
1266:         let points = 16;
1267:         let mut strands = Strands::new(points);
1268:         let line = |from: Vec3, to: Vec3| -> Vec<Vec3> {
1269:             (0..points)
1270:                 .map(|j| from.lerp(to, j as f32 / (points - 1) as f32))
1271:                 .collect()
1272:         };
1273:         // One along x, swinging down; one along z beneath it, swinging up:
1274:         // their bending brings them back, after passing through if nothing
1275:         // stops them.
1276:         strands.push(
1277:             &line(Vec3::new(-0.1, 0.0, 0.0), Vec3::new(0.16, 0.0, 0.0)),
1278:             Attachment {
1279:                 id: StrandId::from_word(1),
1280:                 ..Default::default()
1281:             },
1282:         );
1283:         strands.push(
1284:             &line(Vec3::new(0.05, -0.03, -0.1), Vec3::new(0.05, -0.03, 0.16)),
1285:             Attachment {
1286:                 id: StrandId::from_word(2),
1287:                 ..Default::default()
1288:             },
1289:         );
1290:         let mut crossing = |collide: bool| {
1291:             // Hair's own bending and damping, nothing pulling it back.
1292:             let settings = crate::sim::SimSettings {
1293:                 guides: 2,
1294:                 points,
1295:                 strand_collision: collide,
1296:                 collision_radius: 0.006,
1297:                 clump: crate::sim::SimSettings::default().clump,
1298:                 internal_damping: crate::sim::SimSettings::default().internal_damping,
1299:                 ..quiet()
1300:             };
1301:             let mut sim = bare_sim(&mut groomer, &strands, settings);
1302:             let rest = sim.read_rest(&groomer).expect("read");
1303:             // Which simulated strand is the upper: rooted at -x.
1304:             let upper = if rest[0][0] < -0.05 { 0 } else { 1 };
1305:             // Each moving towards the other, faster towards its tip.
1306:             let previous: Vec<[f32; 4]> = rest
1307:                 .iter()
1308:                 .enumerate()
1309:                 .map(|(i, p)| {
1310:                     let along = (i % points) as f32 / (points - 1) as f32;
1311:                     let towards = if i / points == upper { 1.0 } else { -1.0 };
1312:                     [p[0], p[1] + 0.004 * along * towards, p[2], 1.0]
1313:                 })
1314:                 .collect();
1315:             sim.set_state(&groomer, &rest, &previous).expect("state");
1316:             // Wherever the two cross, seen from above, every frame: how far
1317:             // the upper is above the lower there.
1318:             let mut heights = Vec::new();
1319:             for _ in 0..20 {
1320:                 sim.step(&groomer, 1.0 / 60.0, crate::sim::Rigid::default())
1321:                     .expect("step");
1322:                 let now = sim.read_positions(&groomer).expect("read");
1323:                 let strand = |g: usize| &now[g * points..(g + 1) * points];
1324:                 let (top, bottom) = (strand(upper), strand(1 - upper));
1325:                 for a in top.windows(2) {
1326:                     for b in bottom.windows(2) {
1327:                         let (p, r) = ([a[0][0], a[0][2]], [a[1][0] - a[0][0], a[1][2] - a[0][2]]);
1328:                         let (q, t) = ([b[0][0], b[0][2]], [b[1][0] - b[0][0], b[1][2] - b[0][2]]);
1329:                         let cross = r[0] * t[1] - r[1] * t[0];
1330:                         if cross.abs() < 1e-12 {
1331:                             continue;
1332:                         }
1333:                         let d = [q[0] - p[0], q[1] - p[1]];
1334:                         let u = (d[0] * t[1] - d[1] * t[0]) / cross;
1335:                         let v = (d[0] * r[1] - d[1] * r[0]) / cross;
1336:                         if (0.0..=1.0).contains(&u) && (0.0..=1.0).contains(&v) {
1337:                             let ya = a[0][1] + (a[1][1] - a[0][1]) * u;
1338:                             let yb = b[0][1] + (b[1][1] - b[0][1]) * v;
1339:                             heights.push(ya - yb);
1340:                         }
1341:                     }
1342:                 }
1343:             }
1344:             heights
1345:         };
1346:         let with = crossing(true);
1347:         let without = crossing(false);
1348:         assert!(
1349:             without.iter().any(|&h| h < -0.01),
1350:             "without collisions they should pass: {without:?}"
1351:         );
1352:         // Through by no more than a sliver of the radius.
1353:         assert!(
1354:             with.iter().all(|&h| h > -0.002),
1355:             "they passed through: {with:?} above"
1356:         );
1357:     }
