1359:     /// A bundle pressed together spreads again: the volume pushes hair
1360:     /// denser than at rest apart.
1361:     #[test]
1362:     fn hair_pressed_together_keeps_its_volume() {
1363:         use crate::strands::{Attachment, Strands};
1364:         let Ok(context) = headless_context() else {
1365:             eprintln!("no GPU: skipped");
