1368:         let mut groomer = GpuGroomer::new(context).expect("kernels");
1369:         let points = 12;
1370:         let mut strands = Strands::new(points);
1371:         let mut id = 0;
1372:         for a in 0..8 {
1373:             for b in 0..8 {
1374:                 let root = Vec3::new((a as f32 - 3.5) * 0.01, 0.0, (b as f32 - 3.5) * 0.01);
1375:                 let strand: Vec<Vec3> = (0..points)
1376:                     .map(|j| root + Vec3::new(0.0, -0.15 * j as f32 / (points - 1) as f32, 0.0))
1377:                     .collect();
1378:                 id += 1;
1379:                 strands.push(
1380:                     &strand,
1381:                     Attachment {
1382:                         id: StrandId::from_word(id),
1383:                         ..Default::default()
