56:     /// stack need not run.
57:     pub fn grow_while(
58:         &self,
59:         guides: &Strands,
60:         context: &Context,
61:         keep_going: impl Fn() -> bool,
62:     ) -> Option<(Strands, GrowReport)> {
63:         let mut strands = guides.resampled(self.points.max(2));
64:         let mut report = GrowReport::default();
65:         for op in &self.ops {
66:             if !keep_going() {
67:                 return None;
