69:             let started = Instant::now();
70:             op.apply(&mut strands, context);
71:             report.steps.push((
72:                 op.name(),
73:                 started.elapsed().as_secs_f32() * 1e3,
74:                 strands.len(),
75:             ));
76:         }
77:         Some((strands, report))
