448:             let gap = distance - lift;
449:             // Hair over the forehead rests on it, however high it came from.
450:             let resting = over_face(p) && gap < 0.03;
451:             let supported =
452:                 (gap < style.cling || resting) && n.y > -0.3 && !matches!(flow, Flow::Radial);
453:             let force = Vec3::down();
454: 
455:             if let (Flow::Tie(_), Some(tie)) = (flow, tie) {
456:                 // At the tie -- or, for a strand that cannot reach it from
457:                 // right beneath it, as far as it would have come.
458:                 if (tie.point - p).length() < 0.02 || s > 1.6 * to_tie + 0.03 {
459:                     tied_at = Some(s);
460:                     continue;
461:                 }
462:                 // Over the scalp to the tie, held there: no sliding.
463:                 let want = safe_normalize(tangent(tie.point - p, n), d);
464:                 d = safe_normalize(d.lerp(want, (ds / 0.01).min(1.0)), want);
465:             } else if supported {
466:                 // Lying on the hair beneath: the comb, and gravity down the
467:                 // slope as the hair still to come weighs.
468:                 // A fringe combed forward over the hairline falls straight down
469:                 // the forehead: forward, turned into a curved forehead, would
470:                 // gather it to a point over the nose.
471:                 let comb_to = if over_face(p) && fringed {
472:                     Vec3::down()
473:                 } else {
474:                     flow_at(p) + wander
475:                 };
476:                 let combed = safe_normalize(tangent(comb_to, n), d);
477:                 let downhill = tangent(force, n);
478:                 let mut slide = smoothstep(0.0, 4.0 * stiffness, remaining);
479:                 // Hair lying combed on the hair beneath is held there by
480:                 // friction, and slides only where the weight of what hangs
481:                 // from it pulls it off. Over the front of the head that pull
482:                 // is along the comb, to where the hair hangs beside the face:
483:                 // downhill there would be onto the face, which only hair
484:                 // combed that way (a fringe) goes.
485:                 if !fringed && over_face(p + safe_normalize(downhill, d) * 0.02) {
486:                     slide *= 0.05;
487:                 }
488:                 let want = safe_normalize(combed * (1.0 - slide) + downhill * slide, combed);
489:                 // Rising to its layer near the root, the strand keeps its angle.
490:                 let rising = 1.0 - smoothstep(0.0, rise, s);
491:                 let want = safe_normalize(want * (1.0 - rising) + leaving * rising, want);
492:                 d = safe_normalize(d.lerp(want, (ds / 0.012).min(1.0)), want);
493:             } else {
494:                 // Free: a cantilever under its own weight -- stiff or short
495:                 // hair standing out barely bends.
496:                 d = cantilever(d, force, remaining, stiffness, ds);
497:             }
498:             // Coily hair wanders: a random turn a step, growing with the root of
499:             // the distance (a random walk in direction).
500:             if follicles.kink > 0.0 {
501:                 let axis = safe_normalize(
502:                     d.cross(Vec3::new(rng.gaussian(), rng.gaussian(), rng.gaussian())),
503:                     crate::strands::orthogonal(d),
504:                 );
505:                 d = rotate(d, axis, rng.gaussian() * follicles.kink * ds.sqrt());
506:                 let outward = safe_normalize(p - head.cranium.center, d);
507:                 d = safe_normalize(d + outward * 0.05, d);
508:             }
509:             // The last few centimetres of a tucked cut turn in towards the neck.
510:             if tuck > 0.0 && remaining < 0.05 {
511:                 let neck = Vec3::new(0.0, p.y, head.neck.a.z);
512:                 let inward = safe_normalize(tangent(neck - p, d), d);
513:                 d = safe_normalize(d + inward * (tuck * ds / 0.05), d);
514:             }
515: 
516:             let mut next = p + d * ds;
517:             let floor_here = height(next, s + ds);
518:             let distance = head.distance(next);
519:             if distance < floor_here {
520:                 next += head.gradient(next) * (floor_here - distance);
521:                 next = p + safe_normalize(next - p, d) * ds;
522:             } else if supported && distance > floor_here {
523:                 // Lying on the layer below: settle onto it where it drops away.
524:                 next -= head.gradient(next) * ((distance - floor_here) * 0.15);
525:                 next = p + safe_normalize(next - p, d) * ds;
526:             }
527:             d = safe_normalize(next - p, d);
528:             p = next;
529:             path.push(p);
530:             if is_cut(p) {
531:                 break;
532:             }
533:         }
534:         path
535:     }
536: }
