558: impl Hairdo {
559:     /// How the comb runs, as the GPU's guide kernel takes it: a code
560:     /// (natural, part, swept, back, forward, radial, down, tie) and its one
561:     /// value (the part's `x`, the sweep's side, the tie: tail, bun or
562:     /// braid).
563:     #[cfg_attr(not(feature = "gpu"), allow(dead_code))]
564:     pub(crate) fn flow_code(&self) -> (u32, f32) {
565:         match self.flow() {
566:             Flow::Natural => (0, 0.0),
567:             Flow::Part(x) => (1, x),
568:             Flow::Swept(side) => (2, side),
569:             Flow::Back => (3, 0.0),
570:             Flow::Forward => (4, 0.0),
571:             Flow::Radial => (5, 0.0),
572:             Flow::Down => (6, 0.0),
573:             Flow::Tie(Tie::Tail) => (7, 0.0),
574:             Flow::Tie(Tie::Bun) => (7, 1.0),
575:             Flow::Tie(Tie::Braid) => (7, 2.0),
576:         }
577:     }
578: }
579: 
580: /// Bend `d` towards `force` as a cantilever with `remaining` metres of hair
581: /// still to hang off it: curvature `remaining^2 / (2 L_g^3)` times the sine
582: /// of the angle between them, over one step, never past the force.
583: fn cantilever(d: Vec3, force: Vec3, remaining: f32, stiffness: f32, ds: f32) -> Vec3 {
584:     let axis = d.cross(force);
585:     let sin = axis.length();
586:     if sin < 1e-6 {
587:         return d;
588:     }
589:     let angle = sin.atan2(d.dot(force));
590:     let curvature = remaining.max(0.0).powi(2) / (2.0 * stiffness.powi(3)) * sin;
591:     rotate(d, axis * (1.0 / sin), (curvature * ds).min(angle))
592: }
593: 
594: /// The component of `v` in the plane with normal `n`.
595: fn tangent(v: Vec3, n: Vec3) -> Vec3 {
596:     v - n * v.dot(n)
597: }
