1: //! Expansion of semantic hair parameters into the native numerical node graph.
2: //!
3: //! Unit getters here are the handoff to the CPU/WGSL numerical operations.
4: //! Keep operation order, seed words and floating-point expression order stable.
5: 
6: use super::Look;
7: use crate::ops::{
8:     Clump, Curl, DensityMask, Frizz, Interpolate, Noise, Op, Orient, Profile, Settle, Shrinkwrap,
9:     Trim, Wave,
10: };
11: use crate::{Groom, Head};
12: 
13: impl Look {
14:     /// Expand into the original numerical operation graph, in evaluation order.
15:     pub fn groom(&self, head: &Head) -> Groom {
16:         let mut ops = Vec::new();
17:         self.guide_operations(head, &mut ops);
18:         self.coarse_texture(&mut ops);
19:         self.fine_texture(&mut ops);
20:         Groom {
21:             points: self.points.count(),
22:             ops,
23:         }
24:     }
25: 
26:     fn guide_operations(&self, head: &Head, ops: &mut Vec<Op>) {
27:         let seed = self.seed.word();
28:         let hairdo = &self.hairdo;
29:         let follicles = &self.hairdo.follicles;
30:         if self.drape.enabled() {
31:             ops.push(Op::Settle(Settle {
32:                 gravity: self.gravity.metres_per_second_squared(),
33:                 wind: self.wind.components(),
34:                 ..Default::default()
35:             }));
36:             ops.push(Op::Shrinkwrap(Shrinkwrap {
37:                 offset: 0.003,
38:                 smoothing: 4,
39:                 preserve_length: true,
40:                 ..Default::default()
41:             }));
42:         }
43:         let [crown, temples, top] = follicles.balding;
44:         ops.push(Op::Interpolate(Interpolate {
45:             count: self.strands.count(),
46:             neighbors: self.neighbors.count(),
47:             parting: hairdo.parting(),
48:             // Where neighbouring guides are combed apart, a strand follows
49:             // one of them: the hair parts, it does not fill the gap.
50:             divergence: 0.5,
51:             // Hair that stands out follows its own root's normal all the
52:             // way; hair that lies on the head only leaves the scalp so.
53:             follow_length: if hairdo.stands() { 1.0 } else { 0.05 },
54:             density: if crown + temples + top > 0.0 {
55:                 DensityMask::Balding {
56:                     crown,
57:                     temples,
58:                     top,
59:                 }
60:             } else {
61:                 DensityMask::Uniform
62:             },
63:             patchiness: follicles.patchiness,
64:             edge: follicles.hairline.softness,
65:             radius: follicles.radius,
66:             seed,
67:             ..Default::default()
68:         }));
69:         ops.push(Op::Orient(Orient {
70:             field: follicles.field(head),
71:             memory: follicles.memory,
72:             direction_spread: follicles.direction_spread,
73:             angle_spread: follicles.angle_spread,
74:             seed: seed + 9,
75:         }));
76:         if self.length_variation.ratio() > 0.0 {
77:             ops.push(Op::Trim(Trim {
78:                 length: 1.0,
79:                 random: self.length_variation.ratio(),
80:                 max_length: 0.0,
81:                 seed: seed + 1,
82:             }));
83:         }
84:     }
85: 
86:     fn coarse_texture(&self, ops: &mut Vec<Op>) {
87:         let seed = self.seed.word();
88:         if self.clump.ratio() > 0.0 {
89:             // Dreadlocks are clumped all along, into ropes.
90:             let rope = self.locs.enabled();
91:             ops.push(Op::Clump(Clump {
92:                 guide_distance: self.clump_size.metres(),
93:                 factor: if rope {
94:                     0.93 * self.clump.ratio()
95:                 } else {
96:                     self.clump.ratio() * 0.8
97:                 },
98:                 // A rope gathers within a few centimetres of the scalp.
99:                 shape: if rope { 0.05 } else { 0.3 },
100:                 twist: self.twist.radians_per_metre(),
101:                 twist_random: 0.5,
102:                 tip_spread: self.clump_size.metres() * 0.15,
103:                 clump_offset: self.clump_size.metres() * 0.2,
104:                 preserve_length: true,
105:                 seed: seed + 2,
106:                 min_length: 0.015,
107:                 ..Default::default()
108:             }));
109:         }
110:         if self.curl.ratio() > 0.0 {
111:             ops.push(Op::Curl(Curl {
112:                 guide_distance: self.curl_size.metres(),
113:                 reuse_guide_map: false,
114:                 factor: self.curl.ratio(),
115:                 curl_start: self.curl_start.ratio(),
116:                 radius: self.curl_radius.metres(),
117:                 factor_start: 0.7,
118:                 factor_end: 1.0,
119:                 frequency: self.curl_turns.turns_per_metre() / 3.0,
120:                 random_offset: 0.15,
121:                 seed: seed + 3,
122:                 ..Default::default()
123:             }));
124:         }
125:         if self.wave.metres() > 0.0 {
126:             ops.push(Op::Wave(Wave {
127:                 amplitude: self.wave.metres(),
128:                 wavelength: self.wavelength.metres(),
129:                 seed: seed + 8,
130:                 ..Default::default()
131:             }));
132:         }
133:     }
134: 
135:     fn fine_texture(&self, ops: &mut Vec<Op>) {
136:         let seed = self.seed.word();
137:         let follicles = &self.hairdo.follicles;
138:         if self.clump.ratio() > 0.0 && !self.locs.enabled() {
139:             ops.push(Op::Clump(Clump {
140:                 guide_distance: (self.clump_size.metres() * 0.3).max(0.003),
141:                 factor: self.clump.ratio() * 0.6,
142:                 shape: 0.75,
143:                 tip_spread: 0.001,
144:                 preserve_length: true,
145:                 seed: seed + 4,
146:                 min_length: 0.015,
147:                 ..Default::default()
148:             }));
149:         }
150:         if self.noise.metres() > 0.0 {
151:             ops.push(Op::Noise(Noise {
152:                 // Offsets, not a walk: Blender's cumulative noise sums a
153:                 // point's offset per point, so its reach grows with the
154:                 // point count. Here `distance` is how far hair strays.
155:                 cumulative: false,
156:                 distance: self.noise.metres(),
157:                 scale: 6.0,
158:                 scale_along_curve: self.noise_scale.per_metre() / 5.0,
159:                 offset_per_curve: 0.02,
160:                 shape: 0.6,
161:                 preserve_length: true,
162:                 seed: seed + 5,
163:                 ..Default::default()
164:             }));
165:         }
166:         if self.frizz.metres() > 0.0 {
167:             ops.push(Op::Frizz(Frizz {
168:                 distance: self.frizz.metres(),
169:                 shape: 0.5,
170:                 cumulative: true,
171:                 seed: seed + 6,
172:                 share: self.flyaways.ratio(),
173:                 // Every strand wanders a little on its own, so that no two
174:                 // lie quite parallel: the highlight breaks into strands.
175:                 calm: 0.12,
176:                 frequency: 15.0,
177:                 ..Default::default()
178:             }));
179:         }
180:         ops.push(Op::Shrinkwrap(Shrinkwrap {
181:             offset: 0.0015,
182:             smoothing: 3,
183:             preserve_length: false,
184:             ..Default::default()
185:         }));
186:         ops.push(Op::Profile(Profile {
187:             radius: follicles.radius,
188:             random: follicles.radius_spread,
189:             seed: seed + 7,
190:             relative_to: Some(follicles.radius),
191:         }));
192:     }
193: }
