8:     for (growth, weight) in [
9:         (Growth::Whorl, 55),
10:         (Growth::Cowlick, 12),
11:         (Growth::DoubleWhorl, 8),
12:         (Growth::Radial, 5),
13:         (Growth::Forward, 8),
14:         (Growth::Backward, 7),
15:         (Growth::Down, 5),
16:     ] {
17:         pick -= weight;
18:         if pick < 0 {
19:             f.growth = growth;
20:             break;
21:         }
22:     }
23:     f.whorl = [rng.range(-0.3, 0.3), rng.range(0.3, 0.8)];
24:     f.spiral = rng.range(0.6, 1.6);
25:     f.clockwise = rng.chance(0.75);
26:     f.angle = (f.angle * rng.range(0.7, 1.5)).clamp(0.1, 1.2);
27:     f.angle_spread = rng.range(0.05, 0.2);
