124: /// Chiang's polynomial in the azimuthal roughness, relating a colour to its
125: /// absorption.
126: fn chiang(beta_n: f32) -> f32 {
127:     let b = beta_n;
128:     5.969 - 0.215 * b + 2.532 * b.powi(2) - 10.73 * b.powi(3)
129:         + 5.574 * b.powi(4)
130:         + 0.245 * b.powi(5)
131: }
