133: impl HairMaterial {
134:     pub fn named(name: &str) -> Option<Self> {
135:         let (melanin, redness) = match name {
136:             "black" => (0.95, 0.1),
137:             "dark brown" => (0.8, 0.25),
138:             "brown" => (0.7, 0.35),
139:             "auburn" => (0.55, 0.75),
140:             "red" => (0.4, 0.95),
141:             "blond" => (0.22, 0.4),
142:             "platinum" => (0.08, 0.2),
143:             "grey" => (0.25, 0.02),
144:             _ => return None,
145:         };
146:         Some(Self {
147:             melanin,
148:             redness,
149:             ..Default::default()
150:         })
151:     }
152: 
153:     /// Absorption coefficient per unit of fibre diameter, Blender's melanin
154:     /// model: eumelanin and pheomelanin in proportion `1 - redness :
155:     /// redness`, their total `-ln(1 - melanin)`, and a dye on top.
156:     pub fn absorption(&self) -> [f32; 3] {
157:         let quantity = -(1.0 - self.melanin).max(1e-4).ln();
158:         let eumelanin = quantity * (1.0 - self.redness);
159:         let pheomelanin = quantity * self.redness;
160:         const EU: [f32; 3] = [0.506, 0.841, 1.653];
161:         const PHEO: [f32; 3] = [0.343, 0.733, 1.924];
162:         let f = chiang(self.radial_roughness);
163:         std::array::from_fn(|k| {
164:             let dye = (self.tint[k].clamp(1e-3, 1.0).ln() / f).powi(2);
165:             eumelanin * EU[k] + pheomelanin * PHEO[k] + dye
166:         })
167:     }
168: 
169:     /// The colour a real-time model should give a strand of this material.
170:     ///
171:     /// Chiang's mapping between colour and absorption, inverted, over a
172:     /// quarter of the absorption: over the whole of it, the melanin
173:     /// quantities Blender calls brown come out near black and saturated,
174:     /// where Cycles renders them a mid brown. The quarter is calibrated by
175:     /// eye against Cycles' renders of the named colours; offline rendering
176:     /// should take [`HairMaterial::absorption`] itself.
177:     pub fn base_color(&self) -> [f32; 3] {
178:         let f = chiang(self.radial_roughness);
