30: pub struct Clump {
31:     /// Clump guides are at least this far apart at the root.
32:     pub guide_distance: f32,
33:     /// Chance a strand is a candidate guide.
34:     pub guide_mask: f32,
35:     /// Reuse the clumps an earlier operation chose (`Existing Guide Map`).
36:     pub reuse_guide_map: bool,
37:     pub factor: f32,
38:     /// Falloff along the strand: 0 clumps all along, 0.5 grows linearly to
39:     /// the tip, towards 1 only the tips gather.
40:     pub shape: f32,
41:     /// Radians per metre of arc length.
42:     pub twist: f32,
43:     /// How much of the twist is random per clump.
44:     pub twist_random: f32,
45:     pub twist_factor: f32,
