97:         let ids = &strands.id;
98:         let normals = &strands.root_normal;
99: 
100:         strands
101:             .positions
102:             .par_chunks_mut(points)
103:             .enumerate()
104:             .for_each_init(
105:                 || (Vec::new(), Vec::new()),
106:                 |(lengths, factors), (s, strand)| {
107:                     let g = map.guide[s] as usize;
108:                     let Some(guide) = samplers[g].as_ref() else {
109:                         return;
110:                     };
111:                     let root = reference[s * points];
112:                     let guide_root = guide.at_factor(0.0);
113:                     let offset = root - guide_root.position;
114:                     // The root's offset lies in the scalp; the guide leaves
115:                     // the scalp nearly along it. Across the flow stays
116:                     // across; along the flow becomes depth -- so a patch of
117:                     // roots becomes a round lock rather than a flat one.
118:                     let scalp = normals[g];
119:                     let t0 = guide_root.tangent;
120:                     let across = crate::strands::safe_normalize(t0.cross(scalp), guide_root.normal);
121:                     let along = crate::strands::safe_normalize(t0 - scalp * t0.dot(scalp), t0);
122:                     let depth =
123:                         crate::strands::safe_normalize(across.cross(t0), guide_root.binormal());
124:                     let placed = across * offset.dot(across) + depth * offset.dot(along);
125:                     let x = guide_root.normal.dot(placed);
126:                     let y = guide_root.binormal().dot(placed);
