128:                     // What the tips gather to, in the guide's tip frame.
129:                     let tip = guide.at_factor(1.0);
130:                     let mut gather = Vec3::default();
131:                     if self.tip_spread != 0.0 {
132:                         let r = rng::signed_vec3((ids[s]).word(), seed) * self.tip_spread;
133:                         gather += tip.normal * r.x + tip.binormal() * r.y + tip.tangent * r.z;
134:                     }
135:                     if self.clump_offset != 0.0 {
136:                         let r =
137:                             rng::signed_vec3((ids[g]).word(), seed ^ 0x0FF5) * self.clump_offset;
