141:                     let d = offset.length();
142:                     let weight = if self.distance_threshold != 0.0 && self.distance_falloff == 0.0 {
143:                         if d <= self.distance_threshold {
144:                             1.0
145:                         } else {
146:                             0.0
147:                         }
148:                     } else {
149:                         1.0 - smoothstep(
150:                             self.distance_threshold,
151:                             self.distance_threshold + self.distance_falloff,
152:                             d,
153:                         )
154:                     };
