165:                     for (j, p) in strand.iter_mut().enumerate().skip(1) {
166:                         let t = factors[j];
167:                         let f = shape_range(t, 0.0, 1.0, self.shape, 2.0);
168:                         let at = guide.at_factor(t);
169:                         let parallel = at.normal * x + at.binormal() * y;
170:                         let target = at.position + parallel * (1.0 - f) + gather * f;
