145: impl Profile {
146:     pub fn apply(&self, strands: &mut Strands) {
147:         let seed = rng::seed(self.seed, 51_823);
148:         for (r, &id) in strands.radius.iter_mut().zip(&strands.id) {
149:             let base = match self.relative_to {
150:                 Some(grown) if grown > 0.0 => self.radius * *r / grown,
151:                 _ => self.radius,
152:             };
153:             *r = base * (1.0 + self.random * rng::signed((id).word(), seed)).max(0.05);
154:         }
155:     }
