158: /// The `shape_range` node group: `value` mapped from `[min, max]` to `[0,
159: /// 1]`, bent by `shape`, and mapped back. `shape` 0 is constant 1 (the
160: /// effect everywhere), 0.5 is linear, towards 1 the effect gathers at the
161: /// top of the range; negative shapes mirror it. `base` sets how strongly
162: /// the shape bends (2 in every use).
163: pub fn shape_range(value: f32, min: f32, max: f32, shape: f32, base: f32) -> f32 {
164:     if shape.abs() < 1e-5 {
165:         return 1.0;
166:     }
167:     let x = if (max - min).abs() > 1e-12 {
168:         (value - min) / (max - min)
169:     } else {
170:         0.0
171:     };
172:     let b = base.max(1.00001);
173:     let a = shape.abs().min(0.999999);
174:     let negative = shape < 0.0;
175:     let flip = if a > 0.5 { !negative } else { negative };
176:     let xx = if flip { 1.0 - x } else { x };
177:     let pingpong = if a <= 0.5 { a } else { 1.0 - a };
178:     let m = pingpong * 2.0 * (1.0 - 1.0 / b);
179:     let exponent = -(1.0 - m).max(1e-5).ln() / b.max(1.000_001).ln();
180:     let y = xx.max(0.0).powf(exponent);

181:     let y = if a > 0.5 { 1.0 - y } else { y };
182:     (min + y.clamp(0.0, 1.0) * (max - min)).clamp(min.min(max), min.max(max))
183: }
