185: /// Blender's `Map Range` with smootherstep interpolation, clamped.
186: pub fn smootherstep(edge0: f32, edge1: f32, x: f32) -> f32 {
187:     let t = if (edge1 - edge0).abs() > 1e-12 {
188:         ((x - edge0) / (edge1 - edge0)).clamp(0.0, 1.0)
189:     } else {
190:         0.0
191:     };
192:     t * t * t * (t * (t * 6.0 - 15.0) + 10.0)
193: }
194: 
195: /// Blender's `Map Range` with smoothstep interpolation, clamped.
196: pub fn smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
197:     let t = if (edge1 - edge0).abs() > 1e-12 {
198:         ((x - edge0) / (edge1 - edge0)).clamp(0.0, 1.0)
199:     } else {
200:         0.0
201:     };
202:     t * t * (3.0 - 2.0 * t)
203: }
