205: /// Which strand leads each strand's clump: `Create Guide Index Map`.
206: ///
207: /// The node group scatters the roots, keeps each with probability `mask`,
208: /// merges them by `distance` -- what is left are the clump guides, spaced at
209: /// least that far apart -- and gives every strand the index of the guide
210: /// nearest its root, within its parting group. A distance of zero makes
211: /// every strand its own guide.
212: #[derive(Clone, Debug)]
213: pub struct GuideMap {
214:     /// For each strand, its guide's strand index.
215:     pub guide: Vec<u32>,
216:     /// The guides, in the order they were chosen.
217:     pub guides: Vec<u32>,
218: }
219: 
220: impl GuideMap {
221:     pub fn new(strands: &Strands, distance: f32, mask: f32, seed: u32) -> Self {
222:         let n = strands.len();
223:         if distance <= 0.0 || n == 0 {
224:             return Self {
225:                 guide: (0..n as u32).collect(),
226:                 guides: (0..n as u32).collect(),
227:             };
228:         }
229:         // Candidates in a random order; each kept with probability `mask`.
230:         let mut order: Vec<u32> = (0..n as u32).collect();
231:         order.sort_by_key(|&s| rng::hash(strands.id[s as usize].word(), seed));
232:         let mut grid = PointGrid::new(distance);
233:         let mut guides = Vec::new();
234:         for &s in &order {
235:             if rng::unit(strands.id[s as usize].word(), seed ^ 0x2F0B_1A3D) >= mask {
236:                 continue;
237:             }
238:             let root = strands.root(s as usize);
239:             let group = strands.group[s as usize];
240:             if !grid.any_within(root, distance, |g| g == group) {
241:                 grid.insert(root, group);
242:                 guides.push(s);
243:             }
244:         }
245:         if guides.is_empty() {
246:             let s = order[0];
247:             grid.insert(strands.root(s as usize), strands.group[s as usize]);
248:             guides.push(s);
249:         }
250:         let guide = (0..n)
251:             .into_par_iter()
252:             .map(|s| {
253:                 let root = strands.root(s);
254:                 let group = strands.group[s];
255:                 let nearest = grid
256:                     .nearest(root, distance * 8.0, |g| g == group)
257:                     .or_else(|| grid.nearest(root, f32::INFINITY, |_| true));
258:                 nearest.map_or(s as u32, |(i, _)| guides[i as usize])
259:             })
260:             .collect();
261:         Self { guide, guides }
262:     }
263: 
264:     /// The guide map `strands` carry from an earlier operation, if asked to
265:     /// reuse it and there is one; otherwise a new one, which the strands
266:     /// then carry (Blender stores it as `guide_curve_index`).
267:     pub fn get(strands: &mut Strands, reuse: bool, distance: f32, mask: f32, seed: u32) -> Self {
268:         if reuse && let Some(map) = &strands.guide_map {
269:             return map.clone();
270:         }
271:         let map = Self::new(strands, distance, mask, seed);
272:         strands.guide_map = Some(map.clone());
273:         map
274:     }
