276:     /// A sampler for every guide, indexed by strand (only guides filled).
277:     pub fn samplers(&self, strands: &Strands) -> Vec<Option<CurveSampler>> {
278:         let mut is_guide = vec![false; strands.len()];
279:         for &g in &self.guides {
