289: /// `Restore Curve Segment Length`: keep each segment's current direction
290: /// and give it back (by `factor`) the length it has in `reference`, walking
291: /// out from the root.
292: pub fn restore_lengths(strand: &mut [Vec3], reference: &[Vec3], factor: f32) {
293:     let mut previous = strand[0];
294:     let mut previous_old = strand[0];
295:     for i in 1..strand.len() {
296:         let current = strand[i];
297:         let direction = current - previous_old;
298:         let current_length = direction.length();
299:         let rest = (reference[i] - reference[i - 1]).length();
300:         let length = current_length + (rest - current_length) * factor;
301:         let direction = if current_length > 1e-12 {
302:             direction * (1.0 / current_length)
303:         } else {
304:             (reference[i] - reference[i - 1]).normalize()
305:         };
306:         previous_old = current;
307:         strand[i] = previous + direction * length;
308:         previous = strand[i];
309:     }
310: }
