312: /// Per point: its factor along the strand (arc length over total) and its
313: /// arc length.
314: pub(crate) fn parameters(strand: &[Vec3], lengths: &mut Vec<f32>, factors: &mut Vec<f32>) {
315:     crate::strands::arc_lengths(strand, lengths);
316:     let total = lengths.last().copied().unwrap_or(0.0).max(1e-12);
317:     factors.clear();
318:     factors.extend(lengths.iter().map(|l| l / total));
319: }
