422: /// Turn `v` by `share` of the rotation taking direction `from` to `to`.
423: fn turn_between(v: Vec3, from: Vec3, to: Vec3, share: f32) -> Vec3 {
424:     let from = safe_normalize(from, Vec3::up());
425:     let to = safe_normalize(to, Vec3::up());
426:     let axis = from.cross(to);
427:     let s = axis.length();
428:     let c = from.dot(to);
429:     if s < 1e-6 {
430:         return v;
431:     }
432:     rotate(v, axis * (1.0 / s), s.atan2(c) * share)
433: }

