98: /// Add frame-space offsets to a strand, walked from the root if
99: /// `cumulative`, faded in by `shape`.
100: fn displace(
101:     strand: &mut [Vec3],
102:     offsets: &mut [Vec3],
103:     factors: &[f32],
104:     cumulative: bool,
105:     shape: f32,
106: ) {
107:     let root = offsets[0];
108:     if cumulative {
109:         let mut trailing = Vec3::default();
110:         for o in offsets.iter_mut() {
111:             let v = *o;
112:             let leading = trailing + v;
113:             *o = (leading + trailing - root) * 0.5;
114:             trailing = leading;
115:         }
116:     } else {
117:         for o in offsets.iter_mut() {
118:             *o -= root;
119:         }
120:     }
121:     for (j, p) in strand.iter_mut().enumerate() {
122:         *p += offsets[j] * shape_range(factors[j], 0.0, 1.0, shape, 2.0);
123:     }
124: }
