47:                 let root = strand[0];
48:                 let n = safe_normalize(normals[s], Vec3::up());
49:                 // The way the strand leaves: its first few millimetres, in
50:                 // the scalp's plane.
51:                 let Some(ahead) = strand.iter().find(|p| (**p - root).length() > 0.002) else {
52:                     return;
53:                 };
54:                 let leaves = *ahead - root;
55:                 let flat = leaves - n * leaves.dot(n);
56:                 let grows = self.field.direction(root, n);
57:                 // Strands standing straight up have no way to turn from.
58:                 let turn = if flat.length() > 0.25 * leaves.length() {
59:                     let flat = flat.normalize();
60:                     n.dot(flat.cross(grows)).atan2(flat.dot(grows))
61:                 } else {
62:                     0.0
63:                 } + self.direction_spread * rng::signed((ids[s]).word(), seed);
64:                 let tilt = self.angle_spread * rng::signed((ids[s]).word(), seed ^ 0x7117);
65:                 let tilt_axis = safe_normalize(grows.cross(n), crate::strands::orthogonal(n));
66:                 // A root turned right round stands up.
67:                 let lift = (1.0 - turn.cos()) * 0.5 * self.memory * 0.35;
68:                 let mut along = 0.0;
69:                 let mut previous = root;
70:                 for p in strand.iter_mut().skip(1) {
71:                     along += (*p - previous).length();
72:                     previous = *p;
73:                     let share = 1.0 - crate::ops::smoothstep(0.0, self.memory, along);
74:                     if share <= 0.0 {
75:                         break;
76:                     }
77:                     let mut offset = rotate(*p - root, n, turn * share);
78:                     offset = rotate(offset, tilt_axis, -tilt * share);
79:                     let rise = lift * crate::ops::smoothstep(0.0, self.memory, along) * share * 4.0;
80:                     *p = root + offset + n * rise;
81:                 }
82:             });
83:     }
84: }
