1: //! `Shrinkwrap Hair Curves`: out of the body.
2: //!
3: //! Every point that has sunk below the surface -- or lies closer to it than
4: //! `Offset Distance` -- is moved to the surface plus that offset along the
5: //! outward direction: fully when below, fading to `Above Surface` of the
6: //! way at the offset distance. The moves are blurred along each strand
7: //! (`Smoothing Steps`) so that a strand bends around the body rather than
8: //! kinking at it, and mixed in by `Factor`. `Lock Roots` keeps roots on the
9: //! scalp. DiffLocks applies it "at various stages in the pipeline"; after
10: //! the noise that pushes strands into the head, and after the drape.
11: 
12: use rayon::prelude::*;
13: use serde::{Deserialize, Serialize};
14: 
15: use crate::collider::push_out;
16: use crate::ops::{Context, restore_lengths};
17: use crate::strands::{Strands, blur};
18: 
19: #[derive(Clone, Debug, Serialize, Deserialize)]
20: pub struct Shrinkwrap {
21:     pub factor: f32,
22:     /// Metres off the surface.
23:     pub offset: f32,
24:     /// How much of the way points at the offset distance still move.
25:     pub above_surface: f32,
26:     pub smoothing: usize,
27:     pub lock_roots: bool,
28:     pub preserve_length: bool,
29: }
30: 
31: impl Default for Shrinkwrap {
32:     fn default() -> Self {
33:         Self {
34:             factor: 1.0,
35:             offset: 0.002,
36:             above_surface: 0.5,
37:             smoothing: 2,
38:             lock_roots: true,
39:             preserve_length: false,
40:         }
41:     }
42: }
43: 
44: impl Shrinkwrap {
45:     pub fn apply(&self, strands: &mut Strands, context: &Context) {
46:         let points = strands.points;
47:         let collider = context.collider;
48:         let offset = self.offset.max(1e-10);
49:         let reference = self.preserve_length.then(|| strands.positions.clone());
50:         strands
51:             .positions
52:             .par_chunks_mut(points)
53:             .enumerate()
54:             .for_each_init(
55:                 || (Vec::new(), Vec::new()),
56:                 |(moves, weights), (s, strand)| {
57:                     moves.clear();
58:                     weights.clear();
59:                     let mut any = false;
60:                     for (j, &p) in strand.iter().enumerate() {
61:                         let locked = j == 0 && self.lock_roots;
62:                         let (distance, out) = collider.query(p);
63:                         let weight = if locked || distance >= offset {
64:                             0.0
65:                         } else if distance < 0.0 {
66:                             1.0
67:                         } else {
68:                             1.0 + (self.above_surface - 1.0) * (distance / offset)
69:                         };
70:                         let target = p + out * (offset - distance);
71:                         moves.push((target - p) * weight);
72:                         weights.push(if locked { 0.0 } else { 1.0 });
73:                         any |= weight > 0.0;
74:                     }
75:                     if !any {
76:                         return;
77:                     }
78:                     if self.smoothing > 0 {
79:                         blur(moves, self.smoothing, weights);
80:                     }
81:                     for (p, m) in strand.iter_mut().zip(moves.iter()) {
82:                         *p += *m * self.factor;
83:                     }
84:                     if let Some(reference) = &reference {
85:                         restore_lengths(strand, &reference[s * points..(s + 1) * points], 1.0);
86:                     }
87:                     // Blurring spreads a deep point's push over its
88:                     // neighbours, and restoring lengths can dip a point back
89:                     // in: whatever is still below the surface goes straight
90:                     // out, unsmoothed.
91:                     if self.factor >= 1.0 {
92:                         for p in strand.iter_mut().skip(1) {
93:                             *p = push_out(collider, *p, self.offset * 0.5);
94:                         }
95:                     }
96:                 },
97:             );
98:     }
99: }
