1: //! Length variation: `Trim Hair Curves`.
2: //!
3: //! A groomed style's strands are not all the length their guides were: a
4: //! haircut layers them, and loose ones are shorter. Each strand keeps the
5: //! first share of its arc length -- `length`, less up to `random` of it at
6: //! random, never more than `max_length` metres -- resampled over its same
7: //! number of points.
8: 
9: use rayon::prelude::*;
10: use serde::{Deserialize, Serialize};
11: 
12: use crate::rng;
13: use crate::strands::{Strands, arc_lengths, resample_into};
14: 
15: #[derive(Clone, Debug, Serialize, Deserialize)]
16: pub struct Trim {
17:     /// Share of each strand's length kept.
18:     pub length: f32,
19:     /// Up to this share of that is taken off at random.
20:     pub random: f32,
21:     /// No strand longer than this, metres (0: no limit).
22:     pub max_length: f32,
23:     pub seed: i32,
24: }
25: 
26: impl Default for Trim {
27:     fn default() -> Self {
28:         Self {
29:             length: 1.0,
30:             random: 0.2,
31:             max_length: 0.0,
32:             seed: 0,
33:         }
34:     }
35: }
36: 
37: impl Trim {
38:     pub fn apply(&self, strands: &mut Strands) {
39:         let seed = rng::seed(self.seed, 77_221);
40:         let points = strands.points;
41:         let ids = &strands.id;
42:         strands
43:             .positions
44:             .par_chunks_mut(points)
45:             .enumerate()
46:             .for_each_init(
47:                 || (Vec::new(), Vec::new(), Vec::new()),
48:                 |(lengths, cut, scratch), (s, strand)| {
49:                     arc_lengths(strand, lengths);
50:                     let total = *lengths.last().unwrap_or(&0.0);
51:                     if total <= 0.0 {
52:                         return;
53:                     }
54:                     let mut keep = total
55:                         * (self.length * (1.0 - self.random * rng::unit((ids[s]).word(), seed)))
56:                             .clamp(0.02, 1.0);
57:                     if self.max_length > 0.0 {
58:                         keep = keep.min(self.max_length);
59:                     }
60:                     if keep >= total * 0.9999 {
61:                         return;
62:                     }
63:                     // The points up to `keep`, the last one cut to length.
64:                     cut.clear();
65:                     for j in 0..points {
66:                         if lengths[j] >= keep {
67:                             let previous = lengths[j - 1];
68:                             let t = (keep - previous) / (lengths[j] - previous).max(1e-12);
69:                             cut.push(strand[j - 1].lerp(strand[j], t));
70:                             break;
71:                         }
72:                         cut.push(strand[j]);
73:                     }
74:                     if cut.len() < 2 {
75:                         return;
76:                     }
77:                     resample_into(cut, scratch, strand);
78:                 },
79:             );
80:     }
81: }

