1: //! The drape: how gravity and wind change a groom.
2: //!
3: //! DiffLocks' last step runs Blender's cloth simulation on the strands, with
4: //! the wind's direction and gravity's strength drawn at random, so that
5: //! samples of one style hang and blow differently. A dynamic simulation run
6: //! for a fixed number of steps is neither settled nor faithful to the
7: //! style; here each strand is solved to static equilibrium as an elastic
8: //! rod, and the drape is what *changes* between conditions.
9: //!
10: //! **The rod.** A strand is a chain of segments whose joints resist
11: //! bending away from the groomed shape. At each joint, the load of all the
12: //! hair beyond it -- gravity plus wind, as an acceleration -- makes a
13: //! moment `M`; the joint bends by `M l / (g L_g^3)` towards the load, where
14: //! `L_g` is the strand's gravity length (the length at which hair bends
15: //! under its own weight: about 5 cm for a single strand, more for a lock).
16: //! No joint bends past the load's direction. Moments come from suffix sums,
17: //! so a sweep is linear in the points; sweeps are repeated, relaxed, with
18: //! the body pushed out after each, until the strand is still.
19: //!
20: //! **The difference.** A groom is the shape hair has under ordinary
21: //! gravity. Solving it under the reference conditions and under the asked
22: //! ones, and adding the difference to the groom, leaves it unchanged at 9.81
23: //! m/s^2 and no wind, lifts it in weaker gravity, and blows it in wind --
24: //! without ever sagging a style into something it was not.
25: 
26: use fabelgeist_math::Vec3;
27: use rayon::prelude::*;
28: use serde::{Deserialize, Serialize};
29: 
30: use crate::collider::{Collider, push_out};
31: use crate::ops::{Context, restore_lengths};
32: use crate::strands::{Strands, rotate, safe_normalize, transport};
33: 
34: /// Standard gravity: the conditions a groom is shaped under.
35: pub const STANDARD_GRAVITY: f32 = 9.81;
36: 
37: #[derive(Clone, Debug, Serialize, Deserialize)]
38: pub struct Settle {
39:     /// Metres per second squared, down.
40:     pub gravity: f32,
41:     /// Acceleration, metres per second squared.
42:     pub wind: [f32; 3],
43:     /// Gravity length `L_g`, metres: how long a strand bears its own
44:     /// weight.
45:     pub stiffness: f32,
46:     /// Sweeps to equilibrium.
47:     pub iterations: usize,
48:     /// Metres kept off the body.
49:     pub collision_offset: f32,
50:     /// Apply the change from standard gravity and no wind (true), or solve
51:     /// the groom as a rest shape under the conditions outright (false).
52:     pub relative: bool,
53: }
54: 
55: impl Default for Settle {
56:     fn default() -> Self {
57:         Self {
58:             gravity: STANDARD_GRAVITY,
59:             wind: [0.0; 3],
60:             stiffness: 0.06,
61:             iterations: 60,
62:             collision_offset: 0.003,
63:             relative: true,
64:         }
65:     }
66: }
67: 
68: impl Settle {
69:     pub fn apply(&self, strands: &mut Strands, context: &Context) {
70:         let points = strands.points;
71:         let collider = context.collider;
72:         let load = Vec3::new(0.0, -self.gravity, 0.0) + Vec3::from_array(self.wind);
73:         let reference = Vec3::new(0.0, -STANDARD_GRAVITY, 0.0);
74:         if self.relative && (load - reference).length() < 1e-4 {
75:             return;
76:         }
77:         strands.positions.par_chunks_mut(points).for_each(|strand| {
78:             let groom = strand.to_vec();
79:             let under = solve(&groom, load, self, collider);
80:             if self.relative {
81:                 let base = solve(&groom, reference, self, collider);
82:                 for ((p, a), b) in strand.iter_mut().zip(&under).zip(&base) {
83:                     *p += *a - *b;
84:                 }
85:                 restore_lengths(strand, &groom, 1.0);
86:                 for p in strand.iter_mut().skip(1) {
87:                     *p = push_out(collider, *p, self.collision_offset * 0.5);
88:                 }
89:             } else {
90:                 strand.copy_from_slice(&under);
91:             }
92:         });
93:     }
94: }
95: 
96: impl Settle {
97:     /// The equilibrium of the strand `rest` under `load` (an acceleration),
98:     /// rooted at its first point and held up by `collider`: how a strand of
99:     /// that shape hangs on that body. Draping one groom on two bodies under
100:     /// the same load, the difference is how the second body moves it.
101:     pub fn equilibrium(&self, rest: &[Vec3], load: Vec3, collider: &dyn Collider) -> Vec<Vec3> {
102:         solve(rest, load, self, collider)
103:     }
104: }
105: 
106: /// The equilibrium of `rest` as an elastic rod under `load` (an
107: /// acceleration), rooted at its first point.
108: fn solve(rest: &[Vec3], load: Vec3, settings: &Settle, collider: &dyn Collider) -> Vec<Vec3> {
109:     let n = rest.len();
110:     let segments = n - 1;
111:     let lengths: Vec<f32> = rest.windows(2).map(|w| (w[1] - w[0]).length()).collect();
112:     let rest_dirs: Vec<Vec3> = rest
113:         .windows(2)
114:         .map(|w| safe_normalize(w[1] - w[0], Vec3::down()))
115:         .collect();
116:     let magnitude = load.length();
117:     if magnitude < 1e-6 {
118:         return rest.to_vec();
119:     }
120:     let force = load * (1.0 / magnitude);
121:     // Joint compliance: bend per unit moment per unit length.
122:     let compliance = 1.0 / (STANDARD_GRAVITY * settings.stiffness.max(1e-3).powi(3));
123: 
124:     let mut dirs = rest_dirs.clone();
125:     let mut points = rest.to_vec();
126:     let mut moment_arm_sum = vec![Vec3::default(); segments + 1];
127:     let mut length_sum = vec![0.0f32; segments + 1];
128:     for _ in 0..settings.iterations {
129:         // Suffix sums of each segment's centre times its length, and of the
130:         // lengths: the moment about point i of the load on everything past
131:         // it is (sum c_j l_j - x_i sum l_j) x load.
132:         moment_arm_sum[segments] = Vec3::default();
133:         length_sum[segments] = 0.0;
134:         for j in (0..segments).rev() {
135:             let centre = (points[j] + points[j + 1]) * 0.5;
136:             moment_arm_sum[j] = moment_arm_sum[j + 1] + centre * lengths[j];
137:             length_sum[j] = length_sum[j + 1] + lengths[j];
138:         }
139:         // Root to tip: each joint bends from its groomed angle -- carried
140:         // along as its parent turned -- towards the load.
141:         let mut position = points[0];
142:         for i in 0..segments {
143:             let groomed = if i == 0 {
144:                 rest_dirs[0]
145:             } else {
146:                 transport(rest_dirs[i], rest_dirs[i - 1], dirs[i - 1])
147:             };
148:             let moment = (moment_arm_sum[i] - points[i] * length_sum[i]).cross(load);
149:             let torque = moment.length();
150:             let mut target = groomed;
151:             if torque > 1e-12 {
152:                 let axis = groomed.cross(force);
153:                 let sin = axis.length();
154:                 if sin > 1e-6 {
155:                     let limit = sin.atan2(groomed.dot(force));
156:                     let bend = (torque * compliance * lengths[i]).min(limit);
157:                     target = rotate(groomed, axis * (1.0 / sin), bend);
158:                 }
159:             }
160:             let d = safe_normalize(dirs[i].lerp(target, 0.5), target);
161:             let mut next = position + d * lengths[i];
162:             // The body holds the hair up.
163:             if collider.distance(next) < settings.collision_offset {
164:                 next = push_out(collider, next, settings.collision_offset);
165:                 next = position + safe_normalize(next - position, d) * lengths[i];
166:             }
167:             dirs[i] = safe_normalize(next - position, d);
168:             points[i + 1] = next;
169:             position = next;
170:         }
171:     }
172:     points
173: }
