1: //! Deterministic randomness.
2: //!
3: //! Blender's hair nodes draw their randomness from `Random Value` nodes keyed
4: //! by an ID (a curve's stable ID, or a point's index) and a seed, so that a
5: //! curve's curl phase or tip spread does not change when other curves are
6: //! added or removed. [`unit`] and friends are that: stateless hashes of an ID
7: //! and a seed. [`Rng`] is a sequential source for the few places that draw in
8: //! order -- placing roots, choosing a dataset sample's parameters.
9: 
10: use fabelgeist_math::Vec3;
11: 
12: /// SplitMix64: tiny, fast, and statistically fine for placing roots.
13: #[derive(Clone, Debug)]
14: pub struct Rng(u64);
15: 
16: impl Rng {
17:     pub fn new(seed: u64) -> Self {
18:         Self(seed ^ 0x9E37_79B9_7F4A_7C15)
19:     }
20: 
21:     pub fn next_u64(&mut self) -> u64 {
22:         self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
23:         let mut z = self.0;
24:         z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
25:         z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
26:         z ^ (z >> 31)
27:     }
28: 
29:     pub fn next_u32(&mut self) -> u32 {
30:         (self.next_u64() >> 32) as u32
31:     }
32: 
33:     /// Uniform in `[0, 1)`.
34:     pub fn next_f32(&mut self) -> f32 {
35:         (self.next_u64() >> 40) as f32 / (1u64 << 24) as f32
36:     }
37: 
38:     /// Uniform in `[low, high)`.
39:     pub fn range(&mut self, low: f32, high: f32) -> f32 {
40:         low + (high - low) * self.next_f32()
41:     }
42: 
43:     /// Uniform in `[low, high)`, but spread evenly on a log scale: for
44:     /// parameters like a curl's frequency, where 5 to 10 is as big a step as
45:     /// 20 to 40.
46:     pub fn log_range(&mut self, low: f32, high: f32) -> f32 {
47:         (low.ln() + (high.ln() - low.ln()) * self.next_f32()).exp()
48:     }
49: 
50:     /// True with probability `p`.
51:     pub fn chance(&mut self, p: f32) -> bool {
52:         self.next_f32() < p
53:     }
54: 
55:     /// An index into `0..n`.
56:     pub fn index(&mut self, n: usize) -> usize {
57:         ((self.next_f32() * n as f32) as usize).min(n.saturating_sub(1))
58:     }
59: 
60:     /// A standard normal draw (Box-Muller).
61:     pub fn gaussian(&mut self) -> f32 {
62:         let u = self.next_f32().max(1e-7);
63:         let v = self.next_f32();
64:         (-2.0 * u.ln()).sqrt() * (std::f32::consts::TAU * v).cos()
65:     }
66: 
67:     /// A fresh generator derived from this one.
68:     pub fn fork(&mut self) -> Self {
69:         Self::new(self.next_u64())
70:     }
71: }
72: 
73: /// Draws in order from one word: each the hash of the key and a counter.
74: /// Where [`Rng`] keeps sixty-four bits of state, this keeps a counter, so a
75: /// GPU thread draws the very same numbers ([`crate::gpu`]): the guides are
76: /// grown with it.
77: #[derive(Clone, Debug)]
78: pub struct Stream {
79:     key: u32,
80:     counter: u32,
81: }
82: 
83: impl Stream {
84:     pub fn new(key: u32) -> Self {
85:         Self { key, counter: 0 }
86:     }
87: 
88:     pub fn next_u32(&mut self) -> u32 {
89:         let value = hash(self.key, self.counter);
90:         self.counter = self.counter.wrapping_add(1);
91:         value
92:     }
93: 
94:     /// Uniform in `[0, 1)`.
95:     pub fn next_f32(&mut self) -> f32 {
96:         (self.next_u32() >> 8) as f32 / (1u32 << 24) as f32
97:     }
98: 
99:     /// A standard normal draw (Box-Muller).
100:     pub fn gaussian(&mut self) -> f32 {
101:         let u = self.next_f32().max(1e-7);
102:         let v = self.next_f32();
103:         (-2.0 * u.ln()).sqrt() * (std::f32::consts::TAU * v).cos()
104:     }
105: }
106: 
107: /// A 32-bit avalanche of two words (the finaliser of MurmurHash3 over a
108: /// combined key).
109: pub fn hash(a: u32, b: u32) -> u32 {
110:     let mut h = a.wrapping_mul(0x9E37_79B1) ^ b.rotate_left(16).wrapping_mul(0x85EB_CA6B);
111:     h ^= h >> 16;
112:     h = h.wrapping_mul(0x85EB_CA6B);
113:     h ^= h >> 13;
114:     h = h.wrapping_mul(0xC2B2_AE35);
115:     h ^ (h >> 16)
116: }
117: 
118: /// Three words into one.
119: pub fn hash3(a: u32, b: u32, c: u32) -> u32 {
120:     hash(hash(a, b), c)
121: }
122: 
123: /// Uniform in `[0, 1)` for an ID under a seed.
124: pub fn unit(id: u32, seed: u32) -> f32 {
125:     (hash(id, seed) >> 8) as f32 / (1u32 << 24) as f32
126: }
127: 
128: /// Uniform in `[-1, 1)` for an ID under a seed.
129: pub fn signed(id: u32, seed: u32) -> f32 {
130:     unit(id, seed) * 2.0 - 1.0
131: }
132: 
133: /// Each component uniform in `[-1, 1)`: Blender's vector `Random Value`
134: /// between -1 and 1.
135: pub fn signed_vec3(id: u32, seed: u32) -> Vec3 {
136:     Vec3::new(
137:         signed(id, hash(seed, 1)),
138:         signed(id, hash(seed, 2)),
139:         signed(id, hash(seed, 3)),
140:     )
141: }
142: 
143: /// A seed from a user-facing integer, as Blender's `Hash Value` node does
144: /// before feeding a seed to `Random Value`.
145: pub fn seed(value: i32, salt: u32) -> u32 {
146:     hash(value as u32, salt)
147: }
148: 
149: #[cfg(test)]
150: mod tests {
151:     use super::*;
152: 
153:     #[test]
154:     fn units_are_uniform_enough() {
155:         let n = 20_000;
156:         let mean: f32 = (0..n).map(|i| unit(i, 7)).sum::<f32>() / n as f32;
157:         assert!((mean - 0.5).abs() < 0.01, "{mean}");
158:         assert!((0..n).all(|i| (0.0..1.0).contains(&unit(i, 3))));
159:     }
160: 
161:     #[test]
162:     fn seeds_decorrelate() {
163:         let same = (0..1000)
164:             .filter(|&i| (unit(i, 1) - unit(i, 2)).abs() < 1e-3)
165:             .count();
166:         assert!(same < 10);
167:     }
168: }
