1: //! Strands: the curves every operation reads and writes.
2: //!
3: //! Blender keeps hair as a `Curves` geometry: points in curve order, with
4: //! attributes on the point and on the curve domain. [`Strands`] is the same
5: //! with one simplification the DiffLocks dataset makes too: every strand has
6: //! the same number of points (256 in the dataset). A fixed count makes every
7: //! operation a loop over equal slices, lets them run a strand per task, and
8: //! is what the GPU wants to draw -- a strand is an instance, a point is a
9: //! vertex pair.
10: //!
11: //! The curve-domain attributes are the ones the hair nodes pass between them:
12: //! where a strand is attached on the scalp ([`Strands::root_uv`], Blender's
13: //! `surface_uv_coordinate`), the scalp's normal there, a stable [`id`] that
14: //! keys each strand's randomness, the parting [`group`] it was interpolated
15: //! in, and its radius at the root.
16: //!
17: //! The functions at the bottom are Blender's curve field inputs for a single
18: //! strand: the spline parameter (arc length), tangents, minimum-twist
19: //! normals, and sampling at a factor or a length.
20: //!
21: //! [`id`]: Strands::id
22: //! [`group`]: Strands::group
23: 
24: use crate::identity::PartingGroup;
25: use crate::identity::StrandId;
26: use fabelgeist_math::Vec3;
27: 
28: /// A set of strands with the same number of points each.
29: #[derive(Clone, Debug, Default)]
30: pub struct Strands {
31:     /// Points per strand, root first. At least two.
32:     pub points: usize,
33:     /// Strand-major: strand `s`'s points are `positions[s * points..][..points]`.
34:     pub positions: Vec<Vec3>,
35:     /// Where each strand is attached, in the scalp's UV map.
36:     pub root_uv: Vec<[f32; 2]>,
37:     /// The scalp's normal at each strand's root.
38:     pub root_normal: Vec<Vec3>,
39:     /// Stable per-strand ID: every random choice about a strand is keyed by
40:     /// it, so a strand keeps its curl phase when others are added.
41:     pub id: Vec<StrandId>,
42:     /// The parting group a strand was interpolated in; `-1` belongs to none.
43:     pub group: Vec<PartingGroup>,
44:     /// Radius at the root, metres. The profile along the strand is the
45:     /// groom's ([`crate::ops::Profile`]).
46:     pub radius: Vec<f32>,
47:     /// Which strand leads each one's clump, once an operation has chosen
48:     /// (Blender's `guide_curve_index`); later operations may reuse it, so
49:     /// that curls follow the clumps.
50:     pub guide_map: Option<crate::ops::GuideMap>,
51: }
52: 
53: impl Strands {
54:     pub fn new(points: usize) -> Self {
55:         assert!(points >= 2, "a strand needs a root and a tip");
56:         Self {
57:             points,
58:             ..Default::default()
59:         }
60:     }
61: 
62:     pub fn with_capacity(points: usize, strands: usize) -> Self {
63:         let mut s = Self::new(points);
64:         s.positions.reserve(points * strands);
65:         s.root_uv.reserve(strands);
66:         s.root_normal.reserve(strands);
67:         s.id.reserve(strands);
68:         s.group.reserve(strands);
69:         s.radius.reserve(strands);
70:         s
71:     }
72: 
73:     /// Number of strands.
74:     pub fn len(&self) -> usize {
75:         self.root_uv.len()
76:     }
77: 
78:     pub fn is_empty(&self) -> bool {
79:         self.len() == 0
80:     }
81: 
82:     pub fn strand(&self, s: usize) -> &[Vec3] {
83:         &self.positions[s * self.points..(s + 1) * self.points]
84:     }
85: 
86:     pub fn strand_mut(&mut self, s: usize) -> &mut [Vec3] {
87:         &mut self.positions[s * self.points..(s + 1) * self.points]
88:     }
89: 
90:     pub fn root(&self, s: usize) -> Vec3 {
91:         self.positions[s * self.points]
92:     }
93: 
94:     /// Append a strand; `positions` must hold [`Strands::points`] points.
95:     pub fn push(&mut self, positions: &[Vec3], attachment: Attachment) {
96:         assert_eq!(positions.len(), self.points);
97:         self.guide_map = None;
98:         self.positions.extend_from_slice(positions);
99:         self.root_uv.push(attachment.uv);
100:         self.root_normal.push(attachment.normal);
101:         self.id.push(attachment.id);
102:         self.group.push(attachment.group);
103:         self.radius.push(attachment.radius);
104:     }
105: 
106:     /// The attributes of strand `s`, without its points.
107:     pub fn attachment(&self, s: usize) -> Attachment {
108:         Attachment {
109:             uv: self.root_uv[s],
110:             normal: self.root_normal[s],
111:             id: self.id[s],
112:             group: self.group[s],
113:             radius: self.radius[s],
114:         }
115:     }
116: 
117:     /// Every strand resampled to `points` points spaced evenly by arc length.
118:     pub fn resampled(&self, points: usize) -> Strands {
119:         if points == self.points {
120:             return self.clone();
121:         }
122:         let mut out = Strands::with_capacity(points, self.len());
123:         let mut buffer = vec![Vec3::default(); points];
124:         let mut lengths = Vec::new();
125:         for s in 0..self.len() {
126:             resample_into(self.strand(s), &mut lengths, &mut buffer);
127:             out.push(&buffer, self.attachment(s));
128:         }
129:         out.guide_map = self.guide_map.clone();
130:         out
131:     }
132: 
133:     /// Only the strands `keep` names, in that order.
134:     pub fn select(&self, keep: &[usize]) -> Strands {
135:         let mut out = Strands::with_capacity(self.points, keep.len());
136:         for &s in keep {
137:             out.push(self.strand(s), self.attachment(s));
138:         }
139:         out
140:     }
141: 
142:     /// Append every strand of `other`, resampling it to this point count.
143:     pub fn extend(&mut self, other: &Strands) {
144:         let other = other.resampled(self.points);
145:         self.guide_map = None;
146:         self.positions.extend_from_slice(&other.positions);
147:         self.root_uv.extend_from_slice(&other.root_uv);
148:         self.root_normal.extend_from_slice(&other.root_normal);
149:         self.id.extend_from_slice(&other.id);
150:         self.group.extend_from_slice(&other.group);
151:         self.radius.extend_from_slice(&other.radius);
152:     }
153: 
154:     /// The box around every point.
155:     pub fn bounds(&self) -> [Vec3; 2] {
156:         let mut lo = Vec3::splat(f32::INFINITY);
157:         let mut hi = Vec3::splat(f32::NEG_INFINITY);
158:         for &p in &self.positions {
159:             lo = lo.min(p);
160:             hi = hi.max(p);
161:         }
162:         [lo, hi]
163:     }
164: 
165:     /// Each strand's length.
166:     pub fn lengths(&self) -> Vec<f32> {
167:         (0..self.len()).map(|s| length(self.strand(s))).collect()
168:     }
169: 
170:     /// Whether any position is not finite.
171:     pub fn has_non_finite(&self) -> bool {
172:         self.positions.iter().any(|p| !p.is_finite())
173:     }
174: }
175: 
176: /// A strand's curve-domain attributes.
177: #[derive(Clone, Copy, Debug, Default)]
178: pub struct Attachment {
179:     pub uv: [f32; 2],
180:     pub normal: Vec3,

181:     pub id: StrandId,
182:     pub group: PartingGroup,
183:     pub radius: f32,
184: }
185: 
186: // ---------------------------------------------------------------------------
187: // One strand's field inputs.
188: 
189: /// Cumulative arc length at each point: zero at the root, the strand's length
190: /// at the tip.
191: pub fn arc_lengths(strand: &[Vec3], out: &mut Vec<f32>) {
192:     out.clear();
193:     out.reserve(strand.len());
194:     let mut total = 0.0;
195:     out.push(0.0);
196:     for pair in strand.windows(2) {
197:         total += (pair[1] - pair[0]).length();
198:         out.push(total);
199:     }
200: }
201: 
202: pub fn length(strand: &[Vec3]) -> f32 {
203:     strand.windows(2).map(|p| (p[1] - p[0]).length()).sum()
204: }
205: 
206: /// Blender's poly-curve tangent: along the first and last segments at the
207: /// ends, and between the neighbours inside.
208: pub fn tangents(strand: &[Vec3], out: &mut Vec<Vec3>) {
209:     out.clear();
210:     let n = strand.len();
211:     for i in 0..n {
212:         let d = if i == 0 {
213:             strand[1] - strand[0]
214:         } else if i == n - 1 {
215:             strand[n - 1] - strand[n - 2]
216:         } else {
217:             (strand[i + 1] - strand[i]).normalize() + (strand[i] - strand[i - 1]).normalize()
218:         };
219:         out.push(safe_normalize(d, Vec3::up()));
220:     }
221: }
222: 
223: /// A vector perpendicular to `v`, as Blender's `math::orthogonal` chooses
224: /// one: crossing with the axis `v` has least of.
225: pub fn orthogonal(v: Vec3) -> Vec3 {
226:     let a = v.abs();
227:     let o = if a.x <= a.y && a.x <= a.z {
228:         Vec3::new(0.0, -v.z, v.y)
229:     } else if a.y <= a.z {
230:         Vec3::new(-v.z, 0.0, v.x)
231:     } else {
232:         Vec3::new(-v.y, v.x, 0.0)
233:     };
234:     safe_normalize(o, Vec3::right())
235: }
236: 
237: /// Minimum-twist normals: the first perpendicular to the first tangent, each
238: /// next one the last carried along by the rotation between their tangents
239: /// (parallel transport).
240: pub fn normals(tangents: &[Vec3], out: &mut Vec<Vec3>) {
241:     out.clear();
242:     let Some(&first) = tangents.first() else {
243:         return;
244:     };
245:     let mut normal = orthogonal(first);
246:     out.push(normal);
247:     for pair in tangents.windows(2) {
248:         normal = transport(normal, pair[0], pair[1]);
249:         out.push(normal);
250:     }
251: }
252: 
253: /// Carry `v` by the smallest rotation taking unit `from` to unit `to`.
254: pub fn transport(v: Vec3, from: Vec3, to: Vec3) -> Vec3 {
255:     let axis = from.cross(to);
256:     let s = axis.length();
257:     let c = from.dot(to);
258:     if s < 1e-7 {
259:         return if c > 0.0 { v } else { -v };
260:     }
261:     rotate(v, axis * (1.0 / s), s.atan2(c))
262: }
263: 
264: /// Rodrigues' rotation of `v` by `angle` about unit `axis`.
265: pub fn rotate(v: Vec3, axis: Vec3, angle: f32) -> Vec3 {
266:     let (sin, cos) = angle.sin_cos();
267:     v * cos + axis.cross(v) * sin + axis * (axis.dot(v) * (1.0 - cos))
268: }
269: 
270: pub fn safe_normalize(v: Vec3, fallback: Vec3) -> Vec3 {
271:     let l = v.length();
272:     if l > 1e-12 && l.is_finite() {
273:         v * (1.0 / l)
274:     } else {
275:         fallback
276:     }
277: }
278: 
279: /// Resample by arc length into `out.len()` evenly spaced points.
280: pub fn resample_into(strand: &[Vec3], lengths: &mut Vec<f32>, out: &mut [Vec3]) {
281:     arc_lengths(strand, lengths);
282:     let total = *lengths.last().unwrap_or(&0.0);
283:     let n = out.len();
284:     let mut segment = 0;
285:     for (i, point) in out.iter_mut().enumerate() {
286:         let target = total * i as f32 / (n - 1).max(1) as f32;
287:         while segment + 2 < lengths.len() && lengths[segment + 1] < target {
288:             segment += 1;
289:         }
290:         let span = lengths[segment + 1] - lengths[segment];
291:         let t = if span > 1e-12 {
292:             ((target - lengths[segment]) / span).clamp(0.0, 1.0)
293:         } else {
294:             0.0
295:         };
296:         *point = strand[segment].lerp(strand[segment + 1], t);
297:     }
298: }
299: 
300: /// A strand's positions, arc lengths, tangents and normals, ready to be
301: /// sampled at any factor or length -- Blender's `Sample Curve`.
302: #[derive(Clone, Debug, Default)]
303: pub struct CurveSampler {
304:     pub positions: Vec<Vec3>,
305:     pub lengths: Vec<f32>,
306:     pub tangents: Vec<Vec3>,
307:     pub normals: Vec<Vec3>,
308: }
309: 
310: /// What [`CurveSampler`] returns.
311: #[derive(Clone, Copy, Debug)]
312: pub struct Sample {
313:     pub position: Vec3,
314:     pub tangent: Vec3,
315:     pub normal: Vec3,
316: }
317: 
318: impl Sample {
319:     /// The third axis of the frame: tangent cross normal.
320:     pub fn binormal(&self) -> Vec3 {
321:         self.tangent.cross(self.normal)
322:     }
323: }
324: 
325: impl CurveSampler {
326:     pub fn new(strand: &[Vec3]) -> Self {
327:         let mut sampler = Self::default();
328:         sampler.set(strand);
329:         sampler
330:     }
331: 
332:     pub fn set(&mut self, strand: &[Vec3]) {
333:         self.positions.clear();
334:         self.positions.extend_from_slice(strand);
335:         arc_lengths(strand, &mut self.lengths);

336:         tangents(strand, &mut self.tangents);
337:         normals(&self.tangents, &mut self.normals);
338:     }
339: 
340:     pub fn length(&self) -> f32 {
341:         *self.lengths.last().unwrap_or(&0.0)
342:     }
343: 
344:     /// At `factor` of the arc length, clamped to the strand.
345:     pub fn at_factor(&self, factor: f32) -> Sample {
346:         self.at_length(factor * self.length())
347:     }
348: 
349:     /// At arc length `s` from the root, clamped to the strand.
350:     pub fn at_length(&self, s: f32) -> Sample {
351:         let n = self.positions.len();
352:         let s = s.clamp(0.0, self.length());
353:         // The segment holding `s`: the last point at or before it.
354:         let upper = self.lengths.partition_point(|&l| l <= s).clamp(1, n - 1);
355:         let i = upper - 1;
356:         let span = self.lengths[upper] - self.lengths[i];
357:         let t = if span > 1e-12 {
358:             ((s - self.lengths[i]) / span).clamp(0.0, 1.0)
359:         } else {
360:             0.0
361:         };
362:         let tangent = safe_normalize(
363:             self.tangents[i].lerp(self.tangents[upper], t),
364:             self.tangents[i],
365:         );
366:         let normal = self.normals[i].lerp(self.normals[upper], t);
367:         // Keep the frame orthonormal after interpolation.
368:         let normal = safe_normalize(normal - tangent * normal.dot(tangent), self.normals[i]);
369:         Sample {
370:             position: self.positions[i].lerp(self.positions[upper], t),
371:             tangent,
372:             normal,
373:         }
374:     }
375: }
376: 
377: /// Blur a per-point value along a strand: `iterations` passes of averaging
378: /// each interior point with its neighbours, weighted by `weight` (Blender's
379: /// `Blur Attribute` on the point domain of a curve). The root and tip keep
380: /// their values.
381: pub fn blur(values: &mut [Vec3], iterations: usize, weight: &[f32]) {
382:     let n = values.len();
383:     if n < 3 {
384:         return;
385:     }
386:     let mut next = values.to_vec();
387:     for _ in 0..iterations {
388:         for i in 1..n - 1 {
389:             let w = weight.get(i).copied().unwrap_or(1.0).clamp(0.0, 1.0);
390:             let average = (values[i - 1] + values[i] + values[i + 1]) * (1.0 / 3.0);
391:             next[i] = values[i].lerp(average, w);
392:         }
393:         values[1..n - 1].copy_from_slice(&next[1..n - 1]);
394:     }
395: }
