1: //! Builds a momentum character (skeleton, mesh, skin weights, blend shapes)
2: //! out of an MHR `lod*.fbx` rig.
3: //!
4: //! The traversal order mirrors `momentum::loadOpenFbxCharacter`, because the
5: //! joint indices it produces are what the `.model` parameter transform, the
6: //! skin clusters, and the pose-corrective network are all indexed by.
7: 
8: use std::collections::HashMap;
9: 
10: use anyhow::{Context, Result, bail};
11: 
12: use crate::math::{Mat4, Transform};
13: use fabelgeist_fbx::{FbxObjectName, Object, Scene};
14: use fabelgeist_rig::{RigJointOrdinal, RigJointTable};
15: pub use skeleton::Skeleton;
16: use skeleton::{ParsedSkeleton, parse_skeleton};
17: pub use skin::SkinWeights;
18: use skin::parse_skin;
19: 
20: mod skeleton;
21: mod skin;
22: 
23: /// Momentum allows at most eight joint influences per vertex.
24: pub const MAX_SKIN_JOINTS: usize = 8;
25: 
26: /// `tx, ty, tz, rx, ry, rz, sc`.
27: pub const PARAMETERS_PER_JOINT: usize = 7;
28: 
29: /// Triangulated mesh with the original polygon topology dropped.
30: #[derive(Debug, Default, Clone)]
31: pub struct Mesh {
32:     pub vertices: Vec<[f32; 3]>,
33:     pub faces: Vec<[u32; 3]>,
34:     pub texcoords: Vec<[f32; 2]>,
35:     pub texcoord_faces: Vec<[u32; 3]>,
36: }
37: 
38: /// Dense blend-shape basis, `shape-major`: `vectors[shape * n_verts * 3 + ..]`.
39: #[derive(Debug, Default, Clone)]
40: pub struct BlendShapes {
41:     pub names: Vec<FbxObjectName>,
42:     pub vectors: Vec<f32>,
43:     pub num_vertices: usize,
44: }
45: 
46: /// Everything the MHR forward pass needs from the rig file.
47: pub struct Character {
48:     pub skeleton: Skeleton,
49:     pub mesh: Mesh,
50:     pub skin_weights: SkinWeights,
51:     /// Inverse bind pose per joint as a skeleton state `[t, q, s]`.
52:     pub inverse_bind_pose: RigJointTable<[f32; 8]>,
53:     pub blend_shapes: BlendShapes,
54: }
55: 
56: impl BlendShapes {
57:     pub fn len(&self) -> usize {
58:         self.names.len()
59:     }
60: 
61:     pub fn is_empty(&self) -> bool {
62:         self.names.is_empty()
63:     }
64: }
65: 
66: impl Character {
67:     /// Loads a character from the bytes of a binary FBX rig.
68:     pub fn from_fbx_bytes(data: &[u8], load_blend_shapes: bool) -> Result<Self> {
69:         let scene = Scene::parse(data)?;
70:         let ParsedSkeleton {
71:             skeleton,
72:             joint_ids,
73:         } = parse_skeleton(&scene);
74:         if skeleton.is_empty() {
75:             bail!("no joints found in FBX rig");
76:         }
77: 
78:         let joint_of_object: HashMap<i64, RigJointOrdinal> = joint_ids
79:             .indexed()
80:             .map(|(joint, id)| (*id, joint))
81:             .collect();
82: 
83:         // Default to each joint's bind-pose global transform; clusters override
84:         // the joints they actually bind, which for MHR is all of them.
85:         let bind_pose = skeleton.bind_pose();
86:         let mut inverse_bind_pose: RigJointTable<Mat4> = bind_pose
87:             .iter()
88:             .map(|transform| {
89:                 let inverse = transform.inverse();
90:                 let rotation = crate::math::quat_to_matrix(inverse.rotation);
91:                 let mut m = [[0.0; 4]; 4];
92:                 for row in 0..3 {
93:                     for col in 0..3 {
94:                         m[row][col] = rotation[row][col] * inverse.scale;
95:                     }
96:                     m[row][3] = inverse.translation[row];
97:                 }
98:                 m[3][3] = 1.0;
99:                 m
100:             })
101:             .collect();
102: 
103:         let mesh_model = scene
104:             .objects_of_kind("Model", "Mesh")
105:             .next()
106:             .context("FBX rig has no mesh")?;
107:         let geometry = scene
108:             .child_of_kind(mesh_model.id, "Geometry", "Mesh")
109:             .context("mesh model has no geometry")?;
110: 
111:         let vertex_values = geometry
112:             .node
113:             .child("Vertices")
114:             .and_then(|n| n.f64_array())
115:             .context("mesh geometry has no vertices")?;
116:         let (vertex_triples, remainder) = vertex_values.as_chunks::<3>();
117:         if !remainder.is_empty() {
118:             bail!("FBX vertex array contains an incomplete three-axis position");
119:         }
120:         let vertices: Vec<[f32; 3]> = vertex_triples
121:             .iter()
122:             .map(|v| [v[0] as f32, v[1] as f32, v[2] as f32])
123:             .collect();
124:         let polygon_vertex_index = geometry
125:             .node
126:             .child("PolygonVertexIndex")
127:             .and_then(|n| n.i64_array())
128:             .context("mesh geometry has no polygons")?;
129: 
130:         let faces = triangulate(&polygon_vertex_index)?;
131:         let (texcoords, texcoord_indices) = parse_uvs(geometry, polygon_vertex_index.len())?;
132:         let texcoord_faces = triangulate_texcoords(&polygon_vertex_index, &texcoord_indices);
133: 
134:         let blend_shapes = if load_blend_shapes {
135:             parse_blend_shapes(&scene, geometry, vertices.len())
136:         } else {
137:             BlendShapes::default()
138:         };
139: 
140:         let skin_weights = parse_skin(
141:             &scene,
142:             geometry,
143:             &joint_of_object,
144:             vertices.len(),
145:             &mut inverse_bind_pose,
146:         )?;
147: 
148:         Ok(Self {
149:             skeleton,
150:             mesh: Mesh {
151:                 vertices,
152:                 faces,
153:                 texcoords,
154:                 texcoord_faces,
155:             },
156:             skin_weights,
157:             inverse_bind_pose: inverse_bind_pose
158:                 .iter()
159:                 .map(|m| Transform::from_matrix(m).to_skel_state())
160:                 .collect(),
161:             blend_shapes,
162:         })
163:     }
164: }
165: 
166: /// Splits an FBX `PolygonVertexIndex` stream (negative index ends a polygon)
167: /// into fan-triangulated triangles.
168: fn triangulate(polygon_vertex_index: &[i64]) -> Result<Vec<[u32; 3]>> {
169:     let mut faces = Vec::new();
170:     let mut polygon: Vec<u32> = Vec::with_capacity(4);
171:     for raw in polygon_vertex_index {
172:         let (index, last) = if *raw < 0 {
173:             ((-(*raw + 1)) as u32, true)
174:         } else {
175:             (*raw as u32, false)

176:         };
177:         polygon.push(index);
178:         if !last {
179:             continue;
180:         }
181:         if polygon.len() < 3 {
182:             bail!(
183:                 "invalid face with {} indices; expected at least 3",
184:                 polygon.len()
185:             );
186:         }
187:         for j in 1..polygon.len() - 1 {
188:             faces.push([polygon[0], polygon[j], polygon[j + 1]]);
189:         }
190:         polygon.clear();
191:     }
192:     if !polygon.is_empty() {
193:         bail!("trailing polygon indices without a terminator");
194:     }
195:     Ok(faces)
196: }
197: 
198: fn parse_uvs(geometry: &Object, polygon_count: usize) -> Result<(Vec<[f32; 2]>, Vec<i64>)> {
199:     let Some(layer) = geometry.node.child("LayerElementUV") else {
200:         return Ok((Vec::new(), Vec::new()));
201:     };
202:     let Some(values) = layer.child("UV").and_then(|n| n.f64_array()) else {
203:         return Ok((Vec::new(), Vec::new()));
204:     };
205:     let (uv_pairs, remainder) = values.as_chunks::<2>();
206:     if !remainder.is_empty() {
207:         bail!("FBX UV array contains an incomplete coordinate pair");
208:     }
209:     // FBX texture coordinates are bottom-up.
210:     let texcoords: Vec<[f32; 2]> = uv_pairs
211:         .iter()
212:         .map(|uv| [uv[0] as f32, 1.0 - uv[1] as f32])
213:         .collect();
214: 
215:     let reference = layer
216:         .child("ReferenceInformationType")
217:         .and_then(|n| n.str_prop(0))
218:         .map(|v| v.to_vec())
219:         .unwrap_or_default();
220:     let indices = if reference == b"IndexToDirect" {
221:         layer
222:             .child("UVIndex")
223:             .and_then(|n| n.i64_array())
224:             .unwrap_or_default()
225:     } else {
226:         (0..polygon_count as i64).collect()
227:     };
228:     Ok((texcoords, indices))
229: }
230: 
231: /// Re-splits UV indices onto the polygon boundaries of the vertex index stream.
232: fn triangulate_texcoords(polygon_vertex_index: &[i64], texcoord_indices: &[i64]) -> Vec<[u32; 3]> {
233:     if texcoord_indices.len() != polygon_vertex_index.len() {
234:         return Vec::new();
235:     }
236:     let mut faces = Vec::new();
237:     let mut polygon: Vec<u32> = Vec::with_capacity(4);
238:     for (raw, tex) in polygon_vertex_index.iter().zip(texcoord_indices) {
239:         polygon.push(*tex as u32);
240:         if *raw >= 0 {
241:             continue;
242:         }
243:         for j in 1..polygon.len().saturating_sub(1) {
244:             faces.push([polygon[0], polygon[j], polygon[j + 1]]);
245:         }
246:         polygon.clear();
247:     }
248:     faces
249: }
250: 
251: fn parse_blend_shapes(scene: &Scene, geometry: &Object, num_vertices: usize) -> BlendShapes {
252:     let mut names = Vec::new();
253:     let mut vectors: Vec<f32> = Vec::new();
254: 
255:     let Some(blend_shape) = scene
256:         .children(geometry.id)
257:         .find(|o| o.kind == "Deformer" && o.class == "BlendShape")
258:     else {
259:         return BlendShapes::default();
260:     };
261: 
262:     for channel in scene
263:         .children(blend_shape.id)
264:         .filter(|o| o.kind == "Deformer" && o.class == "BlendShapeChannel")
265:         .collect::<Vec<_>>()
266:     {
267:         for shape in scene
268:             .children(channel.id)
269:             .filter(|o| o.kind == "Geometry" && o.class == "Shape")
270:             .collect::<Vec<_>>()
271:         {
272:             let offsets = shape.node.child("Vertices").and_then(|n| n.f64_array());
273:             let indices = shape.node.child("Indexes").and_then(|n| n.i64_array());
274:             let base = vectors.len();
275:             vectors.resize(base + num_vertices * 3, 0.0);
276:             if let (Some(offsets), Some(indices)) = (offsets, indices) {
277:                 for (slot, vertex) in indices.iter().enumerate() {
278:                     let vertex = *vertex as usize;
279:                     if vertex >= num_vertices || slot * 3 + 2 >= offsets.len() {
280:                         continue;
281:                     }
282:                     for axis in 0..3 {
283:                         vectors[base + vertex * 3 + axis] = offsets[slot * 3 + axis] as f32;
284:                     }
285:                 }
286:             }
287:             names.push(shape.name.clone());
288:         }
289:     }
290: 
291:     BlendShapes {
292:         names,
293:         vectors,
294:         num_vertices,
295:     }
296: }
297: 
298: #[cfg(test)]
299: mod tests {
300:     use super::*;
301: 
302:     #[test]
303:     fn triangulates_polygon_fans() {
304:         // Two polygons: a quad and a triangle, FBX-style negative terminators.
305:         let stream = [0, 1, 2, -4, 4, 5, -7];
306:         let faces = triangulate(&stream).unwrap();
307:         assert_eq!(faces, vec![[0, 1, 2], [0, 2, 3], [4, 5, 6]]);
308:     }
309: 
310:     #[test]
311:     fn rejects_degenerate_polygons() {
312:         assert!(triangulate(&[0, -2]).is_err());
313:         assert!(triangulate(&[0, 1, 2]).is_err());
314:     }
315: }

