1: //! The authored FBX traversal establishes every ordered joint column together.
2: 
3: use crate::math::{Quat, Transform, quat_from_euler_degrees, quat_mul, rotation_order};
4: use fabelgeist_fbx::{Object, Scene};
5: use fabelgeist_rig::{RigJointName, RigJointOrdinal, RigJointTable};
6: 
7: /// The joint hierarchy, in momentum order (parents always precede children).
8: #[derive(Debug, Default, Clone)]
9: pub struct Skeleton {
10:     pub names: RigJointTable<RigJointName>,
11:     /// Roots have no parent; every child follows an earlier admitted joint.
12:     pub parents: RigJointTable<Option<RigJointOrdinal>>,
13:     pub translation_offsets: RigJointTable<[f32; 3]>,
14:     /// Rest rotation baked into the joint, `[x, y, z, w]`.
15:     pub prerotations: RigJointTable<[f32; 4]>,
16: }
17: 
18: struct SkeletonBuilder<'a> {
19:     scene: &'a Scene,
20:     skeleton: Skeleton,
21:     /// FBX object id per joint index, used to resolve skin clusters back to joints.
22:     joint_ids: RigJointTable<i64>,
23: }
24: 
25: pub(super) struct ParsedSkeleton {
26:     pub(super) skeleton: Skeleton,
27:     pub(super) joint_ids: RigJointTable<i64>,
28: }
29: 
30: impl Skeleton {
31:     pub fn len(&self) -> usize {
32:         self.names.len()
33:     }
34: 
35:     pub fn is_empty(&self) -> bool {
36:         self.names.is_empty()
37:     }
38: 
39:     pub fn joint_index(&self, name: &RigJointName) -> Option<RigJointOrdinal> {
40:         name.index_in(&self.names)
41:     }
42: 
43:     /// Bind-pose global transform per joint (all joint parameters zero).
44:     pub fn bind_pose(&self) -> RigJointTable<Transform> {
45:         let mut global: RigJointTable<Transform> = RigJointTable::default();
46:         for joint in self.names.ordinals() {
47:             let offset = self.translation_offsets[joint];
48:             let prerotation = self.prerotations[joint];
49:             let local = Transform {
50:                 translation: [offset[0] as f64, offset[1] as f64, offset[2] as f64],
51:                 rotation: [
52:                     prerotation[0] as f64,
53:                     prerotation[1] as f64,
54:                     prerotation[2] as f64,
55:                     prerotation[3] as f64,
56:                 ],
57:                 scale: 1.0,
58:             };
59:             let parent = self.parents[joint];
60:             global.push(match parent {
61:                 None => local,
62:                 Some(parent) => global[parent].compose(&local),
63:             });
64:         }
65:         global
66:     }
67: }
68: 
69: impl<'a> SkeletonBuilder<'a> {
70:     fn visit(&mut self, object: &Object, parent: Option<RigJointOrdinal>) {
71:         if !object.is_node() {
72:             return;
73:         }
74: 
75:         if object.is_null_node() {
76:             // Nulls are collision primitives or locators; neither is a joint.
77:             // A null at the top of the file is just a grouping node, so keep descending.
78:             if parent.is_none() && object.node.property70("col_type").is_none() {
79:                 for child in self.scene.children(object.id).collect::<Vec<_>>() {
80:                     self.visit(child, None);
81:                 }
82:             }
83:             return;
84:         }
85: 
86:         if !object.is_limb() {
87:             return;
88:         }
89: 
90:         let order = rotation_order(object.node.property70_i64("RotationOrder", 0));
91:         let local_rotation =
92:             quat_from_euler_degrees(object.node.property70_vec3("Lcl Rotation", [0.0; 3]), order);
93:         let pre_rotation = quat_from_euler_degrees(
94:             object.node.property70_vec3("PreRotation", [0.0; 3]),
95:             [0, 1, 2],
96:         );
97:         // momentum bakes any rest rotation into the joint's pre-rotation.
98:         let prerotation: Quat = quat_mul(pre_rotation, local_rotation);
99:         let offset = object.node.property70_vec3("Lcl Translation", [0.0; 3]);
100: 
101:         let index = RigJointOrdinal::from(self.skeleton.len());
102:         self.skeleton.names.push(RigJointName::from(&object.name));
103:         self.skeleton.parents.push(parent);
104:         self.skeleton.translation_offsets.push([
105:             offset[0] as f32,
106:             offset[1] as f32,
107:             offset[2] as f32,
108:         ]);
109:         self.skeleton.prerotations.push([
110:             prerotation[0] as f32,
111:             prerotation[1] as f32,
112:             prerotation[2] as f32,
113:             prerotation[3] as f32,
114:         ]);
115:         self.joint_ids.push(object.id);
116: 
117:         for child in self.scene.children(object.id).collect::<Vec<_>>() {
118:             self.visit(child, Some(index));
119:         }
120:     }
121: }
122: 
123: pub(super) fn parse_skeleton(scene: &Scene) -> ParsedSkeleton {
124:     let mut builder = SkeletonBuilder {
125:         scene,
126:         skeleton: Skeleton::default(),
127:         joint_ids: RigJointTable::default(),
128:     };
129:     for root in scene.children(0).collect::<Vec<_>>() {
130:         builder.visit(root, None);
131:     }
132:     ParsedSkeleton {
133:         skeleton: builder.skeleton,
134:         joint_ids: builder.joint_ids,
135:     }
136: }
