1: //! Resolve FBX cluster identities into the admitted rig's packed influences.
2: 
3: use super::MAX_SKIN_JOINTS;
4: use crate::math::{Mat4, affine_inverse, mat4_from_column_major};
5: use anyhow::{Result, bail};
6: use fabelgeist_fbx::{Object, Scene};
7: use fabelgeist_rig::{PackedRigSkin, RigJointOrdinal, RigJointTable};
8: use std::collections::HashMap;
9: 
10: /// Fixed-width sparse skinning, eight influences per vertex.
11: #[derive(Debug, Default, Clone)]
12: pub struct SkinWeights {
13:     pub index: PackedRigSkin<MAX_SKIN_JOINTS>,
14:     pub weight: Vec<[f32; MAX_SKIN_JOINTS]>,
15: }
16: 
17: #[derive(Clone, Copy)]
18: struct SkinInfluence {
19:     joint: RigJointOrdinal,
20:     weight: f64,
21: }
22: 
23: pub(super) fn parse_skin(
24:     scene: &Scene,
25:     geometry: &Object,
26:     joint_of_object: &HashMap<i64, RigJointOrdinal>,
27:     num_vertices: usize,
28:     inverse_bind_pose: &mut RigJointTable<Mat4>,
29: ) -> Result<SkinWeights> {
30:     let mut per_vertex: Vec<Vec<SkinInfluence>> = vec![Vec::new(); num_vertices];
31: 
32:     let Some(skin) = scene
33:         .children(geometry.id)
34:         .find(|o| o.kind == "Deformer" && o.class == "Skin")
35:     else {
36:         bail!("geometry '{}' has no skin deformer", geometry.name);
37:     };
38: 
39:     for cluster in scene
40:         .children(skin.id)
41:         .filter(|o| o.kind == "Deformer" && o.class == "Cluster")
42:         .collect::<Vec<_>>()
43:     {
44:         let Some(bone) = scene
45:             .children(cluster.id)
46:             .find(|o| joint_of_object.contains_key(&o.id))
47:         else {
48:             bail!("cluster '{}' references an unknown bone", cluster.name);
49:         };
50:         let joint = joint_of_object[&bone.id];
51: 
52:         // The cluster's bind transform overrides the joint's own rest pose.
53:         if let Some(link) = cluster
54:             .node
55:             .child("TransformLink")
56:             .and_then(|n| n.f64_array())
57:             && link.len() == 16
58:         {
59:             inverse_bind_pose[joint] = affine_inverse(&mat4_from_column_major(&link));
60:         }
61: 
62:         let (Some(indices), Some(weights)) = (
63:             cluster.node.child("Indexes").and_then(|n| n.i64_array()),
64:             cluster.node.child("Weights").and_then(|n| n.f64_array()),
65:         ) else {
66:             continue;
67:         };
68:         if indices.len() != weights.len() {
69:             bail!(
70:                 "cluster '{}' has mismatched indices and weights",
71:                 cluster.name
72:             );
73:         }
74: 
75:         for (vertex, weight) in indices.iter().zip(&weights) {
76:             let vertex = *vertex as usize;
77:             if vertex >= num_vertices {
78:                 bail!("cluster '{}' references vertex {vertex}", cluster.name);
79:             }
80:             if *weight <= 0.0 {
81:                 continue;
82:             }
83:             per_vertex[vertex].push(SkinInfluence {
84:                 joint,
85:                 weight: weight.clamp(0.0, 1.0),
86:             });
87:         }
88:     }
89: 
90:     let mut indices = vec![[0; MAX_SKIN_JOINTS]; num_vertices];
91:     let mut weights = vec![[0.0; MAX_SKIN_JOINTS]; num_vertices];
92:     for (vertex, influences) in per_vertex.iter_mut().enumerate() {
93:         if influences.is_empty() {
94:             bail!("no skinning weights for vertex {vertex}");
95:         }
96:         // Keep the strongest influences, then renormalize what survived.
97:         influences.sort_by(|a, b| b.weight.total_cmp(&a.weight));
98:         influences.truncate(MAX_SKIN_JOINTS);
99:         let total: f64 = influences.iter().map(|influence| influence.weight).sum();
100:         if total <= 0.0 {
101:             bail!("empty weight sum for vertex {vertex}");
102:         }
103:         for (slot, influence) in influences.iter().enumerate() {
104:             indices[vertex][slot] = u32::try_from(influence.joint)?;
105:             weights[vertex][slot] = (influence.weight / total) as f32;
106:         }
107:     }
108: 
109:     Ok(SkinWeights {
110:         index: PackedRigSkin::from_native(indices, inverse_bind_pose.joint_count())?,
111:         weight: weights,
112:     })
113: }

