1: //! Small `f64` rotation/transform helpers used while building a character.
2: //!
3: //! Quaternions are stored `[x, y, z, w]`, matching momentum's skeleton state
4: //! layout `[tx, ty, tz, qx, qy, qz, qw, s]`.
5: 
6: pub type Quat = [f64; 4];
7: pub type Vec3 = [f64; 3];
8: /// Row-major 4x4 matrix.
9: pub type Mat4 = [[f64; 4]; 4];
10: 
11: pub const IDENTITY: Quat = [0.0, 0.0, 0.0, 1.0];
12: 
13: /// Hamilton product `a * b`.
14: pub fn quat_mul(a: Quat, b: Quat) -> Quat {
15:     let [x1, y1, z1, w1] = a;
16:     let [x2, y2, z2, w2] = b;
17:     [
18:         w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2,
19:         w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2,
20:         w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2,
21:         w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2,
22:     ]
23: }
24: 
25: pub fn quat_normalize(q: Quat) -> Quat {
26:     let n = (q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3]).sqrt();
27:     if n < 1e-12 {
28:         IDENTITY
29:     } else {
30:         q.map(|v| v / n)
31:     }
32: }
33: 
34: /// Rotation about a coordinate axis (0 = x, 1 = y, 2 = z).
35: fn quat_axis(axis: usize, angle: f64) -> Quat {
36:     let (s, c) = (angle * 0.5).sin_cos();
37:     let mut q = [0.0, 0.0, 0.0, c];
38:     q[axis] = s;
39:     q
40: }
41: 
42: /// Euler angles (radians) composed in the given order, momentum-style: the
43: /// axis listed first is applied first, so XYZ yields `Rz * Ry * Rx`.
44: pub fn quat_from_euler(angles: Vec3, order: [usize; 3]) -> Quat {
45:     let mut result = IDENTITY;
46:     for axis in order {
47:         result = quat_mul(quat_axis(axis, angles[axis]), result);
48:     }
49:     result
50: }
51: 
52: /// FBX stores Euler angles in degrees.
53: pub fn quat_from_euler_degrees(angles: Vec3, order: [usize; 3]) -> Quat {
54:     let radians = angles.map(f64::to_radians);
55:     quat_from_euler(radians, order)
56: }
57: 
58: /// FBX `RotationOrder` enum -> the axis order used by [`quat_from_euler`].
59: pub fn rotation_order(order: i64) -> [usize; 3] {
60:     match order {
61:         1 => [0, 2, 1], // XZY
62:         2 => [1, 2, 0], // YZX
63:         3 => [1, 0, 2], // YXZ
64:         4 => [2, 0, 1], // ZXY
65:         5 => [2, 1, 0], // ZYX
66:         _ => [0, 1, 2], // XYZ (and spherical, which MHR does not use)
67:     }
68: }
69: 
70: /// Shepperd's method, matching `Eigen::Quaternion(Matrix3)`.
71: pub fn quat_from_matrix(m: [[f64; 3]; 3]) -> Quat {
72:     let trace = m[0][0] + m[1][1] + m[2][2];
73:     if trace > 0.0 {
74:         let s = (trace + 1.0).sqrt() * 2.0;
75:         [
76:             (m[2][1] - m[1][2]) / s,
77:             (m[0][2] - m[2][0]) / s,
78:             (m[1][0] - m[0][1]) / s,
79:             0.25 * s,
80:         ]
81:     } else if m[0][0] > m[1][1] && m[0][0] > m[2][2] {
82:         let s = (1.0 + m[0][0] - m[1][1] - m[2][2]).sqrt() * 2.0;
83:         [
84:             0.25 * s,
85:             (m[0][1] + m[1][0]) / s,
86:             (m[0][2] + m[2][0]) / s,
87:             (m[2][1] - m[1][2]) / s,
88:         ]
89:     } else if m[1][1] > m[2][2] {
90:         let s = (1.0 + m[1][1] - m[0][0] - m[2][2]).sqrt() * 2.0;
91:         [
92:             (m[0][1] + m[1][0]) / s,
93:             0.25 * s,
94:             (m[1][2] + m[2][1]) / s,
95:             (m[0][2] - m[2][0]) / s,
96:         ]
97:     } else {
98:         let s = (1.0 + m[2][2] - m[0][0] - m[1][1]).sqrt() * 2.0;
99:         [
100:             (m[0][2] + m[2][0]) / s,
101:             (m[1][2] + m[2][1]) / s,
102:             0.25 * s,
103:             (m[1][0] - m[0][1]) / s,
104:         ]
105:     }
106: }
107: 
108: pub fn quat_to_matrix(q: Quat) -> [[f64; 3]; 3] {
109:     let [x, y, z, w] = quat_normalize(q);
110:     [
111:         [
112:             1.0 - 2.0 * (y * y + z * z),
113:             2.0 * (x * y - z * w),
114:             2.0 * (x * z + y * w),
115:         ],
116:         [
117:             2.0 * (x * y + z * w),
118:             1.0 - 2.0 * (x * x + z * z),
119:             2.0 * (y * z - x * w),
120:         ],
121:         [
122:             2.0 * (x * z - y * w),
123:             2.0 * (y * z + x * w),
124:             1.0 - 2.0 * (x * x + y * y),
125:         ],
126:     ]
127: }
128: 
129: pub fn rotate_vector(q: Quat, v: Vec3) -> Vec3 {
130:     let m = quat_to_matrix(q);
131:     [
132:         m[0][0] * v[0] + m[0][1] * v[1] + m[0][2] * v[2],
133:         m[1][0] * v[0] + m[1][1] * v[1] + m[1][2] * v[2],
134:         m[2][0] * v[0] + m[2][1] * v[1] + m[2][2] * v[2],
135:     ]
136: }
137: 
138: /// A rigid-plus-uniform-scale transform, i.e. one momentum skeleton state.
139: #[derive(Debug, Clone, Copy)]
140: pub struct Transform {
141:     pub translation: Vec3,
142:     pub rotation: Quat,
143:     pub scale: f64,
144: }
145: 
146: impl Default for Transform {
147:     fn default() -> Self {
148:         Self::IDENTITY
149:     }
150: }
151: 
152: impl Transform {
153:     pub const IDENTITY: Self = Self {
154:         translation: [0.0; 3],
155:         rotation: IDENTITY,
156:         scale: 1.0,
157:     };
158: 
159:     /// `self * other`, the momentum skeleton-state product.
160:     pub fn compose(&self, other: &Self) -> Self {
161:         let rotated = rotate_vector(self.rotation, other.translation);
162:         Self {
163:             translation: [
164:                 self.translation[0] + self.scale * rotated[0],
165:                 self.translation[1] + self.scale * rotated[1],
166:                 self.translation[2] + self.scale * rotated[2],
167:             ],
168:             rotation: quat_mul(self.rotation, other.rotation),
169:             scale: self.scale * other.scale,
170:         }
171:     }
172: 
173:     pub fn inverse(&self) -> Self {
174:         let inv_rotation = [
175:             -self.rotation[0],
176:             -self.rotation[1],
177:             -self.rotation[2],
178:             self.rotation[3],
179:         ];
180:         let inv_scale = 1.0 / self.scale;
181:         let rotated = rotate_vector(inv_rotation, self.translation);
182:         Self {
183:             translation: rotated.map(|v| -inv_scale * v),
184:             rotation: inv_rotation,
185:             scale: inv_scale,
186:         }
187:     }
188: 
189:     /// Decomposes an affine matrix, assuming uniform scale and no shear.
190:     ///

191:     /// This is momentum's `Transform::fromMatrix`: the scale is the norm of the
192:     /// first linear column, and the rotation is what remains after dividing it out.
193:     pub fn from_matrix(m: &Mat4) -> Self {
194:         let scale = (m[0][0] * m[0][0] + m[1][0] * m[1][0] + m[2][0] * m[2][0]).sqrt();
195:         let inv = if scale > 1e-12 { 1.0 / scale } else { 1.0 };
196:         let linear = [
197:             [m[0][0] * inv, m[0][1] * inv, m[0][2] * inv],
198:             [m[1][0] * inv, m[1][1] * inv, m[1][2] * inv],
199:             [m[2][0] * inv, m[2][1] * inv, m[2][2] * inv],
200:         ];
201:         Self {
202:             translation: [m[0][3], m[1][3], m[2][3]],
203:             rotation: quat_normalize(quat_from_matrix(linear)),
204:             scale,
205:         }
206:     }
207: 
208:     /// `[tx, ty, tz, qx, qy, qz, qw, s]`, the momentum skeleton-state layout.
209:     pub fn to_skel_state(self) -> [f32; 8] {
210:         let q = quat_normalize(self.rotation);
211:         [
212:             self.translation[0] as f32,
213:             self.translation[1] as f32,
214:             self.translation[2] as f32,
215:             q[0] as f32,
216:             q[1] as f32,
217:             q[2] as f32,
218:             q[3] as f32,
219:             self.scale as f32,
220:         ]
221:     }
222: }
223: 
224: /// Inverts a general affine 4x4 matrix (the bottom row must be `[0, 0, 0, 1]`).
225: pub fn affine_inverse(m: &Mat4) -> Mat4 {
226:     let a = [
227:         [m[0][0], m[0][1], m[0][2]],
228:         [m[1][0], m[1][1], m[1][2]],
229:         [m[2][0], m[2][1], m[2][2]],
230:     ];
231:     let det = a[0][0] * (a[1][1] * a[2][2] - a[1][2] * a[2][1])
232:         - a[0][1] * (a[1][0] * a[2][2] - a[1][2] * a[2][0])
233:         + a[0][2] * (a[1][0] * a[2][1] - a[1][1] * a[2][0]);
234:     let inv_det = if det.abs() > 1e-20 { 1.0 / det } else { 0.0 };
235: 
236:     let mut inv = [[0.0; 4]; 4];
237:     inv[0][0] = (a[1][1] * a[2][2] - a[1][2] * a[2][1]) * inv_det;
238:     inv[0][1] = (a[0][2] * a[2][1] - a[0][1] * a[2][2]) * inv_det;
239:     inv[0][2] = (a[0][1] * a[1][2] - a[0][2] * a[1][1]) * inv_det;
240:     inv[1][0] = (a[1][2] * a[2][0] - a[1][0] * a[2][2]) * inv_det;
241:     inv[1][1] = (a[0][0] * a[2][2] - a[0][2] * a[2][0]) * inv_det;
242:     inv[1][2] = (a[0][2] * a[1][0] - a[0][0] * a[1][2]) * inv_det;
243:     inv[2][0] = (a[1][0] * a[2][1] - a[1][1] * a[2][0]) * inv_det;
244:     inv[2][1] = (a[0][1] * a[2][0] - a[0][0] * a[2][1]) * inv_det;
245:     inv[2][2] = (a[0][0] * a[1][1] - a[0][1] * a[1][0]) * inv_det;
246: 
247:     let translation = [m[0][3], m[1][3], m[2][3]];
248:     for row in inv.iter_mut().take(3) {
249:         row[3] = -(row[0] * translation[0] + row[1] * translation[1] + row[2] * translation[2]);
250:     }
251:     inv[3][3] = 1.0;
252:     inv
253: }
254: 
255: /// Reads a column-major FBX 4x4 matrix into a row-major [`Mat4`].
256: pub fn mat4_from_column_major(values: &[f64]) -> Mat4 {
257:     let mut m = [[0.0; 4]; 4];
258:     for col in 0..4 {
259:         for row in 0..4 {
260:             m[row][col] = values[col * 4 + row];
261:         }
262:     }
263:     m
264: }
265: 
266: #[cfg(test)]
267: mod tests {
268:     use super::*;
269: 
270:     fn approx(a: &[f64], b: &[f64], eps: f64) {
271:         assert_eq!(a.len(), b.len());
272:         for (x, y) in a.iter().zip(b) {
273:             assert!((x - y).abs() < eps, "{a:?} != {b:?}");
274:         }
275:     }
276: 
277:     #[test]
278:     fn euler_xyz_matches_the_closed_form() {
279:         // pymomentum's euler_xyz_to_quaternion, which the reference model uses.
280:         let (rx, ry, rz) = (0.3_f64, -0.7_f64, 1.1_f64);
281:         let (sr, cr) = (rx * 0.5).sin_cos();
282:         let (sp, cp) = (ry * 0.5).sin_cos();
283:         let (sy, cy) = (rz * 0.5).sin_cos();
284:         let expected = [
285:             sr * cp * cy - cr * sp * sy,
286:             cr * sp * cy + sr * cp * sy,
287:             cr * cp * sy - sr * sp * cy,
288:             cr * cp * cy + sr * sp * sy,
289:         ];
290:         approx(&quat_from_euler([rx, ry, rz], [0, 1, 2]), &expected, 1e-12);
291:     }
292: 
293:     #[test]
294:     fn matrix_round_trip() {
295:         let q = quat_normalize([0.2, -0.5, 0.31, 0.77]);
296:         let back = quat_from_matrix(quat_to_matrix(q));
297:         approx(&q, &back, 1e-12);
298:     }
299: 
300:     #[test]
301:     fn transform_inverse_cancels() {
302:         let t = Transform {
303:             translation: [1.5, -2.0, 3.25],
304:             rotation: quat_normalize([0.2, -0.5, 0.31, 0.77]),
305:             scale: 1.7,
306:         };
307:         let identity = t.compose(&t.inverse());
308:         approx(&identity.translation, &[0.0, 0.0, 0.0], 1e-12);
309:         assert!((identity.scale - 1.0).abs() < 1e-12);
310:     }
311: 
312:     #[test]
313:     fn from_matrix_recovers_a_transform() {
314:         let t = Transform {
315:             translation: [1.5, -2.0, 3.25],
316:             rotation: quat_normalize([0.2, -0.5, 0.31, 0.77]),
317:             scale: 1.7,
318:         };
319:         let r = quat_to_matrix(t.rotation);
320:         let mut m = [[0.0; 4]; 4];
321:         for row in 0..3 {
322:             for col in 0..3 {
323:                 m[row][col] = r[row][col] * t.scale;
324:             }
325:             m[row][3] = t.translation[row];
326:         }
327:         m[3][3] = 1.0;
328: 
329:         let decoded = Transform::from_matrix(&m);
330:         approx(&decoded.translation, &t.translation, 1e-12);
331:         approx(&decoded.rotation, &t.rotation, 1e-12);
332:         assert!((decoded.scale - t.scale).abs() < 1e-12);
333:     }
334: 
335:     #[test]
336:     fn affine_inverse_matches_transform_inverse() {
337:         let t = Transform {
338:             translation: [0.5, 4.0, -1.25],
339:             rotation: quat_normalize([-0.1, 0.4, 0.2, 0.9]),
340:             scale: 0.8,
341:         };
342:         let r = quat_to_matrix(t.rotation);
343:         let mut m = [[0.0; 4]; 4];
344:         for row in 0..3 {
345:             for col in 0..3 {
346:                 m[row][col] = r[row][col] * t.scale;
347:             }
348:             m[row][3] = t.translation[row];
349:         }
350:         m[3][3] = 1.0;
351: 
352:         let decoded = Transform::from_matrix(&affine_inverse(&m));
353:         let expected = t.inverse();
354:         approx(&decoded.translation, &expected.translation, 1e-10);
355:         assert!((decoded.scale - expected.scale).abs() < 1e-10);
356:     }
357: }

