1: //! Identities and dense adapters for Momentum's joint-channel transform.
2: 
3: use crate::character::PARAMETERS_PER_JOINT;
4: use fabelgeist_rig::{RigJointOrdinal, RigJointTable};
5: use std::ops::{Index, IndexMut};
6: 
7: /// A joint channel is a matrix row, never a model-parameter column.
8: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
9: pub struct JointParameterRow {
10:     joint: RigJointOrdinal,
11:     channel: JointChannel,
12: }
13: 
14: /// Insertion-ordered column in one admitted parameter transform.
15: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
16: pub struct ModelParameterColumn(usize);
17: 
18: /// Exact, case-sensitive model-parameter identity; duplicates retain order.
19: #[derive(Debug, Clone, PartialEq, Eq)]
20: pub struct ModelParameterName(String);
21: 
22: /// Exact identity of an authored parameter subset.
23: #[derive(Debug, Clone, PartialEq, Eq, Hash)]
24: pub struct ParameterSetName(String);
25: 
26: /// Values in joint order, with the seven channels stored in authored order.
27: #[derive(Debug, Clone)]
28: pub struct JointParameterTable<T>(RigJointTable<[T; PARAMETERS_PER_JOINT]>);
29: 
30: /// Values in insertion-ordered model-parameter columns.
31: #[derive(Debug, Clone)]
32: pub struct ModelParameterTable<T>(Vec<T>);
33: 
34: /// Row-major coefficients with row and column identity retained at every API.
35: #[derive(Debug, Default, Clone)]
36: pub struct ParameterMatrix {
37:     values: Vec<f32>,
38:     joints: usize,
39:     columns: usize,
40: }
41: 
42: /// Borrowed coefficients selected by a joint-channel row.
43: #[derive(Debug)]
44: pub struct ModelParameterRow<'a>(&'a [f32]);
45: 
46: /// The authored seven-channel order of each Momentum joint.
47: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
48: pub enum JointChannel {
49:     TranslationX,
50:     TranslationY,
51:     TranslationZ,
52:     RotationX,
53:     RotationY,
54:     RotationZ,
55:     Scale,
56: }
57: 
58: impl JointChannel {
59:     pub const ALL: [Self; PARAMETERS_PER_JOINT] = [
60:         Self::TranslationX,
61:         Self::TranslationY,
62:         Self::TranslationZ,
63:         Self::RotationX,
64:         Self::RotationY,
65:         Self::RotationZ,
66:         Self::Scale,
67:     ];
68:     pub const TRANSLATIONS: [Self; 3] =
69:         [Self::TranslationX, Self::TranslationY, Self::TranslationZ];
70:     pub const ROTATION_AND_SCALE: [Self; 4] = [
71:         Self::RotationX,
72:         Self::RotationY,
73:         Self::RotationZ,
74:         Self::Scale,
75:     ];
76: 
77:     pub fn from_model_token(token: &str) -> Option<Self> {
78:         match token {
79:             "tx" => Some(Self::TranslationX),
80:             "ty" => Some(Self::TranslationY),
81:             "tz" => Some(Self::TranslationZ),
82:             "rx" => Some(Self::RotationX),
83:             "ry" => Some(Self::RotationY),
84:             "rz" => Some(Self::RotationZ),
85:             "sc" => Some(Self::Scale),
86:             _ => None,
87:         }
88:     }
89: 
90:     fn offset(self) -> usize {
91:         match self {
92:             Self::TranslationX => 0,
93:             Self::TranslationY => 1,
94:             Self::TranslationZ => 2,
95:             Self::RotationX => 3,
96:             Self::RotationY => 4,
97:             Self::RotationZ => 5,
98:             Self::Scale => 6,
99:         }
100:     }
101: }
102: 
103: impl JointParameterRow {
104:     pub fn new(joint: RigJointOrdinal, channel: JointChannel) -> Self {
105:         Self { joint, channel }
106:     }
107: 
108:     /// Native row-major offset, used only by the dense matrix adapter.
109:     fn offset(self) -> usize {
110:         usize::from(self.joint) * PARAMETERS_PER_JOINT + self.channel.offset()
111:     }
112: }
113: 
114: impl ModelParameterColumn {
115:     /// Native parameter-vector/tensor indexing at a numerical boundary.
116:     pub fn native_index(self) -> usize {
117:         self.0
118:     }
119: }
120: 
121: impl From<&str> for ModelParameterName {
122:     fn from(name: &str) -> Self {
123:         Self(name.to_owned())
124:     }
125: }
126: 
127: impl From<String> for ModelParameterName {
128:     fn from(name: String) -> Self {
129:         Self(name)
130:     }
