230: impl ParameterMatrix {
231:     pub fn zeros(joints: usize, columns: usize) -> Self {
232:         Self {
233:             values: vec![0.0; joints * PARAMETERS_PER_JOINT * columns],
234:             joints,
235:             columns,
236:         }
237:     }
238: 
239:     pub fn rows(&self) -> impl Iterator<Item = JointParameterRow> + use<> {
240:         (0..self.joints).flat_map(|joint| {
241:             JointChannel::ALL
242:                 .into_iter()
243:                 .map(move |channel| JointParameterRow::new(joint.into(), channel))
244:         })
245:     }
246: 
247:     pub fn row(&self, row: JointParameterRow) -> ModelParameterRow<'_> {
248:         let start = row.offset() * self.columns;
249:         ModelParameterRow(&self.values[start..start + self.columns])
250:     }
251: 
252:     pub fn add(&mut self, row: JointParameterRow, column: ModelParameterColumn, value: f32) {
253:         self.values[row.offset() * self.columns + column.0] += value;
254:     }
255: 
256:     pub fn append_columns(&mut self, columns: usize) {
257:         let mut expanded = Self::zeros(self.joints, columns);
258:         for row in self.rows() {
259:             let start = row.offset() * columns;
260:             expanded.values[start..start + self.columns].copy_from_slice(self.row(row).as_slice());
261:         }
262:         *self = expanded;
263:     }
264: 
265:     /// Transpose the selected leading columns for native `parameters @ transform`.
266:     pub fn tensor_transpose(&self, columns: usize) -> Vec<f32> {
267:         let rows = self.joints * PARAMETERS_PER_JOINT;
268:         let mut transposed = vec![0.0; columns * rows];
269:         for row in self.rows() {
270:             for column in 0..columns {
271:                 transposed[column * rows + row.offset()] =
272:                     self.row(row)[ModelParameterColumn(column)];
273:             }
274:         }
275:         transposed
276:     }
277: }
