1: //! Quaternion and skeleton-state algebra on Burn tensors.
2: //!
3: //! A skeleton state is `[tx, ty, tz, qx, qy, qz, qw, s]` and represents a
4: //! rigid transform with uniform scale. All helpers work on rank-3 tensors
5: //! shaped `[batch, count, channels]`, which is every shape MHR needs.
6: 
7: use burn::tensor::Tensor;
8: use fabelgeist_rig::{RigJointOrdinal, RigJointTable};
9: 
10: /// Pointer-jumping levels that turn local states into global ones.
11: ///
12: /// Level `l` multiplies every joint whose depth has bit `l` set by the
13: /// accumulated state of its ancestor at the depth prefix below that bit. This
14: /// is pymomentum's `calc_fk_prefix_multiplication_indices`, and it replaces a
15: /// 127-step serial walk with `ceil(log2(depth))` batched steps.
16: pub struct PrefixMultiplicationLevel {
17:     pub source: Vec<RigJointOrdinal>,
18:     pub target: Vec<RigJointOrdinal>,
19: }
20: 
21: /// One channel of the last dimension, keeping the rank.
22: fn channel(tensor: &Tensor<3>, index: usize) -> Tensor<3> {
23:     tensor.clone().narrow(2, index, 1)
24: }
25: 
26: /// The `[x, y, z]` part of a quaternion.
27: fn axis(quaternion: &Tensor<3>, offset: usize) -> Tensor<3> {
28:     quaternion.clone().narrow(2, offset, 3)
29: }
30: 
31: /// Hamilton product of two normalized quaternions, `[..., 4]`.
32: pub fn quaternion_multiply(a: Tensor<3>, b: Tensor<3>) -> Tensor<3> {
33:     let (x1, y1, z1, w1) = (
34:         channel(&a, 0),
35:         channel(&a, 1),
36:         channel(&a, 2),
37:         channel(&a, 3),
38:     );
39:     let (x2, y2, z2, w2) = (
40:         channel(&b, 0),
41:         channel(&b, 1),
42:         channel(&b, 2),
43:         channel(&b, 3),
44:     );
45: 
46:     let x = w1.clone() * x2.clone() + x1.clone() * w2.clone() + y1.clone() * z2.clone()
47:         - z1.clone() * y2.clone();
48:     let y = w1.clone() * y2.clone() - x1.clone() * z2.clone()
49:         + y1.clone() * w2.clone()
50:         + z1.clone() * x2.clone();
51:     let z = w1.clone() * z2.clone() + x1.clone() * y2.clone() - y1.clone() * x2.clone()
52:         + z1.clone() * w2.clone();
53:     let w = w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2;
54: 
55:     Tensor::cat(vec![x, y, z, w], 2)
56: }
57: 
58: /// XYZ Euler angles (radians) to a quaternion, matching pymomentum's
59: /// `euler_xyz_to_quaternion` (the x rotation is applied first).
60: pub fn euler_xyz_to_quaternion(euler: Tensor<3>) -> Tensor<3> {
61:     let half = euler * 0.5;
62:     let (roll, pitch, yaw) = (channel(&half, 0), channel(&half, 1), channel(&half, 2));
63:     let (sr, cr) = (roll.clone().sin(), roll.cos());
64:     let (sp, cp) = (pitch.clone().sin(), pitch.cos());
65:     let (sy, cy) = (yaw.clone().sin(), yaw.cos());
66: 
67:     let x = sr.clone() * cp.clone() * cy.clone() - cr.clone() * sp.clone() * sy.clone();
68:     let y = cr.clone() * sp.clone() * cy.clone() + sr.clone() * cp.clone() * sy.clone();
69:     let z = cr.clone() * cp.clone() * sy.clone() - sr.clone() * sp.clone() * cy.clone();
70:     let w = cr * cp * cy + sr * sp * sy;
71: 
72:     Tensor::cat(vec![x, y, z, w], 2)
73: }
74: 
75: /// Rotates `points` by a normalized quaternion, `v + 2 * (r * (a x v) + a x (a x v))`.
76: pub fn quaternion_rotate(quaternion: &Tensor<3>, points: Tensor<3>) -> Tensor<3> {
77:     let scalar = channel(quaternion, 3);
78:     let vector = axis(quaternion, 0);
79:     let av = cross(vector.clone(), points.clone());
80:     let aav = cross(vector, av.clone());
81:     points + (av * scalar + aav) * 2.0
82: }
83: 
84: fn cross(a: Tensor<3>, b: Tensor<3>) -> Tensor<3> {
85:     let (ax, ay, az) = (channel(&a, 0), channel(&a, 1), channel(&a, 2));
86:     let (bx, by, bz) = (channel(&b, 0), channel(&b, 1), channel(&b, 2));
87:     Tensor::cat(
88:         vec![
89:             ay.clone() * bz.clone() - az.clone() * by.clone(),
90:             az * bx.clone() - ax.clone() * bz,
91:             ax * by - ay * bx,
92:         ],
93:         2,
94:     )
95: }
96: 
97: /// Splits a skeleton state into translation, rotation and scale.
98: pub fn split(state: &Tensor<3>) -> (Tensor<3>, Tensor<3>, Tensor<3>) {
99:     (
100:         state.clone().narrow(2, 0, 3),
101:         state.clone().narrow(2, 3, 4),
102:         state.clone().narrow(2, 7, 1),
103:     )
104: }
105: 
106: /// Composes two skeleton states, `s1 * s2`.
107: pub fn multiply(s1: Tensor<3>, s2: Tensor<3>) -> Tensor<3> {
108:     let (t1, q1, scale1) = split(&s1);
109:     let (t2, q2, scale2) = split(&s2);
110:     let translation = t1 + quaternion_rotate(&q1, t2) * scale1.clone();
111:     Tensor::cat(
112:         vec![translation, quaternion_multiply(q1, q2), scale1 * scale2],
113:         2,
114:     )
115: }
116: 
117: /// Applies a skeleton state to points, `t + q * (s * p)`.
118: pub fn transform_points(state: &Tensor<3>, points: Tensor<3>) -> Tensor<3> {
119:     let (translation, rotation, scale) = split(state);
120:     translation + quaternion_rotate(&rotation, points * scale)
121: }
122: 
123: pub fn prefix_multiplication_levels(
124:     parents: &RigJointTable<Option<RigJointOrdinal>>,
125: ) -> Vec<PrefixMultiplicationLevel> {
126:     let chains: Vec<Vec<RigJointOrdinal>> = parents
127:         .ordinals()
128:         .map(|joint| {
129:             let mut chain = vec![joint];
130:             let mut current = joint;
131:             while let Some(parent) = parents[current] {
132:                 current = parent;
133:                 chain.push(current);
134:             }
135:             chain.reverse();
136:             chain
137:         })
138:         .collect();
139: 
140:     let mut levels = Vec::new();
141:     loop {
142:         let level = levels.len();
143:         let mut source = Vec::new();
144:         let mut target = Vec::new();
145:         for chain in &chains {
146:             let depth = chain.len() - 1;
147:             if (depth >> level) & 1 == 1 {
148:                 source.push(chain[depth]);
149:                 target.push(chain[((depth >> level) << level) - 1]);
150:             }
151:         }
152:         if source.is_empty() {
153:             break;
154:         }
155:         levels.push(PrefixMultiplicationLevel { source, target });
156:     }
157:     levels
158: }
