274:             serial.push(match parent {
275:                 None => *local,
276:                 Some(parent) => serial[parent].compose(local),
277:             });
278:         }
279: 
280:         let mut scanned = locals.clone();
281:         for PrefixMultiplicationLevel { source, target } in &levels {
282:             let updated: Vec<math::Transform> = source
283:                 .iter()
284:                 .zip(target)
285:                 .map(|(s, t)| scanned[*t].compose(&scanned[*s]))
286:                 .collect();
287:             for (slot, value) in source.iter().zip(updated) {
288:                 scanned[*slot] = value;
289:             }
290:         }
291: 
292:         for (joint, (a, b)) in serial.iter().zip(&scanned).enumerate() {
293:             let (a, b) = (a.to_skel_state(), b.to_skel_state());
294:             for channel in 0..8 {
295:                 assert!(
296:                     (a[channel] - b[channel]).abs() < 1e-9,
297:                     "joint {joint}: {a:?} != {b:?}"
298:                 );
299:             }
300:         }
301:     }
302: }

151:     fn record_mesh(
152:         &self,
153:         batch: &mut KernelBatch,
154:         particles: &Particles,
155:         search_radius: f32,
156:     ) -> Result<()> {
157:         let Some(mesh) = &self.mesh else {
158:             return Ok(());
159:         };
160:         let mut parameters = PassParameters::new();
161:         parameters.insert("positions", particles.positions.clone());
162:         parameters.insert("previous", particles.previous.clone());
163:         mesh.bind(&mut parameters);
164:         parameters.insert("count", particles.count());
165:         parameters.insert("thickness", mesh.surface.thickness + self.particle_radius);
166:         parameters.insert("friction", mesh.surface.friction);
167:         parameters.insert("search_radius", search_radius);
168:         batch.dispatch_items(&self.mesh_kernel, &parameters, particles.count())?;
169:         Ok(())
170:     }
171: 
172:     /// Lift particles that start *inside* the mesh back out to its surface.
173:     ///
174:     /// A substep only looks as far as the collision shell and the distance the
175:     /// particle just travelled, which is what keeps it cheap. A particle sunk
176:     /// deep inside the body finds no triangle in that range at all and is left
177:     /// where it is -- and a garment's initial layout puts plenty of panels
178:     /// through the body before the first step ever runs.
179:     ///
180:     /// So this is a separate pass with a search radius wide enough to reach
181:     /// the surface from inside. Run it after laying a garment out, and repeat
182:     /// it a few times: each pass moves a particle to the nearest surface it
183:     /// can see, which for a deeply buried one may not be the final answer.
184:     pub fn record_push_out(
185:         &self,
186:         batch: &mut KernelBatch,
187:         particles: &Particles,
188:         search_radius: f32,
189:     ) -> Result<()> {
190:         if particles.count() == 0 {
191:             return Ok(());
192:         }
193:         // The pass reads `previous` for friction and for the swept box. Making
194:         // it equal to the current position means no motion to rub against and
195:         // a box centred on the particle, which is what a static recovery
196:         // wants.
197:         batch.copy_buffer(
198:             &particles.positions,
199:             &particles.previous,
200:             particles.count() as u64 * 16,
201:         )?;
202:         self.record_mesh(batch, particles, search_radius)?;
203:         Ok(())
204:     }
205: 
206:     /// [`Collisions::record_push_out`], on its own batch, repeated.
207:     pub fn push_out(
208:         &self,
209:         context: &WgpuContext,
210:         particles: &Particles,
211:         search_radius: f32,
212:         passes: u32,
213:     ) -> Result<()> {
214:         let mut batch = KernelBatch::labelled(context, "push out");
215:         for _ in 0..passes {
216:             self.record_push_out(&mut batch, particles, search_radius)?;
217:         }
218:         batch.submit();
219:         Ok(())
220:     }
221: }
222: 
223: impl SubstepHook for Collisions {
224:     fn record(
225:         &mut self,
226:         batch: &mut KernelBatch,
227:         particles: &Particles,
228:         _substep: f32,
229:     ) -> Result<()> {
230:         Collisions::record(self, batch, particles)
231:     }
232: }
233: 
234: /// Run several hooks in order, so that collisions and, say, a self-collision
235: /// pass can both sit in the same substep.
236: pub struct HookChain<'a> {
237:     pub hooks: Vec<&'a mut dyn SubstepHook>,
238: }
239: 
240: impl<'a> HookChain<'a> {
241:     pub fn new(hooks: Vec<&'a mut dyn SubstepHook>) -> Self {
242:         Self { hooks }
243:     }
244: }
245: 
246: impl SubstepHook for HookChain<'_> {
247:     fn record(
248:         &mut self,
249:         batch: &mut KernelBatch,
250:         particles: &Particles,
251:         substep: f32,
252:     ) -> Result<()> {
253:         for hook in self.hooks.iter_mut() {
254:             hook.record(batch, particles, substep)?;
255:         }
256:         Ok(())
257:     }
258: }
