1: //! The collision kernels.
2: //!
3: //! Both of them are XPBD substep hooks: they run after the prediction and
4: //! before the material constraints, and they resolve by moving positions. A
5: //! position moved here becomes a velocity change for free when the substep
6: //! finalises, which is why there is no impulse arithmetic anywhere.
7: 
8: /// Signed distance to each analytic shape, and the outward direction. Mirrors
9: /// `Collider::signed_distance` on the host.
10: pub const SHAPES: &str = r#"
11: struct Collider {
12:     data0: vec4<f32>,
13:     data1: vec4<f32>,
14:     data2: vec4<f32>,
15:     // x = kind (bitcast u32), y = friction, z = thickness
16:     settings: vec4<f32>,
17: };
18: 
19: struct Surface {
20:     distance: f32,
21:     // Outward, away from the solid.
22:     normal: vec3<f32>,
23: };
24: 
25: fn quaternion_rotate(q: vec4<f32>, v: vec3<f32>) -> vec3<f32> {
26:     let u = q.xyz;
27:     return u * (2.0 * dot(u, v)) + v * (q.w * q.w - dot(u, u)) + cross(u, v) * (2.0 * q.w);
28: }
29: 
30: fn quaternion_conjugate(q: vec4<f32>) -> vec4<f32> {
31:     return vec4<f32>(-q.xyz, q.w);
32: }
33: 
34: // A direction to fall back on when the point sits exactly on the medial axis
35: // and there is no well-defined outward. Any fixed choice will do; it only has
36: // to be finite.
37: const DEGENERATE_NORMAL = vec3<f32>(0.0, 1.0, 0.0);
38: 
39: fn collider_surface(collider: Collider, point: vec3<f32>) -> Surface {
40:     let kind = bitcast<u32>(collider.settings.x);
41: 
42:     if (kind == 0u) {
43:         // Plane.
44:         return Surface(dot(point, collider.data0.xyz) - collider.data0.w, collider.data0.xyz);
45:     }
46: 
47:     if (kind == 1u) {
48:         // Sphere.
49:         let delta = point - collider.data0.xyz;
50:         let length_ = length(delta);
51:         var normal = DEGENERATE_NORMAL;
52:         if (length_ > 1e-9) {
53:             normal = delta / length_;
54:         }
55:         return Surface(length_ - collider.data0.w, normal);
56:     }
57: 
58:     if (kind == 2u) {
59:         // Capsule: the segment a-b thickened by a radius.
60:         let a = collider.data0.xyz;
61:         let b = collider.data1.xyz;
62:         let axis = b - a;
63:         let length_squared = dot(axis, axis);
64:         var t = 0.0;
65:         if (length_squared > 1e-12) {
66:             t = clamp(dot(point - a, axis) / length_squared, 0.0, 1.0);
67:         }
68:         let delta = point - (a + axis * t);
69:         let length_ = length(delta);
70:         var normal = DEGENERATE_NORMAL;
71:         if (length_ > 1e-9) {
72:             normal = delta / length_;
73:         }
74:         return Surface(length_ - collider.data0.w, normal);
75:     }
76: 
77:     // Box.
78:     let rotation = collider.data2;
79:     let local = quaternion_rotate(quaternion_conjugate(rotation), point - collider.data0.xyz);
80:     let q = abs(local) - collider.data1.xyz;
81:     let outside = max(q, vec3<f32>(0.0));
82:     let outside_length = length(outside);
83:     let inside = min(max(q.x, max(q.y, q.z)), 0.0);
84: 
85:     var local_normal: vec3<f32>;
86:     if (outside_length > 1e-9) {
87:         local_normal = (outside / outside_length) * sign(local);
88:     } else {
89:         // Inside: the nearest face is the least negative component.
90:         if (q.x >= q.y && q.x >= q.z) {
91:             local_normal = vec3<f32>(sign(local.x), 0.0, 0.0);
92:         } else if (q.y >= q.z) {
93:             local_normal = vec3<f32>(0.0, sign(local.y), 0.0);
94:         } else {
95:             local_normal = vec3<f32>(0.0, 0.0, sign(local.z));
96:         }
97:     }
98:     return Surface(outside_length + inside, quaternion_rotate(rotation, local_normal));
99: }
100: "#;
101: 
102: /// The response shared by both kernels: push out along the normal, then apply
103: /// Coulomb friction against the motion made so far this substep.
104: ///
105: /// Friction in XPBD is positional too. The tangential part of the particle's
106: /// own movement since the substep began is what friction opposes, and the
107: /// Coulomb limit scales with the penetration depth -- which is standing in for
108: /// the normal force, exactly as it does in the rigid-body formulation.
109: pub const RESPONSE: &str = r#"
110: fn collision_response(
111:     position: vec3<f32>,
112:     previous_position: vec3<f32>,
113:     normal: vec3<f32>,
114:     penetration: f32,
115:     friction: f32,
116: ) -> vec3<f32> {
117:     if (penetration <= 0.0) {
118:         return vec3<f32>(0.0);
119:     }
120: 
121:     var correction = normal * penetration;
122: 
123:     if (friction > 0.0) {
124:         // Where the particle would sit once pushed out, against where it was
125:         // when the substep started.
126:         let travelled = (position + correction) - previous_position;
127:         let tangential = travelled - normal * dot(travelled, normal);
128:         let magnitude = length(tangential);
129:         if (magnitude > 1e-9) {
130:             // Static below the limit -- cancel the slide outright; dynamic
131:             // above it -- cancel only as much as the limit allows.
132:             let limit = friction * penetration;
133:             let scale = min(limit / magnitude, 1.0);
134:             correction = correction - tangential * scale;
135:         }
136:     }
137: 
138:     return correction;
139: }
140: "#;
141: 
142: /// Resolve every particle against every analytic collider.
143: ///
144: /// One thread per particle, looping over the colliders. There is no broad
145: /// phase because there is nothing to gain from one: the list is a handful of
146: /// shapes, and reading it is cheaper than culling it.
147: pub fn analytic_source() -> String {
148:     format!(
149:         r#"
150: @group(0) @binding(0) var<storage, read_write> positions: array<vec4<f32>>;
151: @group(0) @binding(1) var<storage, read> previous: array<vec4<f32>>;
152: @group(0) @binding(2) var<storage, read> colliders: array<Collider>;
153: 
154: struct Params {{
155:     count: u32,
156:     collider_count: u32,
157:     particle_radius: f32,
158:     pad: u32,
159: }};
160: @group(0) @binding(3) var<uniform> params: Params;
161: {SHAPES}
162: {RESPONSE}
163: 
164: @compute @workgroup_size(256)
165: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {{
166:     let index = global_id.x;
167:     if (index >= params.count) {{
168:         return;
169:     }}
170: 
171:     let entry = positions[index];
172:     if (entry.w == 0.0) {{
173:         return;
174:     }}
175: 
176:     var position = entry.xyz;
177:     let previous_position = previous[index].xyz;
178: 
179:     for (var i = 0u; i < params.collider_count; i = i + 1u) {{
180:         let collider = colliders[i];
181:         let surface = collider_surface(collider, position);
182:         let separation = collider.settings.z + params.particle_radius;
183:         let penetration = separation - surface.distance;
184:         position = position + collision_response(
185:             position,
186:             previous_position,
187:             surface.normal,
188:             penetration,
189:             collider.settings.y,
190:         );
191:     }}
192: 
193:     positions[index] = vec4<f32>(position, entry.w);
194: }}
195: "#
196:     )
197: }
198: 
199: /// Resolve every particle against a triangle mesh, through the mesh's own BVH.
200: ///

201: /// `traversal` is the source generated by `fabelgeist_bvh::gpu::traversal_source`,
202: /// which calls back into `bvh_hit` for every candidate triangle. WGSL has no
203: /// closures, so the callback keeps its result in module-scope `var`s -- the
204: /// kernel is one particle per thread, so there is nothing to share them with.
205: pub fn mesh_source(traversal: &str) -> String {
206:     format!(
207:         r#"
208: @group(0) @binding(0) var<storage, read_write> positions: array<vec4<f32>>;
209: @group(0) @binding(1) var<storage, read> previous: array<vec4<f32>>;
210: @group(0) @binding(2) var<storage, read> mesh_positions: array<vec4<f32>>;
211: @group(0) @binding(3) var<storage, read> mesh_triangles: array<u32>;
212: @group(0) @binding(4) var<storage, read> bvh_nodes: array<vec4<f32>>;
213: @group(0) @binding(5) var<storage, read> bvh_right_children: array<u32>;
214: @group(0) @binding(6) var<storage, read> bvh_indices: array<u32>;
215: 
216: struct Params {{
217:     count: u32,
218:     thickness: f32,
219:     friction: f32,
220:     // Widens the search beyond the shell. Zero for a normal substep, where the
221:     // swept box is enough; large for the recovery pass that has to find the
222:     // surface from deep inside the mesh.
223:     search_radius: f32,
224: }};
225: @group(0) @binding(7) var<uniform> params: Params;
226: {RESPONSE}
227: 
228: // The query, and the best candidate so far. One particle per thread, so these
229: // stand in for the closure the traversal would otherwise take.
230: var<private> query_point: vec3<f32>;
231: var<private> best_distance_squared: f32;
232: var<private> best_point: vec3<f32>;
233: var<private> best_normal: vec3<f32>;
234: var<private> found: bool;
235: 
236: fn triangle_closest_point(p: vec3<f32>, a: vec3<f32>, b: vec3<f32>, c: vec3<f32>) -> vec3<f32> {{
237:     // Ericson, Real-Time Collision Detection 5.1.5: the three vertex regions
238:     // and the three edge regions come first, so a point outside the triangle's
239:     // prism gets the right answer rather than a projection onto the plane.
240:     let ab = b - a;
241:     let ac = c - a;
242:     let ap = p - a;
243: 
244:     let d1 = dot(ab, ap);
245:     let d2 = dot(ac, ap);
246:     if (d1 <= 0.0 && d2 <= 0.0) {{ return a; }}
247: 
248:     let bp = p - b;
249:     let d3 = dot(ab, bp);
250:     let d4 = dot(ac, bp);
251:     if (d3 >= 0.0 && d4 <= d3) {{ return b; }}
252: 
253:     let vc = d1 * d4 - d3 * d2;
254:     if (vc <= 0.0 && d1 >= 0.0 && d3 <= 0.0) {{
255:         let denominator = d1 - d3;
256:         if (abs(denominator) < 1e-20) {{ return a; }}
257:         return a + ab * (d1 / denominator);
258:     }}
259: 
260:     let cp = p - c;
261:     let d5 = dot(ab, cp);
262:     let d6 = dot(ac, cp);
263:     if (d6 >= 0.0 && d5 <= d6) {{ return c; }}
264: 
265:     let vb = d5 * d2 - d1 * d6;
266:     if (vb <= 0.0 && d2 >= 0.0 && d6 <= 0.0) {{
267:         let denominator = d2 - d6;
268:         if (abs(denominator) < 1e-20) {{ return a; }}
269:         return a + ac * (d2 / denominator);
270:     }}
271: 
272:     let va = d3 * d6 - d5 * d4;
273:     if (va <= 0.0 && (d4 - d3) >= 0.0 && (d5 - d6) >= 0.0) {{
274:         let denominator = (d4 - d3) + (d5 - d6);
275:         if (abs(denominator) < 1e-20) {{ return b; }}
276:         return b + (c - b) * ((d4 - d3) / denominator);
277:     }}
278: 
279:     let denominator = va + vb + vc;
280:     if (abs(denominator) < 1e-20) {{ return a; }}
281:     return a + ab * (vb / denominator) + ac * (vc / denominator);
282: }}
283: 
284: fn bvh_hit(triangle: u32) {{
285:     let ia = mesh_triangles[triangle * 3u];
286:     let ib = mesh_triangles[triangle * 3u + 1u];
287:     let ic = mesh_triangles[triangle * 3u + 2u];
288:     let a = mesh_positions[ia].xyz;
289:     let b = mesh_positions[ib].xyz;
290:     let c = mesh_positions[ic].xyz;
291: 
292:     let closest = triangle_closest_point(query_point, a, b, c);
293:     let delta = query_point - closest;
294:     let distance_squared = dot(delta, delta);
295:     if (found && distance_squared >= best_distance_squared) {{
296:         return;
297:     }}
298: 
299:     found = true;
300:     best_distance_squared = distance_squared;
301:     best_point = closest;
302: 
303:     let face_normal = cross(b - a, c - a);
304:     let face_length = length(face_normal);
305:     if (face_length > 1e-20) {{
306:         best_normal = face_normal / face_length;
307:     }} else {{
308:         best_normal = vec3<f32>(0.0, 1.0, 0.0);
309:     }}
310: }}
311: {traversal}
312: 
313: @compute @workgroup_size(256)
314: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {{
315:     let index = global_id.x;
316:     if (index >= params.count) {{
317:         return;
318:     }}
319: 
320:     let entry = positions[index];
321:     if (entry.w == 0.0) {{
322:         return;
323:     }}
324: 
325:     let position = entry.xyz;
326:     let previous_position = previous[index].xyz;
327:     query_point = position;
328:     found = false;
329:     best_distance_squared = 0.0;
330: 
331:     // The box covers where the particle was as well as where it is, grown by
332:     // the shell. Querying only around the current position would miss a
333:     // particle that crossed a thin surface within one substep -- it would be
334:     // out the other side, past the shell, and look perfectly free.
335:     let margin = vec3<f32>(max(params.thickness, params.search_radius));
336:     let lower = min(position, previous_position) - margin;
337:     let upper = max(position, previous_position) + margin;
338:     bvh_query_aabb(lower, upper);
339:     if (!found) {{
340:         return;
341:     }}
342: 
343:     let delta = position - best_point;
344:     let distance = sqrt(best_distance_squared);
345:     // Which side of the surface the particle is on. The face normal decides,
346:     // rather than the direction to the closest point, because that direction
347:     // says nothing at all once the particle is exactly on the surface.
348:     let side = dot(delta, best_normal);
349: 
350:     var normal: vec3<f32>;
351:     var penetration: f32;
352:     if (side < 0.0) {{
353:         // Already through the surface: come back out the way the face faces,
354:         // by the whole depth plus the shell.
355:         normal = best_normal;
356:         penetration = distance + params.thickness;
357:     }} else {{
358:         if (distance >= params.thickness) {{
359:             return;
360:         }}
361:         // Outside but inside the shell. Push along the direction to the
362:         // particle where that is meaningful, and along the face otherwise.
363:         if (distance > 1e-7) {{
364:             normal = delta / distance;
365:         }} else {{
366:             normal = best_normal;
367:         }}
368:         penetration = params.thickness - distance;
369:     }}
370: 
371:     let correction = collision_response(
372:         position,
373:         previous_position,
374:         normal,
375:         penetration,
376:         params.friction,
377:     );
378:     positions[index] = vec4<f32>(position + correction, entry.w);
379: }}
380: "#
381:     )
382: }
383: 
384: /// Triangle bounds for the mesh BVH, expanded by the collision shell so that a
385: /// query for a point in the shell does not have to expand its own box.

