101: impl TryFrom<RigJointOrdinal> for u32 {
102:     type Error = TryFromIntError;
103: 
104:     fn try_from(index: RigJointOrdinal) -> Result<Self, Self::Error> {
105:         Self::try_from(index.0)
106:     }
107: }
