109: impl RigJointName {
110:     /// A query-specific comparison; exact identity remains case-sensitive.
111:     pub fn eq_ignore_ascii_case(&self, other: &Self) -> bool {
112:         self.0.eq_ignore_ascii_case(other.0.as_ref())
113:     }
114: 
115:     /// Authored joint families such as all thumb or tongue segments.
116:     pub fn family_prefix(&self, prefix: &Self) -> RigJointMembership {
117:         RigJointMembership::from(self.0.starts_with(prefix.0.as_ref()))
118:     }
119: 
120:     /// Existing garment selection matches anatomical fragments anywhere in
121:     /// the label, including helper suffixes. It does not assert canonical anatomy.
122:     pub fn contains_part(&self, part: RigJointPart) -> RigJointMembership {
123:         RigJointMembership::from(self.0.contains(part.as_ref()))
124:     }
125: 
126:     /// Preserve the first occurrence when a rig contains duplicate labels.
127:     pub fn index_in<'a>(
128:         &self,
129:         names: impl IntoIterator<Item = &'a Self>,
130:     ) -> Option<RigJointOrdinal> {
131:         names
132:             .into_iter()
133:             .position(|name: &Self| -> bool { name == self })
134:             .map(RigJointOrdinal::from)
135:     }
136:     pub fn require_in<'a>(
137:         &self,
138:         names: impl IntoIterator<Item = &'a Self>,
139:     ) -> Result<RigJointOrdinal, RigJointLookupError> {
140:         self.index_in(names).ok_or_else(|| -> RigJointLookupError {
141:             RigJointLookupError {
142:                 joint: self.clone(),
143:             }
144:         })
145:     }
146: }
147: 
148: impl From<&str> for RigJointName {
149:     fn from(name: &str) -> Self {
150:         Self(Cow::Owned(name.to_owned()))
151:     }
152: }
