1: //! Fixed-width influence ordinals retained in their native 32-bit layout.
2: 
3: use crate::{RigJointOrdinal, RigJointTable};
4: use derive_more::{Display, Error};
5: 
6: /// The ordinal bound of an admitted rig column. Equal bounds do not establish
7: /// that two independently produced columns belong to the same rig instance.
8: #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
9: pub struct RigJointCount(usize);
10: 
11: /// Packed rig influences. The width, slot order, and zero-weight slots are
12: /// retained exactly; admission checks every word against the actual rig bound.
13: #[derive(Clone, Debug, Default, PartialEq)]
14: pub struct PackedRigSkin<const WIDTH: usize> {
15:     words: Vec<[u32; WIDTH]>,
16:     joints: RigJointCount,
17: }
18: 
19: /// One vertex's ordered influences during a numerical skin calculation.
20: /// Ordinals retain their rig meaning; membership comes from the source buffer.
21: #[derive(Clone, Copy, Debug, PartialEq)]
22: pub struct RigInfluences<const WIDTH: usize> {
23:     pub joints: [RigJointOrdinal; WIDTH],
24:     pub weights: [f32; WIDTH],
25: }
26: 
27: #[derive(Clone, Copy, Debug, PartialEq, Eq, Display, Error)]
28: pub enum RigSkinError {
29:     #[display("skin joint {joint} is outside a rig of {joints} joints")]
30:     OutsideRig { joint: u32, joints: usize },
31:     #[display("skin joint cannot be represented by a native 32-bit word")]
32:     NativeWidth,
33:     #[display("appended skin has a different rig bound")]
34:     DifferentRigBound,
35: }
36: 
37: impl RigJointCount {
38:     /// A count supplied by a native rig decoder or an authored numerical
39:     /// fixture. Production callers retain their source rig's actual extent;
40:     /// deriving a larger extent from skin words would bypass membership checks.
41:     pub const fn from_native_joint_count(joints: usize) -> Self {
42:         Self(joints)
43:     }
44: 
45:     pub(crate) fn from_table<T>(table: &RigJointTable<T>) -> Self {
46:         Self(table.len())
47:     }
48: 
49:     pub fn len(self) -> usize {
50:         self.0
51:     }
52: 
53:     pub fn is_empty(self) -> bool {
54:         self.0 == 0
55:     }
56: }
57: 
58: impl RigInfluences<8> {
59:     pub fn whole_joint(joint: RigJointOrdinal) -> Self {
60:         let mut result = Self {
61:             joints: [RigJointOrdinal::from(0usize); 8],
62:             weights: [0.0; 8],
63:         };
64:         result.joints[0] = joint;
65:         result.weights[0] = 1.0;
66:         result
67:     }
68: }
69: 
70: impl<const WIDTH: usize> RigInfluences<WIDTH> {
71:     /// The VEC4 reduction shared by Bevy and glTF. Duplicate joints combine
72:     /// before sorting; equal weights retain ascending ordinal order.
73:     pub fn strongest_four(self) -> RigInfluences<4> {
74:         let mut combined = std::collections::BTreeMap::<RigJointOrdinal, f32>::new();
75:         for (joint, weight) in self.joints.into_iter().zip(self.weights) {
76:             *combined.entry(joint).or_default() += weight;
77:         }
78:         let mut influences = combined.into_iter().collect::<Vec<_>>();
79:         influences.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
80:         influences.truncate(4);
81:         let sum: f32 = influences.iter().map(|(_, weight)| weight).sum();
82:         let mut result = RigInfluences {
83:             joints: [RigJointOrdinal::from(0usize); 4],
84:             weights: [0.0; 4],
85:         };
86:         for (slot, (joint, weight)) in influences.into_iter().enumerate() {
87:             result.joints[slot] = joint;
88:             result.weights[slot] = weight / sum;
89:         }
90:         result
91:     }
92: 
93:     /// Native Bevy/glTF VEC4 word encoding, with no ordinal truncation.
94:     pub fn native_u16(self) -> Result<[u16; WIDTH], std::num::TryFromIntError> {
95:         let mut words = [0; WIDTH];
96:         for (word, joint) in words.iter_mut().zip(self.joints) {
97:             *word = u16::try_from(usize::from(joint))?;
98:         }
99:         Ok(words)
100:     }
101: }
102: 
103: impl<const WIDTH: usize> PackedRigSkin<WIDTH> {
104:     /// Decode glTF, FBX, GPU readback, or fixture words once at their source.
105:     pub fn from_native(
106:         words: Vec<[u32; WIDTH]>,
107:         joints: RigJointCount,
108:     ) -> Result<Self, RigSkinError> {
109:         for &joint in words.iter().flatten() {
110:             if usize::try_from(joint).map_or(true, |joint| joint >= joints.0) {
111:                 return Err(RigSkinError::OutsideRig {
112:                     joint,
113:                     joints: joints.0,
114:                 });
115:             }
116:         }
117:         Ok(Self { words, joints })
118:     }
119: 
120:     pub fn empty(joints: RigJointCount) -> Self {
121:         Self {
122:             words: Vec::new(),
123:             joints,
124:         }
125:     }
126: 
127:     pub fn repeated(
128:         influences: [RigJointOrdinal; WIDTH],
129:         vertices: usize,
130:         joints: RigJointCount,
131:     ) -> Result<Self, RigSkinError> {
132:         let mut skin = Self::empty(joints);
133:         let words = skin.encode(influences)?;
134:         skin.words = vec![words; vertices];
135:         Ok(skin)
136:     }
137: 
138:     pub fn len(&self) -> usize {
139:         self.words.len()
140:     }
141: 
