191:     pub fn select(&self, vertices: impl IntoIterator<Item = usize>) -> Self {
192:         Self {
193:             words: vertices
194:                 .into_iter()
195:                 .map(|vertex| self.words[vertex])
196:                 .collect(),
197:             joints: self.joints,
198:         }
199:     }
200: 
201:     pub fn append(&mut self, other: Self) -> Result<(), RigSkinError> {
202:         if self.is_empty() {
203:             *self = other;
204:             return Ok(());
205:         }
206:         if !other.is_empty() && self.joints != other.joints {
207:             return Err(RigSkinError::DifferentRigBound);
208:         }
209:         self.words.extend(other.words);
210:         Ok(())
211:     }
212: 
213:     fn encode(&self, joints: [RigJointOrdinal; WIDTH]) -> Result<[u32; WIDTH], RigSkinError> {
214:         let mut words = [0; WIDTH];
215:         for (word, joint) in words.iter_mut().zip(joints) {
216:             *word = u32::try_from(joint).map_err(|_| RigSkinError::NativeWidth)?;
217:             if usize::from(joint) >= self.joints.0 {
218:                 return Err(RigSkinError::OutsideRig {
219:                     joint: *word,
220:                     joints: self.joints.0,
221:                 });
222:             }
223:         }
224:         Ok(words)
225:     }
