19: /// When the host resolves swept contacts and outer layers between GPU
20: /// substeps. Each host projection reads particles back and waits for the GPU,
21: /// so this schedule dominates the cost of an interleaved step.
22: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
23: pub struct HostContactSchedule {
24:     /// GPU substeps swept by one host projection. Zero leaves contact to the
25:     /// GPU collider and self-collision kernels.
26:     pub interval_substeps: u32,
27:     /// Projection sweeps in one surface contact solve.
28:     pub iterations: u32,
29:     /// Alternations between an outer layer and surface contacts.
30:     pub outer_layer_passes: u32,
31: }
32: 
33: /// A simulable thin surface, shared by cloth and metal.
34: pub struct Shell {
35:     pub outer_layer: Option<crate::outer_layer::OuterLayer>,
36:     pub host_contacts: HostContactSchedule,
37:     pub particles: Particles,
38:     surface_contacts: crate::surface_contact::SurfaceContacts,
39:     pub stretch: ConstraintSet,
40:     pub bending: ConstraintSet,
41:     /// Zero-length attachments; cloth uses these for seams.
42:     pub seams: ConstraintSet,
43:     pub self_collision: SelfCollision,
44:     pub material: ShellMaterial,
45: 
46:     /// The triangle list, unchanged by simulation. Particle positions are
47:     /// interleaved with inverse masses; use `read_mesh` for packed mesh data.
48:     pub triangles: Vec<[u32; 3]>,
49:     /// Kept so the surface can be reset to its initial layout.
50:     initial_positions: Vec<Vec3>,
51:     inverse_masses: Vec<crate::ParticleInverseMass>,
52: }
53: 
54: /// Body collision then self-collision, in that order.
55: ///
56: /// Body first: the body is not going to move out of the way, so resolving the
57: /// cloth against it first means the self-collision pass is working with
58: /// positions that are already outside the body rather than pushing layers into
59: /// it.
60: struct ShellHook<'a> {
61:     collisions: &'a mut Collisions,
62:     self_collision: &'a mut SelfCollision,
63: }
64: 
65: impl Default for HostContactSchedule {
66:     fn default() -> Self {
67:         Self {
68:             interval_substeps: 1,
69:             iterations: 4,
70:             outer_layer_passes: 4,
71:         }
72:     }
