147:         Ok(Self {
148:             outer_layer: None,
149:             host_contacts: HostContactSchedule::default(),
150:             surface_contacts: crate::surface_contact::SurfaceContacts::new(
151:                 mesh.positions.len(),
152:                 mesh.triangles.clone(),
153:             )
154:             .with_seams(&mesh.seams),
155:             particles,
156:             stretch,
157:             bending,
158:             seams,
159:             self_collision,
160:             material,
161:             triangles: mesh.triangles.clone(),
162:             initial_positions: mesh.positions.clone(),
163:             inverse_masses,
164:         })
165:     }
