210:     /// Step the garment: collisions against the world, cloth against itself,
211:     /// then the material constraints.
212:     pub fn record_step(
213:         &mut self,
214:         batch: &mut KernelBatch,
215:         solver: &Solver,
216:         collisions: &mut Collisions,
217:         delta: f32,
218:     ) -> Result<()> {
219:         collisions.particle_radius = self.material.particle_radius();
220: 
221:         let mut hook = ShellHook {
222:             collisions,
223:             self_collision: &mut self.self_collision,
224:         };
225: 
226:         solver.record_step(
227:             batch,
228:             &self.particles,
229:             &mut [&mut self.stretch, &mut self.seams, &mut self.bending],
230:             &mut hook,
231:             delta,
232:         )
233:     }
