235:     pub fn step(
236:         &mut self,
237:         context: &WgpuContext,
238:         solver: &Solver,
239:         collisions: &mut Collisions,
240:         delta: f32,
241:     ) -> Result<()> {
242:         let mut batch = KernelBatch::labelled(context, "cloth step");
243:         self.record_step(&mut batch, solver, collisions, delta)?;
244:         batch.submit();
245:         Ok(())
246:     }
247: 
248:     /// Step with one submission per substep -- see
249:     /// [`Solver::step_interleaved`].
250:     ///
251:     /// This is the one to call when the solver shares a device with whatever
252:     /// is drawing the result, which for an interactive fit it always does.
253:     pub async fn step_interleaved(
254:         &mut self,
255:         context: &WgpuContext,
256:         solver: &Solver,
257:         collisions: &mut Collisions,
258:         delta: f32,
259:     ) -> Result<()> {
260:         if !delta.is_finite() || delta <= 0.0 {
261:             return Ok(());
262:         }
263:         let count = solver.settings.substeps.max(1);
264:         let substep = delta / count as f32;
265:         let schedule = self.host_contacts;
266:         let interval = schedule.interval_substeps;
267:         collisions.particle_radius = self.material.particle_radius();
268:         let mut interval_start = None;
269:         for index in 0..count {
270:             if interval > 1 && index % interval == 0 {
271:                 // Sweep the whole interval, not only its last GPU substep.
272:                 interval_start = Some(self.particles.read_positions(context).await?);
273:             }
274:             let mut batch = KernelBatch::labelled(context, "surface contact substep");
275:             let mut hook = ShellHook {
276:                 collisions,
277:                 self_collision: &mut self.self_collision,
278:             };
279:             solver.record_substep(
280:                 &mut batch,
281:                 &self.particles,
282:                 &mut [&mut self.stretch, &mut self.seams, &mut self.bending],
283:                 &mut hook,
284:                 substep,
285:             )?;
286:             batch.submit();
287:             if interval > 0 && ((index + 1) % interval == 0 || index + 1 == count) {
288:                 self.project_host_contacts(context, schedule, interval_start.take().as_deref())
289:                     .await?;
290:             }
291:         }
292:         if interval == 0 {
293:             // Bound the queue: a caller stepping on a timer must not outrun the GPU.
294:             context.submitted_work_done().await;
295:         }
296:         Ok(())
297:     }
298: 
299:     pub async fn read_positions(&self, context: &WgpuContext) -> Result<Vec<Vec3>> {
300:         self.particles.read_positions(context).await
301:     }
302: 
303:     /// Snapshot the deformed surface as reusable mesh geometry. This reads back
304:     /// particle state; it is intended for export/CSG rather than a per-frame draw.
305:     pub async fn read_mesh(&self, context: &WgpuContext) -> Result<fabelgeist_mesh::MeshData> {
306:         let positions = self.read_positions(context).await?;
307:         let mut normals = vec![Vec3::default(); positions.len()];
308:         for &[a, b, c] in &self.triangles {
309:             let n = (positions[b as usize] - positions[a as usize])
310:                 .cross(positions[c as usize] - positions[a as usize]);
311:             for i in [a, b, c] {
312:                 normals[i as usize] += n;
313:             }
314:         }
315:         Ok(fabelgeist_mesh::MeshData {
316:             positions: positions.iter().map(|p| [p.x, p.y, p.z]).collect(),
317:             normals: normals
318:                 .into_iter()
319:                 .map(|n| {
320:                     let n = if n.length_squared() > 1e-20 {
321:                         n.normalize()
322:                     } else {
323:                         Vec3::new(0.0, 1.0, 0.0)
324:                     };
325:                     [n.x, n.y, n.z]
326:                 })
327:                 .collect(),
328:             indices: Some(self.triangles.iter().flatten().copied().collect()),
329:             ..Default::default()
330:         })
