333:     /// Whether the solve has gone unstable. A garment that has blown up shows
334:     /// up as a non-finite position, and it is worth catching before it reaches
335:     /// a renderer.
336:     pub async fn is_finite(&self, context: &WgpuContext) -> Result<bool> {
337:         Ok(self
338:             .read_positions(context)
339:             .await?
340:             .iter()
341:             .all(|p| p.is_finite()))
