344:     async fn project_host_contacts(
345:         &self,
346:         context: &WgpuContext,
347:         schedule: HostContactSchedule,
348:         interval_start: Option<&[Vec3]>,
349:     ) -> Result<()> {
350:         // Alternate the outer layer and swept self contacts. Neither may
351:         // silently win merely because it is the last positional correction.
352:         for _ in 0..schedule.outer_layer_passes.max(1) {
353:             if let Some(layer) = &self.outer_layer {
354:                 layer
355:                     .project_particles(context, &self.particles, &self.triangles)
356:                     .await?;
357:             }
358:             if self.self_collision.enabled {
359:                 self.surface_contacts
360:                     .project_particles(
361:                         context,
362:                         &self.particles,
363:                         self.material.thickness,
364:                         schedule.iterations,
365:                         interval_start,
366:                     )
367:                     .await?;
368:             } else {
369:                 context.submitted_work_done().await;
370:             }
371:             let Some(layer) = &self.outer_layer else {
372:                 break;
373:             };
374:             let positions = self.particles.read_positions(context).await?;
375:             if layer.surface_residual(&positions, &self.triangles)
376:                 <= crate::outer_layer::CLEARANCE_TOLERANCE
377:             {
378:                 break;
379:             }
380:         }
381:         Ok(())
382:     }
383: }
