15: pub struct SurfaceContacts {
16:     fixed_bounds: Option<FixedBounds>,
17:     static_positions: Vec<Vec3>,
18:     static_clearance: f32,
19:     faces: Vec<[u32; 3]>,
20:     edges: Vec<[u32; 2]>,
