23: 
24: impl SurfaceContacts {
25:     pub fn new(count: usize, faces: Vec<[u32; 3]>) -> Self {
26:         let seam_copies = vec![BTreeSet::new(); count];
27:         let mut edges = BTreeSet::new();
28:         for face in &faces {
29:             for k in 0..3 {
30:                 let (a, b) = (face[k], face[(k + 1) % 3]);
31:                 assert!((a as usize) < count && (b as usize) < count);
32:                 edges.insert([a.min(b), a.max(b)]);
33:             }
34:         }
35:         Self {
36:             fixed_bounds: None,
37:             static_positions: Vec::new(),
38:             static_clearance: 0.0,
39:             faces,
40:             edges: edges.into_iter().collect(),
41:             seam_copies,
42:         }
43:     }
44: 
45:     /// Exclude shared seam vertices, never their neighbouring faces.
46:     /// Seam copies represent one physical vertex even before sewing settles.
47:     pub fn with_seams(mut self, seams: &[[u32; 2]]) -> Self {
48:         let count = self.seam_copies.len();
49:         let mut groups: Vec<usize> = (0..count).collect();
50:         for &[a, b] in seams {
51:             let from = groups[b as usize];
52:             let to = groups[a as usize];
53:             for group in &mut groups {
54:                 if *group == from {
55:                     *group = to;
56:                 }
57:             }
58:         }
59:         for i in 0..count {
60:             self.seam_copies[i] = (0..count)
61:                 .filter(|&j| groups[i] == groups[j])
62:                 .map(|j| j as u32)
63:                 .collect();
64:         }
65:         self
66:     }
67: 
68:     /// Include fixed obstacle triangles in the same swept surface solve.
69:     /// Their interiors and edges constrain cloth even when no cloth vertex
70:     /// touches the obstacle; zero inverse mass keeps the obstacle unchanged.
71:     pub fn set_static_surface(&mut self, positions: &[Vec3], faces: &[[u32; 3]], clearance: f32) {
72:         assert!(clearance.is_finite() && clearance >= 0.0);
73:         let count = self.seam_copies.len() - self.static_positions.len();
74:         let mut triangles: Vec<_> = self
75:             .faces
76:             .iter()
77:             .copied()
78:             .filter(|f| f.iter().all(|&i| (i as usize) < count))
79:             .collect();
80:         triangles.extend(faces.iter().map(|f| f.map(|i| i + count as u32)));
81:         let mut next = Self::new(count + positions.len(), triangles);
82:         next.seam_copies[..count].clone_from_slice(&self.seam_copies[..count]);
83:         next.fixed_bounds = FixedBounds::new(&next.faces, &next.edges, count, positions);
84:         next.static_positions = positions.to_vec();
85:         next.static_clearance = clearance;
86:         *self = next;
87:     }
88: 
89:     /// Project a completed GPU substep before the next integration begins.
90:     /// Particle spheres alone cannot detect triangle-interior crossings.
91:     /// Resolve relative normal velocity with mass-weighted impulses; uploading
92:     /// through `write_positions` would incorrectly reset every velocity.
93:     /// `interval_start` holds positions from before several GPU substeps;
94:     /// without it only the last substep's motion is swept.
95:     pub async fn project_particles(
96:         &self,
97:         context: &fabelgeist_gpu::globals::WgpuContext,
98:         particles: &fabelgeist_xpbd::Particles,
99:         thickness: f32,
100:         iterations: u32,
101:         interval_start: Option<&[Vec3]>,
102:     ) -> anyhow::Result<usize> {
103:         let mut previous = match interval_start {
104:             Some(start) => {
105:                 anyhow::ensure!(
106:                     start.len() == particles.count() as usize,
107:                     "interval start does not match the particle count"
108:                 );
109:                 start.to_vec()
110:             }
111:             None => {
112:                 let records = fabelgeist_xpbd::ParticlePositions::from(
113:                     particles
114:                         .previous
115:                         .read::<fabelgeist_xpbd::ParticlePositionRecord>(context)
116:                         .await?,
117:                 );
118:                 records
119:                     .positions()
120:                     .take(particles.count() as usize)
121:                     .collect()
122:             }
123:         };
124:         let predicted = particles.read_positions(context).await?;
125:         let mut corrected = predicted.clone();
126:         let mut velocities = particles.read_velocities(context).await?;
127:         let count = corrected.len();
128:         let mut masses = particles.inverse_masses().to_vec();
129:         previous.extend_from_slice(&self.static_positions);
130:         corrected.extend_from_slice(&self.static_positions);
131:         masses.resize(corrected.len(), ParticleInverseMass::PINNED);
132:         velocities.resize(corrected.len(), Vec3::default());
133:         let contacts = self.solve_inner(
134:             &mut corrected,
135:             &previous,
136:             &masses,
137:             thickness,
138:             iterations,
139:             Some(&mut velocities),
140:         );
141:         if contacts > 0 {
142:             particles.positions.write(
143:                 context,
144:                 fabelgeist_xpbd::ParticlePositions::new(
145:                     &corrected[..count],
146:                     particles.inverse_masses(),
147:                 )?
148:                 .upload(),
149:             )?;
150:             particles.velocities.write(
151:                 context,
152:                 fabelgeist_xpbd::ParticleVelocities::from(&velocities[..count]).upload(),
153:             )?;
154:         }
155:         Ok(contacts)
156:     }
157:     /// Resolve swept surface contacts. Paths are linear between the supplied
158:     /// positions, so callers must invoke this for every simulation substep.
159:     /// Contact sweeps rebuild candidate bounds from the corrected endpoints.
160:     /// Initially intersecting meshes need an untangled starting state; CCD
161:     /// prevents new crossings rather than inferring the intended layer order.
162:     pub fn solve(
163:         &self,
164:         positions: &mut [Vec3],
165:         previous: &[Vec3],
166:         inverse_masses: &[ParticleInverseMass],
167:         thickness: f32,
168:         iterations: u32,
169:     ) -> usize {
170:         if !self.static_positions.is_empty() {
171:             let count = positions.len();
172:             let mut full = positions.to_vec();
173:             let mut start = previous.to_vec();
174:             let mut masses = inverse_masses.to_vec();
175:             full.extend_from_slice(&self.static_positions);
176:             start.extend_from_slice(&self.static_positions);
177:             masses.resize(full.len(), ParticleInverseMass::PINNED);
178:             let contacts =
179:                 self.solve_inner(&mut full, &start, &masses, thickness, iterations, None);
180:             positions.copy_from_slice(&full[..count]);
181:             return contacts;
182:         }
183:         self.solve_inner(
184:             positions,
185:             previous,
186:             inverse_masses,
187:             thickness,
188:             iterations,
189:             None,
190:         )
191:     }
192: }
