1: //! Projection passes for vertex/triangle and edge/edge contacts.
2: use super::*;
3: use fabelgeist_xpbd::{
4:     ConstraintGradient, EffectiveInverseMass, MassValidity, ProjectionActivity, ProjectionDepth,
5:     RelativeNormalSpeed,
6: };
7: 
8: struct ContactState<'a> {
9:     positions: &'a mut [Vec3],
10:     previous: &'a [Vec3],
11:     inverse_masses: &'a [ParticleInverseMass],
12:     velocities: Option<&'a mut [Vec3]>,
13:     thickness: f32,
14: }
15: impl SurfaceContacts {
16:     pub(super) fn solve_inner(
17:         &self,
18:         positions: &mut [Vec3],
19:         previous: &[Vec3],
20:         inverse_masses: &[ParticleInverseMass],
21:         thickness: f32,
22:         iterations: u32,
23:         velocities: Option<&mut [Vec3]>,
24:     ) -> usize {
25:         assert_eq!(positions.len(), self.seam_copies.len());
26:         assert_eq!(positions.len(), previous.len());
27:         assert_eq!(positions.len(), inverse_masses.len());
28:         for mass in inverse_masses {
29:             assert_eq!(mass.validity(), MassValidity::FiniteNonnegative);
30:         }
31:         assert!(positions.iter().chain(previous).all(|p| p.is_finite()));
32:         if !thickness.is_finite() || thickness <= 0.0 {
33:             return 0;
34:         }
35:         let mut state = ContactState {
36:             positions,
37:             previous,
38:             inverse_masses,
39:             velocities,
40:             thickness,
41:         };
42:         let mut contacts = 0;
43:         for _ in 0..iterations {
44:             contacts += self.vertex_contacts(&mut state);
45:             contacts += self.edge_contacts(&mut state);
46:         }
47:         contacts
48:     }
49: 
50:     fn vertex_contacts(&self, state: &mut ContactState<'_>) -> usize {
51:         let thickness = state.thickness;
52:         let search_radius = thickness.max(self.static_clearance);
53:         let dynamic_count = state.positions.len() - self.static_positions.len();
54:         let positions = &mut *state.positions;
55:         let previous = state.previous;
56:         let inverse_masses = state.inverse_masses;
57:         let velocities = &mut state.velocities;
58:         let mut contacts = 0;
59:         let face_count = self
60:             .fixed_bounds
61:             .as_ref()
62:             .map_or(self.faces.len(), |b| b.face_offset);
63:         let bounds: Vec<_> = self.faces[..face_count]
64:             .iter()
65:             .map(|face| {
66:                 Aabb::from_points(
67:                     face.iter()
68:                         .flat_map(|&i| [positions[i as usize], previous[i as usize]]),
69:                 )
70:                 .expand(search_radius)
71:             })
72:             .collect();
73:         let tree = Bvh::build(&bounds);
74:         // Fixed vertices only need to query dynamic faces, avoiding
75:         // expensive body-against-body searches on a dense animated mesh.
76:         let dynamic_faces: Vec<_> = self.faces[..face_count]
77:             .iter()
78:             .enumerate()
79:             .filter_map(|(i, f)| {
80:                 f.iter()
81:                     .any(|&v| inverse_masses[v as usize].mobility() == ParticleMobility::Dynamic)
82:                     .then_some(i)
83:             })
84:             .collect();
85:         let dynamic_bounds: Vec<_> = dynamic_faces.iter().map(|&f| bounds[f]).collect();
86:         let dynamic_tree = Bvh::build(&dynamic_bounds);
87:         let mut candidates = Vec::new();
88:         for v in 0..dynamic_count {
89:             candidates.clear();
90:             let query = Aabb::from_points([positions[v], previous[v]]).expand(search_radius);
91:             if inverse_masses[v].mobility() == ParticleMobility::Dynamic {
92:                 tree.query_aabb(&bounds, &query, |f| candidates.push(f as usize));
93:                 if let Some(fixed) = &self.fixed_bounds {
94:                     fixed.faces.query(&query.expand(search_radius), |f| {
95:                         candidates.push(f + fixed.face_offset)
96:                     });
97:                 }
98:             } else {
99:                 dynamic_tree.query_aabb(&dynamic_bounds, &query, |f| {
100:                     candidates.push(dynamic_faces[f as usize])
101:                 });
102:             }
103:             for &f in &candidates {
104:                 let face = self.faces[f];
105:                 if face
106:                     .iter()
107:                     .any(|&i| i as usize == v || self.seam_copies[v].contains(&i))
108:                 {
109:                     continue;
110:                 }
111:                 contacts += resolve(
112:                     Pair::VertexTriangle,
113:                     positions,
114:                     previous,
115:                     inverse_masses,
116:                     [v, face[0] as usize, face[1] as usize, face[2] as usize],
117:                     if v >= dynamic_count || face.iter().any(|&i| i as usize >= dynamic_count) {
118:                         self.static_clearance
119:                     } else {
120:                         thickness
121:                     },
122:                     velocities.as_deref_mut(),
123:                 );
124:             }
125:         }
126:         if let Some(fixed) = &self.fixed_bounds {
127:             // Obstacle vertices matter only near cloth faces. Visit them from
128:             // the swept face bounds instead of querying every body vertex.
129:             let mut pairs = Vec::new();
130:             for (&f, face_bounds) in dynamic_faces.iter().zip(&dynamic_bounds) {
131:                 fixed
132:                     .vertices
133:                     .query(&face_bounds.expand(search_radius), |i| {
134:                         pairs.push((i + dynamic_count, f))
135:                     });
136:             }
137:             for (v, f) in pairs {
138:                 let face = self.faces[f];
139:                 contacts += resolve(
140:                     Pair::VertexTriangle,
141:                     positions,
142:                     previous,
143:                     inverse_masses,
144:                     [v, face[0] as usize, face[1] as usize, face[2] as usize],
145:                     self.static_clearance,
146:                     velocities.as_deref_mut(),
147:                 );
148:             }
149:         }
150:         contacts
151:     }
152: 
153:     fn edge_contacts(&self, state: &mut ContactState<'_>) -> usize {
154:         let thickness = state.thickness;
155:         let search_radius = thickness.max(self.static_clearance);
156:         let dynamic_count = state.positions.len() - self.static_positions.len();
157:         let positions = &mut *state.positions;
158:         let previous = state.previous;
159:         let inverse_masses = state.inverse_masses;
160:         let velocities = &mut state.velocities;
161:         let mut contacts = 0;
162:         let mut candidates = Vec::new();
163:         let edge_count = self
164:             .fixed_bounds
165:             .as_ref()
166:             .map_or(self.edges.len(), |b| b.edge_offset);
167:         let bounds: Vec<_> = self.edges[..edge_count]
168:             .iter()
169:             .map(|edge| {
170:                 Aabb::from_points(
171:                     edge.iter()
172:                         .flat_map(|&i| [positions[i as usize], previous[i as usize]]),
173:                 )
174:                 .expand(search_radius)
175:             })
176:             .collect();
177:         let tree = Bvh::build(&bounds);
178:         for (i, edge) in self.edges[..edge_count].iter().enumerate() {
179:             if edge
180:                 .iter()
181:                 .all(|&v| inverse_masses[v as usize].mobility() == ParticleMobility::Prescribed)
182:             {
183:                 continue;
184:             }
185:             candidates.clear();
186:             tree.query_aabb(&bounds, &bounds[i], |j| {
187:                 let j = j as usize;
188:                 if j > i
189:                     || self.edges[j].iter().all(|&v| {
190:                         inverse_masses[v as usize].mobility() == ParticleMobility::Prescribed
191:                     })
192:                 {
193:                     candidates.push(j);
194:                 }
195:             });
196:             if let Some(fixed) = &self.fixed_bounds {
197:                 fixed.edges.query(&bounds[i].expand(search_radius), |j| {
198:                     candidates.push(j + fixed.edge_offset)
199:                 });
200:             }
201:             for &j in &candidates {
202:                 let other = self.edges[j];
203:                 if edge.iter().any(|a| {
204:                     other
205:                         .iter()
206:                         .any(|b| a == b || self.seam_copies[*a as usize].contains(b))
207:                 }) {
208:                     continue;
209:                 }
210:                 contacts += resolve(
211:                     Pair::EdgeEdge,
212:                     positions,
213:                     previous,
214:                     inverse_masses,
215:                     [
216:                         edge[0] as usize,
217:                         edge[1] as usize,
218:                         other[0] as usize,
219:                         other[1] as usize,
220:                     ],
221:                     if edge
222:                         .iter()
223:                         .chain(other.iter())
224:                         .any(|&i| i as usize >= dynamic_count)
225:                     {
226:                         self.static_clearance
227:                     } else {
228:                         thickness
229:                     },
230:                     velocities.as_deref_mut(),
231:                 );
232:             }
233:         }
234:         contacts
235:     }
236: }
237: 
238: fn resolve(
239:     pair: Pair,
240:     positions: &mut [Vec3],
241:     previous: &[Vec3],
242:     masses: &[ParticleInverseMass],
243:     ids: [usize; 4],
244:     thickness: f32,
245:     velocities: Option<&mut [Vec3]>,
246: ) -> usize {
247:     let start = ids.map(|i| previous[i]);
248:     let end = ids.map(|i| positions[i]);
249:     // The CCD guard is inside the resting contact shell. This lets touching
250:     // cloth slide tangentially without returning time zero on every step.
251:     let contact = ccd::sweep(pair, start, end, thickness * 0.5)
252:         .unwrap_or_else(|| ccd::proximity(pair, end, start));
253:     debug_assert!((0.0..=1.0).contains(&contact.time));
254:     let separation = ids
255:         .iter()
256:         .zip(contact.weights)
257:         .fold(
258:             Vec3::default(),
259:             |sum: Vec3, (&i, w): (&usize, ConstraintGradient)| -> Vec3 {
260:                 sum + w.contribution(positions[i])
261:             },
262:         )
263:         .dot(contact.normal);
264:     let depth = ProjectionDepth::from(thickness - separation);
265:     if depth.activity() == ProjectionActivity::Inactive {
266:         return 0;
267:     }
268:     let denominator: EffectiveInverseMass = ids
269:         .iter()
270:         .zip(contact.weights)
271:         .map(
272:             |(&i, w): (&usize, ConstraintGradient)| -> EffectiveInverseMass {
273:                 w.inverse_response(masses[i])
274:             },
275:         )
276:         .sum();
277:     if denominator.contact_activity() == ProjectionActivity::Inactive {
278:         return 0;
279:     }
280:     if let Some(velocities) = velocities {
281:         let relative = RelativeNormalSpeed::from(
282:             ids.iter()
283:                 .zip(contact.weights)
284:                 .fold(
285:                     Vec3::default(),
286:                     |sum: Vec3, (&i, w): (&usize, ConstraintGradient)| -> Vec3 {
287:                         sum + w.contribution(velocities[i])
288:                     },
289:                 )
290:                 .dot(contact.normal),
291:         );
292:         if relative.activity() == ProjectionActivity::Active {
293:             for (i, w) in ids.into_iter().zip(contact.weights) {
294:                 velocities[i] -= relative
295:                     .contact_correction(w, masses[i], denominator)
296:                     .along(contact.normal);
297:             }
298:         }
299:     }
300:     for (i, w) in ids.into_iter().zip(contact.weights) {
301:         positions[i] += depth
302:             .contact_correction(w, masses[i], denominator)
303:             .along(contact.normal);
304:     }
305:     1
306: }
