1: //! The cloth-specific kernels: bending, and cloth against itself.
2: 
3: /// Quadratic (isometric) bending.
4: ///
5: /// The obvious constraint on a hinge is its dihedral angle, and it is the
6: /// wrong one for cloth: `acos` is singular exactly where its derivative is
7: /// needed most, and a flat hinge -- which is every hinge in a flat panel, at
8: /// rest -- sits precisely on that singularity. A garment built that way gets
9: /// no bending resistance at all until it has already creased.
10: ///
11: /// So this uses Bergou's quadratic model instead. For four points that are
12: /// coplanar at rest there is exactly one affine dependency between them:
13: /// weights `k` with `sum(k) = 0` and `sum(k_i * x_i) = 0`. That combination
14: /// stays zero under *any* affine deformation -- translation, rotation,
15: /// stretch, shear -- and becomes non-zero only when the patch stops being
16: /// flat. Which makes it a pure bending measure:
17: ///
18: /// ```text
19: /// s = sum(k_i * p_i)      C = |s| - rest      grad_i C = k_i * s / |s|
20: /// ```
21: ///
22: /// Linear in the positions, with full stiffness at the flat state and no
23: /// singularity anywhere the fabric actually goes. The weights are computed per
24: /// hinge when the garment is built, from the panel's own flat layout.
25: pub const BEND: &str = r#"
26: @group(0) @binding(1) var<storage, read_write> lambdas: array<f32>;
27: // Four particle indices per constraint.
28: @group(0) @binding(2) var<storage, read> particles: array<u32>;
29: // The four affine weights, and the rest value in the fifth slot. Non-zero rest
30: // lets a garment be built with a crease already in it.
31: @group(0) @binding(3) var<storage, read> weights: array<f32>;
32: @group(0) @binding(4) var<uniform> params: SolveParams;
33: 
34: @compute @workgroup_size(256)
35: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
36:     let local = global_id.x;
37:     if (local >= params.count) {
38:         return;
39:     }
40:     let constraint = params.first + local;
41: 
42:     let base = constraint * 8u;
43:     let k0 = weights[base];
44:     let k1 = weights[base + 1u];
45:     let k2 = weights[base + 2u];
46:     let k3 = weights[base + 3u];
47:     let rest = weights[base + 4u];
48: 
49:     let i0 = particles[constraint * 4u];
50:     let i1 = particles[constraint * 4u + 1u];
51:     let i2 = particles[constraint * 4u + 2u];
52:     let i3 = particles[constraint * 4u + 3u];
53: 
54:     let w0 = particle_inverse_mass(i0);
55:     let w1 = particle_inverse_mass(i1);
56:     let w2 = particle_inverse_mass(i2);
57:     let w3 = particle_inverse_mass(i3);
58: 
59:     let s = particle_position(i0) * k0
60:           + particle_position(i1) * k1
61:           + particle_position(i2) * k2
62:           + particle_position(i3) * k3;
63: 
64:     let magnitude = length(s);
65:     // Exactly flat is exactly at rest, so there is nothing to correct -- and
66:     // no direction to correct along either. Unlike the dihedral form, this is
67:     // a genuinely empty case rather than a singularity being dodged.
68:     if (magnitude < 1e-12) {
69:         return;
70:     }
71:     let normal = s / magnitude;
72: 
73:     // |grad_i C| is |k_i|, so the weighted denominator is a plain sum.
74:     let denominator = w0 * k0 * k0 + w1 * k1 * k1 + w2 * k2 * k2 + w3 * k3 * k3;
75:     let alpha_tilde = xpbd_alpha_tilde(params.compliance, params.substep);
76:     let solved = xpbd_solve(magnitude - rest, denominator, lambdas[constraint], alpha_tilde);
77:     if (!solved.valid) {
78:         return;
79:     }
80: 
81:     lambdas[constraint] = lambdas[constraint] + solved.delta_lambda;
82:     particle_move(i0, normal * (w0 * k0 * solved.delta_lambda));
83:     particle_move(i1, normal * (w1 * k1 * solved.delta_lambda));
84:     particle_move(i2, normal * (w2 * k2 * solved.delta_lambda));
85:     particle_move(i3, normal * (w3 * k3 * solved.delta_lambda));
86: }
87: "#;
88: 
89: // ----- self-collision -----
90: //
91: // A uniform grid rather than a hierarchy. Cloth particles are all the same
92: // size and roughly evenly spread, which is exactly the case a grid is best at
93: // and a BVH is worst at -- and the grid is rebuilt from scratch every substep
94: // for the cost of a sort.
