1: //! A coloured set of constraints, and the buffers behind it.
2: //!
3: //! Anything the solver sweeps over is one of these: a fabric's stretch, its
4: //! bending, the seams joining two panels, a set of tethers. What differs
5: //! between them is the kernel and the per-constraint data; what is the same is
6: //! the colouring, the Lagrange multipliers, and the dispatch per colour.
7: 
8: use fabelgeist_gpu::prelude::{BufferUpload, BufferUse};
9: use std::sync::Arc;
10: 
11: use anyhow::anyhow;
12: use fabelgeist_compute::prelude::*;
13: use fabelgeist_gpu::prelude::*;
14: 
15: use crate::coloring::{ColorCount, Coloring};
16: use crate::particles::Particles;
17: use crate::wgsl;
18: use crate::{ConstraintArity, ConstraintEdges, ConstraintIncidence};
19: pub use address::{ConstraintCount, ConstraintIndex};
20: 
21: mod address;
22: 
23: /// Extra per-constraint buffers a kernel wants, bound by name.
24: ///
25: /// Distance constraints pass their rest lengths here; a bending constraint
26: /// passes its rest angles. The set reorders them into colour order for you --
27: /// see [`ConstraintSet::reorder`].
28: pub type Attachments = Vec<(String, Buffer)>;
29: 
30: /// One constraint kernel, its constraints in colour order, and its
31: /// multipliers.
32: pub struct ConstraintSet {
33:     pub name: String,
34:     kernel: Arc<Kernel>,
35:     clear: Arc<Kernel>,
36: 
37:     /// Particle indices, `arity` per constraint, in colour order.
38:     pub particles: Buffer,
39:     /// One Lagrange multiplier per constraint.
40:     pub lambdas: Buffer,
41:     /// Whatever else the kernel binds, already in colour order.
42:     pub attachments: Attachments,
43: 
44:     coloring: Coloring,
45:     arity: ConstraintArity,
46:     /// The XPBD compliance: the inverse of stiffness, in metres per newton.
47:     /// Zero is infinitely stiff.
48:     pub compliance: f32,
49:     /// Skip this set without tearing it down.
50:     pub enabled: bool,
51: }
52: 
53: impl ConstraintSet {
54:     /// Build from constraints in any order; they are coloured and reordered
55:     /// here.
56:     ///
57:     /// `incidence` contains complete particle-address records. Every attachment
58:     /// must have one value per constraint, in the same original order, and is
59:     /// permuted to match.
60:     pub fn new(
61:         context: &WgpuContext,
62:         name: impl Into<String>,
63:         kernel: Arc<Kernel>,
64:         cache: &KernelCache,
65:         incidence: &ConstraintIncidence<'_>,
66:         compliance: f32,
67:     ) -> Result<Self> {
68:         let coloring = Coloring::for_incidence(incidence);
69:         let count = coloring.constraint_count();
70:         let particle_buffer = incidence.upload_ordered(context, &coloring)?;
71:         let storage = BufferDefinition::storage();
72:         let lambdas = Buffer::new(
73:             context,
74:             count.lambda_bytes(),
75:             storage
76:                 .with_usage(BufferUse::CopySource)
77:                 .with_label(("constraint lambdas").into()),
78:         )?;
79: 
80:         Ok(Self {
81:             name: name.into(),
82:             kernel,
83:             clear: cache.get(context, wgsl::CLEAR_LAMBDAS)?,
84:             particles: particle_buffer,
85:             lambdas,
86:             attachments: Vec::new(),
87:             coloring,
88:             arity: incidence.arity(),
89:             compliance,
90:             enabled: true,
91:         })
92:     }
93: 
94:     /// A set of distance constraints -- the common case.
95:     pub fn distance(
96:         context: &WgpuContext,
97:         cache: &KernelCache,
98:         name: impl Into<String>,
99:         edges: &ConstraintEdges,
100:         rest_lengths: &[f32],
101:         compliance: f32,
102:     ) -> Result<Self> {
103:         if edges.count() != ConstraintCount::from(rest_lengths.len()) {
104:             return Err(anyhow!(
105:                 "ConstraintSet::distance: {} edges but {} rest lengths",
106:                 edges.count(),
107:                 rest_lengths.len()
108:             ));
109:         }
110:         let incidence = edges.incidence();
111:         let kernel = cache.get(context, &wgsl::constraint_kernel(wgsl::DISTANCE))?;
112:         let mut set = Self::new(context, name, kernel, cache, &incidence, compliance)?;
113:         let reordered = set.reorder(rest_lengths);
114:         set.attach(context, "rest_lengths", &reordered)?;
115:         Ok(set)
116:     }
117: 
118:     /// A set of compliant spring constraints with bump stops and damping.
119:     pub fn spring(
120:         context: &WgpuContext,
121:         cache: &KernelCache,
122:         name: impl Into<String>,
123:         edges: &ConstraintEdges,
124:         rest_lengths: &[f32],
125:         spring_params: &[[f32; 4]],
126:         compliance: f32,
127:     ) -> Result<Self> {
128:         if edges.count() != ConstraintCount::from(rest_lengths.len())
129:             || edges.count() != ConstraintCount::from(spring_params.len())
130:         {
131:             return Err(anyhow!(
132:                 "ConstraintSet::spring: {} edges, {} rest lengths, {} spring params",
133:                 edges.count(),
134:                 rest_lengths.len(),
135:                 spring_params.len()
136:             ));
137:         }
138:         let incidence = edges.incidence();
139:         let kernel = cache.get(context, &wgsl::constraint_kernel(wgsl::SPRING))?;
140:         let mut set = Self::new(context, name, kernel, cache, &incidence, compliance)?;
141:         let reordered_rest = set.reorder(rest_lengths);
142:         set.attach(context, "rest_lengths", &reordered_rest)?;
143:         let reordered_params = set.reorder(spring_params);
144:         set.attach(context, "spring_params", &reordered_params)?;
145:         Ok(set)
146:     }
147: 
148:     /// Permute per-constraint values from the caller's order into colour
149:     /// order.
150:     ///
151:     /// Every attachment has to go through this, or a constraint reads another
152:     /// constraint's rest length -- which produces cloth that looks nearly
153:     /// right and is completely wrong.
154:     pub fn reorder<T: Copy>(&self, values: &[T]) -> Vec<T> {
155:         self.coloring
156:             .order()
157:             .iter()
158:             .map(|&index| values[usize::from(index)])
159:             .collect()
160:     }
161: 
162:     /// Bind a per-constraint buffer under the name the kernel declares. The
163:     /// values must already be in colour order -- see [`ConstraintSet::reorder`].
164:     pub fn attach<T: bytemuck::NoUninit>(
165:         &mut self,
166:         context: &WgpuContext,
167:         name: impl Into<String>,
168:         values: &[T],
169:     ) -> Result<()> {
170:         let name = name.into();
171:         if ConstraintCount::from(values.len()) != self.constraint_count() {
172:             return Err(anyhow!(
173:                 "ConstraintSet `{}`: attachment `{name}` has {} values for {} constraints",
174:                 self.name,
175:                 values.len(),
176:                 self.constraint_count()
177:             ));
178:         }
179:         let definition = BufferDefinition::storage().with_label(name.as_str().into());
180:         // A zero-length buffer cannot be allocated, and an empty constraint
181:         // set is perfectly ordinary -- a garment with no seams, say -- so it
182:         // gets one unused slot instead. Nothing ever dispatches over it.
183:         let buffer = if values.is_empty() {
184:             Buffer::from_upload(context, BufferUpload::from_elements(&[0u32]), definition)?
185:         } else {
186:             Buffer::from_upload(context, BufferUpload::from_elements(values), definition)?
187:         };
188:         self.attachments.retain(|(existing, _)| existing != &name);
189:         self.attachments.push((name, buffer));
190:         Ok(())
191:     }
192: 
193:     /// Bind a buffer whose length is a multiple of the constraint count --
194:     /// several values per constraint, already in colour order.
195:     pub fn attach_raw<T: bytemuck::NoUninit>(
196:         &mut self,
197:         context: &WgpuContext,
198:         name: impl Into<String>,
199:         values: &[T],
200:     ) -> Result<()> {
201:         let name = name.into();
202:         let count = self.constraint_count();
203:         if !count.is_empty() && !values.len().is_multiple_of(usize::from(count)) {
204:             return Err(anyhow!(
205:                 "ConstraintSet `{}`: attachment `{name}` has {} values, which is not a whole number per constraint ({count})",
206:                 self.name,
207:                 values.len()
208:             ));
209:         }
210:         let definition = BufferDefinition::storage().with_label(name.as_str().into());
211:         let buffer = if values.is_empty() {
212:             Buffer::from_upload(context, BufferUpload::from_elements(&[0u32]), definition)?
213:         } else {
214:             Buffer::from_upload(context, BufferUpload::from_elements(values), definition)?
215:         };
216:         self.attachments.retain(|(existing, _)| existing != &name);
217:         self.attachments.push((name, buffer));
218:         Ok(())
219:     }
220: 
221:     pub fn constraint_count(&self) -> ConstraintCount {
222:         self.coloring.constraint_count()
223:     }
224: 
225:     pub fn color_count(&self) -> ColorCount {
226:         self.coloring.color_count()
227:     }
228: 
229:     pub fn arity(&self) -> ConstraintArity {
230:         self.arity
231:     }
232: 
233:     pub fn coloring(&self) -> &Coloring {
234:         &self.coloring
235:     }
236: 
237:     /// Reset the multipliers. Once per substep, before the sweeps: XPBD's
238:     /// compliance only means a real stiffness if `lambda` starts each substep
239:     /// at zero.
240:     pub fn record_clear(&self, batch: &mut KernelBatch) -> Result<()> {
241:         if !self.enabled || self.constraint_count().is_empty() {
242:             return Ok(());
243:         }
244:         let mut parameters = PassParameters::new();
245:         parameters.insert("lambdas", self.lambdas.clone());
246:         parameters.insert("count", self.constraint_count().uniform());
247:         parameters.insert("pad0", 0u32);
248:         parameters.insert("pad1", 0u32);
249:         parameters.insert("pad2", 0u32);
250:         batch.dispatch_items(
251:             &self.clear,
252:             &parameters,
253:             self.constraint_count().dispatch_items(),
254:         )?;
255:         Ok(())
256:     }
257: 
258:     /// One Gauss-Seidel sweep: one dispatch per colour, in order.
259:     pub fn record_solve(
260:         &self,
261:         batch: &mut KernelBatch,
262:         particles: &Particles,
263:         substep: f32,
264:     ) -> Result<()> {
265:         if !self.enabled || self.constraint_count().is_empty() {
266:             return Ok(());
267:         }
268: 
269:         for range in self.coloring.colors() {
270:             if range.count().is_empty() {
271:                 continue;
272:             }
273: 
274:             let mut parameters = PassParameters::new();
275:             parameters.insert("positions", particles.positions.clone());
276:             parameters.insert("lambdas", self.lambdas.clone());
277:             parameters.insert("particles", self.particles.clone());
278:             for (name, buffer) in &self.attachments {
279:                 parameters.insert(name.clone(), buffer.clone());
280:             }
281:             range.bind(&mut parameters);
282:             parameters.insert("compliance", self.compliance);
283:             parameters.insert("substep", substep);
284: 
285:             batch.dispatch_items(&self.kernel, &parameters, range.dispatch_items())?;
286:         }
287:         Ok(())
288:     }
289: }
