1: //! The substep loop.
2: //!
3: //! Extended position-based dynamics, in the small-substeps form Macklin et al.
4: //! settled on: rather than iterating a constraint solve many times inside one
5: //! large step, take many small substeps and solve once in each. It converges
6: //! better for the same total work, and it is what makes a stiff fabric behave
7: //! at a frame rate a garment fit can be watched at.
8: //!
9: //! Per substep:
10: //!
11: //! 1. **predict** -- integrate gravity and damping, remember where each
12: //!    particle was, move it where its velocity wants to go.
13: //! 2. *(the caller's hook)* -- collisions go here, as positional constraints
14: //!    like any other. See `fabelgeist-physics`.
15: //! 3. **solve** -- one Gauss-Seidel sweep over the constraint colours.
16: //! 4. **finalize** -- read velocity back out of the total position change, so
17: //!    that every correction made in 2 and 3 shows up in the velocity for free.
18: 
19: use std::sync::Arc;
20: 
21: use fabelgeist_compute::prelude::*;
22: use fabelgeist_gpu::prelude::*;
23: use fabelgeist_math::Vec3;
24: 
25: use crate::constraint::ConstraintSet;
26: use crate::particles::Particles;
27: use crate::wgsl;
28: 
29: /// How the substep loop is driven.
30: #[derive(Clone, Copy, Debug)]
31: pub struct SolverSettings {
32:     /// Substeps per call to [`Solver::step`]. More is stiffer and steadier;
33:     /// the cost is linear.
34:     pub substeps: u32,
35:     /// Constraint sweeps within each substep. XPBD wants one; more helps a
36:     /// badly conditioned set converge, at the price of the compliance meaning
37:     /// slightly less than it says.
38:     pub iterations: u32,
39:     pub gravity: Vec3,
40:     /// Exponential velocity drag, per second. Independent of the substep
41:     /// count, so changing `substeps` does not change how draggy the cloth is.
42:     pub damping: f32,
43:     /// Ceiling on particle speed. It only ever binds when something has
44:     /// already gone wrong, and it is what turns a blown-up frame into a
45:     /// recoverable one rather than a garment flung off the screen.
46:     pub max_speed: f32,
47: }
48: 
49: impl Default for SolverSettings {
50:     fn default() -> Self {
51:         Self {
52:             substeps: 10,
53:             iterations: 1,
54:             // Metres per second squared, and the rest of the stack is in
55:             // metres, so a garment in centimetres has to be scaled on the way
56:             // in.
57:             gravity: Vec3::new(0.0, -9.81, 0.0),
58:             damping: 0.1,
59:             max_speed: 20.0,
60:         }
61:     }
62: }
63: 
64: /// Anything that wants to run between the prediction and the constraint solve
65: /// of every substep -- which is where collision response belongs.
66: ///
67: /// It sees the substep length because a positional correction has to know it
68: /// to turn into the right velocity change, and friction depends on it.
69: pub trait SubstepHook {
70:     fn record(
71:         &mut self,
72:         batch: &mut KernelBatch,
73:         particles: &Particles,
74:         substep: f32,
75:     ) -> Result<()>;
76: 
77:     fn after_solve(
78:         &mut self,
79:         _batch: &mut KernelBatch,
80:         _particles: &Particles,
81:         _substep: f32,
82:     ) -> Result<()> {
83:         Ok(())
84:     }
85: }
86: 
87: impl SubstepHook for () {
88:     fn record(
89:         &mut self,
90:         _batch: &mut KernelBatch,
91:         _particles: &Particles,
92:         _substep: f32,
93:     ) -> Result<()> {
94:         Ok(())
95:     }
96: }
97: 
98: impl<F> SubstepHook for F
99: where
100:     F: FnMut(&mut KernelBatch, &Particles, f32) -> Result<()>,
101: {
102:     fn record(
103:         &mut self,
104:         batch: &mut KernelBatch,
105:         particles: &Particles,
106:         substep: f32,
107:     ) -> Result<()> {
108:         self(batch, particles, substep)
109:     }
110: }
111: 
112: /// The predict/finalize pair, and the loop that drives them.
113: pub struct Solver {
114:     predict: Arc<Kernel>,
115:     finalize: Arc<Kernel>,
116:     pub settings: SolverSettings,
117: }
118: 
119: impl Solver {
120:     pub fn new(context: &WgpuContext, settings: SolverSettings) -> Result<Self> {
121:         Self::with_cache(context, &KernelCache::new(), settings)
122:     }
123: 
124:     pub fn with_cache(
125:         context: &WgpuContext,
126:         cache: &KernelCache,
127:         settings: SolverSettings,
128:     ) -> Result<Self> {
129:         Ok(Self {
130:             predict: cache.get(context, wgsl::PREDICT)?,
131:             finalize: cache.get(context, wgsl::FINALIZE)?,
132:             settings,
133:         })
134:     }
135: 
136:     /// Record one full step: `settings.substeps` substeps of `delta / substeps`.
137:     pub fn record_step(
138:         &self,
139:         batch: &mut KernelBatch,
140:         particles: &Particles,
141:         constraints: &mut [&mut ConstraintSet],
142:         hook: &mut impl SubstepHook,
143:         delta: f32,
144:     ) -> Result<()> {
145:         let count = particles.count();
146:         if count == 0 || delta <= 0.0 || self.settings.substeps == 0 {
147:             return Ok(());
148:         }
149:         let substep = delta / self.settings.substeps as f32;
150: 
151:         for _ in 0..self.settings.substeps {
152:             self.record_substep(batch, particles, constraints, hook, substep)?;
153:         }
154:         Ok(())
155:     }
156: 
157:     /// One substep, into the given batch.
158:     pub fn record_substep(
159:         &self,
160:         batch: &mut KernelBatch,
161:         particles: &Particles,
162:         constraints: &mut [&mut ConstraintSet],
163:         hook: &mut impl SubstepHook,
164:         substep: f32,
165:     ) -> Result<()> {
166:         self.record_predict(batch, particles, substep)?;
167: 
168:         // Collisions are positional constraints too, and they belong before
169:         // the material ones: the cloth should be told where it may not be
170:         // before it is asked to hold its shape there.
171:         hook.record(batch, particles, substep)?;
172: 
173:         for set in constraints.iter_mut() {
174:             set.record_clear(batch)?;
175:         }
176:         for _ in 0..self.settings.iterations.max(1) {
177:             for set in constraints.iter_mut() {
178:                 set.record_solve(batch, particles, substep)?;
179:             }
180:         }
181: 
182:         hook.after_solve(batch, particles, substep)?;
183:         self.record_finalize(batch, particles, substep)
184:     }
185: 
186:     /// Step with one submission **per substep** rather than one for the whole
187:     /// step.
188:     ///
189:     /// The total work is identical; what changes is how it reaches the device.
190:     /// A whole step is several hundred dispatches, and submitted together they
191:     /// occupy the GPU for as long as they take -- tens of milliseconds for a
192:     /// garment. Anything else sharing that device gets nothing in the
193:     /// meantime, and a compositor that cannot acquire a swapchain image in
194:     /// time drops the frame or gives up on the window.
195:     ///
196:     /// Submitting each substep separately gives the scheduler a dozen places
197:     /// to fit other work. Use this whenever the solver shares a device with a
198:     /// renderer; `step` is for a device the solver has to itself.
199:     pub fn step_interleaved(
200:         &self,
201:         context: &WgpuContext,
202:         particles: &Particles,
203:         constraints: &mut [&mut ConstraintSet],
204:         hook: &mut impl SubstepHook,
205:         delta: f32,
206:     ) -> Result<()> {
207:         let count = particles.count();
208:         if count == 0 || delta <= 0.0 || self.settings.substeps == 0 {
209:             return Ok(());
210:         }
211:         let substep = delta / self.settings.substeps as f32;
212: 
213:         for _ in 0..self.settings.substeps {
214:             let mut batch = KernelBatch::labelled(context, "xpbd substep");
215:             self.record_substep(&mut batch, particles, constraints, hook, substep)?;
216:             batch.submit();
217:         }
218:         Ok(())
219:     }
220: 
221:     /// Step on a batch of its own and submit.
222:     pub fn step(
223:         &self,
224:         context: &WgpuContext,
225:         particles: &Particles,
226:         constraints: &mut [&mut ConstraintSet],
227:         hook: &mut impl SubstepHook,
228:         delta: f32,
229:     ) -> Result<()> {
230:         let mut batch = KernelBatch::labelled(context, "xpbd step");
231:         self.record_step(&mut batch, particles, constraints, hook, delta)?;
232:         batch.submit();
233:         Ok(())
234:     }
235: 
236:     fn record_predict(
237:         &self,
238:         batch: &mut KernelBatch,
239:         particles: &Particles,
240:         substep: f32,
241:     ) -> Result<()> {
242:         let mut parameters = PassParameters::new();
243:         parameters.insert("positions", particles.positions.clone());
244:         parameters.insert("previous", particles.previous.clone());
245:         parameters.insert("velocities", particles.velocities.clone());
246:         parameters.insert(
247:             "gravity",
248:             fabelgeist_math::Vec4::new(
249:                 self.settings.gravity.x,
250:                 self.settings.gravity.y,
251:                 self.settings.gravity.z,
252:                 0.0,
253:             ),
254:         );
255:         parameters.insert("substep", substep);
256:         parameters.insert("damping", self.settings.damping);
257:         parameters.insert("count", particles.count());
258:         parameters.insert("max_speed", self.settings.max_speed);
259:         batch.dispatch_items(&self.predict, &parameters, particles.count())?;
260:         Ok(())
261:     }
262: 
263:     fn record_finalize(
264:         &self,
265:         batch: &mut KernelBatch,
266:         particles: &Particles,
267:         substep: f32,
268:     ) -> Result<()> {
269:         let mut parameters = PassParameters::new();
270:         parameters.insert("positions", particles.positions.clone());
271:         parameters.insert("previous", particles.previous.clone());
272:         parameters.insert("velocities", particles.velocities.clone());
273:         parameters.insert("substep", substep);
274:         parameters.insert("count", particles.count());
275:         parameters.insert("pad0", 0u32);
276:         parameters.insert("pad1", 0u32);
277:         batch.dispatch_items(&self.finalize, &parameters, particles.count())?;
278:         Ok(())
279:     }
280: }

