28: "#;
29: 
30: /// The XPBD update itself.
31: ///
32: /// For a constraint `C` with compliance `alpha`, over a substep of `h`:
33: ///
34: /// ```text
35: /// alpha_tilde = alpha / h^2
36: /// d_lambda    = (-C - alpha_tilde * lambda) / (sum_i w_i |grad_i C|^2 + alpha_tilde)
37: /// dx_i        = w_i * grad_i C * d_lambda
38: /// ```
39: ///
40: /// The compliance term is what makes this XPBD rather than PBD: stiffness
41: /// stops depending on the iteration count and the timestep, so a fabric keeps
42: /// the same feel whatever the solver settings are. `alpha = 0` is the
43: /// infinitely stiff limit and reduces to plain PBD.
44: pub const SOLVE: &str = r#"
45: struct XpbdSolve {
46:     delta_lambda: f32,
47:     valid: bool,
48: };
49: 
50: // `gradient_norm_squared` is `sum_i w_i |grad_i C|^2` -- the weighted
51: // denominator, gathered by the caller because only it knows the arity.
52: fn xpbd_solve(
53:     value: f32,
54:     gradient_norm_squared: f32,
55:     lambda: f32,
56:     alpha_tilde: f32,
57: ) -> XpbdSolve {
58:     let denominator = gradient_norm_squared + alpha_tilde;
59:     // Every particle pinned, or a gradient that vanished: there is no
60:     // correction to make, and dividing would produce one out of nothing.
61:     if (denominator < 1e-12) {
62:         return XpbdSolve(0.0, false);
63:     }
64:     return XpbdSolve((-value - alpha_tilde * lambda) / denominator, true);
65: }
66: 
67: fn xpbd_alpha_tilde(compliance: f32, substep: f32) -> f32 {
68:     return compliance / (substep * substep);
69: }
70: "#;
71: 
72: /// The uniform block every constraint kernel takes.
73: ///
74: /// `first` and `count` bound the colour being solved: constraints are stored
75: /// sorted by colour, so a colour is a contiguous range and a dispatch is just
76: /// an offset and a length.
77: pub const PARAMS: &str = r#"
78: struct SolveParams {
79:     first: u32,
80:     count: u32,
81:     compliance: f32,
82:     substep: f32,
83: };
84: "#;
85: 
86: /// Integrate forces and predict where each particle wants to be.
87: ///
88: /// The previous position is kept because XPBD reads velocity back out of the
89: /// position change at the end of the substep -- which is what makes every
90: /// positional correction, including a collision response, show up in the
91: /// velocity for free.
92: pub const PREDICT: &str = r#"
93: @group(0) @binding(0) var<storage, read_write> positions: array<vec4<f32>>;
94: @group(0) @binding(1) var<storage, read_write> previous: array<vec4<f32>>;
95: @group(0) @binding(2) var<storage, read_write> velocities: array<vec4<f32>>;
96: 
97: struct PredictParams {
98:     gravity: vec4<f32>,
99:     substep: f32,
100:     damping: f32,
101:     count: u32,
102:     max_speed: f32,
103: };
104: @group(0) @binding(3) var<uniform> params: PredictParams;
105: 
106: @compute @workgroup_size(256)
107: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
108:     let index = global_id.x;
109:     if (index >= params.count) {
110:         return;
111:     }
112: 
113:     let current = positions[index];
114:     let inverse_mass = current.w;
115:     previous[index] = vec4<f32>(current.xyz, inverse_mass);
116: 
117:     if (inverse_mass == 0.0) {
118:         velocities[index] = vec4<f32>(0.0, 0.0, 0.0, 0.0);
119:         return;
120:     }
121: 
122:     var velocity = velocities[index].xyz;
123:     velocity = velocity + params.gravity.xyz * params.substep;
124:     // Exponential drag rather than a per-step multiplier, so the amount of
125:     // damping does not change when the substep count does.
126:     velocity = velocity * exp(-params.damping * params.substep);
127: 
128:     // A speed cap is the difference between a solver that recovers from a bad
129:     // frame and one that throws the cloth off the screen. It only ever binds
130:     // when something has already gone wrong.
131:     let speed = length(velocity);
132:     if (speed > params.max_speed && speed > 0.0) {
133:         velocity = velocity * (params.max_speed / speed);
134:     }
135: 
136:     velocities[index] = vec4<f32>(velocity, 0.0);
137:     positions[index] = vec4<f32>(current.xyz + velocity * params.substep, inverse_mass);
