141: /// Read velocity back out of the substep's total position change.
142: pub const FINALIZE: &str = r#"
143: @group(0) @binding(0) var<storage, read> positions: array<vec4<f32>>;
144: @group(0) @binding(1) var<storage, read> previous: array<vec4<f32>>;
145: @group(0) @binding(2) var<storage, read_write> velocities: array<vec4<f32>>;
