147: struct FinalizeParams {
148:     substep: f32,
149:     count: u32,
150:     pad0: u32,
151:     pad1: u32,
152: };
153: @group(0) @binding(3) var<uniform> params: FinalizeParams;
154: 
155: @compute @workgroup_size(256)
156: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
157:     let index = global_id.x;
158:     if (index >= params.count) {
159:         return;
160:     }
161:     if (positions[index].w == 0.0) {
162:         velocities[index] = vec4<f32>(0.0, 0.0, 0.0, 0.0);
163:         return;
164:     }
165:     let delta = positions[index].xyz - previous[index].xyz;
166:     velocities[index] = vec4<f32>(delta / params.substep, 0.0);
167: }
168: "#;
169: 
170: /// Distance constraints: the workhorse. Cloth stretch, seams and tethers are
171: /// all this kernel with different rest lengths and compliances.
172: pub const DISTANCE: &str = r#"
173: @group(0) @binding(1) var<storage, read_write> lambdas: array<f32>;
174: // Two particle indices per constraint.
175: @group(0) @binding(2) var<storage, read> particles: array<u32>;
176: @group(0) @binding(3) var<storage, read> rest_lengths: array<f32>;
177: @group(0) @binding(4) var<uniform> params: SolveParams;
178: 
179: @compute @workgroup_size(256)
180: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
181:     let local = global_id.x;
182:     if (local >= params.count) {
183:         return;
184:     }
185:     let constraint = params.first + local;
186: 
187:     let a = particles[constraint * 2u];
188:     let b = particles[constraint * 2u + 1u];
189:     let inverse_mass_a = particle_inverse_mass(a);
190:     let inverse_mass_b = particle_inverse_mass(b);
191: 
192:     let delta = particle_position(a) - particle_position(b);
193:     let distance = length(delta);
194:     // Two coincident particles have no direction to separate along. Leaving
195:     // them alone lets the next substep, when something else has nudged them
196:     // apart, do the work.
197:     if (distance < 1e-9) {
198:         return;
199:     }
200: 
201:     let normal = delta / distance;
202:     let value = distance - rest_lengths[constraint];
203:     // |grad| is 1 for both particles, so the weighted denominator is just the
204:     // sum of the inverse masses.
205:     let alpha_tilde = xpbd_alpha_tilde(params.compliance, params.substep);
206:     let solved = xpbd_solve(value, inverse_mass_a + inverse_mass_b, lambdas[constraint], alpha_tilde);
207:     if (!solved.valid) {
208:         return;
209:     }
210: 
211:     lambdas[constraint] = lambdas[constraint] + solved.delta_lambda;
212:     particle_move(a, normal * (inverse_mass_a * solved.delta_lambda));
213:     particle_move(b, normal * (-inverse_mass_b * solved.delta_lambda));
214: }
215: "#;
216: 
217: /// Spring constraints with viscous damping and compression/rebound bump stops.
218: pub const SPRING: &str = r#"
219: @group(0) @binding(1) var<storage, read_write> lambdas: array<f32>;
220: // Two particle indices per constraint.
221: @group(0) @binding(2) var<storage, read> particles: array<u32>;
222: @group(0) @binding(3) var<storage, read> rest_lengths: array<f32>;
223: // xy = travel ratios (min_ratio, max_ratio), z = damping, w = bump factor
224: @group(0) @binding(4) var<storage, read> spring_params: array<vec4<f32>>;
225: @group(0) @binding(5) var<uniform> params: SolveParams;
226: 
227: @compute @workgroup_size(256)
228: fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
229:     let local = global_id.x;
230:     if (local >= params.count) {
231:         return;
232:     }
233:     let constraint = params.first + local;
234: 
235:     let a = particles[constraint * 2u];
236:     let b = particles[constraint * 2u + 1u];
237:     let inverse_mass_a = particle_inverse_mass(a);
238:     let inverse_mass_b = particle_inverse_mass(b);
239: 
240:     let delta = particle_position(a) - particle_position(b);
241:     let distance = length(delta);
242:     if (distance < 1e-9) {
243:         return;
244:     }
245: 
246:     let normal = delta / distance;
247:     let rest = rest_lengths[constraint];
248:     let sparams = spring_params[constraint];
249:     let min_limit = rest * sparams.x;
250:     let max_limit = rest * sparams.y;
251:     let bump_factor = max(sparams.w, 1.0);
252: 
253:     var compliance = params.compliance;
254:     if (distance < min_limit || distance > max_limit) {
255:         compliance = compliance / bump_factor;
256:     }
257: 
258:     let value = distance - rest;
259:     let alpha_tilde = xpbd_alpha_tilde(compliance, params.substep);
260:     let solved = xpbd_solve(value, inverse_mass_a + inverse_mass_b, lambdas[constraint], alpha_tilde);
261:     if (!solved.valid) {
262:         return;
263:     }
264: 
265:     lambdas[constraint] = lambdas[constraint] + solved.delta_lambda;
266:     particle_move(a, normal * (inverse_mass_a * solved.delta_lambda));
267:     particle_move(b, normal * (-inverse_mass_b * solved.delta_lambda));
268: }
