80: /// Encode a single path or query component, never a complete URL.
81: pub fn encode_component(value: &str) -> String {
82:     use fmt::Write;
83:     let mut encoded = String::new();
84:     for byte in value.bytes() {
85:         if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
86:             encoded.push(char::from(byte));
87:         } else {
88:             write!(encoded, "%{byte:02X}").expect("writing to a string");
89:         }
90:     }
91:     encoded
92: }
93: 
94: /// Append a query value before any fragment, preserving the rest of the URL.
95: pub fn with_query(path: &str, name: &str, value: &str) -> String {
96:     let (base, fragment) = path.split_once('#').unwrap_or((path, ""));
97:     let separator = if base.contains('?') { '&' } else { '?' };
98:     let mut result = format!(
99:         "{base}{separator}{}={}",
100:         encode_component(name),
101:         encode_component(value)
102:     );
103:     if path.contains('#') {
104:         result.push('#');
105:         result.push_str(fragment);
106:     }
107:     result
108: }
