226: fn typical_disease_effects(public_disease_key: &str) -> Vec<String> {
227:     let Ok(disease_id) = public_disease_key.parse::<DiseaseId>() else {
228:         return Vec::new();
229:     };
230:     let elemental = elemental_association(disease_id).map(|association| {
231:         format!(
232:             "Paracelsian association: {} {} / {}",
233:             association.element.as_str(),
234:             association.kind.as_str(),
235:             association.projected_humour.public_name()
236:         )
237:     });
238:     let mut focal_effects = [[0.0_f32; 4]; 7];
239:     let mut whole_body_effects = [0.0_f32; 4];
240:     for symptom in definition(disease_id).symptoms {
241:         let regions = symptom.observation_regions();
242:         // Broad visible findings should read as a systemic signature rather
243:         // than seven arbitrary limb entries. The observer still sees only the
244:         // public disease definition, never the patient's infection state.
245:         if regions.len() >= 4 {
246:             whole_body_effects[symptom.humour().index()] += symptom.humour_deviation();
247:         } else {
248:             for region in regions {
249:                 focal_effects[region.index()][symptom.humour().index()] +=
250:                     symptom.humour_deviation();
251:             }
252:         }
253:     }
254: 
255:     let mut ranked = BodyRegion::ALL
256:         .into_iter()
257:         .flat_map(|region| {
258:             Humour::ALL.into_iter().filter_map(move |humour| {
259:                 let weight = focal_effects[region.index()][humour.index()];
260:                 (weight > 0.0).then_some((weight, Some(region), humour))
261:             })
262:         })
263:         .collect::<Vec<_>>();
264:     ranked.extend(Humour::ALL.into_iter().filter_map(|humour| {
265:         let weight = whole_body_effects[humour.index()];
266:         (weight > 0.0).then_some((weight, None, humour))
267:     }));
268:     ranked.sort_by(|a, b| {
269:         b.0.total_cmp(&a.0)
270:             .then_with(|| a.1.is_none().cmp(&b.1.is_none()))
271:             .then_with(|| {
272:                 a.1.map_or(usize::MAX, BodyRegion::index)
273:                     .cmp(&b.1.map_or(usize::MAX, BodyRegion::index))
274:             })
275:             .then_with(|| a.2.index().cmp(&b.2.index()))
276:     });
277:     let mut result = elemental.into_iter().collect::<Vec<_>>();
278:     result.extend(ranked.into_iter().take(5).map(|(_, region, humour)| {
279:         let region = match region {
280:             Some(BodyRegion::LeftArm) => "left arm",

