20: /// Mutable Character columns have no effective-dated history yet. They are
21: /// safe to use cross-character only when the subject has not advanced beyond
22: /// the observer. Callers that need co-location or another shared-current fact
23: /// should additionally require equal frontiers.
24: pub(crate) async fn character_not_ahead_of_observer(
25:     state: &AppState,
26:     character_id: u64,
27:     observer_character_id: u64,
28: ) -> Result<bool> {
29:     if character_id == observer_character_id {
30:         return Ok(true);
31:     }
32:     let (subject, observer) = tokio::join!(
33:         character_minute(state, character_id),
34:         character_minute(state, observer_character_id),
35:     );
36:     Ok(matches!((subject?, observer?), (Some(subject), Some(observer)) if subject <= observer))
37: }
