55: pub(crate) async fn character(
56:     state: &AppState,
57:     character_id: u64,
58: ) -> Result<Option<CharacterView>> {
59:     let case_site_sql =
60:         crate::spacetimedb::character_case_site_location_by_character_id(character_id);
61:     // Character is a public mutable projection and is served from the SDK
62:     // cache once its explicit subscription is complete. The case-site view is
63:     // intentionally kept on HTTP SQL: owner-scoped/private projections are
64:     // never treated as an authorization boundary by the shared cache.
65:     let cached_character = state.live.cached_character(character_id);
66:     let mut character = match cached_character {
67:         Some(character) => Ok(prefer_complete_cache(Some(character), None)),
68:         None => {
69:             state
70:                 .db
71:                 .query_one_sats_into::<adventuresim_stdb_client::Character, CharacterView>(
72:                     &crate::spacetimedb::character_by_id(character_id),
73:                 )
74:                 .await
75:         }
76:     }?;
77:     let case_site = state
78:         .db
79:         .query_one_sats::<BackendCharacterCaseSiteLocation>(&case_site_sql)
80:         .await?;
81:     if let Some(character) = character.as_mut() {
82:         character.current_case_site_id = case_site
83:             .map(|location| CaseSiteId::try_new(location.case_site_id.value))
84:             .transpose()
85:             .map_err(|error| {
86:                 SpacetimeError::Spacetime(format!(
87:                     "generated case-site identity failed validation: {error}"
88:                 ))
89:             })?;
90:     }
91:     Ok(character)
92: }
