94: /// Reconstruct mutable life state at the selected observer's authoritative
95: /// personal minute. The trusted gateway can read the broad current Character
96: /// projection, but must not disclose a death from another character's future.
97: pub(crate) async fn project_alive_as_observed(
98:     state: &AppState,
99:     observer_character_id: u64,
100:     characters: &mut [CharacterView],
101: ) -> Result<()> {
102:     let observer_time = match state
103:         .db
104:         .query_one_sats::<CharacterTime>(&crate::spacetimedb::character_time_by_character_id(
105:             observer_character_id,
106:         ))
107:         .await
108:     {
109:         Ok(time) => time,
110:         Err(error) => {
111:             tracing::warn!(%error, observer_character_id, "could not read observer chronology");
112:             for character in characters.iter_mut().filter(|character| !character.alive) {
113:                 character.alive = true;
114:             }
115:             return Ok(());
116:         }
117:     };
118:     let Some(observer_minute) =
119:         observer_time.map(|time| StrategicMinute::new(time.minutes.minutes))
120:     else {
121:         // Without an observer frontier the gateway cannot safely decide that a
122:         // broad current death is already knowable. Preserve availability and
123:         // leave authoritative reducers to reject actions when appropriate.
124:         for character in characters.iter_mut().filter(|character| !character.alive) {
125:             character.alive = true;
126:         }
127:         return Ok(());
128:     };
129:     for character in characters.iter_mut().filter(|character| !character.alive) {
130:         let death = match state
131:             .db
132:             .query_one_sats::<CharacterDeath>(&crate::spacetimedb::character_death_by_character_id(
133:                 character.id,
134:             ))
135:             .await
136:         {
137:             Ok(death) => death,
138:             Err(error) => {
139:                 tracing::warn!(%error, character_id = character.id, observer_character_id, "could not read death chronology");
140:                 character.alive = true;
141:                 continue;
142:             }
143:         };
144:         character.alive = death.is_none_or(|death| {
145:             StrategicMinute::new(death.strategic_minute.minutes) > observer_minute
146:         });
147:     }
148:     Ok(())
149: }
