151: pub(crate) async fn character_as_observed(
152:     state: &AppState,
153:     character_id: u64,
154:     observer_character_id: u64,
155: ) -> Result<Option<CharacterView>> {
156:     if !character_not_ahead_of_observer(state, character_id, observer_character_id).await? {
157:         // We cannot reconstruct location, party, age, wealth, or progression
158:         // at the observer's earlier date. Fail closed instead of returning a
159:         // row containing mutable facts from the subject's future.
160:         return Ok(None);
161:     }
162:     let mut character = character(state, character_id).await?;
163:     if let Some(character) = character.as_mut() {
164:         project_alive_as_observed(
165:             state,
166:             observer_character_id,
167:             std::slice::from_mut(character),
168:         )
169:         .await?;
170:     }
171:     Ok(character)
172: }
173: 
174: pub(crate) async fn character_is_alive_as_observed(
175:     state: &AppState,
176:     character_id: u64,
177:     observer_character_id: u64,
178: ) -> Result<bool> {
179:     // Life state has its own effective-dated history, so callers that need
180:     // only this fact must not inherit the fail-closed policy for unrelated
181:     // mutable Character fields. This keeps asynchronous NPC dialogue
182:     // available without exposing the NPC's future location, wealth, or party.
183:     let mut character = character(state, character_id).await?;
184:     let Some(character) = character.as_mut() else {
185:         return Ok(false);
186:     };
187:     project_alive_as_observed(
188:         state,
189:         observer_character_id,
190:         std::slice::from_mut(character),
191:     )
192:     .await?;
193:     Ok(character.alive)
194: }
