53: fn parse_forage_form(body: &[u8]) -> Result<ForageForm, ()> {
54:     if body.len() > FORAGE_FORM_MAX_BYTES {
55:         return Err(());
56:     }
57:     let mut source = Vec::new();
58:     let mut hours = None;
59:     let mut return_to = None;
60:     for (pair_index, (key, value)) in form_urlencoded::parse(body).enumerate() {
61:         if pair_index >= FORAGE_FORM_MAX_PAIRS {
62:             return Err(());
63:         }
64:         match key.as_ref() {
65:             // Preserve duplicates so the reducer can reject malformed requests.
66:             "source" => {
67:                 if source.len() >= FORAGE_FORM_MAX_SOURCES
68:                     || value.len() > FORAGE_FORM_MAX_SOURCE_LEN
69:                 {
70:                     return Err(());
71:                 }
72:                 source.push(value.into_owned());
73:             }
74:             "hours" => {
75:                 if hours.is_some() {
76:                     return Err(());
77:                 }
78:                 hours = Some(value.parse().map_err(|_| ())?);
79:             }
80:             "return_to" => {
81:                 if return_to.is_some() || value.len() > FORAGE_FORM_MAX_RETURN_TO_LEN {
82:                     return Err(());
83:                 }
84:                 return_to = Some(value.into_owned());
85:             }
86:             _ => {}
87:         }
88:     }
89:     Ok(ForageForm {
90:         source,
91:         hours: hours.ok_or(())?,
92:         return_to: return_to.ok_or(())?,
93:     })
94: }
