466: async fn perform(
467:     State(state): State<AppState>,
468:     session: Session,
469:     RawForm(body): RawForm,
470: ) -> Response {
471:     let Ok(form) = parse_forage_form(&body) else {
472:         return StatusCode::UNPROCESSABLE_ENTITY.into_response();
473:     };
474:     let return_to = local_return_url(&form.return_to).unwrap_or("/");
475:     let Some(character_id) = session.character_id_u64() else {
476:         return Redirect::to("/characters").into_response();
477:     };
478:     let result = async {
479:         let character = character(&state, character_id).await?;
480:         let (environment, attestation) = environment(&state, &character).await?;
481:         let minutes = u64::from(form.hours) * 60;
482:         let request_id = forage_request_id(character_id);
483:         let attempt_generation = state
484:             .db
485:             .query_one_sats::<BackendForageAttemptState>(
486:                 &crate::spacetimedb::forage_attempt_state_by_character_id(character_id),
487:             )
488:             .await
489:             .map_err(|error| error.to_string())?
490:             .map_or(0, |row| row.next_generation);
491:         // The browser submits only selected categories and duration. This
492:         // session-scoped endpoint hydrates the opaque request, generation, and
493:         // private terrain attestation before entering the plan gateway.
494:         state
495:             .db
496:             .call(
497:                 "forage_current_vicinity",
498:                 &[
499:                     json!(character_id),
500:                     json!(&request_id),
501:                     json!(&form.source),
502:                     json!(minutes),
503:                     json!(attempt_generation),
504:                     attestation,
505:                 ],
506:             )
507:             .await
508:             .map_err(|error| error.to_string())?;
509:         let attempt = state
510:             .db
511:             .query_one_sats::<BackendForageReceipt>(&forage_receipt_query(
512:                 character_id,
513:                 &request_id,
514:             ))
515:             .await
516:             .map_err(|error| error.to_string())?
517:             .ok_or("Foraging completed but its result is not visible yet")?;
518:         Ok::<_, String>((environment, attempt, request_id))
519:     }
520:     .await;
521:     match result {
522:         Ok((_environment, _attempt, request_id)) => {
523:             Redirect::to(&forage_result_href(return_to, &request_id)).into_response()
524:         }
525:         Err(error) => {
526:             Redirect::to(&forage_error_href(return_to, forage_error_code(&error))).into_response()
527:         }
528:     }
529: }
