21: const ENVIRONMENT_WINDOW_PATH: &str = "/api/map/environment/{source}";
22: const TERRAIN_CAPTURE_CONCURRENCY: usize = 2;
23: static CAPTURES: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();
24: 
25: /// Native integer query fields are admitted once at the HTTP boundary.
26: #[derive(Deserialize)]
