38: async fn environment_window(
39:     State(state): State<AppState>,
40:     Path(source): Path<SourcePackageDigest>,
41:     Query(query): Query<TerrainWindowQuery>,
42: ) -> Result<
43:     (
44:         [(axum::http::HeaderName, &'static str); 1],
45:         Json<RegionalEnvironment>,
46:     ),
47:     StatusCode,
48: > {
49:     let origin = Wgs84CoordinateMicrodegrees::new(query.latitude, query.longitude)
50:         .ok_or(StatusCode::BAD_REQUEST)?;
51:     let pack = state
52:         .terrain
53:         .as_ref()
54:         .ok_or(StatusCode::SERVICE_UNAVAILABLE)?
55:         .pack
56:         .clone();
57:     if source.as_str() != pack.digest() {
58:         return Err(StatusCode::NOT_FOUND);
59:     }
60:     let permits =
61:         CAPTURES.get_or_init(|| Arc::new(tokio::sync::Semaphore::new(TERRAIN_CAPTURE_CONCURRENCY)));
62:     // Do not enqueue unbounded camera requests behind a busy terrain decoder.
63:     let permit = permits
64:         .clone()
65:         .try_acquire_owned()
66:         .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
67:     let request = RegionalTerrainRequest {
68:         origin,
69:         scale: query.scale,
70:     };
71:     let roads = state.regional_roads.clone();
72:     let window = tokio::task::spawn_blocking(move || -> anyhow::Result<RegionalEnvironment> {
73:         let _permit = permit;
74:         let roads = roads.load(&pack)?;
75:         let connections = connection_window::capture(&roads, request)?;
76:         Ok(RegionalEnvironment::new(
77:             capture(&pack, request)?,
78:             connections,
79:         )?)
80:     })
81:     .await
82:     .map_err(unavailable)?
83:     .map_err(unavailable)?;
84:     // HTTP persistence will need a sampling revision before immutable URLs can
85:     // include sampler policy as well as source identity. Renderer residency is
86:     // independent of HTTP caching and does not require another request on reopen.
87:     Ok(([(CACHE_CONTROL, "private, no-store")], Json(window)))
88: }
