1: //! Bounded presentation clipping and scale-dependent source simplification.
2: use adventuresim_tactical_core::{
3:     regional_environment::{
4:         MAX_REGIONAL_CONNECTION_POINTS, MAX_REGIONAL_CONNECTIONS, RegionalConnection,
5:         RegionalEnvironmentError,
6:     },
7:     regional_terrain::{REGIONAL_TERRAIN_SIDE, RegionalTerrainRequest},
8: };
9: use adventuresim_terrain::road_pack::RoadPack;
10: use adventuresim_world_schema::{
11:     coordinates::{
12:         Wgs84BoundsE7, Wgs84CoordinateE7,
13:         terrain_projection::{NativeTerrainCoordinate, NativeTerrainOffset},
14:     },
15:     regional_connection::RegionalConnectionKind,
16: };
17: use simplification::simplify;
18: 
19: #[path = "connection_window/simplification.rs"]
20: mod simplification;
21: 
22: /// Maximum perpendicular presentation error relative to a captured grid cell.
23: const CONNECTION_SIMPLIFICATION_CELL_FRACTION: f64 = 0.1;
24: type Result<T> = std::result::Result<T, RegionalEnvironmentError>;
25: 
26: struct WindowOutput {
27:     lines: Vec<RegionalConnection>,
28:     points: usize,
29: }
30: 
31: impl WindowOutput {
32:     fn admit(
33:         &mut self,
34:         kind: RegionalConnectionKind,
35:         points: Vec<Wgs84CoordinateE7>,
36:     ) -> Result<()> {
37:         if points.len() < 2 {
38:             return Ok(());
39:         }
40:         let line = RegionalConnection::new(kind, points)?;
41:         self.points += line.points().len();
42:         if self.points > MAX_REGIONAL_CONNECTION_POINTS
43:             || self.lines.len() >= MAX_REGIONAL_CONNECTIONS
44:         {
45:             return Err(RegionalEnvironmentError::Capacity);
46:         }
47:         self.lines.push(line);
48:         Ok(())
49:     }
50: }
51: 
52: pub(super) fn capture(
53:     roads: &RoadPack,
54:     request: RegionalTerrainRequest,
55: ) -> Result<Vec<RegionalConnection>> {
56:     let origin = NativeTerrainCoordinate::from(request.origin.to_e7());
57:     let spacing = f64::from(request.scale.spacing_metres());
58:     let half = (REGIONAL_TERRAIN_SIDE - 1) as f64 * 0.5 * spacing;
59:     let southwest = origin.at_offset(-half, -half);
60:     let northeast = origin.at_offset(half, half);
61:     let bounds = Wgs84BoundsE7::from_longitude_latitude_degrees([
62:         southwest.longitude_degrees.clamp(-180.0, 180.0),
63:         southwest.latitude_degrees.clamp(-90.0, 90.0),
64:         northeast.longitude_degrees.clamp(-180.0, 180.0),
65:         northeast.latitude_degrees.clamp(-90.0, 90.0),
66:     ])
67:     .ok_or(RegionalEnvironmentError::Geometry)?;
68:     let mut output = WindowOutput {
69:         lines: Vec::new(),
70:         points: 0,
71:     };
72:     for line in roads.intersecting(bounds) {
73:         let offsets = line
74:             .points()
75:             .iter()
76:             .map(|point| origin.offset_to((*point).into()))
77:             .collect::<Vec<_>>();
78:         let offsets = simplify(&offsets, spacing * CONNECTION_SIMPLIFICATION_CELL_FRACTION);
79:         let mut piece = Vec::new();
80:         for segment in offsets.windows(2) {
81:             let Some(clipped) = clip([segment[0], segment[1]], half) else {
82:                 output.admit(line.kind(), std::mem::take(&mut piece))?;
83:                 continue;
84:             };
85:             let [start, end] = clipped.map(|point| {
86:                 let point = origin.at_offset(point.east_metres, point.north_metres);
87:                 Wgs84CoordinateE7::from_longitude_latitude_degrees(
88:                     point.longitude_degrees,
89:                     point.latitude_degrees,
90:                 )
91:                 .ok_or(RegionalEnvironmentError::Geometry)
92:             });
93:             let (start, end) = (start?, end?);
94:             if start == end {
95:                 continue;
96:             }
97:             if piece.last().is_some_and(|last| *last != start) {
98:                 output.admit(line.kind(), std::mem::take(&mut piece))?;
99:             }
100:             if piece.is_empty() {
101:                 piece.push(start);
102:             }
103:             piece.push(end);
104:             if piece.len() + output.points > MAX_REGIONAL_CONNECTION_POINTS {
105:                 return Err(RegionalEnvironmentError::Capacity);
106:             }
107:         }
108:         output.admit(line.kind(), piece)?;
109:     }
110:     Ok(output.lines)
111: }
112: 
113: fn clip(
114:     [start, end]: [NativeTerrainOffset; 2],
115:     half_metres: f64,
116: ) -> Option<[NativeTerrainOffset; 2]> {
117:     let mut enter = 0.0_f64;
118:     let mut leave = 1.0_f64;
119:     for [first, last] in [
120:         [start.east_metres, end.east_metres],
121:         [start.north_metres, end.north_metres],
122:     ] {
123:         let delta = last - first;
124:         if delta == 0.0 {
125:             if first.abs() > half_metres {
126:                 return None;
127:             }
128:         } else {
129:             let near = (-half_metres - first) / delta;
130:             let far = (half_metres - first) / delta;
131:             enter = enter.max(near.min(far));
132:             leave = leave.min(near.max(far));
133:             if enter >= leave {
134:                 return None;
135:             }
136:         }
137:     }
138:     Some([enter, leave].map(|parameter| NativeTerrainOffset {
139:         east_metres: start.east_metres + (end.east_metres - start.east_metres) * parameter,
140:         north_metres: start.north_metres + (end.north_metres - start.north_metres) * parameter,
141:     }))
142: }
