1: //! Iterative source polyline approximation at a physical display tolerance.
2: use adventuresim_world_schema::coordinates::terrain_projection::NativeTerrainOffset;
3: 
4: /// Native geometry kernel in continuous east/north metres. This is solely a
5: /// display approximation; source routing and its digest remain untouched.
6: pub(super) fn simplify(
7:     points: &[NativeTerrainOffset],
8:     tolerance_metres: f64,
9: ) -> Vec<NativeTerrainOffset> {
10:     if points.len() < 3 {
11:         return points.to_vec();
12:     }
13:     let mut keep = vec![false; points.len()];
14:     keep[0] = true;
15:     keep[points.len() - 1] = true;
16:     let mut pending = vec![[0, points.len() - 1]];
17:     while let Some([first, last]) = pending.pop() {
18:         let start = points[first];
19:         let direction = NativeTerrainOffset {
20:             east_metres: points[last].east_metres - start.east_metres,
21:             north_metres: points[last].north_metres - start.north_metres,
22:         };
23:         let length_squared = direction.east_metres.powi(2) + direction.north_metres.powi(2);
24:         let mut selected = None;
25:         let mut farthest_squared = tolerance_metres.powi(2);
26:         for (index, point) in points.iter().enumerate().take(last).skip(first + 1) {
27:             let east = point.east_metres - start.east_metres;
28:             let north = point.north_metres - start.north_metres;
29:             let parameter = if length_squared == 0.0 {
30:                 0.0
31:             } else {
32:                 ((east * direction.east_metres + north * direction.north_metres) / length_squared)
33:                     .clamp(0.0, 1.0)
34:             };
35:             let distance_squared = (east - parameter * direction.east_metres).powi(2)
36:                 + (north - parameter * direction.north_metres).powi(2);
37:             if distance_squared > farthest_squared {
38:                 farthest_squared = distance_squared;
39:                 selected = Some(index);
40:             }
41:         }
42:         if let Some(index) = selected {
43:             keep[index] = true;
44:             pending.extend([[first, index], [index, last]]);
45:         }
46:     }
47:     points
48:         .iter()
49:         .zip(keep)
50:         .filter_map(|(point, keep)| keep.then_some(*point))
51:         .collect()
52: }
