1: //! Lazy immutable source admission; no road I/O on strategic startup.
2: use adventuresim_terrain::{
3:     TerrainPack,
4:     road_pack::{ROAD_MANIFEST_NAME, ROAD_PACK_NAME, RoadPack, RoadPackError},
5: };
6: use std::{
7:     path::PathBuf,
8:     sync::{Arc, Mutex},
9: };
10: 
11: pub(crate) type Result<T> = std::result::Result<T, RoadSourceError>;
12: 
13: pub(crate) struct RegionalRoadSource {
14:     directory: PathBuf,
15:     resident: Mutex<Option<Arc<RoadPack>>>,
16: }
17: 
18: #[derive(Debug, thiserror::Error)]
19: pub(crate) enum RoadSourceError {
20:     #[error(transparent)]
21:     Package(#[from] RoadPackError),
22:     #[error("regional road source ownership is unavailable")]
23:     Ownership,
24: }
25: 
26: impl RegionalRoadSource {
27:     pub(crate) fn new(directory: PathBuf) -> Self {
28:         Self {
29:             directory,
30:             resident: Mutex::new(None),
31:         }
32:     }
33: 
34:     /// Called only inside bounded blocking capture. Failed admission leaves the
35:     /// slot empty so an explicit retry can admit repaired development artifacts.
36:     pub(super) fn load(&self, terrain: &TerrainPack) -> Result<Arc<RoadPack>> {
37:         let mut resident = self
38:             .resident
39:             .lock()
40:             .map_err(|_| RoadSourceError::Ownership)?;
41:         if let Some(roads) = &*resident {
42:             if roads.source().as_str() != terrain.digest() {
43:                 return Err(RoadPackError::SourceMismatch.into());
44:             }
45:             return Ok(roads.clone());
46:         }
47:         let roads = Arc::new(RoadPack::load(
48:             &self.directory.join(ROAD_MANIFEST_NAME),
49:             &self.directory.join(ROAD_PACK_NAME),
50:             terrain,
51:         )?);
52:         *resident = Some(roads.clone());
53:         Ok(roads)
54:     }
55: }

