215:     };
216: 
217:     let server = match get_mission_for_viewer(&state, &mission_id).await {
218:         Ok(server) => server,
219:         Err(error) => {
220:             tracing::error!(%error, "failed to load mission");
221:             return (
222:                 StatusCode::SERVICE_UNAVAILABLE,
223:                 "Strategic data is unavailable",
224:             )
225:                 .into_response();
226:         }
227:     };
228:     let Some(server) = server else {
229:         return (StatusCode::NOT_FOUND, "Mission not found").into_response();
230:     };
231:     if !can_view_mission(&viewer, &server) {
232:         return (StatusCode::FORBIDDEN, "Not authorized for this mission").into_response();
233:     }
234: 
235:     let _ = execute_or_request_party_action(
236:         &state,
237:         character_id,
238:         PartyAction::CancelMission { mission_id },
239:     )
240:     .await;
241: 
242:     Redirect::to("/").into_response()
243: }
