1: //! Prepare the actual tactical scene document without requesting a server.
2: use super::scene_preparation::{profile, scene_minute};
3: use super::{AppState, CharacterView, SettlementView};
4: use crate::{session::Session, spacetimedb};
5: use adventuresim_stdb_client as sdk;
6: use adventuresim_tactical_server_dispatcher::scene_input::build_imported_scene;
7: use adventuresim_world_schema::coordinates::Wgs84CoordinateE7;
8: use axum::{
9:     Json, Router,
10:     extract::{Query, State},
11:     http::StatusCode,
12:     routing::get,
13: };
14: use serde::Deserialize;
15: use std::sync::Arc;
16: 
17: #[derive(Deserialize)]
18: struct Request {
19:     settlement: Option<String>,
20: }
21: 
22: pub(super) fn routes() -> Router<AppState> {
23:     Router::new().route("/api/scene-assets", get(scene_assets))
24: }
25: 
26: async fn scene_assets(
27:     State(state): State<AppState>,
28:     session: Session,
29:     Query(request): Query<Request>,
30: ) -> Result<Json<adventuresim_tactical_core::prelude::TacticalSceneInput>, StatusCode> {
31:     let id = session.character_id_u64().ok_or(StatusCode::UNAUTHORIZED)?;
32:     let mut actor = state
33:         .db
34:         .query_one_sats_into::<sdk::Character, CharacterView>(&spacetimedb::character_by_id(id))
35:         .await
36:         .map_err(unavailable)?
37:         .ok_or(StatusCode::UNAUTHORIZED)?;
38:     if request
39:         .settlement
40:         .as_ref()
41:         .is_some_and(|requested| actor.current_settlement_id.as_ref() != Some(requested))
42:     {
43:         return Err(StatusCode::FORBIDDEN);
44:     }
45:     actor.current_case_site_id = super::character_case_site_id(&state, id)
46:         .await
47:         .map_err(unavailable)?;
48:     let (coordinates, scene_key, identity, profile) =
49:         if let Some(settlement_id) = actor.current_settlement_id.as_deref() {
50:             let settlement = state
51:                 .db
52:                 .query_one_sats_into::<sdk::Settlement, SettlementView>(
53:                     &spacetimedb::settlement_by_id(settlement_id),
54:                 )
55:                 .await
56:                 .map_err(unavailable)?
57:                 .ok_or(StatusCode::NOT_FOUND)?;
58:             let coordinates = Wgs84CoordinateE7::from_longitude_latitude_degrees(
59:                 settlement.longitude,
60:                 settlement.latitude,
61:             )
62:             .ok_or(StatusCode::SERVICE_UNAVAILABLE)?;
63:             let profile = profile(&state, &settlement).await?;
64:             (
65:                 coordinates,
66:                 settlement.scene_key,
67:                 settlement.id,
68:                 Some(profile),
69:             )
70:         } else {
71:             let location = super::vicinity::vicinity(&state, &actor)
72:                 .await
73:                 .map_err(unavailable)?;
74:             let coordinates = Wgs84CoordinateE7::from_longitude_latitude_degrees(
75:                 location.longitude,
76:                 location.latitude,
77:             )
78:             .ok_or(StatusCode::SERVICE_UNAVAILABLE)?;
79:             (coordinates, location.kind, location.id, None)
80:         };
81:     let minute = scene_minute(&state).await?;
82:     let terrain = state
83:         .terrain
84:         .as_ref()
85:         .ok_or(StatusCode::SERVICE_UNAVAILABLE)?
86:         .pack
87:         .clone();
88:     // Scene generation is CPU-heavy; bound both concurrency and async-worker use.
89:     static PERMITS: std::sync::OnceLock<Arc<tokio::sync::Semaphore>> = std::sync::OnceLock::new();
90:     let permit = Arc::clone(PERMITS.get_or_init(|| Arc::new(tokio::sync::Semaphore::new(2))))
91:         .acquire_owned()
92:         .await
93:         .map_err(unavailable)?;
94:     let input = tokio::task::spawn_blocking(move || {
95:         let _permit = permit;
96:         build_imported_scene(
97:             &terrain,
98:             &identity,
99:             &scene_key,
100:             coordinates.latitude().get(),
101:             coordinates.longitude().get(),
102:             minute,
103:             minute,
104:             profile.as_ref(),
105:         )
106:     })
107:     .await
108:     .map_err(unavailable)?
109:     .map_err(unavailable)?;
110:     if let Some(catalog) = &input.properties {
111:         super::settlement_properties::ensure_catalog(&state, catalog)
112:             .await
113:             .map_err(unavailable)?;
114:     }
115:     Ok(Json(input))
116: }
117: 
118: fn unavailable(error: impl std::fmt::Display) -> StatusCode {
119:     tracing::error!(%error, "tactical scene preparation failed");
120:     StatusCode::SERVICE_UNAVAILABLE
121: }
