17: };
18: use serde::Deserialize;
19: 
20: const MAX_CHARACTERS_PER_REQUEST: usize = 256;
21: 
22: #[derive(Deserialize)]
23: struct Request {
24:     characters: String,
25: }
26: 
27: pub(super) fn routes() -> Router<AppState> {
