29: }
30: 
31: async fn equipment(
32:     State(state): State<AppState>,
33:     session: Session,
34:     Query(request): Query<Request>,
35: ) -> Result<Json<Vec<CharacterEquipmentAppearance>>, StatusCode> {
36:     let actor = session.character_id_u64().ok_or(StatusCode::UNAUTHORIZED)?;
37:     let ids = request
38:         .characters
39:         .split(',')
40:         .map(str::parse::<u64>)
41:         .collect::<Result<Vec<_>, _>>()
42:         .map_err(|_| StatusCode::BAD_REQUEST)?;
43:     if ids.is_empty() || ids.len() > MAX_CHARACTERS_PER_REQUEST {
44:         return Err(StatusCode::BAD_REQUEST);
45:     }
46:     let actor = state
47:         .db
48:         .query_one_sats_into::<adventuresim_stdb_client::Character, CharacterView>(
49:             &spacetimedb::character_by_id(actor),
50:         )
51:         .await
52:         .map_err(unavailable)?
53:         .ok_or(StatusCode::UNAUTHORIZED)?;
54:     let condition = ids
55:         .iter()
56:         .map(|id| format!("id = {id}"))
57:         .collect::<Vec<_>>()
58:         .join(" OR ");
59:     let characters = state
60:         .db
61:         .query_sats_into::<adventuresim_stdb_client::Character, CharacterView>(&format!(
62:             "SELECT * FROM character WHERE {condition}"
63:         ))
64:         .await
65:         .map_err(unavailable)?;
66:     let mut grants = session.character_ids();
67:     if characters
68:         .iter()
69:         .any(|target| !visible(&actor, target, &grants))
70:         && let Some(party) = actor.party_id.as_deref()
71:     {
72:         let requests = state
73:             .db
74:             .query_sats::<adventuresim_stdb_client::PartyJoinRequest>(&format!(
75:                 "SELECT * FROM party_join_request WHERE party_id = {}",
76:                 spacetimedb::sql_string_literal(party)
77:             ))
78:             .await
79:             .map_err(unavailable)?;
80:         grants.extend(
81:             requests
82:                 .into_iter()
83:                 .filter(|request| request.party_id == party)
84:                 .map(|request| request.character_id),
85:         );
86:     }
87:     if ids.iter().any(|id| {
88:         !characters
89:             .iter()
90:             .any(|person| person.id == *id && visible(&actor, person, &grants))
91:     }) {
92:         return Err(StatusCode::FORBIDDEN);
93:     }
94:     appearances(&state, ids).await
95: }
96: 
97: async fn appearances(
98:     state: &AppState,
99:     ids: Vec<u64>,
100: ) -> Result<Json<Vec<CharacterEquipmentAppearance>>, StatusCode> {
101:     let condition = ids
