169: async fn recipes(
170:     state: &AppState,
171:     objects: &[InventoryObject],
172:     worn: &[CharacterEquippedItem],
173: ) -> Result<(Vec<WeaponInstance>, Vec<WeaponHolderInstance>), StatusCode> {
174:     let condition = objects.iter().filter(|object| matches!(&object.location,
175:         InventoryLocation::Personal(location) if worn.iter().any(|item|
176:             item.character_id == location.character_id && item.inventory_item_id == location.row_id)))
177:         .map(|object| format!("physical_object_id = {}", object.id)).collect::<Vec<_>>().join(" OR ");
178:     if condition.is_empty() {
179:         return Ok((vec![], vec![]));
180:     }
181:     let weapon_sql = format!("SELECT * FROM weapon_instance WHERE {condition}");
182:     let holder_sql = format!("SELECT * FROM weapon_holder_instance WHERE {condition}");
183:     let (weapons, holders) = tokio::join!(
184:         state.db.query_sats::<WeaponInstance>(&weapon_sql),
185:         state.db.query_sats::<WeaponHolderInstance>(&holder_sql)
186:     );
187:     Ok((weapons.map_err(unavailable)?, holders.map_err(unavailable)?))
188: }
