229:         EquipmentAnchorKind::ItemAttachment => AppearanceAnchor::Attachment {
230:             parent: PresentationId(
231:                 row.parent_inventory_item_id
232:                     .ok_or(StatusCode::SERVICE_UNAVAILABLE)?
233:                     .to_string(),
234:             ),
235:             point: row
236:                 .attachment_point_id
237:                 .clone()
238:                 .ok_or(StatusCode::SERVICE_UNAVAILABLE)?,
239:         },
240:     };
241:     Ok(AppearanceOccupancy {
242:         anchor,
243:         channel: spacetimedb::core_equipment_channel(row.channel),
244:         order: row.order,
245:         requirement_index: row.requirement_index,
246:         capacity_index: row.capacity_index,
247:     })
