356: pub(crate) async fn get_active_party_members(
357:     state: &AppState,
358:     active_character: Option<&CharacterView>,
359: ) -> Vec<CharacterView> {
360:     let Some(party_id) = active_character.and_then(|character| character.party_id.as_ref()) else {
361:         return Vec::new();
362:     };
363:     let memberships_sql = format!(
364:         "SELECT * FROM party_member WHERE party_id = {}",
365:         sql_string_literal(party_id)
366:     );
367:     let party_sql = crate::spacetimedb::party_by_id(party_id);
368:     let (memberships, party) = tokio::join!(
369:         state.db.query_sats::<PartyMember>(&memberships_sql),
370:         state.db.query_sats_into::<adventuresim_stdb_client::Party, PartyView>(&party_sql),
371:     );
372:     let memberships = memberships.unwrap_or_default();
373:     let leader_id = party
374:         .unwrap_or_default()
375:         .first()
376:         .map(|party| party.leader_id);
377:     let lookups = memberships.into_iter().map(|membership| async move {
378:         state
379:             .db
380:             .query_sats_into::<adventuresim_stdb_client::Character, CharacterView>(&crate::spacetimedb::character_by_id(
381:                 membership.character_id,
382:             ))
383:             .await
384:             .unwrap_or_default()
385:             .into_iter()
386:             .next()
387:     });
388:     let mut members: Vec<CharacterView> = join_all(lookups).await.into_iter().flatten().collect();
389:     if let Some(actor) = active_character {
390:         // Party membership and Character are mutable current projections. A
391:         // member whose personal frontier is ahead of the viewer would expose
392:         // future location, party, progression, and wealth through this model,
393:         // so omit that row until the viewer catches up.
394:         let visibility = join_all(members.iter().map(|member| async move {
395:             (
396:                 member.id,
397:                 super::super::data::character_not_ahead_of_observer(state, member.id, actor.id)
398:                     .await
399:                     .unwrap_or(false),
400:             )
401:         }))
402:         .await;
403:         let visible_ids = visibility
404:             .into_iter()
405:             .filter_map(|(id, visible)| visible.then_some(id))
406:             .collect::<HashSet<_>>();
407:         members.retain(|member| visible_ids.contains(&member.id));
408:         if let Err(error) =
409:             super::super::data::project_alive_as_observed(state, actor.id, &mut members).await
410:         {
411:             // A failed chronology read must not disclose or act on broad
412:             // current death state from beyond the selected character's date.
413:             tracing::warn!(%error, "could not project party life state at observer date");
414:             for member in members.iter_mut().filter(|member| !member.alive) {
415:                 member.alive = true;
416:             }
417:         }
418:         let addresses_sql = format!(
419:             "SELECT * FROM backend_social_addresses WHERE actor_id = {}",
420:             actor.id
421:         );
422:         let automatic_sql = format!(
423:             "SELECT * FROM backend_automatic_social_chats WHERE actor_id = {}",
424:             actor.id
425:         );
426:         let source_lookups = members.iter().map(|member| async move {
427:             state
428:                 .db
429:                 .query_sats::<CharacterMoraleSource>(&format!(
430:                     "SELECT * FROM backend_character_morale_sources WHERE character_id = {}",
431:                     member.id
432:                 ))
433:                 .await
434:                 .unwrap_or_default()
435:         });
436:         let (source_groups, addresses, automatic_chats) = tokio::join!(
437:             join_all(source_lookups),
438:             state.db.query_sats::<SocialAddress>(&addresses_sql),
439:             state.db.query_sats::<AutomaticSocialChat>(&automatic_sql),
440:         );
441:         let sources: Vec<_> = source_groups.into_iter().flatten().collect();
442:         let successful = addresses.unwrap_or_default();
443:         let automatic_targets: HashSet<u64> = automatic_chats
444:             .unwrap_or_default()
445:             .into_iter()
446:             .filter(|preference| preference.actor_id == actor.id)
447:             .map(|preference| preference.target_id)
448:             .collect();
449:         for member in &mut members {
450:             let colocated = member.id == actor.id
451:                 || (member.current_settlement_id == actor.current_settlement_id
452:                     && member.current_case_site_id == actor.current_case_site_id);
453:             if !member.alive || !actor.alive || !colocated {
454:                 continue;
455:             }
456:             member.social_notification_count =
457:                 adventuresim_core::social::unaddressed_social_source_count(
458:                     actor.id,
459:                     member.id,
460:                     sources
461:                         .iter()
462:                         .filter(|source| source.character_id == member.id)
463:                         .map(|source| {
464:                             (
465:                                 source.id.as_str(),
466:                                 crate::spacetimedb::core_morale_source_kind(source.kind),
467:                                 source.magnitude,
468:                             )
469:                         }),
470:                     successful.iter().map(|address| {
471:                         (
472:                             address.actor_id,
473:                             address.target_id,
474:                             address.source_id.as_str(),
475:                             true,
476:                         )
477:                     }),
478:                 );
479:             member.automatic_social_chat_enabled = automatic_targets.contains(&member.id);
480:         }
481:     }
482:     members.sort_by_key(|member| (Some(member.id) != leader_id, member.id));
483:     members
484: }

