67: pub(super) async fn character_equipment_graph(
68:     state: &AppState,
69:     character_id: u64,
70: ) -> Vec<CharacterEquipmentGraph> {
71:     let worn_sql =
72:         format!("SELECT * FROM character_equipped_item WHERE character_id = {character_id}");
73:     let occupancy_sql =
74:         format!("SELECT * FROM equipment_occupancy WHERE character_id = {character_id}");
75:     let inventory_sql = format!("SELECT * FROM inventory_item WHERE character_id = {character_id}");
76:     let (worn, occupancies, inventory, definitions) = tokio::join!(
77:         state
78:             .db
79:             .query_sats_into::<adventuresim_stdb_client::CharacterEquippedItem, EquippedItemView>(
80:                 &worn_sql,
81:             ),
82:         state.db.query_sats::<EquipmentOccupancy>(&occupancy_sql),
83:         state.db.query_sats::<InventoryItem>(&inventory_sql),
84:         state
85:             .db
86:             .query_sats_into::<DbItem, CatalogItemView>("SELECT * FROM item"),
87:     );
88:     let mut worn = worn.unwrap_or_default();
89:     let worn_ids = worn
90:         .iter()
91:         .map(|row| row.inventory_item_id)
92:         .collect::<Vec<_>>();
93:     let occupancies = occupancies.unwrap_or_default();
94:     let inventory = inventory.unwrap_or_default();
95:     let definitions = definitions.unwrap_or_default();
96:     for node in &mut worn {
97:         node.item_name = inventory
98:             .iter()
99:             .find(|item| item.id == node.inventory_item_id)
100:             .map_or_else(
101:                 || format!("#{}", node.inventory_item_id),
102:                 |item| item.item_id.clone(),
103:             );
104:     }
105:     let used_capacity = occupancies
106:         .iter()
107:         .filter(|row| row.anchor_kind == EquipmentAnchorKind::ItemAttachment)
108:         .fold(HashMap::<(u64, String), u16>::new(), |mut counts, row| {
109:             if let (Some(parent_id), Some(point_id)) = (
110:                 row.parent_inventory_item_id,
111:                 row.attachment_point_id.as_ref(),
112:             ) {
113:                 *counts.entry((parent_id, point_id.clone())).or_default() += 1;
114:             }
115:             counts
116:         });
117:     let mut attachment_targets = Vec::new();
118:     for node in &worn {
119:         let Some(carried) = inventory
120:             .iter()
121:             .find(|item| item.id == node.inventory_item_id)
122:         else {
123:             continue;
124:         };
125:         let Some(definition) = definitions
126:             .iter()
127:             .find(|definition| definition.id == carried.item_id)
128:         else {
129:             continue;
130:         };
131:         for point in &definition.attachment_points {
132:             let used = used_capacity
133:                 .get(&(node.inventory_item_id, point.id.clone()))
134:                 .copied()
135:                 .unwrap_or(0);
136:             attachment_targets.push(EquipmentAttachmentTarget {
137:                 parent_inventory_item_id: node.inventory_item_id,
138:                 parent_item_name: carried.item_id.clone(),
139:                 attachment_point_id: point.id.clone(),
140:                 channel: point.channel,
141:                 accepts_tags: point.accepts_tags.clone(),
142:                 free_capacity: point.capacity.saturating_sub(used),
143:                 order: point.order,
144:             });
145:         }
146:     }
147:     attachment_targets.sort_by_key(|target| {
148:         (
149:             target.parent_inventory_item_id,
150:             target.order,
151:             target.attachment_point_id.clone(),
152:         )
153:     });
154:     vec![CharacterEquipmentGraph {
155:         _character_id: character_id,
156:         worn_item_ids: worn_ids,
157:         equipment_nodes: worn,
158:         equipment_occupancies: occupancies,
159:         attachment_targets,
160:     }]
161: }
