707: pub(crate) async fn medical_presentation(
708:     state: &AppState,
709:     viewer_id: u64,
710:     target_id: u64,
711: ) -> crate::medical::MedicalPresentation {
712:     let rows = match state
713:         .db
714:         .query_sats::<BackendPhysiologyChart>(&format!(
715:             "SELECT * FROM backend_physiology_charts WHERE observer_id = {viewer_id} AND patient_id = {target_id}"
716:         ))
717:         .await
718:     {
719:         Ok(rows) => rows,
720:         Err(error) => {
721:             tracing::error!(%error,target_id,"private medical query failed closed");
722:             return crate::medical::MedicalPresentation {
723:                 unavailable: true,
724:                 ..Default::default()
725:             };
726:         }
727:     };
728:     let administrations = if administration_history_visible(viewer_id, target_id, !rows.is_empty())
729:     {
730:         state
731:             .db
732:             .query_sats::<BackendPhysiologyAdministration>(&format!(
733:                 "SELECT * FROM backend_physiology_administrations WHERE patient_id = {target_id}"
734:             ))
735:             .await
736:             .unwrap_or_default()
737:     } else {
738:         Vec::new()
739:     };
740:     let current_minute = match state
741:         .db
742:         .query_one_sats::<CharacterTime>(&db::character_time_by_character_id(target_id))
743:         .await
744:     {
745:         Ok(Some(time)) => adventuresim_world_schema::calendar::StrategicMinute::new(time.minutes.minutes),
746:         Ok(None) => {
747:             tracing::error!(
748:                 target_id,
749:                 "patient time missing; medical presentation unavailable"
750:             );
751:             return crate::medical::MedicalPresentation {
752:                 unavailable: true,
753:                 ..Default::default()
754:             };
755:         }
756:         Err(error) => {
757:             tracing::error!(%error, target_id, "patient time query failed; medical presentation unavailable");
758:             return crate::medical::MedicalPresentation {
759:                 unavailable: true,
760:                 ..Default::default()
761:             };
762:         }
763:     };
764:     crate::medical::sanitize(&rows, &administrations, current_minute)
765: }
