110: async fn render_residences(
111:     state: &AppState,
112:     settlement: &SettlementView,
113:     character: &CharacterView,
114:     party_members: &[CharacterView],
115:     session: &Session,
116:     notice: Option<&str>,
117: ) -> Html<String> {
118:     if let Err(error) = super::super::settlement_properties::ensure(state, settlement).await {
119:         tracing::error!(%error, settlement_id = %settlement.id, "physical homes unavailable");
120:         return Html("<h1>Residence properties are unavailable</h1>".into());
121:     }
122:     let offers_sql = format!(
123:         "SELECT * FROM backend_available_residence_properties WHERE settlement_id = {}",
124:         sql_string_literal(&settlement.id)
125:     );
126:     let residence_sql = db::character_residence_status_by_character_id(character.id);
127:     let (offers, residences, (presentation, character_minute)) = tokio::join!(
128:         state
129:             .db
130:             .query_sats::<adventuresim_stdb_client::AvailableResidenceProperty>(&offers_sql),
131:         state
132:             .db
133:             .query_sats::<BackendCharacterResidenceStatus>(&residence_sql),
134:         read_family(state, character, session.owner_key().unwrap_or_default()),
135:     );
136:     let (Ok(mut offers), Ok(mut residences)) = (offers, residences) else {
137:         return Html("<h1>Residence properties are unavailable</h1>".into());
138:     };
139:     offers.sort_by_key(|offer| match offer.tier {
140:         adventuresim_stdb_client::HousingTier::Cheap => 0,
141:         adventuresim_stdb_client::HousingTier::Moderate => 1,
142:         adventuresim_stdb_client::HousingTier::Fancy => 2,
143:     });
144:     offers.retain(|offer| offer.available_from_minute.minutes <= character_minute.get());
145:     residences.retain(|holding| holding.character_id == character.id);
146:     residences.sort_by(|left, right| {
147:         (
148:             !left.primary,
149:             left.settlement_id != settlement.id,
150:             left.holding_id.as_str(),
151:         )
152:             .cmp(&(
153:                 !right.primary,
154:                 right.settlement_id != settlement.id,
155:                 right.holding_id.as_str(),
156:             ))
157:     });
158:     let can_rest_at_home = residences
159:         .iter()
160:         .any(|home| home.active && home.occupied && home.settlement_id == settlement.id);
161:     Html(
162:         settlement_residence_page(
163:             settlement,
164:             character,
165:             party_members,
166:             Some(&character.name),
167:             &offers,
168:             &residences,
169:             presentation.as_ref(),
170:             can_rest_at_home,
171:             notice,
172:         )
173:         .into_string(),
174:     )
175: }
