177: async fn read_family(
178:     state: &AppState,
179:     character: &CharacterView,
180:     owner_key: &str,
181: ) -> (Option<RelationshipPresentation>, StrategicMinute) {
182:     let relationship_sql = db::character_relationship_status_by_character_id(character.id);
183:     let family_sql = format!(
184:         "SELECT * FROM backend_family_children WHERE owner_key = {} AND observer_character_id = {}",
185:         sql_string_literal(owner_key),
186:         character.id
187:     );
188:     let clock_sql = db::character_time_by_character_id(character.id);
189:     let (relationship, children, clock) = tokio::join!(
190:         state
191:             .db
192:             .query_one_sats::<BackendCharacterRelationshipStatus>(&relationship_sql),
193:         state.db.query_sats::<BackendFamilyChild>(&family_sql),
194:         state.db.query_one_sats::<CharacterTime>(&clock_sql)
195:     );
196:     let minute = clock.ok().flatten().map_or(StrategicMinute::ZERO, |time| {
197:         StrategicMinute::new(time.minutes.minutes)
198:     });
199:     let relationship = relationship.ok().flatten();
