323: pub(super) async fn change_residence(
324:     State(state): State<AppState>,
325:     Path((id, action, tier)): Path<(String, String, String)>,
326:     session: Session,
327:     Form(form): Form<ResidenceActionForm>,
328: ) -> Redirect {
329:     let fallback = paths::SETTLEMENT_PLACE.url([&id, &("residences")]);
330:     let Some(character_id) = session.character_id_u64() else {
331:         return Redirect::to("/characters");
332:     };
333:     let (Some(operation), Some(tier)) = (
334:         ResidenceOperation::parse(&action),
335:         ResidenceTier::parse(&tier),
336:     ) else {
337:         return Redirect::to(&format!("{fallback}?residence_notice=unavailable"));
338:     };
339:     let selected_holding = form
340:         .holding_id
341:         .filter(|holding_id| !holding_id.trim().is_empty());
342:     let args = match operation {
343:         ResidenceOperation::Rent | ResidenceOperation::Buy => {
344:             let Some(property_id) = form.property_id.filter(|id| !id.is_empty()) else {
345:                 return Redirect::to(&format!("{fallback}?residence_notice=unavailable"));
346:             };
347:             let property = state
348:                 .db
349:                 .query_one_sats::<adventuresim_stdb_client::SettlementProperty>(&format!(
350:                     "SELECT * FROM settlement_property WHERE id = {}",
351:                     sql_string_literal(&property_id)
352:                 ))
353:                 .await;
354:             let expected_tier = match tier {
355:                 ResidenceTier::Cheap => Some(adventuresim_stdb_client::HousingTier::Cheap),
356:                 ResidenceTier::Moderate => Some(adventuresim_stdb_client::HousingTier::Moderate),
357:                 ResidenceTier::Fancy => Some(adventuresim_stdb_client::HousingTier::Fancy),
358:                 ResidenceTier::Current => None,
359:             };
360:             if !matches!(property, Ok(Some(ref property)) if property.settlement_id == id && Some(property.tier) == expected_tier)
361:             {
362:                 return Redirect::to(&format!("{fallback}?residence_notice=unavailable"));
363:             }
364:             vec![json!(character_id), json!(property_id)]
365:         }
366:         ResidenceOperation::Relinquish
367:         | ResidenceOperation::Designate
368:         | ResidenceOperation::Recover => {
369:             let Some(holding_id) = selected_holding.filter(|_| tier == ResidenceTier::Current)
370:             else {
371:                 return Redirect::to(&format!("{fallback}?residence_notice=unavailable"));
372:             };
373:             vec![json!(character_id), json!(holding_id)]
374:         }
375:     };
376:     match state.db.call(operation.reducer(), &args).await {
377:         Ok(()) => Redirect::to(&format!(
378:             "{fallback}?residence_notice={}",
379:             operation.success_notice()
380:         )),
381:         Err(error) => {
382:             tracing::warn!(character_id, ?operation, ?tier, %error, "residence acquisition rejected");
383:             Redirect::to(&format!(
384:                 "{fallback}?residence_notice={}",
385:                 housing_error_code(&error.to_string())
386:             ))
387:         }
388:     }
389: }
