60: impl std::fmt::Display for RestDurationError {
61:     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
62:         use adventuresim_world_schema::calendar::DAYS_PER_YEAR;
63: 
64:         match self {
65:             Self::SettlementBelowMinimum => {
66:                 formatter.write_str("Settlement rest must last at least one day")
67:             }
68:             Self::SettlementAboveMaximum => write!(
69:                 formatter,
70:                 "Settlement rest cannot exceed {DAYS_PER_YEAR} days"
71:             ),
72:             Self::TravelBelowMinimum => formatter.write_str("Rest must last at least one minute"),
73:             Self::TravelAboveMaximum => {
74:                 write!(formatter, "Rest cannot exceed {DAYS_PER_YEAR} days")
75:             }
76:             Self::MinutesNotWhole => formatter.write_str("Rest minutes must be a whole number"),
77:             Self::ClockFormat => formatter.write_str("Rest duration must use HH:MM"),
78:             Self::ClockMinuteOutOfRange => {
79:                 formatter.write_str("Rest duration minutes must be between 00 and 59")
80:             }
81:             Self::DurationOverflow => formatter.write_str("Rest duration is too large"),
82:             Self::WakeTimeMismatch => {
83:                 formatter.write_str("Rest duration does not match the selected wake time")
84:             }
85:             Self::DaysNotWhole => formatter.write_str("Rest days must be a whole number"),
86:             Self::UnknownUnit => formatter.write_str("Unknown rest duration unit"),
87:         }
