93: pub(super) fn settlement_rest_minutes(form: &RestForm) -> Result<u64, RestDurationError> {
94:     let minutes = parsed_rest_minutes(form)?;
95:     if minutes < adventuresim_world_schema::calendar::MINUTES_PER_DAY {
96:         return Err(RestDurationError::SettlementBelowMinimum);
97:     }
98:     if minutes > MAX_SETTLEMENT_REST_MINUTES {
99:         return Err(RestDurationError::SettlementAboveMaximum);
100:     }
101:     Ok(minutes)
102: }
103: 
104: pub(crate) fn travel_rest_minutes(form: &RestForm) -> Result<u64, RestDurationError> {
105:     let minutes = parsed_rest_minutes(form)?;
106:     if minutes == 0 {
107:         return Err(RestDurationError::TravelBelowMinimum);
108:     }
109:     if minutes > MAX_SETTLEMENT_REST_MINUTES {
110:         return Err(RestDurationError::TravelAboveMaximum);
111:     }
112:     Ok(minutes)
113: }
114: 
115: pub(super) fn parsed_rest_minutes(form: &RestForm) -> Result<u64, RestDurationError> {
116:     Ok(match form.unit.as_str() {
117:         "minutes" => form
118:             .duration
119:             .parse::<u64>()
120:             .map_err(|_| RestDurationError::MinutesNotWhole)?,
121:         "hours" => {
122:             let (hours, minutes) = form
123:                 .duration
124:                 .split_once(':')
125:                 .ok_or(RestDurationError::ClockFormat)?;
126:             if minutes.len() != 2 || !minutes.bytes().all(|byte| byte.is_ascii_digit()) {
127:                 return Err(RestDurationError::ClockFormat);
128:             }
129:             let hours = hours
130:                 .parse::<u64>()
131:                 .map_err(|_| RestDurationError::ClockFormat)?;
132:             let minutes = minutes
133:                 .parse::<u64>()
134:                 .map_err(|_| RestDurationError::ClockFormat)?;
135:             if minutes >= 60 {
136:                 return Err(RestDurationError::ClockMinuteOutOfRange);
137:             }
138:             let duration_minutes = hours
139:                 .checked_mul(60)
140:                 .and_then(|value| value.checked_add(minutes))
141:                 .ok_or(RestDurationError::DurationOverflow)?;
142:             if let Some(requested_minutes) = form.requested_minutes
143:                 && requested_minutes != duration_minutes
144:             {
145:                 return Err(RestDurationError::WakeTimeMismatch);
146:             }
147:             form.requested_minutes.unwrap_or(duration_minutes)
148:         }
149:         "days" => {
150:             let days = form
151:                 .duration
152:                 .parse::<u64>()
153:                 .map_err(|_| RestDurationError::DaysNotWhole)?;
154:             days.saturating_mul(adventuresim_world_schema::calendar::MINUTES_PER_DAY)
155:         }
156:         _ => return Err(RestDurationError::UnknownUnit),
157:     })
158: }
