1: //! Signed opaque browser sessions backed by server-side character grants.
2: 
3: use std::{
4:     fmt,
5:     time::{SystemTime, UNIX_EPOCH},
6: };
7: 
8: use axum::{
9:     extract::FromRequestParts,
10:     http::{HeaderMap, HeaderValue, StatusCode, header, request::Parts},
11:     response::{IntoResponse, Redirect, Response},
12: };
13: use axum_extra::extract::CookieJar;
14: use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD};
15: use hmac::{Hmac, Mac};
16: use sha2::{Digest, Sha256};
17: 
18: use crate::{
19:     routes::AppState,
20:     spacetimedb::{BackendBrowserCharacterAccess, sql_string_literal},
21: };
22: 
23: pub const SESSION_COOKIE: &str = "adventuresim_session";
24: const SESSION_VERSION: &str = "v2";
25: const SESSION_ID_BYTES: usize = 32;
26: const OWNER_DOMAIN: &[u8] = b"adventuresim/browser-session-owner/v1\0";
27: const SESSION_LIFETIME_SECONDS: u64 = 60 * 60 * 24 * 30;
28: const SESSION_FUTURE_SKEW_SECONDS: u64 = 5 * 60;
29: 
30: type HmacSha256 = Hmac<Sha256>;
31: 
32: #[derive(Clone)]
33: pub struct SessionCodec {
34:     secret: [u8; 32],
35:     secure_cookie: bool,
36: }
37: 
38: #[derive(Debug, thiserror::Error)]
39: pub enum SessionCodecError {
40:     #[error("STRATEGIC_SESSION_SECRET must be exactly 32 base64url bytes")]
41:     InvalidSecret,
42:     #[error("secure random session generation failed")]
43:     Random,
44: }
45: 
46: #[derive(Clone, Debug, PartialEq, Eq)]
47: pub struct IssuedSession {
48:     pub token: String,
49:     pub owner_key: String,
50: }
51: 
52: impl SessionCodec {
53:     pub fn from_base64url(secret: &str, secure_cookie: bool) -> Result<Self, SessionCodecError> {
54:         let decoded = URL_SAFE_NO_PAD
55:             .decode(secret)
56:             .map_err(|_| SessionCodecError::InvalidSecret)?;
57:         let secret: [u8; 32] = decoded
58:             .try_into()
59:             .map_err(|_| SessionCodecError::InvalidSecret)?;
60:         Ok(Self {
61:             secret,
62:             secure_cookie,
63:         })
64:     }
65: 
66:     pub fn issue(&self) -> Result<IssuedSession, SessionCodecError> {
67:         let mut id = [0u8; SESSION_ID_BYTES];
68:         getrandom::fill(&mut id).map_err(|_| SessionCodecError::Random)?;
69:         let issued_at = unix_seconds();
70:         Ok(self.issue_at(id, issued_at))
71:     }
72: 
73:     fn issue_at(&self, id: [u8; SESSION_ID_BYTES], issued_at: u64) -> IssuedSession {
74:         let encoded_id = URL_SAFE_NO_PAD.encode(id);
75:         let signed = format!("{SESSION_VERSION}.{encoded_id}.{issued_at}");
76:         let signature = self.sign(signed.as_bytes());
77:         IssuedSession {
78:             token: format!("{signed}.{}", URL_SAFE_NO_PAD.encode(signature)),
79:             owner_key: owner_key(&id),
80:         }
81:     }
82: 
83:     /// Verify the HMAC before accepting the opaque ID. `verify_slice` performs
84:     /// a constant-time MAC comparison.
85:     pub fn verify(&self, token: &str) -> Option<String> {
86:         self.verify_at(token, unix_seconds())
87:     }
88: 
89:     fn verify_at(&self, token: &str, now: u64) -> Option<String> {
90:         let mut parts = token.split('.');
91:         let version = parts.next()?;
92:         let encoded_id = parts.next()?;
93:         let encoded_issued_at = parts.next()?;
94:         let encoded_signature = parts.next()?;
95:         if version != SESSION_VERSION || parts.next().is_some() {
96:             return None;
97:         }
98:         let id = URL_SAFE_NO_PAD.decode(encoded_id).ok()?;
99:         let id: [u8; SESSION_ID_BYTES] = id.try_into().ok()?;
100:         let issued_at = encoded_issued_at.parse::<u64>().ok()?;
101:         let signature = URL_SAFE_NO_PAD.decode(encoded_signature).ok()?;
102:         let signed = format!("{version}.{encoded_id}.{encoded_issued_at}");
103:         let mut mac = HmacSha256::new_from_slice(&self.secret).ok()?;
104:         mac.update(signed.as_bytes());
105:         mac.verify_slice(&signature).ok()?;
106:         if issued_at > now.saturating_add(SESSION_FUTURE_SKEW_SECONDS)
107:             || now.saturating_sub(issued_at) > SESSION_LIFETIME_SECONDS
108:         {
109:             return None;
110:         }
111:         Some(owner_key(&id))
112:     }
113: 
114:     fn sign(&self, value: &[u8]) -> [u8; 32] {
115:         let mut mac =
116:             HmacSha256::new_from_slice(&self.secret).expect("HMAC-SHA256 accepts 32-byte keys");
117:         mac.update(value);
118:         mac.finalize().into_bytes().into()
119:     }
120: 
121:     pub fn set_cookie_value(&self, token: &str) -> String {
122:         let secure = if self.secure_cookie { "; Secure" } else { "" };
123:         format!(
124:             "{SESSION_COOKIE}={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age={}{}",
125:             SESSION_LIFETIME_SECONDS, secure
126:         )
127:     }
128: }
129: 
130: fn unix_seconds() -> u64 {
131:     SystemTime::now()
132:         .duration_since(UNIX_EPOCH)
133:         .unwrap_or_default()
134:         .as_secs()
135: }
136: 
137: fn owner_key(id: &[u8; SESSION_ID_BYTES]) -> String {
138:     let mut hash = Sha256::new();
139:     hash.update(OWNER_DOMAIN);
140:     hash.update(id);
141:     hash.finalize()
142:         .iter()
143:         .map(|byte| format!("{byte:02x}"))
144:         .collect()
145: }
