162: #[derive(Clone, Debug, Default)]
163: pub struct Session {
164:     owner_key: Option<String>,
165:     token: Option<String>,
166:     character_id: Option<GrantedCharacterId>,
167:     character_ids: Vec<GrantedCharacterId>,
168: }
