192: pub struct SessionUnavailable;
193: 
194: impl IntoResponse for SessionUnavailable {
195:     fn into_response(self) -> Response {
196:         (
197:             StatusCode::SERVICE_UNAVAILABLE,
198:             "Browser session data is unavailable",
199:         )
200:             .into_response()
201:     }
202: }
203: 
204: impl FromRequestParts<AppState> for Session {
205:     type Rejection = SessionUnavailable;
206: 
207:     async fn from_request_parts(
208:         parts: &mut Parts,
209:         state: &AppState,
210:     ) -> Result<Self, Self::Rejection> {
211:         let jar = CookieJar::from_request_parts(parts, state)
212:             .await
213:             .unwrap_or_default();
214:         let Some(token) = jar
215:             .get(SESSION_COOKIE)
216:             .map(|cookie| cookie.value().to_owned())
217:         else {
218:             return Ok(Session::default());
219:         };
220:         let Some(owner_key) = state.session_codec.verify(&token) else {
221:             // A malformed, expired, or forged cookie has no authority.
222:             return Ok(Session::default());
223:         };
224:         let rows = state
225:             .db
226:             .query_sats::<BackendBrowserCharacterAccess>(&format!(
227:                 "SELECT * FROM backend_browser_character_access WHERE owner_key = {}",
228:                 sql_string_literal(&owner_key)
229:             ))
230:             .await
231:             .map_err(|error| {
232:                 tracing::error!(%error, "failed to resolve browser character grants");
233:                 SessionUnavailable
234:             })?;
235:         if rows.iter().any(|row| row.owner_key != owner_key) {
236:             tracing::error!("browser character access projection returned a foreign owner");
237:             return Err(SessionUnavailable);
238:         }
239:         let character_id = rows
240:             .iter()
241:             .find(|row| row.selected)
242:             .map(|row| GrantedCharacterId(row.character_id));
243:         let character_ids = rows
244:             .into_iter()
245:             .map(|row| GrantedCharacterId(row.character_id))
246:             .collect();
247:         Ok(Session {
248:             owner_key: Some(owner_key),
249:             token: Some(token),
250:             character_id,
251:             character_ids,
252:         })
253:     }
254: }
