256: pub fn redirect_with_session_cookie(
257:     codec: &SessionCodec,
258:     token: Option<&str>,
259:     redirect_to: &str,
260: ) -> Response {
261:     let mut headers = HeaderMap::new();
262:     if let Some(token) = token
263:         && let Ok(cookie) = HeaderValue::from_str(&codec.set_cookie_value(token))
264:     {
265:         headers.append(header::SET_COOKIE, cookie);
266:     }
267:     (headers, Redirect::to(redirect_to)).into_response()
268: }
