270: /// Clearing a character selection keeps the opaque browser identity and all
271: /// grants. The caller must clear the server-side selection first.
272: pub fn clear_character_cookie(redirect_to: &str) -> Response {
273:     Redirect::to(redirect_to).into_response()
274: }
