74:     /// Native imported-source port: bounds are TerrainPack's west/south/east/
75:     /// north degrees. Only coordinate coverage arithmetic consumes this array.
76:     pub(super) fn from_native_source(
77:         source: SourcePackageDigest,
78:         bounds: [f64; 4],
79:         locations: MapLocations<'_>,
80:     ) -> Result<Self> {
81:         let origin = settlement_position(locations.current, bounds).ok_or(MapBuildError::Origin)?;
82:         let mut links = Vec::new();
83:         for settlement in locations.settlements {
84:             let Some(position) = settlement_position(settlement, bounds) else {
85:                 continue;
86:             };
87:             let marker = MapMarker {
88:                 place: StrategicPlaceId::settlement(&settlement.id)?,
89:                 origin: position,
90:                 rank: MapLink::settlement_rank(&settlement.category),
91:                 emphasis: locations.settlement_emphasis(settlement),
92:             };
93:             links.push(MapLink::settlement(marker, settlement));
94:         }
95:         for site in locations.case_sites {
96:             let Some(knowledge) = CaseSiteKnowledgePresentation::from_stage(site.knowledge_stage)
97:             else {
98:                 continue;
99:             };
100:             let Some(position) = case_position(site, bounds) else {
101:                 continue;
102:             };
103:             let marker = MapMarker {
104:                 place: StrategicPlaceId::case_site(&site.case_site_id.value)?,
105:                 origin: position,
106:                 rank: MapMarkerRank::CaseSite,
107:                 emphasis: locations.case_emphasis(site),
108:             };
109:             links.push(MapLink::case_site(marker, site, knowledge));
110:         }
111:         links.sort_by_key(|link| std::cmp::Reverse(link.priority()));
112:         let selected = links.iter().find(|link| {
113:             matches!(
114:                 link.marker.emphasis,
