130:                             )
131:                             .ok_or(MapBuildError::RouteCoordinate)
132:                         })
133:                         .collect::<Result<Vec<_>>>()?,
134:                 )?,
135:                 None => MapRoute::new(MapRouteKind::Estimate, vec![origin, link.marker.origin])?,
