152: impl MapLocations<'_> {
153:     fn settlement_emphasis(&self, settlement: &SettlementView) -> MapMarkerEmphasis {
154:         let selected = self.selected == Some(settlement.id.as_str());
155:         if settlement.id == self.current.id {
156:             return if selected {
157:                 MapMarkerEmphasis::CurrentSelected
158:             } else {
159:                 MapMarkerEmphasis::Current
160:             };
161:         }
162:         if selected {
163:             return MapMarkerEmphasis::Selected;
164:         }
165:         if self.connected.contains(settlement.id.as_str()) {
166:             return MapMarkerEmphasis::Connected;
167:         }
168:         MapMarkerEmphasis::Ordinary
169:     }
170: 
171:     fn case_emphasis(&self, site: &BackendCaseSitePin) -> MapMarkerEmphasis {
172:         if self.selected == Some(site.case_site_id.value.as_str()) {
173:             return MapMarkerEmphasis::Selected;
174:         }
175:         if site.tracked {
176:             return MapMarkerEmphasis::Connected;
177:         }
178:         MapMarkerEmphasis::Ordinary
179:     }
180: }
