182: pub(crate) fn has_geographic_source(settlement: &SettlementView) -> bool {
183:     settlement.source_node_id.is_some()
184:         && Wgs84CoordinateMicrodegrees::from_longitude_latitude_degrees(
185:             settlement.longitude,
186:             settlement.latitude,
187:         )
188:         .is_some()
189: }
