191: /// Native source-coverage adapter; returned positions are checked microdegrees.
192: fn settlement_position(
193:     settlement: &SettlementView,
194:     bounds: [f64; 4],
195: ) -> Option<Wgs84CoordinateMicrodegrees> {
196:     if !has_geographic_source(settlement)
197:         || !adventuresim_world_schema::coordinates_in_bounds(
198:             settlement.longitude,
199:             settlement.latitude,
200:             bounds,
201:         )
202:     {
203:         return None;
204:     }
205:     Wgs84CoordinateMicrodegrees::from_longitude_latitude_degrees(
206:         settlement.longitude,
207:         settlement.latitude,
208:     )
209: }
210: 
211: /// The generated record's geographic flag and E7 leaves are admitted once here.
212: fn case_position(
213:     site: &BackendCaseSitePin,
214:     bounds: [f64; 4],
215: ) -> Option<Wgs84CoordinateMicrodegrees> {
216:     if !site.coordinates_are_geographic {
217:         return None;
218:     }
219:     let point = Wgs84CoordinateE7::new(site.latitude_e_7, site.longitude_e_7)?;
220:     let (longitude, latitude) = point.longitude_latitude_degrees();
221:     if !adventuresim_world_schema::coordinates_in_bounds(longitude, latitude, bounds) {
222:         return None;
223:     }
224:     Wgs84CoordinateMicrodegrees::from_longitude_latitude_degrees(longitude, latitude)
225: }

