369: fn quest_counterparty_strip(case_site_id: &str, counterparties: &[QuestCounterparty]) -> Markup {
370:     html! {
371:         nav class="scene-interactable-strip counterparty-strip" aria-label="People here" {
372:             @for counterparty in counterparties {
373:                 div class="scene-interactable scene-interactable--person counterparty-portrait" {
374:                     span class="scene-interactable-visual" aria-hidden="true" { "?" }
375:                     span class="scene-interactable-label" { (&counterparty.character.name) }
376:                     @if counterparty.contact_decision == crate::spacetimedb::InteractionPresentationDecision::Request {
377:                       form method="post" action=(crate::location_urls::patterns::CONTACT_QUEST_COUNTERPARTY.url([&case_site_id])) {
378:                         input type="hidden" name="target_id" value=(counterparty.character.id);
379:                         input type="hidden" name="contact_ref" value=(&counterparty.contact_ref);
380:                         input type="hidden" name="expected_revision" value=(counterparty.revision);
381:                         input type="hidden" name="action_id" value=(format!("quest-contact:{case_site_id}:{}:{}", counterparty.revision, counterparty.character.id));
382:                         button type="submit" class="btn btn-secondary btn-small" { "Request" }
383:                       }
384:                     } @else {
385:                       button type="button" class="btn btn-secondary btn-small" disabled {
386:                         (if counterparty.contact_decision == crate::spacetimedb::InteractionPresentationDecision::Refused { "Refused" } else { "Unavailable" })
387:                       }
388:                     }
389:                     @if counterparty.character.alive && counterparty.treatment_limb_slug.is_some() && matches!(counterparty.treatment_decision,
390:                         crate::spacetimedb::InteractionPresentationDecision::Request
391:                         | crate::spacetimedb::InteractionPresentationDecision::EmergencyTreatment) {
392:                         form method="post" action=(crate::location_urls::patterns::BANDAGE_QUEST_COUNTERPARTY.url([&case_site_id])) {
393:                             input type="hidden" name="patient_id" value=(counterparty.character.id);
394:                             input type="hidden" name="limb_slug" value=(counterparty.treatment_limb_slug.as_deref().unwrap_or_default());
395:                             input type="hidden" name="action_id" value=(crate::templates::fresh_request_token("treatment"));
396:                             input type="hidden" name="context_ref" value=(&counterparty.contact_ref);
397:                             input type="hidden" name="expected_membership_revision" value=(counterparty.membership_revision);
398:                             button type="submit" class="btn btn-secondary btn-small" {
399:                               (if counterparty.treatment_decision == crate::spacetimedb::InteractionPresentationDecision::EmergencyTreatment { "Emergency treatment" } else { "Request treatment" })
400:                             }
401:                         }
402:                     } @else {
403:                       button type="button" class="btn btn-secondary btn-small" disabled {
404:                         (if counterparty.treatment_decision == crate::spacetimedb::InteractionPresentationDecision::Refused { "Refused" } else { "Unavailable" })
405:                       }
406:                     }
407:                 }
408:             }
409:         }
410:     }
