230:     ));
231:     let selected = injuries
232:         .iter()
233:         .find(|injury| crate::spacetimedb::core_body_region(injury.limb) == selected_limb);
234:     let cut = selected.map_or(0.0, |injury| injury.cut_damage.max(0.0));
235:     let bruise = selected.map_or(0.0, |injury| injury.bruise_damage.max(0.0));
236:     let fracture = selected.map_or(0.0, |injury| injury.fracture_damage.max(0.0));
