240:     let has_kit = surgery_kits > 0;
241:     let self_treatment = active_character.id == patient.id;
242:     let procedure_skill =
243:         |procedure| surgery_procedure_skill(procedure, surgery_check, self_treatment);
244:     let surgery_skill = procedure_skill(SurgeryProcedure::Bandage);
245:     let extraction_skill = procedure_skill(SurgeryProcedure::Extract);
246:     let stitching_skill = procedure_skill(SurgeryProcedure::Stitch);
247:     let close_href = location.preserve_building(if self_treatment {
248:         format!("{}/party/{}", location.base_path(), patient.id)
249:     } else {
250:         format!("{}/party/{}/stats", location.base_path(), patient.id)
251:     });
252:     html! {
253:         div class="character-action-overlay" data-character-action-dialog {
254:             a class="character-action-backdrop" href=(&close_href) aria-label="Close surgery dialog" {}
255:             section class="character-action-dialog surgery-dialog" role="dialog" aria-modal="true" aria-labelledby="surgery-dialog-title" tabindex="-1" {
256:                 header class="character-action-dialog-header" {
257:                     h2 id="surgery-dialog-title" { (patient.name) " — " (surgery_limb_name(selected_limb)) }
258:                     a class="character-action-dialog-close" href=(&close_href) aria-label="Close surgery dialog" { "×" }
259:                 }
260:                 div class="surgery-rail" {
261:                 div class="surgery-supplies" aria-label="Surgery supplies" {
262:                     (surgery_supply("Bandages", "bandage-roll", bandages))
263:                     (surgery_supply("Surgery kits", "medical-pack", surgery_kits))
264:                     (surgery_supply("Splints", "arm-bandage", splints))
265:                     (surgery_supply("Soft soap", "water-drop", soaps))
266:                     (surgery_supply("Disinfecting alcohol", "beer-stein", alcohol_units))
267:                 }
268:                 div class="surgery-procedures" {
269:                     @for projectile in projectiles.iter().filter(|projectile| crate::spacetimedb::core_body_region(projectile.limb) == selected_limb) {
270:                         @let requires_kit = adventuresim_core::surgery::extraction_requires_surgery_kit(projectile.extraction_dc);
271:                         (surgery_procedure_row(&action, match projectile.kind { ProjectileKind::Arrowhead => "Remove arrowhead", ProjectileKind::Ball => "Remove ball" }, match projectile.kind { ProjectileKind::Arrowhead => "plain-arrow", ProjectileKind::Ball => "bullet-visual" }, SurgeryProcedure::Extract, if requires_kit { &[SurgeryItemRequirement::SurgeryKitReusable] } else { &[] }, surgery_duration(SurgeryProcedure::Extract, extraction_skill, projectile.extraction_dc), projectile.extraction_dc,
272:                             extraction_skill, None, if extraction_skill < projectile.extraction_dc { Some("Insufficient Surgery skill") } else if requires_kit && !has_kit { Some("No surgery kit") } else { None }, Some(projectile.id), soaps > 0, true, selected_alcohol))
273:                     }
274:                     (surgery_procedure_row(&action, "Bandage", "bandage-roll", SurgeryProcedure::Bandage, &[SurgeryItemRequirement::BandageConsumed], surgery_duration(SurgeryProcedure::Bandage, surgery_skill, 0.0), 0.0,
275:                         surgery_skill, if cut <= 0.0 { Some("No injury is present") } else { None }, if cut <= 0.0 { Some("No injury is present") } else if bandaged { Some("Already bandaged") } else if bandages == 0 { Some("No bandages") } else { None }, None, soaps > 0, true, selected_alcohol))
276:                     (surgery_procedure_row(&action, "Stitch", "scalpel", SurgeryProcedure::Stitch, &[SurgeryItemRequirement::SurgeryKitReusable], surgery_duration(SurgeryProcedure::Stitch, stitching_skill, 2.0), 2.0,
277:                         stitching_skill, if cut <= 0.0 { Some("No injury is present") } else { None }, if cut <= 0.0 { Some("No injury is present") } else if stitched { Some("Already stitched") } else if stitching_skill < 2.0 { Some("Insufficient Surgery skill") } else if !has_kit { Some("No surgery kit") } else { None }, None, soaps > 0, true, selected_alcohol))
278:                     @if splinted {
279:                         (surgery_procedure_row(&action, "Remove splint", "arm-bandage", SurgeryProcedure::RemoveSplint, &[], surgery_duration(SurgeryProcedure::RemoveSplint, surgery_skill, 0.0), 0.0, surgery_skill, None, None, None, false, false, None))
280:                     } @else {
281:                         (surgery_procedure_row(&action, "Splint", "arm-bandage", SurgeryProcedure::Splint, &[SurgeryItemRequirement::SplintEquipped], surgery_duration(SurgeryProcedure::Splint, surgery_skill, 1.0), 1.0,
282:                             surgery_skill, if fracture <= 0.0 { Some("No injury is present") } else { None }, if fracture <= 0.0 { Some("No injury is present") } else if surgery_skill < 1.0 { Some("Insufficient Surgery skill") } else if splints == 0 { Some("No splints") } else { None }, None, false, false, None))
283:                     }
