314: fn corpse_action_form(
315:     corpse: &BackendCorpse,
316:     location_base: &str,
317:     window: &str,
318:     action_kind: crate::medical::CorpseActionKind,
319:     discipline: &str,
320:     stage: &str,
321:     label: &str,
322:     disabled: Option<&str>,
323: ) -> Markup {
324:     use crate::medical::CorpseActionKind;
325: 
326:     let unauthorized = match action_kind {
327:         CorpseActionKind::Burn => !corpse.penalty_free_burning,
328:         CorpseActionKind::Bury => false,
329:         CorpseActionKind::Exhume => !corpse.exhumation_permission,
330:         CorpseActionKind::Open | CorpseActionKind::Examine => corpse.permission == "none",
331:     };
332:     let destructive = action_kind == CorpseActionKind::Burn;
333:     let action_tag = action_kind.tag();
334:     let warning = if destructive && unauthorized {
335:         "Burning a victim cannot be authorized. It permanently destroys the body and evidence, severely harms family affinity, and brings severe settlement infamy."
336:     } else if destructive {
337:         "Burning this slain enemy carries no social penalty, but permanently destroys the body and all remaining evidence."
338:     } else {
339:         "No permission: proceeding is likely to seriously upset the family and bring substantial settlement infamy."
340:     };
341:     let confirmation = if destructive && unauthorized {
342:         "Burning this victim cannot be authorized. It will permanently destroy the body and evidence, severely harm family affinity, and bring severe settlement infamy. Proceed?"
343:     } else if destructive {
344:         "Burn this slain enemy? This will permanently destroy the body and all remaining evidence."
345:     } else {
346:         "You do not have permission. The family will be seriously upset and the settlement will regard this as infamous. Proceed?"
347:     };
348:     html! {
349:         form method="post"
350:             action=(format!("/corpses/{}/action", corpse.corpse_id))
351:             class=(if unauthorized { "surgery-procedure autopsy-action unauthorized-action" } else { "surgery-procedure autopsy-action" })
352:             data-strategic-tooltip=[(unauthorized || destructive).then_some(warning)]
353:             tabindex=[(unauthorized || destructive).then_some("0")]
354:             onsubmit=[(unauthorized || destructive).then_some(format!("return confirm('{confirmation}')"))] {
355:             input type="hidden" name="action_kind" value=(action_tag);
356:             input type="hidden" name="discipline" value=(discipline);
357:             input type="hidden" name="stage" value=(stage);
358:             input type="hidden" name="expected_revision" value=(corpse.revision);
359:             input type="hidden" name="confirm_unauthorized" value=(if unauthorized { "true" } else { "false" });
360:             input type="hidden" name="action_id" value=(format!("autopsy:{action_tag}:{discipline}:{stage}:{}", corpse.revision));
361:             input type="hidden" name="return_to" value=(format!("{location_base}?corpse={}&medical={window}", corpse.corpse_id));
362:             (game_icon(label, match action_kind {
363:                 CorpseActionKind::Open => "scalpel",
364:                 CorpseActionKind::Burn => "campfire",
365:                 _ => "magnifying-glass",
366:             }))
367:             div class="surgery-procedure-copy" {
368:                 strong { (label) }
369:                 @if destructive && unauthorized {
370:                     small { " Cannot be authorized" }
371:                 } @else if unauthorized {
372:                     small { " Permission missing" }
373:                 }
374:             }
375:             button type="submit"
376:                 class=(if unauthorized || destructive { "btn btn-danger" } else { "btn btn-primary" })
377:                 disabled[disabled.is_some()]
378:                 title=[disabled] {
379:                 (label)
380:             }
381:         }
382:     }
383: }
