684: fn physiology_series_paths(
685:     readings: &[ChartReadingPresentation],
686:     gaps: &[ChartGapPresentation],
687:     region_index: usize,
688:     humour_index: usize,
689: ) -> Vec<String> {
690:     if readings.is_empty() {
691:         return Vec::new();
692:     }
693:     let first_minute = readings
694:         .first()
695:         .map_or(StrategicMinute::ZERO, |reading| reading.minute);
696:     let last_minute = readings
697:         .last()
698:         .map_or(first_minute, |reading| reading.minute);
699:     let mut paths = vec![String::new()];
700: 
701:     for (index, reading) in readings.iter().enumerate() {
702:         let x = physiology_deviation_x(reading.humour_deviations_bps[region_index][humour_index]);
703:         let y = physiology_time_y(reading.minute, first_minute, last_minute);
704:         let begins_after_gap = index > 0
705:             && gaps
706:                 .iter()
707:                 .any(|gap| gap.from < reading.minute && gap.to > readings[index - 1].minute);
708:         if begins_after_gap {
709:             paths.push(String::new());
710:         }
711:         let path = paths.last_mut().expect("at least one trend path");
712:         if path.is_empty() {
713:             path.push_str(&format!("M {x:.1},{y:.1} l 0.01,0 "));
714:         } else {
715:             path.push_str(&format!("L {x:.1},{y:.1} "));
716:         }
717:     }
718:     paths
719: }
