721: fn physiology_relative_day_label(minute: StrategicMinute, today: StrategicMinute) -> String {
722:     let days_ago =
723:         today.elapsed_since(minute) / adventuresim_world_schema::calendar::MINUTES_PER_DAY;
724:     match days_ago {
725:         0 => "Today".to_owned(),
726:         1 => "1 day ago".to_owned(),
727:         days => format!("{days} days ago"),
728:     }
729: }
