731: fn physiology_time_y(
732:     minute: StrategicMinute,
733:     first_minute: StrategicMinute,
734:     last_minute: StrategicMinute,
735: ) -> f32 {
736:     let duration = last_minute.elapsed_since(first_minute);
737:     if duration == 0 {
738:         50.0
739:     } else {
740:         4.0 + minute.elapsed_since(first_minute).min(duration) as f32 * 92.0 / duration as f32
741:     }
742: }
743: 
744: fn physiology_deviation_x(value_bps: i16) -> f32 {
745:     // The notebook is an observational instrument, not a full failure-range
746:     // meter. Expand its common ±35% window so ordinary daily wobble and
747:     // treatment response remain legible; accessible labels retain exact values.
748:     22.0 + (value_bps as f32 / 3_500.0).clamp(-1.0, 1.0) * 18.0
749: }
