776: fn physiology_likelihood(
777:     candidate: &crate::medical::DiseaseLikelihoodPresentation,
778:     tooltip_id: &str,
779: ) -> Markup {
780:     let percent = candidate.likelihood_bps / 100;
781:     let hue = candidate.likelihood_bps as f32 * 120.0
782:         / f32::from(adventuresim_world_schema::BASIS_POINTS_PER_WHOLE);
783:     html! {
784:         li class="physiology-disease-likelihood"
785:             style=(format!("--likelihood-hue: {hue:.1}deg"))
786:             tabindex="0"
787:             aria-describedby=(tooltip_id)
788:             aria-label=(format!("{}: estimated likelihood {percent}%", candidate.label)) {
789:             span { (candidate.label) }
790:             aside id=(tooltip_id) class="physiology-disease-effects" role="tooltip" {
791:                 strong { "Typical humour pattern" }
792:                 @if candidate.typical_effects.is_empty() {
793:                     span { "No characteristic pattern recorded." }
794:                 } @else {
795:                     ul {
796:                         @for effect in &candidate.typical_effects {
797:                             li { (effect) }
798:                         }
799:                     }
800:                 }
801:                 small aria-hidden="true" { (format!("Estimated likelihood: {percent}%")) }
802:             }
803:         }
804:     }
805: }
