1318:     clippy::too_many_arguments,
1319:     reason = "the labelled attribute group is the final Maud boundary for independent presentation fields"
1320: )]
1321: fn attribute_group_with_labels(
1322:     name: &str,
1323:     slug: &str,
1324:     health: f32,
1325:     medical: &MedicalPresentation,
1326:     region: usize,
1327:     surgery: Option<(&str, Option<&str>)>,
1328:     injuries: &[LimbInjury],
1329:     projectiles: &[RetainedProjectile],
1330:     rows: &[(&str, &str, f32)],
1331:     show_labels: bool,
1332:     side: Option<&str>,
1333: ) -> Markup {
1334:     let health = health.clamp(0.0, 1.0);
1335:     html! {
1336:         div class=(match side {
1337:             Some(side) => format!("attribute-group limb-attribute-column {side}"),
1338:             None => "attribute-group".to_owned(),
1339:         }) {
1340:             div class="attribute-group-heading" {
1341:                 span { (name) }
1342:                 @if let Some((path_template, open_limb)) = surgery {
1343:                     @let open = open_limb == Some(slug);
1344:                     a class=(if open { "character-menu-button limb-surgery-button is-open" } else { "character-menu-button limb-surgery-button" })
1345:                         href=(path_template.replace("__limb__", slug)) title=(format!("Treat {name}")) aria-label=(format!("Open surgery menu for {name}"))
1346:                         aria-haspopup="dialog" aria-expanded=(open) {
1347:                         span class="stat-icon" style="--stat-icon: url('/static/icons/game/scalpel.svg')" aria-hidden="true" {}
1348:                         @if open { span class="sr-only" { " (open)" } }
1349:                     }
1350:                 }
1351:             }
1352:             (regional_health_bar(name, health, medical, region, injuries, projectiles))
1353:             @for (attribute_name, icon, value) in rows {
1354:                 (attribute_row(attribute_name, icon, *value, health, show_labels))
1355:             }
1356:         }
1357:     }
1358: }
