1360: fn regional_health_bar(
1361:     name: &str,
1362:     physical_health: f32,
1363:     medical: &MedicalPresentation,
1364:     region: usize,
1365:     injuries: &[LimbInjury],
1366:     projectiles: &[RetainedProjectile],
1367: ) -> Markup {
1368:     let physical_health = physical_health.clamp(0.0, 1.0);
1369:     let physical_damage = 1.0 - physical_health;
1370:     let limb = BodyRegion::ALL[region];
1371:     let injury = injuries
1372:         .iter()
1373:         .find(|injury| crate::spacetimedb::core_body_region(injury.limb) == limb);
1374:     let segments::PhysicalDamage {
1375:         cut,
1376:         frostbite,
1377:         fracture,
1378:         blunt,
1379:     } = segments::PhysicalDamage::new(physical_damage, injury);
1380:     let bandaged = injury.is_some_and(|row| row.bandaged);
1381:     let splinted = injury.is_some_and(|row| row.splint_inventory_item_id.is_some());
1382:     let fracture_label = if splinted {
1383:         "splinted fracture"
1384:     } else {
1385:         "fracture"
1386:     };
1387:     let humour = medical.regional_humours.map(|values| values[region]);
1388:     let values = humour.unwrap_or_default();
1389:     let humour_total = if humour.is_some() {
1390:         values.sanguine.abs()
1391:             + values.phlegmatic.abs()
1392:             + values.choleric.abs()
1393:             + values.melancholic.abs()
1394:     } else {
1395:         medical.concealed_other[region]
1396:     };
1397:     let other = physical_health * humour_total.clamp(0.0, 1.0);
1398:     let okay = (physical_health - other).max(0.0);
1399:     let scale = if humour.is_some() && humour_total > 1.0 {
1400:         other / humour_total
1401:     } else {
1402:         physical_health
1403:     };
1404:     let segments = segments::assessed_humours(humour, scale);
1405:     let reading = if humour.is_some() {
1406:         format!(
1407:             "{name}: {:.0}% sound, {:.0}% cut, {:.0}% frostbite, {:.0}% blunt, {:.0}% {fracture_label}, {:.0}% sanguine, {:.0}% phlegmatic, {:.0}% choleric, {:.0}% melancholic impairment",
1408:             okay * 100.0,
1409:             cut * 100.0,
1410:             frostbite * 100.0,
1411:             blunt * 100.0,
1412:             fracture * 100.0,
1413:             values.sanguine.abs() * scale * 100.0,
1414:             values.phlegmatic.abs() * scale * 100.0,
1415:             values.choleric.abs() * scale * 100.0,
1416:             values.melancholic.abs() * scale * 100.0,
1417:         )
1418:     } else {
1419:         format!(
1420:             "{name}: {:.0}% sound, {:.0}% cut, {:.0}% frostbite, {:.0}% blunt, {:.0}% {fracture_label}, {:.0}% other impairment",
1421:             okay * 100.0,
1422:             cut * 100.0,
1423:             frostbite * 100.0,
1424:             blunt * 100.0,
1425:             fracture * 100.0,
1426:             other * 100.0,
1427:         )
1428:     };
1429:     crate::templates::interface_help::regional_reading(
1430:         limb,
1431:         &reading,
1432:         okay,
1433:         html! {
1434:             span class="attribute-health-bar" role="meter"
1435:                 aria-label=(&reading)
1436:                 aria-valuemin="0" aria-valuemax="100" aria-valuenow=(okay * 100.0) {
1437:                 span class="attribute-health-current" title="Sound" style=(format!("width:{:.1}%", okay * 100.0)) {}
1438:                 span class=(if bandaged { "attribute-health-cut bandaged-cut" } else { "attribute-health-cut" }) title=(if bandaged { "Bandaged cut damage" } else { "Cut damage" }) style=(format!("width:{:.1}%", cut * 100.0)) {}
1439:                 span class="attribute-health-frostbite" title="Frostbite damage" style=(format!("width:{:.1}%", frostbite * 100.0)) {}
1440:                 span class="attribute-health-blunt" title="Blunt damage" style=(format!("width:{:.1}%", blunt * 100.0)) {}
1441:                 span class=(if splinted { "attribute-health-fracture splinted-fracture" } else { "attribute-health-fracture" })
1442:                     title=(if splinted { "Splinted fracture" } else { "Fracture" })
1443:                     style=(format!("width:{:.1}%", fracture * 100.0)) {}
1444:                 @if humour.is_none() && other > 0.0 {
1445:                     span class="attribute-health-other" title="Other impairment"
1446:                         style=(format!("width:{:.1}%", other * 100.0)) {}
1447:                 }
1448:                 @for (humour, class, amount) in segments {
1449:                     @if amount > 0.0 {
1450:                         @let disclosure = adventuresim_core::physiology::humour_disclosure(humour);
1451:                         span class=(class)
1452:                             title=(&disclosure)
1453:                             data-strategic-tooltip=(&disclosure)
1454:                             tabindex="0"
1455:                             aria-label=(format!(
1456:                                 "{}: {:.0}% of this region. {}",
1457:                                 humour.public_name(),
1458:                                 amount * 100.0,
1459:                                 disclosure,
1460:                             ))
1461:                             style=(format!("width:{:.1}%", amount * 100.0)) {}
1462:                     }
1463:                 }
1464:                 @for (projectile_index, projectile) in projectiles.iter().filter(|projectile| crate::spacetimedb::core_body_region(projectile.limb) == limb).enumerate() {
1465:                     span class=(match projectile.kind { ProjectileKind::Arrowhead => "surgery-projectile-icon projectile-arrowhead", ProjectileKind::Ball => "surgery-projectile-icon projectile-ball" })
1466:                         style=(format!("right:{:.2}rem", 0.2 + projectile_index as f32 * 0.75))
1467:                         title=(match projectile.kind { ProjectileKind::Arrowhead => "Retained arrowhead", ProjectileKind::Ball => "Retained ball" }) aria-hidden="true" {}
1468:                 }
1469:             }
1470:         },
1471:     )
1472: }
