1474: fn attribute_row(name: &str, icon: &str, value: f32, health: f32, show_label: bool) -> Markup {
1475:     let effective_value = value * health.clamp(0.0, 1.0);
1476:     let current_width = (effective_value.clamp(0.0, 5.0) / 5.0) * 100.0;
1477:     let damage_width = ((value - effective_value).max(0.0) / 5.0) * 100.0;
1478:     html! {
1479:         div class=(if show_label { "party-attribute-row" } else { "party-attribute-row party-attribute-icon-only" }) {
1480:             (stat_icon(name, "attributes", icon, show_label))
1481:             span class="party-attribute-name" { (name) }
1482:             div class="attribute-rank-bar" data-tooltip-pinnable aria-keyshortcuts="Enter Space"
1483:                 data-strategic-tooltip=(format!("{name}: {effective_value:.1} out of 5"))
1484:                 tabindex="0"
1485:                 role="meter" aria-valuemin="0" aria-valuemax="5" aria-valuenow=(format!("{effective_value:.1}"))
1486:                 aria-label=(format!("{name}: {effective_value:.1} out of 5")) {
1487:                 span class="rank-current" style=(format!("width:{current_width:.1}%")) {}
1488:                 span class="rank-damage" style=(format!("left:{current_width:.1}%;width:{damage_width:.1}%")) {}
1489:             }
1490:         }
1491:     }
1492: }
