1494: pub(super) fn stat_icon(label: &str, category: &str, icon: &str, decorative: bool) -> Markup {
1495:     let path = stat_icon_path(category, icon);
1496:     html! {
1497:         span
1498:             class=(format!("stat-icon stat-icon-{icon}"))
1499:             style=(format!("--stat-icon: url('{path}')"))
1500:             role=[(!decorative).then_some("img")]
1501:             aria-label=[(!decorative).then_some(label)]
1502:             title=[(!decorative).then_some(label)]
1503:             aria-hidden=[decorative.then_some("true")]
1504:         {}
1505:         span class="stat-readable-label" aria-hidden="true" { (label) }
1506:     }
1507: }
