37: /// Visible physical injury components, bounded by the region's known damage.
38: pub(super) struct PhysicalDamage {
39:     pub(super) cut: f32,
40:     pub(super) frostbite: f32,
41:     pub(super) fracture: f32,
42:     pub(super) blunt: f32,
43: }
44: 
45: impl PhysicalDamage {
46:     pub(super) fn new(
47:         physical_damage: f32,
48:         injury: Option<&crate::spacetimedb::LimbInjury>,
49:     ) -> Self {
50:         let cut = injury
51:             .map_or(0.0, |row| row.cut_damage)
52:             .min(physical_damage);
53:         let frostbite = injury
54:             .map_or(0.0, |row| row.frostbite_damage)
55:             .min((physical_damage - cut).max(0.0));
56:         let total_blunt = injury
57:             .map_or(physical_damage - cut - frostbite, |row| {
58:                 row.bruise_damage.max(row.fracture_damage)
59:             })
60:             .min((physical_damage - cut - frostbite).max(0.0));
61:         let fracture = injury
62:             .map_or(0.0, |row| row.fracture_damage)
63:             .min(total_blunt);
64:         let blunt = (total_blunt - fracture).max(0.0);
65:         Self {
66:             cut,
67:             frostbite,
68:             fracture,
69:             blunt,
70:         }
71:     }
72: }

