326: fn settlement_alias_labels(
327:     settlement: &SettlementView,
328:     aliases: &[SettlementAlias],
329: ) -> Vec<String> {
330:     let canonical = settlement.name.to_lowercase();
331:     let mut labels = BTreeSet::new();
332:     for alias in aliases {
333:         let label = alias.prefix.as_ref().map_or_else(
334:             || alias.name.trim().to_owned(),
335:             |prefix| format!("{} {}", prefix.trim(), alias.name.trim()),
336:         );
337:         if !label.is_empty() && label.to_lowercase() != canonical {
338:             labels.insert(label);
339:         }
340:     }
341:     let total = labels.len();
342:     let mut labels: Vec<_> = labels.into_iter().take(8).collect();
343:     if total > labels.len() {
344:         labels.push(format!("and {} more", total - labels.len()));
345:     }
346:     labels
347: }
