381: pub(crate) fn settlement_description(population_level: i32) -> &'static str {
382:     match population_level {
383:         i32::MIN..=1 => "A quiet cluster of farmsteads and cottages.",
384:         2 => "A quaint hamlet gathered around a well-worn road.",
385:         3 => "A modest village serving the surrounding countryside.",
386:         4 => "A busy market town with a steady flow of travelers.",
387:         5 => "A prosperous town enclosed by crowded streets.",
388:         _ => "A large and bustling city whose streets rarely fall silent.",
389:     }
390: }
