392: pub(super) fn format_distance(distance_m: u64) -> String {
393:     format!("{:.1} km", distance_m as f64 / 1_000.0)
394: }
395: 
396: pub(super) fn format_population(settlement: &SettlementView) -> String {
397:     match settlement.population_estimate {
398:         0 => population_description(settlement.population_level).to_string(),
399:         population => format!("approximately {}", format_number(population)),
400:     }
401: }
402: 
403: fn format_number(value: u32) -> String {
404:     let digits = value.to_string();
405:     let first_group = match digits.len() % 3 {
406:         0 => 3,
407:         remainder => remainder,
408:     };
409:     let mut formatted = digits[..first_group].to_string();
410:     for group in digits.as_bytes()[first_group..].chunks(3) {
411:         formatted.push(',');
412:         formatted.push_str(std::str::from_utf8(group).expect("population digits are valid UTF-8"));
413:     }
414:     formatted
415: }
416: 
417: pub(super) fn format_journey_time(minutes: u64) -> String {
418:     let hours = minutes / 60;
419:     let minutes = minutes % 60;
420:     if hours == 0 {
421:         format!("{minutes} min")
422:     } else if minutes == 0 {
423:         format!("{hours} h")
424:     } else {
425:         format!("{hours} h {minutes} min")
426:     }
427: }
