449: 
450: impl VisualStageKind {
451:     const fn tag(self) -> &'static str {
452:         match self {
453:             Self::Settlement => "settlement",
454:             Self::Map => "map",
455:             Self::Route => "route",
456:             Self::Camp => "camp",
457:             Self::Quest => "quest",
458:             Self::Alchemy => "alchemy",
459:             Self::Service => "service",
460:             Self::Chest => "chest",
461:             Self::Campfire => "campfire",
462:             Self::Character => "character",
463:         }
464:     }
465: 
466:     const fn scene_label(self) -> &'static str {
467:         match self {
468:             Self::Settlement => "At the settlement gates",
469:             Self::Map | Self::Route => "Roads and destinations",
470:             Self::Camp => "Camp beside the road",
471:             Self::Quest => "Encounter ground",
472:             Self::Alchemy => "The apothecary workbench",
473:             Self::Service => "At the counter",
474:             Self::Chest => "Shared party stores",
475:             Self::Campfire | Self::Character => "Adventurer profile",
476:         }
477:     }
478: }
