480: pub(crate) fn visual_stage(kind: VisualStageKind, title: &str, description: &str) -> Markup {
481:     let scene_label = kind.scene_label();
482:     html! {
483:         figure class=(format!("service-visual service-visual-{}", kind.tag())) {
484:             div class="service-visual-scene" role="img" aria-label=(format!("{title}. {description}")) {
485:                 span class="visual-scene-sky" aria-hidden="true" {}
486:                 span class="visual-scene-horizon" aria-hidden="true" {}
487:                 span class="visual-scene-route" aria-hidden="true" {}
488:                 span class="visual-scene-caption" {
489:                     strong { (title) }
490:                     span { (scene_label) }
491:                 }
492:             }
493:             figcaption { (description) }
494:         }
495:     }
496: }
