100:                                 title="Profile" aria-label=(format!("Profile of {}", member.name)) {
101:                                 (game_icon("Profile", "person"))
102:                             }
103:                             @if member.alive && active_character.is_some_and(|character| character.alive) {
104:                             a href=(format!("{}/party/{}/social", location_path, member.id))
105:                                 class=(format!("portrait-tab party-social-action{}", if persistently_notified { " party-social-notified" } else { "" }))
106:                                 data-portrait-tab="conversation" title=(if notified { format!("Open {}'s Recent Tidings ({} morale concerns)", member.name, member.social_notification_count) } else { format!("Talk to {}", member.name) })
107:                                 aria-label=(if notified { format!("Open conversation with {} to Recent Tidings; {} unaddressed morale concerns", member.name, member.social_notification_count) } else { format!("Open conversation with {}", member.name) }) {
108:                                 span class="party-action-icon"
