112:                                     span class="party-social-notification" aria-hidden="true" {
113:                                         (member.social_notification_count)
114:                                     }
115:                                 }
116:                             }
117:                             a href=(format!("{}/party/{}/inventory", location_path, member.id))
118:                                 class="portrait-tab" data-portrait-tab="inventory" aria-label=(format!("Inventory of {}", member.name))
119:                                 title=(if is_active { "Open inventory and discard items".to_string() } else { format!("Compare inventory with {}", member.name) }) {
120:                                 span class="party-action-icon"
121:                                     style="--party-action-icon: url('/static/icons/game/knapsack.svg')"
122:                                     role="img" aria-label="Inventory" {}
123:                             }
124:                             }
125:                     }
126:             });
127:             CharacterPortraitView {
128:                 id: member.id,
129:                 name: &member.name,
130:                 alive: member.alive,
131:                 active: is_active,
132:                 selected: selected_character_id == Some(member.id),
133:                 href: inspection_href,
134:                 title: format!("Inspect {}", member.name),
135:                 aria_label: format!("Inspect {}", member.name),
136:                 decoration: Some(html! {
