138:                     span class="incapacitation-wheel"
139:                         data-strategic-condition-wheel=(member.id)
140:                         role="img"
141:                         aria-label="Loading strategic condition"
142:                         title="Loading strategic condition" tabindex="0" {}
143:                     }
144:                 }),
145:                 badge: None,
146:                 actions,
147:             }
148:         })
149:         .collect::<Vec<_>>();
150:     character_portrait_overlay("Active party", inventory, &portraits)
151: }
