154:                 @let rent_label = format!("Rent: {} coin every 30 days", offer.rent_per_period);
155:                 @let purchase_label = format!("Purchase: {} coin", offer.purchase_price);
156:                 @let upkeep_label = format!("Owner upkeep: {} maintenance plus {} property tax every 30 days", offer.owner_maintenance_per_period, offer.property_tax_per_period);
157:                 @let leisure_label = format!("Leisure morale bonus: {} percent", format_morale_percent(offer.leisure_morale_basis_points));
158:                 @let rent_confirmation = format!("return confirm('Rent this {tier} residence for {} coin every 30 days?')", offer.rent_per_period);
159:                 @let buy_confirmation = format!("return confirm('Buy this {tier} residence for {} coin? Ongoing owner costs are {} coin every 30 days.')", offer.purchase_price, owner_cost);
160:                 article class="residence-offer" data-residence-tier=(residence_tier_id(offer.tier)) {
161:                     div class="residence-offer-heading" { (decorative_game_icon("house")) strong { (tier) " home " (offer.building_id) } }
