165:                         (residence_meter("hammer-nails", "upkeep", &upkeep_label, owner_cost, max_owner_cost))
166:                         (residence_meter("sun", "leisure", &leisure_label, u32::from(offer.leisure_morale_basis_points), max_leisure))
167:                     }
