259: fn family_panel(relationship: Option<&RelationshipPresentation>) -> Markup {
260:     html! {
261:             @if let Some(relationship) = relationship {
262:                 div class="household-visual" role="group" aria-label="Household and family" {
263:                 @if let Some(spouse_name) = &relationship.spouse_name {
264:                     div class="household-member" aria-label=(format!("Spouse: {spouse_name}")) title=(format!("Spouse: {spouse_name}")) {
265:                         (decorative_game_icon("heart-beats")) span class="household-member-name" { (spouse_name) }
266:                     }
267:                 }
268:                 @if let Some(partner_name) = &relationship.courtship_partner_name {
269:                     @let courtship_kind = relationship.courtship_kind.unwrap_or(CourtshipKind::Informal);
270:                     @let informal = courtship_kind == CourtshipKind::Informal;
271:                     @let courtship_kind_label = match courtship_kind { CourtshipKind::Formal => "formal", CourtshipKind::Informal => "informal" };
272:                     @let courtship_visibility = if !informal { "; formal and public" } else if relationship.courtship_exposed { "; known to family" } else { "; private" };
273:                     @let courtship_icon = if !informal { "rose" } else if relationship.courtship_exposed { "eye-target" } else { "lockpicks" };
274:                     @let courtship_label = format!("{courtship_kind_label} courtship with {partner_name}{courtship_visibility}");
275:                     div class="household-member" title=(&courtship_label) aria-label=(&courtship_label) {
276:                         (decorative_game_icon("rose")) span class="household-member-name" { (partner_name) }
277:                         span class="household-member-state" aria-hidden="true" {
278:                             (decorative_game_icon(courtship_icon))
279:                         }
280:                     }
281:                 }
282:                 @if let Some(wedding) = &relationship.wedding {
283:                     @let wedding_label = format!("Wedding {}, {} days remaining", wedding.date_label, wedding.days_remaining);
284:                     @let wedding_progress = DAYS_PER_YEAR.saturating_sub(wedding.days_remaining.min(DAYS_PER_YEAR)) * 100 / DAYS_PER_YEAR;
285:                     (household_progress("calendar", "wedding", &wedding_label, wedding_progress))
286:                 }
287:                 @if let Some(days) = relationship.pregnancy_due_days {
288:                     @let pregnancy_label = format!("Expected birth in about {days} days");
289:                     @let pregnancy_progress = 270_u64.saturating_sub(days.min(270)) * 100 / 270;
290:                     (household_progress("stomach", "pregnancy", &pregnancy_label, pregnancy_progress))
291:                 }
292:                 @for child in &relationship.children {
293:                     @let stage = child_stage_label(child.stage);
294:                     @let stage_id = child_stage_id(child.stage);
295:                     @let (focus_icon, focus) = child_activity_presentation(child.stage, child.focus);
296:                     @let state = if !child.alive { "deceased" } else if child.adult_playable { "adult and available in the character roster" } else { stage };
297:                     @let label = format!("Child: {}; {state}; focus: {focus}; maturity {} percent", child.name, child.maturity_basis_points / 100);
298:                     div class=(format!("household-child household-child-stage-{stage_id}")) aria-label=(&label) title=(&label) data-strategic-tooltip=(&label) {
299:                         div class="household-member" {
300:                             (decorative_game_icon("person")) span class="household-member-name" { (&child.name) }
301:                             span class="household-member-state" aria-hidden="true" {
302:                                 (decorative_game_icon(if !child.alive { "death-skull" } else if child.adult_playable { "crown" } else { focus_icon }))
303:                             }
304:                         }
305:                         (household_progress("person", "maturity", &label, u64::from(child.maturity_basis_points) / 100))
306:                     }
307:                 }
308:                 }
309:             }
310:     }
311: }
