313: fn format_morale_percent(basis_points: u16) -> String {
314:     let whole = basis_points / 100;
315:     let fraction = basis_points % 100;
316:     if fraction == 0 {
317:         whole.to_string()
318:     } else {
319:         format!("{whole}.{fraction:02}")
320:     }
321: }
