35: pub fn settlement_map_page(
36:     settlement: &SettlementView,
37:     settlements: &[SettlementView],
38:     case_sites: &[crate::spacetimedb::BackendCaseSitePin],
39:     terrain: Option<&crate::routes::travel::TerrainPlanner>,
40:     destinations: &[TravelDestination],
41:     selected_id: Option<&str>,
42:     active_character: Option<&CharacterView>,
43:     active_party: Option<&PartyView>,
44:     _party_members: &[CharacterView],
45:     default_rest_minutes: u64,
46:     soap_preview: SoapRestPreview,
47:     can_travel: bool,
48:     provision_forecast: Option<&TravelProvisionForecast>,
49:     provisioning_path: Option<&str>,
50:     is_current_settlement: bool,
51:     abandonable_quest: Option<&BackendContract>,
52:     logged_in_as: Option<&str>,
53: ) -> Markup {
54:     let selected = selected_id.and_then(|id| destinations.iter().find(|entry| entry.id == id));
55:     let selected_town = selected_id.and_then(|id| settlements.iter().find(|entry| entry.id == id));
56:     let base_path = crate::location_urls::patterns::SETTLEMENT.url([&settlement.id]);
57:     let connected_ids = destinations
58:         .iter()
59:         .filter(|destination| !destination.round_trip_destination)
60:         .map(|destination| destination.id.as_str())
61:         .collect::<BTreeSet<_>>();
62:     let content = html! {
63:         (map_destination_list_with_context(
64:             destinations,
65:             selected_id,
66:             &base_path,
67:             is_current_settlement.then_some(MapCurrentLocation {
68:                 name: &settlement.name,
69:             }),
70:             abandonable_quest.map(|quest| MapAbandonableQuest {
71:                 id: &quest.id,
72:                 title: &quest.title,
73:             }),
74:             active_party.filter(|_| can_travel).map(|_| html! {
75:                 section class="rest-service-menu map-rest-menu" aria-label="Rest" {
76:                     (party_rest_menu(
77:                         &format!("{base_path}/rest"),
78:                         "map-rest",
79:                         "Rest here",
80:                         "Rest party",
81:                         default_rest_minutes,
82:                         None,
83:                         soap_preview,
84:                     ))
85:                 }
86:             }),
87:         ))
88:         main class="center-content settlement-main settlement-map-main" {
89:             @if settlement.source_node_id.is_some() {
90:                 @if let Some(terrain) = terrain {
91:                     (crate::strategic_map::strategic_map(
92:                         &terrain.pack,
93:                         settlements,
94:                         case_sites,
95:                         settlement,
96:                         &connected_ids,
97:                         selected_id,
98:                         &base_path,
99:                         selected.and_then(|destination| destination.terrain_route.as_ref()),
100:                     ))
101:                 } @else {
102:                     (crate::strategic_map::strategic_map_bundle_unavailable())
103:                 }
104:             } @else {
105:                 (crate::strategic_map::strategic_map_unavailable(&settlement.name))
106:             }
107:         }
108:         (map_destination_detail(
109:             selected,
110:             selected_town,
111:             selected_town.is_some_and(|destination| destination.id == settlement.id),
112:             can_travel,
113:             provisioning_path,
114:             provision_forecast,
115:             active_party,
116:             active_party.is_some_and(|party| party.leader_id == active_character.map_or(0, |character| character.id)),
117:             None,
118:             &base_path,
119:         ))
120:     };
121:     settlement_layout_with_session(
122:         &format!("{} map", settlement.name),
123:         &settlement.name,
124:         &settlement.id,
125:         &settlement.category,
126:         "map",
127:         Some(&settlement.religion_id),
128:         Some(&settlement.economy),
129:         content,
130:         logged_in_as,
131:     )
132: }
