212:                                         data-emergency-alcohol-days=(forecast.emergency_alcohol_days)
213:                                         data-ration-kcal=(forecast.ration_kcal)
214:                                         data-waterskin-ml=(forecast.waterskin_capacity_ml) {}
215:                                 }
216:                                 strong { (&destination.name) }
