230:                             button type="submit" class="btn btn-danger btn-small" { "Abandon active quest" }
231:                         }
232:                     }
233:                 }
234:             }))
235:             }
236:             @if let Some(rest_menu) = rest_menu {
237:                 (rest_menu)
238:             }
239:         }
240:     }
241: }
