468: pub(crate) fn travel_planner_bar_for(
469:     destination_name: &str,
470:     destination_description: &str,
471:     selected_round_trip: bool,
472:     journey_minutes: u64,
473:     camp_stop_minutes: &str,
474:     camp_forecasts: &str,
475:     camp_fatigue_percent: u8,
476:     journey: Option<&PartyJourney>,
477:     journey_route: Option<&PartyJourneyRouteView>,
478:     provision_forecast: Option<&TravelProvisionForecast>,
479:     preview_departure_minute: StrategicMinute,
480:     preview_elapsed_minutes: u64,
481:     preview_segments: &str,
482:     terrain_spans: &str,
483: ) -> Markup {
484:     let journey_origin_name = journey.map_or("", |item| item.origin.name());
485:     let journey_destination_name = journey.map_or("", |item| item.destination.name());
486:     let journey_turnaround_minutes = journey
487:         .filter(|item| item.destination.case_site_id().is_some())
488:         .map_or(0, |item| item.total_movement_minutes);
489:     let journey_total_movement_minutes = journey.map_or(0, |item| {
490:         if item.destination.case_site_id().is_some() {
491:             item.total_movement_minutes.saturating_add(
492:                 journey_route
493:                     .and_then(|route| route.return_route.as_ref())
494:                     .map_or(item.total_movement_minutes, |route| route.minutes),
495:             )
496:         } else {
497:             item.total_movement_minutes
498:         }
499:     });
500:     let journey_completed_movement_minutes =
501:         journey.map_or(0, |item| item.completed_movement_minutes);
502:     let journey_camp_stops = journey.map_or_else(String::new, |item| {
503:         format_camp_stops(&item.reached_camp_movement_minutes)
504:     });
505:     let journey_forecast_stops = journey.map_or_else(String::new, |item| {
506:         let mut stops = item
507:             .forecast_camp_intervals
508:             .iter()
509:             .map(|interval| interval.movement_minute)
510:             .collect::<Vec<_>>();
511:         if item.destination.case_site_id().is_some() {
512:             stops.extend(
513:                 item.reached_camp_movement_minutes
514:                     .iter()
515:                     .chain(
516:                         item.forecast_camp_intervals
517:                             .iter()
518:                             .map(|interval| &interval.movement_minute),
519:                     )
520:                     .rev()
521:                     .map(|minute| journey_total_movement_minutes.saturating_sub(*minute)),
522:             );
523:         }
524:         format_camp_stops(&stops)
525:     });
526:     html! {
527:         section class="travel-planner" data-travel-planner
528:             data-camp-fatigue-percent=(camp_fatigue_percent)
529:             data-selected-name=(destination_name)
530:             data-selected-description=(destination_description)
531:             data-selected-round-trip=(selected_round_trip)
532:             data-selected-minutes=(journey_minutes)
533:             data-selected-camp-stops=(camp_stop_minutes)
534:             data-selected-camp-forecasts=(camp_forecasts)
535:             data-journey-origin-name=(journey_origin_name)
536:             data-journey-destination-name=(journey_destination_name)
537:             data-journey-total-movement-minutes=(journey_total_movement_minutes)
538:             data-journey-turnaround-minutes=(journey_turnaround_minutes)
539:             data-journey-completed-movement-minutes=(journey_completed_movement_minutes)
540:             data-departure-minute=(journey.map_or(preview_departure_minute.get(), |item| item.departure_minute.minutes))
541:             data-total-elapsed-minutes=(journey.map_or(preview_elapsed_minutes, |item| item.total_elapsed_minutes))
542:             data-completed-elapsed-minutes=(journey.map_or(0, |item| item.completed_elapsed_minutes))
543:             data-itinerary-segments=(preview_segments)
544:             data-terrain-spans=(terrain_spans)
545:             data-journey-camp-stops=(journey_camp_stops)
546:             data-journey-forecast-stops=(journey_forecast_stops)
547:             data-provision-planning-minutes=[provision_forecast.map(|row| row.planning_minutes)]
548:             data-provision-living-members=[provision_forecast.map(|row| row.living_members)]
