613: fn format_terrain_spans(destination: &TravelDestination) -> String {
614:     destination
615:         .terrain_route
616:         .as_ref()
617:         .map_or_else(String::new, |route| {
618:             route
619:                 .spans
620:                 .iter()
621:                 .map(|span| (span, 0_u64))
622:                 .chain(
623:                     destination
624:                         .return_terrain_route
625:                         .iter()
626:                         .flat_map(|return_route| {
627:                             return_route.spans.iter().map(|span| (span, route.minutes))
628:                         }),
629:                 )
630:                 .filter_map(|(span, offset)| {
631:                     let kind = match span.surface {
632:                         adventuresim_terrain::Surface::Road => "road",
633:                         adventuresim_terrain::Surface::Open => "open",
634:                         adventuresim_terrain::Surface::SparseWoods => "sparse-woods",
635:                         adventuresim_terrain::Surface::DeepWoods => "deep-woods",
636:                         adventuresim_terrain::Surface::Wetland => "wetland",
637:                         adventuresim_terrain::Surface::Water => return None,
638:                     };
639:                     Some(format!(
640:                         "{kind},{},{},{},{},{},{},{},{}",
641:                         span.start_minute.saturating_add(offset),
642:                         span.duration_minutes,
643:                         span.check_millirank,
644:                         span.terrain.plains,
645:                         span.terrain.forest,
646:                         span.terrain.hills,
647:                         span.terrain.wetlands,
648:                         span.terrain.urban,
649:                     ))
650:                 })
651:                 .collect::<Vec<_>>()
652:                 .join("|")
653:         })
654: }
