283: /// The look direction for the character.
284: ///
285: /// Usually, this is populated by the camera.
286: #[derive(Component, Clone, Reflect, PartialEq, Debug, Default, MapEntities)]
287: #[cfg_attr(feature = "serialize", derive(serde::Serialize, serde::Deserialize))]
288: #[cfg_attr(feature = "serialize", reflect(Serialize, Deserialize))]
289: #[reflect(Component)]
290: pub struct CharacterLook {
291:     /// The yaw the character is looking at (relative to the world).
292:     pub yaw: f32,
293:     /// The pitch the character is looking at (relative to the character).
294:     ///
295:     /// For normal movement, this is not necessary, but for actions like swimming, this affects the
296:     /// direction the character will swim in.
297:     pub pitch: f32,
298: }
299: 
300: impl CharacterLook {
301:     /// Converts a quaternion into the corresponding look values.
302:     ///
303:     /// Usually this `quat` comes from the camera.
304:     pub fn from_quat(quat: Quat) -> Self {
305:         let (yaw, pitch, _) = quat.to_euler(EulerRot::YXZ);
306:         Self { yaw, pitch }
307:     }
308: 
309:     /// Applies this look direction to `quat`.
310:     ///
311:     /// This preserves the roll of `quat`.
312:     pub fn apply_to_quat(&self, quat: &mut Quat) {
313:         let (_, _, roll) = quat.to_euler(EulerRot::YXZ);
314:         *quat = Quat::from_euler(EulerRot::YXZ, self.yaw, self.pitch, roll);
315:     }
316: 
317:     /// Creates a [`Quat`] corresponding to this look direction.
318:     ///
319:     /// Unlike [`Self::apply_to_quat`], this does not mutate an existing [`Quat`], so there's no
320:     /// roll to preserve.
321:     pub fn to_quat(&self) -> Quat {
322:         Quat::from_euler(EulerRot::YXZ, self.yaw, self.pitch, 0.0)
323:     }
324: }
325: 
