7: 
8: pub(super) struct RepeatedEvaluationSnapshot {
9:     scenario: ScenarioMetadata<'static>,
10:     scenario_frame: usize,
11:     bones: CapturedBones,
12:     contact_sequence: ContactSequence,
13:     landing_sequence: adventuresim_tactical_core::animation::LandingSequence,
14:     event_count: usize,
15:     leg_ik: Option<LegIkDiagnostics>,
16: }
17: 
18: #[derive(Debug)]
19: pub(super) enum RepeatedBoneMismatch {
20:     MissingBone { bone: BoneRole },
21:     UnexpectedBone { bone: BoneRole },
22:     Transform {
23:         bone: BoneRole,
24:         position_delta: NonnegativeLength,
25:         rotation_delta: AngularMagnitudeDegrees,
26:     },
27:     InvalidObservation { bone: BoneRole, cause: AnimationValueError },
28: }
29: 
30: impl RepeatedBoneMismatch {
31:     fn bone(&self) -> BoneRole {
32:         match self {
33:             Self::MissingBone { bone } | Self::UnexpectedBone { bone }
34:             | Self::Transform { bone, .. } | Self::InvalidObservation { bone, .. } => *bone,
35:         }
36:     }
37: }
38: 
39: impl CaptureSequence {
40:     pub(super) fn record_repeated_evaluation(
41:         &mut self,
42:         frame: &PlannedFrame,
43:         bones: &CapturedBones,
44:         skeleton: &SkeletonState,
45:         leg_ik: Option<LegIkDiagnostics>,
46:     ) {
47:         let event_count = self.presentation_events.len();
48:         if self.view_index == 0 {
49:             self.repeated_evaluation_baseline = Some(RepeatedEvaluationSnapshot {
50:                 scenario: frame.scenario.clone(),
51:                 scenario_frame: frame.scenario_frame,
52:                 bones: bones.clone(),
53:                 contact_sequence: skeleton.contact_sequence,
54:                 landing_sequence: skeleton.landing_sequence,
55:                 event_count,
56:                 leg_ik,
57:             });
58:         } else if let Some(baseline) = &self.repeated_evaluation_baseline {
59:             let repeated_evaluation_matches =
60:                 baseline.matches(frame, bones, skeleton, event_count, leg_ik);
61:             self.repeated_evaluation_valid &= repeated_evaluation_matches;
62:         } else {
63:             self.repeated_evaluation_valid = false;
64:             warn!(scenario = frame.scenario.label(), scenario_frame = frame.scenario_frame,
65:                 "repeated animation evaluation has no baseline observation");
66:         }
67:     }
68: }
69: 
70: impl RepeatedEvaluationSnapshot {
71:     fn matches(
72:         &self,
73:         frame: &PlannedFrame,
74:         bones: &CapturedBones,
75:         skeleton: &SkeletonState,
76:         event_count: usize,
77:         leg_ik: Option<LegIkDiagnostics>,
78:     ) -> bool {
79:         let bone_mismatch = repeated_bone_mismatch(&self.bones, bones);
80:         let bones_match = bone_mismatch.is_none();
81:         let repeated_evaluation_matches = self.scenario == frame.scenario
82:             && self.scenario_frame == frame.scenario_frame
83:             && bones_match
84:             && self.contact_sequence == skeleton.contact_sequence
85:             && self.landing_sequence == skeleton.landing_sequence
86:             && self.event_count == event_count
87:             && repeated_leg_ik_matches(self.leg_ik, leg_ik);
88:         if !repeated_evaluation_matches
89:             && let Some(mismatch) = &bone_mismatch
90:         {
91:             let bone = mismatch.bone();
92:             let (position_delta, rotation_delta) = match mismatch {
93:                 RepeatedBoneMismatch::Transform { position_delta, rotation_delta, .. } => {
94:                     (Some(position_delta.metres()), Some(rotation_delta.degrees()))
95:                 }
96:                 _ => (None, None),
97:             };
98:             let invalid_cause = match mismatch {
99:                 RepeatedBoneMismatch::InvalidObservation { cause, .. } => Some(cause),
100:                 _ => None,
101:             };
102:             warn!(
103:                 scenario = frame.scenario.label(),
104:                 scenario_frame = frame.scenario_frame,
105:                 bone = report_bone_label(bone)
106:                     .map(str::to_owned)
107:                     .unwrap_or_else(|| format!("{bone:?}")),
108:                 ?position_delta,
109:                 ?rotation_delta,
110:                 ?invalid_cause,
111:                 ?mismatch,
112:                 "repeated animation evaluation changed a captured bone"
113:             );
114:         }
115:         if !repeated_evaluation_matches && bone_mismatch.is_none() {
116:             warn!(
117:                 scenario = frame.scenario.label(),
118:                 scenario_frame = frame.scenario_frame,
119:                 baseline_contact = self.contact_sequence.encoded(),
120:                 contact = skeleton.contact_sequence.encoded(),
121:                 baseline_landing = self.landing_sequence.encoded(),
122:                 landing = skeleton.landing_sequence.encoded(),
123:                 baseline_events = self.event_count,
124:                 events = event_count,
125:                 "repeated animation evaluation changed non-bone state"
126:             );
127:         }
