129:     }
130: }
131: 
132: pub(super) fn repeated_bone_mismatch(
133:     expected: &CapturedBones,
134:     actual: &CapturedBones,
135: ) -> Option<RepeatedBoneMismatch> {
136:     if let Some(bone) = expected.keys().find(|bone| !actual.contains_key(**bone)) {
137:         return Some(RepeatedBoneMismatch::MissingBone { bone: *bone });
138:     }
139:     if let Some(bone) = actual.keys().find(|bone| !expected.contains_key(**bone)) {
140:         return Some(RepeatedBoneMismatch::UnexpectedBone { bone: *bone });
141:     }
142:     // Equal key sets retain the same lexical report order in both captures.
143:     expected.iter().zip(actual.iter()).find_map(|((name, expected), (_, actual))| {
144:         let position_delta =
145:             Vec3::from_array(expected.position).distance(Vec3::from_array(actual.position));
146:         let expected_rotation = Quat::from_array(expected.rotation_xyzw);
147:         let actual_rotation = Quat::from_array(actual.rotation_xyzw);
148:         // `acos` quantizes identical f32 quaternions to roughly 0.056-0.079
149:         // degrees on some frames. Treat a direct dot match as identity, then
150:         // retain the angular report for genuine changes.
151:         let rotation_dot = expected_rotation.dot(actual_rotation).abs();
152:         let rotation_delta = if rotation_dot >= 1.0 - 0.000_001 {
153:             0.0
154:         } else {
155:             expected_rotation
156:                 .angle_between(actual_rotation)
157:                 .to_degrees()
158:         };
159:         // Re-evaluating one logical tick must be visually identical. Keep only
160:         // sub-half-millimetre/sub-twentieth-degree numeric noise.
161:         let position_delta = match NonnegativeLength::from_metres(position_delta) {
162:             Ok(delta) => delta,
163:             Err(cause) => return Some(RepeatedBoneMismatch::InvalidObservation { bone: *name, cause }),
164:         };
165:         let rotation_delta = match AngularMagnitudeDegrees::from_degrees(rotation_delta) {
166:             Ok(delta) => delta,
167:             Err(cause) => return Some(RepeatedBoneMismatch::InvalidObservation { bone: *name, cause }),
168:         };
169:         (position_delta.metres() > 0.0005 || rotation_delta.degrees() > 0.05).then_some(
170:             RepeatedBoneMismatch::Transform { bone: *name, position_delta, rotation_delta },
171:         )
172:     })
173: }
