1: //! Scene-root fixture motion and explicit capture ground-observation authority.
2: 
3: use super::*;
4: use adventuresim_building_generator::spatial_geometry::{
5:     CoordinateAxis, GeometryError, GeometryRole, Position,
6: };
7: use fabelgeist_geometry::{GeometryResult, SignedLength};
8: use adventuresim_tactical_core::{
9:     city_layout::grounding::SupportElevation,
10:     scene_coordinates::{Scene, ScenePlanPoint},
11: };
12: 
13: #[derive(Clone, Copy)]
14: pub(super) enum CaptureGround {
15:     Terrain,
16:     AuthoredPlane(SupportElevation),
17: }
18: 
19: impl CaptureGround {
20:     pub(super) fn collect_bones(
21:         self,
22:         subject: Entity,
23:         bones: &Query<(&HumanoidBone, &GlobalTransform)>,
24:         terrain: &SceneTerrain,
25:     ) -> GeometryResult<CapturedBones> {
26:         bones
27:             .iter()
28:             .filter(|(bone, _)| bone.owner == subject && report_bone_label(bone.role).is_some())
29:             .map(|(bone, transform)| {
30:                 let rotation = transform.rotation();
31:                 let elevation = match self {
32:                     CaptureGround::AuthoredPlane(height) => Some(height),
33:                     CaptureGround::Terrain => {
34:                         ScenePlanPoint::from_metres(transform.translation().xz())
35:                             .and_then(|point| terrain.height_at(point))
36:                     }
37:                 };
38:                 Ok((
39:                     bone.role,
40:                     BoneSample {
41:                         position: transform.translation().to_array(),
42:                         rotation_xyzw: [rotation.x, rotation.y, rotation.z, rotation.w],
43:                         terrain_clearance_metres: elevation
44:                             .map(|height| {
45:                                 SignedLength::from_metres(transform.translation().y - height.metres())
46:                             })
47:                             .transpose()?,
48:                     },
49:                 ))
50:             })
51:             .collect()
52:     }
53: }
54: 
55: impl CaptureSequence {
56:     /// Admit the initial scene root while retaining its current scale.
57:     pub(super) fn initial_root(
58:         &mut self,
59:         terrain: &SceneTerrain,
60:         mut transform: Transform,
61:     ) -> Option<Transform> {
62:         let ground = self.admit_terrain_height(terrain, ScenePlanPoint::ORIGIN)?;
63:         let position = self.admit_scene_position(Vec3::new(
64:             0.0,
65:             ground.metres() + CAPTURE_ROOT_GROUND_OFFSET_METRES,
66:             0.0,
67:         ))?;
68:         transform.translation = position.metres();
69:         transform.rotation = Quat::from_rotation_y(std::f32::consts::PI);
70:         Some(transform)
71:     }
72: 
73:     /// Native scene-root translation advances by the existing controller step;
74:     /// admit its footprint before queries and its complete position before Bevy.
75:     pub(super) fn fixture_root_position(
76:         &mut self,
77:         terrain: &SceneTerrain,
78:         current: Vec3,
79:         frame: &PlannedFrame,
80:         motion: &subject_motion::CaptureMotion,
81:         terrain_ik: TerrainIkMode,
82:     ) -> Option<Position<Scene>> {
83:         let horizontal = current.xz() + motion.world_velocity.xz() * motion.elapsed.seconds();
84:         let point = self.admit_terrain_point(horizontal)?;
85:         let vertical = if is_quickstep_scenario(&frame.scenario) {
86:             let ground = self.admit_terrain_height(terrain, point)?.metres()
87:                 + CAPTURE_ROOT_GROUND_OFFSET_METRES;
88:             ground
89:                 + quickstep_fixture_vertical_state(frame.scenario_frame)
90:                     .0
91:                     .max(0.0)
92:         } else if terrain_ik.is_enabled() {
93:             self.admit_terrain_height(terrain, point)?.metres() + CAPTURE_ROOT_GROUND_OFFSET_METRES
94:         } else {
95:             current.y
96:         };
97:         self.admit_scene_position(Vec3::new(horizontal.x, vertical, horizontal.y))
98:     }
99: 
100:     /// The full ragdoll scenario lowers the production-like controller root
101:     /// while its capsule island resolves contact against the same terrain.
102:     pub(super) fn full_ragdoll_root(
103:         &mut self,
104:         terrain: &SceneTerrain,
105:         mut transform: Transform,
106:         frame: &PlannedFrame,
107:     ) -> Option<Transform> {
108:         let fall = ((frame.scenario_frame + 4) as f32 / 8.0).clamp(0.0, 1.0);
109:         transform.rotation = Quat::from_rotation_y(std::f32::consts::PI)
110:             * Quat::from_rotation_x(1.25 * smoothstep01(fall));
111:         let ground = self.admit_terrain_height(terrain, ScenePlanPoint::ORIGIN)?;
112:         transform.translation.y =
113:             ground.metres() + CAPTURE_ROOT_GROUND_OFFSET_METRES - 0.62 * smoothstep01(fall);
114:         transform.translation = self.admit_scene_position(transform.translation)?.metres();
115:         Some(transform)
116:     }
117: 
118:     /// An authored flat plane is measured from the visible scene-root datum;
119:     /// failure to admit that observation cannot select terrain instead.
120:     pub(super) fn capture_ground(
121:         &mut self,
122:         terrain_ik: TerrainIkMode,
123:         subject: Vec3,
124:     ) -> Option<CaptureGround> {
125:         if terrain_ik.is_enabled() {
126:             return Some(CaptureGround::Terrain);
127:         }
128:         let height = subject.y - CAPTURE_ROOT_GROUND_OFFSET_METRES;
129:         if let Some(height) = SupportElevation::from_metres(height) {
130:             return Some(CaptureGround::AuthoredPlane(height));
131:         }
132:         self.admission = CaptureAdmission::Rejected(RejectedCaptureAdmission::Geometry(
133:             GeometryError::NonFinite {
134:                 role: GeometryRole::Elevation,
135:                 axis: CoordinateAxis::Y,
136:             },
137:         ));
138:         None
139:     }
140: }
