50:         let Some(direction) = Vec3::from_array(after.world_travel_direction).try_normalize() else {
51:             duration = 0.0;
52:             continue;
53:         };
54:         let behind = [
55:             (BoneRole::ThighLeft, BoneRole::FootLeft),
56:             (BoneRole::ThighRight, BoneRole::FootRight),
57:         ]
58:         .into_iter()
59:         .all(|(hip, foot)| {
