185:             support.zip(release_active).is_some_and(|(support, release_active)| {
186:                 support.fraction() > 0.05
187:                     || authored.zip(solved).is_some_and(|(authored, solved)| {
188:                         let authored = Vec3::from_array(authored);
189:                         let solved = Vec3::from_array(solved);
190:                         planned.is_some() || release_active || solved.distance(authored) <= 0.03
191:                     })
192:             })
193:         },
194:     )
195: }
