197: pub(super) fn ordinary_unplanned_release_transition_is_valid(
198:     before: &FrameSample,
199:     after: &FrameSample,
200:     before_solve: Option<[f32; 3]>,
201:     after_solve: Option<[f32; 3]>,
202:     before_release_target: Option<[f32; 3]>,
203:     after_release_target: Option<[f32; 3]>,
204: ) -> bool {
205:     before_solve
206:         .zip(after_solve)
207:         .is_some_and(|(before_solve, after_solve)| {
208:             let before_solve_world = Vec3::from_array(before_solve);
209:             let after_solve_world = Vec3::from_array(after_solve);
210:             let before_solve = target_body_local(before, before_solve_world);
211:             let after_solve = target_body_local(after, after_solve_world);
212:             let frozen_goal_converges = before_release_target.zip(after_release_target).is_none_or(
213:                 |(before_goal, after_goal)| {
214:                     let before_goal = Vec3::from_array(before_goal);
215:                     let after_goal = Vec3::from_array(after_goal);
216:                     target_body_local(before, before_goal)
217:                         .distance(target_body_local(after, after_goal))
218:                         > 0.002
219:                         || after_solve_world.distance(after_goal)
220:                             <= before_solve_world.distance(before_goal) + 0.001
221:                 },
222:             );
223:             let step_limit = if frame_uses_run_motion_budget(after) {
224:                 // Run's owner-space target advances up to 8.75 cm per sample;
225:                 // its terrain scenario independently rejects rendered foot
226:                 // motion above 9.5 cm. Walk/settle retains the 5.5 cm budget.
227:                 0.095
228:             } else {
229:                 0.055
230:             };
231:             after_solve.distance(before_solve) <= step_limit && frozen_goal_converges
232:         })
233: }
234: 
235: pub(super) fn frame_uses_run_motion_budget(frame: &FrameSample) -> bool {
236:     let run_speed_threshold = (walk_locomotion_profile()
237:         .reference_speed
238:         .metres_per_second()
239:         + run_locomotion_profile().reference_speed.metres_per_second())
240:         * 0.5;
241:     frame.speed_metres_per_second.metres_per_second() >= run_speed_threshold
242: }
