246:     reason = "this domain boundary names each independent input explicitly"
247: )]
248: pub(super) fn ordinary_planned_transition_is_valid(
249:     before: &FrameSample,
250:     after: &FrameSample,
251:     foot: BoneRole,
252:     before_plan: Option<[f32; 3]>,
253:     after_plan: Option<[f32; 3]>,
254:     before_solve: Option<[f32; 3]>,
255:     after_solve: Option<[f32; 3]>,
256:     after_support: UnitInterval,
257:     release_active: bool,
258: ) -> bool {
259:     before_plan
260:         .zip(after_plan)
261:         .zip(before_solve.zip(after_solve))
262:         .is_none_or(|((before_plan, after_plan), (before_solve, after_solve))| {
263:             let before_plan = Vec3::from_array(before_plan);
264:             let after_plan = Vec3::from_array(after_plan);
265:             let before_solve_world = Vec3::from_array(before_solve);
266:             let after_solve_world = Vec3::from_array(after_solve);
267:             if frame_uses_run_motion_budget(after) {
268:                 let plan_is_frozen = before_plan.distance(after_plan) <= 0.002;
269:                 let atomic_acquisition_retarget = after_support.fraction() > 0.05
270:                     && !release_active
271:                     && after_solve_world.distance(after_plan) <= 0.02;
272:                 let owned_airborne_replan = after_support.fraction() <= 0.5 && release_active;
273:                 let rendered_step = before.bones.get(foot).zip(after.bones.get(foot)).map(
274:                     |(before_foot, after_foot)| {
275:                         target_body_local(after, Vec3::from_array(after_foot.position)).distance(
276:                             target_body_local(before, Vec3::from_array(before_foot.position)),
277:                         )
278:                     },
279:                 );
280:                 (plan_is_frozen || atomic_acquisition_retarget || owned_airborne_replan)
281:                     && rendered_step.is_some_and(|step| step <= 0.095)
282:             } else {
283:                 before_plan.distance(after_plan) <= 0.002
284:                     && after_solve_world.distance(after_plan)
285:                         <= before_solve_world.distance(before_plan) + 0.005
286:             }
287:         })
288: }
