306: pub(super) fn reported_support_contacts_are_valid(frames: &[FrameSample]) -> bool {
307:     let tolerance = sole_contact_tolerance_metres();
308:     frames.iter().all(|frame| {
309:         if is_quickstep_scenario(&frame.scenario)
310:             || frame.scenario.kind() == ScenarioKind::Attack
311:             || frame.action != SkeletonAction::None
312:             || (!scenario_uses_terrain_ik(&frame.scenario)
313:                 && frame.weapon_guard == WeaponGuardState::Lowered)
314:         {
315:             // In an FK-only comparison the semantic weights describe authored
316:             // loading, not a claim that the procedural solver owns contact.
317:             // Attack captures exercise the same raised-guard locomotion and
318:             // terrain IK ownership used outside attacks.
319:             return true;
320:         }
321:         [
322:             (BoneRole::FootLeft, frame.ik_left_support_weight),
323:             (BoneRole::FootRight, frame.ik_right_support_weight),
324:         ]
325:         .into_iter()
326:         .all(|(foot, support)| {
327:             let quickstep_toe_contact = if is_quickstep_scenario(&frame.scenario) {
328:                 let toe = if foot == BoneRole::FootLeft {
329:                     BoneRole::ToeLeft
330:                 } else {
331:                     BoneRole::ToeRight
332:                 };
333:                 frame
334:                     .bones
335:                     .get(toe)
336:                     .and_then(|bone| bone.terrain_clearance_metres)
337:                     .is_some_and(|clearance| clearance.metres().abs() <= tolerance.metres())
338:             } else {
339:                 false
340:             };
341:             support.is_some_and(|support| {
342:                 support.fraction() < 0.95
343:                     || quickstep_toe_contact
344:                     || frame
345:                         .bones
346:                         .get(foot)
347:                         .and_then(|bone| bone.terrain_clearance_metres)
348:                         .is_some_and(|ankle_clearance| {
349:                             (ankle_clearance.metres() - measured_ankle_sole_offset_metres().metres()).abs()
350:                                 <= if frame.scenario.is(ScenarioId::RaisedGuardStationaryTurn) {
351:                                     // The combat stance is deliberately
352:                                     // non-flat-footed; its planted pole target
353:                                     // has a measured 1.11 cm ankle residual.
354:                                     0.012
355:                                 } else {
356:                                     tolerance.metres()
357:                                 }
358:                         })
359:             })
360:         })
361:     })
362: }
