364: pub(super) fn terrain_run_contacts_are_valid(frames: &[FrameSample]) -> AnimationValueResult<bool> {
365:     let run = frames
366:         .iter()
367:         .filter(|frame| frame.scenario.is(ScenarioId::TerrainSteadyRun55))
368:         .collect::<Vec<_>>();
369:     if run.is_empty() {
370:         return Ok(true);
371:     }
372:     let warmed = phase_validation_frames(&run);
373:     let mut acquisitions = Vec::new();
374:     let mut last = None;
375:     for frame in &warmed {
376:         let (left, right) = frame.required_ik_support()?;
377:         let support = if left.fraction().max(right.fraction()) < 0.5 {
378:             None
379:         } else {
380:             Some(left.fraction() >= right.fraction())
381:         };
382:         if support != last {
383:             if let Some(left) = support {
384:                 acquisitions.push(left);
385:             }
386:             last = support;
387:         }
388:     }
389:     Ok(acquisitions.len() >= 4
390:         && acquisitions.contains(&true)
391:         && acquisitions.contains(&false)
392:         && acquisitions.windows(2).all(|pair| pair[0] != pair[1])
393:         && maximum_no_support_seconds(&warmed)?.measured().is_some_and(|elapsed| {
394:                 (0.08..=0.20).contains(&elapsed.seconds())
395:             }))
396: }
