398: fn metric_frames_after_warmup<'a>(
399:     metadata: &ScenarioMetadata<'_>,
400:     frames: &[&'a FrameSample],

401: ) -> Vec<&'a FrameSample> {
402:     // Terrain conformity calibrates retained pelvis/plant state during its first cycle.
403:     if metadata.kind() == ScenarioKind::Terrain {
404:         phase_validation_frames(frames)
405:     } else {
406:         frames.to_vec()
407:     }
408: }
