21: pub(in crate::animation_viewer::report) fn minimum_flight_sole_clearance(
22:     frames: &[&FrameSample],
23: ) -> ReportResult<Observation<SignedLength>> {
24:     if frames.is_empty() {
25:         return Ok(Observation::Unavailable(UnavailableReason::NoFrames));
26:     }
27:     let mut minimum: Option<SignedLength> = None;
28:     for frame in frames.iter().filter(|frame| {
29:         frame.left_support_weight.fraction() <= 0.001
30:             && frame.right_support_weight.fraction() <= 0.001
31:     }) {
32:         for foot in [BoneRole::FootLeft, BoneRole::FootRight] {
33:             let Some(bone) = frame.bones.get(foot) else {
34:                 return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: foot }));
35:             };
36:             let Some(ankle) = bone.terrain_clearance_metres else {
37:                 return Ok(Observation::Unavailable(UnavailableReason::MissingTerrainClearance { bone: foot }));
38:             };
39:             // Preserve the capture's existing flight-sole numerical offset.
40:             let clearance = SignedLength::from_metres(ankle.metres() - 0.085)?;
41:             minimum = Some(minimum.map_or(clearance, |value| value.min(clearance)));
42:         }
43:     }
44:     Ok(minimum.map_or(Observation::NotApplicable, Observation::Measured))
