48:     frames: &[&FrameSample],
49: ) -> ReportResult<Observation<SignedLengthRange>> {
50:     let mut bounds: Option<SignedLengthRange> = None;
51:     for frame in frames {
52:         let procedural_solve_active =
53:             frame.ik_left_solve_target.is_some() || frame.ik_right_solve_target.is_some();
54:         let support = if procedural_solve_active {
55:             Some(frame.required_ik_support()?)
56:         } else {
57:             None
58:         };
59:         for (foot, left) in [(BoneRole::FootLeft, true), (BoneRole::FootRight, false)] {
60:             let is_contact = if let Some((left_support, right_support)) = support {
61:                 (if left { left_support } else { right_support }).fraction() >= 0.95
62:             } else {
63:                 let phase = frame.gait_phase.cycles().rem_euclid(1.0);
64:                 let distance = if left {
65:                     phase.min(1.0 - phase)
66:                 } else {
67:                     (phase - 0.5).abs()
68:                 };
69:                 distance <= 0.035
70:             };
71:             if !is_contact {
72:                 continue;
73:             }
74:             let Some(bone) = frame.bones.get(foot) else {
75:                 return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: foot }));
76:             };
77:             let Some(ankle) = bone.terrain_clearance_metres else {
78:                 return Ok(Observation::Unavailable(UnavailableReason::MissingTerrainClearance { bone: foot }));
79:             };
80:             let clearance = SignedLength::from_metres(
81:                 ankle.metres() - measured_ankle_sole_offset_metres().metres(),
