1: //! Captured continuity, upper-body loop seams and world-plant drift.
2: 
3: use super::*;
4: use adventuresim_tactical_core::animation::{AngularMagnitudeDegrees, NonnegativeLength};
5: 
6: struct ContinuityBoneSample {
7:     bone: BoneRole,
8:     from_frame: usize,
9:     to_frame: usize,
10:     displacement: NonnegativeLength,
11:     rotation: AngularMagnitudeDegrees,
12: }
13: 
14: impl ScenarioContinuityMetrics {
15:     pub(in crate::animation_viewer::report) fn measure(
16:         metadata: &ScenarioMetadata<'_>,
17:         frames: &[&FrameSample],
18:     ) -> AnimationValueResult<Observation<Self>> {
19:         if frames.len() < 3 {
20:             return Ok(Observation::Unavailable(UnavailableReason::NoAdjacentFrames));
21:         }
22:         let mut metrics = Self {
23:             maximum_root_relative_step_metres: NonnegativeLength::ZERO,
24:             maximum_leg_root_relative_step_metres: NonnegativeLength::ZERO,
25:             maximum_foot_root_relative_step_metres: NonnegativeLength::ZERO,
26:             maximum_knee_root_relative_step_metres: NonnegativeLength::ZERO,
27:             worst_displacement: None,
28:             maximum_bone_rotation_step_degrees: AngularMagnitudeDegrees::ZERO,
29:             maximum_foot_rotation_step_degrees: AngularMagnitudeDegrees::ZERO,
30:             worst_rotation: None,
31:             maximum_supported_foot_slip_metres_per_frame: Observation::NotApplicable,
32:         };
33:         // Frame zero establishes retained procedural state. Preserve the first
34:         // real pre-roll transition (1→2) as the beginning of continuity gates.
35:         for pair in frames.windows(2).skip(1) {
36:             let (before, after) = (pair[0], pair[1]);
37:             for (bone, _) in REPORT_BONES {
38:                 if !before.bones.contains_key(bone) || !after.bones.contains_key(bone) {
39:                     return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone }));
40:                 }
41:             }
42:             for name in before.bones.keys() {
43:                 match ContinuityBoneSample::measure(before, after, *name)? {
44:                     Observation::Measured(sample) => metrics.include(sample),
45:                     Observation::Unavailable(reason) => return Ok(Observation::Unavailable(reason)),
46:                     Observation::NotApplicable => return Ok(Observation::NotApplicable),
47:                 }
48:             }
49:             match supported_foot_slip(metadata, before, after)? {
50:                 Observation::Measured(slip) => {
51:                     if !matches!(metrics.maximum_supported_foot_slip_metres_per_frame, Observation::Unavailable(_)) {
52:                         let maximum = metrics.maximum_supported_foot_slip_metres_per_frame.measured().copied().map_or(slip, |maximum| maximum.max(slip));
53:                         metrics.maximum_supported_foot_slip_metres_per_frame = Observation::Measured(maximum);
54:                     }
55:                 }
56:                 Observation::Unavailable(reason) => {
57:                     metrics.maximum_supported_foot_slip_metres_per_frame = Observation::Unavailable(reason);
58:                 }
59:                 Observation::NotApplicable => {}
60:             }
61:         }
62:         Ok(Observation::Measured(metrics))
63:     }
64:     fn include(&mut self, sample: ContinuityBoneSample) {
65:         if sample.displacement > self.maximum_root_relative_step_metres {
66:             self.maximum_root_relative_step_metres = sample.displacement;
67:             self.worst_displacement = Some(ContinuityLocation {
68:                 bone: sample.bone, from_frame: sample.from_frame, to_frame: sample.to_frame, value: sample.displacement,
69:             });
70:         }
71:         if is_leg_bone(&sample.bone) { self.maximum_leg_root_relative_step_metres = self.maximum_leg_root_relative_step_metres.max(sample.displacement); }
72:         if is_foot_bone(&sample.bone) { self.maximum_foot_root_relative_step_metres = self.maximum_foot_root_relative_step_metres.max(sample.displacement); }
73:         if is_knee_bone(&sample.bone) { self.maximum_knee_root_relative_step_metres = self.maximum_knee_root_relative_step_metres.max(sample.displacement); }
74:         if is_foot_bone(&sample.bone) { self.maximum_foot_rotation_step_degrees = self.maximum_foot_rotation_step_degrees.max(sample.rotation); }
75:         if sample.rotation > self.maximum_bone_rotation_step_degrees {
76:             self.maximum_bone_rotation_step_degrees = sample.rotation;
77:             self.worst_rotation = Some(ContinuityLocation {
78:                 bone: sample.bone, from_frame: sample.from_frame, to_frame: sample.to_frame, value: sample.rotation,
79:             });
80:         }
81:     }
82: 
83: }
84: 
85: impl ContinuityBoneSample {
86:     fn measure(before: &FrameSample, after: &FrameSample, bone: BoneRole) -> AnimationValueResult<Observation<Self>> {
87:         let Some(before_bone) = before.bones.get(bone) else {
88:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone }));
89:         };
90:         let Some(after_bone) = after.bones.get(bone) else {
91:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone }));
92:         };
93:         // The native body-frame projection preserves root subtraction before rotation.
94:         let after_position = target_body_local(after, Vec3::from_array(after_bone.position));
95:         let before_position = target_body_local(before, Vec3::from_array(before_bone.position));
96:         Ok(Observation::Measured(Self {
97:             bone,
98:             from_frame: before.scenario_frame,
99:             to_frame: after.scenario_frame,
100:             displacement: NonnegativeLength::from_metres(after_position.distance(before_position))?,
101:             rotation: AngularMagnitudeDegrees::from_degrees(body_local_rotation(after, after_bone).angle_between(body_local_rotation(before, before_bone)).to_degrees())?,
102:         }))
103:     }
104: }
105: 
106: impl LoopSeamMetrics {
107:     pub(in crate::animation_viewer::report) fn measure(
108:         metadata: &ScenarioMetadata<'_>,
109:         frames: &[&FrameSample],
110:     ) -> AnimationValueResult<Observation<Self>> {
111:         if !expects_loop_seam(metadata) {
112:             return Ok(Observation::NotApplicable);
113:         }
114:         let mut maximum: Option<Self> = None;
115:         for pair in frames.windows(2).filter(|pair| (pair[1].gait_phase.cycles() - pair[0].gait_phase.cycles()).abs() > 0.5) {
116:             match Self::between(pair[0], pair[1])? {
117:                 Observation::Measured(seam) => {
118:                     maximum = Some(maximum.map_or(seam, |maximum| Self {
119:                         position_metres: maximum.position_metres.max(seam.position_metres),
120:                         rotation_degrees: maximum.rotation_degrees.max(seam.rotation_degrees),
121:                     }));
122:                 }
123:                 Observation::Unavailable(reason) => return Ok(Observation::Unavailable(reason)),
124:                 Observation::NotApplicable => return Ok(Observation::NotApplicable),
125:             }
126:         }
127:         Ok(maximum.map_or(Observation::Unavailable(UnavailableReason::NoCompletedCycle), Observation::Measured))
128:     }
129: }
130: 
131: impl LoopSeamMetrics {
132: pub(in crate::animation_viewer::report) fn between(
133:     first: &FrameSample,
134:     last: &FrameSample,
135: ) -> AnimationValueResult<Observation<LoopSeamMetrics>> {
136:     for (bone, _) in REPORT_BONES.into_iter().filter(|(bone, _)| !is_leg_bone(bone)) {
137:         if !first.bones.contains_key(bone) || !last.bones.contains_key(bone) {
138:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone }));
139:         }
140:     }
141:     let mut metrics = LoopSeamMetrics { position_metres: NonnegativeLength::ZERO, rotation_degrees: AngularMagnitudeDegrees::ZERO };
142:     for (name, a) in &first.bones {
143:         // Stateful foot locking owns lower-body continuity through plant slip
144:         // and drift; the loop seam measures repeatable authored upper body.
145:         if is_leg_bone(name) { continue; }
146:         let Some(b) = last.bones.get(*name) else {
147:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: *name }));
148:         };
149:         let Some((last_position, first_position)) = body_local(last, *name).zip(body_local(first, *name)) else {
150:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: *name }));
151:         };
152:         metrics.position_metres = metrics.position_metres.max(NonnegativeLength::from_metres(last_position.distance(first_position))?);
153:         metrics.rotation_degrees = metrics.rotation_degrees.max(AngularMagnitudeDegrees::from_degrees(body_local_rotation(first, a).angle_between(body_local_rotation(last, b)).to_degrees())?);
154:     }
155:     Ok(Observation::Measured(metrics))
156: }
157: 
158: }
159: 
160: pub(in crate::animation_viewer::report) fn maximum_planted_foot_drift(
161:     metadata: &ScenarioMetadata<'_>,
162:     frames: &[&FrameSample],
163: ) -> AnimationValueResult<Observation<NonnegativeLength>> {
164:     if frames.is_empty() {
165:         return Ok(Observation::Unavailable(UnavailableReason::NoFrames));
166:     }
167:     let mut maximum: Option<NonnegativeLength> = None;
168:     for (foot, left) in [(BoneRole::FootLeft, true), (BoneRole::FootRight, false)] {
169:         let mut anchor = None;
170:         for frame in frames {
171:             if metadata.kind() != ScenarioKind::Terrain && !frame.guard_action { anchor = None; continue; }
172:             let support = if left { frame.left_support_weight.fraction() } else { frame.right_support_weight.fraction() };
173:             // Full plants remain separate from the blended per-frame slip gate.
174:             if support >= FULL_PLANT_SUPPORT_WEIGHT {
175:                 let Some(bone) = frame.bones.get(foot) else {
176:                     return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: foot }));
177:                 };
178:                 let position = Vec3::from_array(bone.position).xz();
179:                 let origin = anchor.get_or_insert(position);
180:                 let drift = NonnegativeLength::from_metres(position.distance(*origin))?;
181:                 maximum = Some(maximum.map_or(drift, |maximum| maximum.max(drift)));
182:             } else { anchor = None; }
183:         }
184:     }
185:     Ok(maximum.map_or(Observation::NotApplicable, Observation::Measured))
186: }
