1: //! Peak prominence and phase-window checks for sampled visual height.
2: 
3: use super::*;
4: 
5: // Ignore sub-3 mm sampling noise, but reject any additional visible beat in
6: // the phase-owned vertical curve.
7: const HEIGHT_PEAK_PROMINENCE_METRES: f32 = 0.003;
8: const PASSING_PEAK_PHASE_WINDOW: f32 = 0.10;
9: 
10: pub(super) fn prominent_height_peaks(samples: &[HeightSample]) -> ReportResult<Observation<HeightPeaks>> {
11:     if samples.len() < 3 {
12:         return Ok(Observation::Unavailable(UnavailableReason::InsufficientHeightSamples));
13:     }
14:     let mut peaks = Vec::new();
15:     for (index, sample) in samples.iter().enumerate() {
16:         let phase = sample.phase().cycles();
17:         let height = sample.height().metres();
18:         let previous = samples[(index + samples.len() - 1) % samples.len()].height().metres();
19:         let next = samples[(index + 1) % samples.len()].height().metres();
20:         if height <= previous || height < next {
21:             continue;
22:         }
23:         let Some(left_minimum) = samples
24:             .iter()
25:             .filter_map(|candidate| {
26:                 let candidate_phase = candidate.phase().cycles();
27:                 let candidate_height = candidate.height().metres();
28:                 let distance = (phase - candidate_phase).rem_euclid(1.0);
29:                 (distance > 0.0 && distance <= 0.125).then_some(candidate_height)
30:             })
31:             .reduce(f32::min) else {
32:                 return Ok(Observation::Unavailable(UnavailableReason::MissingHeightNeighborhood));
33:             };
34:         let Some(right_minimum) = samples
35:             .iter()
36:             .filter_map(|candidate| {
37:                 let candidate_phase = candidate.phase().cycles();
38:                 let candidate_height = candidate.height().metres();
39:                 let distance = (candidate_phase - phase).rem_euclid(1.0);
40:                 (distance > 0.0 && distance <= 0.125).then_some(candidate_height)
41:             })
42:             .reduce(f32::min) else {
43:                 return Ok(Observation::Unavailable(UnavailableReason::MissingHeightNeighborhood));
44:             };
45:         let prominence = fabelgeist_geometry::SignedLength::from_metres(height - left_minimum.max(right_minimum))?;
46:         if prominence.metres() >= HEIGHT_PEAK_PROMINENCE_METRES {
47:             peaks.push(phase);
48:         }
49:     }
50:     let phase_distance = |phase: f32, target: f32| {
51:         let distance = (phase - target).abs();
52:         distance.min(1.0 - distance)
53:     };
54:     let in_passing_windows = [0.25, 0.75].into_iter().all(|target| {
55:         peaks
56:             .iter()
57:             .filter(|&&phase| phase_distance(phase, target) <= PASSING_PEAK_PHASE_WINDOW)
58:             .count()
59:             == 1
60:     });
61:     Ok(Observation::Measured(HeightPeaks {
62:         count: peaks.len(),
63:         in_passing_windows,
64:     }))
65: }

