163:     frames: &[&FrameSample],
164: ) -> ReportResult<Observation<SignedLength>> {
165:     let mut minimum: Option<SignedLength> = None;
166:     for frame in frames {
167:         for LegBones { hip: hip_role, knee: knee_role, foot: foot_role } in LEGS {
168:             let mut positions = [Vec3::ZERO; 3];
169:             for (index, bone) in [hip_role, knee_role, foot_role].into_iter().enumerate() {
170:                 let Some(sample) = frame.bones.get(bone) else {
171:                     return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone }));
172:                 };
173:                 positions[index] = Vec3::from_array(sample.position);
174:             }
175:             let [hip, knee, foot] = positions;
176:             let axis = foot - hip;
177:             if axis.length_squared() > 0.0001 {
178:                 let closest = hip + axis * (knee - hip).dot(axis) / axis.length_squared();
179:                 let Some(forward) = Vec3::from_array(frame.world_travel_direction).try_normalize() else {
180:                     return Ok(Observation::Unavailable(UnavailableReason::NoMotionSamples));
181:                 };
182:                 let value = SignedLength::from_metres((knee - closest).dot(forward))?;
183:                 minimum = Some(minimum.map_or(value, |minimum| minimum.min(value)));
184:             }
185:         }
186:     }
187:     Ok(minimum.map_or(Observation::Unavailable(if frames.is_empty() { UnavailableReason::NoFrames } else { UnavailableReason::DegenerateLegAxis }), Observation::Measured))
188: }
