1: //! Supported-foot displacement from current captured native bone positions.
2: 
3: use super::*;
4: use adventuresim_tactical_core::animation::{AngularMagnitudeDegrees, NonnegativeLength};
5: 
6: pub(super) fn supported_foot_slip(
7:     metadata: &ScenarioMetadata<'_>,
8:     before: &FrameSample,
9:     after: &FrameSample,
10: ) -> AnimationValueResult<Observation<NonnegativeLength>> {
11:     let mut maximum_slip: Option<NonnegativeLength> = None;
12:     let body_turn = AngularMagnitudeDegrees::from_degrees(Quat::from_array(before.body_rotation_xyzw)
13:         .angle_between(Quat::from_array(after.body_rotation_xyzw))
14:         .to_degrees())?;
15:     for (foot, support) in [
16:         (
17:             BoneRole::FootLeft,
18:             before
19:                 .left_support_weight
20:                 .fraction()
21:                 .min(after.left_support_weight.fraction()),
22:         ),
23:         (
24:             BoneRole::FootRight,
25:             before
26:                 .right_support_weight
27:                 .fraction()
28:                 .min(after.right_support_weight.fraction()),
29:         ),
30:     ] {
31:         // A body turn deliberately slides an old world plant onto
32:         // its new anatomical side corridor. Treat that bounded
33:         // adaptation separately from skating under a stable body.
34:         let procedural_plant_active =
35:             metadata.kind() == ScenarioKind::Terrain || (before.guard_action && after.guard_action);
36:         if !procedural_plant_active || support < 0.9 || body_turn.degrees() > 0.5 {
37:             continue;
38:         }
39:         let Some((a, b)) = before.bones.get(foot).zip(after.bones.get(foot)) else {
40:             return Ok(Observation::Unavailable(UnavailableReason::MissingBone { bone: foot }));
41:         };
42:         let distance = (Vec3::from_array(b.position) - Vec3::from_array(a.position)).xz().length();
43:         let distance = NonnegativeLength::from_arithmetic(distance)?;
44:         maximum_slip = Some(maximum_slip.map_or(distance, |maximum| maximum.max(distance)));
45:     }
46:     Ok(maximum_slip.map_or(Observation::NotApplicable, Observation::Measured))
47: }
