22:     let finite_transforms = frames.iter().all(FrameSample::has_finite_bone_transforms);
23:     let all_scenarios_complete = capture_scenarios_complete(&frames, &plan);
24:     let all_artifacts_written = capture_artifacts_written(&output, &frames);
25:     let continuity_within_review_bounds = continuity_within_review_bounds(&scenarios);
26:     let no_ground_penetration = scenarios.iter().all(|metrics| {
27:         if metrics.scenario.has(ScenarioFeature::Dive)
28:             || metrics.scenario.has(ScenarioFeature::GetUp)
29:         {
30:             // These authored whole-body poses intentionally put the character
31:             // on the surface. Ankle/sole contact metrics assume upright feet
32:             // and report false penetration once the feet rotate onto a side
33:             // or heel; visual review and finite/continuity gates remain active.
34:             true
