73: 
74: impl BufferBuilder {
75:     fn push(&mut self, bytes: &[u8], target: Option<u32>) -> usize {
76:         while !self.bytes.len().is_multiple_of(4) {
77:             self.bytes.push(0);
78:         }
79:         let offset = self.bytes.len();
80:         self.bytes.extend_from_slice(bytes);
81:         let mut view = json!({
82:             "buffer": 0,
83:             "byteOffset": offset,
84:             "byteLength": bytes.len(),
85:         });
86:         if let Some(target) = target {
87:             view["target"] = target.into();
88:         }
89:         self.views.push(view);
90:         self.views.len() - 1
91:     }
92: }
