115: fn state(value: [f32; 8]) -> Transform {
116:     Transform {
117:         translation: [value[0] as f64, value[1] as f64, value[2] as f64],
118:         rotation: [
119:             value[3] as f64,
120:             value[4] as f64,
121:             value[5] as f64,
122:             value[6] as f64,
123:         ],
124:         scale: value[7] as f64,
125:     }
126: }
127: 
128: fn transform_matrix(transform: Transform) -> [f32; 16] {
129:     let rotation = fabelgeist_mhr::math::quat_to_matrix(transform.rotation);
130:     let scale = transform.scale;
131:     // glTF stores matrices as column-major arrays.
132:     [
133:         (rotation[0][0] * scale) as f32,
134:         (rotation[1][0] * scale) as f32,
135:         (rotation[2][0] * scale) as f32,
136:         0.0,
137:         (rotation[0][1] * scale) as f32,
138:         (rotation[1][1] * scale) as f32,
139:         (rotation[2][1] * scale) as f32,
140:         0.0,
141:         (rotation[0][2] * scale) as f32,
142:         (rotation[1][2] * scale) as f32,
143:         (rotation[2][2] * scale) as f32,
144:         0.0,
145:         transform.translation[0] as f32,
146:         transform.translation[1] as f32,
147:         transform.translation[2] as f32,
148:         1.0,
149:     ]
150: }
