159: fn between(a: Transform, b: Transform, amount: f64) -> [f64; 3] {
160:     [
161:         a.translation[0] + (b.translation[0] - a.translation[0]) * amount,
162:         a.translation[1] + (b.translation[1] - a.translation[1]) * amount,
163:         a.translation[2] + (b.translation[2] - a.translation[2]) * amount,
164:     ]
165: }
166: 
167: fn subtract(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
168:     [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
169: }
170: 
171: fn dot(a: [f64; 3], b: [f64; 3]) -> f64 {
172:     a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
173: }
174: 
175: fn cross(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
176:     [
177:         a[1] * b[2] - a[2] * b[1],
178:         a[2] * b[0] - a[0] * b[2],
179:         a[0] * b[1] - a[1] * b[0],
180:     ]
181: }
182: 
183: fn length(vector: [f64; 3]) -> f64 {
184:     dot(vector, vector).sqrt()
185: }
186: 
187: fn normalize(vector: [f64; 3], side: &str, description: &str) -> Result<[f64; 3]> {
188:     let length = length(vector);
189:     if !length.is_finite() || length < 1e-9 {
190:         bail!("MHR {side} hand landmarks do not define a stable {description}");
191:     }
192:     Ok(vector.map(|component| component / length))
193: }
194: 
195: fn ray_triangle_distance(
196:     origin: [f64; 3],
197:     direction: [f64; 3],
198:     a: [f64; 3],
199:     b: [f64; 3],
200:     c: [f64; 3],
201: ) -> Option<f64> {
202:     ray_triangle_hit(origin, direction, a, b, c).map(|(distance, _, _)| distance)
203: }
204: 
205: fn ray_triangle_hit(
206:     origin: [f64; 3],
207:     direction: [f64; 3],
208:     a: [f64; 3],
209:     b: [f64; 3],
210:     c: [f64; 3],
211: ) -> Option<(f64, f64, f64)> {
212:     let edge_ab = subtract(b, a);
213:     let edge_ac = subtract(c, a);
214:     let perpendicular = cross(direction, edge_ac);
215:     let determinant = dot(edge_ab, perpendicular);
216:     if determinant.abs() < RAY_INTERSECTION_EPSILON {
217:         return None;
218:     }
219: 
220:     let inverse_determinant = determinant.recip();
221:     let from_a = subtract(origin, a);
222:     let u = inverse_determinant * dot(from_a, perpendicular);
223:     if !(0.0..=1.0).contains(&u) {
224:         return None;
225:     }
226: 
227:     let cross_from_a = cross(from_a, edge_ab);
228:     let v = inverse_determinant * dot(direction, cross_from_a);
229:     if v < 0.0 || u + v > 1.0 {
230:         return None;
231:     }
232: 
233:     let distance = inverse_determinant * dot(edge_ac, cross_from_a);
234:     (distance > RAY_INTERSECTION_EPSILON).then_some((distance, u, v))
235: }
