237: fn attachment_region_weight(mesh: &RiggedMesh<'_>, vertex: usize) -> f32 {
238:     mesh.joint_indices
239:         .vertex(vertex)
240:         .iter()
241:         .zip(mesh.joint_weights[vertex])
242:         .filter(|(joint, _)| {
243:             mesh.joint_names
244:                 .get(**joint)
245:                 .is_some_and(|name: &RigJointName| -> bool {
246:                     crate::clothing::waist_surface_joint(name) == RigJointMembership::Included
247:                 })
248:         })
249:         .map(|(_, weight)| weight)
250:         .sum()
251: }
252: 
253: fn face_key(mut face: [u32; 3]) -> [u32; 3] {
254:     face.sort_unstable();
255:     face
256: }
257: 
258: fn uv_barycentric(point: [f64; 2], a: [f64; 2], b: [f64; 2], c: [f64; 2]) -> Option<[f64; 3]> {
259:     let determinant = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1]);
260:     if determinant.abs() <= RAY_INTERSECTION_EPSILON {
261:         return None;
262:     }
263:     let first =
264:         ((b[1] - c[1]) * (point[0] - c[0]) + (c[0] - b[0]) * (point[1] - c[1])) / determinant;
265:     let second =
266:         ((c[1] - a[1]) * (point[0] - c[0]) + (a[0] - c[0]) * (point[1] - c[1])) / determinant;
267:     let third = 1.0 - first - second;
268:     const UV_EDGE_EPSILON: f64 = 1e-6;
269:     [first, second, third]
270:         .iter()
271:         .all(|weight| *weight >= -UV_EDGE_EPSILON && *weight <= 1.0 + UV_EDGE_EPSILON)
272:         .then_some([first, second, third])
273: }
274: 
275: fn interpolate3(values: [[f64; 3]; 3], weights: [f64; 3]) -> [f64; 3] {
276:     std::array::from_fn(|axis| {
277:         values[0][axis] * weights[0] + values[1][axis] * weights[1] + values[2][axis] * weights[2]
278:     })
279: }
