281: fn equipment_surface_socket(
282:     mesh: &RiggedMesh<'_>,
283:     translation: [f64; 3],
284:     normal: [f64; 3],
285:     tangent: [f32; 3],
286: ) -> Result<Transform> {
287:     let pelvis = landmark(mesh, &RigJointName::ROOT)?;
288:     let pelvis_transform = state(mesh.global_joint_states[pelvis]);
289:     let direction = normalize(normal, "equipment", "surface normal")?;
290:     let translation = std::array::from_fn(|axis| {
291:         translation[axis] + direction[axis] * EQUIPMENT_SOCKET_CLEARANCE_METERS
292:     });
293:     let mut local_y = tangent.map(f64::from);
294:     let tangent_normal_component = dot(local_y, direction);
295:     for axis in 0..3 {
296:         local_y[axis] -= direction[axis] * tangent_normal_component;
297:     }
298:     let local_y = normalize(local_y, "equipment", "authored socket tangent")?;
299:     let local_z = direction;
300:     let local_x = normalize(cross(local_y, local_z), "equipment", "socket frame")?;
301:     let rotation = quat_normalize(quat_from_matrix([
302:         [local_x[0], local_y[0], local_z[0]],
303:         [local_x[1], local_y[1], local_z[1]],
304:         [local_x[2], local_y[2], local_z[2]],
305:     ]));
306:     let model_space_socket = Transform {
307:         translation,
308:         rotation,
309:         scale: 1.0,
310:     };
311:     Ok(pelvis_transform.inverse().compose(&model_space_socket))
312: }
