314: /// Resolves one canonical anatomical UV coordinate against this LOD's body
315: /// atlas and its fitted garment shell, then constructs a pelvis-local socket.
316: pub fn fitted_equipment_socket_from_uv(
317:     mesh: &RiggedMesh<'_>,
318:     shell: &RiggedShell<'_>,
319:     layout: &SurfaceUvLayout<'_>,
320:     uv: [f32; 2],
321:     outward: [f64; 3],
322:     tangent: [f32; 3],
323: ) -> Result<Transform> {
324:     if layout.domain != MHR_ANATOMICAL_UV_DOMAIN {
325:         bail!("unsupported anatomical UV domain {}", layout.domain);
326:     }
327:     if layout.texcoord_faces.len() != mesh.faces.len() {
328:         bail!("anatomical UV faces do not match the MHR body topology");
329:     }
330:     let selected_faces = shell
331:         .faces
332:         .iter()
333:         .copied()
334:         .map(face_key)
335:         .collect::<std::collections::BTreeSet<_>>();
336:     let expected_outward = normalize(outward, "equipment", "expected outward direction")?;
337:     let point = uv.map(f64::from);
338:     let mut maximum_attachment_weight = 0.0_f64;
339:     let candidate = mesh
340:         .faces
341:         .iter()
342:         .copied()
343:         .zip(layout.texcoord_faces.iter().copied())
344:         .enumerate()
345:         .filter(|(_, (face, _))| selected_faces.contains(&face_key(*face)))
346:         .filter_map(|(face_index, (face, uv_face))| {
347:             let uv_triangle = uv_face
348:                 .map(|index| layout.texcoords.get(index as usize).copied())
349:                 .into_iter()
350:                 .collect::<Option<Vec<_>>>()?;
351:             let barycentric = uv_barycentric(
352:                 point,
353:                 uv_triangle[0].map(f64::from),
354:                 uv_triangle[1].map(f64::from),
355:                 uv_triangle[2].map(f64::from),
356:             )?;
357:             let weights = face.map(|vertex| attachment_region_weight(mesh, vertex as usize) as f64);
358:             let attachment_weight = weights[0] * barycentric[0]
359:                 + weights[1] * barycentric[1]
360:                 + weights[2] * barycentric[2];
361:             maximum_attachment_weight = maximum_attachment_weight.max(attachment_weight);
362:             if attachment_weight < EQUIPMENT_SOCKET_WEIGHT_THRESHOLD as f64 {
363:                 return None;
364:             }
365:             let normals = face.map(|vertex| shell.normals[vertex as usize].map(f64::from));
366:             let normal = normalize(
367:                 interpolate3(normals, barycentric),
368:                 "equipment",
369:                 "interpolated UV surface normal",
370:             )
371:             .ok()?;
372:             let alignment = dot(normal, expected_outward);
373:             (alignment > 0.25).then_some((
374:                 alignment,
375:                 attachment_weight,
376:                 face_index,
377:                 face,
378:                 barycentric,
379:                 normal,
380:             ))
381:         })
382:         .max_by(|left, right| {
383:             left.0
384:                 .total_cmp(&right.0)
385:                 .then_with(|| left.1.total_cmp(&right.1))
386:                 .then_with(|| right.2.cmp(&left.2))
387:         });
388:     let Some((_, _, _, face, barycentric, normal)) = candidate else {
389:         bail!(
390:             "anatomical UV {:?} in domain {} did not resolve on fitted shell {} (maximum attachment weight {:.3})",
391:             uv,
392:             layout.domain,
393:             shell.name,
394:             maximum_attachment_weight,
395:         );
396:     };
397:     let positions = face.map(|vertex| shell.positions[vertex as usize].map(f64::from));
398:     equipment_surface_socket(mesh, interpolate3(positions, barycentric), normal, tangent)
399: }
