401: /// Authoring utility that converts the previous outward-ray convention into a
402: /// canonical anatomical UV coordinate. Routine asset generation resolves the
403: /// stored UV and does not call this function.
404: pub fn bootstrap_equipment_surface_uv(
405:     mesh: &RiggedMesh<'_>,
406:     shell: &RiggedShell<'_>,
407:     layout: &SurfaceUvLayout<'_>,
408:     outward: [f64; 3],
409: ) -> Result<[f32; 2]> {
410:     if layout.texcoord_faces.len() != mesh.faces.len() {
411:         bail!("anatomical UV faces do not match the MHR body topology");
412:     }
413:     let body_faces = mesh
414:         .faces
415:         .iter()
416:         .copied()
417:         .enumerate()
418:         .map(|(index, face)| (face_key(face), index))
419:         .collect::<std::collections::BTreeMap<_, _>>();
420:     let selected_vertices = shell
421:         .faces
422:         .iter()
423:         .flat_map(|face| face.iter().copied())
424:         .map(|vertex| vertex as usize)
425:         .collect::<std::collections::BTreeSet<_>>();
426:     let (minimum, maximum) = selected_vertices.iter().fold(
427:         ([f64::INFINITY; 3], [f64::NEG_INFINITY; 3]),
428:         |(mut minimum, mut maximum), vertex| {
429:             for axis in 0..3 {
430:                 let coordinate = shell.positions[*vertex][axis] as f64;
431:                 minimum[axis] = minimum[axis].min(coordinate);
432:                 maximum[axis] = maximum[axis].max(coordinate);
433:             }
434:             (minimum, maximum)
435:         },
436:     );
437:     let minimum_y = minimum[1];
438:     let maximum_y = maximum[1];
439:     if !minimum_y.is_finite() || maximum_y <= minimum_y {
440:         bail!("fitted equipment shell has no usable vertical surface extent");
441:     }
442: 
443:     let direction = normalize(outward, "equipment", "outward ray")?;
444:     let position = |index: u32| shell.positions[index as usize].map(f64::from);
445:     let mut surface_uv = None;
446:     let mut intersection_count = 0_usize;
447:     let mut outward_intersection_count = 0_usize;
448:     let mut maximum_attachment_weight = 0.0_f64;
449:     // Prefer the belt centre, with nearby height samples providing
450:     // deterministic recovery when the centre lies exactly on a triangle edge.
451:     for height_fraction in [0.5_f64, 0.4, 0.6, 0.3, 0.7] {
452:         let origin = [
453:             (minimum[0] + maximum[0]) * 0.5,
454:             minimum_y + (maximum_y - minimum_y) * height_fraction,
455:             (minimum[2] + maximum[2]) * 0.5,
456:         ];
457:         let candidate = shell
458:             .faces
459:             .iter()
460:             .copied()
461:             .filter_map(|face| {
462:                 let a = position(face[0]);
463:                 let b = position(face[1]);
464:                 let c = position(face[2]);
465:                 let face_normal = cross(subtract(b, a), subtract(c, a));
466:                 let (distance, u, v) = ray_triangle_hit(origin, direction, a, b, c)?;
467:                 intersection_count += 1;
468:                 // From an interior origin, an outward-facing exit is a
469:                 // rendering back-face: its normal points with the ray.
470:                 if dot(face_normal, direction) <= RAY_INTERSECTION_EPSILON {
471:                     return None;
472:                 }
473:                 outward_intersection_count += 1;
474:                 let weights = face.map(|vertex| attachment_region_weight(mesh, vertex as usize));
475:                 let weight = weights[0] as f64 * (1.0 - u - v)
476:                     + weights[1] as f64 * u
477:                     + weights[2] as f64 * v;
478:                 maximum_attachment_weight = maximum_attachment_weight.max(weight);
479:                 (weight >= EQUIPMENT_SOCKET_WEIGHT_THRESHOLD as f64).then_some((
480:                     distance,
481:                     face,
482:                     [1.0 - u - v, u, v],
483:                 ))
484:             })
485:             .max_by(|left, right| left.0.total_cmp(&right.0));
486:         if let Some((_, face, barycentric)) = candidate {
487:             let body_face_index = body_faces
488:                 .get(&face_key(face))
489:                 .copied()
490:                 .context("fitted shell face is absent from the MHR body topology")?;
491:             let body_face = mesh.faces[body_face_index];
492:             let uv_face = layout.texcoord_faces[body_face_index];
493:             let mut resolved = [0.0_f64; 2];
494:             for (shell_corner, vertex) in face.into_iter().enumerate() {
495:                 let body_corner = body_face
496:                     .iter()
497:                     .position(|candidate| *candidate == vertex)
498:                     .context("fitted shell face does not preserve body vertices")?;
499:                 let texcoord = layout
500:                     .texcoords
501:                     .get(uv_face[body_corner] as usize)
502:                     .context("MHR UV face references a missing coordinate")?;
503:                 for axis in 0..2 {
504:                     resolved[axis] += barycentric[shell_corner] * texcoord[axis] as f64;
505:                 }
506:             }
507:             surface_uv = Some(resolved.map(|component| component as f32));
508:             break;
509:         }
510:     }
511:     surface_uv.with_context(|| {
512:         format!(
513:             "fitted equipment shell has no eligible outward surface for UV bootstrapping ({} intersections, {} outward, maximum attachment weight {:.3}); shell bounds {minimum:?}..{maximum:?}",
514:             intersection_count,
515:             outward_intersection_count,
516:             maximum_attachment_weight,
517:         )
518:     })
519: }
