521: fn palmar_surface_distance(
522:     mesh: &RiggedMesh<'_>,
523:     side: &str,
524:     palm_center: [f64; 3],
525:     palmar_normal: [f64; 3],
526:     maximum_distance: f64,
527: ) -> Result<f64> {
528:     let position = |index: u32| mesh.positions[index as usize].map(f64::from);
529:     mesh.faces
530:         .iter()
531:         .filter_map(|face| {
532:             ray_triangle_distance(
533:                 palm_center,
534:                 palmar_normal,
535:                 position(face[0]),
536:                 position(face[1]),
537:                 position(face[2]),
538:             )
539:         })
540:         .filter(|distance| *distance <= maximum_distance)
541:         .reduce(f64::min)
542:         .with_context(|| format!("MHR {side} palm mesh has no surface beneath the socket"))
543: }
