545: fn weapon_attachment(
546:     mesh: &RiggedMesh<'_>,
547:     side: &str,
548:     wrist: Transform,
549:     middle: Transform,
550:     index: Transform,
551:     ring: Transform,
552:     thumb: [Transform; 2],
553: ) -> Result<Transform> {
554:     let palm_length = normalize(
555:         subtract(middle.translation, wrist.translation),
556:         side,
557:         "palm length",
558:     )?;
559:     let palm_width = subtract(index.translation, ring.translation);
560:     let palm_width_length = length(palm_width);
561:     let mut palmar_normal = normalize(cross(palm_length, palm_width), side, "palm plane")?;
562:     let knuckle_center = [
563:         (index.translation[0] + middle.translation[0] + ring.translation[0]) / 3.0,
564:         (index.translation[1] + middle.translation[1] + ring.translation[1]) / 3.0,
565:         (index.translation[2] + middle.translation[2] + ring.translation[2]) / 3.0,
566:     ];
567:     let palm_center = [
568:         (wrist.translation[0] + knuckle_center[0]) * 0.5,
569:         (wrist.translation[1] + knuckle_center[1]) * 0.5,
570:         (wrist.translation[2] + knuckle_center[2]) * 0.5,
571:     ];
572: 
573:     // The thumb base disambiguates the palmar side of the skeletal hand plane
574:     // on both mirrored hands. Offset the socket to that side rather than
575:     // leaving it embedded halfway through the palm.
576:     if dot(palmar_normal, subtract(thumb[0].translation, palm_center)) < 0.0 {
577:         palmar_normal = palmar_normal.map(|component| -component);
578:     }
579:     // The weapon's +Y axis is the palm-width axis: exactly perpendicular to
580:     // the wrist-to-fingers direction. The thumb landmark only chooses which of
581:     // the two possible width directions is outward for each mirrored hand.
582:     let mut weapon_y = normalize(cross(palmar_normal, palm_length), side, "palm width")?;
583:     if dot(weapon_y, subtract(thumb[1].translation, palm_center)) < 0.0 {
584:         weapon_y = weapon_y.map(|component| -component);
585:     }
586:     let weapon_z = palmar_normal;
587:     let weapon_x = normalize(cross(weapon_y, weapon_z), side, "weapon frame")?;
588:     let rotation = quat_normalize(quat_from_matrix([
589:         [weapon_x[0], weapon_y[0], weapon_z[0]],
590:         [weapon_x[1], weapon_y[1], weapon_z[1]],
591:         [weapon_x[2], weapon_y[2], weapon_z[2]],
592:     ]));
593:     let depth = palmar_surface_distance(mesh, side, palm_center, palmar_normal, palm_width_length)?
594:         + PALMAR_SOCKET_CLEARANCE_METERS;
595: 
596:     let surface_socket = Transform {
597:         translation: [
598:             palm_center[0] + palmar_normal[0] * depth,
599:             palm_center[1] + palmar_normal[1] * depth,
600:             palm_center[2] + palmar_normal[2] * depth,
601:         ],
602:         rotation,
603:         scale: wrist.scale,
604:     };
605:     Ok(surface_socket.compose(&WEAPON_SOCKET_CALIBRATION))
606: }
607: 
608: fn position_bounds(positions: &[[f32; 3]]) -> ([f32; 3], [f32; 3]) {
609:     positions.iter().fold(
610:         ([f32::INFINITY; 3], [f32::NEG_INFINITY; 3]),
611:         |(mut minimum, mut maximum), position| {
612:             for axis in 0..3 {
613:                 minimum[axis] = minimum[axis].min(position[axis]);
614:                 maximum[axis] = maximum[axis].max(position[axis]);
615:             }
616:             (minimum, maximum)
617:         },
618:     )
619: }
620: 
621: fn linear_base_color([red, green, blue, alpha]: [f32; 4]) -> [f32; 4] {
622:     fn channel(value: f32) -> f32 {
623:         if value <= 0.04045 {
624:             value / 12.92
625:         } else {
626:             ((value + 0.055) / 1.055).powf(2.4)
627:         }
628:     }
629:     [channel(red), channel(green), channel(blue), alpha]
630: }
