632: /// Writes a zero-animation GLB using the requested texture packaging contract.
633: pub fn export_rigged_glb(
634:     output: GlbOutput<'_>,
635:     character_name: &str,
636:     recipe_version: u8,
637:     lod: u8,
638:     mesh: &RiggedMesh<'_>,
639:     shells: &[RiggedShell<'_>],
640:     sockets: &[RiggedSocket<'_>],
641: ) -> Result<()> {
642:     validate(lod, mesh, shells, sockets)?;
643:     let compact = shells
644:         .iter()
645:         .map(|shell| compact::CompactShell::new(mesh, shell))
646:         .collect::<Vec<_>>();
647:     let targets = compact
648:         .iter()
649:         .map(compact::CompactShell::targets)
650:         .collect::<Vec<_>>();
651:     let shells = compact
652:         .iter()
653:         .zip(&targets)
654:         .map(|(shell, targets)| shell.rigged(targets))
655:         .collect::<Vec<_>>();
656:     let shells = shells.as_slice();
657:     let mut buffer = BufferBuilder::default();
658:     let positions = buffer.push(
659:         &f32_bytes(mesh.positions.iter().flatten().copied()),
660:         Some(34_962),
661:     );
662:     let normals = buffer.push(
663:         &f32_bytes(mesh.normals.iter().flatten().copied()),
664:         Some(34_962),
665:     );
666:     let (joints_0, weights_0) =
667:         skinning::append(&mut buffer, mesh.joint_indices, mesh.joint_weights)?;
668:     let exported_faces = if mesh.export_body { mesh.faces } else { &[] };
669:     let indices = buffer.push(
670:         &u32_bytes(exported_faces.iter().flatten().copied()),
671:         Some(34_963),
672:     );
673:     let shell_views = shell::append_views(&mut buffer, shells)?;
674: 
675:     let mut globals = mesh.global_transforms();
676:     let mut joint_names = mesh.joint_names.clone();
677:     let mut joint_parents = mesh.joint_parents.clone();
678:     let mut attachments = Vec::new();
679:     if !mesh.faces.is_empty() {
680:         let transform = |joint: RigJointOrdinal| -> Transform { globals[joint] };
681:         let left_wrist = landmark(mesh, &RigJointName::L_WRIST)?;
682:         let left_middle = landmark(mesh, &RigJointName::L_MIDDLE1)?;
683:         let left_index = landmark(mesh, &RigJointName::L_INDEX1)?;
684:         let left_ring = landmark(mesh, &RigJointName::L_RING1)?;
685:         let left_thumb_base = landmark(mesh, &RigJointName::L_THUMB0)?;
686:         let left_thumb = landmark(mesh, &RigJointName::L_THUMB1)?;
687:         let right_wrist = landmark(mesh, &RigJointName::R_WRIST)?;
688:         let right_middle = landmark(mesh, &RigJointName::R_MIDDLE1)?;
689:         let right_index = landmark(mesh, &RigJointName::R_INDEX1)?;
690:         let right_ring = landmark(mesh, &RigJointName::R_RING1)?;
691:         let right_thumb_base = landmark(mesh, &RigJointName::R_THUMB0)?;
692:         let right_thumb = landmark(mesh, &RigJointName::R_THUMB1)?;
693:         let head = landmark(mesh, &RigJointName::C_HEAD)?;
694:         let left_eye = landmark(mesh, &RigJointName::L_EYE)?;
695:         let right_eye = landmark(mesh, &RigJointName::R_EYE)?;
696:         let left_grip = weapon_attachment(
697:             mesh,
698:             "left",
699:             transform(left_wrist),
700:             transform(left_middle),
701:             transform(left_index),
702:             transform(left_ring),
703:             [transform(left_thumb_base), transform(left_thumb)],
704:         )?;
705:         let right_grip = weapon_attachment(
706:             mesh,
707:             "right",
708:             transform(right_wrist),
709:             transform(right_middle),
710:             transform(right_index),
711:             transform(right_ring),
712:             [transform(right_thumb_base), transform(right_thumb)],
713:         )?;
714:         let camera = Transform {
715:             translation: between(transform(left_eye), transform(right_eye), 0.5),
716:             rotation: transform(head).rotation,
717:             scale: transform(head).scale,
718:         };
719:         skeleton::append_attachment(
720:             &mut joint_names,
721:             &mut joint_parents,
722:             &mut globals,
723:             &RigJointName::L_WEAPON,
724:             left_wrist,
725:             left_grip,
726:         );
727:         skeleton::append_attachment(
728:             &mut joint_names,
729:             &mut joint_parents,
730:             &mut globals,
731:             &RigJointName::R_WEAPON,
732:             right_wrist,
733:             right_grip,
734:         );
735:         skeleton::append_attachment(
736:             &mut joint_names,
737:             &mut joint_parents,
738:             &mut globals,
739:             &RigJointName::C_CAMERA,
740:             head,
741:             camera,
742:         );
743:         attachments = vec![
744:             json!({"name": RigJointName::L_WEAPON, "parent": RigJointName::L_WRIST, "role": "left_weapon_grip"}),
745:             json!({"name": RigJointName::R_WEAPON, "parent": RigJointName::R_WRIST, "role": "right_weapon_grip"}),
746:             json!({"name": RigJointName::C_CAMERA, "parent": RigJointName::C_HEAD, "role": "first_person_camera"}),
747:         ];
748:     }
749:     let inverse_bind_matrices = buffer.push(
750:         &f32_bytes(
751:             globals
752:                 .iter()
753:                 .flat_map(|global| transform_matrix(global.inverse())),
754:         ),
755:         None,
756:     );
757: 
758:     let (minimum, maximum) = position_bounds(mesh.positions);
759: 
760:     let mut accessors = Vec::new();
761:     let mut accessor =
762:         |view, component_type, count, kind: &str, bounds: Option<([f32; 3], [f32; 3])>| {
763:             let mut value = json!({
764:                 "bufferView": view,
765:                 "componentType": component_type,
766:                 "count": count,
767:                 "type": kind,
768:             });
769:             if let Some((minimum, maximum)) = bounds {
770:                 value["min"] = json!(minimum);
771:                 value["max"] = json!(maximum);
772:             }
773:             accessors.push(value);
774:             accessors.len() - 1
775:         };
776:     let position_accessor = accessor(
777:         positions,
778:         5_126,
779:         mesh.positions.len(),
780:         "VEC3",
781:         Some((minimum, maximum)),
782:     );
783:     let normal_accessor = accessor(normals, 5_126, mesh.normals.len(), "VEC3", None);
784:     let joints_0_accessor = accessor(joints_0, 5_123, mesh.positions.len(), "VEC4", None);
785:     let weights_0_accessor = accessor(weights_0, 5_126, mesh.positions.len(), "VEC4", None);
786:     let index_accessor = accessor(indices, 5_125, exported_faces.len() * 3, "SCALAR", None);
787:     let inverse_bind_accessor = accessor(
788:         inverse_bind_matrices,
789:         5_126,
790:         joint_names.len(),
791:         "MAT4",
792:         None,
793:     );
794:     let mut primitives = Vec::new();
795:     let mut material_values = Vec::new();
796:     if mesh.export_body {
797:         primitives.push(json!({
798:             "attributes": {
799:                 "POSITION": position_accessor,
800:                 "NORMAL": normal_accessor,

801:                 "JOINTS_0": joints_0_accessor,
802:                 "WEIGHTS_0": weights_0_accessor,
803:             },
804:             "indices": index_accessor,
805:             "material": 0,
806:         }));
807:         material_values.push(json!({
808:             "name": "Skin",
809:             "pbrMetallicRoughness": {
810:                 "baseColorFactor": [0.64, 0.39, 0.30, 1.0],
811:                 "metallicFactor": 0.0,
812:                 "roughnessFactor": 0.52,
813:             }
814:         }));
815:     }
816:     let mut texture_images = textures::TextureImages::new(output);
817:     shell::Writer {
818:         buffer: &mut buffer,
819:         primitives: &mut primitives,
820:         materials: &mut material_values,
821:         body_skin: [joints_0_accessor, weights_0_accessor],
822:         textures: &mut texture_images,
823:     }
824:     .append(shells, shell_views, accessor);
825: 
826:     let (mut nodes, roots) = skeleton::nodes(&joint_names, &joint_parents, &globals, mesh)?;
827:     // Keep one stable, non-joint hierarchy root. Bevy uses this node as the
828:     // beginning of every animation target path, and Cascadeur preserves it
829:     // when the base rig is used to author motion files.
830:     let skeleton_node = nodes.len();
831:     nodes.push(json!({"name": "Skeleton", "children": roots}));
832:     let skeleton_root = mesh
833:         .joint_parents
834:         .iter()
835:         .position(Option::is_none)
836:         .context("MHR skeleton has no root")?;
837:     sockets::append(&mut nodes, mesh, sockets)?;
838:     let mut scene_nodes = vec![skeleton_node];
839:     let extras = assembly::extras(
840:         character_name,
841:         recipe_version,
842:         lod,
843:         shells,
844:         sockets,
845:         &attachments,
846:     );
847:     let mut exported_mesh = json!({
848:         "name": character_name,
849:         "primitives": primitives,
850:     });
851:     morphs::write(
852:         mesh,
853:         shells,
854:         &mut exported_mesh,
855:         &mut buffer,
856:         &mut accessors,
857:     );
858:     let exported_meshes = assembly::append(
859:         exported_mesh,
860:         mesh,
861:         shells,
862:         character_name,
863:         &mut nodes,
864:         &mut scene_nodes,
865:     );
866:     let mut document = json!({
867:         "asset": {"version": "2.0", "generator": "Fabelgeist MHR character creator"},
868:         "scene": 0,
869:         "scenes": [{"name": "Character", "nodes": scene_nodes}],
870:         "nodes": nodes,
871:         "meshes": exported_meshes,
872:         "materials": material_values,
873:         "skins": [{
874:             "name": "MHR",
875:             "inverseBindMatrices": inverse_bind_accessor,
876:             "skeleton": skeleton_root,
877:             "joints": (0..joint_names.len()).collect::<Vec<_>>(),
878:         }],
879:         "accessors": accessors,
880:         "bufferViews": buffer.views,
881:         "buffers": [{"byteLength": buffer.bytes.len()}],
882:         "extras": extras
883:     });
884: 
885:     texture_images.finish(output, &mut document)?;
886: 
887:     glb::write(output.path(), &document, buffer.bytes)
888: }
