67: async fn run(bytes: &[u8]) -> anyhow::Result<String> {
68:     use adventuresim_character_creator::{design_input, runtime_equipment};
69:     use anyhow::Context;
70:     let (body, _) = armor_fixture::load(bytes)?;
71:     let bracer = design_input::load_bracer_design(None)?;
72:     let breastplate = design_input::load_breastplate_design(None)?;
73:     let gpu = adventuresim_character_creator::armor_gpu_async().await?;
74:     let errors = capture_errors(gpu);
75:     let mut results = Vec::new();
76:     for round in 0..2 {
77:         for probe in Probe::ALL {
78:             let (item, placement) = match probe {
79:                 Probe::Catalog(item, placement) => (item, placement),
80:                 Probe::Anime => ("anime", "worn"),
81:                 Probe::Wrapped => ("wrapped_tassets", "worn"),
82:             };
83:             let started = web_time::Instant::now();
84:             let cached_kernels = gpu.cache().len();
85:             let mut breastplate = breastplate.clone();
86:             let armor = if matches!(probe, Probe::Wrapped) {
87:                 wrapped(&body).await
88:             } else {
89:                 let recipe = if matches!(probe, Probe::Anime) {
90:                     breastplate.construction =
91:                         fabelgeist_armor::BreastplateConstruction::Anime(Default::default());
92:                     "cuirass"
93:                 } else {
94:                     item
95:                 };
96:                 runtime_equipment::generate(
97:                     &body,
98:                     adventuresim_core::equipment_assets::CatalogPlacement::find(
99:                         adventuresim_core::item_catalog::catalog(),
100:                         recipe,
101:                         placement,
102:                     )
103:                     .ok_or_else(|| anyhow::anyhow!("unknown equipment placement"))?,
104:                     &bracer,
105:                     &breastplate,
106:                     &[],
107:                 )
108:                 .await
109:                 .with_context(|| format!("fitting {item}, round {round}"))
110:             };
111:             let failures = errors.lock().unwrap().clone();
112:             anyhow::ensure!(failures.is_empty(), "WebGPU validation: {failures:?}");
113:             let armor = armor?;
114:             anyhow::ensure!(
115:                 gpu.cache().len() == cached_kernels,
116:                 "post-readiness fit compiled new kernels: {item}"
117:             );
118:             anyhow::ensure!(
119:                 armor.morphs.is_empty(),
120:                 "runtime equipment generated morph targets"
121:             );
122:             anyhow::ensure!(
123:                 !armor.positions.is_empty() && !armor.indices.is_empty(),
124:                 "empty equipment"
125:             );
126:             anyhow::ensure!(
127:                 armor
128:                     .positions
129:                     .iter()
130:                     .chain(&armor.normals)
131:                     .flatten()
132:                     .all(|v| v.is_finite()),
133:                 "non-finite mesh"
134:             );
135:             anyhow::ensure!(
136:                 armor
137:                     .indices
138:                     .iter()
139:                     .all(|&index| (index as usize) < armor.positions.len()),
140:                 "invalid mesh index"
141:             );
142:             anyhow::ensure!(
143:                 armor.indices.as_chunks::<3>().0.iter().any(|face| {
144:                     let [a, b, c] =
145:                         face.map(|i| bevy::math::Vec3::from(armor.positions[i as usize]));
146:                     (b - a).cross(c - a).length_squared() > 1e-14
147:                 }),
148:                 "collapsed equipment geometry: {item}"
149:             );
150:             results.push(serde_json::json!({"item":item,"round":round,"ms":started.elapsed().as_secs_f64()*1000.0,
151:                 "vertices":armor.positions.len(),"triangles":armor.indices.len()/3,"morphs":armor.morphs.len(),
152:                 "new_kernels":gpu.cache().len()-cached_kernels}));
153:         }
154:     }
155:     Ok(serde_json::to_string_pretty(&results)?)
156: }
