1: //! The MHR body model: identity, pose and expression parameters in, posed
2: //! mesh vertices and a skeleton state out.
3: 
4: use std::path::{Path, PathBuf};
5: 
6: use anyhow::{Context, Result, bail};
7: use burn::tensor::ops::IndexingUpdateOp;
8: use burn::tensor::{Device, Int, Tensor, TensorData};
9: 
10: use crate::character::{Character, PARAMETERS_PER_JOINT};
11: use crate::correctives::PoseCorrectives;
12: use crate::model_def::{ParameterTransform, append_blend_shape_parameters, parse_model_definition};
13: use crate::skel_state;
14: 
15: mod tensor_upload;
16: 
17: /// Shape coefficients: 20 body, 20 head, 5 hands.
18: pub const NUM_IDENTITY_BLEND_SHAPES: usize = 45;
19: /// Facial expression coefficients.
20: pub const NUM_FACE_EXPRESSION_BLEND_SHAPES: usize = 72;
21: /// Total blend shapes carried by an MHR rig.
22: pub const NUM_BLEND_SHAPES: usize = NUM_IDENTITY_BLEND_SHAPES + NUM_FACE_EXPRESSION_BLEND_SHAPES;
23: 
24: /// Supported runtime body detail, 4 (densest) through 6.
25: pub const MIN_LOD: u8 = 4;
26: pub const MAX_LOD: u8 = 6;
27: 
28: const MODEL_DEFINITION: &str = "compact_v6_1.model";
29: const CORRECTIVE_ACTIVATION: &str = "corrective_activation.npz";
30: 
31: /// How to load a model.
32: #[derive(Debug, Clone, Copy)]
33: pub struct MhrConfig {
34:     pub lod: u8,
35:     /// Load the pose-corrective network. It dominates both load time and
36:     /// memory (2.5 GiB of coefficients at LOD 0), so it can be turned off.
37:     pub pose_correctives: bool,
38: }
39: 
40: impl Default for MhrConfig {
41:     fn default() -> Self {
42:         Self {
43:             lod: MIN_LOD,
44:             pose_correctives: true,
45:         }
46:     }
47: }
48: 
49: /// One forward pass.
50: pub struct MhrOutput {
51:     /// Posed vertices in centimetres, `[batch, vertices, 3]`.
52:     pub vertices: Tensor<3>,
53:     /// Unit vertex normals of the posed mesh, `[batch, vertices, 3]`.
54:     ///
55:     /// Recomputed from the deformed vertices rather than skinned from the rest
56:     /// pose, because blend shapes and the pose correctives change the surface
57:     /// itself, not just its rigid frame.
58:     pub normals: Tensor<3>,
59:     /// Global joint transforms `[tx, ty, tz, qx, qy, qz, qw, s]`, `[batch, joints, 8]`.
60:     pub skeleton_state: Tensor<3>,
61: }
62: 
63: /// The MHR body model.
64: pub struct Mhr {
65:     /// Topology and names, kept on the host for lookups and the normal pass.
66:     pub character: Character,
67:     pub parameter_transform: ParameterTransform,
68:     device: Device,
69: 
70:     /// `[model parameters, joints * 7]`, transposed for a right-hand matmul.
71:     transform: Tensor<2>,
72:     /// Constant joint-parameter offsets, or `None` when the rig has none.
73:     offsets: Option<Tensor<2>>,
74:     num_model_parameters: usize,
75: 
76:     /// `[1, joints, 3]` and `[1, joints, 4]`.
77:     joint_translation_offsets: Tensor<3>,
78:     joint_prerotations: Tensor<3>,
79:     /// `[1, joints, 8]`.
80:     inverse_bind_pose: Tensor<3>,
81:     /// Levels of the forward-kinematics prefix scan.
82:     fk_levels: Vec<(Tensor<1, Int>, Tensor<1, Int>)>,
83: 
84:     /// `[45, vertices * 3]` and `[72, vertices * 3]`.
85:     identity_basis: Tensor<2>,
86:     expression_basis: Tensor<2>,
87:     /// `[1, vertices * 3]`.
88:     base_shape: Tensor<2>,
89: 
90:     /// The three corners of every triangle, flattened, `[faces * 3]`.
91:     face_corners: Tensor<1, Int>,
92: 
93:     /// Flattened non-zero skinning influences.
94:     skin_joint_indices: Tensor<1, Int>,
95:     skin_vertex_indices: Tensor<1, Int>,
96:     /// `[1, influences, 1]`.
97:     skin_weights: Tensor<3>,
98: 
99:     correctives: Option<PoseCorrectives>,
100: }
101: 
102: /// Accepts either the asset directory itself or its parent.
103: fn resolve_asset_dir(path: &Path) -> Result<PathBuf> {
104:     if path.join(MODEL_DEFINITION).is_file() {
105:         return Ok(path.to_path_buf());
106:     }
107:     let nested = path.join("assets");
108:     if nested.join(MODEL_DEFINITION).is_file() {
109:         return Ok(nested);
110:     }
111:     bail!(
112:         "no MHR assets in {}: expected {MODEL_DEFINITION} there or under assets/",
113:         path.display()
114:     )
115: }
116: 
117: impl Mhr {
118:     /// Loads MHR through `fabelgeist-fs`, including `prism://project`, HTTP/blob,
119:     /// browser File System Access handles, and native filesystem paths.
120:     pub async fn from_uri(asset_dir: &str, config: MhrConfig, device: &Device) -> Result<Self> {
121:         if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
122:             bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
123:         }
124:         let base = asset_dir.trim_end_matches(['/', '\\']);
125:         let read_asset = |name: String| async move {
126:             let direct = format!("{base}/{name}");
127:             match fabelgeist_fs::read_bytes(&direct).await {
128:                 Ok(bytes) => Ok(bytes),
129:                 Err(direct_error) => {
130:                     let nested = format!("{base}/assets/{name}");
131:                     fabelgeist_fs::read_bytes(&nested).await.map_err(|nested_error| {
132:                         anyhow::anyhow!(
133:                             "could not read MHR asset {name:?} from {direct} ({direct_error:#}) or {nested} ({nested_error:#})"
134:                         )
135:                     })
136:                 }
137:             }
138:         };
139: 
140:         let fbx = read_asset(format!("lod{}.fbx", config.lod)).await?;
141:         let definition = String::from_utf8(read_asset(MODEL_DEFINITION.into()).await?)
142:             .map_err(|error| anyhow::anyhow!("MHR model definition is not UTF-8: {error}"))?;
143:         let corrective_archives = if config.pose_correctives {
144:             Some((
145:                 read_asset(CORRECTIVE_ACTIVATION.into()).await?,
146:                 read_asset(format!("corrective_blendshapes_lod{}.npz", config.lod)).await?,
147:             ))
148:         } else {
149:             None
150:         };
151: 
152:         Self::from_asset_bytes(&fbx, &definition, corrective_archives, config, device)
153:     }
154: 
155:     /// Loads a model from an MHR asset directory (the unpacked `assets.zip`).
156:     pub fn from_files(
157:         asset_dir: impl AsRef<Path>,
158:         config: MhrConfig,
159:         device: &Device,
160:     ) -> Result<Self> {
161:         if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
162:             bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
163:         }
164:         let dir = resolve_asset_dir(asset_dir.as_ref())?;
165: 
166:         let fbx_path = dir.join(format!("lod{}.fbx", config.lod));
167:         let fbx =
168:             std::fs::read(&fbx_path).with_context(|| format!("reading {}", fbx_path.display()))?;
169:         let character = Character::from_fbx_bytes(&fbx, true)
170:             .with_context(|| format!("loading {}", fbx_path.display()))?;
171:         let definition_path = dir.join(MODEL_DEFINITION);
172:         let definition = std::fs::read_to_string(&definition_path)
173:             .with_context(|| format!("reading {}", definition_path.display()))?;
174:         let correctives = if config.pose_correctives {
175:             PoseCorrectives::load(
176:                 &dir.join(CORRECTIVE_ACTIVATION),
177:                 &dir.join(format!("corrective_blendshapes_lod{}.npz", config.lod)),
178:                 character.skeleton.len(),
179:                 character.mesh.vertices.len(),
180:                 device,
181:             )
182:             .context("loading the pose-corrective network")?
183:         } else {
184:             None
185:         };
186:         Self::from_loaded_assets(character, &definition, correctives, device)
187:     }
188: 
189:     /// Loads MHR from asset bytes, allowing browsers and virtual filesystems to
190:     /// provide the same FBX/model/NPZ inputs as the native filesystem loader.
191:     pub fn from_asset_bytes(
192:         fbx: &[u8],
193:         definition: &str,
194:         corrective_archives: Option<(Vec<u8>, Vec<u8>)>,
195:         config: MhrConfig,
196:         device: &Device,
197:     ) -> Result<Self> {
198:         if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
199:             bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
200:         }
201:         let character = Character::from_fbx_bytes(fbx, true).context("loading the MHR FBX")?;
202:         let correctives = if config.pose_correctives {
203:             let (activation, basis) = corrective_archives
204:                 .context("pose correctives requested but their NPZ archives were not provided")?;
205:             PoseCorrectives::from_bytes(
206:                 activation,
207:                 basis,
208:                 character.skeleton.len(),
209:                 character.mesh.vertices.len(),
210:                 device,
211:             )
212:             .context("loading the pose-corrective network")?
213:         } else {
214:             None
215:         };
216: 
217:         Self::from_loaded_assets(character, definition, correctives, device)
218:     }
219: 
220:     fn from_loaded_assets(
221:         character: Character,
222:         definition: &str,
223:         correctives: Option<PoseCorrectives>,
224:         device: &Device,
225:     ) -> Result<Self> {
226:         let mut parameter_transform = parse_model_definition(definition, &character.skeleton)
227:             .context("parsing the MHR model definition")?;
228:         let num_model_parameters = parameter_transform.num_parameters();
229:         // momentum appends one model parameter per identity blend shape when a
230:         // blend shape is attached to the character.
231:         append_blend_shape_parameters(&mut parameter_transform, NUM_IDENTITY_BLEND_SHAPES);
232:         Self::new(
233:             character,
234:             parameter_transform,
235:             num_model_parameters,
236:             correctives,
237:             device,
238:         )
239:     }
240: 
241:     fn new(
242:         character: Character,
243:         parameter_transform: ParameterTransform,
244:         num_model_parameters: usize,
245:         correctives: Option<PoseCorrectives>,
246:         device: &Device,
247:     ) -> Result<Self> {
248:         let joints = character.skeleton.len();
