272:                         [1, joints * PARAMETERS_PER_JOINT],
273:                     ),
274:                     device,
275:                 )
276:             });
277: 
278:         let fk_levels = tensor_upload::fk_levels(
279:             skel_state::prefix_multiplication_levels(&character.skeleton.parents),
280:             device,
281:         )?;
282: 
283:         let basis = &character.blend_shapes.vectors;
284:         let identity_basis = Tensor::from_data(
285:             TensorData::new(
286:                 basis[..NUM_IDENTITY_BLEND_SHAPES * vertices * 3].to_vec(),
287:                 [NUM_IDENTITY_BLEND_SHAPES, vertices * 3],
288:             ),
289:             device,
290:         );
291:         let expression_basis = Tensor::from_data(
292:             TensorData::new(
