294:                 [NUM_FACE_EXPRESSION_BLEND_SHAPES, vertices * 3],
295:             ),
296:             device,
297:         );
298: 
299:         // Drop zero influences: MHR averages under three joints per vertex.
300:         let mut skin_joint_indices = Vec::new();
301:         let mut skin_vertex_indices = Vec::new();
302:         let mut skin_weights = Vec::new();
303:         for (vertex, (indices, weights)) in character
304:             .skin_weights
305:             .index
306:             .iter()
307:             .zip(&character.skin_weights.weight)
308:             .enumerate()
309:         {
310:             for (joint, weight) in indices.into_iter().zip(weights) {
311:                 if *weight > 1e-5 {
