313:                     skin_vertex_indices.push(i32::try_from(vertex)?);
314:                     skin_weights.push(*weight);
315:                 }
316:             }
317:         }
318:         let influences = skin_weights.len();
319: 
320:         let face_corners: Vec<i32> = character
321:             .mesh
322:             .faces
323:             .iter()
324:             .flatten()
325:             .map(|corner| i32::try_from(*corner))
326:             .collect::<Result<_, _>>()?;
327:         let num_corners = face_corners.len();
328: 
329:         Ok(Self {
330:             device: device.clone(),
331:             transform: Tensor::from_data(
332:                 TensorData::new(
333:                     transform,
334:                     [num_model_parameters, joints * PARAMETERS_PER_JOINT],
335:                 ),
336:                 device,
337:             ),
