100: pub trait SeedableNoise {
101:     /// Sets the seed of the noise.
102:     /// This seed can be absolutely any value.
103:     /// Even 0 is fine!
104:     fn set_seed(&mut self, seed: u32);
105: 
106:     /// Gets the seed of the noise.
107:     fn get_seed(&self) -> u32;
108: }
109: 
110: /// Specifies that this noise is scalable.
111: ///
112: /// ```
113: /// # use noiz::prelude::*;
114: /// let mut noise = Noise::<common_noise::Perlin>::default();
115: /// noise.set_period(30.0);
116: /// # let val = noise.sample_for::<f32>(bevy_math::Vec2::ZERO);
117: /// ```
118: pub trait ScalableNoise {
119:     /// Sets the scale of the noise via its frequency.
120:     /// The frequency scales noise directly.
121:     /// At a frequency of `5`, an input of `2.0` will really sample at `10.0`.
122:     /// A frequency of `0.0`, infinity, or any other unusual value is not recommended.
123:     ///
124:     /// ```
125:     /// # use noiz::prelude::*;
126:     /// # let mut heightmap = Noise::<common_noise::Perlin>::default();
127:     /// // I want each sample to represent data from 30 units apart.
128:     /// heightmap.set_frequency(30.0);
129:     /// # let val = heightmap.sample_for::<f32>(bevy_math::Vec2::ZERO);
130:     /// ```
131:     fn set_frequency(&mut self, frequency: f32);
132: 
133:     /// Gets the scale of the noise via its frequency.
134:     /// See also [`get_frequency`](ScalableNoise::get_frequency).
135:     fn get_frequency(&self) -> f32;
136: 
137:     /// Sets the scale of the noise via its period.
138:     /// The `period` is the inverse of the [`frequency`](ScalableNoise::set_frequency).
139:     /// A period of `5` means an input will need to progress by `5` beffore it's inner sample can progress by `1.0`.
140:     /// A period of `0.0`, infinity, or any other unusual value is not recommended.
141:     ///
142:     /// ```
143:     /// # use noiz::prelude::*;
144:     /// # let mut heightmap = Noise::<common_noise::Perlin>::default();
145:     /// // I want each big mountain to be 30 units apart.
146:     /// heightmap.set_period(30.0);
147:     /// # let val = heightmap.sample_for::<f32>(bevy_math::Vec2::ZERO);
148:     /// ```
149:     fn set_period(&mut self, period: f32) {
150:         self.set_frequency(1.0 / period);
151:     }
152: 
153:     /// Gets the scale of the noise via its period.
154:     /// See also [`set_period`](ScalableNoise::set_period).
155:     fn get_period(&self) -> f32 {
156:         1.0 / self.get_frequency()
157:     }
158: }
159: 
160: /// Indicates that this noise is samplable by type `I`.
161: ///
162: /// This differs from a [`NoiseFunction<I>`] because this is self contained.
163: /// It provides it's own random number generator, with its own seed, etc.
164: ///
165: /// ```
166: /// # use noiz::prelude::*;
167: /// # use bevy_math::prelude::*;
168: /// let noise = Noise::<common_noise::Perlin>::default();
169: /// let value = noise.sample_for::<f32>(Vec2::new(1.0, -1.0));
170: /// ```
171: pub trait Sampleable<I> {
172:     /// Represents the raw result of the sample.
173:     /// This could be a pretty type like `f32` or it could encode additional information, like gradients, etc.
174:     type Result;
175: 
176:     /// Samples the noise at `loc`, returning the raw [`Sampleable::Result`] and the resulting [`NoiseRng`] state.
177:     /// This result may be incomplete and may depend on some cleanup to make the result meaningful.
178:     /// Use this with caution.
179:     ///
180:     /// ```

