1: //! Analytic colliders: the shapes a solver can test against in closed form.
2: //!
3: //! A body could be collided against as a triangle mesh alone -- and
4: //! [`crate::mesh`] does that -- but a handful of capsules approximating limbs
5: //! is far cheaper and, for a garment that only needs to stay outside the body,
6: //! often enough. Both are available, and they compose: a mesh for the torso
7: //! where the fit matters, capsules for the arms.
8: 
9: use fabelgeist_math::Vec3;
10: 
11: /// Bytes per collider on the GPU: three `vec4` of shape data plus a `vec4` of
12: /// kind, friction and padding.
13: pub const COLLIDER_BYTES: usize = 64;
14: 
15: /// A shape, in world space.
16: #[derive(Clone, Copy, Debug, PartialEq)]
17: pub enum Shape {
18:     /// Everything on the negative side of the plane is inside.
19:     Plane {
20:         normal: Vec3,
21:         offset: f32,
22:     },
23:     Sphere {
24:         center: Vec3,
25:         radius: f32,
26:     },
27:     /// A swept sphere: the segment `a`-`b` thickened by `radius`. This is what
28:     /// a limb is.
29:     Capsule {
30:         a: Vec3,
31:         b: Vec3,
32:         radius: f32,
33:     },
34:     /// An axis-aligned box, optionally rotated by `rotation` about its centre.
35:     /// The rotation is a unit quaternion, `xyzw`.
36:     Box {
37:         center: Vec3,
38:         half_extents: Vec3,
39:         rotation: [f32; 4],
40:     },
41: }
42: 
43: #[derive(Clone, Copy, Debug, PartialEq)]
44: pub struct Collider {
45:     pub shape: Shape,
46:     /// Coulomb friction against this surface. Zero is frictionless; a garment
47:     /// staying on a shoulder rather than sliding off it wants roughly 0.3.
48:     pub friction: f32,
49:     /// Extra separation held between a particle's centre and the surface. Half
50:     /// the fabric's thickness, plus whatever margin keeps the two visually
51:     /// apart.
52:     pub thickness: f32,
53: }
54: 
55: impl Collider {
56:     pub fn new(shape: Shape) -> Self {
57:         Self {
58:             shape,
59:             friction: 0.3,
60:             thickness: 0.002,
61:         }
62:     }
63: 
64:     pub fn plane(normal: Vec3, offset: f32) -> Self {
65:         Self::new(Shape::Plane { normal, offset })
66:     }
67: 
68:     /// The ground: `y = height`.
69:     pub fn ground(height: f32) -> Self {
70:         Self::plane(Vec3::new(0.0, 1.0, 0.0), height)
71:     }
72: 
73:     pub fn sphere(center: Vec3, radius: f32) -> Self {
74:         Self::new(Shape::Sphere { center, radius })
75:     }
76: 
77:     pub fn capsule(a: Vec3, b: Vec3, radius: f32) -> Self {
78:         Self::new(Shape::Capsule { a, b, radius })
79:     }
80: 
81:     pub fn with_friction(mut self, friction: f32) -> Self {
82:         self.friction = friction;
83:         self
84:     }
85: 
86:     pub fn with_thickness(mut self, thickness: f32) -> Self {
87:         self.thickness = thickness;
88:         self
89:     }
90: 
91:     fn kind(&self) -> u32 {
92:         match self.shape {
93:             Shape::Plane { .. } => 0,
94:             Shape::Sphere { .. } => 1,
95:             Shape::Capsule { .. } => 2,
96:             Shape::Box { .. } => 3,
97:         }
98:     }
99: 
100:     /// The 16 floats the WGSL `Collider` struct expects.
101:     pub fn pack(&self) -> [f32; 16] {
102:         let mut packed = [0.0f32; 16];
103:         match self.shape {
104:             Shape::Plane { normal, offset } => {
105:                 packed[0..4].copy_from_slice(&[normal.x, normal.y, normal.z, offset]);
106:             }
107:             Shape::Sphere { center, radius } => {
108:                 packed[0..4].copy_from_slice(&[center.x, center.y, center.z, radius]);
109:             }
110:             Shape::Capsule { a, b, radius } => {
111:                 packed[0..4].copy_from_slice(&[a.x, a.y, a.z, radius]);
112:                 packed[4..8].copy_from_slice(&[b.x, b.y, b.z, 0.0]);
113:             }
114:             Shape::Box {
115:                 center,
116:                 half_extents,
117:                 rotation,
118:             } => {
119:                 packed[0..4].copy_from_slice(&[center.x, center.y, center.z, 0.0]);
120:                 packed[4..8].copy_from_slice(&[
121:                     half_extents.x,
122:                     half_extents.y,
123:                     half_extents.z,
124:                     0.0,
125:                 ]);
126:                 packed[8..12].copy_from_slice(&rotation);
127:             }
128:         }
129:         packed[12] = f32::from_bits(self.kind());
130:         packed[13] = self.friction;
131:         packed[14] = self.thickness;
132:         packed
133:     }
212: pub fn pack_colliders(colliders: &[Collider]) -> Vec<f32> {
213:     let mut packed = Vec::with_capacity(colliders.len() * 16);
214:     for collider in colliders {
215:         packed.extend_from_slice(&collider.pack());
216:     }
217:     packed
218: }

