275: fn clip_plan_polygon_to_rect(mut polygon: Vec<Vec2>, min: Vec2, max: Vec2) -> Vec<Vec2> {
276:     for (axis, value, keep_greater) in [
277:         (0_usize, min.x, true),
278:         (0, max.x, false),
279:         (1, min.y, true),
280:         (1, max.y, false),
281:     ] {
282:         if polygon.is_empty() {
283:             break;
284:         }
285:         let input = std::mem::take(&mut polygon);
286:         let coordinate = |point: Vec2| if axis == 0 { point.x } else { point.y };
287:         let inside = |point: Vec2| {
288:             if keep_greater {
289:                 coordinate(point) >= value - 0.0001
290:             } else {
291:                 coordinate(point) <= value + 0.0001
292:             }
293:         };
294:         for index in 0..input.len() {
295:             let current = input[index];
296:             let previous = input[(index + input.len() - 1) % input.len()];
297:             let current_inside = inside(current);
298:             let previous_inside = inside(previous);
299:             if current_inside != previous_inside {
300:                 let denominator = coordinate(current) - coordinate(previous);
301:                 let fraction = if denominator.abs() <= 0.000_001 {
302:                     0.0
303:                 } else {
304:                     (value - coordinate(previous)) / denominator
305:                 };
306:                 polygon.push(previous.lerp(current, fraction));
307:             }
308:             if current_inside {
309:                 polygon.push(current);
310:             }
311:         }
312:     }
313:     polygon
314: }
