316: fn signed_plan_area(polygon: &[Vec2]) -> f32 {
317:     polygon
318:         .iter()
319:         .enumerate()
320:         .map(|(index, point)| {
321:             let next = polygon[(index + 1) % polygon.len()];
322:             point.x * next.y - next.x * point.y
323:         })
324:         .sum::<f32>()
325:         * 0.5
326: }
327: 
328: fn convex_plan_hull(mut points: Vec<Vec2>) -> Vec<Vec2> {
329:     points.sort_by(|left, right| {
330:         left.x
331:             .total_cmp(&right.x)
332:             .then_with(|| left.y.total_cmp(&right.y))
333:     });
334:     points.dedup_by(|left, right| left.distance_squared(*right) <= 0.000_004);
335:     if points.len() < 3 {
336:         return points;
337:     }
338:     let cross = |origin: Vec2, a: Vec2, b: Vec2| (a - origin).perp_dot(b - origin);
339:     let mut lower = Vec::new();
340:     for point in points.iter().copied() {
341:         while lower.len() >= 2
342:             && cross(lower[lower.len() - 2], lower[lower.len() - 1], point) <= 0.000_002
343:         {
344:             lower.pop();
345:         }
346:         lower.push(point);
347:     }
348:     let mut upper = Vec::new();
349:     for point in points.iter().rev().copied() {
350:         while upper.len() >= 2
351:             && cross(upper[upper.len() - 2], upper[upper.len() - 1], point) <= 0.000_002
352:         {
353:             upper.pop();
354:         }
355:         upper.push(point);
356:     }
357:     lower.pop();
358:     upper.pop();
359:     lower.extend(upper);
360:     lower
361: }
