363: fn clip_plan_polygon_to_convex(mut polygon: Vec<Vec2>, clip: &[Vec2]) -> Vec<Vec2> {
364:     if clip.len() < 3 {
365:         return Vec::new();
366:     }
367:     let orientation = signed_plan_area(clip).signum();
368:     for edge_index in 0..clip.len() {
369:         if polygon.is_empty() {
370:             break;
371:         }
372:         let edge_start = clip[edge_index];
373:         let edge_end = clip[(edge_index + 1) % clip.len()];
374:         let edge = edge_end - edge_start;
375:         let side = |point: Vec2| orientation * edge.perp_dot(point - edge_start);
376:         let input = std::mem::take(&mut polygon);
377:         for index in 0..input.len() {
378:             let current = input[index];
379:             let previous = input[(index + input.len() - 1) % input.len()];
380:             let current_side = side(current);
381:             let previous_side = side(previous);
382:             let current_inside = current_side >= -0.0001;
383:             let previous_inside = previous_side >= -0.0001;
384:             if current_inside != previous_inside {
385:                 let denominator = previous_side - current_side;
386:                 let fraction = if denominator.abs() <= 0.000_001 {
387:                     0.0
388:                 } else {
389:                     previous_side / denominator
390:                 };
391:                 polygon.push(previous.lerp(current, fraction));
392:             }
393:             if current_inside {
394:                 polygon.push(current);
395:             }
396:         }
397:     }
398:     polygon
399: }
