401: fn roof_plane_height(plane: RoofPlaneEquation, point: Vec2) -> f32 {
402:     -(plane.normal.x * point.x + plane.normal.z * point.y + plane.constant) / plane.normal.y
403: }
404: 
405: pub(crate) fn plan_point_in_convex_polygon(point: Vec2, polygon: &[Vec2]) -> bool {
406:     if polygon.len() < 3 {
407:         return false;
408:     }
409:     let orientation = signed_plan_area(polygon).signum();
410:     polygon.iter().enumerate().all(|(index, start)| {
411:         let end = polygon[(index + 1) % polygon.len()];
412:         orientation * (end - *start).perp_dot(point - *start) >= -0.002
413:     })
414: }
415: 
416: fn plan_point_in_polygon(point: Vec2, polygon: &[Vec2]) -> bool {
417:     if polygon.len() < 3 {
418:         return false;
419:     }
420:     let mut inside = false;
421:     for index in 0..polygon.len() {
422:         let start = polygon[index];
423:         let end = polygon[(index + 1) % polygon.len()];
424:         let crosses = (start.y > point.y) != (end.y > point.y)
425:             && point.x
426:                 < (end.x - start.x) * (point.y - start.y) / (end.y - start.y).abs().max(0.000_001)
427:                     * (end.y - start.y).signum()
428:                     + start.x;
429:         if crosses {
430:             inside = !inside;
431:         }
432:     }
433:     inside
434: }
