436: fn roof_surface_height_at(assembly: &RoofAssembly, point: Vec2) -> Option<f32> {
437:     assembly.faces.iter().find_map(|face| {
438:         let projected = face
439:             .polygon
440:             .iter()
441:             .map(|vertex| Vec2::new(vertex.x, vertex.z))
442:             .collect::<Vec<_>>();
443:         plan_point_in_convex_polygon(point, &projected)
444:             .then(|| roof_plane_height(face.plane, point))
445:     })
446: }
