448: fn roof_underside_height_at(assembly: &RoofAssembly, point: Vec2) -> Option<f32> {
449:     assembly.faces.iter().find_map(|face| {
450:         let projected = face
451:             .polygon
452:             .iter()
453:             .map(|vertex| Vec2::new(vertex.x, vertex.z))
454:             .collect::<Vec<_>>();
455:         plan_point_in_convex_polygon(point, &projected).then(|| face.underside_height_at(point))
456:     })
457: }
