459: fn ray_segment_intersection(origin: Vec2, direction: Vec2, a: Vec2, b: Vec2) -> Option<Vec2> {
460:     let edge = b - a;
461:     let denominator = direction.perp_dot(edge);
462:     if denominator.abs() <= 0.000_001 {
463:         return None;
464:     }
465:     let offset = a - origin;
466:     let ray_t = offset.perp_dot(edge) / denominator;
467:     let edge_t = offset.perp_dot(direction) / denominator;
468:     (ray_t >= -0.002 && (-0.002..=1.002).contains(&edge_t))
469:         .then(|| origin + direction * ray_t.max(0.0))
470: }

