1: fn resolve_roof_assemblies(
2:     program: &BuildingProgram,
3:     roofs: &[RoofPiece],
4:     dormers: &[RoofDormer],
5:     towers: &[RoundTower],
6:     square_towers: &[SquareTower],
7:     stairs: &[Stair],
8:     walls: &[crate::WallAssembly],
9:     openings: &[crate::OpeningAssembly],
10:     geometry: &mut ResolvedGeometry,
11: ) -> Result<Vec<RoofAssembly>, GenerationError> {
12:     let mut assemblies = Vec::new();
13:     for (index, roof) in roofs.iter().copied().enumerate() {
14:         let id = RoofAssemblyId(index as u64 + 1);
15:         let shed_high_side = match (program.church_program.is_some(), index, roof.kind) {
16:             (true, 1, RoofKind::Shed) => Some(Direction::North),
17:             (true, 2, RoofKind::Shed) => Some(Direction::South),
18:             (_, _, RoofKind::Shed) => Some(match roof.ridge_axis {
19:                 RidgeAxis::Z => Direction::East,
20:                 RidgeAxis::X => Direction::North,
21:             }),
22:             _ => None,
23:         };
24:         assemblies.push(resolve_one_roof(
25:             id,
26:             GeometryOwnerId(60_000 + index as u32),
27:             roof,
28:             Some(index),
29:             None,
30:             None,
31:             RoofPhase::Primary,
32:             shed_high_side,
33:             None,
34:             walls,
35:             geometry,
36:         )?);
37:     }
38:     if let Some(parent) = assemblies
39:         .first()
40:         .map(|assembly| (assembly.id, assembly.owner))
41:     {
42:         for index in 1..roofs.len() {
43:             let child_recipe = roofs[index];
44:             let parent_recipe = roofs[0];
45:             let child_min = child_recipe.centre - child_recipe.size * 0.5;
46:             let child_max = child_recipe.centre + child_recipe.size * 0.5;
47:             let parent_min = parent_recipe.centre - parent_recipe.size * 0.5;
48:             let parent_max = parent_recipe.centre + parent_recipe.size * 0.5;
49:             let overlaps = child_min.x < parent_max.x
50:                 && child_max.x > parent_min.x
51:                 && child_min.y < parent_max.y
52:                 && child_max.y > parent_min.y;
53:             if overlaps && child_recipe.base_height_metres > parent_recipe.base_height_metres + 0.5
54:             {
55:                 let child_id = assemblies[index].id;
56:                 assemblies[index].parent = Some(parent.0);
57:                 assemblies[index].phase = RoofPhase::AttachedChild;
58:                 let belfry_top = small_church::belfry_enclosure_top(program, index);
59:                 let enclosure_material = if belfry_top.is_some()
60:                     || walls
61:                         .iter()
62:                         .any(|wall| wall.material == crate::WallMaterialClass::TimberInfill)
63:                 {
64:                     RoofMaterial::TimberInfill
65:                 } else {
66:                     RoofMaterial::MasonryInfill
67:                 };
68:                 let top = belfry_top.unwrap_or(child_recipe.base_height_metres);
69:                 let parent_snapshot = assemblies[0].clone();
70:                 roof_child_enclosure::append(
71:                     &mut assemblies[index],
72:                     &parent_snapshot,
73:                     child_recipe,
74:                     parent_recipe.base_height_metres,
75:                     top,
76:                     enclosure_material,
77:                 );
78:                 let cut_id = ResolvedItemId((0xF_u64 << 60) | child_id.0);
79:                 let bounds = SpatialBounds::<Architectural>::from_metres(
80:                     Vec3::new(
81:                         child_min.x,
82:                         parent_recipe.base_height_metres - 0.2,
83:                         child_min.y,
84:                     ),
85:                     Vec3::new(
86:                         child_max.x,
87:                         child_recipe.base_height_metres + 5.0,
88:                         child_max.y,
89:                     ),
90:                 )?;
91:                 geometry.voids.push(ResolvedVoid {
92:                     id: cut_id,
93:                     owner: parent.1,
94:                     bounds,
95:                     role: VoidRole::RoofOpening,
96:                     shape: crate::ResolvedVoidShape::Box,
97:                     subtracts_from: parent.1,
98:                 });
99:                 let child_supports = assemblies[index].support_nodes.clone();
100:                 let child_copy = assemblies[index].clone();
101:                 roof_internal_cut::split_internal_edges(&mut assemblies[0], bounds, geometry)?;
102:                 trim_roof_edge_treatments_for_cut(assemblies[0].owner, bounds, geometry)?;
103:                 trim_roof_boundary_edges_for_cut(&mut assemblies[0], bounds);
104:                 let cut_edges =
105:                     cut_parent_roof_face(&mut assemblies[0], &child_copy, bounds, geometry)?;
106:                 let valleys =
107:                     bind_child_valleys(&mut assemblies[0], &child_copy, &cut_edges, geometry)?;
108:                 let flashing_ids = assemblies[0]
109:                     .edges
110:                     .iter()
111:                     .filter(|edge| cut_edges.contains(&edge.id))
112:                     .filter_map(|edge| edge.flashing)
113:                     .collect();
114:                 assemblies[0].children.push(RoofChildAssembly {
115:                     child: child_id,
116:                     kind: RoofChildKind::CrossGable,
117:                     parent_cut: cut_id,
118:                     trimmer_nodes: child_supports,
119:                     valley_edges: valleys,
120:                     flashing_ids,
121:                     facade_wall: None,
122:                     split_eave_edges: Vec::new(),
123:                 });
124:             }
125:         }
126:     }
127:     roof_dormers::append(&mut assemblies, dormers, walls, geometry)?;
128:     for (index, tower) in towers.iter().copied().enumerate() {
129:         if let Some(roof) = tower.roof {
130:             let id = RoofAssemblyId(2_000 + index as u64);
131:             assemblies.push(resolve_one_roof(
132:                 id,
133:                 GeometryOwnerId(62_000 + index as u32),
134:                 roof,
135:                 None,
136:                 Some(index),
137:                 None,
138:                 RoofPhase::Primary,
139:                 None,
140:                 None,
141:                 walls,
142:                 geometry,
143:             )?);
144:         }
145:     }
146:     for (index, tower) in square_towers.iter().copied().enumerate() {
147:         let id = RoofAssemblyId(3_000 + index as u64);
148:         assemblies.push(resolve_one_roof(
149:             id,
150:             GeometryOwnerId(63_000 + index as u32),
151:             tower.roof,
152:             None,
153:             Some(index),
154:             None,
155:             RoofPhase::Primary,
156:             None,
157:             None,
158:             walls,
159:             geometry,
160:         )?);
161:     }
162:     // A tower piercing the principal roof is a true abutment, not two
163:     // overlapping independent meshes. Cut the main weather faces to the
164:     // tower footprint, flash every resulting edge, and bind the tower roof as
165:     // a child carried by its own masonry ring.
166:     if !square_towers.is_empty() && !assemblies.is_empty() {
167:         for (tower_index, tower) in square_towers.iter().copied().enumerate() {
168:             let Some(child_index) = assemblies
169:                 .iter()
170:                 .position(|roof| roof.id == RoofAssemblyId(3_000 + tower_index as u64))
171:             else {
172:                 continue;
173:             };
174:             let child = assemblies[child_index].clone();
175:             let parent_id = assemblies[0].id;
176:             let cut_id = ResolvedItemId((0xF_u64 << 60) | child.id.0);
177:             // `SquareTower::size` locates the four authoritative wall
178:             // centrelines.  The parent roof must stop at the exterior shell
179:             // faces, not halfway through the masonry.
180:             let shell_half_thickness = walls
181:                 .iter()
182:                 .filter_map(|wall| match wall.source {
183:                     crate::WallSourceId::SquareTowerFace {
184:                         tower_index: source_tower,
185:                         ..
186:                     } if source_tower == tower_index => Some(wall.thickness_metres * 0.5),
187:                     _ => None,
188:                 })
189:                 .fold(0.0_f32, f32::max);
190:             let half = tower.size * 0.5 + Vec2::splat(shell_half_thickness);
191:             let bounds = SpatialBounds::<Architectural>::from_metres(
192:                 Vec3::new(
193:                     tower.centre.x - half.x,
194:                     assemblies[0]
195:                         .faces
196:                         .iter()
197:                         .flat_map(|face| face.polygon.iter().map(|point| point.y))
198:                         .fold(f32::INFINITY, f32::min)
199:                         - 0.2,
200:                     tower.centre.y - half.y,
201:                 ),
202:                 Vec3::new(
203:                     tower.centre.x + half.x,
204:                     tower.wall_height_metres + 8.0,
205:                     tower.centre.y + half.y,
206:                 ),
207:             )?;
208:             geometry.voids.push(ResolvedVoid {
209:                 id: cut_id,
210:                 owner: assemblies[0].owner,
211:                 bounds,
212:                 role: VoidRole::RoofOpening,
213:                 shape: crate::ResolvedVoidShape::Box,
214:                 subtracts_from: assemblies[0].owner,
215:             });
216:             let cut_height = bounds.max().metres().y;
217:             let mut vertical_cut = child.clone();
218:             let mut cut_face = child.faces[0].clone();
219:             cut_face.polygon = vec![
220:                 Vec3::new(bounds.min().metres().x, cut_height, bounds.min().metres().z),
221:                 Vec3::new(bounds.max().metres().x, cut_height, bounds.min().metres().z),
222:                 Vec3::new(bounds.max().metres().x, cut_height, bounds.max().metres().z),
223:                 Vec3::new(bounds.min().metres().x, cut_height, bounds.max().metres().z),
224:             ];
225:             cut_face.cutouts.clear();
226:             cut_face.plane = RoofPlaneEquation {
227:                 normal: Vec3::Y,
228:                 constant: -cut_height,
229:             };
230:             vertical_cut.faces = vec![cut_face];
231:             trim_roof_edge_treatments_for_cut(assemblies[0].owner, bounds, geometry)?;
232:             trim_roof_boundary_edges_for_cut(&mut assemblies[0], bounds);
233:             let cut_edges =
234:                 cut_parent_roof_face(&mut assemblies[0], &vertical_cut, bounds, geometry)?;
235:             for edge in assemblies[0]
236:                 .edges
237:                 .iter_mut()
238:                 .filter(|edge| cut_edges.contains(&edge.id))
239:             {
240:                 edge.kind = RoofEdgeKind::TowerAbutment;
241:             }
242:             let flashing_ids = assemblies[0]
243:                 .edges
244:                 .iter()
245:                 .filter(|edge| cut_edges.contains(&edge.id))
246:                 .filter_map(|edge| edge.flashing)
247:                 .collect::<Vec<_>>();
248:             assemblies[0].children.push(RoofChildAssembly {
249:                 child: child.id,
250:                 kind: RoofChildKind::Tower,
251:                 parent_cut: cut_id,
252:                 trimmer_nodes: child.support_nodes.clone(),
253:                 valley_edges: cut_edges,
254:                 flashing_ids,
255:                 facade_wall: None,
256:                 split_eave_edges: Vec::new(),
257:             });
258:             assemblies[child_index].parent = Some(parent_id);
259:             assemblies[child_index].phase = RoofPhase::AttachedChild;
260:         }
261:     }
262:     bind_coincident_primary_roof_edges(&mut assemblies, geometry)?;
263:     finalize_roof_drainage(program.archetype, &mut assemblies, geometry)?;
264:     supplement_split_eave_drainage(&assemblies, geometry)?;
265:     consolidate_roof_outlet_stations(
266:         program.archetype,
267:         &mut assemblies,
268:         stairs,
269:         walls,
270:         openings,
271:         geometry,
272:     )?;
273:     resolve_roof_abutment_contours(&mut assemblies, walls, geometry)?;
274:     refit_roof_edge_treatments(&mut assemblies, geometry)?;
275:     bind_roof_junctions(&assemblies, geometry)?;
276:     Ok(assemblies)
277: }

1: fn split_cross_gable_parent_eave(
2:     parent: &mut RoofAssembly,
3:     child_id: RoofAssemblyId,
4:     origin: Vec2,
5:     tangent: Vec2,
6:     width: f32,
7: ) -> Vec<ResolvedItemId> {
8:     let front_left = origin - tangent * width * 0.5;
9:     let front_right = origin + tangent * width * 0.5;
10:     let candidate = parent
11:         .edges
12:         .iter()
13:         .enumerate()
14:         .find_map(|(edge_index, edge)| {
15:             if edge.kind != RoofEdgeKind::Eave {
16:                 return None;
17:             }
18:             let a = Vec2::new(edge.start.x, edge.start.z);
19:             let b = Vec2::new(edge.end.x, edge.end.z);
20:             let delta = b - a;
21:             if delta.normalize_or_zero().dot(tangent).abs() < 0.99 {
22:                 return None;
23:             }
24:             let denominator = delta.length_squared();
25:             let left_t = (front_left - a).dot(delta) / denominator.max(0.000_001);
26:             let right_t = (front_right - a).dot(delta) / denominator.max(0.000_001);
27:             let lo = left_t.min(right_t);
28:             let hi = left_t.max(right_t);
29:             (lo > 0.02 && hi < 0.98 && (hi - lo) * delta.length() >= width * 0.85)
30:                 .then_some((edge_index, lo, hi))
31:         });
32:     let Some((edge_index, lo, hi)) = candidate else {
33:         return Vec::new();
34:     };
35:     let old = parent.edges.remove(edge_index);
36:     let left_point = old.start.lerp(old.end, lo);
37:     let right_point = old.start.lerp(old.end, hi);
38:     let serial = parent.edges.len() as u64;
39:     let ids = [0_u64, 1, 2].map(|slot| {
40:         ResolvedItemId((0xB_u64 << 60) | (parent.id.0 << 16) | 0x0E00 | (serial << 2) | slot)
41:     });
42:     parent.edges.extend([
43:         RoofEdge {
44:             id: ids[0],
45:             start: old.start,
46:             end: left_point,
47:             kind: RoofEdgeKind::Eave,
48:             adjacent_faces: old.adjacent_faces.clone(),
49:             flashing: None,
50:             drainage_terminal: old.drainage_terminal,
51:         },
52:         RoofEdge {
53:             id: ids[1],
54:             start: left_point,
55:             end: right_point,
56:             kind: RoofEdgeKind::OpeningCut,
57:             adjacent_faces: old.adjacent_faces.clone(),
58:             flashing: None,
59:             drainage_terminal: None,
60:         },
61:         RoofEdge {
62:             id: ids[2],
63:             start: right_point,
64:             end: old.end,
65:             kind: RoofEdgeKind::Eave,
66:             adjacent_faces: old.adjacent_faces,
67:             flashing: None,
68:             drainage_terminal: old.drainage_terminal,
69:         },
70:     ]);
71:     if let Some(link) = parent
72:         .children
73:         .iter_mut()
74:         .find(|link| link.child == child_id)
75:     {
76:         link.split_eave_edges = ids.to_vec();
77:     }
78:     ids.to_vec()
79: }
