81: fn clip_plan_polygon_to_child_above_parent(
82:     mut polygon: Vec<Vec2>,
83:     parent: RoofPlaneEquation,
84:     child: RoofPlaneEquation,
85: ) -> Result<Vec<Vec2>, crate::GenerationError> {
86:     if polygon.is_empty() {
87:         return Ok(polygon);
88:     }
89:     let clearance =
90:         |point: Vec2| roof_plane_height(child, point) - roof_plane_height(parent, point);
91:     let input = std::mem::take(&mut polygon);
92:     for index in 0..input.len() {
93:         let current = input[index];
94:         let previous = input[(index + input.len() - 1) % input.len()];
95:         let current_clearance = clearance(current);
96:         let previous_clearance = clearance(previous);
97:         let current_inside = current_clearance >= -0.001;
98:         let previous_inside = previous_clearance >= -0.001;
99:         if current_inside != previous_inside {
100:             let denominator = previous_clearance - current_clearance;
101:             let fraction = if denominator.abs() <= 0.000_001 {
102:                 0.0
103:             } else {
104:                 previous_clearance / denominator
105:             };
106:             polygon.push(previous.lerp(current, fraction));
107:         }
108:         if current_inside {
109:             polygon.push(current);
110:         }
111:     }
112:     Ok(polygon)
113: }
