115: fn cut_parent_roof_face(
116:     assembly: &mut RoofAssembly,
117:     child: &RoofAssembly,
118:     cut_bounds: SpatialBounds<Architectural>,
119:     geometry: &mut ResolvedGeometry,
120: ) -> Result<Vec<ResolvedItemId>, crate::GenerationError> {
121:     let mut cut_edges = Vec::new();
122:     let serial_base = assembly.edges.len();
123:     for face in &mut assembly.faces {
124:         let projected = face
125:             .polygon
126:             .iter()
127:             .map(|point| Vec2::new(point.x, point.z))
128:             .collect::<Vec<_>>();
129:         let mut cut_points = Vec::new();
130:         for child_face in &child.faces {
131:             let child_projected = child_face
132:                 .polygon
133:                 .iter()
134:                 .map(|point| Vec2::new(point.x, point.z))
135:                 .collect::<Vec<_>>();
136:             let bounded = clip_plan_polygon_to_rect(
137:                 projected.clone(),
138:                 Vec2::new(cut_bounds.min().metres().x, cut_bounds.min().metres().z),
139:                 Vec2::new(cut_bounds.max().metres().x, cut_bounds.max().metres().z),
140:             );
141:             let mut clipped = clip_plan_polygon_to_convex(bounded, &child_projected);
142:             clipped =
143:                 clip_plan_polygon_to_child_above_parent(clipped, face.plane, child_face.plane)?;
144:             let unique = unique_roof_cut_points(clipped);
145:             cut_points.extend(unique);
146:         }
147:         let unique = convex_plan_hull(cut_points);
148:         let signed_area = signed_plan_area(&unique);
149:         if unique.len() >= 3 && signed_area.abs() > 0.002 {
150:             let mut cutout = unique
151:                 .into_iter()
152:                 .map(|point| Vec3::new(point.x, roof_plane_height(face.plane, point), point.y))
153:                 .collect::<Vec<_>>();
154:             if signed_area > 0.0 {
155:                 cutout.reverse();
156:             }
157:             let face_id = face.id;
158:             face.cutouts.push(cutout.clone());
159:             for index in 0..cutout.len() {
160:                 let serial = serial_base + cut_edges.len();
161:                 let edge_id = ResolvedItemId(
162:                     (0xB_u64 << 60) | (assembly.id.0 << 16) | (0x800 + serial) as u64,
163:                 );
164:                 let start = cutout[index];
165:                 let end = cutout[(index + 1) % cutout.len()];
166:                 let flashing_id = ResolvedItemId(
167:                     (0x8_u64 << 60) | (assembly.id.0 << 16) | (0x800 + serial) as u64,
168:                 );
169:                 let delta = end - start;
170:                 geometry.solids.push(ResolvedSolid::new(
171:                     CollisionCuboid::<Architectural>::from_metres(
172:                         flashing_id,
173:                         (start + end) * 0.5 + Vec3::Y * 0.012,
174:                         Vec3::new((delta.length() - 0.12).max(0.05), 0.024, 0.10),
175:                         delta.z.atan2(delta.x),
176:                         0.08,
177:                         0.0,
178:                     )?,
179:                     assembly.owner,
180:                     SolidRole::RoofFlashing,
181:                     crate::ResolvedSolidShape::Cuboid,
182:                     vec![assembly.support_nodes[0]],
183:                 ));
184:                 geometry
185:                     .support_interfaces
186:                     .push(crate::SupportInterface::new(
187:                         ResolvedItemId(
188:                             (0x9_u64 << 60) | (assembly.id.0 << 16) | (0x800 + serial) as u64,
189:                         ),
190:                         assembly.owner,
191:                         assembly.support_nodes[0],
192:                         SpatialBounds::<Architectural>::from_metres(
193:                             (start + end) * 0.5 - Vec3::new(0.12, 0.04, 0.12),
194:                             (start + end) * 0.5 + Vec3::new(0.12, 0.08, 0.12),
195:                         )?,
196:                     ));
197:                 cut_edges.push(edge_id);
198:                 assembly.edges.push(RoofEdge {
199:                     id: edge_id,
200:                     start,
201:                     end,
202:                     kind: RoofEdgeKind::OpeningCut,
203:                     adjacent_faces: vec![face_id],
204:                     flashing: Some(flashing_id),
205:                     drainage_terminal: None,
206:                 });
207:             }
208:         }
209:     }
210:     Ok(cut_edges)
211: }
