213: fn bind_child_valleys(
214:     parent: &mut RoofAssembly,
215:     child: &RoofAssembly,
216:     cut_edges: &[ResolvedItemId],
217:     geometry: &mut ResolvedGeometry,
218: ) -> Result<Vec<ResolvedItemId>, crate::GenerationError> {
219:     let mut valleys = Vec::new();
220:     let mut candidates = cut_edges
221:         .iter()
222:         .filter_map(|id| {
223:             parent
224:                 .edges
225:                 .iter()
226:                 .find(|edge| edge.id == *id)
227:                 .map(|edge| (*id, (edge.start.y - edge.end.y).abs()))
228:         })
229:         .filter(|(_, fall)| *fall > 0.02)
230:         .collect::<Vec<_>>();
231:     candidates.sort_by(|left, right| right.1.total_cmp(&left.1));
232:     for (edge_id, _) in candidates.into_iter().take(2) {
233:         if let Some(edge) = parent.edges.iter_mut().find(|edge| edge.id == edge_id) {
234:             edge.kind = RoofEdgeKind::Valley;
235:             let (high, low) = if edge.start.y >= edge.end.y {
236:                 (edge.start, edge.end)
237:             } else {
238:                 (edge.end, edge.start)
239:             };
240:             let suffix = edge.id.0 & ((1_u64 << 60) - 1);
241:             let outlet_id = ResolvedItemId((0xE_u64 << 60) | suffix);
242:             let route_id = ResolvedItemId((0xD_u64 << 60) | suffix);
243:             geometry.voids.push(ResolvedVoid {
244:                 id: outlet_id,
245:                 owner: parent.owner,
246:                 bounds: SpatialBounds::<Architectural>::from_metres(
247:                     // The terminal is an upward-open throat beginning at the
248:                     // weather surface. Extending it below the valley would
249:                     // falsely cut the receiving eave gutter or wall plate.
250:                     low - Vec3::new(0.04, 0.0, 0.04),
251:                     low + Vec3::new(0.04, 0.08, 0.04),
252:                 )?,
253:                 role: VoidRole::Drain,
254:                 shape: crate::ResolvedVoidShape::Box,
255:                 subtracts_from: parent.owner,
256:             });
257:             geometry.drainage_routes.push(DrainageRoute {
258:                 id: route_id,
259:                 owner: parent.owner,
260:                 outlet_void: outlet_id,
261:                 inlet: high,
262:                 outlet: low,
263:             });
264:             edge.drainage_terminal = Some(outlet_id);
265:             if let Some(flashing) = edge
266:                 .flashing
267:                 .and_then(|id| geometry.solids.iter_mut().find(|solid| solid.id == id))
268:             {
269:                 let delta = edge.end - edge.start;
270:                 let run = Vec2::new(delta.x, delta.z).length().max(0.01);
271:                 let uphill = (high - low).normalize_or_zero();
272:                 flashing.centre = Position::<Architectural>::from_metres(
273:                     (high + low) * 0.5 + uphill * 0.06 + Vec3::Y * (flashing.size.metres().y * 0.5),
274:                 )?;
275:                 {
276:                     let mut native_geometry = flashing.size.metres();
277:                     native_geometry.x = (delta.length() - 0.12).max(0.05);
278:                     flashing.size =
279:                         CuboidDimensions::from_metres(native_geometry).map_err(|cause| {
280:                             crate::CollisionError {
281:                                 source_id: flashing.id,
282:                                 cause,
283:                             }
284:                         })?;
285:                 };
286:                 flashing.longfall_radians = Radians::new(delta.y.atan2(run))?;
287:             }
288:             if let Some(face) = child.faces.iter().min_by(|left, right| {
289:                 let midpoint = (edge.start + edge.end) * 0.5;
290:                 let left_distance = left
291:                     .polygon
292:                     .iter()
293:                     .map(|point| point.distance_squared(midpoint))
294:                     .fold(f32::INFINITY, f32::min);
295:                 let right_distance = right
296:                     .polygon
297:                     .iter()
298:                     .map(|point| point.distance_squared(midpoint))
299:                     .fold(f32::INFINITY, f32::min);
300:                 left_distance.total_cmp(&right_distance)
301:             }) {
302:                 edge.adjacent_faces.push(face.id);
303:             }
304:             valleys.push(edge_id);
305:         }
306:     }
307:     Ok(valleys)
308: }
