310: fn trim_roof_edge_treatments_for_cut(
311:     owner: GeometryOwnerId,
312:     cut: SpatialBounds<Architectural>,
313:     geometry: &mut ResolvedGeometry,
314: ) -> Result<(), crate::GenerationError> {
315:     let cut_centre = Vec2::new(
316:         (cut.min().metres().x + cut.max().metres().x) * 0.5,
317:         (cut.min().metres().z + cut.max().metres().z) * 0.5,
318:     );
319:     let cut_half = Vec2::new(
320:         (cut.max().metres().x - cut.min().metres().x) * 0.5,
321:         (cut.max().metres().z - cut.min().metres().z) * 0.5,
322:     );
323:     for solid in geometry.solids.iter_mut().filter(|solid| {
324:         solid.owner == owner
325:             && matches!(
326:                 solid.role,
327:                 SolidRole::RoofEdgeTreatment | SolidRole::RoofGutter
328:             )
329:     }) {
330:         let tangent = Vec2::new(
331:             solid.yaw_radians.radians().cos(),
332:             solid.yaw_radians.radians().sin(),
333:         );
334:         let plan_scale = solid.longfall_radians.radians().cos().abs().max(0.01);
335:         let normal = Vec2::new(-tangent.y, tangent.x);
336:         let centre = Vec2::new(solid.centre.metres().x, solid.centre.metres().z);
337:         let offset = cut_centre - centre;
338:         let lateral_extent = cut_half.x * normal.x.abs() + cut_half.y * normal.y.abs();
339:         if offset.dot(normal).abs() > lateral_extent + solid.size.metres().z * 0.5 + 0.01 {
340:             continue;
341:         }
342:         let cut_along = (cut_half.x * tangent.x.abs() + cut_half.y * tangent.y.abs()) / plan_scale;
343:         let cut_centre_along = offset.dot(tangent) / plan_scale;
344:         let cut_min = cut_centre_along - cut_along;
345:         let cut_max = cut_centre_along + cut_along;
346:         let old_min = -solid.size.metres().x * 0.5;
347:         let old_max = solid.size.metres().x * 0.5;
348:         if cut_max <= old_min + 0.01 || cut_min >= old_max - 0.01 {
349:             continue;
350:         }
351:         let kept = if cut_min <= old_min + 0.01 && cut_max < old_max - 0.05 {
352:             Some((cut_max + 0.08, old_max))
353:         } else if cut_max >= old_max - 0.01 && cut_min > old_min + 0.05 {
354:             Some((old_min, cut_min - 0.08))
355:         } else {
356:             // No curated tower presently bisects a ridge. Rejecting this
357:             // topology later is safer than leaving a treatment through the
358:             // opening; a full two-segment edge graph is required for it.
359:             None
360:         };
361:         if let Some((from, to)) = kept {
362:             let shift = (from + to) * 0.5;
363:             let mut centre = solid.centre.metres();
364:             centre.x += tangent.x * plan_scale * shift;
365:             centre.y += solid.longfall_radians.radians().sin() * shift;
366:             centre.z += tangent.y * plan_scale * shift;
367:             solid.centre = Position::<Architectural>::from_metres(centre).map_err(|cause| {
368:                 crate::CollisionError {
369:                     source_id: solid.id,
370:                     cause,
371:                 }
372:             })?;
373:             {
374:                 let mut native_geometry = solid.size.metres();
375:                 native_geometry.x = to - from;
376:                 solid.size = CuboidDimensions::from_metres(native_geometry).map_err(|cause| {
377:                     crate::CollisionError {
378:                         source_id: solid.id,
379:                         cause,
380:                     }
381:                 })?;
382:             };
383:             let interface_id = ResolvedItemId((0x9_u64 << 60) | (solid.id.0 & ((1_u64 << 60) - 1)));
384:             if let Some(interface) = geometry
385:                 .support_interfaces
386:                 .iter_mut()
387:                 .find(|interface| interface.id == interface_id)
388:             {
389:                 interface.bounds = SpatialBounds::from_metres(
390:                     solid.centre.metres() - Vec3::new(0.08, 0.025, 0.08),
391:                     solid.centre.metres() + Vec3::new(0.08, 0.025, 0.08),
392:                 )?;
393:             }
394:         } else {
395:             {
396:                 let mut native_geometry = solid.size.metres();
397:                 native_geometry.x = 0.0;
398:                 solid.size = CuboidDimensions::from_metres(native_geometry).map_err(|cause| {
399:                     crate::CollisionError {
400:                         source_id: solid.id,
401:                         cause,
402:                     }
403:                 })?;
404:             };
405:         }
406:     }
407:     geometry
408:         .solids
409:         .retain(|solid| solid.size.metres().x > 0.001);
410: 
411:     Ok(())
412: }
413: 
414: fn trim_roof_boundary_edges_for_cut(
415:     assembly: &mut RoofAssembly,
416:     cut: SpatialBounds<Architectural>,
417: ) {
418:     let inside = |point: Vec3| {
419:         point.x >= cut.min().metres().x - 0.002
420:             && point.x <= cut.max().metres().x + 0.002
421:             && point.z >= cut.min().metres().z - 0.002
422:             && point.z <= cut.max().metres().z + 0.002
423:     };
424:     for edge in assembly.edges.iter_mut().filter(|edge| {
425:         matches!(edge.kind, RoofEdgeKind::Eave | RoofEdgeKind::GableVerge)
426:             && edge.adjacent_faces.len() == 1
427:     }) {
428:         let start_inside = inside(edge.start);
429:         let end_inside = inside(edge.end);
430:         if start_inside == end_inside {
431:             continue;
432:         }
433:         let from = edge.start;
434:         let delta = edge.end - edge.start;
435:         let mut intersections = Vec::new();
436:         for (axis_start, axis_delta, low, high) in [
437:             (from.x, delta.x, cut.min().metres().x, cut.max().metres().x),
438:             (from.z, delta.z, cut.min().metres().z, cut.max().metres().z),
439:         ] {
440:             if axis_delta.abs() <= 0.000_001 {
441:                 continue;
442:             }
443:             for boundary in [low, high] {
444:                 let t = (boundary - axis_start) / axis_delta;
445:                 if (0.0..=1.0).contains(&t) {
446:                     let point = from + delta * t;
447:                     if point.x >= cut.min().metres().x - 0.003
448:                         && point.x <= cut.max().metres().x + 0.003
449:                         && point.z >= cut.min().metres().z - 0.003
450:                         && point.z <= cut.max().metres().z + 0.003
451:                     {
452:                         intersections.push((t, point));
453:                     }
454:                 }
455:             }
456:         }
457:         if start_inside {
458:             if let Some((_, point)) = intersections
459:                 .into_iter()
460:                 .max_by(|left, right| left.0.total_cmp(&right.0))
461:             {
462:                 edge.start = point + delta.normalize_or_zero() * 0.10;
463:             }
464:         } else if let Some((_, point)) = intersections
465:             .into_iter()
466:             .min_by(|left, right| left.0.total_cmp(&right.0))
467:         {
468:             edge.end = point - delta.normalize_or_zero() * 0.10;
469:         }
470:     }
471: }
472: 
473: fn unique_roof_cut_points(clipped: Vec<Vec2>) -> Vec<Vec2> {
474:     let mut unique = Vec::new();
475:     for point in clipped {
476:         if !unique
477:             .iter()
478:             .any(|existing: &Vec2| existing.distance_squared(point) <= 0.000_004)
479:         {
480:             unique.push(point);
481:         }
482:     }
483:     unique
484: }

