90: fn clip_to_underside(polygon: &[Vec3], face: &RoofFace) -> Vec<Vec3> {
91:     let mut clipped = Vec::new();
92:     let signed = |p: Vec3| {
93:         face.plane.normal.dot(p)
94:             + face.plane.constant
95:             + face.thickness_metres * face.plane.normal.length()
96:     };
97:     for (&a, &b) in polygon
98:         .iter()
99:         .zip(polygon.iter().cycle().skip(1))
100:         .take(polygon.len())
101:     {
102:         let da = signed(a);
103:         let db = signed(b);
104:         if da <= 0.0 {
105:             clipped.push(a);
106:         }
107:         if (da < 0.0 && db > 0.0) || (da > 0.0 && db < 0.0) {
108:             clipped.push(a.lerp(b, da / (da - db)));
109:         }
110:     }
111:     clipped
112: }
