1: fn resolve_roof_abutment_contours(
2:     assemblies: &mut [RoofAssembly],
3:     walls: &[crate::WallAssembly],
4:     geometry: &mut ResolvedGeometry,
5: ) -> Result<(), crate::GenerationError> {
6:     let contacts = roof_contacts::RoofContacts::new(walls, &geometry.solids)?;
7:     let _: () = for assembly in assemblies {
8:         for (kind_slot, (edge_kind, abutment_kind)) in [
9:             (RoofEdgeKind::WallAbutment, RoofAbutmentKind::Wall),
10:             (RoofEdgeKind::TowerAbutment, RoofAbutmentKind::Tower),
11:         ]
12:         .into_iter()
13:         .enumerate()
14:         {
15:             let edge_indices = assembly
16:                 .edges
17:                 .iter()
18:                 .enumerate()
19:                 .filter_map(|(index, edge)| (edge.kind == edge_kind).then_some(index))
20:                 .collect::<Vec<_>>();
21:             if edge_indices.is_empty() {
22:                 continue;
23:             }
24:             let abutment_id =
25:                 ResolvedItemId((0x7_u64 << 60) | (assembly.id.0 << 16) | 0xD000 | kind_slot as u64);
26:             let mut samples = Vec::new();
27:             let mut edge_ids = Vec::new();
28:             for edge_index in edge_indices {
29:                 let edge = &mut assembly.edges[edge_index];
30:                 let old_flashing = edge.flashing;
31:                 let first_edge_sample = samples.len();
32:                 let first_edge_bond = geometry.junction_bonds.len();
33:                 let delta = edge.end - edge.start;
34:                 let length = delta.length().max(0.01);
35:                 let station_count = (length / 0.22).ceil().max(1.0) as usize;
36:                 let horizontal = Vec2::new(delta.x, delta.z).normalize_or_zero();
37:                 for station in 0..=station_count {
38:                     let t = station as f32 / station_count as f32;
39:                     let point = edge.start.lerp(edge.end, t);
40:                     let plan_point = Vec2::new(point.x, point.z);
41:                     let Some(host) =
42:                         roof_contacts::abutment_host(walls, abutment_kind, point, plan_point)
43:                     else {
44:                         continue;
45:                     };
