51:                     // Reserve independent bit ranges for edge and station.
52:                     // Long clerestory contacts exceed 64 samples, so the old
53:                     // `edge << 8 | station * 4` encoding aliased IDs once the
54:                     // station carried into the edge bits.
55:                     let serial = ((edge_index as u64 & 0x7) << 10) | ((station as u64 & 0xFF) << 2);
56:                     let base = (0x8_u64 << 60) | (assembly.id.0 << 16) | 0xA000 | serial;
57:                     let apron = if station == 0 {
58:                         old_flashing.unwrap_or(ResolvedItemId(base))
59:                     } else {
60:                         ResolvedItemId(base)
61:                     };
62:                     let upstand = ResolvedItemId(base | 1);
63:                     let counter = ResolvedItemId(base | 2);
64:                     let outward = Vec3::new(host.frame.outward.x, 0.0, host.frame.outward.y);
