64:         let rad_y = self.rotation.y.to_radians();
65:         let rad_z = self.rotation.z.to_radians();
66: 
67:         let cx = rad_x.cos();
68:         let sx = rad_x.sin();
69:         let cy = rad_y.cos();
70:         let sy = rad_y.sin();
71:         let cz = rad_z.cos();
72:         let sz = rad_z.sin();
