17:     pub fn centered(coverage: f32) -> Self {
18:         let coverage = coverage.clamp(0.0, 1.0);
19:         Self {
20:             start: (1.0 - coverage) * 0.5,
21:             end: (1.0 + coverage) * 0.5,
22:         }
23:     }
