2: 
3: pub(in crate::autoresolve) fn melee_assignment(
4:     attacker_index: usize,
5:     attackers: &[Combatant],
6:     defenders: &[Combatant],
7:     parameters: crate::combat::AutoresolveParameters,
8: ) -> (usize, f32) {
9:     let mut ordered = active_melee_indices(defenders);
10:     ordered.extend(active_ranged_indices(defenders));
11:     for index in active_indices(defenders) {
12:         if !ordered.contains(&index) {
13:             ordered.push(index);
14:         }
15:     }
16:     debug_assert!(!ordered.is_empty());
17:     let rank = attackers[..=attacker_index]
18:         .iter()
19:         .filter(|combatant| {
20:             !combatant.is_defeated()
21:                 && combatant.can_attack_melee()
22:                 && preferred_attack_mode(combatant) == BattleAttackKind::Melee
23:         })
24:         .count()
25:         .saturating_sub(1);
26:     let target = ordered[rank % ordered.len()];
27:     (
28:         target,
29:         if rank >= ordered.len() {
30:             parameters.outnumbered_flanking
31:         } else {
32:             0.0
33:         },
34:     )
35: }
36: 
37: pub(in crate::autoresolve) fn active_indices(side: &[Combatant]) -> Vec<usize> {
38:     side.iter()
39:         .enumerate()
40:         .filter_map(|(index, combatant)| (!combatant.is_defeated()).then_some(index))
41:         .collect()
42: }
43: 
44: pub(in crate::autoresolve) fn active_melee_indices(side: &[Combatant]) -> Vec<usize> {
45:     side.iter()
46:         .enumerate()
47:         .filter_map(|(index, combatant)| {
48:             (!combatant.is_defeated()
49:                 && combatant.can_attack_melee()
50:                 && preferred_attack_mode(combatant) == BattleAttackKind::Melee)
51:                 .then_some(index)
52:         })
53:         .collect()
54: }
55: 
56: pub(in crate::autoresolve) fn active_ranged_indices(side: &[Combatant]) -> Vec<usize> {
57:     side.iter()
58:         .enumerate()
59:         .filter_map(|(index, combatant)| {
60:             (!combatant.is_defeated() && combatant.can_attack_ranged()).then_some(index)
61:         })
62:         .collect()
63: }
64: 
65: pub(in crate::autoresolve) fn prioritized_ranged_targets(side: &[Combatant]) -> Vec<usize> {
66:     let ranged = active_ranged_indices(side);
67:     if ranged.is_empty() {
68:         active_indices(side)
69:     } else {
70:         ranged
71:     }
72: }
