1: //! Parse and compare typed demographic selectors from authored quest data.
2: 
3: use adventuresim_world_schema::Sex;
4: use serde_json::{Map, Value};
5: use std::fmt;
6: 
7: #[derive(Debug, Eq, PartialEq)]
8: pub(super) enum SexSelectorError {
9:     Missing,
10:     ExpectedArray,
11:     ExpectedString(usize),
12:     Unknown { index: usize, value: String },
13: }
14: 
15: impl SexSelectorError {
16:     pub(super) fn at(self, rule_path: &str) -> String {
17:         format!("{rule_path}.sexes: {self}")
18:     }
19: }
20: 
21: impl fmt::Display for SexSelectorError {
22:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
23:         match self {
24:             Self::Missing => formatter.write_str("missing"),
25:             Self::ExpectedArray => formatter.write_str("expected array"),
26:             Self::ExpectedString(index) => write!(formatter, "entry {index}: expected string"),
27:             Self::Unknown { index, value } => {
28:                 write!(formatter, "entry {index}: unknown sex selector {value}")
29:             }
30:         }
31:     }
32: }
33: 
34: pub(super) fn parse_sexes(rule: &Map<String, Value>) -> Result<Vec<Sex>, SexSelectorError> {
35:     let values = rule.get("sexes").ok_or(SexSelectorError::Missing)?;
36:     let values = values.as_array().ok_or(SexSelectorError::ExpectedArray)?;
37:     values
38:         .iter()
39:         .enumerate()
40:         .map(|(index, value)| {
41:             let value = value
42:                 .as_str()
43:                 .ok_or(SexSelectorError::ExpectedString(index))?;
44:             value.parse().map_err(|_| SexSelectorError::Unknown {
45:                 index,
46:                 value: value.to_owned(),
47:             })
48:         })
49:         .collect()
50: }
51: 
52: pub(super) fn sex_selectors_overlap(left: &[Sex], right: &[Sex]) -> bool {
53:     left.is_empty() || right.is_empty() || left.iter().any(|sex| right.contains(sex))
54: }
