143:                 1 => Conscience::Callous,
144:                 _ => Conscience::Cruel,
145:             }
146:         }
147:         5 => {
148:             result.self_regard = if random.boolean() {
149:                 SelfRegard::Proud
150:             } else {
151:                 SelfRegard::Humble
152:             }
153:         }
154:         6 => {
155:             result.conviction = if random.boolean() {
156:                 Conviction::Zealous
157:             } else {
158:                 Conviction::Irreverent
159:             }
160:         }
161:         7 => {
162:             result.hygiene = if random.boolean() {
163:                 Hygiene::Slovenly
164:             } else {
165:                 Hygiene::Cleanly
166:             }
167:         }
168:         8 => {
169:             result.temperance = if random.boolean() {
170:                 Temperance::Temperate
171:             } else {
172:                 Temperance::Drunkard
173:             }
174:         }
175:         9 => {
176:             result.mirth = if random.boolean() {
177:                 Mirth::Merry
178:             } else {
179:                 Mirth::Grave
180:             }
181:         }
182:         10 => {
183:             result.courtship = if random.boolean() {
