324: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
325: pub struct Portion {
326:     numerator: NonZeroU64,
327:     denominator: NonZeroU64,
328: }
329: 
330: impl Portion {
331:     pub fn try_new(numerator: u64, denominator: u64) -> Result<Self, MaterialError> {
332:         let numerator = NonZeroU64::new(numerator).ok_or(MaterialError::ZeroPortion)?;
333:         let denominator = NonZeroU64::new(denominator).ok_or(MaterialError::ZeroDenominator)?;
334:         if numerator > denominator {
335:             return Err(MaterialError::PortionExceedsWhole);
336:         }
337:         Ok(Self {
338:             numerator,
339:             denominator,
340:         })
341:     }
342: 
343:     pub fn split_measure(
344:         self,
345:         whole: MaterialMeasure,
346:     ) -> Result<(MaterialMeasure, Option<MaterialMeasure>), MaterialError> {
347:         let take = MaterialMeasure {
348:             mass_milligrams: prorated_floor(
349:                 whole.mass_milligrams,
350:                 self.numerator.get(),
351:                 self.denominator.get(),
352:             )?,
353:             volume_microliters: prorated_floor(
354:                 whole.volume_microliters,
355:                 self.numerator.get(),
356:                 self.denominator.get(),
357:             )?,
358:         };
359:         if take == MaterialMeasure::ZERO {
360:             return Err(MaterialError::EmptyPortion);
361:         }
362:         let remainder = whole.checked_sub(take)?;
363:         Ok((
364:             take,
365:             (remainder != MaterialMeasure::ZERO).then_some(remainder),
366:         ))
367:     }
368: }
369: 
370: fn prorated_floor(value: u64, numerator: u64, denominator: u64) -> Result<u64, MaterialError> {
371:     let scaled = u128::from(value)
372:         .checked_mul(u128::from(numerator))
373:         .ok_or(MaterialError::Overflow)?
374:         / u128::from(denominator);
375:     u64::try_from(scaled).map_err(|_| MaterialError::Overflow)
376: }
