470: impl<C: DomainMaterialComponent, X: DomainContaminant> PrivateMaterialTruth<C, X> {
471:     pub fn try_new(
472:         components: Vec<ExtensiveComponent<C>>,
473:         contaminants: Vec<ContaminantLoad<X>>,
474:     ) -> Result<Self, MaterialError> {
475:         if has_duplicate_keys(&components, |value| &value.component)
476:             || has_duplicate_keys(&contaminants, |value| &value.contaminant)
477:         {
478:             return Err(MaterialError::DuplicatePrivateComponent);
479:         }
480:         Ok(Self {
481:             components,
482:             contaminants,
483:         })
484:     }
