493:     pub fn split(&self, portion: Portion) -> Result<(Self, Self), MaterialError> {
494:         let mut taken_components = Vec::new();
495:         let mut remainder_components = Vec::new();
496:         for value in &self.components {
497:             let taken = prorated_floor(
498:                 value.magnitude.get(),
499:                 portion.numerator.get(),
500:                 portion.denominator.get(),
501:             )?;
502:             if let Some(magnitude) = NonZeroU64::new(taken) {
503:                 taken_components.push(ExtensiveComponent {
504:                     component: value.component.clone(),
505:                     magnitude,
506:                 });
507:             }
508:             if let Some(magnitude) = NonZeroU64::new(value.magnitude.get() - taken) {
509:                 remainder_components.push(ExtensiveComponent {
510:                     component: value.component.clone(),
511:                     magnitude,
512:                 });
513:             }
514:         }
515:         let mut taken_contaminants = Vec::new();
516:         let mut remainder_contaminants = Vec::new();
517:         for value in &self.contaminants {
518:             let taken = prorated_floor(
519:                 value.load.get(),
520:                 portion.numerator.get(),
521:                 portion.denominator.get(),
522:             )?;
523:             if let Some(load) = NonZeroU64::new(taken) {
524:                 taken_contaminants.push(ContaminantLoad {
525:                     contaminant: value.contaminant.clone(),
526:                     load,
527:                 });
528:             }
529:             if let Some(load) = NonZeroU64::new(value.load.get() - taken) {
530:                 remainder_contaminants.push(ContaminantLoad {
531:                     contaminant: value.contaminant.clone(),
532:                     load,
533:                 });
534:             }
535:         }
536:         Ok((
537:             Self::try_new(taken_components, taken_contaminants)?,
538:             Self::try_new(remainder_components, remainder_contaminants)?,
539:         ))
540:     }
541: }
