543: fn has_duplicate_keys<T, K: Eq>(values: &[T], key: impl Fn(&T) -> &K) -> bool {
544:     values.iter().enumerate().any(|(index, value)| {
545:         values[index + 1..]
546:             .iter()
547:             .any(|other| key(value) == key(other))
548:     })
549: }
