792: fn verify_conservation(
793:     inputs: &[MaterialMeasure],
794:     outputs: &[MaterialMeasure],
795:     accounted_loss: MaterialMeasure,
796:     rounding_tolerance: RoundingTolerance,
797: ) -> Result<ConservationReceipt, MaterialError> {
798:     let inputs = checked_sum(inputs)?;
799:     let outputs = checked_sum(outputs)?;
800:     let expected_outputs = inputs
801:         .checked_sub(accounted_loss)
802:         .map_err(|_| MaterialError::ConservationViolation)?;
803:     let rounding_difference = expected_outputs
804:         .checked_sub(outputs)
805:         .map_err(|_| MaterialError::ConservationViolation)?;
806:     if rounding_difference.mass_milligrams > rounding_tolerance.0.mass_milligrams
807:         || rounding_difference.volume_microliters > rounding_tolerance.0.volume_microliters
808:     {
809:         return Err(MaterialError::ConservationViolation);
810:     }
811:     Ok(ConservationReceipt {
812:         inputs,
813:         outputs,
814:         accounted_loss,
815:         rounding_tolerance,
816:         rounding_difference,
817:     })
818: }
