953: pub struct MaterialTransformationReceipt<
954:     P: DomainPreparation,
955:     C: DomainMaterialComponent,
956:     X: DomainContaminant,
957:     D: DomainConservationPolicy,
958:     O: DomainMaterialReceipt,
959: > {
960:     provenance: MaterialActionProvenance,
961:     input_digest: MaterialInputDigest,
962:     sources: Vec<SourceLotContribution<P, C, X>>,
963:     outputs: Vec<ProducedMaterial<P, C, X>>,
