978:         provenance: MaterialActionProvenance,
979:         sources: Vec<SourceLotContribution<P, C, X>>,
980:         outputs: Vec<ProducedMaterial<P, C, X>>,
981:         policy: ProcessConservationPolicy<D, C, X>,
982:         domain_outcome: O,
983:     ) -> Result<Self, MaterialError> {
984:         if sources.is_empty() {
985:             return Err(MaterialError::EmptySourceContribution);
986:         }
987:         if has_duplicate_keys(&sources, |value| &value.source.identity.lot_id) {
988:             return Err(MaterialError::DuplicateSourceLot);
989:         }
990:         if sources.iter().enumerate().any(|(index, value)| {
991:             sources[index + 1..]
992:                 .iter()
993:                 .any(|other| value.source.identity.object_id() == other.source.identity.object_id())
994:         }) {
995:             return Err(MaterialError::DuplicateSourceObject);
996:         }
997:         if has_duplicate_keys(&outputs, |value| &value.snapshot.identity.lot_id) {
998:             return Err(MaterialError::DuplicateOutputLot);
999:         }
1000:         if outputs.iter().enumerate().any(|(index, value)| {
1001:             outputs[index + 1..].iter().any(|other| {
1002:                 value.snapshot.identity.object_id() == other.snapshot.identity.object_id()
1003:             })
1004:         }) {
1005:             return Err(MaterialError::DuplicateOutputObject);
1006:         }
1007:         let input_digest = canonical_input_digest(&sources);
1008:         let input_measures = sources
1009:             .iter()
1010:             .map(|value| value.consumed)
1011:             .collect::<Vec<_>>();
1012:         let output_measures = outputs
1013:             .iter()
1014:             .map(|value| value.snapshot.measure)
1015:             .collect::<Vec<_>>();
1016:         let conservation = verify_conservation(
1017:             &input_measures,
1018:             &output_measures,
1019:             policy.bulk_loss,
1020:             policy.rounding_tolerance,
1021:         )?;
1022:         verify_private_conservation(&sources, &outputs, &policy)?;
1023:         Ok(Self {
1024:             provenance,
1025:             input_digest,
1026:             sources,
1027:             outputs,
1028:             policy,
1029:             conservation,
1030:             domain_outcome,
1031:         })
1032:     }
