1034:     pub const fn provenance(&self) -> MaterialActionProvenance {
1035:         self.provenance
1036:     }
1037:     pub const fn input_digest(&self) -> MaterialInputDigest {
1038:         self.input_digest
1039:     }
1040:     pub fn sources(&self) -> &[SourceLotContribution<P, C, X>] {
1041:         &self.sources
1042:     }
1043:     pub fn outputs(&self) -> &[ProducedMaterial<P, C, X>] {
1044:         &self.outputs
1045:     }
1046:     pub const fn conservation(&self) -> ConservationReceipt {
1047:         self.conservation
1048:     }
1049:     pub const fn policy(&self) -> &ProcessConservationPolicy<D, C, X> {
1050:         &self.policy
1051:     }
