1056: 
1057: fn canonical_input_digest<
1058:     P: DomainPreparation,
1059:     C: DomainMaterialComponent,
1060:     X: DomainContaminant,
1061: >(
1062:     sources: &[SourceLotContribution<P, C, X>],
1063: ) -> MaterialInputDigest {
1064:     let mut ordered = sources.iter().collect::<Vec<_>>();
1065:     ordered.sort_by_key(|value| value.source.identity.lot_id);
1066:     let mut hash = Sha256::new();
1067:     hash.update(b"adventuresim.material-input.v1");
1068:     for source in ordered {
1069:         hash.update(source.source.identity.lot_id.get().to_le_bytes());
1070:         hash.update(source.source.identity.object_id().get().to_le_bytes());
1071:         hash.update(source.source.revision.to_le_bytes());
1072:         hash.update(source.source.measure.mass_milligrams.to_le_bytes());
1073:         hash.update(source.source.measure.volume_microliters.to_le_bytes());
1074:         hash.update(source.consumed.mass_milligrams.to_le_bytes());
1075:         hash.update(source.consumed.volume_microliters.to_le_bytes());
1076:         update_custody_digest(&mut hash, source.source.identity.custody());
1077:     }
1078:     MaterialInputDigest(hash.finalize().into())
1079: }
1080: 
1081: fn update_custody_digest(hash: &mut Sha256, custody: &OperationalCustody) {
1082:     match custody {
1083:         OperationalCustody::Character(value) => {
1084:             hash.update([0]);
1085:             hash.update(value.get().to_le_bytes());
1086:         }
1087:         OperationalCustody::Party(value) => {
1088:             hash.update([1]);
1089:             update_digest_bytes(hash, value.as_str().as_bytes());
1090:         }
1091:         OperationalCustody::Container(value) => {
1092:             hash.update([2]);
1093:             hash.update(value.get().to_le_bytes());
1094:         }
1095:         OperationalCustody::Place(value) => {
1096:             hash.update([3]);
1097:             update_digest_bytes(hash, value.to_string().as_bytes());
1098:         }
1099:         OperationalCustody::Fixture(value) => {
1100:             hash.update([4]);
1101:             update_digest_bytes(hash, value.to_string().as_bytes());
1102:         }
1103:     }
1104: }
1105: 
1106: fn update_digest_bytes(hash: &mut Sha256, bytes: &[u8]) {
1107:     hash.update((bytes.len() as u64).to_le_bytes());
1108:     hash.update(bytes);
1109: }
