1111: fn verify_private_conservation<
1112:     P: DomainPreparation,
1113:     C: DomainMaterialComponent,
1114:     X: DomainContaminant,
1115:     D: DomainConservationPolicy,
1116: >(
1117:     sources: &[SourceLotContribution<P, C, X>],
1118:     outputs: &[ProducedMaterial<P, C, X>],
1119:     policy: &ProcessConservationPolicy<D, C, X>,
1120: ) -> Result<(), MaterialError> {
1121:     let input_components = sources
1122:         .iter()
1123:         .flat_map(|value| value.consumed_truth.components.iter())
1124:         .map(|value| (value.component.clone(), value.magnitude.get()))
1125:         .collect::<Vec<_>>();
1126:     let output_components = outputs
1127:         .iter()
1128:         .flat_map(|value| value.snapshot.truth.components.iter())
1129:         .map(|value| (value.component.clone(), value.magnitude.get()))
1130:         .collect::<Vec<_>>();
1131:     verify_extensive_values(
1132:         &input_components,
1133:         &output_components,
1134:         &policy.component_changes,
1135:     )?;
1136: 
1137:     let input_contaminants = sources
1138:         .iter()
1139:         .flat_map(|value| value.consumed_truth.contaminants.iter())
1140:         .map(|value| (value.contaminant.clone(), value.load.get()))
1141:         .collect::<Vec<_>>();
1142:     let output_contaminants = outputs
1143:         .iter()
1144:         .flat_map(|value| value.snapshot.truth.contaminants.iter())
1145:         .map(|value| (value.contaminant.clone(), value.load.get()))
1146:         .collect::<Vec<_>>();
1147:     verify_extensive_values(
1148:         &input_contaminants,
1149:         &output_contaminants,
1150:         &policy.contaminant_changes,
1151:     )
1152: }
1153: 
1154: fn verify_extensive_values<K: Clone + fmt::Debug + Eq>(
1155:     inputs: &[(K, u64)],
1156:     outputs: &[(K, u64)],
1157:     changes: &[ExtensiveChange<K>],
1158: ) -> Result<(), MaterialError> {
1159:     let mut keys = Vec::<K>::new();
1160:     for key in inputs
1161:         .iter()
1162:         .map(|value| &value.0)
1163:         .chain(outputs.iter().map(|value| &value.0))
1164:         .chain(changes.iter().map(|value| &value.property))
1165:     {
1166:         if !keys.contains(key) {
1167:             keys.push(key.clone());
1168:         }
1169:     }
1170:     for key in keys {
1171:         let input = inputs
1172:             .iter()
1173:             .filter(|value| value.0 == key)
1174:             .try_fold(0_u64, |total, value| {
1175:                 total.checked_add(value.1).ok_or(MaterialError::Overflow)
1176:             })?;
1177:         let output = outputs
1178:             .iter()
1179:             .filter(|value| value.0 == key)
1180:             .try_fold(0_u64, |total, value| {
1181:                 total.checked_add(value.1).ok_or(MaterialError::Overflow)
1182:             })?;
1183:         let expected = match changes.iter().find(|value| value.property == key) {
1184:             None => input,
1185:             Some(change) if change.kind == ExtensiveChangeKind::Gain => input
1186:                 .checked_add(change.magnitude.get())
1187:                 .ok_or(MaterialError::Overflow)?,
1188:             Some(change) => input
1189:                 .checked_sub(change.magnitude.get())
1190:                 .ok_or(MaterialError::PrivateConservationViolation)?,
1191:         };
1192:         if output != expected {
1193:             return Err(MaterialError::PrivateConservationViolation);
1194:         }
1195:     }
1196:     Ok(())
1197: }

