62:     pub fn to_mat4(&self) -> Mat4 {
63:         let rad_x = self.rotation.x.to_radians();
64:         let rad_y = self.rotation.y.to_radians();
65:         let rad_z = self.rotation.z.to_radians();
66: 
67:         let cx = rad_x.cos();
68:         let sx = rad_x.sin();
69:         let cy = rad_y.cos();
70:         let sy = rad_y.sin();
71:         let cz = rad_z.cos();
72:         let sz = rad_z.sin();
73: 
74:         // Rotation matrix R = Rz * Ry * Rx
75:         let r00 = cy * cz;
76:         let r01 = sx * sy * cz - cx * sz;
77:         let r02 = cx * sy * cz + sx * sz;
78: 
79:         let r10 = cy * sz;
80:         let r11 = sx * sy * sz + cx * cz;
81:         let r12 = cx * sy * sz - sx * cz;
82: 
83:         let r20 = -sy;
84:         let r21 = sx * cy;
85:         let r22 = cx * cy;
86: 
87:         Mat4 {
88:             columns: [
89:                 [
90:                     r00 * self.scale.x,
91:                     r10 * self.scale.x,
92:                     r20 * self.scale.x,
93:                     0.0,
94:                 ],
95:                 [
96:                     r01 * self.scale.y,
97:                     r11 * self.scale.y,
98:                     r21 * self.scale.y,
99:                     0.0,
100:                 ],
101:                 [
102:                     r02 * self.scale.z,
103:                     r12 * self.scale.z,
104:                     r22 * self.scale.z,
105:                     0.0,
106:                 ],
107:                 [self.position.x, self.position.y, self.position.z, 1.0],
