1: //! Entry points for plain limb charts and shared fitted shoulder carriers.
2: use super::limb::{LimbShape, shape};
3: use super::{ArmorGpu, BuiltPart};
4: use crate::{GenerateError, LimbArmorDesign, PartFrame};
5: use fabelgeist_gpu::prelude::BufferUpload;
6: 
7: /// Record a limb design's charts, placed by the part frame at the start of
8: /// `frame`, into a new device part.
9: pub fn record_limb_armor(
10:     gpu: &ArmorGpu,
11:     batch: &mut fabelgeist_compute::KernelBatch,
12:     design: &LimbArmorDesign,
13:     frame: &fabelgeist_gpu::prelude::Buffer,
14: ) -> Result<super::DevicePart, GenerateError> {
15:     if let LimbArmorDesign::Pauldron(d) = design {
16:         return super::pauldron::DevicePauldronCarrier::record(gpu, batch, d, frame)?
17:             .record_plates(gpu, batch, d);
18:     }
19:     let LimbShape { part, design } = shape(gpu, design)?;
20:     part.record(gpu, batch, &design, &[frame])
21: }
22: 
23: /// Generate a limb plate on the device, placed by `fit`.
24: pub fn generate_limb_armor_on(
25:     gpu: &ArmorGpu,
26:     design: &LimbArmorDesign,
27:     fit: &PartFrame,
28: ) -> Result<BuiltPart, GenerateError> {
29:     if let LimbArmorDesign::Pauldron(d) = design {
30:         fit.validate()?;
31:         let frame = gpu.upload(BufferUpload::from_elements(&super::recipe::frame_words(
32:             fit,
33:         )))?;
34:         let mut batch = gpu.batch("pauldron");
35:         let carrier = super::pauldron::DevicePauldronCarrier::record(gpu, &mut batch, d, &frame)?;
36:         let mut part = carrier.record_plates(gpu, &mut batch, d)?;
37:         part.record_shells(gpu, &mut batch)?;
38:         batch.submit();
39:         if gpu.read::<u32>(&carrier.status)?[0] != 0 {
40:             return Err(GenerateError::InvalidSurface);
41:         }
42:         return part.read(gpu);
43:     }
44:     let LimbShape { part, design } = shape(gpu, design)?;
45:     part.build(gpu, &design, fit)
46: }

