18:     pub penetrated_energy_joules: f32,
19: }
20: 
21: #[derive(Debug, Clone, Copy, PartialEq)]
22: pub(super) struct ContactEnergyResolution {
23:     pub armor_impact: Option<ArmorImpact>,
24:     pub cut_energy_joules: f32,
25:     pub blunt_energy_joules: f32,
26: }
27: 
28: pub(super) fn effective_edge_resistance(
29:     surface: ArmorSurface,
30:     precision: super::ContactPrecision,
31: ) -> f32 {
32:     precision.resistance(surface.resistance)
33: }
34: 
35: pub(super) fn resolve_contact_energy(
36:     surface: Option<ArmorSurface>,
37:     attack: f32,
38:     incident_energy_joules: f32,
39:     precision: super::ContactPrecision,
40: ) -> ContactEnergyResolution {
41:     let incident = incident_energy_joules.max(0.0);
42:     if incident <= 0.0 {
43:         return ContactEnergyResolution {
44:             armor_impact: None,
45:             cut_energy_joules: 0.0,
46:             blunt_energy_joules: 0.0,
47:         };
48:     }
49:     let edge_energy = incident * precision.concentrated_fraction();
50:     let blunt_energy = incident - edge_energy;
51:     let Some(surface) = surface else {
52:         return ContactEnergyResolution {
53:             armor_impact: None,
54:             cut_energy_joules: edge_energy,
55:             blunt_energy_joules: blunt_energy,
56:         };
57:     };
58: 
59:     let penetrated = (edge_energy - effective_edge_resistance(surface, precision)).max(0.0);
60:     let stopped_edge = edge_energy - penetrated;
61:     // Some stopped edge energy deforms the armor into the body; the remainder
62:     // is reflected or retained by the armor. Blunt-channel energy starts as a
63:     // transmission candidate. Padding consumes that shared budget once.
64:     let edge_transmission_candidate = stopped_edge * 0.5;
65:     let transmission_candidate = edge_transmission_candidate + blunt_energy;
66:     let padding_resisted = transmission_candidate.min(surface.padding.max(0.0));
67:     let transmitted = transmission_candidate - padding_resisted;
68:     let resisted = stopped_edge - edge_transmission_candidate + padding_resisted;
69:     debug_assert!((incident - resisted - transmitted - penetrated).abs() < 0.001);
70:     let impact = ArmorImpact {
71:         surface,
72:         outcome: if penetrated > 0.0 {
73:             ArmorImpactOutcome::Penetrated
74:         } else if attack < 1.0 {
75:             ArmorImpactOutcome::Deflected
76:         } else {
77:             ArmorImpactOutcome::Stopped
78:         },
79:         resisted_energy_joules: resisted,
80:         transmitted_energy_joules: transmitted,
81:         penetrated_energy_joules: penetrated,
82:     };
83:     ContactEnergyResolution {
84:         armor_impact: Some(impact),
85:         cut_energy_joules: penetrated,
86:         blunt_energy_joules: transmitted,
87:     }
88: }
