1: //! Canonical candidate ordering and proportional integer-weighted draws.
2: use super::*;
3: use fabelgeist_determinism::Seed;
4: 
5: pub(super) fn choose<T: Copy>(
6:     seed: Seed,
7:     module: &str,
8:     relation: &str,
9:     candidates: &[Candidate<T>],
10:     trace: &mut Vec<FactorTrace>,
11: ) -> Result<(T, Option<&'static str>), GenerationError> {
12:     if candidates.len() > MAX_SOLVER_CANDIDATES {
13:         return Err(GenerationError::CandidateLimit);
14:     }
15:     let mut ordered: Vec<_> = (0..candidates.len()).collect();
16:     canonicalize(candidates, &mut ordered)?;
17:     let mut accepted_indices = Vec::new();
18:     for index in ordered {
19:         let c = &candidates[index];
20:         let accepted = c.impossible.is_none() && c.weight.combined() > 0;
21:         trace.push(FactorTrace {
22:             module_id: ModuleId::new(module),
23:             relation_id: RelationId::new(relation),
24:             factor_ids: c.factors.iter().map(|f| FactorId::new(*f)).collect(),
25:             candidate_id: c.id.into(),
26:             plausibility: c.weight.plausibility,
27:             curation: c.weight.curation,
28:             accepted,
29:             hard_zero_reason: c.impossible.map(str::to_owned),
30:             required_bridge: c.bridge.map(BridgeId::new),
31:             decision: TraceDecision::Candidate,
32:         });
33:         if accepted {
34:             accepted_indices.push(index);
35:         }
36:     }
37:     if accepted_indices.is_empty() {
38:         return Err(GenerationError::NoCandidates {
39:             module: ModuleId::new(module),
40:             diagnostics: trace.clone(),
41:         });
42:     }
43:     let weights: Vec<_> = accepted_indices
44:         .iter()
45:         .map(|index| candidates[*index].weight.combined())
46:         .collect();
47:     let mut random = fabelgeist_determinism::Seed::derive(
48:         &seed.to_le_bytes(),
49:         fabelgeist_determinism::StreamId::new("quest.choice"),
50:         &[module.as_bytes(), relation.as_bytes()],
51:     )
52:     .rng();
53:     let selected = random
54:         .weighted_index(&weights)
55:         .map_err(GenerationError::Sampling)?;
56:     let candidate = &candidates[accepted_indices[selected]];
57:     Ok((candidate.value, candidate.bridge))
58: }
