30:             .iter()
31:             .map(|witness| {
32:                 std::mem::size_of::<u64>()
33:                     + witness.profession.len()
34:                     + witness.visible_description.len()
35:                     + witness.expected_location.len()
36:                     + witness.expected_location_label.len()
37:             })
38:             .sum::<usize>()
39:             > 64 * 1024
40:     {
41:         return Err(GenerationError::CandidateLimit);
42:     }
43:     let mut families = family_candidates();
44:     if context.requested_family != Some(TemplateFamily::Outbreak) {
45:         families.retain(|candidate| candidate.value != TemplateFamily::Outbreak);
46:     }
47:     let family_indices = if let Some(requested) = context.requested_family {
48:         families
49:             .iter()
50:             .position(|c| c.value == requested)
51:             .into_iter()
52:             .collect()
53:     } else {
54:         weighted_order(context.seed, "family", &families)?
55:     };
56:     let witnesses = deterministic_witness_order(context);
57:     let mut visited = 0usize;
58:     for family_index in family_indices {
59:         let family = families[family_index].value;
60:         let causes = cause_candidates(family);
61:         for cause_index in weighted_order(context.seed, "cause", &causes)? {
62:             let cause = causes[cause_index].value;
63:             let sites = site_candidates(cause);
64:             for site_index in weighted_order(context.seed, "site", &sites)? {
65:                 let site = sites[site_index].value;
66:                 for &primary_index in &witnesses {
67:                     let witness = &context.witness_candidates[primary_index];
68:                     let circumstances = circumstance_candidates(witness.demographic);
69:                     for circumstance_index in weighted_order(
70:                         context.seed,
71:                         "circumstance",
72:                         &circumstances,
73:                     )? {
74:                         visited += 1;
75:                         if visited > MAX_SOLVER_VISITED_NODES {
76:                             return Err(GenerationError::CandidateLimit);
77:                         }
78:                         let circumstance = circumstances[circumstance_index].value;
79:                         if !witness.allowed_circumstances.contains(&circumstance) {
80:                             trace.push(FactorTrace {
81:                                 module_id: ModuleId::new("module.circumstance"),
82:                                 relation_id: RelationId::new("relation.circumstance.npc_fact"),
83:                                 factor_ids: vec![FactorId::new("factor.witness.actual_schedule")],
84:                                 candidate_id: format!(
85:                                     "{}:{}",
86:                                     witness.resident_character_id,
87:                                     circumstance.as_str()
88:                                 ),
89:                                 plausibility: 0,
90:                                 curation: 0,
91:                                 accepted: false,
92:                                 hard_zero_reason: Some(
93:                                     "persistent NPC facts do not permit this circumstance".into(),
94:                                 ),
95:                                 required_bridge: None,
96:                                 decision: TraceDecision::ForwardRejected,
97:                             });
98:                             continue;
99:                         }
100:                         let descriptions = description_candidates(cause);
101:                         let Some(description_index) = weighted_order(
102:                             context.seed,
103:                             "description",
104:                             &descriptions,
105:                         )?
106:                         .first()
107:                         .copied() else {
108:                             trace.push(FactorTrace {
109:                                 module_id: ModuleId::new("module.description"),
110:                                 relation_id: RelationId::new("relation.description.cause"),
111:                                 factor_ids: vec![FactorId::new("factor.description.forward_check")],
112:                                 candidate_id: cause.stable_variant_id(),
113:                                 plausibility: 0,
114:                                 curation: 0,
115:                                 accepted: false,
116:                                 hard_zero_reason: Some(
117:                                     "cause has no possible bestiary report".into(),
118:                                 ),
119:                                 required_bridge: None,
120:                                 decision: TraceDecision::Backtracked,
121:                             });
122:                             continue;
123:                         };
124:                         let secondary_index = witnesses
125:                             .iter()
126:                             .copied()
127:                             .find(|index| *index != primary_index)
128:                             .expect("two witnesses checked");
129:                         for (module, id, bridge_id, factors) in [
130:                             (
131:                                 "module.template",
132:                                 family.stable_variant_id().into(),
133:                                 families[family_index].bridge,
134:                                 families[family_index].factors.clone(),
135:                             ),
136:                             (
137:                                 "module.cause",
138:                                 cause.stable_variant_id(),
139:                                 causes[cause_index].bridge,
140:                                 causes[cause_index].factors.clone(),
141:                             ),
142:                             (
143:                                 "module.site",
144:                                 site.as_str().into(),
145:                                 sites[site_index].bridge,
146:                                 sites[site_index].factors.clone(),
147:                             ),
148:                             (
149:                                 "module.witness",
150:                                 witness.resident_character_id.to_string(),
151:                                 None,
152:                                 vec!["factor.witness.actual_population"],
153:                             ),
154:                             (
155:                                 "module.circumstance",
156:                                 circumstance.as_str().into(),
157:                                 circumstances[circumstance_index].bridge,
158:                                 circumstances[circumstance_index].factors.clone(),
159:                             ),
160:                             (
161:                                 "module.description",
162:                                 descriptions[description_index].value.as_str().into(),
163:                                 descriptions[description_index].bridge,
164:                                 descriptions[description_index].factors.clone(),
165:                             ),
166:                         ] {
167:                             trace.push(FactorTrace {
168:                                 module_id: ModuleId::new(module),
169:                                 relation_id: RelationId::new("relation.solver.binding"),
170:                                 factor_ids: factors.into_iter().map(FactorId::new).collect(),
171:                                 candidate_id: id,
172:                                 plausibility: 100,
173:                                 curation: 100,
174:                                 accepted: true,
175:                                 hard_zero_reason: None,
176:                                 required_bridge: bridge_id.map(BridgeId::new),
177:                                 decision: TraceDecision::Bound,
178:                             });
179:                         }
180:                         return Ok(SolvedVariables {
181:                             family,
182:                             cause,
183:                             site,
184:                             demographic: witness.demographic,
185:                             circumstance,
186:                             description: descriptions[description_index].value,
187:                             family_bridge: families[family_index].bridge,
188:                             cause_bridge: causes[cause_index].bridge,
189:                             site_bridge: sites[site_index].bridge,
190:                             circumstance_bridge: circumstances[circumstance_index].bridge,
191:                             description_bridge: descriptions[description_index].bridge,
192:                             primary_witness: primary_index,
193:                             secondary_witness: secondary_index,
194:                         });
195:                     }
196:                     trace.push(FactorTrace {
197:                         module_id: ModuleId::new("module.witness"),
198:                         relation_id: RelationId::new("relation.solver.backtrack"),
199:                         factor_ids: vec![FactorId::new("factor.no_valid_circumstance")],
200:                         candidate_id: witness.resident_character_id.to_string(),
201:                         plausibility: 0,
202:                         curation: 0,
203:                         accepted: false,
204:                         hard_zero_reason: Some("witness has no compatible circumstance".into()),
205:                         required_bridge: None,
206:                         decision: TraceDecision::Backtracked,
207:                     });
208:                 }
209:             }
210:         }
211:     }
212:     Err(GenerationError::NoCandidates {
213:         module: ModuleId::new("module.quest"),
214:         diagnostics: trace.clone(),
215:     })
216: }
