34: /// Canonical, versioned encoding for durable rights-question fingerprints.
35: ///
36: /// Every component is length-framed, and common boundary variants are encoded
37: /// here so domain rights digests cannot drift into ad hoc concatenation or
38: /// enum formatting.
39: pub(crate) struct CanonicalRightsQuestionDigest(Sha256);
40: 
41: impl CanonicalRightsQuestionDigest {
42:     pub(crate) fn new(purpose: &[u8]) -> Self {
43:         let mut digest = Self(Sha256::new());
44:         digest.frame(b"adventuresim.rights-question");
45:         digest.frame(b"v1");
46:         digest.frame(purpose);
47:         digest
48:     }
49: 
50:     pub(crate) fn frame(&mut self, value: &[u8]) {
51:         self.0.update((value.len() as u64).to_le_bytes());
52:         self.0.update(value);
53:     }
54: 
55:     pub(crate) fn frame_subject<S: DomainRightsSubject>(
56:         &mut self,
57:         subject: &RightsSubject<S>,
58:         frame_domain: impl FnOnce(&mut Self, &S),
59:     ) {
60:         match subject {
61:             RightsSubject::Character(character) => {
62:                 self.frame(b"character");
63:                 self.frame(&character.get().to_le_bytes());
64:             }
65:             RightsSubject::Party(party) => {
66:                 self.frame(b"party");
67:                 self.frame(party.as_str().as_bytes());
68:             }
69:             RightsSubject::Domain(domain) => {
70:                 self.frame(b"domain");
71:                 frame_domain(self, domain);
72:             }
73:         }
74:     }
75: 
76:     pub(crate) fn frame_resource<R: DomainRightsResource>(
77:         &mut self,
78:         resource: &RightsResource<R>,
79:         frame_domain: impl FnOnce(&mut Self, &R),
80:     ) {
81:         match resource {
82:             RightsResource::Object(object) => {
83:                 self.frame(b"object");
84:                 self.frame(&object.get().to_le_bytes());
85:             }
86:             RightsResource::Place(place) => {
87:                 self.frame(b"place");
88:                 self.frame(place.to_string().as_bytes());
89:             }
90:             RightsResource::Fixture(fixture) => {
91:                 self.frame(b"fixture");
92:                 self.frame(fixture.to_string().as_bytes());
93:             }
94:             RightsResource::Domain(domain) => {
95:                 self.frame(b"domain");
96:                 frame_domain(self, domain);
97:             }
98:         }
99:     }
100: 
101:     pub(crate) fn frame_operation<O: DomainRightsOperation>(
102:         &mut self,
103:         operation: &RightsOperation<O>,
104:         frame_domain: impl FnOnce(&mut Self, &O),
105:     ) {
106:         match operation {
107:             RightsOperation::Own => self.frame(b"own"),
108:             RightsOperation::HoldCustody => self.frame(b"hold-custody"),
109:             RightsOperation::Use => self.frame(b"use"),
110:             RightsOperation::TransferCustody { destination } => {
111:                 self.frame(b"transfer-custody");
112:                 self.frame_custody(destination);
113:             }
114:             RightsOperation::Alter => self.frame(b"alter"),
115:             RightsOperation::Access => self.frame(b"access"),
116:             RightsOperation::ReceivePermission => self.frame(b"receive-permission"),
117:             RightsOperation::Domain(domain) => {
118:                 self.frame(b"domain");
119:                 frame_domain(self, domain);
120:             }
121:         }
122:     }
123: 
124:     pub(crate) fn frame_jurisdiction<J: DomainJurisdiction>(
125:         &mut self,
126:         jurisdiction: &RightsJurisdiction<J>,
127:         frame_domain: impl FnOnce(&mut Self, &J),
128:     ) {
129:         match jurisdiction {
130:             RightsJurisdiction::Global => self.frame(b"global"),
131:             RightsJurisdiction::Place(place) => {
132:                 self.frame(b"place");
133:                 self.frame(place.to_string().as_bytes());
134:             }
135:             RightsJurisdiction::Domain(domain) => {
136:                 self.frame(b"domain");
137:                 frame_domain(self, domain);
138:             }
139:         }
140:     }
141: 
142:     fn frame_custody(&mut self, custody: &OperationalCustody) {
143:         match custody {
144:             OperationalCustody::Character(character) => {
145:                 self.frame(b"character");
146:                 self.frame(&character.get().to_le_bytes());
147:             }
148:             OperationalCustody::Party(party) => {
149:                 self.frame(b"party");
150:                 self.frame(party.as_str().as_bytes());
151:             }
152:             OperationalCustody::Container(container) => {
153:                 self.frame(b"container");
154:                 self.frame(&container.get().to_le_bytes());
155:             }
156:             OperationalCustody::Place(place) => {
157:                 self.frame(b"place");
158:                 self.frame(place.to_string().as_bytes());
159:             }
160:             OperationalCustody::Fixture(fixture) => {
161:                 self.frame(b"fixture");
162:                 self.frame(fixture.to_string().as_bytes());
163:             }
164:         }
165:     }
166: 
167:     pub(crate) fn finish(self) -> [u8; 32] {
168:         self.0.finalize().into()
169:     }
170: }
