218: 
219: impl<
220:     S: DomainRightsSubject,
221:     R: DomainRightsResource,
222:     O: DomainRightsOperation,
223:     J: DomainJurisdiction,
224: > RightsQuestion<S, R, O, J>
225: {
226:     pub fn try_new(
227:         subject: RightsSubject<S>,
228:         resource: RightsResource<R>,
229:         operation: RightsOperation<O>,
230:         jurisdiction: RightsJurisdiction<J>,
231:     ) -> Result<Self, RightsQuestionError> {
232:         if let RightsJurisdiction::Place(expected) = &jurisdiction {
233:             match &resource {
234:                 RightsResource::Place(actual) if actual != expected => {
235:                     return Err(RightsQuestionError::ResourceJurisdictionMismatch);
236:                 }
237:                 RightsResource::Fixture(actual) if actual.place() != expected => {
238:                     return Err(RightsQuestionError::ResourceJurisdictionMismatch);
239:                 }
240:                 _ => {}
241:             }
242:         }
243:         if let (
244:             RightsResource::Object(object_id),
245:             RightsOperation::TransferCustody {
246:                 destination: OperationalCustody::Container(container_id),
247:             },
248:         ) = (&resource, &operation)
249:             && object_id == container_id
250:         {
251:             return Err(RightsQuestionError::SelfContainment);
252:         }
253:         Ok(Self {
254:             subject,
255:             resource,
256:             operation,
257:             jurisdiction,
258:         })
259:     }
