261:     pub const fn subject(&self) -> &RightsSubject<S> {
262:         &self.subject
263:     }
264:     pub const fn resource(&self) -> &RightsResource<R> {
265:         &self.resource
266:     }
267:     pub const fn operation(&self) -> &RightsOperation<O> {
268:         &self.operation
269:     }
270:     pub const fn jurisdiction(&self) -> &RightsJurisdiction<J> {
271:         &self.jurisdiction
272:     }
273: }
