89:     is_abrupt: bool,
90: }
91: 
92: impl Default for RenderVisibilityRanges {
93:     fn default() -> Self {
94:         Self {
95:             entities: default(),
96:             range_to_index: default(),
97:             buffer: BufferVec::new(
