772: /// Populates [`face_neighbors`](TriangleInfo::face_neighbors) based on matching edges.
773: fn build_neighbors<O: Ops>(triangles: &mut [TriangleInfo<O>], vertices: &[FaceVertex]) {
774:     let (vertices, _) = vertices.split_at(triangles.len() * 3);
775: 
776:     // build array of edges
777:     let mut edges = vertices
778:         .chunks_exact(3)
779:         .enumerate()
780:         .flat_map(|(f, chunk)| {
781:             chunk
782:                 .iter()
783:                 .zip(chunk.iter().cycle().skip(1))
784:                 .take(3)
785:                 .map(move |(a, b)| (f, a.min(b), a.max(b)))
786:         })
787:         .map(|(f, &i0, &i1)| Edge { i0, i1, f })
788:         .collect::<Vec<_>>();
789: 
790:     // Sort over all edges by i0, i1, then f.
791:     // This is the pricy one.
792:     quick_sort_edges(&mut edges);
793: 
794:     // pair up, adjacent triangles
795:     for (index, a) in edges.iter().enumerate() {
796:         // resolve index ordering and edge_num
797:         let (n_a, (i0_a, i1_a)) = get_edge(&vertices[a.f * 3..][..3], a.i0, a.i1).unwrap();
798: 
799:         if triangles[a.f].face_neighbors[n_a].is_some() {
800:             continue;
801:         }
802: 
803:         // get true index ordering
804:         let found = edges
805:             .iter()
806:             .skip(index + 1)
807:             // If `edges` is improperly sorted, neighbors may not be found for
808:             // faces with the largest `i0`.
809:             .take_while(|b| (a.i0, a.i1) == (b.i0, b.i1))
810:             .find_map(|b| {
811:                 // flip i0_B and i1_B
812:                 // resolve index ordering and edge_num
813:                 let (n_b, (i1_b, i0_b)) = get_edge(&vertices[b.f * 3..][..3], b.i0, b.i1).unwrap();
