879:             tangent_spaces[dst] = tangent_spaces[src];
880:         });
881: }
882: 
883: /// Degenerate quads with one good triangle will be fixed by copying a space from
884: /// the good triangle to the coinciding vertex.
885: fn generate_tangent_spaces_for_partially_degenerate_quads<I: Geometry<O>, O: Ops>(
886:     // Using `impl Copy` to highlight this function doesn't interact with tangent
887:     // space values.
888:     tangent_spaces: &mut [impl Copy],
889:     triangle_info_list: &[TriangleInfo<O>],
890:     context: &I,
891: ) {
892:     // deal with degenerate quads with one good triangle
893:     triangle_info_list
894:         .iter()
895:         // this triangle belongs to a quad where the
896:         // other triangle is degenerate
897:         .filter(|triangle_info| triangle_info.quad_with_one_degenerate_triangle)
898:         .map(|triangle_info| {
899:             let dst = triangle_info.missing_vertex.unwrap() as usize;
900: 
901:             let offset = triangle_info.tangent_spaces_offset;
902:             let face = triangle_info.original_face_index;
903:             let missing_position = context.position(face, dst);
904: 
905:             let src = triangle_info
906:                 .vertex_indices()
907:                 .iter()
908:                 .find_map(|&vertex| {
909:                     let vertex = vertex as usize;
910:                     let source_position = context.position(face, vertex);
911:                     (source_position == missing_position).then_some(vertex)
912:                 })
913:                 .unwrap();
914: 
915:             (dst + offset, src + offset)
916:         })
917:         .for_each(|(dst, src)| {
918:             tangent_spaces[dst] = tangent_spaces[src];
919:         });
920: }

