13: #[derive(Clone, Deserialize, Serialize)]
14: #[serde(deny_unknown_fields)]
15: struct Camera {
16:     position_metres: [f32; 3],
17:     target_metres: [f32; 3],
18: }
19: 
20: impl Camera {
21:     fn validate(&self) -> bool {
22:         let position = Vec3::from_array(self.position_metres);
23:         let target = Vec3::from_array(self.target_metres);
24:         position.is_finite()
25:             && target.is_finite()
26:             && (target - position).cross(Vec3::Y).length_squared() > 0.0
27:     }
28: 
29:     fn review(&self) -> Result<BuildingReviewCamera> {
30:         Ok(BuildingReviewCamera {
31:             position: Position::from_metres(Vec3::from_array(self.position_metres))?,
32:             target: Position::from_metres(Vec3::from_array(self.target_metres))?,
33:             plaster_raking_light: None,
34:         })
35:     }
36: }
