38: #[derive(Deserialize, Serialize)]
39: #[serde(deny_unknown_fields)]
40: struct Document {
41:     version: u16,
42:     /// Scene-relative metres, with the same seven indexes as city-review.
43:     exterior: Vec<Camera>,
44:     /// Frozen eye-height pose; scene-performance uses its established 80° FOV.
45:     benchmark: Option<Camera>,
46:     /// Explicit physical members to inspect with the production playable LODs.
47:     playable_building_ids: Vec<adventuresim_tactical_core::scene_input::SceneBuildingId>,
48: }
49: 
50: #[derive(Resource)]
51: pub(super) struct Contract(Option<Document>);
52: 
53: impl Contract {
54:     pub(super) fn load(path: Option<PathBuf>, profile: &str) -> Self {
55:         assert!(
56:             path.is_some() || profile != PROFILE,
57:             "terrain-grounding requires --city-cameras"
58:         );
59:         let document = path.map(|path| {
60:             let bytes = std::fs::read(&path).expect("read explicit camera contract");
61:             let document: Document =
62:                 serde_json::from_slice(&bytes).expect("decode camera contract");
63:             assert_eq!(
64:                 document.version, CONTRACT_VERSION,
65:                 "camera contract version"
66:             );
67:             assert!(
68:                 document.exterior.len() == 7,
69:                 "camera contract requires all seven fixed city poses"
70:             );
71:             assert!(document.exterior.iter().all(Camera::validate));
72:             assert!(document.benchmark.as_ref().is_none_or(Camera::validate));
73:             document
74:         });
75:         Self(document)
76:     }
77: }
78: 
79: pub(super) fn apply(contract: Res<Contract>, mut state: ResMut<SceneCaptureState>) -> Result {
80:     let Some(document) = &contract.0 else {
81:         return Ok(());
82:     };
83:     let exterior = document
84:         .exterior
85:         .iter()
86:         .map(Camera::review)
87:         .collect::<Result<Vec<_>>>()?;
88:     let benchmark = document
89:         .benchmark
90:         .as_ref()
91:         .map(Camera::review)
92:         .transpose()?;
93:     state.city_exterior_cameras = exterior;
94:     if let Some(camera) = benchmark {
95:         state.ground_eye_position = camera.position;
96:         state.ground_eye_target = camera.target;
97:     }
98:     std::fs::write(
99:         state.output.join("fixed-camera-contract.json"),
100:         serde_json::to_vec_pretty(document)?,
101:     )?;
102:     Ok(())
103: }
